if (!function_exists('cleg_secure_config_normalize_key')) {
    function cleg_secure_config_normalize_key($key) {
        $key = strtolower((string) $key);
        $key = preg_replace('/[^a-z0-9_]+/', '_', $key);
        return trim($key, '_');
    }
}

if (!function_exists('cleg_secure_config_constant_for_key')) {
    function cleg_secure_config_constant_for_key($key) {
        $key = cleg_secure_config_normalize_key($key);
        $map = cleg_secure_config_map();
        return isset($map[$key]) ? $map[$key] : strtoupper('CLEG_' . $key);
    }
}

if (!function_exists('cleg_secure_config_read_option_store')) {
    function cleg_secure_config_read_option_store() {
        if (!function_exists('get_option')) {
            return array();
        }

        $option = get_option('cleg_secure_config', array());
        return is_array($option) ? $option : array();
    }
}

if (!function_exists('cleg_secure_config_resolve_source_value')) {
    function cleg_secure_config_resolve_source_value($key) {
        $constant = cleg_secure_config_constant_for_key($key);

        if (defined($constant)) {
            return constant($constant);
        }

        $env_value = getenv($constant);
        if ($env_value !== false && $env_value !== '') {
            return $env_value;
        }

        $key = cleg_secure_config_normalize_key($key);
        $option = cleg_secure_config_read_option_store();
        if (array_key_exists($key, $option)) {
            return cleg_secure_config_decrypt_if_needed($option[$key]);
        }

        if (array_key_exists($constant, $option)) {
            return cleg_secure_config_decrypt_if_needed($option[$constant]);
        }

        return '';
    }
}

if (!function_exists('cleg_secure_config_get')) {
    function cleg_secure_config_get($key, $default = '') {
        $key = cleg_secure_config_normalize_key($key);
        $option_value = cleg_secure_config_resolve_source_value($key);

        if ($option_value !== '' && $option_value !== null) {
            return apply_filters('cleg_secure_config_value', $option_value, $key, $default);
        }

        return apply_filters('cleg_secure_config_value', $default, $key, $default);
    }
}

if (!function_exists('cleg_secure_config_storage_key')) {
    function cleg_secure_config_storage_key() {
        $parts = array();
        foreach (array('AUTH_KEY', 'SECURE_AUTH_KEY', 'LOGGED_IN_KEY', 'NONCE_KEY', 'AUTH_SALT', 'SECURE_AUTH_SALT') as $constant) {
            if (defined($constant)) {
                $parts[] = constant($constant);
            }
        }

        if (function_exists('site_url')) {
            $parts[] = site_url();
        }

        $material = implode('|', array_filter(array_map('strval', $parts)));
        if ($material === '') {
            return '';
        }

        return hash('sha256', $material, true);
    }
}

if (!function_exists('cleg_secure_config_can_encrypt')) {
    function cleg_secure_config_can_encrypt() {
        return function_exists('openssl_encrypt')
            && function_exists('openssl_decrypt')
            && function_exists('random_bytes')
            && cleg_secure_config_storage_key() !== '';
    }
}

if (!function_exists('cleg_secure_config_encrypt_for_storage')) {
    function cleg_secure_config_encrypt_for_storage($value) {
        $value = (string) $value;

        if ($value === '' || !cleg_secure_config_can_encrypt()) {
            return $value;
        }

        $cipher = 'aes-256-gcm';
        $iv_length = openssl_cipher_iv_length($cipher);
        if (!$iv_length) {
            return $value;
        }

        $iv = random_bytes($iv_length);
        $tag = '';
        $encrypted = openssl_encrypt($value, $cipher, cleg_secure_config_storage_key(), OPENSSL_RAW_DATA, $iv, $tag);

        if ($encrypted === false || $tag === '') {
            return $value;
        }

        $payload = array(
            'iv' => base64_encode($iv),
            'tag' => base64_encode($tag),
            'data' => base64_encode($encrypted),
        );

        return 'clegenc:v1:' . base64_encode(wp_json_encode($payload));
    }
}

if (!function_exists('cleg_secure_config_decrypt_if_needed')) {
    function cleg_secure_config_decrypt_if_needed($value) {
        $value = (string) $value;

        if (strpos($value, 'clegenc:v1:') !== 0 || !cleg_secure_config_can_encrypt()) {
            return $value;
        }

        $encoded = substr($value, strlen('clegenc:v1:'));
        $json = base64_decode($encoded, true);
        if ($json === false) {
            return '';
        }

        $payload = json_decode($json, true);
        if (!is_array($payload) || empty($payload['iv']) || empty($payload['tag']) || empty($payload['data'])) {
            return '';
        }

        $iv = base64_decode((string) $payload['iv'], true);
        $tag = base64_decode((string) $payload['tag'], true);
        $data = base64_decode((string) $payload['data'], true);
        if ($iv === false || $tag === false || $data === false) {
            return '';
        }

        $decrypted = openssl_decrypt($data, 'aes-256-gcm', cleg_secure_config_storage_key(), OPENSSL_RAW_DATA, $iv, $tag);
        return $decrypted === false ? '' : $decrypted;
    }
}

if (!function_exists('cleg_secure_config_update_values')) {
    function cleg_secure_config_update_values($values) {
        if (!is_array($values) || !function_exists('update_option')) {
            return false;
        }

        $map = cleg_secure_config_map();
        $stored = cleg_secure_config_read_option_store();

        foreach ($values as $key => $value) {
            $key = cleg_secure_config_normalize_key($key);
            if (!array_key_exists($key, $map)) {
                continue;
            }

            $value = trim(sanitize_text_field((string) $value));
            if ($value === '') {
                continue;
            }

            $stored[$key] = cleg_secure_config_encrypt_for_storage($value);
        }

        return update_option('cleg_secure_config', $stored, false);
    }
}

if (!function_exists('cleg_secure_config_delete_values')) {
    function cleg_secure_config_delete_values($keys) {
        if (!is_array($keys) || !function_exists('update_option')) {
            return false;
        }

        $map = cleg_secure_config_map();
        $stored = get_option('cleg_secure_config', array());
        if (!is_array($stored)) {
            $stored = array();
        }

        foreach ($keys as $key) {
            $key = cleg_secure_config_normalize_key($key);
            if (!array_key_exists($key, $map)) {
                continue;
            }

            unset($stored[$key], $stored[$map[$key]]);
        }

        return update_option('cleg_secure_config', $stored, false);
    }
}

if (!function_exists('cleg_secure_config_has')) {
    function cleg_secure_config_has($key) {
        return cleg_secure_config_get($key, '') !== '';
    }
}

if (!function_exists('cleg_secure_config_redact')) {
    function cleg_secure_config_redact($value) {
        $value = (string) $value;
        $length = strlen($value);

        if ($length <= 0) {
            return '';
        }

        if ($length <= 8) {
            return str_repeat('*', $length);
        }

        return substr($value, 0, 4) . str_repeat('*', max(4, $length - 8)) . substr($value, -4);
    }
}
