if (!function_exists('cleg_saas_tenant_module_flags')) {
    function cleg_saas_tenant_module_flags(?string $tenant_id = null): array {
        $tenant_id = $tenant_id ? sanitize_key($tenant_id) : cleg_saas_current_tenant_id();
        $option_keys = array(
            'cleg_saas_modules_' . $tenant_id,
            'cleg_modules_' . $tenant_id,
        );

        foreach ($option_keys as $option_key) {
            $value = get_option($option_key, null);
            if (is_array($value)) {
                return array_map('rest_sanitize_boolean', $value);
            }
        }

        return array();
    }
}

if (!function_exists('cleg_saas_module_definition')) {
    function cleg_saas_module_definition(string $module_key): array {
        $module_key = sanitize_key($module_key);
        $registry = cleg_saas_module_registry();
        return isset($registry[$module_key]) && is_array($registry[$module_key]) ? $registry[$module_key] : array();
    }
}

if (!function_exists('cleg_saas_tenant_module_flag')) {
    function cleg_saas_tenant_module_flag(string $module_key, ?string $tenant_id = null) {
        $module_key = sanitize_key($module_key);
        $tenant_id = $tenant_id ? sanitize_key($tenant_id) : cleg_saas_current_tenant_id();
        $flags = cleg_saas_tenant_module_flags($tenant_id);
        return array_key_exists($module_key, $flags) ? (bool) $flags[$module_key] : null;
    }
}

if (!function_exists('cleg_saas_module_visibility')) {
    function cleg_saas_module_visibility(string $module_key, ?string $tenant_id = null): bool {
        $module_key = sanitize_key($module_key);
        $module = cleg_saas_module_definition($module_key);

        if ($module_key === '' || empty($module)) {
            return false;
        }

        if (empty($module['disableable'])) {
            return true;
        }

        $tenant_flag = cleg_saas_tenant_module_flag($module_key, $tenant_id);
        if ($tenant_flag !== null) {
            return (bool) $tenant_flag;
        }

        $tenant_id = $tenant_id ? sanitize_key($tenant_id) : cleg_saas_current_tenant_id();
        $default = array_key_exists('default_enabled', $module) ? (bool) $module['default_enabled'] : false;
        return (bool) apply_filters('cleg_saas_module_enabled_default', $default, $module_key, $tenant_id, $module);
    }
}

if (!function_exists('cleg_saas_module_enabled')) {
    function cleg_saas_module_enabled(string $module_key, ?string $tenant_id = null): bool {
        return cleg_saas_module_visibility($module_key, $tenant_id);
    }
}

if (!function_exists('cleg_saas_shortcode_module_map')) {
    function cleg_saas_shortcode_module_map(): array {
        $map = array();

        foreach (cleg_saas_module_registry() as $module_key => $module) {
            foreach ((array) ($module['shortcodes'] ?? array()) as $shortcode) {
                $map[$shortcode] = $module_key;
            }
        }

        return apply_filters('cleg_saas_shortcode_module_map', $map);
    }
}

if (!function_exists('cleg_saas_route_module_map')) {
    function cleg_saas_route_module_map(): array {
        $map = array();

        foreach (cleg_saas_module_registry() as $module_key => $module) {
            foreach ((array) ($module['routes'] ?? array()) as $route) {
                $map[trim((string) $route, '/')] = $module_key;
            }
        }

        return apply_filters('cleg_saas_route_module_map', $map);
    }
}

if (!function_exists('cleg_saas_module_closed_message')) {
    function cleg_saas_module_closed_message(string $module_key): string {
        $registry = cleg_saas_module_registry();
        $label = isset($registry[$module_key]['label']) ? (string) $registry[$module_key]['label'] : 'Modulo';
        if (function_exists('cleg_tenant_admin_module_catalog')) {
            $catalog = cleg_tenant_admin_module_catalog();
            if (isset($catalog[$module_key]['label'])) {
                $label = (string) $catalog[$module_key]['label'];
            }
        }

        if (current_user_can('manage_options')) {
            return '<section class="cleg-module-closed"><h2>Modulo desactivado</h2><p>' . esc_html($label) . ' no esta activo para esta empresa.</p></section>';
        }

        return '<section class="cleg-module-closed" aria-hidden="true"></section>';
    }
}

if (!function_exists('cleg_saas_pre_do_shortcode_tag')) {
    function cleg_saas_pre_do_shortcode_tag($return, $tag, $attr, $m) {
        $map = cleg_saas_shortcode_module_map();

        if (!isset($map[$tag])) {
            return $return;
        }

        $module_key = $map[$tag];
        if (cleg_saas_module_enabled($module_key)) {
            return $return;
        }

        return cleg_saas_module_closed_message($module_key);
    }
}
add_filter('pre_do_shortcode_tag', 'cleg_saas_pre_do_shortcode_tag', 10, 4);

if (!function_exists('cleg_saas_current_route_slug')) {
    function cleg_saas_current_route_slug(): string {
        $path = isset($_SERVER['REQUEST_URI']) ? wp_parse_url(esc_url_raw(wp_unslash($_SERVER['REQUEST_URI'])), PHP_URL_PATH) : '';
        $path = trim((string) $path, '/');

        if ($path === '') {
            return '';
        }

        $parts = explode('/', $path);
        return sanitize_title((string) $parts[0]);
    }
}

if (!function_exists('cleg_saas_guard_routes')) {
    function cleg_saas_guard_routes(): void {
        if (is_admin() || wp_doing_ajax()) {
            return;
        }

        $route = cleg_saas_current_route_slug();
        if ($route === '') {
            return;
        }

        $map = cleg_saas_route_module_map();
        if (!isset($map[$route])) {
            return;
        }

        $module_key = $map[$route];
        if (cleg_saas_module_enabled($module_key)) {
            return;
        }

        status_header(404);
        nocache_headers();
        wp_die(
            wp_kses_post(cleg_saas_module_closed_message($module_key)),
            esc_html__('Modulo no disponible', 'cleg'),
            array('response' => 404)
        );
    }
}
add_action('template_redirect', 'cleg_saas_guard_routes', 2);
