if (!function_exists('cleg_access_default_tenant')) {
    function cleg_access_default_tenant(): array {
        return array(
            'id' => 'cleg',
            'slug' => 'cleg',
            'name' => 'Vantrexor',
        );
    }
}

if (!function_exists('cleg_access_user_has_any_cap')) {
    function cleg_access_user_has_any_cap(WP_User $user, array $capabilities): bool {
        foreach ($capabilities as $capability) {
            if (user_can($user, $capability)) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg_access_user_has_portal_signal')) {
    function cleg_access_user_has_portal_signal(WP_User $user): bool {
        $roles = isset($user->roles) ? (array) $user->roles : array();
        $portal_roles = array(
            'administrator',
            'editor',
            'subscriber',
            'trabajador',
            'cleg_rrhh_admin',
            'cleg_procurement_user',
            'cleg_procurement_admin',
            'cleg_owner',
            'cleg_technical_admin',
        );

        if (array_intersect($portal_roles, $roles)) {
            return true;
        }

        return cleg_access_user_has_any_cap($user, array(
            'cleg_access_portal',
            'cleg_access_rrhh',
            'cleg_manage_rrhh',
            'cleg_access_procurement',
            'cleg_manage_procurement',
            'cleg_view_payroll',
            'cleg_manage_payroll',
            'cleg_manage_roles',
            'cleg_manage_tenant',
        ));
    }
}

if (!function_exists('cleg_access_infer_tenant_role_label')) {
    function cleg_access_infer_tenant_role_label(WP_User $user): string {
        $roles = isset($user->roles) ? (array) $user->roles : array();

        if (in_array('administrator', $roles, true) || in_array('cleg_technical_admin', $roles, true) || cleg_access_user_has_any_cap($user, array('manage_options', 'cleg_manage_roles', 'cleg_manage_tenant', 'cleg_technical_full_access'))) {
            return 'Admin Tecnico / Alejandro Admin';
        }

        if (in_array('cleg_owner', $roles, true)) {
            return 'Owner / Luis';
        }

        if (in_array('editor', $roles, true) || in_array('cleg_rrhh_admin', $roles, true) || cleg_access_user_has_any_cap($user, array('cleg_access_rrhh', 'cleg_manage_rrhh'))) {
            return 'Admin Recursos Humanos';
        }

        if (in_array('cleg_procurement_admin', $roles, true) || cleg_access_user_has_any_cap($user, array('cleg_manage_procurement'))) {
            return 'CLEG Procurement Admin';
        }

        if (in_array('cleg_procurement_user', $roles, true) || cleg_access_user_has_any_cap($user, array('cleg_access_procurement'))) {
            return 'CLEG Procurement User';
        }

        return 'Trabajador';
    }
}

if (!function_exists('cleg_access_resolve_user_context')) {
    function cleg_access_resolve_user_context($user_id = 0): array {
        $user_id = $user_id ? absint($user_id) : get_current_user_id();
        $user = $user_id ? get_userdata($user_id) : false;
        $default_tenant = cleg_access_default_tenant();

        if (!$user instanceof WP_User) {
            return array(
                'user' => null,
                'tenant' => $default_tenant,
                'roles' => array(),
                'caps' => array(),
                'status' => 'anonymous',
            );
        }

        $tenant_id = (string) get_user_meta($user->ID, 'cleg_tenant_id', true);
        $tenant_slug = (string) get_user_meta($user->ID, 'cleg_tenant_slug', true);
        $tenant_name = (string) get_user_meta($user->ID, 'cleg_tenant_name', true);
        $status = (string) get_user_meta($user->ID, 'cleg_tenant_status', true);

        if ($tenant_id === '') {
            $tenant_id = $default_tenant['id'];
        }

        if ($tenant_slug === '') {
            $tenant_slug = sanitize_title($tenant_id);
        }

        if ($tenant_name === '') {
            $tenant_name = $tenant_id === $default_tenant['id'] ? $default_tenant['name'] : strtoupper($tenant_slug);
        }

        return array(
            'user' => $user,
            'tenant' => array(
                'id' => sanitize_key($tenant_id),
                'slug' => sanitize_title($tenant_slug),
                'name' => sanitize_text_field($tenant_name),
            ),
            'roles' => isset($user->roles) ? array_values((array) $user->roles) : array(),
            'caps' => array_keys((array) $user->allcaps),
            'status' => $status === 'inactive' ? 'inactive' : 'active',
        );
    }
}

if (!function_exists('cleg_access_user_can')) {
    function cleg_access_user_can(string $capability, string $module_key = '', $user_id = 0): bool {
        $context = cleg_access_resolve_user_context($user_id);
        if (!$context['user'] instanceof WP_User || $context['status'] !== 'active') {
            return false;
        }

        if ($module_key !== '' && function_exists('cleg_saas_module_enabled') && !cleg_saas_module_enabled($module_key, $context['tenant']['id'])) {
            return false;
        }

        return user_can($context['user'], $capability);
    }
}

if (!function_exists('cleg_access_migrate_existing_users_to_default_tenant')) {
    function cleg_access_migrate_existing_users_to_default_tenant(bool $force = false): array {
        $option_key = 'cleg_access_tenant_migration_20260701';
        $report_key = $option_key . '_report';

        if (!$force && get_option($option_key) === 'completed') {
            $existing = get_option($report_key, array());
            return is_array($existing) ? $existing : array('status' => 'completed');
        }

        $default_tenant = cleg_access_default_tenant();
        $report = array(
            'status' => 'completed',
            'ran_at' => current_time('mysql'),
            'tenant' => $default_tenant,
            'scanned' => 0,
            'updated' => 0,
            'skipped' => 0,
            'users' => array(),
        );

        $users = get_users(array(
            'fields' => 'all',
            'number' => 2000,
            'orderby' => 'ID',
            'order' => 'ASC',
        ));

        foreach ($users as $user) {
            if (!$user instanceof WP_User) {
                continue;
            }

            $report['scanned']++;
            if (!cleg_access_user_has_portal_signal($user)) {
                $report['skipped']++;
                continue;
            }

            $changed = false;
            if ((string) get_user_meta($user->ID, 'cleg_tenant_id', true) === '') {
                update_user_meta($user->ID, 'cleg_tenant_id', $default_tenant['id']);
                $changed = true;
            }

            if ((string) get_user_meta($user->ID, 'cleg_tenant_slug', true) === '') {
                update_user_meta($user->ID, 'cleg_tenant_slug', $default_tenant['slug']);
                $changed = true;
            }

            if ((string) get_user_meta($user->ID, 'cleg_tenant_name', true) === '') {
                update_user_meta($user->ID, 'cleg_tenant_name', $default_tenant['name']);
                $changed = true;
            }

            if ((string) get_user_meta($user->ID, 'cleg_tenant_role', true) === '') {
                update_user_meta($user->ID, 'cleg_tenant_role', cleg_access_infer_tenant_role_label($user));
                $changed = true;
            }

            if ((string) get_user_meta($user->ID, 'cleg_tenant_status', true) === '') {
                update_user_meta($user->ID, 'cleg_tenant_status', 'active');
                $changed = true;
            }

            if ($changed) {
                update_user_meta($user->ID, 'cleg_tenant_migrated_at', current_time('mysql'));
                update_user_meta($user->ID, 'cleg_tenant_migration_source', 'default_tenant_20260701');
                $report['updated']++;
                $report['users'][] = array(
                    'id' => (int) $user->ID,
                    'login' => $user->user_login,
                    'tenant_role' => cleg_access_infer_tenant_role_label($user),
                );
            }
        }

        update_option($report_key, $report, false);
        update_option($option_key, 'completed', false);

        return $report;
    }
}

if (!function_exists('cleg_access_run_default_tenant_migration_once')) {
    function cleg_access_run_default_tenant_migration_once(): void {
        cleg_access_migrate_existing_users_to_default_tenant(false);
    }
}

add_action('init', 'cleg_access_run_default_tenant_migration_once', 8);
add_action('wp_loaded', 'cleg_access_run_default_tenant_migration_once', 1);
/**
