/**
 * CLEG 08 - Contact/Formulario CLEG
 */
/* Shortcode + AJAX para Formulario de Contacto CLEG */

add_shortcode('cleg_contact', function () {
  $nonce = wp_create_nonce('cleg_contact_nonce');
  ob_start(); ?>
  <div class="cleg-contact container">
    <style>
      .cleg-contact .card{background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.03));
        border:1px solid rgba(255,255,255,.12); border-radius:18px; padding:18px; color:#e6f2ff}
      .cleg-contact .row{display:grid; gap:12px}
      @media(min-width:980px){.cleg-contact .row{grid-template-columns:1fr 1fr}}
      .cleg-contact .input{width:100%;padding:12px 14px;border-radius:12px;border:1px solid rgba(255,255,255,.12);
        background:rgba(255,255,255,.06); color:#fff; outline:none}
      .cleg-contact .textarea{min-height:120px;resize:vertical}
      .cleg-contact .btn{display:inline-flex;align-items:center;gap:10px;padding:12px 18px;border-radius:14px;
        border:0; background:linear-gradient(135deg,#33a6df,#2563eb); color:#fff; font-weight:700; cursor:pointer}
      .cleg-contact .msg{margin-top:10px; font-size:14px}
      .cleg-contact .hidden-hp{position:absolute;left:-9999px;opacity:0}
    </style>

    <div class="card">
      <form id="cleg-contact-form" autocomplete="on">
        <input type="hidden" name="action" value="cleg_contact_submit">
        <input type="hidden" name="nonce" value="<?php echo esc_attr($nonce); ?>">
        <!-- honeypot anti-spam -->
        <input class="hidden-hp" type="text" name="company" tabindex="-1" autocomplete="off">

        <div class="row">
          <input class="input" type="text" name="name" placeholder="Nombre" autocomplete="name" required>
          <input class="input" type="email" name="email" placeholder="Email" autocomplete="email" required>
        </div>
        <div class="row">
          <input class="input" type="tel" name="phone" placeholder="TelÃ©fono" autocomplete="tel">
          <input class="input" type="text" name="subject" placeholder="Asunto (opcional)" autocomplete="on">
        </div>
        <div class="row" style="grid-template-columns:1fr">
          <textarea class="input textarea" name="message" placeholder="CuÃ©ntanos tu necesidadâ€¦" required></textarea>
        </div>
        <button class="btn" type="submit">Enviar mensaje</button>
        <div class="msg" id="cleg-msg"></div>
      </form>
    </div>
  </div>

  <script>
    (function(){
      const form = document.getElementById('cleg-contact-form');
      const msg  = document.getElementById('cleg-msg');
      const ajaxURL = "<?php echo esc_url( admin_url('admin-ajax.php') ); ?>";

      function qs(data){ return new URLSearchParams(data).toString(); }

      form.addEventListener('submit', async (e)=>{
        e.preventDefault();
        msg.textContent = "Enviandoâ€¦";
        const btn = form.querySelector('button[type="submit"]');
        btn.disabled = true;

        // Construir los datos de forma segura
        const data = {
          action: 'cleg_contact_submit',
          nonce: form.querySelector('[name="nonce"]').value,
          name: form.name.value.trim(),
          email: form.email.value.trim(),
          phone: form.phone.value.trim(),
          subject: form.subject.value.trim(),
          message: form.message.value.trim(),
          company: form.company.value.trim() // honeypot
        };

        try{
          const res = await fetch(ajaxURL, {
            method: 'POST',
            headers: {'Content-Type':'application/x-www-form-urlencoded'},
            body: qs(data),
            credentials: 'same-origin'
          });
          const json = await res.json();
          if(json.success){
            msg.textContent = "Â¡Gracias! Hemos recibido tu mensaje y te contactaremos pronto.";
            form.reset();
          }else{
            msg.textContent = json.data && json.data.message ? json.data.message : "No se pudo enviar. Intenta de nuevo.";
          }
        }catch(err){
          msg.textContent = "Error de conexiÃ³n. Intenta nuevamente.";
        }finally{
          btn.disabled = false;
        }
      });
    })();
  </script>
  <?php
  return ob_get_clean();
});

/* Handler AJAX */
add_action('wp_ajax_nopriv_cleg_contact_submit', 'cleg_contact_submit');
add_action('wp_ajax_cleg_contact_submit', 'cleg_contact_submit');

function cleg_contact_submit(){
  // Seguridad
  if( ! isset($_POST['nonce']) || ! wp_verify_nonce($_POST['nonce'], 'cleg_contact_nonce') ){
    wp_send_json_error(['message'=>'Solicitud no vÃ¡lida (nonce).'], 403);
  }

  // Anti-spam honeypot
  if( ! empty($_POST['company']) ){
    wp_send_json_success(['message'=>'OK']); // silenciar bots
  }

  // Sanitizar
  $name    = sanitize_text_field( wp_unslash($_POST['name'] ?? '') );
  $email   = sanitize_email( wp_unslash($_POST['email'] ?? '') );
  $phone   = sanitize_text_field( wp_unslash($_POST['phone'] ?? '') );
  $subject = sanitize_text_field( wp_unslash($_POST['subject'] ?? 'Nueva consulta') );
  $message = sanitize_textarea_field( wp_unslash($_POST['message'] ?? '') );

  if ( empty($name) || empty($message) || ! is_email($email) ){
    wp_send_json_error(['message'=>'Por favor completa nombre, email y mensaje vÃ¡lidos.'], 400);
  }

  // Destinatarios
  $to = 'luis.coll@clegllc.com';
  $headers = [];
  $headers[] = 'Content-Type: text/html; charset=UTF-8';
  $headers[] = 'Cc: Alejandro Alfonso <alejandro.alfonso@clegllc.com>';
  $headers[] = 'Reply-To: '. $name .' <'. $email .'>';

  // (opcional) define un remitente con tu dominio para mejor entregabilidad:
  $from_email = 'no-reply@' . preg_replace('/^www\./','', parse_url(home_url(), PHP_URL_HOST));
  $headers[] = 'From: CLEG Website <'. $from_email .'>';

  $body  = '<h2>Nueva consulta desde clegllc.com</h2>';
  $body .= '<p><strong>Nombre:</strong> '. esc_html($name) .'</p>';
  $body .= '<p><strong>Email:</strong> '. esc_html($email) .'</p>';
  $body .= '<p><strong>TelÃ©fono:</strong> '. esc_html($phone) .'</p>';
  $body .= '<p><strong>Asunto:</strong> '. esc_html($subject) .'</p>';
  $body .= '<p><strong>Mensaje:</strong><br>'. nl2br( esc_html($message) ) .'</p>';

  $sent = wp_mail($to, 'Contacto web: '.$subject, $body, $headers);

  if ($sent){
    wp_send_json_success(['message'=>'Enviado']);
  } else {
    wp_send_json_error(['message'=>'No se pudo enviar el correo. Revisa la configuraciÃ³n SMTP.'], 500);
  }
}
