/**
 * CLEG 00 - Portal Access Guard
 */
/**
 * CLEG 00 - Portal Access Guard v1.1
 *
 * Pegar en Code Snippets sin la linea inicial <?php.
 * Reemplaza a: CLEG 00 - Portal Trabajadores Legacy Core.
 *
 * Objetivo:
 * - Mantener el rol trabajador.
 * - Centralizar rutas protegidas del portal.
 * - Redirigir usuarios autenticados desde /acceso/.
 * - Evitar que paginas internas dependan solo del shortcode para protegerse.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg00_ensure_worker_role')) {
    function cleg00_ensure_worker_role() {
        if (!get_role('trabajador')) {
            add_role('trabajador', 'Trabajador', array('read' => true));
        }
    }
    add_action('init', 'cleg00_ensure_worker_role', 5);
}

if (!function_exists('cleg00_current_path')) {
    function cleg00_current_path() {
        $uri = isset($_SERVER['REQUEST_URI']) ? sanitize_text_field(wp_unslash($_SERVER['REQUEST_URI'])) : '/';
        $path = parse_url($uri, PHP_URL_PATH);
        $path = $path ? '/' . trim($path, '/') . '/' : '/';
        return $path === '//' ? '/' : $path;
    }
}

if (!function_exists('cleg00_user_has_any_role')) {
    function cleg00_user_has_any_role(array $roles) {
        if (!is_user_logged_in()) {
            return false;
        }

        $user = wp_get_current_user();
        $user_roles = is_array($user->roles) ? $user->roles : array();

        foreach ($roles as $role) {
            if (in_array($role, $user_roles, true)) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg00_is_admin_user')) {
    function cleg00_is_admin_user() {
        return current_user_can('manage_options')
            || current_user_can('edit_pages')
            || current_user_can('cleg_access_rrhh')
            || current_user_can('cleg_manage_rrhh')
            || current_user_can('cleg_view_payroll')
            || current_user_can('cleg_manage_payroll')
            || cleg00_user_has_any_role(array('administrator', 'editor'));
    }
}

if (!function_exists('cleg00_is_worker_user')) {
    function cleg00_is_worker_user() {
        return current_user_can('cleg_access_portal')
            || cleg00_user_has_any_role(array('trabajador'))
            || cleg00_is_admin_user();
    }
}

if (!function_exists('cleg00_user_has_any_cap')) {
    function cleg00_user_has_any_cap($user, array $caps) {
        if (!$user || is_wp_error($user)) {
            return false;
        }

        foreach ($caps as $cap) {
            if (user_can($user, $cap)) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg00_login_user_can_worker')) {
    function cleg00_login_user_can_worker($user) {
        $roles = is_object($user) && isset($user->roles) ? (array) $user->roles : array();

        return in_array('trabajador', $roles, true)
            || cleg00_login_user_can_admin($user)
            || cleg00_user_has_any_cap($user, array('cleg_access_portal'));
    }
}

if (!function_exists('cleg00_login_user_can_admin')) {
    function cleg00_login_user_can_admin($user) {
        $roles = is_object($user) && isset($user->roles) ? (array) $user->roles : array();

        return in_array('administrator', $roles, true)
            || in_array('editor', $roles, true)
            || cleg00_user_has_any_cap($user, array(
                'manage_options',
                'edit_pages',
                'cleg_access_rrhh',
                'cleg_manage_rrhh',
                'cleg_view_payroll',
                'cleg_manage_payroll',
            ));
    }
}

if (!function_exists('cleg00_login_user_is_procurement_only')) {
    function cleg00_login_user_is_procurement_only($user) {
        if (!$user || is_wp_error($user)) {
            return false;
        }

        return cleg00_user_has_any_cap($user, array('cleg_access_procurement'))
            && !cleg00_user_has_any_cap($user, array(
                'cleg_manage_procurement',
                'cleg_clock_own_hours',
                'cleg_view_own_hours',
                'cleg_access_rrhh',
                'cleg_manage_rrhh',
                'manage_options',
                'edit_pages',
            ));
    }
}

if (!function_exists('cleg00_login_user_can_procurement')) {
    function cleg00_login_user_can_procurement($user) {
        return cleg00_login_user_can_admin($user)
            || cleg00_user_has_any_cap($user, array(
                'cleg_access_procurement',
                'cleg_manage_procurement',
                'cleg_view_all_purchase_requests',
            ));
    }
}

if (!function_exists('cleg00_is_procurement_user')) {
    function cleg00_is_procurement_user() {
        return cleg00_is_admin_user()
            || current_user_can('cleg_access_procurement')
            || current_user_can('cleg_manage_procurement')
            || current_user_can('cleg_view_all_purchase_requests');
    }
}

if (!function_exists('cleg00_routes')) {
    function cleg00_routes() {
        return array(
            'worker' => array(
                '/panel/',
                '/formularios/',
                '/mis-nominas/',
                '/mis-documentos/',
            ),
            'admin' => array(
                '/admin-rrhh/',
                '/admin-horas/',
                '/admin-tiempo-real/',
                '/admin-dispositivos/',
                '/admin-empleados/',
                '/admin-job-sites/',
                '/admin-solicitudes/',
                '/payroll-rrhh/',
                '/payroll-reportes/',
                '/empleados/',
            ),
            'procurement' => array(
                '/admin-procurement/',
            ),
        );
    }
}

if (!function_exists('cleg00_route_group_for_path')) {
    function cleg00_route_group_for_path(string $path): string {
        $path = '/' . trim((string) $path, '/') . '/';

        foreach (cleg00_routes() as $group => $routes) {
            if (in_array($path, (array) $routes, true)) {
                return (string) $group;
            }
        }

        return '';
    }
}

if (!function_exists('cleg00_route_can_user_access')) {
    function cleg00_route_can_user_access(string $path, $user) {
        if (!$user || is_wp_error($user) || empty($user->roles)) {
            return false;
        }

        $group = cleg00_route_group_for_path($path);
        if ($group === '') {
            return false;
        }

        if ($group === 'admin') {
            return cleg00_login_user_can_admin($user);
        }

        if ($group === 'procurement') {
            return cleg00_login_user_can_procurement($user);
        }

        return cleg00_login_user_can_worker($user);
    }
}

if (!function_exists('cleg00_route_redirect_for_user')) {
    function cleg00_route_redirect_for_user(string $path, $user): string {
        if (!$user || is_wp_error($user) || empty($user->roles)) {
            return '';
        }

        $path = '/' . trim((string) $path, '/') . '/';
        if ($path === '/acceso/' && cleg00_login_user_is_procurement_only($user)) {
            return home_url('/admin-procurement/');
        }

        $group = cleg00_route_group_for_path($path);

        if ($group === 'admin' || $group === 'worker') {
            if (cleg00_login_user_can_worker($user)) {
                return cleg00_default_portal_url();
            }
        }

        return '';
    }
}

if (!function_exists('cleg00_login_url')) {
    function cleg00_login_url() {
        return home_url('/acceso/');
    }
}

if (!function_exists('cleg00_default_portal_url')) {
    function cleg00_default_portal_url() {
        return home_url('/panel/');
    }
}

if (!function_exists('cleg00_guard_portal_routes')) {
    function cleg00_guard_portal_routes() {
        if (is_admin() || wp_doing_ajax() || wp_doing_cron()) {
            return;
        }

        $path = cleg00_current_path();
        $group = cleg00_route_group_for_path($path);

        if ($path === '/acceso/' && is_user_logged_in()) {
            $current_user = wp_get_current_user();
            $redirect = cleg00_route_redirect_for_user('/acceso/', $current_user);
            if ($redirect !== '') {
                wp_safe_redirect($redirect);
                exit;
            }

            wp_safe_redirect(cleg00_default_portal_url());
            exit;
        }

        if ($group !== '' && !cleg00_route_can_user_access($path, wp_get_current_user())) {
            if (is_user_logged_in()) {
                $redirect = cleg00_route_redirect_for_user($path, wp_get_current_user());
                if ($redirect !== '') {
                    wp_safe_redirect($redirect);
                    exit;
                }

                wp_safe_redirect(cleg00_default_portal_url());
                exit;
            }

            wp_safe_redirect(add_query_arg('cleg_redirect', rawurlencode($path), cleg00_login_url()));
            exit;
        }
    }
    add_action('template_redirect', 'cleg00_guard_portal_routes', 1);
}

if (!function_exists('cleg00_login_redirect')) {
    function cleg00_login_redirect($redirect_to, $requested_redirect_to, $user) {
        if (is_wp_error($user) || empty($user) || empty($user->roles)) {
            return $redirect_to;
        }

        if (!empty($_REQUEST['cleg_redirect'])) {
            $raw_path = sanitize_text_field(wp_unslash($_REQUEST['cleg_redirect']));
            $path = '/' . trim(rawurldecode($raw_path), '/') . '/';

            if (cleg00_route_can_user_access($path, $user)) {
                return home_url($path);
            }
        }

        if (!empty($requested_redirect_to)) {
            $requested_path = parse_url($requested_redirect_to, PHP_URL_PATH);
            $requested_path = $requested_path ? '/' . trim($requested_path, '/') . '/' : '';

            if (cleg00_route_can_user_access($requested_path, $user)) {
                return home_url($requested_path);
            }
        }

        if (cleg00_login_user_is_procurement_only($user)) {
            return home_url('/admin-procurement/');
        }

        if (cleg00_login_user_can_worker($user)) {
            return cleg00_default_portal_url();
        }

        if (cleg00_login_user_can_admin($user)) {
            return cleg00_default_portal_url();
        }

        return $redirect_to;
    }
    add_filter('login_redirect', 'cleg00_login_redirect', 20, 3);
}

if (!function_exists('cleg00_logout_redirect')) {
    function cleg00_logout_redirect() {
        wp_safe_redirect(cleg00_login_url());
        exit;
    }
    add_action('wp_logout', 'cleg00_logout_redirect');
}
/**
