 */


/**
 * BEGIN modulos/01-access-identity/03-cleg-01-portal-login-v4.php
 * Module: access_identity
 * Target: 01-Snippets-Activos/03-cleg-01-portal-login-v4.php
 * Source path: modulos/01-access-identity/03-cleg-01-portal-login-v4.php
 */
/**
 * CLEG 01 - Portal Login
 */
/**
 * CLEG 01 - Portal Login v4.2
 * Shortcode: [cleg_login]
 * Pagina: /acceso/
 * v4.1 mueve al snippet el shell visual de Acceso que antes podia vivir en CSS adicional.
 * v4.2 corrige selector amplio que daba min-height a hijos de entry-content y mostraba un bloque superior.
 */

if (!defined('ABSPATH')) {
    exit;
}

function cleg01_is_access_page() {
    return is_page('acceso') || untrailingslashit($_SERVER['REQUEST_URI'] ?? '') === '/acceso';
}

function cleg01_requested_redirect_path() {
    $raw = '';

    if (!empty($_REQUEST['cleg_redirect'])) {
        $raw = sanitize_text_field(wp_unslash($_REQUEST['cleg_redirect']));
    } elseif (!empty($_REQUEST['redirect_to'])) {
        $raw = sanitize_text_field(wp_unslash($_REQUEST['redirect_to']));
    }

    if (!$raw) {
        return '';
    }

    $decoded = rawurldecode($raw);
    $path = parse_url($decoded, PHP_URL_PATH);
    $path = $path ? '/' . trim($path, '/') . '/' : '';

    return $path === '//' ? '/' : $path;
}

function cleg01_user_can_procurement($user) {
    if (!$user || is_wp_error($user)) {
        return false;
    }

    $roles = isset($user->roles) ? (array) $user->roles : array();

    return in_array('administrator', $roles, true)
        || in_array('editor', $roles, true)
        || user_can($user, 'manage_options')
        || user_can($user, 'edit_pages')
        || user_can($user, 'cleg_access_procurement')
        || user_can($user, 'cleg_manage_procurement')
        || user_can($user, 'cleg_view_all_purchase_requests');
}

function cleg01_user_can_tenant_admin($user) {
    if (!$user || is_wp_error($user)) {
        return false;
    }

    $roles = isset($user->roles) ? (array) $user->roles : array();

    return in_array('administrator', $roles, true)
        || in_array('editor', $roles, true)
        || user_can($user, 'manage_options')
        || user_can($user, 'edit_others_pages')
        || user_can($user, 'cleg_manage_tenant')
        || user_can($user, 'cleg_manage_roles')
        || user_can($user, 'cleg_configure_modules')
        || user_can($user, 'cleg_technical_full_access');
}

function cleg01_target_for_user($user, $requested_path = '') {
    if ($requested_path === '/admin-procurement/' && cleg01_user_can_procurement($user)) {
        return home_url('/admin-procurement/');
    }

    if (cleg01_user_can_tenant_admin($user)) {
        return home_url('/panel/');
    }

    if (
        $user &&
        !is_wp_error($user) &&
        user_can($user, 'cleg_access_procurement') &&
        !user_can($user, 'cleg_manage_procurement') &&
        !user_can($user, 'cleg_clock_own_hours') &&
        !user_can($user, 'cleg_access_rrhh') &&
        !user_can($user, 'cleg_manage_rrhh')
    ) {
        return home_url('/admin-procurement/');
    }

    return home_url('/panel/');
}

function cleg01_process_login_before_output() {
    if (!cleg01_is_access_page()) {
        return;
    }

    if (function_exists('cleg01_is_password_flow') && cleg01_is_password_flow()) {
        if (function_exists('cleg01_process_password_flow')) {
            cleg01_process_password_flow();
        }
        return;
    }

    if (is_user_logged_in() && empty($_POST['cleg_login_submit'])) {
        wp_safe_redirect(cleg01_target_for_user(wp_get_current_user(), cleg01_requested_redirect_path()));
        exit;
    }

    if (empty($_POST['cleg_login_submit'])) {
        return;
    }

    if (
        empty($_POST['cleg_login_nonce']) ||
        !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_login_nonce'])), 'cleg_login_action')
    ) {
        $GLOBALS['cleg01_login_error'] = 'Intenta nuevamente.';
        return;
    }

    $username = isset($_POST['cleg_user']) ? sanitize_user(wp_unslash($_POST['cleg_user']), true) : '';
    $password = isset($_POST['cleg_pin']) ? (string) wp_unslash($_POST['cleg_pin']) : '';

    if (!$username || !$password) {
        $GLOBALS['cleg01_login_error'] = 'Completa usuario y PIN.';
        return;
    }

    $user = wp_signon(array(
        'user_login' => $username,
        'user_password' => $password,
        'remember' => true,
    ), is_ssl());

    if (is_wp_error($user)) {
        $GLOBALS['cleg01_login_error'] = 'Usuario o PIN incorrecto.';
        return;
    }

    wp_set_current_user($user->ID);
    wp_set_auth_cookie($user->ID, true, is_ssl());

    wp_safe_redirect(cleg01_target_for_user($user, cleg01_requested_redirect_path()));
    exit;
}
add_action('template_redirect', 'cleg01_process_login_before_output', 1);

function cleg01_is_password_flow() {
    return isset($_GET['cleg_reset']) || isset($_POST['cleg_reset_action']);
}

function cleg01_password_reset_url($user_login, $key) {
    return add_query_arg(array(
        'cleg_reset' => 'set',
        'key' => rawurlencode((string) $key),
        'login' => rawurlencode((string) $user_login),
    ), home_url('/acceso/'));
}

function cleg01_lostpassword_url($lostpassword_url = '', $redirect = '') {
    $url = add_query_arg('cleg_reset', 'request', home_url('/acceso/'));
    return $redirect ? add_query_arg('redirect_to', rawurlencode($redirect), $url) : $url;
}
add_filter('lostpassword_url', 'cleg01_lostpassword_url', 10, 2);

function cleg01_redirect_default_password_screens() {
    $action = isset($_REQUEST['action']) ? sanitize_key(wp_unslash($_REQUEST['action'])) : '';
    if ($action === 'lostpassword') {
        wp_safe_redirect(cleg01_lostpassword_url());
        exit;
    }

    if (in_array($action, array('rp', 'resetpass'), true)) {
        $key = isset($_REQUEST['key']) ? sanitize_text_field(wp_unslash($_REQUEST['key'])) : '';
        $login = isset($_REQUEST['login']) ? sanitize_user(wp_unslash($_REQUEST['login']), true) : '';
        if ($key !== '' && $login !== '') {
            wp_safe_redirect(cleg01_password_reset_url($login, $key));
            exit;
        }
    }
}
add_action('login_init', 'cleg01_redirect_default_password_screens');

function cleg01_send_password_reset_email($user) {
    if (!$user || !($user instanceof WP_User)) {
        return false;
    }

    $key = get_password_reset_key($user);
    if (is_wp_error($key)) {
        return false;
    }

    $reset_url = cleg01_password_reset_url($user->user_login, $key);
    $subject = 'Vantrexor - acceso al portal';
    $message = "Hola " . ($user->display_name ?: $user->user_login) . ",\n\n"
        . "Recibimos una solicitud para definir o cambiar tu contrasena del portal Vantrexor.\n\n"
        . "Usa este enlace:\n" . $reset_url . "\n\n"
        . "Si no solicitaste este cambio, puedes ignorar este mensaje.\n\n"
        . "Entrada del portal:\n" . home_url('/acceso/') . "\n";

    return wp_mail($user->user_email, $subject, $message);
}

function cleg01_process_password_flow() {
    if (empty($_POST['cleg_reset_action'])) {
        return;
    }

    $action = sanitize_key(wp_unslash($_POST['cleg_reset_action']));

    if ($action === 'request') {
        if (empty($_POST['cleg_reset_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_reset_nonce'])), 'cleg_reset_request')) {
            $GLOBALS['cleg01_reset_error'] = 'Intenta nuevamente.';
            return;
        }

        $identity = isset($_POST['cleg_reset_identity']) ? sanitize_text_field(wp_unslash($_POST['cleg_reset_identity'])) : '';
        $user = false;
        if ($identity !== '') {
            $user = is_email($identity) ? get_user_by('email', sanitize_email($identity)) : get_user_by('login', sanitize_user($identity, true));
        }

        if ($user instanceof WP_User) {
            cleg01_send_password_reset_email($user);
        }

        wp_safe_redirect(add_query_arg('cleg_reset', 'sent', home_url('/acceso/')));
        exit;
    }

    if ($action === 'set') {
        if (empty($_POST['cleg_set_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_set_nonce'])), 'cleg_reset_set')) {
            $GLOBALS['cleg01_reset_error'] = 'Intenta nuevamente.';
            return;
        }

        $login = isset($_POST['login']) ? sanitize_user(wp_unslash($_POST['login']), true) : '';
        $key = isset($_POST['key']) ? sanitize_text_field(wp_unslash($_POST['key'])) : '';
        $pass1 = isset($_POST['pass1']) ? (string) wp_unslash($_POST['pass1']) : '';
        $pass2 = isset($_POST['pass2']) ? (string) wp_unslash($_POST['pass2']) : '';

        if ($pass1 === '' || strlen($pass1) < 8 || $pass1 !== $pass2) {
            $GLOBALS['cleg01_reset_error'] = 'La contrasena debe tener 8 caracteres o mas y coincidir en ambos campos.';
            return;
        }

        $user = check_password_reset_key($key, $login);
        if (is_wp_error($user)) {
            $GLOBALS['cleg01_reset_error'] = 'El enlace expiro o no es valido. Solicita uno nuevo.';
            return;
        }

        reset_password($user, $pass1);
        wp_safe_redirect(add_query_arg('cleg_reset', 'complete', home_url('/acceso/')));
        exit;
    }
}

function cleg01_login_shortcode() {
    $error = isset($GLOBALS['cleg01_login_error']) ? $GLOBALS['cleg01_login_error'] : '';
    $reset_error = isset($GLOBALS['cleg01_reset_error']) ? $GLOBALS['cleg01_reset_error'] : '';
    $reset_state = isset($_GET['cleg_reset']) ? sanitize_key(wp_unslash($_GET['cleg_reset'])) : '';

    ob_start();
    ?>
    <section class="cleg-login-wrap" aria-label="Acceso Vantrexor">
        <div class="cleg-login-card">
            <?php echo cleg_vantrexor_logo_markup('name'); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            <p class="cleg-login-kicker">Console access</p>
            <h1><?php echo esc_html($reset_state ? 'Acceso al portal' : 'Acceso trabajadores'); ?></h1>

            <?php if ($error || $reset_error): ?>
                <div class="cleg-login-error"><?php echo esc_html($error ?: $reset_error); ?></div>
            <?php endif; ?>

            <?php if ($reset_state === 'request') : ?>
            <p class="cleg-login-copy">Escribe tu usuario o email y enviaremos un enlace seguro para definir una nueva contrasena.</p>
            <form method="post" action="<?php echo esc_url(add_query_arg('cleg_reset', 'request', home_url('/acceso/'))); ?>" autocomplete="on">
                <?php wp_nonce_field('cleg_reset_request', 'cleg_reset_nonce'); ?>
                <input type="hidden" name="cleg_reset_action" value="request">
                <label><span>Usuario o email</span><input name="cleg_reset_identity" type="text" autocomplete="username" placeholder="usuario@empresa.com" required></label>
                <button type="submit">Enviar enlace</button>
            </form>
            <a class="cleg-login-home" href="<?php echo esc_url(home_url('/acceso/')); ?>">Volver al acceso</a>
            <?php elseif ($reset_state === 'sent') : ?>
            <p class="cleg-login-copy">Si el usuario existe, enviaremos un enlace para definir la contrasena. Revisa tu email.</p>
            <a class="cleg-login-button-link" href="<?php echo esc_url(home_url('/acceso/')); ?>">Volver al acceso</a>
            <?php elseif ($reset_state === 'complete') : ?>
            <p class="cleg-login-copy">La contrasena quedo actualizada. Ya puedes entrar al portal.</p>
            <a class="cleg-login-button-link" href="<?php echo esc_url(home_url('/acceso/')); ?>">Entrar</a>
            <?php elseif ($reset_state === 'set') : ?>
            <?php
            $reset_login = isset($_GET['login']) ? sanitize_user(rawurldecode(wp_unslash($_GET['login'])), true) : '';
            $reset_key = isset($_GET['key']) ? sanitize_text_field(rawurldecode(wp_unslash($_GET['key']))) : '';
            ?>
            <p class="cleg-login-copy">Define una nueva contrasena para tu acceso al portal.</p>
            <form method="post" action="<?php echo esc_url(add_query_arg('cleg_reset', 'set', home_url('/acceso/'))); ?>" autocomplete="on">
                <?php wp_nonce_field('cleg_reset_set', 'cleg_set_nonce'); ?>
                <input type="hidden" name="cleg_reset_action" value="set">
                <input type="hidden" name="login" value="<?php echo esc_attr($reset_login); ?>">
                <input type="hidden" name="key" value="<?php echo esc_attr($reset_key); ?>">
                <label><span>Nueva contrasena</span><input name="pass1" type="password" autocomplete="new-password" minlength="8" required></label>
                <label><span>Confirmar contrasena</span><input name="pass2" type="password" autocomplete="new-password" minlength="8" required></label>
                <button type="submit">Guardar contrasena</button>
            </form>
            <a class="cleg-login-home" href="<?php echo esc_url(add_query_arg('cleg_reset', 'request', home_url('/acceso/'))); ?>">Solicitar otro enlace</a>
            <?php else : ?>
            <form method="post" action="<?php echo esc_url(home_url('/acceso/')); ?>" autocomplete="on">
                <?php wp_nonce_field('cleg_login_action', 'cleg_login_nonce'); ?>
                <?php if (cleg01_requested_redirect_path()) : ?>
                    <input type="hidden" name="cleg_redirect" value="<?php echo esc_attr(cleg01_requested_redirect_path()); ?>">
                <?php endif; ?>

                <label>
                    <span>Usuario</span>
                    <input
                        name="cleg_user"
                        type="text"
                        autocomplete="username"
                        placeholder="Usuario"
                        required
                    >
                </label>

                <label>
                    <span>PIN</span>
                    <input
                        name="cleg_pin"
                        type="password"
                        inputmode="numeric"
                        autocomplete="current-password"
                        placeholder="PIN"
                        required
                    >
                </label>

                <label class="cleg-login-remember">
                    <input type="checkbox" name="cleg_remember" value="1" checked>
                    <span>Recordarme</span>
                </label>

                <button type="submit" name="cleg_login_submit" value="1">
                    Entrar
                </button>
            </form>
            <a class="cleg-login-home" href="<?php echo esc_url(add_query_arg('cleg_reset', 'request', home_url('/acceso/'))); ?>">Cambiar o recuperar contrasena</a>
            <a class="cleg-login-home" href="<?php echo esc_url(home_url('/')); ?>">Volver a inicio</a>
            <?php endif; ?>
        </div>
        <?php echo cleg01_login_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
    </section>
    <?php
    return ob_get_clean();
}
add_shortcode('cleg_login', 'cleg01_login_shortcode');

