/**
 * CLEG Navigation & Shell v0.1
 *
 * Centraliza el registro de navegacion por modulo, permisos efectivos y gating
 * por tenant. No renderiza paginas completas; solo entrega items seguros para
 * que cada modulo pinte su propia experiencia.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_shell_current_tenant_id')) {
    function cleg_shell_current_tenant_id(): string {
        $user_id = get_current_user_id();
        $tenant_id = $user_id > 0 ? (string) get_user_meta($user_id, 'cleg_tenant_id', true) : '';

        if ($tenant_id === '') {
            $tenant_id = 'cleg';
        }

        return sanitize_key($tenant_id);
    }
}

if (!function_exists('cleg_shell_module_defaults')) {
    function cleg_shell_module_defaults(): array {
        return array(
            'core_saas' => true,
            'access_identity' => true,
            'tenant_admin' => true,
            'navigation_shell' => true,
            'employee_center' => true,
            'hr_core' => true,
            'onboarding' => true,
            'forms_requests' => true,
            'payroll' => true,
            'documents' => true,
            'field_ops' => true,
            'projects_work_orders' => true,
            'procurement_quotes' => true,
            'command_center' => true,
            'integrations_layer' => true,
            'design_system' => true,
            'mobile_utilities' => true,
            'sync_qa' => true,
            'cleg_private_internal' => false,
            'legacy_unconfirmed' => false,
        );
    }
}

if (!function_exists('cleg_shell_module_enabled')) {
    function cleg_shell_module_enabled(string $module_key, ?string $tenant_id = null): bool {
        $module_key = sanitize_key($module_key);
        $tenant_id = $tenant_id ? sanitize_key($tenant_id) : cleg_shell_current_tenant_id();

        if ($module_key === '') {
            return false;
        }

        if (function_exists('cleg_saas_module_enabled')) {
            return (bool) cleg_saas_module_enabled($module_key, $tenant_id);
        }

        $defaults = cleg_shell_module_defaults();
        $enabled = array_key_exists($module_key, $defaults) ? (bool) $defaults[$module_key] : false;

        return (bool) apply_filters('cleg_shell_module_enabled', $enabled, $module_key, $tenant_id);
    }
}

if (!function_exists('cleg_shell_user_can_any')) {
    function cleg_shell_user_can_any(array $capabilities): bool {
        if (empty($capabilities)) {
            return true;
        }

        foreach ($capabilities as $capability) {
            if (current_user_can($capability)) {
                return true;
            }
        }

        return false;
    }
}

