if (!function_exists('cleg_shell_filter_items')) {
    function cleg_shell_filter_items(string $context, array $args = array()): array {
        $tenant_id = isset($args['tenant_id']) ? sanitize_key((string) $args['tenant_id']) : cleg_shell_current_tenant_id();
        $items = array();

        foreach (cleg_shell_items($context) as $item) {
            $module = isset($item['module']) ? sanitize_key((string) $item['module']) : '';
            if ($module !== '' && !cleg_shell_module_enabled($module, $tenant_id)) {
                continue;
            }

            if (!empty($item['capabilities']) && !cleg_shell_user_can_any((array) $item['capabilities'])) {
                continue;
            }

            $condition = isset($item['condition']) ? (string) $item['condition'] : '';
            if ($condition === 'show_employee_payroll' && empty($args['show_employee_payroll'])) {
                continue;
            }
            if ($condition === 'hide_procurement_admin' && !empty($args['show_procurement_admin'])) {
                continue;
            }

            $items[] = $item;
        }

        return $items;
    }
}

if (!function_exists('cleg_shell_command_center_modules')) {
    function cleg_shell_command_center_modules(array $args = array()): array {
        return cleg_shell_filter_items('command_center', $args);
    }
}

if (!function_exists('cleg_shell_render_attributes')) {
    function cleg_shell_render_attributes(array $attributes): string {
        $html = '';

        foreach ($attributes as $name => $value) {
            $name = sanitize_key((string) $name);
            if ($name === '') {
                continue;
            }

            if ($value === '') {
                $html .= ' ' . esc_attr($name);
                continue;
            }

            $html .= ' ' . esc_attr($name) . '="' . esc_attr((string) $value) . '"';
        }

        return $html;
    }
}

if (!function_exists('cleg_shell_render_worker_menu_items')) {
    function cleg_shell_render_worker_menu_items(array $args = array()): string {
        $items = cleg_shell_filter_items('worker_menu', $args);
        $html = '';

        if (shortcode_exists('cleg_change_pin')) {
            $html .= do_shortcode('[cleg_change_pin]');
        }

        foreach ($items as $item) {
            $type = isset($item['type']) ? (string) $item['type'] : 'link';
            $label = isset($item['label']) ? (string) $item['label'] : '';
            $href = isset($item['href']) ? (string) $item['href'] : '#';
            $attributes = cleg_shell_render_attributes((array) ($item['attributes'] ?? array()));

            if ($label === '') {
                continue;
            }

            if ($type === 'button') {
                $html .= '<button type="button"' . $attributes . '>' . esc_html($label) . '</button>';
                continue;
            }

            $html .= '<a href="' . esc_url($href) . '"' . $attributes . '>' . esc_html($label) . '</a>';
        }

        return $html;
    }
}
