/**
 * CLEG Integrations Layer - Airtable v0.1
 *
 * Cliente comun para Airtable por tenant y modulo. Los modulos deben pasar por
 * esta capa para que el SaaS pueda cerrar requests cuando un modulo esta apagado
 * o cuando falte configuracion privada del tenant.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_integrations_current_tenant_id')) {
    function cleg_integrations_current_tenant_id(): string {
        if (function_exists('cleg_saas_current_tenant_id')) {
            return sanitize_key((string) cleg_saas_current_tenant_id());
        }

        $user_id = get_current_user_id();
        $tenant_id = $user_id > 0 ? (string) get_user_meta($user_id, 'cleg_tenant_id', true) : '';

        if ($tenant_id === '') {
            $tenant_id = defined('CLEG_DEFAULT_TENANT_ID') ? (string) CLEG_DEFAULT_TENANT_ID : 'cleg';
        }

        return sanitize_key($tenant_id);
    }
}

if (!function_exists('cleg_integrations_module_enabled')) {
    function cleg_integrations_module_enabled(string $module_key, ?string $tenant_id = null): bool {
        $module_key = sanitize_key($module_key);
        $tenant_id = $tenant_id ? sanitize_key($tenant_id) : cleg_integrations_current_tenant_id();

        if ($module_key === '') {
            return false;
        }

        if (function_exists('cleg_saas_module_enabled')) {
            return (bool) cleg_saas_module_enabled($module_key, $tenant_id);
        }

        return true;
    }
}

if (!function_exists('cleg_integrations_airtable_default_tables')) {
    function cleg_integrations_airtable_default_tables(): array {
        return array(
            'hr_core' => array(
                'employees' => defined('CLEG_RRHH_TABLE_EMPLOYEES') ? CLEG_RRHH_TABLE_EMPLOYEES : 'Employees',
                'job_sites' => defined('CLEG_RRHH_TABLE_JOB_SITES') ? CLEG_RRHH_TABLE_JOB_SITES : 'Job Sites',
