if (!function_exists('cleg_integrations_airtable_normalize_config')) {
    function cleg_integrations_airtable_normalize_config($config): array {
        if (!is_array($config)) {
            return array();
        }

        $base_id = $config['base_id'] ?? $config['base'] ?? $config['airtable_base_id'] ?? '';
        $token = $config['token'] ?? $config['pat'] ?? $config['airtable_pat'] ?? $config['airtable_token'] ?? '';
        $tables = isset($config['tables']) && is_array($config['tables']) ? $config['tables'] : array();

        return array(
            'base_id' => is_scalar($base_id) ? trim((string) $base_id) : '',
            'token' => is_scalar($token) ? trim((string) $token) : '',
            'tables' => array_map('sanitize_text_field', $tables),
        );
    }
}

if (!function_exists('cleg_integrations_airtable_config_from_options')) {
    function cleg_integrations_airtable_config_from_options(string $module_key, string $tenant_id): array {
        $option_keys = array(
            'cleg_saas_airtable_' . $tenant_id . '_' . $module_key,
            'cleg_integrations_airtable_' . $tenant_id . '_' . $module_key,
            'cleg_saas_airtable_' . $tenant_id,
            'cleg_integrations_airtable_' . $tenant_id,
        );

        foreach ($option_keys as $option_key) {
            $value = get_option($option_key, array());
            if (!is_array($value)) {
                continue;
            }

            if (isset($value[$module_key]) && is_array($value[$module_key])) {
                $value = $value[$module_key];
            }

            $config = cleg_integrations_airtable_normalize_config($value);
            if ($config['base_id'] !== '' || $config['token'] !== '') {
                return $config;
            }
        }

        return array();
    }
}

if (!function_exists('cleg_integrations_airtable_config_from_secure_store')) {
    function cleg_integrations_airtable_config_from_secure_store(string $module_key): array {
        if (!function_exists('cleg_secure_config_get')) {
            return array();
        }

        $base_id = cleg_secure_config_get($module_key . '_airtable_base_id', '');
        $token = cleg_secure_config_get($module_key . '_airtable_token', '');

        if ($base_id === '') {
            $base_id = cleg_secure_config_get('admin_airtable_base_id', cleg_secure_config_get('airtable_base_id', ''));
        }

        if ($token === '') {
            $token = cleg_secure_config_get('admin_airtable_token', cleg_secure_config_get('airtable_pat', ''));
        }

        return cleg_integrations_airtable_normalize_config(array(
            'base_id' => $base_id,
            'token' => $token,
        ));
    }
}

if (!function_exists('cleg_integrations_airtable_config_from_constants')) {
    function cleg_integrations_airtable_config_from_constants(): array {
        $base_id = '';
        $token = '';

        if (defined('CLEG_ADMIN_AIRTABLE_BASE_ID') && CLEG_ADMIN_AIRTABLE_BASE_ID !== '') {
            $base_id = CLEG_ADMIN_AIRTABLE_BASE_ID;
        } elseif (defined('CLEG_RRHH_AIRTABLE_BASE') && CLEG_RRHH_AIRTABLE_BASE !== '') {
            $base_id = CLEG_RRHH_AIRTABLE_BASE;
        } elseif (defined('CLEG_AIRTABLE_BASE_ID') && CLEG_AIRTABLE_BASE_ID !== '') {
            $base_id = CLEG_AIRTABLE_BASE_ID;
        }

        if (defined('CLEG_ADMIN_AIRTABLE_TOKEN') && CLEG_ADMIN_AIRTABLE_TOKEN !== '') {
            $token = CLEG_ADMIN_AIRTABLE_TOKEN;
        } elseif (defined('CLEG_RRHH_AIRTABLE_PAT') && CLEG_RRHH_AIRTABLE_PAT !== '') {
            $token = CLEG_RRHH_AIRTABLE_PAT;
        } elseif (defined('CLEG_AIRTABLE_PAT') && CLEG_AIRTABLE_PAT !== '') {
            $token = CLEG_AIRTABLE_PAT;
        }

        return cleg_integrations_airtable_normalize_config(array(
            'base_id' => $base_id,
            'token' => $token,
        ));
    }
}

if (!function_exists('cleg_integrations_airtable_config')) {
    function cleg_integrations_airtable_config(string $module_key, ?string $tenant_id = null): array {
        $module_key = sanitize_key($module_key);
        $tenant_id = $tenant_id ? sanitize_key($tenant_id) : cleg_integrations_current_tenant_id();

        if (!cleg_integrations_module_enabled($module_key, $tenant_id)) {
            return array();
        }

        $config = cleg_integrations_airtable_config_from_options($module_key, $tenant_id);
        if (empty($config['base_id']) || empty($config['token'])) {
            $config = cleg_integrations_airtable_config_from_secure_store($module_key);
        }
        if (empty($config['base_id']) || empty($config['token'])) {
            $config = cleg_integrations_airtable_config_from_constants();
        }

        $defaults = cleg_integrations_airtable_default_tables();
        $default_tables = isset($defaults[$module_key]) ? $defaults[$module_key] : array();
        $config['tables'] = array_merge($default_tables, $config['tables'] ?? array());

        return apply_filters('cleg_integrations_airtable_config', $config, $module_key, $tenant_id);
    }
}

if (!function_exists('cleg_integrations_airtable_ready')) {
    function cleg_integrations_airtable_ready(string $module_key, ?string $tenant_id = null): bool {
        $config = cleg_integrations_airtable_config($module_key, $tenant_id);

        return !empty($config['base_id'])
            && !empty($config['token'])
            && $config['token'] !== 'REEMPLAZAR_AIRTABLE_PAT';
    }
}

if (!function_exists('cleg_integrations_airtable_table')) {
    function cleg_integrations_airtable_table(string $module_key, string $table_key_or_name, ?string $tenant_id = null): string {
        $config = cleg_integrations_airtable_config($module_key, $tenant_id);
        $table_key = sanitize_key($table_key_or_name);

        if ($table_key !== '' && !empty($config['tables'][$table_key])) {
            return sanitize_text_field((string) $config['tables'][$table_key]);
        }

        return sanitize_text_field($table_key_or_name);
    }
}

if (!function_exists('cleg_integrations_airtable_error')) {
    function cleg_integrations_airtable_error(string $code, string $message, array $data = array()): WP_Error {
        return new WP_Error($code, $message, $data);
    }
}

if (!function_exists('cleg_integrations_airtable_request')) {
    function cleg_integrations_airtable_request(string $module_key, string $method, string $table_key_or_name, array $args = array(), $body = null, ?string $tenant_id = null) {
        $module_key = sanitize_key($module_key);
        $tenant_id = $tenant_id ? sanitize_key($tenant_id) : cleg_integrations_current_tenant_id();

        if (!cleg_integrations_module_enabled($module_key, $tenant_id)) {
            return cleg_integrations_airtable_error('cleg_integrations_module_disabled', 'Modulo apagado para este tenant.');
        }

        $config = cleg_integrations_airtable_config($module_key, $tenant_id);
        if (empty($config['base_id']) || empty($config['token']) || $config['token'] === 'REEMPLAZAR_AIRTABLE_PAT') {
            return cleg_integrations_airtable_error('cleg_integrations_missing_airtable_config', 'Falta configurar Airtable para este modulo.');
        }

        $table = cleg_integrations_airtable_table($module_key, $table_key_or_name, $tenant_id);
        if ($table === '') {
            return cleg_integrations_airtable_error('cleg_integrations_missing_airtable_table', 'Falta configurar la tabla de Airtable.');
        }

        $query = $args;
        if (isset($args['query']) && is_array($args['query'])) {
            $query = $args['query'];
        }

        $record_id = isset($args['record_id']) ? sanitize_text_field((string) $args['record_id']) : '';
        unset($query['record_id']);

        $url = 'https://api.airtable.com/v0/' . rawurlencode($config['base_id']) . '/' . rawurlencode($table);
        if ($record_id !== '') {
            $url .= '/' . rawurlencode($record_id);
        }
        if (!empty($query)) {
            $url = add_query_arg($query, $url);
        }

        $request = array(
            'method' => strtoupper($method),
            'timeout' => isset($args['timeout']) ? (int) $args['timeout'] : 20,
            'headers' => array(
                'Authorization' => 'Bearer ' . $config['token'],
                'Content-Type' => 'application/json',
            ),
        );

        if ($body === null && isset($args['body'])) {
            $body = $args['body'];
        }

        if ($body !== null) {
            $request['body'] = wp_json_encode($body);
        }

        $response = wp_remote_request($url, $request);
        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        $data = json_decode(wp_remote_retrieve_body($response), true);

        if ($code < 200 || $code >= 300) {
            return cleg_integrations_airtable_error('cleg_integrations_airtable_error', 'Airtable respondio con error.', array(
                'status' => $code,
                'body' => $data,
            ));
        }

        return is_array($data) ? $data : array();
    }
}

if (!function_exists('cleg_integrations_airtable_records')) {
    function cleg_integrations_airtable_records(string $module_key, string $table_key_or_name, array $query = array(), int $max_pages = 20, ?string $tenant_id = null) {
        $records = array();
        $offset = '';
        $page = 0;

        do {
            $page += 1;
            $page_query = $query;
            $page_query['pageSize'] = isset($page_query['pageSize']) ? (int) $page_query['pageSize'] : 100;

            if ($offset !== '') {
                $page_query['offset'] = $offset;
            }

            $response = cleg_integrations_airtable_request($module_key, 'GET', $table_key_or_name, $page_query, null, $tenant_id);
            if (is_wp_error($response)) {
                return $response;
            }

            if (!empty($response['records']) && is_array($response['records'])) {
                $records = array_merge($records, $response['records']);
            }

            $offset = isset($response['offset']) ? sanitize_text_field((string) $response['offset']) : '';
        } while ($offset !== '' && $page < $max_pages);

        return $records;
    }
}
