if (!function_exists('cleg_app_airtable_is_configured')) {
    function cleg_app_airtable_is_configured() {
        if (function_exists('cleg_integrations_airtable_ready')) {
            return cleg_integrations_airtable_ready('hr_core')
                || cleg_integrations_airtable_ready('field_ops')
                || cleg_integrations_airtable_ready('forms_requests')
                || cleg_integrations_airtable_ready('projects_work_orders')
                || cleg_integrations_airtable_ready('procurement_quotes');
        }

        return CLEG_APP_AIRTABLE_TOKEN !== ''
            && CLEG_APP_AIRTABLE_TOKEN !== 'REEMPLAZAR_AIRTABLE_PAT'
            && CLEG_AIRTABLE_BASE_ID !== '';
    }
}

if (!function_exists('cleg_app_airtable_module_for_table')) {
    function cleg_app_airtable_module_for_table($table) {
        $table = (string) $table;

        if (defined('CLEG_AIRTABLE_TIME_TABLE') && $table === CLEG_AIRTABLE_TIME_TABLE) {
            return 'field_ops';
        }

        if (defined('CLEG_AIRTABLE_JOBS_TABLE') && $table === CLEG_AIRTABLE_JOBS_TABLE) {
            return 'projects_work_orders';
        }

        if (defined('CLEG_AIRTABLE_HR_TABLE') && $table === CLEG_AIRTABLE_HR_TABLE) {
            return 'forms_requests';
        }

        if (defined('CLEG_AIRTABLE_RECEIPTS_TABLE') && $table === CLEG_AIRTABLE_RECEIPTS_TABLE) {
            return 'procurement_quotes';
        }

        return 'hr_core';
    }
}

if (!function_exists('cleg_app_airtable_request')) {
    function cleg_app_airtable_request($method, $table, $args = array()) {
        if (function_exists('cleg_integrations_airtable_request')) {
            $query = (!empty($args['query']) && is_array($args['query'])) ? $args['query'] : array();
            $body = !empty($args['body']) ? $args['body'] : null;
            if (!empty($args['record_id'])) {
                $query['record_id'] = sanitize_text_field((string) $args['record_id']);
            }

            return cleg_integrations_airtable_request(cleg_app_airtable_module_for_table($table), $method, $table, $query, $body);
        }

        if (!cleg_app_airtable_is_configured()) {
            return new WP_Error('cleg_airtable_missing_config', 'No se pudo conectar con la oficina.');
        }

        $url = 'https://api.airtable.com/v0/' . rawurlencode(CLEG_AIRTABLE_BASE_ID) . '/' . rawurlencode($table);

        if (!empty($args['query']) && is_array($args['query'])) {
            $url = add_query_arg($args['query'], $url);
        }

        $request = array(
            'method' => $method,
            'timeout' => 20,
            'headers' => array(
                'Authorization' => 'Bearer ' . CLEG_APP_AIRTABLE_TOKEN,
                'Content-Type' => 'application/json',
            ),
        );

        if (!empty($args['body'])) {
            $request['body'] = wp_json_encode($args['body']);
        }

        $response = wp_remote_request($url, $request);

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        $body = json_decode(wp_remote_retrieve_body($response), true);

        if ($code < 200 || $code >= 300) {
            $message = isset($body['error']['message']) ? $body['error']['message'] : 'No se pudo completar la solicitud.';
            return new WP_Error('cleg_airtable_api_error', $message, array('status' => $code));
        }

        return is_array($body) ? $body : array();
    }
}

