        return $fields;
    }
}

if (!function_exists('cleg_app_pick_field')) {
    function cleg_app_pick_field($fields, $keys, $default = '') {
        if (!is_array($fields)) {
            return $default;
        }

        foreach ((array) $keys as $key) {
            if (isset($fields[$key]) && $fields[$key] !== '') {
                if (is_array($fields[$key])) {
                    return sanitize_text_field(implode(', ', array_map('strval', $fields[$key])));
                }

                return sanitize_text_field($fields[$key]);
            }
        }

        return $default;
    }
}

