if (!function_exists('cleg_app_get_employee')) {
    function cleg_app_get_employee($user) {
        if (!$user || empty($user->ID) || !cleg_app_airtable_is_configured()) {
            return false;
        }

        $parts = array();

        $parts[] = '{WordPress User ID}=' . (int) $user->ID;

        if (!empty($user->user_login)) {
            $login = cleg_app_formula_text(sanitize_user($user->user_login));
            $parts[] = "{Portal Username}='{$login}'";
        }

        if (!empty($user->user_email)) {
            $email = cleg_app_formula_text(sanitize_email($user->user_email));
            $parts[] = "LOWER({Email})=LOWER('{$email}')";
        }

        $formula = count($parts) > 1 ? 'OR(' . implode(',', $parts) . ')' : $parts[0];

        $response = cleg_app_airtable_request('GET', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'query' => array(
                'pageSize' => 1,
                'filterByFormula' => $formula,
            ),
        ));

        if (is_wp_error($response) || empty($response['records'][0])) {
            return false;
        }

        $record = $response['records'][0];
        $fields = $record['fields'] ?? array();

        return array(
            'id' => sanitize_text_field($record['id']),
            'name' => isset($fields['Employee Name']) ? sanitize_text_field($fields['Employee Name']) : '',
            'email' => isset($fields['Email']) ? sanitize_email($fields['Email']) : '',
            'role' => isset($fields['Role']) ? sanitize_text_field($fields['Role']) : '',
            'status' => isset($fields['Status']) ? sanitize_text_field($fields['Status']) : '',
            'payroll_tax_type' => isset($fields['Payroll Tax Type']) ? sanitize_text_field($fields['Payroll Tax Type']) : '',
            'company_card_label' => cleg_app_pick_field($fields, array('Assigned Card', 'Company Card', 'Company Card Label', 'Tarjeta Asignada')),
            'company_card_last4' => cleg_app_pick_field($fields, array('Card Last 4', 'Company Card Last 4', 'Tarjeta Ultimos 4')),
            'can_approve' => !empty($fields['Can Approve Hours']),
            'time_required' => !empty($fields['Time Tracking Required']),
        );
    }
}

if (!function_exists('cleg_app_user_can_admin')) {
    function cleg_app_user_can_admin($user, $employee = false) {
        if ($employee && !empty($employee['can_approve'])) {
            return true;
        }

        if (!$user || empty($user->roles)) {
            return false;
        }

        $admin_roles = array('administrator', 'editor', 'hr_manager', 'rrhh', 'cleg_admin');
        return (bool) array_intersect($admin_roles, (array) $user->roles);
    }
}

if (!function_exists('cleg_app_user_can_worker')) {
    function cleg_app_user_can_worker($user, $employee = false) {
        if ($employee && in_array(strtolower($employee['status']), array('active', 'activo', ''), true)) {
            return true;
        }

        if (!$user || empty($user->roles)) {
            return false;
        }

        $worker_roles = array('subscriber', 'contributor', 'worker', 'trabajador', 'cleg_worker');
        return (bool) array_intersect($worker_roles, (array) $user->roles);
    }
}

if (!function_exists('cleg_app_get_job_sites')) {
    function cleg_app_get_job_sites() {
        $cache_key = 'cleg_app_job_sites_v1';
        $cached = get_transient($cache_key);

        if (is_array($cached)) {
            return $cached;
        }

        $response = cleg_app_airtable_request('GET', CLEG_AIRTABLE_JOBS_TABLE, array(
            'query' => array(
                'pageSize' => 100,
                'sort[0][field]' => 'Job Site Name',
                'sort[0][direction]' => 'asc',
                'filterByFormula' => "OR({Status}='Active',{Status}='Activo',{Status}='')",
            ),
        ));

        if (is_wp_error($response)) {
            return $response;
        }

        $jobs = array();

        foreach (($response['records'] ?? array()) as $record) {
            $fields = $record['fields'] ?? array();
            $name = isset($fields['Job Site Name']) ? sanitize_text_field($fields['Job Site Name']) : '';

            if ($name === '') {
                continue;
            }

            $jobs[] = array(
                'id' => sanitize_text_field($record['id']),
                'name' => $name,
                'latitude' => isset($fields['Latitude']) ? (float) $fields['Latitude'] : null,
                'longitude' => isset($fields['Longitude']) ? (float) $fields['Longitude'] : null,
                'radius' => isset($fields['Allowed Radius Meters']) ? (float) $fields['Allowed Radius Meters'] : 0,
                'requires_geolocation' => !empty($fields['Requires Geolocation']),
                'supervisor_email' => isset($fields['Supervisor Email']) ? sanitize_email($fields['Supervisor Email']) : '',
            );
        }

        set_transient($cache_key, $jobs, 5 * MINUTE_IN_SECONDS);

        return $jobs;
    }
}

if (!function_exists('cleg_app_get_job_site_meta')) {
    function cleg_app_get_job_site_meta($job_site_name) {
        $jobs = cleg_app_get_job_sites();

        if (is_wp_error($jobs) || !is_array($jobs)) {
            return false;
        }

        foreach ($jobs as $job) {
            if (isset($job['name']) && $job['name'] === $job_site_name) {
                return $job;
            }
        }

        return false;
    }
}

if (!function_exists('cleg_app_distance_meters')) {
    function cleg_app_distance_meters($lat1, $lon1, $lat2, $lon2) {
        $earth_radius = 6371000;
        $d_lat = deg2rad((float) $lat2 - (float) $lat1);
        $d_lon = deg2rad((float) $lon2 - (float) $lon1);
        $a = sin($d_lat / 2) * sin($d_lat / 2)
            + cos(deg2rad((float) $lat1)) * cos(deg2rad((float) $lat2))
            * sin($d_lon / 2) * sin($d_lon / 2);
        $c = 2 * atan2(sqrt($a), sqrt(1 - $a));

        return round($earth_radius * $c);
    }
}

if (!function_exists('cleg_app_gps_review_note')) {
    function cleg_app_gps_review_note($review, $job_site_name, $accuracy, $gps_error, $allowed_radius = '') {
        $reasons = !empty($review['reasons']) ? array_values(array_unique($review['reasons'])) : array('Manual Review');
        $lines = array(
            'GPS REVIEW REQUIRED - ' . implode(' + ', $reasons),
        );

        if ($job_site_name !== '') {
            $lines[] = 'Job Site: ' . sanitize_text_field($job_site_name);
        }

        if ($accuracy !== '') {
            $lines[] = 'GPS accuracy: ' . round((float) $accuracy) . 'm (max allowed: 35m)';
        }

        if ($review['distance'] !== '') {
            $distance_line = 'Distance from job site: ' . round((float) $review['distance']) . 'm';
            if ($allowed_radius !== '') {
                $distance_line .= ' (allowed radius: ' . round((float) $allowed_radius) . 'm)';
            }
            $lines[] = $distance_line;
        }

        if ($gps_error !== '') {
            $lines[] = 'Device/browser message: ' . sanitize_text_field($gps_error);
        }

        $lines[] = 'Action: verify with worker/supervisor before approving.';

        return implode("\n", $lines);
    }
}

if (!function_exists('cleg_app_location_review')) {
    function cleg_app_location_review($job_site_name, $latitude, $longitude, $accuracy, $gps_override, $gps_error) {
        $review = array(
            'required' => false,
            'reasons' => array(),
            'audit_flags' => array(),
            'distance' => '',
            'note' => '',
        );

        if ($latitude === '' || $longitude === '') {
            $review['required'] = true;
            $review['reasons'][] = $gps_override === '1' ? 'GPS Permission Denied' : 'Missing GPS';
            $review['audit_flags'][] = 'Missing GPS';
            $review['note'] = cleg_app_gps_review_note($review, $job_site_name, $accuracy, $gps_error);
            return $review;
        }

        if ($accuracy !== '' && (float) $accuracy > 100) {
            $review['required'] = true;
            $review['reasons'][] = 'Low GPS Accuracy';
            $review['audit_flags'][] = 'Low GPS Accuracy';
        }

        $job = cleg_app_get_job_site_meta($job_site_name);

        if (!$job || empty($job['requires_geolocation'])) {
            if (!$job) {
                $review['required'] = true;
                $review['reasons'][] = 'Job Site Missing Coordinates';
                $review['audit_flags'][] = 'Manual Review';
                $review['note'] = cleg_app_gps_review_note($review, $job_site_name, $accuracy, $gps_error);
            }
            return $review;
        }

        if ($job['latitude'] === null || $job['longitude'] === null || empty($job['radius'])) {
            $review['required'] = true;
            $review['reasons'][] = 'Job Site Missing Coordinates';
            $review['audit_flags'][] = 'Manual Review';
            $review['note'] = cleg_app_gps_review_note($review, $job_site_name, $accuracy, $gps_error);
            return $review;
        }

        $distance = cleg_app_distance_meters($latitude, $longitude, $job['latitude'], $job['longitude']);
        $review['distance'] = $distance;

        if ($distance > (float) $job['radius']) {
            $review['required'] = true;
            $review['reasons'][] = 'Outside Geofence';
            $review['audit_flags'][] = 'Outside Geofence';
        }

        if ($review['required']) {
            $review['note'] = cleg_app_gps_review_note($review, $job_site_name, $accuracy, $gps_error, $job['radius']);
        }

        return $review;
    }
}

if (!function_exists('cleg_app_open_filter_for_user')) {
    function cleg_app_open_filter_for_user($user) {
        $parts = array();

        if (!empty($user->ID)) {
            $parts[] = '{WordPress User ID}=' . (int) $user->ID;
        }

        if (!empty($user->user_email)) {
            $email = cleg_app_formula_text(sanitize_email($user->user_email));
            $parts[] = "{Employee Email}='{$email}'";
        }

        if (!empty($user->user_login)) {
            $login = cleg_app_formula_text(sanitize_user($user->user_login));
            $parts[] = "{Portal Username}='{$login}'";
        }

        $identity = count($parts) > 1 ? 'OR(' . implode(',', $parts) . ')' : $parts[0];
        return 'AND(' . $identity . ',{Clock Out Time}=BLANK())';
    }
}

