if (!function_exists('cleg_app_get_week_entries')) {
    function cleg_app_get_week_entries($user, $week_offset = 0) {
        if (!$user || empty($user->ID) || !cleg_app_airtable_is_configured()) {
            return array();
        }

        $parts = array('{WordPress User ID}=' . (int) $user->ID);

        if (!empty($user->user_email)) {
            $email = cleg_app_formula_text(sanitize_email($user->user_email));
            $parts[] = "{Employee Email}='{$email}'";
        }

        if (!empty($user->user_login)) {
            $login = cleg_app_formula_text(sanitize_user($user->user_login));
            $parts[] = "{Portal Username}='{$login}'";
        }

        $identity = count($parts) > 1 ? 'OR(' . implode(',', $parts) . ')' : $parts[0];
        $monday = strtotime('monday this week') + ((int) $week_offset * WEEK_IN_SECONDS);
        $next_monday = $monday + WEEK_IN_SECONDS;
        $week_start = gmdate('Y-m-d\TH:i:s\Z', $monday);
        $week_end = gmdate('Y-m-d\TH:i:s\Z', $next_monday);
        $formula = "AND({$identity},IS_AFTER({Clock In Time},'{$week_start}'),IS_BEFORE({Clock In Time},'{$week_end}'))";

        $response = cleg_app_airtable_request('GET', CLEG_AIRTABLE_TIME_TABLE, array(
            'query' => array(
                'pageSize' => 25,
                'filterByFormula' => $formula,
                'sort[0][field]' => 'Clock In Time',
                'sort[0][direction]' => 'desc',
            ),
        ));

        if (is_wp_error($response)) {
            return array();
        }

        $entries = array();

        foreach (($response['records'] ?? array()) as $record) {
            $fields = $record['fields'] ?? array();
            $clock_in = cleg_app_effective_clock_in($fields);
            $clock_out = cleg_app_effective_clock_out($fields);
            $entries[] = array(
                'job_site' => isset($fields['Job Site Name']) ? sanitize_text_field($fields['Job Site Name']) : 'Proyecto',
                'in' => $clock_in,
                'out' => $clock_out,
                'hours' => cleg_app_entry_hours($fields, $clock_in, $clock_out),
                'status' => isset($fields['Approval Status']) ? sanitize_text_field($fields['Approval Status']) : '',
                'admin_note' => isset($fields['Employee Visible Admin Note']) ? sanitize_textarea_field($fields['Employee Visible Admin Note']) : '',
                'weekday' => $clock_in !== '' ? wp_date('l', strtotime($clock_in)) : '',
                'date' => $clock_in !== '' ? wp_date('M j', strtotime($clock_in)) : '',
            );
        }

        return $entries;
    }
}

if (!function_exists('cleg_app_entries_summary')) {
    function cleg_app_entries_summary($entries) {
        $summary = array('hours' => 0, 'entries' => 0, 'pending' => 0);

        foreach ($entries as $entry) {
            if (isset($entry['hours']) && is_numeric($entry['hours']) && ($entry['status'] ?? '') !== 'Rejected') {
                $summary['hours'] += (float) $entry['hours'];
            }

            $summary['entries']++;

            if (($entry['status'] ?? '') === 'Pending Review' || ($entry['status'] ?? '') === 'Open') {
                $summary['pending']++;
            }
        }

        $summary['hours'] = cleg_app_hours_label($summary['hours']);
        return $summary;
    }
}

if (!function_exists('cleg_app_get_month_summary')) {
    function cleg_app_get_month_summary($user) {
        $summary = array('hours' => 0, 'entries' => 0, 'pending' => 0, 'notes' => array());

        if (!$user || empty($user->ID) || !cleg_app_airtable_is_configured()) {
            return $summary;
        }

        $parts = array('{WordPress User ID}=' . (int) $user->ID);

        if (!empty($user->user_email)) {
            $email = cleg_app_formula_text(sanitize_email($user->user_email));
            $parts[] = "{Employee Email}='{$email}'";
        }

        if (!empty($user->user_login)) {
            $login = cleg_app_formula_text(sanitize_user($user->user_login));
            $parts[] = "{Portal Username}='{$login}'";
        }

        $identity = count($parts) > 1 ? 'OR(' . implode(',', $parts) . ')' : $parts[0];
        $month_start = gmdate('Y-m-d\TH:i:s\Z', strtotime('-30 days'));
        $formula = "AND({$identity},IS_AFTER({Clock In Time},'{$month_start}'))";
        $response = cleg_app_airtable_request('GET', CLEG_AIRTABLE_TIME_TABLE, array(
            'query' => array(
                'pageSize' => 100,
                'filterByFormula' => $formula,
                'sort[0][field]' => 'Clock In Time',
                'sort[0][direction]' => 'desc',
            ),
        ));

        if (is_wp_error($response)) {
            return $summary;
        }

        foreach (($response['records'] ?? array()) as $record) {
            $fields = $record['fields'] ?? array();
            $status = isset($fields['Approval Status']) ? sanitize_text_field($fields['Approval Status']) : '';
            $clock_in = cleg_app_effective_clock_in($fields);
            $clock_out = cleg_app_effective_clock_out($fields);
            $hours = cleg_app_entry_hours($fields, $clock_in, $clock_out);

            if (is_numeric($hours) && $status !== 'Rejected') {
                $summary['hours'] += (float) $hours;
            }

            $summary['entries']++;

            if ($status === 'Pending Review' || $status === 'Open') {
                $summary['pending']++;
            }

            if (!empty($fields['Employee Visible Admin Note'])) {
                $summary['notes'][] = array(
                    'date' => $clock_in,
                    'note' => sanitize_textarea_field($fields['Employee Visible Admin Note']),
                );
            }
        }

        $summary['hours'] = cleg_app_hours_label($summary['hours']);
        $summary['notes'] = array_slice($summary['notes'], 0, 5);

        return $summary;
    }
}

if (!function_exists('cleg_app_entry_hours')) {
    function cleg_app_entry_hours($fields, $clock_in, $clock_out) {
        if (is_array($fields) && isset($fields['Payroll Hours Calc']) && is_numeric($fields['Payroll Hours Calc'])) {
            return (float) $fields['Payroll Hours Calc'];
        }

        $start = strtotime($clock_in);
        $end = strtotime($clock_out);

        if (!$start || !$end || $end <= $start) {
            return 0;
        }

        $lunch_minutes = 30;

        if (is_array($fields) && array_key_exists('Lunch Minutes', $fields) && $fields['Lunch Minutes'] !== '') {
            $lunch_minutes = max(0, (int) $fields['Lunch Minutes']);
        }

        return max(0, (($end - $start) / HOUR_IN_SECONDS) - ($lunch_minutes / 60));
    }
}

if (!function_exists('cleg_app_hours_label')) {
    function cleg_app_hours_label($hours) {
        if (!is_numeric($hours) || (float) $hours <= 0) {
            return '--';
        }

        $minutes_total = (int) round(((float) $hours) * 60);
        $hours_part = intdiv($minutes_total, 60);
        $minutes_part = $minutes_total % 60;

        if ($minutes_part > 0) {
            return $hours_part . ' h ' . $minutes_part . ' min';
        }

        return $hours_part . ' h';
    }
}

if (!function_exists('cleg_app_hours_between')) {
    function cleg_app_hours_between($clock_in, $clock_out) {
        return cleg_app_entry_hours(array(), $clock_in, $clock_out);
    }
}

if (!function_exists('cleg_app_get_client_ip')) {
    function cleg_app_get_client_ip() {
        $keys = array('HTTP_CF_CONNECTING_IP', 'HTTP_X_FORWARDED_FOR', 'REMOTE_ADDR');

        foreach ($keys as $key) {
            if (empty($_SERVER[$key])) {
                continue;
            }

            $raw = sanitize_text_field(wp_unslash($_SERVER[$key]));
            $parts = explode(',', $raw);
            $ip = trim($parts[0]);

            if ($ip !== '') {
                return $ip;
            }
        }

        return '';
    }
}

if (!function_exists('cleg_app_get_user_agent')) {
    function cleg_app_get_user_agent() {
        if (empty($_SERVER['HTTP_USER_AGENT'])) {
            return '';
        }

        return substr(sanitize_textarea_field(wp_unslash($_SERVER['HTTP_USER_AGENT'])), 0, 1000);
    }
}

if (!function_exists('cleg_app_find_previous_device_user')) {
    function cleg_app_find_previous_device_user($device_id, $current_user) {
        $device_id = sanitize_text_field($device_id);

        if ($device_id === '' || !cleg_app_airtable_is_configured()) {
            return '';
        }

        $formula = "{Device ID}='" . cleg_app_formula_text($device_id) . "'";
        $response = cleg_app_airtable_request('GET', CLEG_AIRTABLE_TIME_TABLE, array(
            'query' => array(
                'pageSize' => 10,
                'filterByFormula' => $formula,
                'sort[0][field]' => 'Clock In Time',
                'sort[0][direction]' => 'desc',
            ),
        ));

        if (is_wp_error($response)) {
            return '';
        }

        $current_id = (int) $current_user->ID;
        $current_username = sanitize_user($current_user->user_login);

        foreach (($response['records'] ?? array()) as $record) {
            $fields = $record['fields'] ?? array();
            $record_user_id = isset($fields['WordPress User ID']) ? (int) $fields['WordPress User ID'] : 0;
            $record_username = isset($fields['Portal Username']) ? sanitize_text_field($fields['Portal Username']) : '';

            if ($record_user_id && $record_user_id !== $current_id) {
                return $record_username !== '' ? $record_username : 'WP User ID ' . $record_user_id;
            }

            if ($record_username !== '' && $record_username !== $current_username) {
                return $record_username;
            }
        }

        return '';
    }
}

if (!function_exists('cleg_app_format_time_label')) {
    function cleg_app_format_time_label($value) {
        if ($value === '') {
            return 'Pendiente';
        }

        $timestamp = strtotime($value);

        if (!$timestamp) {
            return sanitize_text_field($value);
        }

        return esc_html(wp_date('M j, g:i a', $timestamp));
    }
}

if (!function_exists('cleg_panel_rrhh_shortcode')) {
    function cleg_panel_rrhh_shortcode($atts = array()) {
        if (!is_user_logged_in()) {
            $login_url = home_url('/acceso/');
            return '<section class="cleg-app-wrap cleg-app-logged-out"><div class="cleg-app-shell"><div class="cleg-app-brand-block">' . cleg_vantrexor_logo_markup('mark') . '<p class="cleg-app-kicker">Vantrexor</p></div><h2>Acceso requerido</h2><p>Entra para marcar entrada o salida.</p><a class="cleg-app-link-btn" href="' . esc_url($login_url) . '">Entrar</a></div>' . cleg_app_styles() . '</section>';
        }

        $user = wp_get_current_user();
        $employee = cleg_app_get_employee($user);
        $force_worker = current_user_can('manage_options') && isset($_GET['cleg_view']) && sanitize_text_field(wp_unslash($_GET['cleg_view'])) === 'trabajador';
        $is_admin = !$force_worker && cleg_app_user_can_admin($user, $employee);
        $is_worker = $force_worker || cleg_app_user_can_worker($user, $employee);

        if (!$is_admin && !$is_worker) {
            return '<section class="cleg-app-wrap"><div class="cleg-app-shell"><div class="cleg-app-brand-block">' . cleg_vantrexor_logo_markup('mark') . '<p class="cleg-app-kicker">Vantrexor</p></div><h2>Permiso pendiente</h2><p>Tu usuario esta activo, pero todavia falta darte permiso para entrar.</p><a class="cleg-app-text-link" href="' . esc_url(wp_logout_url(home_url('/acceso/'))) . '">Cerrar sesion</a></div>' . cleg_app_styles() . '</section>';
        }

        $display_name = $employee && $employee['name'] !== '' ? $employee['name'] : ($user->display_name ?: $user->user_login);
        $logout_url = wp_logout_url(home_url('/acceso/'));

        if ($is_admin) {
            $modules = array(
                array('RRHH', 'Human Resources', 'Activo 90%', home_url('/admin-rrhh/'), 'hr_core'),
                array('Proyecto', 'Proyectos y costos', 'En construccion 20%', home_url('/admin-job-sites/'), 'projects_work_orders'),
                array('Compras', 'Compras y RFQ', 'Activo 75%', home_url('/admin-procurement/'), 'procurement_quotes'),
            );

            $html = '<section class="cleg-app-wrap cleg-command-home" aria-label="Panel Vantrexor"><div class="cleg-app-shell cleg-command-shell"><div class="cleg-command-home-head"><div class="cleg-app-brand-block">' . cleg_vantrexor_logo_markup('mark') . '<p class="cleg-app-kicker">Vantrexor</p></div><h2>Panel</h2></div><a class="cleg-app-link-btn cleg-app-link-btn-ghost" href="' . esc_url($logout_url) . '">Cerrar sesion</a></div><div class="cleg-command-modules">';

            foreach ($modules as $module) {
                if (function_exists('cleg_saas_module_enabled') && !cleg_saas_module_enabled($module[4])) {
                    continue;
                }
                if (!function_exists('cleg_saas_module_enabled') && function_exists('cleg_shell_module_enabled') && !cleg_shell_module_enabled($module[4])) {
                    continue;
                }

                $icon = function_exists('cleg_visual_module_icon') ? cleg_visual_module_icon((string) $module[4], 'cleg-command-module-icon') : '';
                $html .= '<a class="cleg-command-module" href="' . esc_url($module[3]) . '">' . $icon . '<span>' . esc_html($module[2]) . '</span><small>' . esc_html($module[1]) . '</small><strong>' . esc_html($module[0]) . '</strong></a>';
            }

            return $html . '</div></div>' . cleg_app_styles() . '</section>';
        }

        ob_start();
        ?>
        <section class="cleg-app-wrap" aria-label="Portal de trabajadores Vantrexor">
            <?php echo cleg_app_render_worker($user, $display_name, $logout_url, $employee); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            <?php echo cleg_app_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
        </section>
        <?php

        return ob_get_clean();
    }
}

