if (!function_exists('cleg_app_clock_submit')) {
    function cleg_app_clock_submit() {
        if (!is_user_logged_in()) {
            wp_send_json_error(array('message' => 'Sesion expirada. Vuelve a entrar.'), 401);
        }

        check_ajax_referer('cleg_worker_app_nonce', 'nonce');

        if (!cleg_app_airtable_is_configured()) {
            wp_send_json_error(array('message' => 'No se pudo conectar con la oficina. Intenta de nuevo.'), 400);
        }

        $user = wp_get_current_user();
        $open_entry = cleg_app_get_open_entry($user);
        $is_clock_out = !empty($open_entry);
        $mode = isset($_POST['mode']) ? sanitize_text_field(wp_unslash($_POST['mode'])) : '';
        $is_project_switch = $is_clock_out && $mode === 'switch_project';
        $job_site = isset($_POST['job_site']) ? sanitize_text_field(wp_unslash($_POST['job_site'])) : '';
        $note = isset($_POST['note']) ? sanitize_textarea_field(wp_unslash($_POST['note'])) : '';
        $device_id = isset($_POST['device_id']) ? sanitize_text_field(wp_unslash($_POST['device_id'])) : '';
        $gps_override = isset($_POST['gps_override']) ? sanitize_text_field(wp_unslash($_POST['gps_override'])) : '0';
        $gps_error = isset($_POST['gps_error']) ? sanitize_text_field(wp_unslash($_POST['gps_error'])) : '';
        $geofence_override = isset($_POST['geofence_override']) ? sanitize_text_field(wp_unslash($_POST['geofence_override'])) : '0';
        $client_time = isset($_POST['client_time']) ? sanitize_text_field(wp_unslash($_POST['client_time'])) : '';
        $latitude = isset($_POST['latitude']) ? sanitize_text_field(wp_unslash($_POST['latitude'])) : '';
        $longitude = isset($_POST['longitude']) ? sanitize_text_field(wp_unslash($_POST['longitude'])) : '';
        $accuracy = isset($_POST['accuracy']) ? sanitize_text_field(wp_unslash($_POST['accuracy'])) : '';
        $event_time = cleg_app_iso_time($client_time);
        $map_link = cleg_app_map_link($latitude, $longitude);
        $employee_name = sanitize_text_field($user->display_name ?: $user->user_login);
        $employee_email = !empty($user->user_email) ? sanitize_email($user->user_email) : '';
        $portal_username = sanitize_user($user->user_login);
        $ip_address = cleg_app_get_client_ip();
        $user_agent = cleg_app_get_user_agent();
        $previous_device_user = cleg_app_find_previous_device_user($device_id, $user);
        $audit_flags = array();
        $review_job_site = $is_clock_out && !$is_project_switch && $open_entry ? $open_entry['job_site'] : $job_site;
        $gps_review = cleg_app_location_review($review_job_site, $latitude, $longitude, $accuracy, $gps_override, $gps_error);
        $temporary_job_site = stripos($review_job_site, 'Proyecto Temporal') !== false;

        if (in_array('Outside Geofence', $gps_review['reasons'], true) && $geofence_override !== '1') {
            wp_send_json_error(array(
                'code' => 'outside_geofence',
                'message' => 'Parece que estas lejos de este proyecto. Revisa si escogiste el proyecto correcto.',
                'distance' => $gps_review['distance'],
            ), 409);
        }

        if ($previous_device_user !== '') {
            $audit_flags[] = 'Shared Device Detected';
        }

        if ($temporary_job_site) {
            $audit_flags[] = 'Manual Review';
        }

        $audit_flags = array_merge($audit_flags, $gps_review['audit_flags']);

        if ($is_project_switch) {
            $old_job_site = $open_entry['job_site'];

            if ($job_site === '') {
                wp_send_json_error(array('message' => 'Escoge el nuevo proyecto.'), 400);
            }

            if ($old_job_site !== '' && strcasecmp($old_job_site, $job_site) === 0) {
                wp_send_json_error(array('message' => 'Escoge un proyecto diferente al actual.'), 400);
            }

            $exit_gps_review = cleg_app_location_review($old_job_site, $latitude, $longitude, $accuracy, $gps_override, $gps_error);
