if (!function_exists('cleg_app_manual_clock_out_submit')) {
    function cleg_app_manual_clock_out_submit() {
        if (!is_user_logged_in()) {
            wp_send_json_error(array('message' => 'Sesion expirada. Vuelve a entrar.'), 401);
        }

        check_ajax_referer('cleg_worker_app_nonce', 'nonce');

        if (!cleg_app_airtable_is_configured()) {
            wp_send_json_error(array('message' => 'No se pudo conectar con la oficina. Intenta de nuevo.'), 400);
        }

        $user = wp_get_current_user();
        $open_entry = cleg_app_get_open_entry($user);

        if (empty($open_entry)) {
            wp_send_json_error(array('message' => 'No tienes una entrada abierta.'), 400);
        }

        $manual_time = isset($_POST['manual_clock_out_iso']) ? sanitize_text_field(wp_unslash($_POST['manual_clock_out_iso'])) : '';
        $manual_note = isset($_POST['manual_note']) ? sanitize_textarea_field(wp_unslash($_POST['manual_note'])) : '';

        if ($manual_time === '') {
            wp_send_json_error(array('message' => 'Escoge la hora de salida.'), 400);
        }

        $manual_timestamp = strtotime($manual_time);

        if (!$manual_timestamp) {
            wp_send_json_error(array('message' => 'Revisa la hora de salida.'), 400);
        }

        if ($manual_timestamp > time()) {
            wp_send_json_error(array('message' => 'La hora de salida no puede ser en el futuro.'), 400);
        }

        $clock_out_time = cleg_app_iso_time($manual_time);
        $portal_username = sanitize_user($user->user_login);
        $note = 'Worker manual clock out requested. Current user: ' . $portal_username;

        if ($manual_note !== '') {
            $note .= "\nWorker note: " . $manual_note;
        }

        $fields = array(
            'Clock Out Time' => $clock_out_time,
            'Worker Reported Clock Out Time' => $clock_out_time,
            'Worker Manual Clock Out Requested' => true,
            'Worker Clock Out Review Note' => $manual_note,
            'Approval Status' => 'Pending Review',
            'Portal Username' => $portal_username,
            'GPS Review Required' => true,
            'Audit Flags' => array('Manual Review'),
            'Admin Notes' => $note,
        );

        $response = cleg_app_airtable_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
            'body' => array(
                'typecast' => true,
                'records' => array(
                    array(
                        'id' => $open_entry['id'],
                        'fields' => cleg_app_remove_empty_values($fields),
                    ),
                ),
            ),
        ));

        if (is_wp_error($response)) {
            wp_send_json_error(array('message' => 'No se pudo enviar. Intenta de nuevo.'), 500);
        }

        wp_send_json_success(array(
            'message' => 'Salida enviada para revisar.',
            'is_working' => false,
            'button_label' => 'Marcar entrada',
            'status_label' => 'No has empezado',
            'status_detail' => 'Salida enviada',
            'clock_in_time' => '',
            'job_site' => '',
        ));
    }
}

if (!function_exists('cleg_app_worker_request_submit')) {
    function cleg_app_worker_request_submit() {
        if (!is_user_logged_in()) {
            wp_send_json_error(array('message' => 'Sesion expirada. Vuelve a entrar.'), 401);
        }

        check_ajax_referer('cleg_worker_app_nonce', 'nonce');

        if (!cleg_app_airtable_is_configured()) {
            wp_send_json_error(array('message' => 'No se pudo conectar con la oficina. Intenta de nuevo.'), 400);
        }

        $user = wp_get_current_user();
        $type = isset($_POST['request_type']) ? sanitize_text_field(wp_unslash($_POST['request_type'])) : 'Ausencia';
        $detail = isset($_POST['request_detail']) ? sanitize_textarea_field(wp_unslash($_POST['request_detail'])) : '';
        $absence_date = isset($_POST['absence_date']) ? sanitize_text_field(wp_unslash($_POST['absence_date'])) : '';

        $allowed_types = array('Ausencia', 'Incidente', 'CorrecciÃ³n de hora', 'Permiso', 'Otro');
        if (!in_array($type, $allowed_types, true)) {
            $type = 'Otro';
        }

        if ($type === 'Ausencia') {
            if ($absence_date === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $absence_date)) {
                wp_send_json_error(array('message' => 'Escoge el dia que faltaste.'), 400);
            }

            $detail = trim('Dia que faltaste: ' . $absence_date . ($detail !== '' ? "\nNota: " . $detail : ''));
        } elseif ($detail === '') {
            wp_send_json_error(array('message' => 'Escribe una nota corta.'), 400);
        }

        $fields = array(
            'Request Code' => 'REQ-' . gmdate('Ymd-His') . '-' . (int) $user->ID,
            'Employee Name' => sanitize_text_field($user->display_name ?: $user->user_login),
            'Employee Email' => sanitize_email($user->user_email),
            'Portal Username' => sanitize_user($user->user_login),
            'WordPress User ID' => (int) $user->ID,
            'Request Type' => $type,
            'Status' => 'Pending',
            'Request Date' => $type === 'Ausencia' && $absence_date !== '' ? $absence_date : gmdate('Y-m-d'),
            'Details' => $detail,
        );

        $response = cleg_app_airtable_request('POST', CLEG_AIRTABLE_HR_TABLE, array(
            'body' => array(
                'typecast' => true,
                'records' => array(array('fields' => cleg_app_remove_empty_values($fields))),
            ),
        ));

        if (is_wp_error($response)) {
            wp_send_json_error(array('message' => 'No se pudo enviar. Intenta de nuevo.'), 500);
        }

        wp_send_json_success(array('message' => $type === 'Ausencia' ? 'Ausencia enviada.' : 'Mensaje enviado.'));
    }
}

if (!function_exists('cleg_app_handle_receipt_file')) {
    function cleg_app_handle_receipt_file($field_name) {
        if (empty($_FILES[$field_name]) || !is_array($_FILES[$field_name]) || empty($_FILES[$field_name]['name'])) {
            return new WP_Error('cleg_receipt_file_missing', 'Sube una foto o PDF del recibo.');
        }

        $file = $_FILES[$field_name];

        if (!empty($file['error'])) {
            return new WP_Error('cleg_receipt_file_error', 'No se pudo leer el archivo. Intenta de nuevo.');
        }

        if (!empty($file['size']) && (int) $file['size'] > 12 * MB_IN_BYTES) {
            return new WP_Error('cleg_receipt_file_large', 'El archivo debe pesar menos de 12 MB.');
        }

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';

        $upload = wp_handle_upload($file, array(
            'test_form' => false,
            'mimes' => array(
                'jpg|jpeg|jpe' => 'image/jpeg',
                'png' => 'image/png',
                'webp' => 'image/webp',
                'pdf' => 'application/pdf',
            ),
        ));

        if (isset($upload['error'])) {
            return new WP_Error('cleg_receipt_upload_failed', sanitize_text_field($upload['error']));
        }

        $filetype = wp_check_filetype($upload['file'], null);
        $attachment_id = wp_insert_attachment(array(
            'post_mime_type' => $filetype['type'],
            'post_title' => sanitize_file_name(pathinfo($upload['file'], PATHINFO_FILENAME)),
            'post_content' => '',
            'post_status' => 'private',
        ), $upload['file']);

        if (!is_wp_error($attachment_id)) {
            $metadata = wp_generate_attachment_metadata($attachment_id, $upload['file']);
            wp_update_attachment_metadata($attachment_id, $metadata);
        }

        return array(
            'attachment_id' => is_wp_error($attachment_id) ? 0 : (int) $attachment_id,
            'url' => esc_url_raw($upload['url']),
            'filename' => sanitize_file_name(basename($upload['file'])),
        );
    }
}

if (!function_exists('cleg_app_receipt_submit')) {
    function cleg_app_receipt_submit() {
        if (!is_user_logged_in()) {
            wp_send_json_error(array('message' => 'Sesion expirada. Vuelve a entrar.'), 401);
        }

        check_ajax_referer('cleg_worker_app_nonce', 'nonce');

