            wp_send_json_error(array('message' => 'No se pudo conectar con la oficina. Intenta de nuevo.'), 400);
        }

        $user = wp_get_current_user();
        $employee = cleg_app_get_employee($user);
        $purchase_date = isset($_POST['purchase_date']) ? sanitize_text_field(wp_unslash($_POST['purchase_date'])) : '';
        $description = isset($_POST['purchase_description']) ? sanitize_textarea_field(wp_unslash($_POST['purchase_description'])) : '';
        $total_raw = isset($_POST['purchase_total']) ? sanitize_text_field(wp_unslash($_POST['purchase_total'])) : '';
        $job_site = isset($_POST['purchase_job_site']) ? sanitize_text_field(wp_unslash($_POST['purchase_job_site'])) : '';
        $category = isset($_POST['purchase_category']) ? sanitize_text_field(wp_unslash($_POST['purchase_category'])) : '';
        $total = is_numeric($total_raw) ? round((float) $total_raw, 2) : 0;

        $allowed_categories = array(
            'Agua / comida' => 'Meals and refreshments',
            'Materiales de proyecto' => 'Job materials / project cost',
            'Combustible / peaje / estacionamiento' => 'Vehicle and travel',
            'Herramientas / equipos menores' => 'Small tools and equipment',
