        $card_label = is_array($employee) && !empty($employee['company_card_label']) ? $employee['company_card_label'] : '';
        $card_last4 = is_array($employee) && !empty($employee['company_card_last4']) ? $employee['company_card_last4'] : '';
        $qb_hint = $allowed_categories[$category];

        $fields = array(
            'Receipt Code' => $receipt_code,
            'Status' => 'Archivado',
