            'Employee Email' => sanitize_email($employee_email),
            'Portal Username' => sanitize_user($user->user_login),
            'WordPress User ID' => (int) $user->ID,
            'Employee Record ID' => is_array($employee) && !empty($employee['id']) ? $employee['id'] : '',
            'Purchase Date' => $purchase_date,
            'Description' => $description,
            'Total' => $total,
            'Purchase Category' => $category,
            'Job Site Name' => $job_site,
            'Cost Bucket' => 'Project Cost',
            'Payroll Reference' => 'Employee card purchase - no payroll deduction',
            'QuickBooks Sync Status' => 'QB pendiente',
            'QuickBooks Suggested Account' => $qb_hint,
            'Company Card' => $card_label,
            'Card Last 4' => $card_last4,
            'Receipt Attachment ID' => (int) $file['attachment_id'],
            'Receipt File URL' => $file['url'],
            'Receipt Photo' => array(array('url' => $file['url'])),
            'Submitted At' => gmdate('c'),
            'Source' => 'Worker Panel',
        );

        $response = cleg_app_airtable_request('POST', CLEG_AIRTABLE_RECEIPTS_TABLE, array(
            'body' => array(
                'typecast' => true,
                'records' => array(array('fields' => cleg_app_remove_empty_values($fields))),
            ),
        ));

        if (!is_wp_error($response)) {
            wp_send_json_success(array('message' => 'Recibo enviado para revision.'));
        }

        $fallback_detail = "Recibo de compra\n"
            . 'Proyecto: ' . $job_site . "\n"
            . 'Fecha: ' . $purchase_date . "\n"
            . 'Categoria: ' . $category . "\n"
            . 'Total: $' . number_format($total, 2, '.', '') . "\n"
            . 'Descripcion: ' . $description . "\n"
            . 'Archivo: ' . $file['url'] . "\n"
            . 'QuickBooks sugerido: ' . $qb_hint;

        $fallback = cleg_app_airtable_request('POST', CLEG_AIRTABLE_HR_TABLE, array(
            'body' => array(
                'typecast' => true,
                'records' => array(array('fields' => cleg_app_remove_empty_values(array(
                    'Request Code' => $receipt_code,
                    'Employee Name' => sanitize_text_field($employee_name),
                    'Employee Email' => sanitize_email($employee_email),
                    'Portal Username' => sanitize_user($user->user_login),
                    'WordPress User ID' => (int) $user->ID,
                    'Request Type' => 'Recibo de compra',
                    'Status' => 'Pending',
                    'Request Date' => $purchase_date,
                    'Details' => $fallback_detail,
                )))),
            ),
        ));

        if (is_wp_error($fallback)) {
            wp_send_json_error(array('message' => 'No se pudo enviar el recibo. Intenta de nuevo.'), 500);
        }

        wp_send_json_success(array('message' => 'Recibo enviado para revision.'));
    }
}

if (!function_exists('cleg_app_script')) {
    function cleg_app_script() {
        static $printed = false;

        if ($printed) {
            return '';
        }

        $printed = true;

        ob_start();
        ?>
        <script>
            (function () {
                const app = document.querySelector('[data-cleg-worker-app]');
                if (!app) return;

                const workerMenu = app.querySelector('.cleg-worker-menu');
                const workerMenuSummary = workerMenu ? workerMenu.querySelector('summary') : null;
                if (workerMenu && workerMenuSummary) {
                    workerMenuSummary.setAttribute('role', 'button');
                    workerMenuSummary.setAttribute('aria-expanded', workerMenu.open ? 'true' : 'false');
                    workerMenuSummary.addEventListener('click', function (event) {
                        event.preventDefault();
                        workerMenu.open = !workerMenu.open;
                        workerMenuSummary.setAttribute('aria-expanded', workerMenu.open ? 'true' : 'false');
                    });
                    workerMenu.addEventListener('click', function (event) {
                        if (event.target.closest('a')) {
                            workerMenu.open = false;
                            workerMenuSummary.setAttribute('aria-expanded', 'false');
                        }
                    });
                    document.addEventListener('click', function (event) {
                        if (!workerMenu.contains(event.target)) {
                            workerMenu.open = false;
                            workerMenuSummary.setAttribute('aria-expanded', 'false');
                        }
                    });
                }

                const form = app.querySelector('[data-clock-form]');
                const button = app.querySelector('[data-clock-button]');
                const buttonLabel = app.querySelector('[data-clock-button-label]');
                const modeInput = app.querySelector('[data-clock-mode]');
                const jobField = app.querySelector('[data-job-field]');
                const jobSelect = app.querySelector('[data-job-select]');
                const activeJob = app.querySelector('[data-active-job]');
                const switchProjectButton = app.querySelector('[data-switch-project-toggle]');
                const message = app.querySelector('[data-clock-message]');
                const warning = app.querySelector('[data-security-warning]');
                const alertModal = app.querySelector('[data-cleg-alert-modal]');
                const alertTitle = app.querySelector('[data-cleg-alert-title]');
                const alertBody = app.querySelector('[data-cleg-alert-body]');
                const alertClose = app.querySelector('[data-cleg-alert-close]');
                const deviceInput = app.querySelector('[data-device-id]');
                const geofenceOverride = app.querySelector('[data-geofence-override]');
                const label = app.querySelector('[data-status-label]');
                const detail = app.querySelector('[data-status-detail]');
                const elapsed = app.querySelector('[data-clock-elapsed]');
                const manualPanel = app.querySelector('[data-manual-clock-out-panel]');
                const manualForm = app.querySelector('[data-manual-clock-out-form]');
                const enableAlerts = app.querySelector('[data-enable-shift-alerts]');
                const installAppButton = app.querySelector('[data-cleg-worker-pwa-install]');
                const welcome = app.querySelector('[data-cleg-welcome]');
                const purchasePanel = app.querySelector('[data-cleg-worker-purchase-panel]');
                const purchaseLinks = app.querySelectorAll('[data-cleg-worker-purchase-open]');
                let workerInstallPrompt = null;
                let clockIn = app.getAttribute('data-clock-in') || '';
                let timer = null;
                let longShiftTimer = null;
                let isSwitchingProject = false;

                if (welcome) {
                    window.setTimeout(function () {
                        welcome.classList.add('is-leaving');
                    }, 3200);
                    window.setTimeout(function () {
                        welcome.classList.add('is-hidden');
                    }, 3900);
                }

                const getDeviceId = function () {
                    const key = 'cleg_worker_device_id';
                    let value = '';

                    try {
                        value = window.localStorage.getItem(key) || '';

                        if (!value) {
                            if (window.crypto && window.crypto.randomUUID) {
                                value = window.crypto.randomUUID();
                            } else {
                                value = 'cleg-' + Date.now() + '-' + Math.random().toString(16).slice(2);
                            }

                            window.localStorage.setItem(key, value);
                        }
                    } catch (error) {
                        value = 'cleg-session-' + Date.now() + '-' + Math.random().toString(16).slice(2);
                    }

                    return value;
                };

                if (deviceInput) {
                    deviceInput.value = getDeviceId();
                }

                const openPurchasePanel = function () {
                    if (!purchasePanel) return;
                    purchasePanel.classList.remove('is-hidden');
                    window.setTimeout(function () {
                        purchasePanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }, 30);
                };

                if (purchaseLinks.length) {
                    purchaseLinks.forEach(function (link) {
                        link.addEventListener('click', function (event) {
                            event.preventDefault();
                            openPurchasePanel();
                        });
                    });
                }

                if (window.location.hash === '#cleg-worker-purchase') {
                    openPurchasePanel();
                }

                const showVisualAlert = function (title, body) {
                    if (!alertModal) return;
                    if (alertTitle) alertTitle.textContent = title || 'Revisa esto';
                    if (alertBody) alertBody.textContent = body || 'Falta revisar algo antes de marcar.';
                    alertModal.classList.remove('is-hidden');
                    alertModal.setAttribute('aria-hidden', 'false');
                    if (alertClose) alertClose.focus({ preventScroll: true });
                };

                const hideVisualAlert = function () {
                    if (!alertModal) return;
                    alertModal.classList.add('is-hidden');
                    alertModal.setAttribute('aria-hidden', 'true');
                };

                if (alertClose) alertClose.addEventListener('click', hideVisualAlert);
                if (alertModal) {
                    alertModal.addEventListener('click', function (event) {
                        if (event.target === alertModal) hideVisualAlert();
                    });
                }
                document.addEventListener('keydown', function (event) {
                    if (event.key === 'Escape') hideVisualAlert();
                });

                const pad = function (num) {
                    return String(num).padStart(2, '0');
                };

                const setButtonText = function (text) {
                    if (buttonLabel) {
                        buttonLabel.textContent = text;
                    } else if (button) {
                        button.textContent = text;
                    }
                };

                const setSwitchingProject = function (enabled) {
                    const isWorking = app.getAttribute('data-working') === '1';
                    isSwitchingProject = !!enabled && isWorking;

                    if (modeInput) modeInput.value = isSwitchingProject ? 'switch_project' : (isWorking ? 'out' : 'in');
                    if (jobField) jobField.classList.toggle('is-hidden', isWorking && !isSwitchingProject);
                    if (switchProjectButton) {
                        switchProjectButton.classList.toggle('is-hidden', !isWorking);
                        switchProjectButton.textContent = isSwitchingProject ? 'Cancelar cambio' : 'Cambiar proyecto';
                    }
                    if (jobSelect && isSwitchingProject) jobSelect.value = '';
                    setButtonText(isSwitchingProject ? 'Confirmar cambio' : (isWorking ? 'Marcar salida' : 'Marcar entrada'));
                    if (message && isSwitchingProject) {
                        message.textContent = 'Escoge el nuevo proyecto y confirma el cambio.';
                        message.classList.remove('is-warning');
                    }
                    if (geofenceOverride) geofenceOverride.value = '0';
                };

                const renderElapsed = function () {
                    if (!clockIn || !elapsed) {
                        if (elapsed) elapsed.textContent = '00:00:00';
                        return;
                    }

                    const start = new Date(clockIn).getTime();
                    if (!start) return;

                    const diff = Math.max(0, Date.now() - start);
                    const total = Math.floor(diff / 1000);
                    const hours = Math.floor(total / 3600);
                    const minutes = Math.floor((total % 3600) / 60);
                    const seconds = total % 60;
                    elapsed.textContent = pad(hours) + ':' + pad(minutes) + ':' + pad(seconds);
                };

                const startTimer = function () {
                    window.clearInterval(timer);
                    renderElapsed();
                    if (clockIn) timer = window.setInterval(renderElapsed, 1000);
                };

                const scheduleLongShiftNotice = function () {
                    window.clearTimeout(longShiftTimer);
                    if (!clockIn) return;

                    const start = new Date(clockIn).getTime();
                    if (!start) return;

                    const tenHours = 10 * 60 * 60 * 1000;
                    const delay = Math.max(0, start + tenHours - Date.now());

                    longShiftTimer = window.setTimeout(function () {
                        const text = 'Llevas 10 horas trabajando. Si terminaste, marca salida.';
                        if (warning) {
                            warning.textContent = text;
                            warning.classList.remove('is-hidden');
                        }
                        if ('Notification' in window && Notification.permission === 'granted') {
                    new Notification('Vantrexor', { body: text });
                        }
                    }, delay);
                };

                const requestNotificationPermission = function () {
                    if (!('Notification' in window)) return;
                    if (Notification.permission === 'default') {
                        Notification.requestPermission();
                    }
                };

                const getPosition = function () {
                    return new Promise(function (resolve) {
                        if (!navigator.geolocation) {
                            resolve({});
                            return;
                        }

                        navigator.geolocation.getCurrentPosition(function (pos) {
                            resolve({
                                latitude: pos.coords.latitude,
                                longitude: pos.coords.longitude,
                                accuracy: Math.round(pos.coords.accuracy || 0)
                            });
                        }, function (error) {
                            resolve({
                                error: error && error.message ? error.message : 'No se pudo usar tu ubicacion.'
                            });
                        }, {
                            enableHighAccuracy: true,
                            timeout: 9000,
                            maximumAge: 30000
                        });
                    });
                };

                const setWorking = function (isWorking, data) {
                    app.setAttribute('data-working', isWorking ? '1' : '0');
                    clockIn = isWorking ? (data.clock_in_time || '') : '';
                    app.setAttribute('data-clock-in', clockIn);
                    modeInput.value = isWorking ? 'out' : 'in';
                    isSwitchingProject = false;
                    setButtonText(isWorking ? 'Marcar salida' : 'Marcar entrada');
                    label.textContent = data.status_label || (isWorking ? 'Trabajando' : 'No has empezado');
                    detail.textContent = data.status_detail || (isWorking ? 'Trabajando' : 'Listo para entrar');

                    if (jobField) jobField.classList.toggle('is-hidden', isWorking);
                    if (switchProjectButton) {
                        switchProjectButton.classList.toggle('is-hidden', !isWorking);
                        switchProjectButton.textContent = 'Cambiar proyecto';
                    }
                    if (manualPanel) {
                        manualPanel.classList.toggle('is-hidden', !isWorking);
                        if (!isWorking) manualPanel.open = false;
                    }
                    if (activeJob) {
                        activeJob.textContent = data.job_site || 'Proyecto actual';
                        activeJob.classList.toggle('is-hidden', !isWorking);
                    }

                    if (!isWorking && jobSelect) jobSelect.value = '';
                    startTimer();
                    scheduleLongShiftNotice();
                };

                startTimer();
                scheduleLongShiftNotice();

                if (enableAlerts) {
                    enableAlerts.addEventListener('click', function () {
                        requestNotificationPermission();
                        if (message) message.textContent = 'Recordatorio activado en este telefono.';
                    });
                }

                if (switchProjectButton) {
                    switchProjectButton.addEventListener('click', function () {
                        setSwitchingProject(!isSwitchingProject);
                        if (!isSwitchingProject && message) {
                            message.textContent = 'Se usara tu ubicacion al marcar.';
                            message.classList.remove('is-warning');
                        }
                    });
                }

                form.addEventListener('submit', async function (event) {
                    event.preventDefault();
                    button.disabled = true;
                    setButtonText('Marcando...');
                    message.textContent = 'Buscando tu ubicacion...';
                    message.classList.remove('is-warning');

                    const isStartingShift = app.getAttribute('data-working') !== '1';
                    if ((isStartingShift || isSwitchingProject) && jobSelect && !jobSelect.value) {
                        button.disabled = false;
                        setButtonText(isSwitchingProject ? 'Confirmar cambio' : 'Marcar entrada');
                        message.textContent = isSwitchingProject ? 'Escoge el nuevo proyecto.' : 'Escoge el proyecto antes de marcar entrada.';
                        message.classList.add('is-warning');
                        showVisualAlert('Escoge el proyecto', isSwitchingProject ? 'Escoge el nuevo proyecto antes de confirmar el cambio.' : 'Primero escoge el proyecto donde estas trabajando.');
                        if (warning) {
                            warning.textContent = 'Falta escoger el proyecto.';
                            warning.classList.remove('is-hidden');
                        }
                        return;
                    }

                    const position = await getPosition();
                    const gpsOverride = form.querySelector('[data-gps-override]');
                    const gpsError = form.querySelector('[data-gps-error]');

                    if ((!position.latitude || !position.longitude) && gpsOverride && gpsOverride.value !== '1') {
                        gpsOverride.value = '1';
                        if (gpsError) gpsError.value = position.error || 'No se pudo usar tu ubicacion.';
                        button.disabled = false;
                        const isWorking = app.getAttribute('data-working') === '1';
                        setButtonText(isSwitchingProject ? 'Cambiar sin ubicacion' : (isWorking ? 'Marcar salida sin ubicacion' : 'Marcar entrada sin ubicacion'));
                        message.textContent = 'Activa la ubicacion y toca otra vez. Si no puedes, toca de nuevo y la oficina lo revisa.';
                        message.classList.add('is-warning');
                        showVisualAlert('No se pudo usar tu ubicacion', 'Activa la ubicacion del telefono y toca otra vez. Si no puedes, el proximo intento se envia para revision.');
                        if (warning) {
                            warning.textContent = 'No se pudo usar tu ubicacion. Si tocas otra vez, la oficina lo revisa.';
                            warning.classList.remove('is-hidden');
                        }
                        return;
                    }

                    const formData = new FormData(form);
                    formData.set('client_time', new Date().toISOString());

                    if (position.latitude) formData.set('latitude', position.latitude);
                    if (position.longitude) formData.set('longitude', position.longitude);
                    if (position.accuracy) formData.set('accuracy', position.accuracy);

                    message.textContent = 'Marcando...';

                    try {
                        const response = await fetch('<?php echo esc_url(admin_url('admin-ajax.php')); ?>', {
                            method: 'POST',
                            credentials: 'same-origin',
                            body: formData
                        });
                        const payload = await response.json();

                        if (!payload || !payload.success) {
                            const apiError = new Error(payload && payload.data && payload.data.message ? payload.data.message : 'No se pudo marcar. Intenta de nuevo.');
                            apiError.code = payload && payload.data && payload.data.code ? payload.data.code : '';
                            throw apiError;
                        }

                        setWorking(!!payload.data.is_working, payload.data);
                        message.textContent = payload.data.message || 'Marcado.';
                        message.classList.remove('is-warning');
                        if (geofenceOverride) geofenceOverride.value = '0';

                        if (warning) warning.classList.add('is-hidden');

                        const note = form.querySelector('textarea[name="note"]');
                        if (note) note.value = '';
                    } catch (error) {
                        const isWorking = app.getAttribute('data-working') === '1';
                        if (error.code === 'outside_geofence' && geofenceOverride && geofenceOverride.value !== '1') {
                            geofenceOverride.value = '1';
                            setButtonText(isSwitchingProject ? 'Cambiar fuera de zona' : (isWorking ? 'Marcar salida fuera de zona' : 'Marcar fuera de zona'));
                            message.textContent = error.message + ' Si el proyecto es correcto, toca de nuevo y la oficina lo revisa.';
                            message.classList.add('is-warning');
                            showVisualAlert('Estas fuera de zona', 'Revisa que el proyecto sea correcto. Si estas seguro, toca otra vez y la oficina lo revisa.');
                            if (warning) {
                                warning.textContent = 'Estas lejos del proyecto escogido. Revisa antes de marcar.';
                                warning.classList.remove('is-hidden');
                            }
                        } else {
                            setButtonText(isSwitchingProject ? 'Confirmar cambio' : (isWorking ? 'Marcar salida' : 'Marcar entrada'));
                            message.textContent = error.message || 'No se pudo marcar. Intenta de nuevo.';
                            message.classList.add('is-warning');
                        }
                    } finally {
                        button.disabled = false;
                    }
                });

                if (jobSelect && geofenceOverride) {
                    jobSelect.addEventListener('change', function () {
                        geofenceOverride.value = '0';
                        if (message) message.classList.remove('is-warning');
                        if (warning) warning.classList.add('is-hidden');
                    });
                }

                window.addEventListener('beforeinstallprompt', function (event) {
                    event.preventDefault();
                    workerInstallPrompt = event;
                });

                if (installAppButton) {
                    installAppButton.addEventListener('click', async function () {
                        if (workerMenu) {
                            workerMenu.open = false;
                            if (workerMenuSummary) workerMenuSummary.setAttribute('aria-expanded', 'false');
                        }

                        if (workerInstallPrompt) {
                            workerInstallPrompt.prompt();
                            try {
                                await workerInstallPrompt.userChoice;
                            } catch (error) {}
                            workerInstallPrompt = null;
                            return;
                        }

                        showVisualAlert('Instalar app', 'Android: abre el menu del navegador y toca Instalar app o Agregar a pantalla de inicio. iPhone: toca Compartir y luego Agregar a pantalla de inicio.');
                    });
                }

                if (manualForm) {
                    const manualLocalInput = manualForm.querySelector('[data-manual-clock-out-local]');
                    if (manualLocalInput) {
                        const setManualMaxNow = function () {
                            const now = new Date();
                            const offset = now.getTimezoneOffset() * 60000;
                            manualLocalInput.max = new Date(now.getTime() - offset).toISOString().slice(0, 16);
                        };
                        setManualMaxNow();
                        manualLocalInput.addEventListener('focus', setManualMaxNow);
                    }

                    manualForm.addEventListener('submit', async function (event) {
                        event.preventDefault();
                        const submit = manualForm.querySelector('button[type="submit"]');
                        const localInput = manualForm.querySelector('[data-manual-clock-out-local]');
                        const isoInput = manualForm.querySelector('[data-manual-clock-out-iso]');
                        if (!localInput || !localInput.value) {
                            message.textContent = 'Escoge la hora de salida.';
                            return;
                        }
                        if (isoInput) isoInput.value = new Date(localInput.value).toISOString();
                        if (submit) {
                            submit.disabled = true;
                            submit.textContent = 'Enviando...';
                        }
                        try {
                            const response = await fetch('<?php echo esc_url(admin_url('admin-ajax.php')); ?>', {
                                method: 'POST',
                                credentials: 'same-origin',
                                body: new FormData(manualForm)
                            });
                            const payload = await response.json();
                            if (!payload || !payload.success) {
                                throw new Error(payload && payload.data && payload.data.message ? payload.data.message : 'No se pudo enviar. Intenta de nuevo.');
                            }
                            setWorking(false, payload.data);
                            message.textContent = payload.data.message || 'Salida enviada para revisar.';
                            manualForm.closest('details').open = false;
                        } catch (error) {
                            message.textContent = error.message || 'No se pudo enviar. Intenta de nuevo.';
                        } finally {
                            if (submit) {
                                submit.disabled = false;
                                submit.textContent = 'Enviar salida';
                            }
                        }
                    });
                }

                const requestForm = app.querySelector('[data-worker-request-form]');
                const receiptForm = app.querySelector('[data-worker-receipt-form]');
                const localDateValue = function (date) {
                    const year = date.getFullYear();
                    const month = String(date.getMonth() + 1).padStart(2, '0');
                    const day = String(date.getDate()).padStart(2, '0');
                    return year + '-' + month + '-' + day;
                };

                if (receiptForm) {
                    const receiptMessage = receiptForm.querySelector('[data-worker-receipt-message]');
                    const receiptSummary = receiptForm.querySelector('[data-worker-receipt-summary]');
                    const receiptFile = receiptForm.querySelector('input[name="receipt_file"]');
                    const receiptDate = receiptForm.querySelector('[data-receipt-date]');
                    const receiptTotal = receiptForm.querySelector('input[name="purchase_total"]');
                    const receiptJob = receiptForm.querySelector('select[name="purchase_job_site"]');
                    const receiptCategory = receiptForm.querySelector('select[name="purchase_category"]');
                    const receiptFileStatus = receiptForm.querySelector('[data-worker-receipt-file-status]');
                    const updateReceiptSummary = function () {
                        const file = receiptFile && receiptFile.files && receiptFile.files[0];
                        if (receiptFileStatus) {
                            receiptFileStatus.textContent = file ? 'Archivo: ' + file.name + ' (' + Math.ceil(file.size / 1024) + ' KB)' : 'Ningún archivo seleccionado.';
                        }
                        if (receiptSummary) {
                            const values = [
                                file ? file.name : 'sin archivo',
                                receiptDate && receiptDate.value ? receiptDate.value : 'sin fecha',
                                receiptTotal && receiptTotal.value ? '$' + receiptTotal.value : 'sin total',
                                receiptJob && receiptJob.value ? receiptJob.value : 'sin proyecto',
                                receiptCategory && receiptCategory.value ? receiptCategory.value : 'sin categoría'
                            ];
                            receiptSummary.textContent = 'Revisión: ' + values.join(' · ');
                        }
                    };
                    [receiptFile, receiptDate, receiptTotal, receiptJob, receiptCategory].forEach(function (control) {
                        if (control) control.addEventListener('change', updateReceiptSummary);
                        if (control && control.type !== 'file') control.addEventListener('input', updateReceiptSummary);
                    });
                    updateReceiptSummary();
                    receiptForm.addEventListener('submit', async function (event) {
                        event.preventDefault();
                        const submit = receiptForm.querySelector('button[type="submit"]');
                        if (submit) {
                            submit.disabled = true;
                            submit.textContent = 'Enviando...';
                        }
                        if (receiptMessage) {
                            receiptMessage.textContent = 'Subiendo recibo...';
                            receiptMessage.classList.remove('is-warning');
                        }

                        try {
                            const response = await fetch('<?php echo esc_url(admin_url('admin-ajax.php')); ?>', {
                                method: 'POST',
                                credentials: 'same-origin',
                                body: new FormData(receiptForm)
                            });
                            const payload = await response.json();
                            if (!payload || !payload.success) {
                                throw new Error(payload && payload.data && payload.data.message ? payload.data.message : 'No se pudo enviar el recibo. Intenta de nuevo.');
                            }

                            receiptForm.reset();
                            if (receiptDate) receiptDate.value = localDateValue(new Date());
                            if (receiptMessage) {
                                receiptMessage.textContent = payload.data.message || 'Recibo enviado para revision.';
                                receiptMessage.classList.remove('is-warning');
                            }
                        } catch (error) {
                            if (receiptMessage) {
                                receiptMessage.textContent = error.message || 'No se pudo enviar el recibo. Intenta de nuevo.';
                                receiptMessage.classList.add('is-warning');
                            }
                        } finally {
                            if (submit) {
                                submit.disabled = false;
                                submit.textContent = 'Enviar recibo';
                            }
                        }
                    });
                }

                if (requestForm) {
                    const requestMessage = requestForm.querySelector('[data-worker-request-message]');
                    const absenceStart = requestForm.querySelector('[data-absence-start]');
                    const absenceEnd = requestForm.querySelector('[data-absence-end]');
                    const detailInput = requestForm.querySelector('textarea[name="request_detail"]');
                    const dateList = function (startValue, endValue) {
                        const dates = [];
                        const start = new Date(startValue + 'T00:00:00');
                        const end = new Date((endValue || startValue) + 'T00:00:00');

                        if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
                            throw new Error('Escoge fechas validas.');
                        }

                        if (end.getTime() < start.getTime()) {
                            throw new Error('La fecha Hasta no puede ser anterior a Desde.');
                        }

                        const cursor = new Date(start.getTime());
                        while (cursor.getTime() <= end.getTime()) {
                            if (dates.length >= 31) {
                                throw new Error('El rango maximo es de 31 dias.');
                            }
                            dates.push(cursor.toISOString().slice(0, 10));
                            cursor.setDate(cursor.getDate() + 1);
                        }

                        return dates;
                    };

                    if (absenceStart && absenceEnd) {
                        absenceStart.addEventListener('change', function () {
                            absenceEnd.min = absenceStart.value || '';
                            if (!absenceEnd.value || absenceEnd.value < absenceStart.value) {
                                absenceEnd.value = absenceStart.value || '';
                            }
                        });
                    }

                    requestForm.addEventListener('submit', async function (event) {
                        event.preventDefault();
                        const submit = requestForm.querySelector('button[type="submit"]');
                        if (submit) {
                            submit.disabled = true;
                            submit.textContent = 'Enviando...';
                        }
                        if (requestMessage) requestMessage.textContent = 'Enviando...';
                        try {
                            const days = dateList(absenceStart ? absenceStart.value : '', absenceEnd ? absenceEnd.value : '');
                            const originalDetail = detailInput ? detailInput.value.trim() : '';

                            let sentDays = 0;
                            for (let index = 0; index < days.length; index++) {
                                if (requestMessage) {
                                    requestMessage.textContent = days.length > 1 ? 'Enviando ' + (index + 1) + ' de ' + days.length + '...' : 'Enviando...';
                                }

                                const formData = new FormData(requestForm);
                                formData.set('absence_date', days[index]);

                                if (days.length > 1) {
                                    formData.set('request_detail', 'Rango solicitado: ' + days[0] + ' al ' + days[days.length - 1] + (originalDetail ? "\n" + originalDetail : ''));
                                }

                                const response = await fetch('<?php echo esc_url(admin_url('admin-ajax.php')); ?>', {
                                    method: 'POST',
                                    credentials: 'same-origin',
                                    body: formData
                                });
                                const payload = await response.json();
                                if (!payload || !payload.success) {
                                    throw new Error('Se enviaron ' + sentDays + ' de ' + days.length + ' dias. ' + (payload && payload.data && payload.data.message ? payload.data.message : 'No se pudo completar el rango. Revisa los dias enviados antes de reintentar.'));
                                }
                                sentDays++;
                            }

                            requestForm.reset();
                            if (requestMessage) requestMessage.textContent = days.length > 1 ? 'Ausencia enviada por ' + days.length + ' dias.' : 'Ausencia enviada.';
                        } catch (error) {
                            if (requestMessage) requestMessage.textContent = error.message || 'No se pudo enviar. Intenta de nuevo.';
                        } finally {
                            if (submit) {
                                submit.disabled = false;
                                submit.textContent = 'Enviar';
                            }
                        }
                    });
                }
            })();
        </script>
        <?php
        return ob_get_clean();
    }
}

