if (!function_exists('cleg_admin_airtable_ready')) {
    function cleg_admin_airtable_ready() {
        if (function_exists('cleg_integrations_airtable_ready')) {
            return cleg_integrations_airtable_ready('hr_core')
                || cleg_integrations_airtable_ready('forms_requests')
                || cleg_integrations_airtable_ready('field_ops')
                || cleg_integrations_airtable_ready('projects_work_orders')
                || cleg_integrations_airtable_ready('procurement_quotes');
        }

        return CLEG_ADMIN_AIRTABLE_TOKEN !== '' && CLEG_ADMIN_AIRTABLE_TOKEN !== 'REEMPLAZAR_AIRTABLE_PAT';
    }
}

if (!function_exists('cleg_admin_airtable_module_for_table')) {
    function cleg_admin_airtable_module_for_table($table) {
        $table = (string) $table;

        $map = array(
            'forms_requests' => array(
                defined('CLEG_AIRTABLE_HR_REQUESTS_TABLE') ? CLEG_AIRTABLE_HR_REQUESTS_TABLE : 'HR Requests',
            ),
            'field_ops' => array(
                defined('CLEG_AIRTABLE_TIME_TABLE') ? CLEG_AIRTABLE_TIME_TABLE : 'Time Entries',
                defined('CLEG_RRHH_TABLE_TIME_ENTRIES') ? CLEG_RRHH_TABLE_TIME_ENTRIES : 'Time Entries',
                defined('CLEG_RRHH_TABLE_LOCATION_PINGS') ? CLEG_RRHH_TABLE_LOCATION_PINGS : 'Worker Location Pings',
            ),
            'projects_work_orders' => array(
                defined('CLEG_AIRTABLE_JOBSITES_TABLE') ? CLEG_AIRTABLE_JOBSITES_TABLE : 'Job Sites',
                defined('CLEG_RRHH_TABLE_JOB_SITES') ? CLEG_RRHH_TABLE_JOB_SITES : 'Job Sites',
            ),
            'procurement_quotes' => array(
                defined('CLEG_PROC_AIRTABLE_REQUESTS_TABLE') ? CLEG_PROC_AIRTABLE_REQUESTS_TABLE : 'Procurement Requests',
                defined('CLEG_PROC_AIRTABLE_ITEMS_TABLE') ? CLEG_PROC_AIRTABLE_ITEMS_TABLE : 'Procurement Items',
                defined('CLEG_PROC_AIRTABLE_QUOTES_TABLE') ? CLEG_PROC_AIRTABLE_QUOTES_TABLE : 'Procurement Quotes',
                defined('CLEG_PROC_AIRTABLE_POS_TABLE') ? CLEG_PROC_AIRTABLE_POS_TABLE : 'Procurement POs',
                defined('CLEG_PROC_AIRTABLE_SHIPMENTS_TABLE') ? CLEG_PROC_AIRTABLE_SHIPMENTS_TABLE : 'Procurement Shipments',
                defined('CLEG_PROC_AIRTABLE_VENDORS_TABLE') ? CLEG_PROC_AIRTABLE_VENDORS_TABLE : 'Procurement Vendors',
                defined('CLEG_PROC_AIRTABLE_HISTORY_TABLE') ? CLEG_PROC_AIRTABLE_HISTORY_TABLE : 'Procurement Product History',
                defined('CLEG_PROC_AIRTABLE_FOLLOWUPS_TABLE') ? CLEG_PROC_AIRTABLE_FOLLOWUPS_TABLE : 'Procurement Follow Ups',
                defined('CLEG_PROC_AIRTABLE_AUDIT_TABLE') ? CLEG_PROC_AIRTABLE_AUDIT_TABLE : 'Procurement Audit Log',
                defined('CLEG_AIRTABLE_RECEIPTS_TABLE') ? CLEG_AIRTABLE_RECEIPTS_TABLE : 'Purchase Receipts',
            ),
            'hr_core' => array(
                defined('CLEG_AIRTABLE_EMPLOYEES_TABLE') ? CLEG_AIRTABLE_EMPLOYEES_TABLE : 'Employees',
                defined('CLEG_RRHH_TABLE_EMPLOYEES') ? CLEG_RRHH_TABLE_EMPLOYEES : 'Employees',
                defined('CLEG_AIRTABLE_AUDIT_TABLE') ? CLEG_AIRTABLE_AUDIT_TABLE : 'Portal Audit Log',
            ),
        );

        foreach ($map as $module_key => $tables) {
            if (in_array($table, array_unique($tables), true)) {
                return $module_key;
            }
        }

        return 'hr_core';
    }
}

if (!function_exists('cleg_admin_request')) {
    function cleg_admin_request($method, $table, $args = array()) {
        if (function_exists('cleg_integrations_airtable_request')) {
            $module_key = cleg_admin_airtable_module_for_table($table);
            $query = (!empty($args['query']) && is_array($args['query'])) ? $args['query'] : array();
            $body = !empty($args['body']) ? $args['body'] : null;
            if (!empty($args['record_id'])) {
                $query['record_id'] = sanitize_text_field((string) $args['record_id']);
            }

            return cleg_integrations_airtable_request($module_key, $method, $table, $query, $body);
        }

        if (!cleg_admin_airtable_ready()) {
            return new WP_Error('cleg_admin_airtable_missing', 'Airtable no esta configurado en este snippet.');
        }

        $url = 'https://api.airtable.com/v0/' . rawurlencode(CLEG_AIRTABLE_BASE_ID) . '/' . rawurlencode($table);

        if (!empty($args['query']) && is_array($args['query'])) {
            $url = add_query_arg($args['query'], $url);
        }

        $request = array(
            'method' => $method,
            'timeout' => 20,
            'headers' => array(
                'Authorization' => 'Bearer ' . CLEG_ADMIN_AIRTABLE_TOKEN,
                'Content-Type' => 'application/json',
            ),
        );

        if (!empty($args['body'])) {
            $request['body'] = wp_json_encode($args['body']);
        }

        $response = wp_remote_request($url, $request);

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        $body = json_decode(wp_remote_retrieve_body($response), true);

        if ($code < 200 || $code >= 300) {
            $message = isset($body['error']['message']) ? $body['error']['message'] : 'Airtable rechazo la solicitud.';
            return new WP_Error('cleg_admin_airtable_error', $message, array('status' => $code));
        }

        return is_array($body) ? $body : array();
    }
}

if (!function_exists('cleg_admin_user_allowed')) {
    function cleg_admin_user_allowed() {
        if (!is_user_logged_in()) {
            return false;
        }

        $user = wp_get_current_user();
        $path = isset($_SERVER['REQUEST_URI']) ? trim((string) wp_parse_url(esc_url_raw(wp_unslash($_SERVER['REQUEST_URI'])), PHP_URL_PATH), '/') : '';
        $is_field_ops_admin = in_array($path, array('admin-horas', 'admin-tiempo-real', 'admin-dispositivos'), true);

        if ($is_field_ops_admin && function_exists('cleg_field_ops_user_can_review_hours') && cleg_field_ops_user_can_review_hours($user->ID)) {
            return true;
        }

        if (function_exists('cleg_starter_user_can_rrhh') && cleg_starter_user_can_rrhh()) {
            return true;
        }

        if (current_user_can('manage_options') || current_user_can('edit_pages')) {
            return true;
        }

        $roles = (array) $user->roles;
        $allowed_roles = array('administrator', 'editor', 'hr_manager', 'rrhh', 'cleg_admin');
        return (bool) array_intersect($roles, $allowed_roles);
    }
}

if (!function_exists('cleg_admin_gate')) {
    function cleg_admin_gate() {
        if (cleg_admin_user_allowed()) {
            return '';
        }

        if (!is_user_logged_in()) {
            return '<section class="cleg-admin-ui"><div class="cleg-admin-empty"><h2>Acceso requerido</h2><p>Entra al portal para ver esta pagina.</p><a href="' . esc_url(home_url('/acceso/')) . '">Entrar</a></div></section>';
        }

        return '<section class="cleg-admin-ui"><div class="cleg-admin-empty"><h2>No autorizado</h2><p>Esta pantalla es solo para administradores de RRHH.</p></div></section>';
    }
}

if (!function_exists('cleg_admin_formula_text')) {
    function cleg_admin_formula_text($value) {
