    }
}

if (!function_exists('cleg_admin_records')) {
    function cleg_admin_records($table, $query = array()) {
        $records = array();
        $cursor = '';

        do {
            $page_query = $query;
            $page_query['pageSize'] = isset($page_query['pageSize']) ? min(100, (int) $page_query['pageSize']) : 100;

            if ($cursor !== '') {
                $page_query['offset'] = $cursor;
            }

            $response = cleg_admin_request('GET', $table, array('query' => $page_query));

            if (is_wp_error($response)) {
                return $response;
            }

            $records = array_merge($records, $response['records'] ?? array());
            $cursor = isset($response['offset']) ? sanitize_text_field($response['offset']) : '';
        } while ($cursor !== '');

        return $records;
    }
}

if (!function_exists('cleg_admin_time_records')) {
    function cleg_admin_time_records($filter = '', $limit = 100) {
        $query = array(
            'pageSize' => min(100, (int) $limit),
            'sort[0][field]' => 'Clock In Time',
            'sort[0][direction]' => 'desc',
