        if ($filter !== '') {
            $query['filterByFormula'] = $filter;
        }

        if (function_exists('cleg_field_ops_records')) {
            return cleg_field_ops_records(CLEG_AIRTABLE_TIME_TABLE, $query);
        }

        return cleg_admin_records(CLEG_AIRTABLE_TIME_TABLE, $query);
    }
}

