if (!function_exists('cleg_admin_money')) {
    function cleg_admin_money($value) {
        return '$' . number_format((float) $value, 2);
    }
}

if (!function_exists('cleg_admin_hours_float')) {
    function cleg_admin_hours_float($in, $out) {
        $start = strtotime($in);
        $end = strtotime($out);

        if (!$start || !$end || $end <= $start) {
            return 0;
        }

        return round(($end - $start) / HOUR_IN_SECONDS, 2);
    }
}

if (!function_exists('cleg_admin_hours_label')) {
    function cleg_admin_hours_label($hours) {
        $hours = max(0, (float) $hours);
        $total_minutes = (int) round($hours * 60);
        $whole_hours = (int) floor($total_minutes / 60);
        $minutes = $total_minutes % 60;

        return $whole_hours . 'h:' . str_pad((string) $minutes, 2, '0', STR_PAD_LEFT) . 'm';
    }
}

if (!function_exists('cleg_admin_employee_pay_index')) {
    function cleg_admin_employee_pay_index($employees) {
        $index = array();

        foreach ((array) $employees as $employee) {
            $name = cleg_admin_field($employee, 'Employee Name');
            $username = cleg_admin_field($employee, 'Portal Username');
            $data = array(
                'amount' => (float) cleg_admin_field($employee, 'Payroll Amount', 0),
                'period' => cleg_admin_field($employee, 'Payroll Period', 'Per Hour'),
            );

            if ($name !== '') {
                $index[strtolower($name)] = $data;
            }

            if ($username !== '') {
                $index[strtolower($username)] = $data;
            }
        }

        return $index;
    }
}

if (!function_exists('cleg_admin_local_to_iso')) {
    function cleg_admin_local_to_iso($value) {
        $value = trim((string) $value);

        if ($value === '') {
            return '';
        }

        try {
            $dt = new DateTime($value, new DateTimeZone('America/Puerto_Rico'));
        } catch (Exception $e) {
            return '';
        }

        $dt->setTimezone(new DateTimeZone('UTC'));
        return $dt->format('Y-m-d\TH:i:s.000\Z');
    }
}

if (!function_exists('cleg_admin_pr_datetime')) {
    function cleg_admin_pr_datetime($value) {
        $value = trim((string) $value);

        if ($value === '') {
            return null;
        }

        try {
            $dt = new DateTime($value, new DateTimeZone('UTC'));
            $dt->setTimezone(new DateTimeZone('America/Puerto_Rico'));
            return $dt;
        } catch (Exception $e) {
            return null;
        }
    }
}

if (!function_exists('cleg_admin_field')) {
    function cleg_admin_field($record, $field, $default = '') {
        $fields = $record['fields'] ?? array();
        $value = $fields[$field] ?? $default;

        if (is_array($value)) {
            if (isset($value['name'])) {
                return sanitize_text_field($value['name']);
            }

            $names = array();
            foreach ($value as $item) {
                if (is_array($item) && isset($item['name'])) {
                    $names[] = sanitize_text_field($item['name']);
                } elseif (is_scalar($item)) {
                    $names[] = sanitize_text_field((string) $item);
                }
            }

            return implode(', ', $names);
        }

        return is_scalar($value) ? sanitize_text_field((string) $value) : $default;
    }
}

if (!function_exists('cleg_admin_date')) {
    function cleg_admin_date($value) {
        if ($value === '') {
            return 'Pendiente';
        }

        $dt = cleg_admin_pr_datetime($value);
        return $dt ? $dt->format('M j, g:i a') : sanitize_text_field($value);
    }
}

if (!function_exists('cleg_admin_datetime_input')) {
    function cleg_admin_datetime_input($value) {
        $dt = cleg_admin_pr_datetime($value);
        return $dt ? $dt->format('Y-m-d\TH:i') : '';
    }
}

if (!function_exists('cleg_admin_hours')) {
    function cleg_admin_hours($in, $out) {
        $start = strtotime($in);
        $end = strtotime($out);

        if (!$start || !$end || $end <= $start) {
            return '--';
        }

        return cleg_admin_hours_label(($end - $start) / HOUR_IN_SECONDS);
    }
}

if (!function_exists('cleg_admin_context_url')) {
    function cleg_admin_context_url($path, $args = array()) {
        return add_query_arg($args, home_url($path));
    }
}

if (!function_exists('cleg_admin_selected_status')) {
    function cleg_admin_selected_status() {
        $status = isset($_GET['cleg_status']) ? sanitize_text_field(wp_unslash($_GET['cleg_status'])) : 'pending';
        return in_array($status, array('pending', 'manual', 'approved', 'open', 'deleted', 'closed'), true) ? $status : 'pending';
    }
}

if (!function_exists('cleg_admin_formula_and')) {
    function cleg_admin_formula_and($parts) {
        $clean = array();
        foreach ((array) $parts as $part) {
            if (is_string($part) && trim($part) !== '') {
                $clean[] = trim($part);
            }
        }

        if (empty($clean)) {
            return '';
        }

        return count($clean) === 1 ? $clean[0] : 'AND(' . implode(',', $clean) . ')';
    }
}

if (!function_exists('cleg_admin_audit_line')) {
    function cleg_admin_audit_line($actor, $label, $old, $new, $reason = '') {
        $line = '[' . wp_date('m/d/Y g:i A') . '] ' . $actor . ' - ' . $label . ': ' . (string) ($old !== '' ? $old : '--') . ' -> ' . (string) ($new !== '' ? $new : '--');
        if ($reason !== '') {
            $line .= ' | Motivo: ' . $reason;
        }
        return $line;
    }
}

if (!function_exists('cleg_admin_hr_request_by_id')) {
    function cleg_admin_hr_request_by_id($record_id) {
        $records = cleg_admin_records(CLEG_AIRTABLE_HR_REQUESTS_TABLE, array(
            'pageSize' => 1,
            'filterByFormula' => "RECORD_ID()='" . cleg_admin_formula_text($record_id) . "'",
        ));
        if (is_wp_error($records)) {
            return $records;
        }
        return $records[0] ?? array();
    }
}

if (!function_exists('cleg_admin_portal_audit')) {
    function cleg_admin_portal_audit($event_type, $related_table, $record_id, $employee, $username, $before, $after, $reason = '') {
        $user = wp_get_current_user();
        $actor = $user && $user->exists() ? ($user->display_name ?: $user->user_login) : 'Sistema';
        $ip = isset($_SERVER['REMOTE_ADDR']) ? sanitize_text_field(wp_unslash($_SERVER['REMOTE_ADDR'])) : '';

        return cleg_admin_request('POST', CLEG_AIRTABLE_AUDIT_TABLE, array(
            'body' => array(
                'records' => array(array(
                    'fields' => array(
                        'Event Time' => current_time('c'),
                        'Actor' => $actor,
                        'Actor WP User ID' => $user && $user->exists() ? (string) $user->ID : '',
                        'Event Type' => $event_type,
                        'Related Table' => $related_table,
                        'Related Record ID' => $record_id,
                        'Employee Name' => $employee,
                        'Portal Username' => $username,
                        'Before Value' => $before,
                        'After Value' => $after,
                        'Reason' => $reason,
                        'IP Address' => $ip,
                    ),
                )),
                'typecast' => true,
            ),
        ));
    }
}

if (!function_exists('cleg_admin_record_by_id')) {
    function cleg_admin_record_by_id($record_id) {
        $records = cleg_admin_time_records("RECORD_ID()='" . cleg_admin_formula_text($record_id) . "'", 1);
        if (is_wp_error($records)) {
            return $records;
        }
        return $records[0] ?? array();
    }
}

if (!function_exists('cleg_admin_module_for_active')) {
    function cleg_admin_module_for_active($active = '') {
        $map = array(
            'dashboard' => 'rrhh',
            'employees' => 'rrhh',
            'requests' => 'rrhh',
            'horas' => 'field',
            'live' => 'field',
            'devices' => 'field',
            'payroll' => 'field',
            'payroll-reports' => 'field',
            'jobs' => 'projects',
            'receipts' => 'procurement',
            'tenant-admin' => 'tenant',
        );

        return $map[$active] ?? 'rrhh';
    }
}

if (!function_exists('cleg_admin_module_eyebrow')) {
    function cleg_admin_module_eyebrow($active = '') {
        $labels = array(
            'rrhh' => 'Vantrexor RRHH',
            'field' => 'Vantrexor Campo',
            'projects' => 'Vantrexor Proyectos',
            'payroll' => 'Vantrexor Payroll',
            'procurement' => 'Vantrexor Compras',
            'tenant' => 'Vantrexor Administracion',
        );
        $module = cleg_admin_module_for_active($active);

        return $labels[$module] ?? 'Vantrexor Portal';
    }
}

if (!function_exists('cleg_admin_module_nav_items')) {
    function cleg_admin_module_nav_items($active = '') {
        $module = cleg_admin_module_for_active($active);

        if ($module === 'field') {
            return array(
                'horas' => array('Revision de horas', home_url('/admin-horas/')),
                'live' => array('Tiempo real', home_url('/admin-tiempo-real/')),
                'devices' => array('Dispositivos', home_url('/admin-dispositivos/')),
                'payroll' => array('Payroll', home_url('/payroll-rrhh/')),
                'payroll-reports' => array('Reportes payroll', home_url('/payroll-reportes/')),
            );
        }

        if ($module === 'projects') {
            return array(
                'jobs' => array('Proyectos', home_url('/admin-job-sites/')),
            );
        }

        if ($module === 'payroll') {
            return array(
                'payroll' => array('Payroll', home_url('/payroll-rrhh/')),
            );
        }

        if ($module === 'procurement') {
            return array(
                'procurement' => array('Compras', home_url('/admin-procurement/')),
                'receipts' => array('Recibos', home_url('/admin-recibos/')),
            );
        }

        if ($module === 'tenant') {
            return array(
                'tenant-admin' => array('Administracion', function_exists('cleg_tenant_admin_tab_url') ? cleg_tenant_admin_tab_url('overview') : home_url('/administracion/')),
            );
        }

        return array(
            'dashboard' => array('Control RRHH', home_url('/admin-rrhh/')),
            'employees' => array('Trabajadores', home_url('/admin-empleados/')),
            'requests' => array('Solicitudes', home_url('/admin-solicitudes/')),
        );
    }
}

if (!function_exists('cleg_admin_nav_item_module')) {
    function cleg_admin_nav_item_module($key) {
        $map = array(
            'dashboard' => 'hr_core',
            'employees' => 'hr_core',
            'requests' => 'forms_requests',
            'horas' => 'field_ops',
            'live' => 'field_ops',
            'devices' => 'field_ops',
            'jobs' => 'projects_work_orders',
            'payroll' => 'payroll',
            'payroll-reports' => 'payroll',
            'procurement' => 'procurement_quotes',
            'receipts' => 'procurement_quotes',
            'tenant-admin' => 'tenant_admin',
        );

        $key = sanitize_key((string) $key);

        return $map[$key] ?? '';
    }
}

if (!function_exists('cleg_admin_nav_module_enabled')) {
    function cleg_admin_nav_module_enabled($module_key) {
        $module_key = sanitize_key((string) $module_key);
        if ($module_key === '') {
            return true;
        }

        if (function_exists('cleg_saas_module_enabled')) {
            return (bool) cleg_saas_module_enabled($module_key);
        }

        if (function_exists('cleg_shell_module_enabled')) {
            return (bool) cleg_shell_module_enabled($module_key);
        }

        return true;
    }
}

if (!function_exists('cleg_admin_filter_nav_items')) {
    function cleg_admin_filter_nav_items($items) {
        foreach ($items as $key => $item) {
            $module_key = cleg_admin_nav_item_module($key);
            if ($module_key !== '' && !cleg_admin_nav_module_enabled($module_key)) {
                unset($items[$key]);
            }
        }

        return $items;
    }
}

if (!function_exists('cleg_admin_nav')) {
    function cleg_admin_nav($active = '') {
        $module = cleg_admin_module_for_active($active);
        $items = cleg_admin_filter_nav_items(cleg_admin_module_nav_items($active));
        $utility_items = array(
            'panel' => array('Panel', home_url('/panel/'), 'is-panel-link'),
            'logout' => array('Cerrar sesion', wp_logout_url(home_url('/acceso/')), 'is-logout'),
        );

        $can_view_payroll = function_exists('cleg_payroll_can_view')
            ? cleg_payroll_can_view()
            : (current_user_can('cleg_view_payroll') || current_user_can('cleg_manage_payroll') || current_user_can('manage_options'));
        if (!$can_view_payroll) {
            unset($items['payroll']);
        }

        $module_labels = array(
            'rrhh' => 'RRHH',
            'field' => 'Campo',
            'projects' => 'Proyectos',
            'payroll' => 'Payroll',
            'procurement' => 'Compras',
        );
        $active_label = isset($items[$active]) ? $items[$active][0] : ($module_labels[$module] ?? 'Modulo');
        $mobile_items = $items;

        $task_items = array(
            'horas' => array('Horas', home_url('/admin-horas/'), 'field_ops'),
            'requests' => array('Solicitudes', home_url('/admin-solicitudes/'), 'forms_requests'),
            'procurement' => array('Compras', home_url('/admin-procurement/'), 'procurement_quotes'),
        );
        $mobile = '<details class="cleg-admin-mobile-menu cleg-admin-task-menu"><summary><span>Tareas</span><b>Menu</b></summary><div>';
        foreach ($task_items as $key => $task) {
            if (!cleg_admin_nav_module_enabled($task[2])) {
                continue;
            }
            $task_active = ($key === 'horas' && $module === 'field')
                || ($key === 'requests' && $module === 'rrhh')
                || ($key === 'procurement' && $module === 'procurement');
            $mobile .= '<a class="' . esc_attr($task_active ? 'is-active' : '') . '" href="' . esc_url($task[1]) . '">' . esc_html($task[0]) . '</a>';
        }
        $mobile .= '<span class="cleg-admin-task-more-label">Más</span>';
        foreach ($mobile_items as $key => $item) {
            $mobile .= '<a class="' . esc_attr($key === $active ? 'is-active' : '') . '" href="' . esc_url($item[1]) . '">' . esc_html($item[0]) . '</a>';
        }
        foreach ($utility_items as $item) {
            $mobile .= '<a class="' . esc_attr($item[2]) . '" href="' . esc_url($item[1]) . '">' . esc_html($item[0]) . '</a>';
        }
        $mobile .= '</div></details>';

        $html = $mobile . '<nav class="cleg-admin-nav cleg-admin-nav-' . esc_attr($module) . '" aria-label="Navegacion de modulo ' . esc_attr($module_labels[$module] ?? 'administrativo') . '">';

        foreach ($items as $key => $item) {
            $html .= '<a class="' . esc_attr($key === $active ? 'is-active' : '') . '" href="' . esc_url($item[1]) . '">' . esc_html($item[0]) . '</a>';
        }
        foreach ($utility_items as $item) {
            $html .= '<a class="' . esc_attr($item[2]) . '" href="' . esc_url($item[1]) . '">' . esc_html($item[0]) . '</a>';
        }

        return $html . '</nav>';
    }
}

if (!function_exists('cleg_admin_page_open')) {
    function cleg_admin_page_open($active, $title, $subtitle = '') {
        $gate = cleg_admin_gate();

        if ($gate !== '') {
            return $gate;
        }

        $notice = isset($_GET['cleg_admin_error']) ? sanitize_text_field(wp_unslash($_GET['cleg_admin_error'])) : '';
        $approved_id = isset($_GET['cleg_approved']) ? sanitize_text_field(wp_unslash($_GET['cleg_approved'])) : '';
        $saved = isset($_GET['cleg_saved']) ? sanitize_text_field(wp_unslash($_GET['cleg_saved'])) : '';
        $blocked = isset($_GET['cleg_blocked']) ? absint($_GET['cleg_blocked']) : 0;
        $undone = isset($_GET['cleg_undone']) ? sanitize_text_field(wp_unslash($_GET['cleg_undone'])) : '';
        $manual_created = isset($_GET['cleg_manual_created']) ? absint($_GET['cleg_manual_created']) : 0;
        $success_notice = '';

        if ($approved_id !== '') {
            $success_notice = '<div class="cleg-admin-notice is-success cleg-undo-toast"><strong>Horas aprobadas</strong><form method="post">'
                . wp_nonce_field('cleg_admin_time_action', 'cleg_admin_nonce', true, false)
                . '<input type="hidden" name="cleg_admin_record_id" value="' . esc_attr($approved_id) . '">'
                . '<button type="submit" name="cleg_admin_action" value="undo_approval">Deshacer</button>'
                . '</form></div>';
        } elseif ($undone !== '') {
            $success_notice = '<div class="cleg-admin-notice is-success"><strong>Aprobacion deshecha.</strong></div>';
        } elseif ($manual_created === 1) {
            $success_notice = '<div class="cleg-admin-notice is-success"><strong>Jornada manual creada para revision.</strong><span>Debe aprobarse antes de aparecer en Payroll. Payroll solo muestra jornadas con estado Approved.</span></div>';
        } elseif ($saved !== '') {
            $success_notice = '<div class="cleg-admin-notice is-success"><strong>Cambios guardados.</strong>' . ($blocked > 0 ? '<span>' . esc_html($blocked) . ' fila(s) no se procesaron por faltar Job Site, salida o permiso.</span>' : '') . '</div>';
        }

        return cleg_admin_desktop_menu_lock_styles() . '<section class="cleg-admin-ui"><main class="cleg-admin-main cleg-admin-shell">'
            . cleg_admin_page_header($title, $subtitle, array('eyebrow' => cleg_admin_module_eyebrow($active)))
            . ($notice !== '' ? '<div class="cleg-admin-notice is-error">' . esc_html($notice) . '</div>' : '')
            . $success_notice
            . cleg_admin_nav($active);
    }
}

if (!function_exists('cleg_admin_page_header')) {
    function cleg_admin_page_header($title, $subtitle = '', $attention = array()) {
        $value = isset($attention['value']) ? (string) $attention['value'] : '';
        $label = isset($attention['label']) ? (string) $attention['label'] : '';
        $detail = isset($attention['detail']) ? (string) $attention['detail'] : '';
        $state = isset($attention['state']) ? sanitize_html_class((string) $attention['state']) : '';
        $class = trim('cleg-admin-header cleg-command-center ' . $state);

        $eyebrow = isset($attention['eyebrow']) ? (string) $attention['eyebrow'] : 'Vantrexor';
        $brand_mark = function_exists('cleg_vantrexor_logo_markup')
            ? cleg_vantrexor_logo_markup('mark')
            : '<span class="cleg-vantrexor-mark" aria-label="Vantrexor"><span aria-hidden="true">V</span></span>';
        $html = '<header class="' . esc_attr($class) . '"><div class="cleg-command-copy"><div class="cleg-app-brand-block">' . $brand_mark . '<p class="cleg-app-kicker">' . esc_html($eyebrow) . '</p></div><h1>' . esc_html($title) . '</h1>' . ($subtitle !== '' ? '<span>' . esc_html($subtitle) . '</span>' : '') . '</div>';

        if ($value !== '' || $label !== '' || $detail !== '') {
            $html .= '<div class="cleg-command-score"><span>' . esc_html($label) . '</span><strong>' . esc_html($value) . '</strong><small>' . esc_html($detail) . '</small></div>';
        }

        return $html . '</header>';
    }
}

if (!function_exists('cleg_admin_page_close')) {
    function cleg_admin_page_close() {
        return '</main>' . cleg_admin_review_memory_script() . '</section>';
    }
}

