if (!function_exists('cleg_admin_status_pill')) {
    function cleg_admin_status_pill($status) {
        $class = 'is-neutral';
        if ($status === 'Approved') {
            $class = 'is-ok';
        } elseif ($status === 'Pending Review' || $status === 'Open' || $status === 'Manual Need Review') {
            $class = 'is-warn';
        } elseif ($status === 'Rejected' || $status === 'Deleted') {
            $class = 'is-bad';
        } elseif ($status === 'Payroll Closed') {
            $class = 'is-neutral';
        }

        return '<span class="cleg-pill ' . esc_attr($class) . '">' . esc_html($status ?: '--') . '</span>';
    }
}

if (!function_exists('cleg_admin_meters_to_miles_label')) {
    function cleg_admin_meters_to_miles_label($meters) {
        if ($meters === '' || $meters === null) {
            return '';
        }
        $meters = preg_replace('/[^0-9\.\-]/', '', (string) $meters);
        if ($meters === '' || !is_numeric($meters)) {
            return '';
        }
        $miles = ((float) $meters) / 1609.344;
        return number_format($miles, 2) . ' millas';
    }
}

if (!function_exists('cleg_admin_geofence_is_clear')) {
    function cleg_admin_geofence_is_clear($record) {
        $in_map = cleg_admin_field($record, 'Clock In Map Link');
        $out_map = cleg_admin_field($record, 'Clock Out Map Link');
        $flags = cleg_admin_field($record, 'Audit Flags');
        $reason = cleg_admin_field($record, 'GPS Review Reason');

        if ($in_map === '' || $out_map === '') {
            return false;
        }

        if (cleg_admin_field($record, 'Clock In Outside Geofence') !== '' || cleg_admin_field($record, 'Clock Out Outside Geofence') !== '') {
            return false;
        }

        return strpos($flags, 'Outside Geofence') === false
            && strpos($reason, 'Outside Geofence') === false
            && strpos($flags, 'Missing GPS') === false
            && strpos($reason, 'Missing GPS') === false;
    }
}

if (!function_exists('cleg_admin_error')) {
    function cleg_admin_error() {
        $messages = array();
        foreach (func_get_args() as $error) {
            if (is_wp_error($error)) {
                $messages[] = $error->get_error_message();
            }
        }

        return '<div class="cleg-admin-empty"><h2>No se pudo leer Airtable</h2><p>' . esc_html(implode(' ', $messages) ?: 'Verifica token y permisos.') . '</p></div>';
    }
}

if (!function_exists('cleg_admin_recent_table')) {
    function cleg_admin_recent_table($records, $limit = 10) {
        $records = array_slice($records, 0, $limit);
        $html = '<div class="cleg-panel"><h2>Actividad reciente</h2><div class="cleg-table-wrap"><table><thead><tr><th>Empleado</th><th>Job Site</th><th>Entrada</th><th>Salida</th><th>Status</th><th>Alertas</th></tr></thead><tbody>';

        foreach ($records as $record) {
            $html .= '<tr><td>' . esc_html(cleg_admin_field($record, 'Employee Name')) . '</td><td>' . esc_html(cleg_admin_field($record, 'Job Site Name')) . '</td><td>' . esc_html(cleg_admin_date(cleg_admin_field($record, 'Clock In Time'))) . '</td><td>' . esc_html(cleg_admin_date(cleg_admin_field($record, 'Clock Out Time'))) . '</td><td>' . cleg_admin_status_pill(cleg_admin_field($record, 'Approval Status')) . '</td><td>' . esc_html(cleg_admin_field($record, 'Audit Flags', '--')) . '</td></tr>';
        }

        return $html . '</tbody></table></div></div>';
    }
}

if (!function_exists('cleg_admin_context_hours_panel')) {
    function cleg_admin_context_hours_panel($title, $records, $job_sites = array(), $back_url = '') {
        $today_closed_hours = 0;
        $today_open_hours = 0;
        $week_hours = 0;
        $month_hours = 0;
        $cost_hours = 0;
        $open_today_count = 0;
        $closed_today_count = 0;
        $employee_hours = array();
        $now = new DateTime('now', new DateTimeZone('America/Puerto_Rico'));
        $today_key = $now->format('Y-m-d');
        $week_key = $now->format('o-W');
        $month_key = $now->format('Y-m');
        $live_rows = array();

        foreach ((array) $records as $record) {
            $status = cleg_admin_field($record, 'Approval Status');
            if (in_array($status, array('Rejected', 'Deleted', 'Payroll Closed'), true)) {
                continue;
            }

            $clock_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
            $clock_out = cleg_admin_field($record, 'Admin Adjusted Clock Out Time') ?: cleg_admin_field($record, 'Worker Reported Clock Out Time') ?: cleg_admin_field($record, 'Clock Out Time');
            $effective_out = $clock_out !== '' ? $clock_out : $now->format('Y-m-d H:i:s');
            $hours = cleg_admin_hours_float($clock_in, $effective_out);
            $cost_hours += $hours;

            $dt = cleg_admin_pr_datetime($clock_in);
            if ($dt) {
                if ($dt->format('Y-m-d') === $today_key) {
                    if ($clock_out === '') {
                        $today_open_hours += $hours;
                        $open_today_count++;
                        $live_rows[] = array('id' => sanitize_text_field($record['id'] ?? ''), 'start' => $dt->getTimestamp(), 'base' => 0);
                    } else {
                        $today_closed_hours += $hours;
                        $closed_today_count++;
                    }
                }
                if ($dt->format('o-W') === $week_key) {
                    $week_hours += $hours;
                }
                if ($dt->format('Y-m') === $month_key) {
                    $month_hours += $hours;
                }
            }

            $employee = cleg_admin_field($record, 'Employee Name', cleg_admin_field($record, 'Portal Username', 'Sin empleado'));
            $employee_hours[$employee] = ($employee_hours[$employee] ?? 0) + $hours;
        }

        $today_total = $today_closed_hours + $today_open_hours;
        $today_closed_minutes = (int) round($today_closed_hours * 60);
        $html = '<div class="cleg-context-head"><div><span>Consulta de proyecto</span><h2>' . esc_html($title) . '</h2></div>' . ($back_url !== '' ? '<a href="' . esc_url($back_url) . '">Volver a proyectos</a>' : '') . '</div>';
        $html .= '<div class="cleg-metrics-grid cleg-metrics-grid-compact cleg-project-readonly-metrics">'
            . '<div class="cleg-metric"><strong data-cleg-live-total="1" data-closed-minutes="' . esc_attr((string) $today_closed_minutes) . '">' . esc_html(cleg_admin_hours_label($today_total)) . '</strong><span>Horas hoy</span><small>' . esc_html($open_today_count . ' abierta(s) / ' . $closed_today_count . ' cerrada(s)') . '</small></div>'
            . cleg_admin_metric_card('Horas semana', cleg_admin_hours_label($week_hours), 'aprobadas, revision y abiertas')
            . cleg_admin_metric_card('Horas mes', cleg_admin_hours_label($month_hours), 'base operacional')
            . cleg_admin_metric_card('Horas para costo', cleg_admin_hours_label($cost_hours), 'excluye deleted, rejected y payroll closed')
            . '</div>';
        if (!empty($employee_hours)) {
            $html .= '<div class="cleg-admin-grid cleg-project-readonly-grid">'
                . cleg_admin_bar_chart('Horas por empleado', $employee_hours)
                . '</div>';
        }
        $html .= '<style>
body .cleg-admin-ui .cleg-readonly-hours-list{display:grid!important;gap:10px!important}
body .cleg-admin-ui .cleg-readonly-hour-row{display:grid!important;grid-template-columns:minmax(180px,1.25fr) repeat(4,minmax(120px,1fr))!important;gap:10px!important;align-items:center!important;text-align:center!important}
body .cleg-admin-ui .cleg-readonly-hour-row>div{min-width:0!important;max-width:100%!important;overflow:hidden!important;text-align:center!important}
body .cleg-admin-ui .cleg-readonly-hour-row :where(strong,b,small,span){display:block!important;max-width:100%!important;overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important;text-align:center!important}
@media(max-width:900px){body .cleg-admin-ui .cleg-readonly-hour-row{grid-template-columns:1fr 1fr!important}}
</style>';
        $html .= '<div class="cleg-panel cleg-project-hours-readonly" id="cleg-horas"><div class="cleg-panel-head"><div><h2>Horas relacionadas</h2></div></div>';
        $html .= cleg_admin_readonly_hours_list($records);
        $html .= '</div>';

        if (!empty($live_rows)) {
            $html .= '<script>(function(){var rows=' . wp_json_encode($live_rows) . ';function labelMinutes(total){total=Math.max(0,Math.round(total));var h=Math.floor(total/60);var m=total%60;return h+"h:"+String(m).padStart(2,"0")+"m";}function tick(){var now=Math.floor(Date.now()/1000);document.querySelectorAll("[data-cleg-live-entry]").forEach(function(el){var start=parseInt(el.getAttribute("data-start"),10);if(start){el.textContent=labelMinutes((now-start)/60);}});document.querySelectorAll("[data-cleg-live-total]").forEach(function(el){var total=parseInt(el.getAttribute("data-closed-minutes"),10)||0;rows.forEach(function(row){if(row.start){total+=(now-row.start)/60;}});el.textContent=labelMinutes(total);});}tick();setInterval(tick,60000);})();</script>';
        }

        return $html;
    }
}

if (!function_exists('cleg_admin_readonly_hours_list')) {
    function cleg_admin_readonly_hours_list($records) {
        $html = '<div class="cleg-readonly-hours-list">';
        foreach ((array) $records as $record) {
            $status = cleg_admin_field($record, 'Approval Status');
            if (in_array($status, array('Rejected', 'Deleted', 'Payroll Closed'), true)) {
                continue;
            }
            $clock_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
            $clock_out = cleg_admin_field($record, 'Admin Adjusted Clock Out Time') ?: cleg_admin_field($record, 'Worker Reported Clock Out Time') ?: cleg_admin_field($record, 'Clock Out Time');
            $employee = cleg_admin_field($record, 'Employee Name', cleg_admin_field($record, 'Portal Username', 'Sin empleado'));
            $project = cleg_admin_field($record, 'Job Site Name', 'Sin proyecto');
            $dt = cleg_admin_pr_datetime($clock_in);
            $hours_label = $clock_out !== '' ? cleg_admin_hours($clock_in, $clock_out) : '<span data-cleg-live-entry="1" data-start="' . esc_attr($dt ? $dt->getTimestamp() : '') . '">' . esc_html(cleg_admin_hours($clock_in, current_time('mysql'))) . '</span>';
            $status_label = $clock_out === '' ? 'Abierta' : ($status ?: 'Sin estado');
            $html .= '<article class="cleg-readonly-hour-row">'
                . '<div><strong>' . esc_html($employee) . '</strong><small>' . esc_html($project) . '</small></div>'
                . '<div><span>Entrada</span><b>' . esc_html(cleg_admin_date($clock_in)) . '</b></div>'
                . '<div><span>Salida</span><b>' . esc_html($clock_out !== '' ? cleg_admin_date($clock_out) : 'Abierta') . '</b></div>'
                . '<div><span>Horas</span><b>' . wp_kses_post($hours_label) . '</b></div>'
                . '<div>' . cleg_admin_status_pill($status_label) . '</div>'
                . '</article>';
        }
        if ($html === '<div class="cleg-readonly-hours-list">') {
            $html .= '<div class="cleg-admin-empty"><h2>Sin horas relacionadas</h2><p>No hay registros activos, aprobados o en revision para este proyecto.</p></div>';
        }
        return $html . '</div>';
    }
}

if (!function_exists('cleg_admin_mobile_flags')) {
    function cleg_admin_mobile_flags($record) {
        $badges = array();
        $flags = cleg_admin_field($record, 'Audit Flags');
        $reason = cleg_admin_field($record, 'GPS Review Reason');

        if (cleg_admin_field($record, 'Clock Out Time') === '') {
            $badges[] = '<span class="cleg-pill is-warn">Abierta</span>';
        }

        if (cleg_admin_field($record, 'Worker Manual Clock Out Requested') !== '') {
            $badges[] = '<span class="cleg-pill is-warn">Olvido salida</span>';
        }

        if (strpos($flags, 'Outside Geofence') !== false || strpos($reason, 'Outside Geofence') !== false) {
            $badges[] = '<span class="cleg-pill is-bad">Fuera de zona</span>';
        }

        if (strpos($flags, 'Missing GPS') !== false) {
            $badges[] = '<span class="cleg-pill is-bad">Sin GPS</span>';
        }

        if (strpos($flags, 'Shared Device Detected') !== false) {
            $badges[] = '<span class="cleg-pill is-warn">Movil compartido</span>';
        }

        return implode('', $badges);
    }
}

if (!function_exists('cleg_admin_mobile_map_button')) {
    function cleg_admin_mobile_map_button($record) {
        $map = cleg_admin_field($record, 'Clock In Map Link') ?: cleg_admin_field($record, 'Clock Out Map Link');

        if ($map === '') {
            return '<span class="cleg-mobile-muted">GPS no disponible</span>';
        }

        return '<a class="cleg-mobile-map" href="' . esc_url($map) . '" target="_blank" rel="noopener">Abrir GPS</a>';
    }
}

if (!function_exists('cleg_admin_mobile_action_form')) {
    function cleg_admin_mobile_action_form($record_id, $action, $label, $class = '') {
        return '<form class="cleg-mobile-action-form" method="post">'
            . wp_nonce_field('cleg_admin_time_action', 'cleg_admin_nonce', true, false)
            . '<input type="hidden" name="cleg_admin_record_id" value="' . esc_attr($record_id) . '">'
            . '<button class="' . esc_attr($class) . '" type="submit" name="cleg_admin_action" value="' . esc_attr($action) . '">' . esc_html($label) . '</button>'
            . '</form>';
    }
}
