/**
 * CLEG HR Core Data Access v0.1
 *
 * Puerta de datos del modulo HR Core. Mantiene compatibilidad con el core admin
 * mientras la configuracion final por tenant/modulo se migra a Integrations Layer.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_hr_core_request')) {
    function cleg_hr_core_request($method, $table, $args = array()) {
        $module_key = 'hr_core';
        if (defined('CLEG_AIRTABLE_TAX_PROFILES_TABLE') && $table === CLEG_AIRTABLE_TAX_PROFILES_TABLE) {
            $module_key = 'payroll';
        }

        if (function_exists('cleg_integrations_airtable_request')) {
            $query = (!empty($args['query']) && is_array($args['query'])) ? $args['query'] : array();
            $body = !empty($args['body']) ? $args['body'] : null;
            if (!empty($args['record_id'])) {
                $query['record_id'] = sanitize_text_field((string) $args['record_id']);
            }

            return cleg_integrations_airtable_request($module_key, $method, $table, $query, $body);
        }

        if (function_exists('cleg_admin_request')) {
            return cleg_admin_request($method, $table, $args);
        }

        return new WP_Error('cleg_hr_core_data_unavailable', 'HR Core no tiene acceso de datos configurado.');
    }
}

if (!function_exists('cleg_hr_core_records')) {
    function cleg_hr_core_records($table, $query = array()) {
        $module_key = 'hr_core';
        if (defined('CLEG_AIRTABLE_TAX_PROFILES_TABLE') && $table === CLEG_AIRTABLE_TAX_PROFILES_TABLE) {
            $module_key = 'payroll';
        }

        if (function_exists('cleg_integrations_airtable_records')) {
            return cleg_integrations_airtable_records($module_key, $table, $query);
        }

        if (function_exists('cleg_admin_records')) {
            return cleg_admin_records($table, $query);
        }

        return new WP_Error('cleg_hr_core_records_unavailable', 'HR Core no puede leer registros.');
    }
}

if (!function_exists('cleg_hr_get_employee_profile')) {
    function cleg_hr_get_employee_profile($employee_id, $tenant_key = '') {
        if (!defined('CLEG_AIRTABLE_EMPLOYEES_TABLE')) {
            return new WP_Error('cleg_hr_employee_table_missing', 'HR Core no tiene tabla de empleados configurada.');
        }

        $employee_id = sanitize_text_field((string) $employee_id);
        if ($employee_id === '') {
            return new WP_Error('cleg_hr_employee_missing', 'Falta el empleado solicitado.');
        }

        $formula = "OR(RECORD_ID()='" . str_replace("'", "\\'", $employee_id) . "',{Portal Username}='" . str_replace("'", "\\'", $employee_id) . "')";
        if ($tenant_key !== '') {
            $formula = 'AND(' . $formula . ",{Tenant Key}='" . str_replace("'", "\\'", sanitize_key((string) $tenant_key)) . "')";
        }

        $records = cleg_hr_core_records(CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'filterByFormula' => $formula,
            'maxRecords' => 1,
        ));

        if (is_wp_error($records)) {
            return $records;
        }

        return !empty($records[0]) ? $records[0] : new WP_Error('cleg_hr_employee_not_found', 'Empleado no encontrado.');
    }
}

if (!function_exists('cleg_payroll_get_tax_profiles')) {
    function cleg_payroll_get_tax_profiles($tenant_key = '') {
        if (!defined('CLEG_AIRTABLE_TAX_PROFILES_TABLE')) {
            return new WP_Error('cleg_payroll_tax_profiles_missing', 'Payroll no tiene tabla de Tax Profiles configurada.');
        }

        $query = array();
        if ($tenant_key !== '') {
            $query['filterByFormula'] = "{Tenant Key}='" . str_replace("'", "\\'", sanitize_key((string) $tenant_key)) . "'";
        }

        return cleg_hr_core_records(CLEG_AIRTABLE_TAX_PROFILES_TABLE, $query);
    }
}

if (!function_exists('cleg_hr_get_leave_balance')) {
    function cleg_hr_get_leave_balance($employee_id, $tenant_key = '') {
        if (!defined('CLEG_AIRTABLE_LEAVE_LEDGER_TABLE')) {
            return new WP_Error('cleg_hr_leave_ledger_missing', 'HR Core no tiene tabla de Leave Ledger configurada.');
        }

        $employee_id = sanitize_text_field((string) $employee_id);
        if ($employee_id === '') {
            return new WP_Error('cleg_hr_employee_missing', 'Falta el empleado solicitado.');
        }

        $formula = "{Employee ID}='" . str_replace("'", "\\'", $employee_id) . "'";
        if ($tenant_key !== '') {
            $formula = 'AND(' . $formula . ",{Tenant Key}='" . str_replace("'", "\\'", sanitize_key((string) $tenant_key)) . "')";
        }

        return cleg_hr_core_records(CLEG_AIRTABLE_LEAVE_LEDGER_TABLE, array(
            'filterByFormula' => $formula,
            'maxRecords' => 200,
        ));
    }
}

if (!function_exists('cleg_hr_get_approved_leave_for_period')) {
    function cleg_hr_get_approved_leave_for_period($employee_id, $period = array(), $tenant_key = '') {
        if (!defined('CLEG_AIRTABLE_LEAVE_LEDGER_TABLE')) {
            return new WP_Error('cleg_hr_leave_ledger_missing', 'HR Core no tiene tabla de Leave Ledger configurada.');
        }

        $employee_id = sanitize_text_field((string) $employee_id);
        if ($employee_id === '') {
            return new WP_Error('cleg_hr_employee_missing', 'Falta el empleado solicitado.');
        }

        $start = !empty($period['start']) ? sanitize_text_field((string) $period['start']) : '';
        $end = !empty($period['end']) ? sanitize_text_field((string) $period['end']) : '';

        $parts = array(
            "{Employee ID}='" . str_replace("'", "\\'", $employee_id) . "'",
            "{Status}='Approved'",
        );
        if ($tenant_key !== '') {
            $parts[] = "{Tenant Key}='" . str_replace("'", "\\'", sanitize_key((string) $tenant_key)) . "'";
        }
        if ($start !== '') {
            $parts[] = "IS_AFTER({Leave Date}, '" . str_replace("'", "\\'", $start) . "')";
        }
        if ($end !== '') {
            $parts[] = "IS_BEFORE({Leave Date}, '" . str_replace("'", "\\'", $end) . "')";
        }

        return cleg_hr_core_records(CLEG_AIRTABLE_LEAVE_LEDGER_TABLE, array(
            'filterByFormula' => 'AND(' . implode(',', $parts) . ')',
            'maxRecords' => 200,
        ));
    }
}
