if (!function_exists('cleg_field_ops_employee_can_approve_hours')) {
    function cleg_field_ops_employee_can_approve_hours($user_id = 0) {
        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        $user = $user_id > 0 ? get_user_by('id', $user_id) : false;
        if (!$user instanceof WP_User) {
            return false;
        }

        $cache_key = 'cleg_field_ops_emp_can_approve_' . $user_id;
        $cached = get_transient($cache_key);
        if ($cached === 'yes') {
            return true;
        }
        if ($cached === 'no') {
            return false;
        }

        $parts = array('{WordPress User ID}=' . (int) $user->ID);
        if (!empty($user->user_login)) {
            $parts[] = "{Portal Username}='" . str_replace("'", "\\'", sanitize_user($user->user_login)) . "'";
        }
        if (!empty($user->user_email)) {
            $parts[] = "LOWER({Email})=LOWER('" . str_replace("'", "\\'", sanitize_email($user->user_email)) . "')";
        }

        $formula = count($parts) > 1 ? 'OR(' . implode(',', $parts) . ')' : $parts[0];
        $employee_table = defined('CLEG_AIRTABLE_EMPLOYEES_TABLE') ? CLEG_AIRTABLE_EMPLOYEES_TABLE : 'Employees';
        $records = cleg_field_ops_records($employee_table, array(
            'pageSize' => 1,
            'filterByFormula' => $formula,
        ));

        if (is_wp_error($records) && function_exists('cleg_admin_records')) {
            $records = cleg_admin_records($employee_table, array(
                'pageSize' => 1,
                'filterByFormula' => $formula,
            ));
        }

        $can_approve = false;
        if (!is_wp_error($records) && !empty($records[0]['fields']) && is_array($records[0]['fields'])) {
            $fields = $records[0]['fields'];
            $can_approve = !empty($fields['Can Approve Hours']);
        }

        set_transient($cache_key, $can_approve ? 'yes' : 'no', 5 * MINUTE_IN_SECONDS);
        return $can_approve;
    }
}

if (!function_exists('cleg_field_ops_user_has_any_cap')) {
    function cleg_field_ops_user_has_any_cap($user_id, array $caps) {
        foreach ($caps as $cap) {
            if (user_can($user_id, $cap)) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg_field_ops_user_can_review_hours')) {
    function cleg_field_ops_user_can_review_hours($user_id = 0, $tenant_key = '') {
        if (!cleg_field_ops_module_enabled($tenant_key)) {
            return false;
        }

        $user_id = $user_id ? (int) $user_id : get_current_user_id();
        if ($user_id <= 0) {
            return false;
        }

        if (cleg_field_ops_user_has_any_cap($user_id, array(
            'manage_options',
            'edit_pages',
            'cleg_technical_full_access',
            'cleg_manage_tenant',
            'cleg_manage_rrhh',
            'cleg_access_rrhh',
            'cleg_view_field_attendance',
            'cleg_review_hours',
            'cleg_approve_hours',
            'cleg_correct_hours',
        ))) {
            return true;
        }

        return cleg_field_ops_employee_can_approve_hours($user_id);
    }
}

