if (!function_exists('cleg_field_ops_get_time_entries')) {
    function cleg_field_ops_get_time_entries($filters = array()) {
        if (!defined('CLEG_AIRTABLE_TIME_TABLE')) {
            return new WP_Error('cleg_field_ops_time_table_missing', 'Field Ops no tiene tabla de horas configurada.');
        }

        if (!cleg_field_ops_can_view_live_ops()) {
            return new WP_Error('cleg_field_ops_forbidden', 'No tienes permiso para ver operaciones de campo.');
        }

        $query = array();
        if (!empty($filters['formula'])) {
            $query['filterByFormula'] = (string) $filters['formula'];
        }
        if (!empty($filters['max_records'])) {
            $query['maxRecords'] = max(1, min(500, (int) $filters['max_records']));
        }
        if (!empty($filters['sort']) && is_array($filters['sort'])) {
            $query['sort'] = $filters['sort'];
        }

        return cleg_field_ops_records(CLEG_AIRTABLE_TIME_TABLE, $query);
    }
}

if (!function_exists('cleg_field_ops_open_shift_formula')) {
    function cleg_field_ops_open_shift_formula() {
        return "{Clock Out Time}=BLANK()";
    }
}

if (!function_exists('cleg_field_ops_device_formula')) {
    function cleg_field_ops_device_formula() {
        return "{Device ID}!=''";
    }
}

if (!function_exists('cleg_field_ops_get_live_presence')) {
    function cleg_field_ops_get_live_presence($filters = array()) {
        $filters = is_array($filters) ? $filters : array();
        $filters['formula'] = !empty($filters['formula']) ? $filters['formula'] : cleg_field_ops_open_shift_formula();
        $filters['max_records'] = !empty($filters['max_records']) ? (int) $filters['max_records'] : 100;

        return cleg_field_ops_get_time_entries($filters);
    }
}

if (!function_exists('cleg_field_ops_get_device_records')) {
    function cleg_field_ops_get_device_records($filters = array()) {
        $filters = is_array($filters) ? $filters : array();
        $filters['formula'] = !empty($filters['formula']) ? $filters['formula'] : cleg_field_ops_device_formula();
        $filters['max_records'] = !empty($filters['max_records']) ? (int) $filters['max_records'] : 100;

        return cleg_field_ops_get_time_entries($filters);
    }
}

if (!function_exists('cleg_field_ops_effective_clock_in_formula')) {
    function cleg_field_ops_effective_clock_in_formula() {
        return "IF({Admin Adjusted Clock In Time},{Admin Adjusted Clock In Time},{Clock In Time})";
    }
}

if (!function_exists('cleg_field_ops_effective_clock_out_formula')) {
    function cleg_field_ops_effective_clock_out_formula() {
        return "IF({Admin Adjusted Clock Out Time},{Admin Adjusted Clock Out Time},IF({Worker Reported Clock Out Time},{Worker Reported Clock Out Time},{Clock Out Time}))";
    }
}

if (!function_exists('cleg_field_ops_identity_formula')) {
    function cleg_field_ops_identity_formula($employee_name = '', $portal_username = '', $wp_user_id = 0) {
        $parts = array();
        $wp_user_id = absint($wp_user_id);
        $employee_name = sanitize_text_field((string) $employee_name);
        $portal_username = sanitize_user((string) $portal_username, true);

        if ($wp_user_id > 0) {
            $parts[] = '{WordPress User ID}=' . $wp_user_id;
        }
        if ($portal_username !== '') {
            $parts[] = "{Portal Username}='" . str_replace("'", "\\'", $portal_username) . "'";
        }
        if ($employee_name !== '') {
            $parts[] = "{Employee Name}='" . str_replace("'", "\\'", $employee_name) . "'";
        }

        if (empty($parts)) {
            return '';
        }

        return count($parts) === 1 ? $parts[0] : 'OR(' . implode(',', $parts) . ')';
    }
}

if (!function_exists('cleg_field_ops_validate_no_time_overlap')) {
    function cleg_field_ops_validate_no_time_overlap($employee_name, $portal_username, $wp_user_id, $clock_in, $clock_out, $exclude_record_id = '') {
        if (!defined('CLEG_AIRTABLE_TIME_TABLE')) {
            return new WP_Error('cleg_field_ops_time_table_missing', 'No se pudo validar solapes: falta la tabla de horas.');
        }

        $clock_in = sanitize_text_field((string) $clock_in);
        $clock_out = sanitize_text_field((string) $clock_out);
        $exclude_record_id = sanitize_text_field((string) $exclude_record_id);

        if ($clock_in === '' || $clock_out === '' || strtotime($clock_in) === false || strtotime($clock_out) === false) {
            return new WP_Error('cleg_field_ops_overlap_invalid_time', 'No se pudo validar solapes: entrada o salida invalida.');
        }

        if (strtotime($clock_out) <= strtotime($clock_in)) {
            return new WP_Error('cleg_field_ops_overlap_invalid_range', 'La salida debe ser despues de la entrada.');
        }

        $identity = cleg_field_ops_identity_formula($employee_name, $portal_username, $wp_user_id);
        if ($identity === '') {
            return new WP_Error('cleg_field_ops_overlap_missing_employee', 'No se pudo validar solapes: falta identificar al trabajador.');
        }

        $effective_in = cleg_field_ops_effective_clock_in_formula();
        $effective_out = cleg_field_ops_effective_clock_out_formula();
        $parts = array(
            $identity,
            "{Approval Status}!='Deleted'",
            "{Approval Status}!='Rejected'",
            "IS_BEFORE({$effective_in},'" . str_replace("'", "\\'", $clock_out) . "')",
            "OR({$effective_out}=BLANK(),IS_AFTER({$effective_out},'" . str_replace("'", "\\'", $clock_in) . "'))",
        );

        if ($exclude_record_id !== '') {
            $parts[] = "RECORD_ID()!='" . str_replace("'", "\\'", $exclude_record_id) . "'";
        }

        $records = cleg_field_ops_records(CLEG_AIRTABLE_TIME_TABLE, array(
            'pageSize' => 1,
            'filterByFormula' => 'AND(' . implode(',', $parts) . ')',
        ));

        if (is_wp_error($records)) {
            return $records;
        }

        if (!empty($records)) {
            return new WP_Error('cleg_field_ops_time_overlap', 'Este trabajador ya tiene una jornada que se solapa con ese horario. Nadie puede estar en dos lugares al mismo tiempo.');
        }

        return true;
    }
}
