        if (function_exists('cleg_saas_module_enabled')) {
            return (bool) cleg_saas_module_enabled($module_key);
        }

        if (function_exists('cleg_shell_module_enabled')) {
            return (bool) cleg_shell_module_enabled($module_key);
        }

        return true;
    }
}

if (!function_exists('cleg_admin_mobile_control_header')) {
    function cleg_admin_mobile_control_header($metrics) {
