            . '</div>'
            . '<aside><span>' . esc_html($attention_label) . '</span><strong>' . esc_html($attention) . '</strong><small>' . esc_html($attention_detail !== '' ? $attention_detail : current_time('M j, g:i a') . ' PR') . '</small></aside>'
            . '</header>';

        if ($kpi_html !== '') {
            $html .= '<section class="cleg-field-mobile-kpis" aria-label="Resumen rapido">' . $kpi_html . '</section>';
        }

        return $html;
    }
}

if (!function_exists('cleg_admin_project_cost_summary')) {
    function cleg_admin_project_cost_summary($time_entries, $employees) {
        $employee_index = cleg_admin_employee_pay_index($employees);
        $projects = array();
        $day_keys = array();
        $now = new DateTime('now', new DateTimeZone('America/Puerto_Rico'));
        $now_value = $now->format('Y-m-d H:i:s');

        foreach ((array) $time_entries as $record) {
            $status = cleg_admin_field($record, 'Approval Status');
            if (in_array($status, array('Rejected', 'Deleted', 'Payroll Closed'), true)) {
                continue;
            }

            $project = cleg_admin_field($record, 'Job Site Name', 'Sin proyecto');
            $employee_name = cleg_admin_field($record, 'Employee Name');
            $portal_username = cleg_admin_field($record, 'Portal Username');
            $employee_key = strtolower($employee_name ?: $portal_username);
            $pay = $employee_index[$employee_key] ?? array('amount' => 0, 'period' => 'Per Hour');
            $clock_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
            $clock_out = cleg_admin_field($record, 'Admin Adjusted Clock Out Time') ?: cleg_admin_field($record, 'Worker Reported Clock Out Time') ?: cleg_admin_field($record, 'Clock Out Time');
            $effective_out = $clock_out !== '' ? $clock_out : $now_value;
            $hours = cleg_admin_hours_float($clock_in, $effective_out);

            if (!isset($projects[$project])) {
                $projects[$project] = array('hours' => 0, 'cost' => 0, 'entries' => 0, 'open' => 0, 'last' => '', 'employees' => array());
            }

            $projects[$project]['hours'] += $hours;
            $projects[$project]['entries']++;
            if ($clock_out === '') {
                $projects[$project]['open']++;
            }
            if ($employee_name !== '') {
                $projects[$project]['employees'][$employee_name] = true;
            }
            if ($clock_in !== '' && ($projects[$project]['last'] === '' || strtotime($clock_in) > strtotime($projects[$project]['last']))) {
                $projects[$project]['last'] = $clock_in;
            }

            $period = $pay['period'];
            $amount = (float) $pay['amount'];
            if ($period === 'Per Hour') {
                $projects[$project]['cost'] += $hours * $amount;
            } elseif ($period === 'Per Day') {
                $day = $clock_in !== '' ? gmdate('Y-m-d', strtotime($clock_in)) : '';
                $day_key = $project . '|' . $employee_key . '|' . $day;
                if ($day !== '' && empty($day_keys[$day_key])) {
                    $projects[$project]['cost'] += $amount;
                    $day_keys[$day_key] = true;
                }
            }
        }

        uasort($projects, function ($a, $b) {
            return $b['hours'] <=> $a['hours'];
        });

        return $projects;
    }
}

if (!function_exists('cleg_admin_project_overview_panel')) {
    function cleg_admin_project_overview_panel($time_entries, $employees, $job_sites = array()) {
        $summary = cleg_admin_project_cost_summary($time_entries, $employees);
        $active_names = array();
        foreach ((array) $job_sites as $site) {
            $name = cleg_admin_field($site, 'Job Site Name');
            if ($name !== '' && !isset($summary[$name])) {
                $summary[$name] = array('hours' => 0, 'cost' => 0, 'entries' => 0, 'open' => 0, 'last' => '', 'employees' => array());
            }
            if ($name !== '') {
                $active_names[$name] = true;
            }
        }

        $html = '<div class="cleg-panel cleg-project-panel"><div class="cleg-panel-head"><div><h2>Hora hombre por proyecto</h2><p>Horas y costo estimado conectados a Time Entries, Employees y Job Sites.</p></div><a class="cleg-row-action" href="' . esc_url(home_url('/admin-job-sites/')) . '">Ver proyectos</a></div><div class="cleg-table-wrap"><table><thead><tr><th>Proyecto</th><th>Horas hombre</th><th>Costo estimado</th><th>Trabajadores</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>';

        foreach (array_slice($summary, 0, 12, true) as $project => $data) {
            $status = !empty($active_names[$project]) ? '<span class="cleg-pill is-ok">Activo</span>' : '<span class="cleg-pill is-warn">Temporal / sin ficha</span>';
            if (!empty($data['open'])) {
                $status .= '<span class="cleg-pill is-warn">' . esc_html($data['open']) . ' abierta(s)</span>';
            }
            $project_url = cleg_admin_context_url('/admin-job-sites/', array('cleg_project' => $project));
            $html .= '<tr><td><a class="cleg-cell-link" href="' . esc_url($project_url) . '"><strong>' . esc_html($project) . '</strong><small>Ultimo movimiento: ' . esc_html($data['last'] !== '' ? cleg_admin_date($data['last']) : 'Sin horas') . '</small></a></td><td><a class="cleg-cell-link" href="' . esc_url($project_url) . '"><strong>' . esc_html(cleg_admin_hours_label((float) $data['hours'])) . '</strong><small>' . esc_html((int) $data['entries']) . ' registros</small></a></td><td><a class="cleg-cell-link" href="' . esc_url($project_url) . '"><strong>' . esc_html(cleg_admin_money($data['cost'])) . '</strong><small>Hora hombre estimada</small></a></td><td><a class="cleg-cell-link" href="' . esc_url($project_url) . '">' . esc_html(count($data['employees'])) . '</a></td><td>' . $status . '</td><td><a class="cleg-row-action" href="' . esc_url($project_url) . '">Abrir proyecto</a></td></tr>';
        }

        if (empty($summary)) {
            $html .= '<tr><td colspan="6">Todavia no hay horas por proyecto.</td></tr>';
        }

        return $html . '</tbody></table></div></div>';
    }
}

if (!function_exists('cleg_admin_request_status_counts')) {
    function cleg_admin_request_status_counts($requests) {
        $counts = array('Pending' => 0, 'Approved' => 0, 'Rejected' => 0, 'Deleted' => 0, 'Other' => 0);
        foreach ((array) $requests as $request) {
            $status = cleg_admin_field($request, 'Status', 'Other');
            $counts[isset($counts[$status]) ? $status : 'Other']++;
        }
        return $counts;
    }
}

if (!function_exists('cleg_admin_request_pill')) {
    function cleg_admin_request_pill($status) {
        $class = 'is-neutral';
        if ($status === 'Approved') {
            $class = 'is-ok';
        } elseif ($status === 'Pending' || $status === 'Pending Review') {
            $class = 'is-warn';
        } elseif ($status === 'Rejected' || $status === 'Deleted') {
            $class = 'is-bad';
        }
        return '<span class="cleg-pill ' . esc_attr($class) . '">' . esc_html($status ?: '--') . '</span>';
    }
}

if (!function_exists('cleg_admin_request_date_label')) {
    function cleg_admin_request_date_label($value, $with_time = false) {
        // A civil absence day is not a UTC instant: never shift it to another day.
        if (!$with_time && preg_match('/^(\d{4})-(\d{2})-(\d{2})$/', (string) $value, $parts)) {
            return checkdate((int) $parts[2], (int) $parts[3], (int) $parts[1])
                ? $parts[3] . '/' . $parts[2] . '/' . $parts[1]
                : sanitize_text_field((string) $value);
        }
        $timestamp = strtotime((string) $value);
        if (!$timestamp) {
            return sanitize_text_field((string) $value);
        }

        return $with_time ? wp_date('d/m/Y g:i a', $timestamp) : wp_date('d/m/Y', $timestamp);
    }
}

if (!function_exists('cleg_admin_request_days_count')) {
    function cleg_admin_request_days_count($start, $end, $fallback_days = array()) {
        $start_ts = strtotime((string) $start);
        $end_ts = strtotime((string) $end);

        if ($start_ts && $end_ts && $end_ts >= $start_ts) {
            return max(1, (int) floor(($end_ts - $start_ts) / DAY_IN_SECONDS) + 1);
        }

        return max(1, count(array_unique(array_filter((array) $fallback_days))));
    }
}

if (!function_exists('cleg_admin_request_detail_summary')) {
    function cleg_admin_request_detail_summary($request) {
        $details = cleg_admin_field($request, 'Details');
        $day = '';
        if (preg_match('/Dia que faltaste:\s*(\d{4}-\d{2}-\d{2})/i', $details, $matches)) {
            $day = $matches[1];
        }
        if ($day === '') {
            $day = cleg_admin_field($request, 'Request Date');
        }
        $start = $day;
        $end = $day;

        if (preg_match('/Rango solicitado:\s*(\d{4}-\d{2}-\d{2})\s*(?:al|-|to)\s*(\d{4}-\d{2}-\d{2})/i', $details, $matches)) {
            $start = $matches[1];
            $end = $matches[2];
        }

        $reason = '';
        if (preg_match('/Nota:\s*(.*?)(?:\s*Rango solicitado:|$)/is', $details, $matches)) {
            $reason = trim((string) $matches[1]);
        }

        if ($reason === '') {
            $reason = preg_replace('/Dia que faltaste:\s*\d{4}-\d{2}-\d{2}/i', '', $details);
            $reason = preg_replace('/Rango solicitado:\s*\d{4}-\d{2}-\d{2}\s*(?:al|-|to)\s*\d{4}-\d{2}-\d{2}/i', '', (string) $reason);
            $reason = trim(str_replace('Nota:', '', (string) $reason));
        }

        return array(
            'day' => $day,
            'start' => $start !== '' ? $start : $day,
            'end' => $end !== '' ? $end : $day,
            'reason' => $reason !== '' ? $reason : 'Sin razón escrita',
        );
    }
}

if (!function_exists('cleg_admin_group_hr_requests_for_display')) {
    function cleg_admin_group_hr_requests_for_display($requests) {
        $groups = array();

        foreach (cleg_admin_sort_requests_by_submitted_date($requests) as $request) {
            $summary = cleg_admin_request_detail_summary($request);
            $submitted = cleg_admin_request_submitted_date($request);
            $submitted_ts = strtotime($submitted) ?: 0;
            $employee = cleg_admin_field($request, 'Employee Name');
            $username = cleg_admin_field($request, 'Portal Username');
            $type = cleg_admin_field($request, 'Request Type');
            $status = cleg_admin_field($request, 'Status');
            $key = md5(implode('|', array($employee, $username, $type, $status, $summary['start'], $summary['end'], $summary['reason'])));

            if (!isset($groups[$key])) {
                $groups[$key] = array(
                    'employee' => $employee,
                    'username' => $username,
                    'type' => $type,
                    'status' => $status,
                    'submitted' => $submitted,
                    'submitted_ts' => $submitted_ts,
                    'start' => $summary['start'],
                    'end' => $summary['end'],
                    'reason' => $summary['reason'],
                    'days' => array(),
                    'records' => array(),
                    'notes' => array(),
                );
            }

            if ($submitted_ts > 0 && ($groups[$key]['submitted_ts'] === 0 || $submitted_ts < $groups[$key]['submitted_ts'])) {
                $groups[$key]['submitted_ts'] = $submitted_ts;
                $groups[$key]['submitted'] = $submitted;
            }

            if ($summary['day'] !== '') {
                $groups[$key]['days'][] = $summary['day'];
            }

            $notes = trim(cleg_admin_field($request, 'Admin Notes'));
            if ($notes !== '') {
                $groups[$key]['notes'][] = $notes;
            }

            $groups[$key]['records'][] = $request;
        }

        usort($groups, function ($a, $b) {
            return ((int) ($b['submitted_ts'] ?? 0)) <=> ((int) ($a['submitted_ts'] ?? 0));
        });

        return $groups;
    }
}

if (!function_exists('cleg_admin_hr_request_group_action_form')) {
    function cleg_admin_hr_request_group_action_form($records) {
        $records = (array) $records;
        if (empty($records)) {
            return '<small>Sin accion</small>';
        }

        if (count($records) === 1) {
            return cleg_admin_hr_request_action_form($records[0]);
        }

        $all_pending = true;
        foreach ($records as $record) {
            if (cleg_admin_request_bucket($record) !== 'pending') {
                $all_pending = false;
                break;
            }
        }

        if (!$all_pending) {
            return '<small>Decision tomada</small>';
        }

        $html = '<details class="cleg-request-group-actions"><summary>Aprobar dias</summary>';
        foreach ($records as $record) {
            $summary = cleg_admin_request_detail_summary($record);
            $html .= '<div><small>' . esc_html(cleg_admin_request_date_label($summary['day'])) . '</small>' . cleg_admin_hr_request_action_form($record) . '</div>';
        }

        return $html . '</details>';
    }
}

if (!function_exists('cleg_admin_requests_table')) {
    function cleg_admin_requests_table($requests, $limit = 20, $title = 'Solicitudes recientes', $subtitle = 'Ausencias, permisos y novedades enviadas desde el portal trabajador.', $show_all_link = true) {
        $action = $show_all_link ? '<a class="cleg-row-action" href="' . esc_url(home_url('/admin-solicitudes/')) . '">Ver todas</a>' : '';
        $html = '<div class="cleg-panel"><div class="cleg-panel-head"><div><h2>' . esc_html($title) . '</h2><p>' . esc_html($subtitle) . '</p></div>' . $action . '</div>';
        $mobile = '<div class="cleg-mobile-only cleg-mobile-card-stack" aria-label="' . esc_attr($title) . '">';
        $table = '<div class="cleg-table-wrap cleg-desktop-table"><table class="cleg-requests-summary-table"><thead><tr><th>Trabajador</th><th>Solicitud</th><th>Dias solicitados</th><th>Razon</th><th>Status</th><th>Accion</th></tr></thead><tbody>';
        $request_groups = cleg_admin_group_hr_requests_for_display($requests);

        foreach (array_slice($request_groups, 0, $limit) as $group) {
            $days_count = cleg_admin_request_days_count($group['start'], $group['end'], $group['days']);
            $range = cleg_admin_request_date_label($group['start']) . ($group['end'] !== $group['start'] ? ' - ' . cleg_admin_request_date_label($group['end']) : '');
            $days_label = $days_count . ' dia' . ($days_count === 1 ? '' : 's');
            $notes = array_unique(array_filter((array) ($group['notes'] ?? array())));
            $audit = !empty($notes) ? '<details class="cleg-request-audit"><summary>Auditoria</summary><pre>' . esc_html(implode("\n", $notes)) . '</pre></details>' : '';
            $records = (array) ($group['records'] ?? array());
            $action_html = cleg_admin_hr_request_group_action_form($records);

            $mobile .= '<article class="cleg-mobile-card cleg-metric"><div class="cleg-mobile-card-top cleg-context-head"><div><span>' . esc_html($group['type']) . '</span><strong>' . esc_html($group['employee']) . '</strong></div>' . cleg_admin_request_pill($group['status']) . '</div><div class="cleg-mobile-facts"><div class="cleg-metric"><small>Fechas</small><b>' . esc_html($range) . '</b></div><div class="cleg-metric"><small>Días</small><b>' . esc_html($days_label) . '</b></div></div><p class="cleg-mobile-muted">' . esc_html($group['reason']) . '</p>' . $action_html . '</article>';
            $table .= '<tr><td><strong>' . esc_html($group['employee']) . '</strong><small>' . esc_html($group['username']) . '</small></td>'
                . '<td><strong>' . esc_html($group['type']) . '</strong><small>Pedido: ' . esc_html(cleg_admin_request_date_label($group['submitted'], true)) . '</small></td>'
                . '<td><strong>' . esc_html($range) . '</strong><small>' . esc_html($days_label) . '</small></td>'
                . '<td><span class="cleg-request-reason">' . esc_html($group['reason']) . '</span>' . $audit . '</td>'
                . '<td>' . cleg_admin_request_pill($group['status']) . '</td><td>' . $action_html . '</td></tr>';
        }
        if (empty($request_groups)) {
            $table .= '<tr><td colspan="6">No hay solicitudes registradas.</td></tr>';
            $mobile .= '<article class="cleg-mobile-card cleg-metric"><strong>No hay solicitudes registradas.</strong></article>';
        }
        return $mobile . '</div>' . $html . $table . '</tbody></table></div></div>';
    }
}

if (!function_exists('cleg_admin_request_bucket')) {
    function cleg_admin_request_bucket($request) {
        $status = cleg_admin_field($request, 'Status');

        if ($status === '' || $status === 'Pending' || $status === 'Pending Review' || $status === 'Open') {
            return 'pending';
        }

        if ($status === 'Approved') {
            return 'approved';
        }

        return 'history';
    }
}

if (!function_exists('cleg_admin_split_hr_requests')) {
    function cleg_admin_split_hr_requests($requests) {
        $groups = array(
            'pending' => array(),
            'approved' => array(),
            'history' => array(),
            'operational' => array(),
        );

        foreach ((array) $requests as $request) {
            $bucket = cleg_admin_request_bucket($request);
            $groups[$bucket][] = $request;
            if ($bucket === 'pending' || $bucket === 'approved') {
                $groups['operational'][] = $request;
            }
        }

        return $groups;
    }
}

if (!function_exists('cleg_admin_request_submitted_date')) {
    function cleg_admin_request_submitted_date($request) {
        $candidates = array(
            cleg_admin_field($request, 'Submitted Date'),
            cleg_admin_field($request, 'Request Submitted Date'),
            cleg_admin_field($request, 'Created Date'),
            cleg_admin_field($request, 'Created Time'),
            $request['createdTime'] ?? '',
            cleg_admin_field($request, 'Request Date'),
        );

        foreach ($candidates as $candidate) {
            if (trim((string) $candidate) !== '') {
                return (string) $candidate;
            }
        }

        return '';
    }
}

if (!function_exists('cleg_admin_sort_requests_by_submitted_date')) {
    function cleg_admin_sort_requests_by_submitted_date($requests) {
        $requests = (array) $requests;
        usort($requests, function ($a, $b) {
            return strtotime(cleg_admin_request_submitted_date($b)) <=> strtotime(cleg_admin_request_submitted_date($a));
        });
        return $requests;
    }
}

if (!function_exists('cleg_admin_status_counts')) {
    function cleg_admin_status_counts($records) {
        $counts = array('Open' => 0, 'Pending Review' => 0, 'Manual Need Review' => 0, 'Approved' => 0, 'Deleted' => 0, 'Payroll Closed' => 0, 'Rejected' => 0, 'Other' => 0);

        foreach ($records as $record) {
            $status = cleg_admin_field($record, 'Approval Status', 'Other');
            $counts[isset($counts[$status]) ? $status : 'Other']++;
        }

        return $counts;
    }
}

if (!function_exists('cleg_admin_bar_chart')) {
    function cleg_admin_bar_chart($title, $data) {
        $values = array();
        foreach ($data as $item) {
            $values[] = is_array($item) ? (float) ($item['value'] ?? 0) : (float) $item;
        }
        $max = max(1, max($values ?: array(0)));
        $html = '<div class="cleg-chart"><h2>' . esc_html($title) . '</h2>';

        foreach ($data as $label => $value) {
            $href = '';
            if (is_array($value)) {
                $href = $value['href'] ?? '';
                $value = (float) ($value['value'] ?? 0);
            }
            $width = max(3, round(((float) $value / $max) * 100));
            $shown_value = floor($value) === $value ? (string) (int) $value : number_format($value, 2);
            $row = '<span>' . esc_html($label) . '</span><i><b style="width:' . esc_attr($width) . '%"></b></i><strong>' . esc_html($shown_value) . '</strong>';
            $html .= $href !== ''
                ? '<a class="cleg-bar cleg-bar-link" href="' . esc_url($href) . '">' . $row . '</a>'
                : '<div class="cleg-bar">' . $row . '</div>';
        }

        return $html . '</div>';
    }
}

if (!function_exists('cleg_admin_field_contact_index')) {
    function cleg_admin_field_contact_index($employees) {
        $index = array();

        foreach ((array) $employees as $employee) {
            $phone = cleg_admin_field($employee, 'Phone');
            if ($phone === '') {
                continue;
            }

            $keys = array(
                strtolower(cleg_admin_field($employee, 'Portal Username')),
                strtolower(cleg_admin_field($employee, 'Employee Name')),
            );

            foreach ($keys as $key) {
                if ($key !== '') {
                    $index[$key] = $phone;
                }
            }
        }

        return $index;
    }
}

if (!function_exists('cleg_admin_field_worker_phone')) {
    function cleg_admin_field_worker_phone($record, $contacts) {
        $keys = array(
            strtolower(cleg_admin_field($record, 'Portal Username')),
            strtolower(cleg_admin_field($record, 'Employee Name')),
        );

        foreach ($keys as $key) {
            if ($key !== '' && !empty($contacts[$key])) {
                return $contacts[$key];
            }
        }

        return '';
    }
}

if (!function_exists('cleg_admin_field_phone_href')) {
    function cleg_admin_field_phone_href($phone) {
        $clean = preg_replace('/[^0-9+]/', '', (string) $phone);
        return $clean !== '' ? $clean : '';
    }
}

if (!function_exists('cleg_admin_field_status')) {
    function cleg_admin_field_status($record) {
        $flags = cleg_admin_field($record, 'Audit Flags');
        $reason = cleg_admin_field($record, 'GPS Review Reason');
        $map = cleg_admin_field($record, 'Clock In Map Link') ?: cleg_admin_field($record, 'Clock Out Map Link');

        if (strpos($flags, 'Outside Geofence') !== false || strpos($reason, 'Outside Geofence') !== false || cleg_admin_field($record, 'Clock In Outside Geofence') !== '') {
            return array('Fuera de proyecto', 'is-bad');
        }

        if ($map === '' || strpos($flags, 'Missing GPS') !== false || strpos($reason, 'Missing GPS') !== false) {
            return array('Sin GPS', 'is-bad');
        }

        if (cleg_admin_field($record, 'Worker Manual Clock Out Requested') !== '') {
            return array('Salida pendiente', 'is-warn');
        }

        return array('Trabajando', 'is-ok');
    }
}

if (!function_exists('cleg_admin_field_shift_minutes')) {
    function cleg_admin_field_shift_minutes($record) {
        $dt = cleg_admin_pr_datetime(cleg_admin_field($record, 'Clock In Time'));
        if (!$dt) {
            return 0;
        }

        $now = new DateTime('now', wp_timezone());
        return max(0, (int) floor(($now->getTimestamp() - $dt->getTimestamp()) / 60));
    }
}

if (!function_exists('cleg_admin_field_shift_label')) {
    function cleg_admin_field_shift_label($minutes) {
        $hours = (int) floor(max(0, $minutes) / 60);
        $mins = max(0, $minutes) % 60;
        return $hours . 'h ' . str_pad((string) $mins, 2, '0', STR_PAD_LEFT) . 'm';
    }
}

if (!function_exists('cleg_admin_field_quick_actions')) {
    function cleg_admin_field_quick_actions($record, $phone) {
