        $html = '<div class="cleg-field-worker-actions">';

        if ($phone_href !== '') {
            $html .= '<a href="tel:' . esc_attr($phone_href) . '">Llamar</a>';
            $html .= '<a href="https://wa.me/' . esc_attr(ltrim($phone_href, '+')) . '?text=' . rawurlencode($message) . '" target="_blank" rel="noopener">WhatsApp</a>';
        } else {
            $html .= '<span>Sin telefono</span>';
            $html .= '<span>WhatsApp no disponible</span>';
        }

        return $html . '</div>';
    }
}

