if (!function_exists('cleg_admin_field_is_today')) {
    function cleg_admin_field_is_today($record) {
        $clock_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
        $dt = cleg_admin_pr_datetime($clock_in);

        if (!$dt) {
            return false;
        }

        $today = new DateTime('now', wp_timezone());
        return $dt->format('Y-m-d') === $today->format('Y-m-d');
    }
}

if (!function_exists('cleg_admin_mobile_today_records')) {
