}

if (!function_exists('cleg_admin_mobile_field_menu')) {
    function cleg_admin_mobile_field_menu($pending_count = 0, $active_count = 0, $today_count = 0, $has_map = false) {
        $links = array(
            array('label' => 'Revisar horas', 'href' => '#cleg-field-mobile-review', 'count' => (int) $pending_count),
            array('label' => 'Activos ahora', 'href' => '#cleg-field-workers', 'count' => (int) $active_count),
            array('label' => 'Jornadas de hoy', 'href' => '#cleg-field-today-shifts', 'count' => (int) $today_count),
        );

        if ($has_map && $active_count > 0) {
            $links[] = array('label' => 'Mapa del equipo', 'href' => '#cleg-campo-mapa', 'count' => (int) $active_count);
        }

        $items = '';
        foreach ($links as $link) {
            if ((int) $link['count'] <= 0) {
                continue;
            }
            $items .= '<a href="' . esc_url($link['href']) . '">' . esc_html($link['label']) . '<em>' . esc_html((int) $link['count']) . '</em></a>';
        }

        if ($items === '') {
            return '';
        }

        return '<details class="cleg-field-menu"><summary><span>Menu operativo</span><b>Opciones</b></summary><div>' . $items . '</div></details>';
    }
}

