if (!function_exists('cleg_admin_mobile_review_panel')) {
    function cleg_admin_mobile_review_panel($records) {
        $records = cleg_admin_mobile_review_records($records);
        $html = '<details class="cleg-field-mobile-review cleg-field-mobile-accordion" id="cleg-field-mobile-review">'
            . '<summary><div class="cleg-field-review-head"><span><small>Revisar horas</small><b>Revision pendiente</b></span><strong>' . esc_html(count($records)) . '</strong></div></summary>';

        if (empty($records)) {
            return $html . '<div class="cleg-field-shift-empty">No hay horas pendientes de revision ahora mismo.</div></details>';
        }

        foreach (array_slice($records, 0, 10) as $record) {
            $id = sanitize_text_field($record['id'] ?? '');
            $name = cleg_admin_field($record, 'Employee Name', cleg_admin_field($record, 'Portal Username', 'Trabajador'));
            $project = cleg_admin_field($record, 'Job Site Name', 'Sin proyecto');
            $status = cleg_admin_field($record, 'Approval Status', 'Pending Review');
            $adjusted_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time');
            $adjusted_out = cleg_admin_field($record, 'Admin Adjusted Clock Out Time');
            $clock_in = $adjusted_in ?: cleg_admin_field($record, 'Clock In Time');
            $clock_out = $adjusted_out ?: cleg_admin_field($record, 'Worker Reported Clock Out Time') ?: cleg_admin_field($record, 'Clock Out Time');
            $hours = (float) cleg_admin_field($record, 'Payroll Hours Calc', cleg_admin_field($record, 'Total Hours', 0));
            $can_approve = $clock_out !== '' && !cleg_admin_mobile_missing_job_site($project);

            $html .= '<article class="cleg-field-review-row">'
                . '<button type="button" class="cleg-field-review-main" aria-expanded="false">'
                . '<span><b>' . esc_html($name) . '</b><small>' . esc_html($project) . '</small></span>'
                . cleg_admin_status_pill($status)
                . '</button>'
                . '<div class="cleg-field-review-facts">'
                . cleg_admin_mobile_review_time_editor($id, 'admin_adjusted_clock_in', $clock_in, 'Entrada', cleg_admin_date($clock_in), $adjusted_in !== '' ? 'Corregida' : 'Original')
                . cleg_admin_mobile_review_time_editor($id, 'admin_adjusted_clock_out', $clock_out, 'Salida', $clock_out !== '' ? cleg_admin_date($clock_out) : 'Pendiente', $adjusted_out !== '' ? 'Corregida' : 'Original')
                . '<span><strong>Horas</strong>' . esc_html($hours > 0 ? cleg_admin_hours_label($hours) : 'Por calcular') . '</span>'
                . '</div>'
                . cleg_admin_mobile_review_audit_drawer($record)
                . '<div class="cleg-field-review-actions">'
                . ($can_approve ? cleg_admin_mobile_review_action_form($id, 'approve', 'Aprobar', 'is-approve') : '<span>No aprobable aun</span>')
                . cleg_admin_mobile_review_action_form($id, 'delete', 'Eliminar', 'is-delete')
                . cleg_admin_field_incident_form($id, 'Revisar viernes', 'Mantener revision')
                . '</div>'
                . '</article>';
        }

        return $html . '</details>';
    }
}

