            $clock_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
            $clock_out = cleg_admin_field($record, 'Admin Adjusted Clock Out Time') ?: cleg_admin_field($record, 'Clock Out Time');
            $is_open = $clock_out === '';
