                . '<div class="cleg-field-shift-times"><small>Entrada ' . esc_html(cleg_admin_date($clock_in)) . '</small><small>Salida ' . esc_html($clock_out !== '' ? cleg_admin_date($clock_out) : 'Pendiente') . '</small></div>'
                . ($is_open ? cleg_admin_field_close_form($id, $minutes >= 600 ? 'Cerrar larga' : 'Cerrar salida') : '<em>Cerrada</em>')
                . '</article>';
