    }
}

if (!function_exists('cleg_admin_mobile_field_today')) {
    function cleg_admin_mobile_field_today($records, $employees = array(), $today_records = array(), $metrics = array(), $requests = array()) {
        $contacts = cleg_admin_field_contact_index($employees);
        $active = count((array) $records);
        $missing_gps = 0;
        $long_open = 0;
        $pending = 0;
        $review_pending_count = count(cleg_admin_mobile_review_records($today_records));

        foreach ((array) $records as $record) {
            list($status_label) = cleg_admin_field_status($record);
            if ($status_label === 'Sin GPS') {
                $missing_gps++;
            }
            if (cleg_admin_field_shift_minutes($record) >= 600) {
                $long_open++;
            }
            if ($status_label !== 'Trabajando' || cleg_admin_field($record, 'Worker Manual Clock Out Requested') !== '') {
                $pending++;
            }
        }

        $metrics['active_now'] = $active;

        $html = '<section class="cleg-mobile-only cleg-field-today cleg-field-mini-panel" aria-label="Panel operativo movil">'
            . cleg_admin_mobile_control_header($metrics)
            . '<details class="cleg-field-workers-block cleg-field-mobile-accordion" id="cleg-field-workers">'
            . '<summary><div class="cleg-field-worker-head"><span><small>Trabajadores</small><b>En turno</b></span><strong>' . esc_html($active) . '</strong></div></summary>'
            . '<div class="cleg-field-worker-list">';

        foreach ((array) $records as $record) {
            $id = sanitize_text_field($record['id'] ?? '');
            $name = cleg_admin_field($record, 'Employee Name', cleg_admin_field($record, 'Portal Username', 'Trabajador'));
            $project = cleg_admin_field($record, 'Job Site Name', 'Sin proyecto');
            $clock_in = cleg_admin_field($record, 'Clock In Time');
            $phone = cleg_admin_field_worker_phone($record, $contacts);
            $shift_minutes = cleg_admin_field_shift_minutes($record);
            list($status_label, $status_class) = cleg_admin_field_status($record);

            $html .= '<article class="cleg-field-worker-card">'
                . '<button type="button" class="cleg-field-worker-main" aria-expanded="false" data-worker-name="' . esc_attr($name) . '">'
                . '<em class="cleg-field-active-dot" aria-label="' . esc_attr($status_label) . '"></em>'
                . '<span class="cleg-field-worker-name"><b>' . esc_html($name) . '</b></span>'
                . '<small>' . esc_html(cleg_admin_field_shift_label($shift_minutes)) . '</small>'
                . '</button>'
                . '<div class="cleg-field-worker-meta">'
                . '<span><strong>Proyecto</strong>' . esc_html($project) . '</span>'
                . '<span><strong>Ultimo ping</strong>' . esc_html(cleg_admin_date($clock_in)) . '</span>'
                . '<span><strong>Abierta</strong>' . esc_html(cleg_admin_field_shift_label($shift_minutes)) . '</span>'
                . '</div>'
                . '<div class="cleg-field-worker-detail">'
                . '<div class="cleg-field-detail-grid"><span><strong>Entrada</strong>' . esc_html(cleg_admin_date($clock_in)) . '</span><span><strong>Salida</strong>Pendiente</span><span><strong>Proyecto asignado</strong>' . esc_html($project) . '</span><span><strong>Estado</strong>' . esc_html($status_label) . '</span></div>'
                . '<div class="cleg-field-detail-actions">' . ($id !== '' ? cleg_admin_field_close_form($id, $shift_minutes >= 600 ? 'Cerrar jornada larga' : 'Cerrar salida') : '') . ($id !== '' ? cleg_admin_field_incident_form($id, 'Revisar viernes', 'Marcar para revisar') : '') . '</div>'
                . '<div class="cleg-field-incidents">'
                . ($id !== '' ? cleg_admin_field_incident_form($id, 'Falta salida', 'Falta salida') : '')
                . ($id !== '' && $status_label === 'Sin GPS' ? cleg_admin_field_incident_form($id, 'GPS raro', 'GPS raro') : '')
                . ($id !== '' ? cleg_admin_field_incident_form($id, 'Llego tarde', 'Llego tarde') : '')
                . '</div>'
                . '</div>'
                . '</article>';
        }

        if (empty($records)) {
            $html .= '<article class="cleg-field-worker-card is-empty"><strong>No hay trabajadores activos ahora mismo.</strong><span>Cuando alguien marque entrada, aparecera aqui.</span></article>';
        }

        return $html . '</div></details>' . cleg_admin_mobile_requests_panel($requests) . cleg_admin_mobile_review_panel($today_records) . '</section>' . cleg_admin_field_today_script();
    }
}

if (!function_exists('cleg_admin_mobile_gps_drawer')) {
    function cleg_admin_mobile_gps_drawer() {
        if (!shortcode_exists('cleg_admin_gps_tracking')) {
            return '';
        }

        return '<details class="cleg-mobile-only cleg-field-gps-drawer cleg-field-mobile-accordion">'
            . '<summary><div class="cleg-field-gps-head"><span><small>GPS</small><b>Ubicacion del equipo</b></span><strong>Ver</strong></div></summary>'
            . '<div class="cleg-field-gps-slot">' . do_shortcode('[cleg_admin_gps_tracking]') . '</div>'
            . '</details>';
    }
}

