    function cleg_admin_field_today_script() {
        $style = '<style id="cleg-field-worker-contrast-fix-v2">body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-card,body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-main,body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-meta,body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-detail{background:#fff!important;color:#06182d!important;-webkit-text-fill-color:#06182d!important;text-shadow:none!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-card{border:1px solid rgba(6,24,45,.14)!important;border-radius:8px!important;box-shadow:0 8px 18px rgba(6,24,45,.05)!important;overflow:hidden!important;transform:none!important;scale:1!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-card.is-open{background:#fff!important;border-color:#2f6f9f!important;box-shadow:0 0 0 2px rgba(47,111,159,.20),0 8px 18px rgba(6,24,45,.05)!important;transform:none!important;scale:1!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-main,body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-card.is-open .cleg-field-worker-main{display:grid!important;grid-template-columns:18px minmax(0,1fr) auto!important;align-items:center!important;gap:8px!important;width:100%!important;min-width:0!important;min-height:42px!important;padding:6px 8px!important;background:#fff!important;color:#06182d!important;-webkit-text-fill-color:#06182d!important;border:0!important;border-radius:8px!important;box-shadow:none!important;transform:none!important;scale:1!important;text-align:left!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-main b,body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-main .cleg-field-worker-name b,body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-main span{display:block!important;color:#06182d!important;-webkit-text-fill-color:#06182d!important;text-shadow:none!important;font-size:16px!important;line-height:1.18!important;white-space:normal!important;word-break:normal!important;overflow-wrap:break-word!important;writing-mode:horizontal-tb!important;text-orientation:mixed!important;text-align:left!important;overflow:visible!important;text-overflow:clip!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-main small{display:block!important;color:#516579!important;-webkit-text-fill-color:#516579!important;text-shadow:none!important;font-size:11px!important;line-height:1.1!important;white-space:nowrap!important;text-align:right!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-name{display:block!important;min-width:0!important;max-width:100%!important;white-space:normal!important;word-break:normal!important;overflow-wrap:break-word!important;writing-mode:horizontal-tb!important;text-orientation:mixed!important;text-align:left!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-worker-detail{background:#f4f7fb!important;}body .cleg-admin-ui .cleg-field-today .cleg-field-workers-block .cleg-field-active-dot{background:#24c46b!important;-webkit-text-fill-color:initial!important;color:initial!important;}}</style>';
        $script = '<script>(function(){function ready(callback){if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",callback,{once:true});return;}callback();}function scrollTopOf(element){if(!element||!element.scrollIntoView)return;window.setTimeout(function(){element.scrollIntoView({behavior:"smooth",block:"start",inline:"nearest"});},80);}function focusMap(button,open){var name=button.getAttribute("data-worker-name")||"";if(!open||!name)return;var drawer=document.querySelector(".cleg-field-gps-drawer");if(drawer)drawer.open=true;setTimeout(function(){document.dispatchEvent(new CustomEvent("cleg17:gps-focus-worker",{detail:{name:name}}));},120);}function closeCards(scope,selector,cardSelector,openClass,except){scope.querySelectorAll(cardSelector+"."+openClass).forEach(function(item){if(item!==except){item.classList.remove(openClass);var btn=item.querySelector(selector);if(btn)btn.setAttribute("aria-expanded","false");}});}function wireAccordions(){var accordions=document.querySelectorAll(".cleg-admin-ui .cleg-field-mobile-accordion");accordions.forEach(function(detail){var summary=detail.querySelector("summary");if(!summary)return;summary.addEventListener("click",function(){var willOpen=!detail.open;if(!willOpen)return;accordions.forEach(function(other){if(other!==detail)other.open=false;});window.setTimeout(function(){scrollTopOf(summary);},10);});});}function wireToggle(selector,cardSelector,openClass){document.querySelectorAll(selector).forEach(function(button){button.addEventListener("click",function(){var card=button.closest(cardSelector);if(!card)return;var scope=card.closest(".cleg-field-mobile-accordion")||document;var open=!card.classList.contains(openClass);closeCards(scope,selector,cardSelector,openClass,card);card.classList.toggle(openClass,open);button.setAttribute("aria-expanded",open?"true":"false");if(open)scrollTopOf(button);if(selector===".cleg-field-worker-main")focusMap(button,open);});});}ready(function(){wireAccordions();wireToggle(".cleg-field-worker-main",".cleg-field-worker-card","is-open");wireToggle(".cleg-field-request-main",".cleg-field-request-row","is-open");wireToggle(".cleg-field-review-main",".cleg-field-review-row","is-open");});document.addEventListener("submit",function(event){var form=event.target;if(!form.closest(".cleg-field-today"))return;if(form.classList&&form.classList.contains("cleg-field-review-time-form"))return;var button=form.querySelector("button[type=submit],button[name=cleg_admin_action],button[name=cleg_admin_hr_request_action]");var label=button?button.textContent.trim():"aplicar";if(!window.confirm("Confirmar: "+label+"?")){event.preventDefault();}});})();</script>';

        return $style . $script;
    }
}

if (!function_exists('cleg_admin_rrhh_period_key')) {
    function cleg_admin_rrhh_period_key() {
        $period = isset($_GET['cleg_period']) ? sanitize_key(wp_unslash($_GET['cleg_period'])) : 'week';
        return in_array($period, array('week', 'month', 'year'), true) ? $period : 'week';
    }
}

if (!function_exists('cleg_admin_rrhh_period_label')) {
    function cleg_admin_rrhh_period_label($period) {
        $labels = array(
            'week'  => 'Semana',
            'month' => 'Mes',
            'year'  => 'Ano',
        );
        return $labels[$period] ?? 'Semana';
    }
}

if (!function_exists('cleg_admin_rrhh_period_next')) {
    function cleg_admin_rrhh_period_next($period) {
        if ($period === 'week') {
            return 'month';
        }
        if ($period === 'month') {
            return 'year';
        }
        return 'week';
    }
}

if (!function_exists('cleg_admin_rrhh_period_toggle_url')) {
    function cleg_admin_rrhh_period_toggle_url($period) {
        return add_query_arg('cleg_period', cleg_admin_rrhh_period_next($period), home_url('/admin-rrhh/'));
    }
}

if (!function_exists('cleg_admin_rrhh_period_bounds')) {
    function cleg_admin_rrhh_period_bounds($period) {
        $tz = new DateTimeZone('America/Puerto_Rico');
        $now = new DateTimeImmutable('now', $tz);

        if ($period === 'month') {
            $start = $now->modify('first day of this month')->setTime(0, 0, 0);
            $end = $start->modify('+1 month');
        } elseif ($period === 'year') {
            $start = $now->setDate((int) $now->format('Y'), 1, 1)->setTime(0, 0, 0);
            $end = $start->modify('+1 year');
        } else {
            $start = $now->modify('monday this week')->setTime(0, 0, 0);
            $end = $start->modify('+1 week');
        }

        return array('start' => $start, 'end' => $end);
    }
}

if (!function_exists('cleg_admin_rrhh_parse_period_datetime')) {
    function cleg_admin_rrhh_parse_period_datetime($value) {
        $value = trim((string) $value);
        if ($value === '') {
            return null;
        }

        $tz = new DateTimeZone('America/Puerto_Rico');
        try {
            if (preg_match('/^\d{4}-\d{2}-\d{2}$/', $value)) {
                return new DateTimeImmutable($value . ' 00:00:00', $tz);
            }

            $dt = new DateTimeImmutable($value, new DateTimeZone('UTC'));
            return $dt->setTimezone($tz);
        } catch (Exception $e) {
            return null;
        }
    }
}

if (!function_exists('cleg_admin_rrhh_value_in_period')) {
    function cleg_admin_rrhh_value_in_period($value, $bounds) {
        $dt = cleg_admin_rrhh_parse_period_datetime($value);
        return $dt && $dt >= $bounds['start'] && $dt < $bounds['end'];
    }
}

if (!function_exists('cleg_admin_rrhh_filter_time_entries')) {
    function cleg_admin_rrhh_filter_time_entries($records, $bounds) {
        return array_values(array_filter((array) $records, function ($record) use ($bounds) {
            $clock_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
            return cleg_admin_rrhh_value_in_period($clock_in, $bounds);
        }));
    }
}

if (!function_exists('cleg_admin_rrhh_filter_requests')) {
    function cleg_admin_rrhh_filter_requests($records, $bounds) {
        return array_values(array_filter((array) $records, function ($record) use ($bounds) {
            return cleg_admin_rrhh_value_in_period(cleg_admin_request_submitted_date($record), $bounds);
        }));
    }
}

if (!function_exists('cleg_admin_rrhh_shortcode')) {
    function cleg_admin_rrhh_shortcode() {
        if (isset($_GET['cleg_tenant_tab']) && function_exists('cleg_tenant_admin_center_shortcode')) {
            wp_safe_redirect(cleg_tenant_admin_tab_url(sanitize_key(wp_unslash($_GET['cleg_tenant_tab']))));
            exit;
        }

        $gate = cleg_admin_gate();

        if ($gate !== '') {
            return $gate;
        }

        $notice = isset($_GET['cleg_admin_error']) ? sanitize_text_field(wp_unslash($_GET['cleg_admin_error'])) : '';
        $approved_id = isset($_GET['cleg_approved']) ? sanitize_text_field(wp_unslash($_GET['cleg_approved'])) : '';
        $saved = isset($_GET['cleg_saved']) ? sanitize_text_field(wp_unslash($_GET['cleg_saved'])) : '';
        $blocked = isset($_GET['cleg_blocked']) ? absint($_GET['cleg_blocked']) : 0;
        $undone = isset($_GET['cleg_undone']) ? sanitize_text_field(wp_unslash($_GET['cleg_undone'])) : '';
        $manual_created = isset($_GET['cleg_manual_created']) ? absint($_GET['cleg_manual_created']) : 0;
        $success_notice = '';

        if ($approved_id !== '') {
            $success_notice = '<div class="cleg-admin-notice is-success cleg-undo-toast"><strong>Horas aprobadas</strong><form method="post">'
                . wp_nonce_field('cleg_admin_time_action', 'cleg_admin_nonce', true, false)
                . '<input type="hidden" name="cleg_admin_record_id" value="' . esc_attr($approved_id) . '">'
                . '<button type="submit" name="cleg_admin_action" value="undo_approval">Deshacer</button>'
                . '</form></div>';
        } elseif ($undone !== '') {
            $success_notice = '<div class="cleg-admin-notice is-success"><strong>Aprobacion deshecha.</strong></div>';
        } elseif ($manual_created === 1) {
            $success_notice = '<div class="cleg-admin-notice is-success"><strong>Jornada manual creada para revision.</strong><span>Debe aprobarse antes de aparecer en Payroll. Payroll solo muestra jornadas con estado Approved.</span></div>';
        } elseif ($saved !== '') {
            $success_notice = '<div class="cleg-admin-notice is-success"><strong>Cambios guardados.</strong>' . ($blocked > 0 ? '<span>' . esc_html($blocked) . ' fila(s) no se procesaron por faltar Job Site, salida o permiso.</span>' : '') . '</div>';
        }

        $notices_html = ($notice !== '' ? '<div class="cleg-admin-notice is-error">' . esc_html($notice) . '</div>' : '') . $success_notice;
        $html = '<section class="cleg-admin-ui"><main class="cleg-admin-main cleg-admin-shell">';

        $period = cleg_admin_rrhh_period_key();
        $period_bounds = cleg_admin_rrhh_period_bounds($period);
        $period_label = cleg_admin_rrhh_period_label($period);
        $next_period_label = cleg_admin_rrhh_period_label(cleg_admin_rrhh_period_next($period));

        $employees = cleg_admin_employees();
        $time_entries_all = cleg_admin_time_records('', 300);
        $open_entries_all = cleg_admin_time_records('{Clock Out Time}=BLANK()', 300);
        $job_sites = cleg_admin_job_sites();
        $hr_requests_all = cleg_admin_hr_requests(300);

        if (is_wp_error($employees) || is_wp_error($time_entries_all) || is_wp_error($open_entries_all) || is_wp_error($job_sites)) {
            return $html . $notices_html . cleg_admin_error($employees, $time_entries_all, $open_entries_all, $job_sites) . cleg_admin_page_close();
        }

        if (is_wp_error($hr_requests_all)) {
            $hr_requests_all = array();
        }

        $time_entries = cleg_admin_rrhh_filter_time_entries($time_entries_all, $period_bounds);
        $open_entries = cleg_admin_rrhh_filter_time_entries($open_entries_all, $period_bounds);
        $hr_requests = cleg_admin_rrhh_filter_requests($hr_requests_all, $period_bounds);

        $active_employees = 0;
        $missing_wp_id = 0;

        foreach ($employees as $employee) {
            if (cleg_admin_field($employee, 'Status') === 'Active') {
                $active_employees++;
            }

            if (cleg_admin_field($employee, 'Role') === 'Trabajador' && cleg_admin_field($employee, 'WordPress User ID') === '') {
                $missing_wp_id++;
            }
        }

        $status_counts = cleg_admin_status_counts($time_entries);
        $open_shift_count = is_array($open_entries) ? count($open_entries) : 0;
        $status_counts['Open'] = $open_shift_count;
        $request_counts = cleg_admin_request_status_counts($hr_requests);
        $shared_devices = 0;
        $missing_gps = 0;
        $job_counts = array();
        $project_summary = cleg_admin_project_cost_summary($time_entries, $employees);
        $total_project_hours = 0;
        $total_project_cost = 0;
        $active_project_count = 0;
        $open_project_count = 0;
        $highest_project = '';
        $highest_project_hours = 0;
        $sin_project_hours = 0;

        foreach ($project_summary as $project_name => $project) {
            $total_project_hours += (float) $project['hours'];
            $total_project_cost += (float) $project['cost'];

            if ((float) $project['hours'] > 0 || (int) $project['open'] > 0) {
                $active_project_count++;
            }

            if ((int) $project['open'] > 0) {
                $open_project_count++;
            }

            if ((float) $project['hours'] > $highest_project_hours) {
                $highest_project = (string) $project_name;
                $highest_project_hours = (float) $project['hours'];
            }

            if (strtolower((string) $project_name) === 'sin proyecto' || strtolower((string) $project_name) === 'sin job site') {
                $sin_project_hours += (float) $project['hours'];
            }
        }

        foreach ($time_entries as $record) {
            $flags = cleg_admin_field($record, 'Audit Flags');
            $job = cleg_admin_field($record, 'Job Site Name', 'Sin Job Site');
            $job_counts[$job] = ($job_counts[$job] ?? 0) + 1;

            if (strpos($flags, 'Shared Device Detected') !== false) {
                $shared_devices++;
            }

            if (strpos($flags, 'Missing GPS') !== false) {
                $missing_gps++;
            }
        }

        arsort($job_counts);
        $job_counts = array_slice($job_counts, 0, 6, true);

        $status_chart = array(
            'Abiertas' => array('value' => $status_counts['Open'], 'href' => cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'open'))),
            'Pendientes' => array('value' => $status_counts['Pending Review'], 'href' => cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'pending'))),
            'Aprobadas' => array('value' => $status_counts['Approved'], 'href' => cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'approved'))),
            'Eliminadas' => array('value' => $status_counts['Deleted'], 'href' => cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'deleted'))),
        );

        $job_chart = array();
        foreach ($job_counts as $job => $count) {
            $job_chart[$job] = array(
                'value' => $count,
                'href' => cleg_admin_context_url('/admin-job-sites/', array('cleg_project' => $job)),
            );
        }

        $hour_attention_count = max((int) $status_counts['Pending Review'], (int) $status_counts['Open']);
        $other_attention_count = (int) $request_counts['Pending'] + (int) $missing_gps + (int) $shared_devices + (int) $missing_wp_id;
        $attention_count = $hour_attention_count + $other_attention_count;
        $attention_detail = $hour_attention_count . ' horas/rev + ' . $other_attention_count . ' alertas - ' . strtolower($period_label);
        $attention_label = $attention_count > 0 ? 'Atencion requerida' : 'Todo estable';
        $hero_state = $attention_count > 0 ? 'is-hot' : 'is-calm';

        $mobile_metrics = array(
            'requests_pending' => $request_counts['Pending'],
            'reviews_pending'  => $status_counts['Pending Review'],
            'attention_count'   => $attention_count,
            'attention_detail'  => $attention_detail,
        );
        $html .= cleg_admin_mobile_field_today($open_entries, $employees, $time_entries, $mobile_metrics, $hr_requests);
        $html .= cleg_admin_mobile_gps_drawer();

        $html .= '<div class="cleg-dashboard-desktop">';

        if (function_exists('cleg_admin_page_header')) {
            $html .= cleg_admin_page_header('Control RRHH', '', array(
                'label' => $attention_label,
                'value' => $attention_count,
                'detail' => $attention_detail,
                'state' => $hero_state,
            ));
        } else {
            $html .= '<section class="cleg-command-center ' . esc_attr($hero_state) . '">'
                . '<div class="cleg-command-copy"><h2>Control RRHH</h2></div>'
                . '<div class="cleg-command-score"><span>' . esc_html($attention_label) . '</span><strong>' . esc_html($attention_count) . '</strong><small>' . esc_html($attention_detail) . '</small></div>'
                . '</section>';
        }

        $html .= cleg_admin_nav('dashboard') . $notices_html;

        $field_ops_enabled = cleg_admin_dashboard_module_enabled('field_ops');
        $forms_requests_enabled = cleg_admin_dashboard_module_enabled('forms_requests');
        $projects_enabled = cleg_admin_dashboard_module_enabled('projects_work_orders');
        $payroll_enabled = cleg_admin_dashboard_module_enabled('payroll');

        $metric_cards = ($field_ops_enabled ? cleg_admin_metric_link_when_active('Horas pendientes', $status_counts['Pending Review'], cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'pending')), 'accion inmediata') : '')
            . ($field_ops_enabled ? cleg_admin_metric_link_when_active('Jornadas abiertas', $status_counts['Open'], cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'open')), 'field activo') : '')
            . ($forms_requests_enabled ? cleg_admin_metric_link_when_active('Solicitudes pendientes', $request_counts['Pending'], home_url('/admin-solicitudes/'), 'ausencias y novedades') : '');

        $attention_cards = '';
        $attention_items = array(
            array('label' => 'Dispositivos compartidos', 'value' => $shared_devices, 'href' => home_url('/admin-tiempo-real/'), 'tone' => $shared_devices > 0 ? 'is-warn' : 'is-ok', 'module' => 'field_ops'),
            array('label' => 'Sin proyecto', 'value' => $sin_project_hours, 'display' => number_format($sin_project_hours, 1) . ' h', 'href' => cleg_admin_context_url('/admin-job-sites/', array('cleg_project' => 'Sin proyecto')), 'tone' => $sin_project_hours > 0 ? 'is-bad' : 'is-ok', 'module' => 'projects_work_orders'),
            array('label' => 'Alertas GPS', 'value' => $missing_gps, 'href' => home_url('/admin-tiempo-real/'), 'tone' => $missing_gps > 0 ? 'is-warn' : 'is-ok', 'module' => 'field_ops'),
        );
        foreach ($attention_items as $item) {
            if (!cleg_admin_dashboard_module_enabled($item['module'] ?? '')) {
                continue;
            }
            if ((float) $item['value'] <= 0) {
                continue;
            }
            $attention_cards .= '<a class="cleg-metric cleg-metric-link cleg-attention-card ' . esc_attr($item['tone']) . '" href="' . esc_url($item['href']) . '"><strong>' . esc_html($item['display'] ?? $item['value']) . '</strong><span>' . esc_html($item['label']) . '</span><small>Ver detalle</small></a>';
        }

        if ($metric_cards !== '' || $attention_cards !== '') {
            $html .= '<div class="cleg-metrics-grid cleg-executive-metrics">' . $metric_cards . $attention_cards . '</div>';
        }

        $priority_links = '';
        if ($field_ops_enabled && (int) $status_counts['Pending Review'] > 0) {
            $priority_links .= '<a href="' . esc_url(cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'pending'))) . '"><b>' . esc_html($status_counts['Pending Review']) . '</b><span>horas por aprobar o corregir</span><em>Revision</em></a>';
        }
        if ($field_ops_enabled && (int) $status_counts['Open'] > 0) {
            $priority_links .= '<a href="' . esc_url(cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'open'))) . '"><b>' . esc_html($status_counts['Open']) . '</b><span>jornadas abiertas ahora</span><em>Tiempo real</em></a>';
        }
        if ($projects_enabled && (int) $active_project_count > 0) {
            $priority_links .= '<a href="' . esc_url(home_url('/admin-job-sites/')) . '"><b>' . esc_html($active_project_count) . '</b><span>proyectos con movimiento</span><em>Proyectos</em></a>';
        }
        if ($payroll_enabled && (float) $total_project_cost > 0) {
            $priority_links .= '<a href="' . esc_url(home_url('/payroll-rrhh/')) . '"><b>' . esc_html(cleg_admin_money($total_project_cost)) . '</b><span>costo estimado conectado</span><em>Payroll</em></a>';
        }
        $active_status_chart = array_filter($status_chart, function ($item) {
            return (float) ($item['value'] ?? 0) > 0;
        });
        if ($priority_links !== '' || !empty($active_status_chart)) {
            $html .= '<div class="cleg-dashboard-layout">';
            if ($priority_links !== '') {
                $html .= '<div class="cleg-panel cleg-focus-panel"><div class="cleg-panel-head"><div><h2>Prioridad de hoy</h2></div></div><div class="cleg-priority-list">' . $priority_links . '</div></div>';
            }
            if (!empty($active_status_chart)) {
                $html .= '<div class="cleg-panel cleg-pulse-panel"><div class="cleg-panel-head"><div><h2>Pulso operativo</h2></div></div>' . cleg_admin_bar_chart('Estado de horas', $active_status_chart) . '</div>';
            }
            $html .= '</div>';
        }

        $project_showcase = '';
        $project_cards = 0;
        foreach ($projects_enabled ? $project_summary : array() as $project => $data) {
            if ($project_cards >= 4) {
                break;
            }
            if ((float) $data['hours'] <= 0 && (int) $data['open'] <= 0) {
                continue;
            }
            $project_cards++;
            $project_url = cleg_admin_context_url('/admin-job-sites/', array('cleg_project' => $project));
            $tone = (int) $data['open'] > 0 ? 'is-warn' : (((string) $project === 'Sin proyecto' || (string) $project === 'Sin Job Site') ? 'is-bad' : 'is-ok');
            $project_showcase .= '<a class="cleg-project-tile ' . esc_attr($tone) . '" href="' . esc_url($project_url) . '"><span>' . esc_html((string) $project) . '</span><strong>' . esc_html(cleg_admin_hours_label((float) $data['hours'])) . '</strong><small>' . esc_html(cleg_admin_money($data['cost'])) . ' estimado</small><em>' . esc_html(count($data['employees'])) . ' trabajadores</em></a>';
        }
        if ($project_showcase !== '') {
            $html .= '<section class="cleg-panel cleg-project-showcase"><div class="cleg-panel-head"><div><h2>Proyectos con movimiento</h2></div><a class="cleg-row-action" href="' . esc_url(home_url('/admin-job-sites/')) . '">Ver todos</a></div><div class="cleg-project-showcase-grid">' . $project_showcase . '</div></section>';
        }

        $dashboard_bottom = '';
        if ($forms_requests_enabled && !empty($hr_requests)) {
            $request_feed = '';
            foreach (array_slice(cleg_admin_sort_requests_by_submitted_date((array) $hr_requests), 0, 4) as $request) {
                $request_feed .= '<a href="' . esc_url(home_url('/admin-solicitudes/')) . '"><b>' . esc_html(cleg_admin_field($request, 'Employee Name', cleg_admin_field($request, 'Portal Username'))) . '</b><span>' . esc_html(cleg_admin_field($request, 'Request Type', 'Solicitud')) . ' - ' . esc_html(cleg_admin_request_submitted_date($request)) . '</span>' . cleg_admin_request_pill(cleg_admin_field($request, 'Status')) . '</a>';
            }
            if ($request_feed !== '') {
                $dashboard_bottom .= '<div class="cleg-panel cleg-requests-preview"><div class="cleg-panel-head"><div><h2>Solicitudes recientes</h2></div><a class="cleg-row-action" href="' . esc_url(home_url('/admin-solicitudes/')) . '">Ver todas</a></div><div class="cleg-compact-feed">' . $request_feed . '</div></div>';
            }
        }

        $activity_feed = '';
        foreach ($field_ops_enabled ? array_slice((array) $time_entries, 0, 5) : array() as $record) {
            $clock_out = cleg_admin_field($record, 'Clock Out Time');
            $activity_feed .= '<a href="' . esc_url(home_url('/admin-horas/')) . '"><b>' . esc_html(cleg_admin_field($record, 'Employee Name')) . '</b><span>' . esc_html(cleg_admin_field($record, 'Job Site Name', 'Sin proyecto')) . ' - ' . esc_html(cleg_admin_date(cleg_admin_field($record, 'Clock In Time'))) . '</span>' . cleg_admin_status_pill($clock_out === '' ? 'Open' : cleg_admin_field($record, 'Approval Status')) . '</a>';
        }
        if ($activity_feed !== '') {
            $dashboard_bottom .= '<div class="cleg-panel cleg-activity-preview"><div class="cleg-panel-head"><div><h2>Actividad reciente</h2></div><a class="cleg-row-action" href="' . esc_url(home_url('/admin-tiempo-real/')) . '">Abrir</a></div><div class="cleg-compact-feed">' . $activity_feed . '</div></div>';
        }
        if ($dashboard_bottom !== '') {
            $html .= '<div class="cleg-admin-grid cleg-admin-grid-aside cleg-dashboard-bottom">' . $dashboard_bottom . '</div>';
        }

        return $html . '</div>' . cleg_admin_page_close();
    }
}

