/**
 * CLEG 05B - Admin Revision de Horas v2.1
 *
 * Pantalla /admin-horas/, shortcode [cleg_admin_horas] y acciones de revision de horas.
 * Generado desde CLEG 05 v2.18 durante refactor por pantalla.
 * No tocar CLEG 04 ni funciones del panel trabajador.
 * Visual: CLEG 03B - RRHH Design System.
 * v1.1 agrupa visualmente marcajes del mismo empleado/dia para jornadas partidas por almuerzo.
 * v1.2 mantiene apertura automatica en la semana pendiente mas antigua, pero siempre incluye la semana actual real en el filtro aunque sea lunes.
 * v1.3 integra jornadas manuales dentro de Pendientes y bloquea salidas manuales en otro dia.
 * v1.4 filtra por hora efectiva de la jornada: ajuste admin si existe, si no hora base.
 * v1.5 refuerza lectura GPS en detalle: usa link o lat/lng, verde dentro de zona, rojo con millas fuera.
 * v1.6 separa jornadas abiertas de pendientes: sin salida queda Open, no Pending Review.
 * v1.7 abre Pendientes y Abiertas en su semana mas antigua propia al cambiar de submenu y centra avisos guardados.
 * v1.8 elimina autosave en edicion de horas y muestra auditoria estructurada por actor, antes, despues y nota.
 * v1.9 pule revision visual: avisos por linea, separadores continuos y auditoria en lenguaje humano.
 * v2.1 muestra Cerrar jornada como accion primaria visible y retira Aprobar en abiertas.
 * v2.2 filtra auditoria para mostrar solo cambios reales con antes/despues distinto.
 */

if (!defined('ABSPATH')) {
    exit;
}


if (!function_exists('cleg_admin_status_filter_formula')) {
    function cleg_admin_status_filter_formula($status) {
        if ($status === 'approved') {
            return "{Approval Status}='Approved'";
        }

        if ($status === 'open') {
            return "OR({Approval Status}='Open',{Clock Out Time}=BLANK())";
        }

        if ($status === 'manual') {
            return "{Approval Status}='Manual Need Review'";
        }

        if ($status === 'deleted') {
            return "{Approval Status}='Deleted'";
        }

        if ($status === 'closed') {
            return "{Approval Status}='Payroll Closed'";
        }

        if ($status === 'all') {
            return "AND({Approval Status}!='Deleted',{Approval Status}!='Payroll Closed',{Approval Status}!='Rejected')";
        }

        return "OR({Approval Status}='Pending Review',{Approval Status}='Manual Need Review')";
    }
}

if (!function_exists('cleg_admin_week_bounds')) {
    function cleg_admin_week_bounds($week = '') {
        $tz = wp_timezone();
        try {
            if ($week !== '') {
                $base = new DateTimeImmutable($week . ' 00:00:00', $tz);
            } else {
                $base = new DateTimeImmutable('now', $tz);
            }
        } catch (Exception $e) {
            $base = new DateTimeImmutable('now', $tz);
        }

        $weekday = (int) $base->format('w');
        $week_start = $base->modify('-' . $weekday . ' days')->setTime(0, 0, 0);
        $week_end = $week_start->modify('+6 days')->setTime(23, 59, 59);

        return array($week_start, $week_end);
    }
}

if (!function_exists('cleg_admin_effective_clock_in_value')) {
    function cleg_admin_effective_clock_in_value($record) {
        return cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
    }
}

if (!function_exists('cleg_admin_effective_clock_in_formula')) {
    function cleg_admin_effective_clock_in_formula() {
        return "IF({Admin Adjusted Clock In Time},{Admin Adjusted Clock In Time},{Clock In Time})";
    }
}

if (!function_exists('cleg_admin_utc_iso_from_local')) {
    function cleg_admin_utc_iso_from_local($date) {
        if (!($date instanceof DateTimeInterface)) {
            return '';
        }

        return $date->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s.000\Z');
    }
}

if (!function_exists('cleg_admin_record_in_week')) {
    function cleg_admin_record_in_week($record, $week_start, $week_end) {
        $clock_in = cleg_admin_effective_clock_in_value($record);
        if ($clock_in === '' || !($week_start instanceof DateTimeInterface) || !($week_end instanceof DateTimeInterface)) {
            return false;
        }

        try {
            $date = new DateTimeImmutable($clock_in, wp_timezone());
        } catch (Exception $e) {
            return false;
        }

        return $date >= $week_start && $date <= $week_end;
    }
}

if (!function_exists('cleg_admin_filter_records_by_week')) {
    function cleg_admin_filter_records_by_week($records, $week_start, $week_end) {
        if (is_wp_error($records)) {
            return $records;
        }

        return array_values(array_filter((array) $records, function ($record) use ($week_start, $week_end) {
            return cleg_admin_record_in_week($record, $week_start, $week_end);
        }));
    }
}

if (!function_exists('cleg_admin_oldest_review_week_start')) {
    function cleg_admin_oldest_review_week_start($status = 'pending') {
        $status = sanitize_key($status);
        if ($status === 'manual') {
            $status = 'pending';
        }

        $records = cleg_field_ops_records(CLEG_AIRTABLE_TIME_TABLE, array(
            'pageSize' => 100,
            'filterByFormula' => cleg_admin_formula_and(array(
                cleg_admin_status_filter_formula($status),
                "OR({Clock In Time}!='',{Admin Adjusted Clock In Time}!='')",
            )),
            'sort[0][field]' => 'Clock In Time',
            'sort[0][direction]' => 'asc',
        ));

        if (is_wp_error($records) || empty($records)) {
            list($fallback_start) = cleg_admin_week_bounds('');
            return $fallback_start->format('Y-m-d');
        }

        $oldest = null;
        foreach ($records as $record) {
            $clock_in = cleg_admin_effective_clock_in_value($record);
            if ($clock_in === '') {
                continue;
            }

            try {
                $date = new DateTimeImmutable($clock_in, wp_timezone());
            } catch (Exception $e) {
                continue;
            }

            if ($oldest === null || $date < $oldest) {
                $oldest = $date;
            }
        }

        if (!$oldest) {
            list($fallback_start) = cleg_admin_week_bounds('');
            return $fallback_start->format('Y-m-d');
        }

        $weekday = (int) $oldest->format('w');
        return $oldest->modify('-' . $weekday . ' days')->format('Y-m-d');
    }
}

if (!function_exists('cleg_admin_oldest_pending_week_start')) {
    function cleg_admin_oldest_pending_week_start() {
        return cleg_admin_oldest_review_week_start('pending');
    }
}

if (!function_exists('cleg_admin_review_week_options')) {
    function cleg_admin_review_week_options($selected_start, $count = 18, $status = 'pending') {
        $options = array();
        list($current_start) = cleg_admin_week_bounds('');
        $status = sanitize_key($status);
        $oldest_review = cleg_admin_oldest_review_week_start($status);
        $oldest_label = $status === 'open' ? 'Abierta mas antigua: ' : ($status === 'pending' ? 'Pendiente mas antigua: ' : 'Registro mas antiguo: ');
        $base = $current_start;

        for ($i = 0; $i < $count; $i++) {
            $start = $base->modify('-' . $i . ' weeks');
            $end = $start->modify('+6 days');
            $key = $start->format('Y-m-d');
            $prefix = $i === 0 ? 'Semana actual: ' : ($i === 1 ? 'Semana pasada: ' : 'Semana: ');
            $options[$key] = $prefix . $start->format('m/d/Y') . ' - ' . $end->format('m/d/Y');
        }

        if ($oldest_review !== '' && !isset($options[$oldest_review])) {
            try {
                $oldest = new DateTimeImmutable($oldest_review . ' 00:00:00', wp_timezone());
                $options[$oldest_review] = $oldest_label . $oldest->format('m/d/Y') . ' - ' . $oldest->modify('+6 days')->format('m/d/Y');
            } catch (Exception $e) {
                // Keep generated options only.
            }
        }

        if ($selected_start !== '' && !isset($options[$selected_start])) {
            try {
                $selected = new DateTimeImmutable($selected_start . ' 00:00:00', wp_timezone());
                $options[$selected_start] = 'Semana: ' . $selected->format('m/d/Y') . ' - ' . $selected->modify('+6 days')->format('m/d/Y');
            } catch (Exception $e) {
                // Keep generated options only.
            }
        }

        return $options;
    }
}

if (!function_exists('cleg_admin_review_filter_formula')) {
    function cleg_admin_review_filter_formula($status, $employee = '', $job_site = '', $week = '') {
        $parts = array(cleg_admin_status_filter_formula($status));
        list($week_start, $week_end) = cleg_admin_week_bounds($week);
        $effective_clock_in = cleg_admin_effective_clock_in_formula();
        $range_start = cleg_admin_utc_iso_from_local($week_start);
        $range_end = cleg_admin_utc_iso_from_local($week_end);
        $parts[] = "OR(IS_SAME(" . $effective_clock_in . ",'" . $range_start . "'),IS_AFTER(" . $effective_clock_in . ",'" . $range_start . "'))";
        $parts[] = "OR(IS_SAME(" . $effective_clock_in . ",'" . $range_end . "'),IS_BEFORE(" . $effective_clock_in . ",'" . $range_end . "'))";

        if ($employee !== '') {
            $safe_employee = cleg_admin_formula_text($employee);
            $parts[] = "OR(FIND('" . $safe_employee . "',{Employee Name})>0,FIND('" . $safe_employee . "',{Portal Username})>0)";
        }

        if ($job_site !== '') {
            $parts[] = "{Job Site Name}='" . cleg_admin_formula_text($job_site) . "'";
        }

        return cleg_admin_formula_and($parts);
    }
}

if (!function_exists('cleg_admin_filter_tabs')) {
    function cleg_admin_filter_tabs($active = 'pending') {
        $items = array(
            'pending' => 'Pendientes',
            'approved' => 'Aprobadas',
            'open' => 'Abiertas',
            'deleted' => 'Eliminadas',
            'closed' => 'Payroll Closed',
        );

        $html = '<nav class="cleg-subnav" aria-label="Filtro de horas">';
        foreach ($items as $key => $label) {
            $args = $_GET;
            $args['cleg_status'] = $key;
            unset($args['_wp_http_referer']);
            if ($key !== $active) {
                unset($args['cleg_week'], $args['cleg_employee'], $args['cleg_job_site'], $args['cleg_refresh']);
            }
            $html .= '<a class="' . esc_attr($key === $active ? 'is-active' : '') . '" href="' . esc_url(cleg_admin_context_url('/admin-horas/', $args)) . '">' . esc_html($label) . '</a>';
        }
        return $html . '</nav>';
    }
}

if (!function_exists('cleg_admin_review_filters_form')) {
    function cleg_admin_review_filters_form($status, $employee, $job_site, $week_start, $week_end, $job_sites, $employees = array(), $option_records = array()) {
        $week_options = cleg_admin_review_week_options($week_start->format('Y-m-d'), 18, $status);
        $employee_options = array();
        $job_options = array();

        foreach ((array) $option_records as $record) {
            $name = cleg_admin_field($record, 'Employee Name');
            $username = cleg_admin_field($record, 'Portal Username');
            $value = $username !== '' ? $username : $name;
            if ($value !== '') {
                $employee_options[$value] = trim($name . ($username !== '' ? ' (' . $username . ')' : ''));
            }

            $record_job = cleg_admin_field($record, 'Job Site Name');
            if ($record_job !== '') {
                $job_options[$record_job] = $record_job;
            }
        }

        asort($employee_options);
        asort($job_options);

        $html = '<form class="cleg-review-filters" method="get">'
            . '<input type="hidden" name="cleg_status" value="' . esc_attr($status) . '">'
            . '<label>Semana<select name="cleg_week" data-autofilter="1">';

        foreach ($week_options as $week_value => $week_label) {
            $html .= '<option value="' . esc_attr($week_value) . '" ' . selected($week_start->format('Y-m-d'), $week_value, false) . '>' . esc_html($week_label) . '</option>';
        }

        $html .= '</select></label>';

        if (!empty($employee_options)) {
            $html .= '<label>Empleado<select name="cleg_employee" data-autofilter="1"><option value="">Todos en esta pestaña</option>';

            foreach ($employee_options as $value => $label) {
                $html .= '<option value="' . esc_attr($value) . '" ' . selected($employee, $value, false) . '>' . esc_html($label) . '</option>';
            }

            $html .= '</select></label>';
        }

        if (!empty($job_options)) {
            $html .= '<label>Job Site<select name="cleg_job_site" data-autofilter="1"><option value="">Todos en esta pestaña</option>';

            foreach ($job_options as $name) {
                $html .= '<option value="' . esc_attr($name) . '" ' . selected($job_site, $name, false) . '>' . esc_html($name) . '</option>';
            }

            $html .= '</select></label>';
        }

        if ($employee !== '' || $job_site !== '') {
            $html .= '<a class="cleg-clear-filter" href="' . esc_url(cleg_admin_context_url('/admin-horas/', array('cleg_status' => $status, 'cleg_week' => $week_start->format('Y-m-d')))) . '">Limpiar filtro</a>';
        }

        $html .= '</form>';

        return $html;
    }
}

if (!function_exists('cleg_admin_review_kpi_cards')) {
    function cleg_admin_review_kpi_cards($ready_count, $open_count, $total_count) {
        $items = array(
            array('value' => (int) $ready_count, 'label' => 'listas para aprobar'),
            array('value' => (int) $open_count, 'label' => 'abiertas / sin salida'),
            array('value' => (int) $total_count, 'label' => 'total por revisar'),
        );

        $cards = '';
        foreach ($items as $item) {
            if ((int) $item['value'] <= 0) {
                continue;
            }
            $cards .= '<div><strong>' . esc_html((int) $item['value']) . '</strong><span>' . esc_html($item['label']) . '</span></div>';
        }

        return $cards !== '' ? '<div class="cleg-mobile-summary">' . $cards . '</div>' : '';
    }
}

