if (!function_exists('cleg_admin_bulk_review_bar')) {
    function cleg_admin_bulk_review_bar($status = 'pending') {
        if ($status === 'closed') {
            return '';
        }

        $primary = '';
        if (cleg_admin_current_user_can_approve_hours() && in_array($status, array('pending', 'manual', 'open'), true)) {
            $primary = '<button type="submit" name="cleg_admin_action" value="bulk_approve">Aprobar seleccionadas</button>';
        } elseif (cleg_admin_current_user_can_correct_hours() && in_array($status, array('approved', 'deleted'), true)) {
            $primary = '<button type="submit" name="cleg_admin_action" value="bulk_reopen">Mandar a revision</button>';
        }

        $delete_button = $status !== 'deleted' && cleg_admin_current_user_can_delete_hours()
            ? '<button class="is-danger cleg-delete-btn" type="submit" name="cleg_admin_action" value="bulk_delete">Eliminar seleccionadas</button>'
            : '';

        if ($primary === '' && $delete_button === '') {
            return '<div class="cleg-bulk-review-bar is-readonly"><strong>Modo consulta</strong><span>No hay acciones masivas disponibles para esta cuenta.</span></div>';
        }

        return '<form id="cleg-bulk-time-form" class="cleg-bulk-review-bar" method="post">'
            . wp_nonce_field('cleg_admin_time_action', 'cleg_admin_nonce', true, false)
            . '<strong>Seleccionadas</strong>'
            . $primary
            . $delete_button
            . '<div class="cleg-delete-popover"><strong>Motivo</strong><label><input type="radio" name="delete_reason" value="Error" checked> Error</label><label><input type="radio" name="delete_reason" value="Prueba de campo"> Prueba de campo</label><label><input type="radio" name="delete_reason" value="Otro"> Otro</label></div>'
            . '</form>';
    }
}

if (!function_exists('cleg_admin_manual_entry_form')) {
    function cleg_admin_manual_entry_form($employees = array(), $job_sites = array()) {
        if (!cleg_admin_current_user_can_correct_hours()) {
            return '';
        }

        $today = wp_date('Y-m-d');
        $html = '<details class="cleg-manual-entry"><summary>Agregar jornada manual</summary>'
            . '<form method="post">'
            . wp_nonce_field('cleg_admin_time_action', 'cleg_admin_nonce', true, false)
            . '<input type="hidden" name="cleg_admin_action" value="create_manual_entry">'
            . '<label>Empleado<select name="manual_employee" required><option value="">Seleccionar</option>';

        foreach ((array) $employees as $worker) {
            $status = cleg_admin_field($worker, 'Status');
            if (!in_array($status, array('Active', 'Activo'), true)) {
                continue;
            }

            $name = cleg_admin_field($worker, 'Employee Name');
            $username = cleg_admin_field($worker, 'Portal Username');
            if ($name === '' && $username === '') {
                continue;
            }

            $wp_user_id = cleg_admin_field($worker, 'WordPress User ID');
            $value = rawurlencode($name) . '|' . rawurlencode($username) . '|' . rawurlencode($wp_user_id);
            $label = trim($name . ($username !== '' ? ' (' . $username . ')' : ''));
            $html .= '<option value="' . esc_attr($value) . '">' . esc_html($label) . '</option>';
        }

        $html .= '</select></label><label>Job Site<select name="manual_job_site" required><option value="">Seleccionar</option>';

        foreach ((array) $job_sites as $site) {
            $name = cleg_admin_field($site, 'Job Site Name');
            if ($name !== '') {
                $html .= '<option value="' . esc_attr($name) . '">' . esc_html($name) . '</option>';
            }
        }

        $html .= '</select></label>'
            . '<label>Entrada<input type="datetime-local" name="manual_clock_in" value="' . esc_attr($today . 'T07:00') . '" required></label>'
            . '<label>Salida<input type="datetime-local" name="manual_clock_out" value="' . esc_attr($today . 'T15:30') . '" required></label>'
            . '<label>Motivo<select name="manual_reason"><option value="Olvido marcar">Olvido marcar</option><option value="Problema GPS">Problema GPS</option><option value="Empleado nuevo">Empleado nuevo</option><option value="Otro">Otro</option></select></label>'
            . '<button type="submit">Crear para revision</button>'
            . '</form></details>';

        return $html;
    }
}

if (!function_exists('cleg_admin_missing_job_site')) {
    function cleg_admin_missing_job_site($job_site) {
        $job_site = trim((string) $job_site);
        return $job_site === '' || in_array($job_site, array('Sin Job Site', 'Sin proyecto', 'Proyecto Temporal - Pendiente de Crear'), true);
    }
}

if (!function_exists('cleg_admin_review_memory_script')) {
    function cleg_admin_review_memory_script() {
        return <<<'HTML'
<script>
(function(){
  var key = 'cleg_admin_horas_scroll';
  if (window.location.pathname.indexOf('/admin-horas') === -1) return;
  document.addEventListener('DOMContentLoaded', function(){
    var saved = sessionStorage.getItem(key);
    if (saved) {
      sessionStorage.removeItem(key);
      setTimeout(function(){ window.scrollTo(0, parseInt(saved, 10) || 0); }, 80);
    }

    document.querySelectorAll('form').forEach(function(form){
      form.addEventListener('submit', function(){
        sessionStorage.setItem(key, String(window.scrollY || 0));
      });
    });

    document.querySelectorAll('.cleg-check-all').forEach(function(check){
      check.addEventListener('change', function(){
        document.querySelectorAll('input[name="cleg_bulk_ids[]"]').forEach(function(rowCheck){
          rowCheck.checked = check.checked;
        });
        updateBulkBar();
      });
    });

    function updateBulkBar(){
      var bar = document.querySelector('.cleg-bulk-review-bar');
      if (!bar) return;
      var selected = document.querySelectorAll('input[name="cleg_bulk_ids[]"]:checked').length;
      bar.classList.toggle('has-selection', selected > 0);
    }

    document.querySelectorAll('input[name="cleg_bulk_ids[]"]').forEach(function(check){
      check.addEventListener('change', updateBulkBar);
    });
    updateBulkBar();

    document.querySelectorAll('.cleg-review-filters select[data-autofilter="1"]').forEach(function(field){
      field.addEventListener('change', function(){
        sessionStorage.setItem(key, String(window.scrollY || 0));
        field.form.submit();
      });
    });

    document.querySelectorAll('.cleg-delete-btn').forEach(function(button){
      button.addEventListener('click', function(event){
        var form = button.closest('form');
        if (!form || form.classList.contains('cleg-confirm-delete')) return;
        event.preventDefault();
        form.classList.add('cleg-confirm-delete');
        button.textContent = 'Confirmar eliminar';
      });
    });

    document.querySelectorAll('.cleg-review-compact-table .cleg-row-details').forEach(function(details){
      var row = details.closest('tr');
      var shiftCell = details.closest('td');
      var jobCell = row ? row.querySelector('.cleg-job-site-cell') : null;
      if (!row || !shiftCell || !jobCell) return;

      function syncDetailLayout(){
        var isOpen = details.open;
        row.classList.toggle('cleg-details-open', isOpen);
        shiftCell.colSpan = isOpen ? 2 : 1;
        jobCell.hidden = isOpen;
      }

      details.addEventListener('toggle', syncDetailLayout);
      syncDetailLayout();
    });
  });
})();
</script>
HTML;
    }
}

if (!function_exists('cleg_admin_horas_shortcode')) {
    function cleg_admin_horas_shortcode() {
        $html = cleg_admin_page_open('horas', 'Revision de horas', '');

        if (strpos($html, 'cleg-admin-empty') !== false) {
            return $html;
        }

        $selected_status = cleg_admin_selected_status();
        if ($selected_status === 'manual') {
            $selected_status = 'pending';
        }
        $job_sites = cleg_admin_job_sites();
        $employees = cleg_admin_employees();
        $employee_filter = isset($_GET['cleg_employee']) ? sanitize_text_field(wp_unslash($_GET['cleg_employee'])) : '';
        $job_filter = isset($_GET['cleg_job_site']) ? sanitize_text_field(wp_unslash($_GET['cleg_job_site'])) : '';
        $week_filter = isset($_GET['cleg_week']) ? sanitize_text_field(wp_unslash($_GET['cleg_week'])) : '';
        if ($week_filter === '') {
            $week_filter = cleg_admin_oldest_review_week_start($selected_status);
        }
        list($week_start, $week_end) = cleg_admin_week_bounds($week_filter);
        $filter_options_formula = cleg_admin_review_filter_formula($selected_status, '', '', $week_start->format('Y-m-d'));
        $pending_formula = cleg_admin_review_filter_formula($selected_status, $employee_filter, $job_filter, $week_start->format('Y-m-d'));
        $filter_options_records = function_exists('cleg_field_ops_get_time_entries')
            ? cleg_field_ops_get_time_entries(array('formula' => $filter_options_formula, 'max_records' => 300))
            : cleg_admin_time_records($filter_options_formula, 300);
        $pending = function_exists('cleg_field_ops_get_time_entries')
            ? cleg_field_ops_get_time_entries(array('formula' => $pending_formula, 'max_records' => 100))
            : cleg_admin_time_records($pending_formula, 100);
        $filter_options_records = cleg_admin_filter_records_by_week($filter_options_records, $week_start, $week_end);
        $pending = cleg_admin_filter_records_by_week($pending, $week_start, $week_end);

        if (is_wp_error($pending) || is_wp_error($filter_options_records) || is_wp_error($job_sites) || is_wp_error($employees)) {
            return $html . cleg_admin_error($pending, $filter_options_records, $job_sites, $employees) . cleg_admin_page_close();
        }

        $open_count = 0;
        $ready_count = 0;
        foreach ($pending as $record) {
            if (cleg_admin_field($record, 'Clock Out Time') === '') {
                $open_count++;
            } else {
                $ready_count++;
            }
        }

        $html .= cleg_admin_review_notice_style();
        $html .= cleg_admin_filter_tabs($selected_status);
        $html .= cleg_admin_review_filters_form($selected_status, $employee_filter, $job_filter, $week_start, $week_end, $job_sites, $employees, $filter_options_records);
        $html .= cleg_admin_review_kpi_cards($ready_count, $open_count, count($pending));
        $panel_title = $selected_status === 'approved' ? 'Horas aprobadas' : ($selected_status === 'deleted' ? 'Horas eliminadas' : ($selected_status === 'closed' ? 'Payroll Closed' : ($selected_status === 'open' ? 'Jornadas abiertas' : 'Horas pendientes')));
        $html .= '<div class="cleg-panel cleg-review-panel"><h2>' . esc_html($panel_title) . '</h2>';
        if ($selected_status === 'pending') {
            $html .= cleg_admin_manual_entry_form($employees, $job_sites);
        }
        $html .= cleg_admin_bulk_review_bar($selected_status);
        $html .= cleg_admin_mobile_review_cards($pending, $job_sites);
        $html .= cleg_admin_review_table($pending, $job_sites);
        $html .= '</div>';

        return $html . cleg_admin_page_close();
    }
}

