if (!function_exists('cleg_admin_hours_float')) {
    function cleg_admin_hours_float($clock_in, $clock_out) {
        if ($clock_in === '' || $clock_out === '') {
            return 0;
        }

        $start = strtotime($clock_in);
        $end = strtotime($clock_out);
        if (!$start || !$end || $end <= $start) {
            return 0;
        }

        return round(($end - $start) / 3600, 2);
    }
}

if (!function_exists('cleg_admin_format_hours')) {
    function cleg_admin_format_hours($hours) {
        $total_minutes = (int) round(max(0, (float) $hours) * 60);
        $whole_hours = intdiv($total_minutes, 60);
        $minutes = $total_minutes % 60;

        if ($minutes === 0) {
            return $whole_hours . 'h';
        }

        return $whole_hours . 'h ' . $minutes . ' min';
    }
}

if (!function_exists('cleg_admin_group_time_records_by_day')) {
    function cleg_admin_group_time_records_by_day($records) {
        $groups = array();

        foreach ($records as $record) {
            $clock_in = cleg_admin_effective_clock_in($record);
            $timestamp = $clock_in !== '' ? strtotime($clock_in) : false;
            $day_key = $timestamp ? wp_date('Y-m-d', $timestamp) : 'sin-fecha';
            $identity = cleg_admin_field($record, 'WordPress User ID');
            if ($identity === '') {
                $identity = cleg_admin_field($record, 'Portal Username');
            }
            if ($identity === '') {
                $identity = cleg_admin_field($record, 'Employee Name');
            }
            $key = sanitize_title((string) $identity . '-' . $day_key);

            if (!isset($groups[$key])) {
                $groups[$key] = array(
                    'records' => array(),
                    'timestamp' => $timestamp ? (int) $timestamp : 0,
                );
            }
            $groups[$key]['records'][] = $record;
        }

        uasort($groups, function ($a, $b) {
            return (int) ($a['timestamp'] ?? 0) <=> (int) ($b['timestamp'] ?? 0);
        });

        foreach ($groups as &$group) {
            usort($group['records'], function ($a, $b) {
                return strtotime(cleg_admin_effective_clock_in($a)) <=> strtotime(cleg_admin_effective_clock_in($b));
            });

            $hours = 0;
            $segments = array();
            $job_site_segments = array();
            $job_sites = array();
            foreach ($group['records'] as $record) {
                $clock_in = cleg_admin_effective_clock_in($record);
                $clock_out = cleg_admin_effective_clock_out($record);
                $hours += cleg_admin_hours_float($clock_in, $clock_out);
                $segments[] = trim(cleg_admin_date($clock_in) . ' - ' . ($clock_out !== '' ? cleg_admin_date($clock_out) : 'Salida pendiente'));
                $job_site = cleg_admin_field($record, 'Job Site Name', 'Sin Job Site');
                $job_site_segments[] = $job_site;
                $job_sites[$job_site] = true;
            }

            $first = $group['records'][0] ?? array();
            $first_clock = cleg_admin_effective_clock_in($first);
            $group['count'] = count($group['records']);
            $group['hours'] = $hours;
            $group['date_label'] = $first_clock !== '' ? wp_date('m/d/Y', strtotime($first_clock)) : 'Sin fecha';
            $group['segments'] = $segments;
            $group['job_site_segments'] = $job_site_segments;
            $group['segments_label'] = implode(' / ', $segments);
            $group['job_sites'] = implode(' / ', array_keys($job_sites));
        }
        unset($group);

        return array_values($groups);
    }
}

