                    . '<div class="cleg-time-edit"><div class="cleg-time-edit-head"><div><small>Entrada</small><b>' . esc_html(cleg_admin_date($clock_in)) . '</b></div><span class="cleg-time-kind">' . esc_html($adjusted_in_value !== '' ? 'Corregida' : 'Original') . '</span>' . cleg_admin_gps_mini($record, 'in') . '</div>' . (!$is_closed ? cleg_admin_inline_time_input($record, 'admin_adjusted_clock_in', $clock_in, $form_id, 'Cambiar entrada') : '') . '</div>'
                    . '<div class="cleg-time-edit"><div class="cleg-time-edit-head"><div><small>Salida</small><b>' . esc_html($clock_out !== '' ? cleg_admin_date($clock_out) : 'Abierta') . '</b></div><span class="cleg-time-kind">' . esc_html($adjusted_out_value !== '' ? 'Corregida' : 'Original') . '</span>' . cleg_admin_gps_mini($record, 'out') . '</div>' . (!$is_closed ? cleg_admin_inline_time_input($record, 'admin_adjusted_clock_out', $clock_out, $form_id, 'Cambiar salida') : '') . '</div>'
                    . (!$is_closed || $manual_note !== '' ? '<details class="cleg-review-notes"><summary>Notas</summary><div>' . ($manual_note !== '' ? '<p class="cleg-worker-note"><strong>Nota trabajador:</strong> ' . esc_html($manual_note) . '</p>' : '') . (!$is_closed ? '<label>Interna<textarea name="admin_adjustment_note" form="' . esc_attr($form_id) . '" rows="2" placeholder="Motivo o comentario interno"></textarea></label><label>Visible empleado<textarea name="employee_visible_note" form="' . esc_attr($form_id) . '" rows="2" placeholder="Mensaje visible al trabajador"></textarea></label>' : '') . '</div></details>' : '')
                . '</div>'
                . cleg_admin_review_form($id, $record, $job_sites, $form_id)
                . '</section>';
        }
        return $html . '</div>';
    }
}

