if (!function_exists('cleg_admin_group_audit_summary_html')) {
    function cleg_admin_group_audit_summary_html($records) {
        $notes = array();
        foreach ((array) $records as $record) {
            $audit = trim((string) cleg_admin_field($record, 'Admin Notes'));
            if ($audit !== '') {
                $notes[] = $audit;
            }
        }

        if (empty($notes)) {
            return '<span class="cleg-muted">Sin auditoria</span>';
        }

        $flat = trim(implode("\n", $notes));
        $normalized = preg_replace('/\s+(?=\[\d{2}\/\d{2}\/\d{4}\s+\d{1,2}:\d{2}\s+(?:AM|PM)\])/', "\n", $flat);
        $rows = array_filter(array_map('trim', preg_split('/\r\n|\r|\n/', (string) $normalized)));
        $rows = array_values(array_filter($rows, 'cleg_admin_audit_row_has_real_change'));
        if (empty($rows)) {
            return '<span class="cleg-muted">Sin cambios reales</span>';
        }

        $normalized = implode("\n", $rows);
        $last = end($rows);
        $summary = $last ? cleg_admin_audit_summary_sentence((string) $last) : 'Ver auditoria';

        return '<details class="cleg-audit-summary"><summary>' . esc_html($summary) . '</summary><div class="cleg-audit-summary-body">' . cleg_admin_audit_trail_html($normalized) . '</div></details>';
    }
}

if (!function_exists('cleg_admin_gps_links')) {
    function cleg_admin_gps_links($record) {
        $links = array();

        foreach (array('in' => 'GPS entrada', 'out' => 'GPS salida') as $kind => $label_base) {
            $point = cleg_admin_gps_point($record, $kind);
            if (!$point['outside'] || $point['map'] === '') {
                continue;
            }

            $label = $label_base;
            $miles = cleg_admin_meters_to_miles_label($point['distance']);
            if ($miles !== '') {
                $label .= ' (' . $miles . ')';
            }
            $links[] = '<a href="' . esc_url($point['map']) . '" target="_blank" rel="noopener">' . esc_html($label) . '</a>';
        }

        if (empty($links)) {
            return '';
        }

        return '<div class="cleg-gps-links"><strong>Fuera de zona:</strong> ' . implode(' ', $links) . '</div>';
    }
}

if (!function_exists('cleg_admin_gps_point')) {
    function cleg_admin_gps_point($record, $kind) {
        $is_in = $kind === 'in';
        $lat_fields = $is_in ? array('Clock In Latitude', 'Clock In GPS Latitude', 'Latitude') : array('Clock Out Latitude', 'Clock Out GPS Latitude');
        $lng_fields = $is_in ? array('Clock In Longitude', 'Clock In GPS Longitude', 'Longitude') : array('Clock Out Longitude', 'Clock Out GPS Longitude');

        $map = $is_in ? cleg_admin_field($record, 'Clock In Map Link') : cleg_admin_field($record, 'Clock Out Map Link');
        $lat = '';
        $lng = '';

        foreach ($lat_fields as $field) {
            $lat = cleg_admin_field($record, $field);
            if ($lat !== '') {
                break;
            }
        }

        foreach ($lng_fields as $field) {
            $lng = cleg_admin_field($record, $field);
            if ($lng !== '') {
                break;
            }
        }

        if ($map === '' && $lat !== '' && $lng !== '') {
            $map = 'https://www.google.com/maps?q=' . rawurlencode($lat . ',' . $lng);
        }

        $outside_raw = $is_in ? cleg_admin_field($record, 'Clock In Outside Geofence') : cleg_admin_field($record, 'Clock Out Outside Geofence');
        $distance = $is_in ? (cleg_admin_field($record, 'Clock In Geofence Distance Meters') ?: cleg_admin_field($record, 'Geofence Distance Meters')) : (cleg_admin_field($record, 'Clock Out Geofence Distance Meters') ?: cleg_admin_field($record, 'Geofence Distance Meters'));
        $flags = cleg_admin_field($record, 'Audit Flags');
        $reason = cleg_admin_field($record, 'GPS Review Reason');
        $fallback_outside = $outside_raw === '' && (stripos($reason, 'Outside Geofence') !== false || stripos($flags, 'Outside Geofence') !== false);
        $is_outside = $outside_raw !== '' || $fallback_outside;

        return array(
            'map' => $map,
            'lat' => $lat,
            'lng' => $lng,
            'outside' => $is_outside,
            'distance' => $distance,
        );
    }
}

if (!function_exists('cleg_admin_gps_mini')) {
    function cleg_admin_gps_mini($record, $kind) {
        $point = cleg_admin_gps_point($record, $kind);
        $class = $point['outside'] ? ' is-out' : ' is-in';
        $title = $point['outside'] ? 'GPS fuera de zona' : 'GPS dentro de zona';

        if ($point['map'] === '') {
            return '<span class="cleg-gps-mini is-missing" title="GPS no disponible">GPS</span>';
        }

        return '<a class="cleg-gps-mini' . esc_attr($class) . '" href="' . esc_url($point['map']) . '" target="_blank" rel="noopener" title="' . esc_attr($title) . '">GPS</a>';
    }
}

if (!function_exists('cleg_admin_gps_review_item')) {
    function cleg_admin_gps_review_item($record, $kind) {
        $is_in = $kind === 'in';
        $label = $is_in ? 'Entrada' : 'Salida';
        $point = cleg_admin_gps_point($record, $kind);
        $has_clock_value = $is_in ? cleg_admin_field($record, 'Clock In Time') !== '' : (cleg_admin_field($record, 'Clock Out Time') !== '' || cleg_admin_field($record, 'Worker Reported Clock Out Time') !== '' || cleg_admin_field($record, 'Admin Adjusted Clock Out Time') !== '');

        if ($point['map'] === '') {
            $missing_text = $has_clock_value ? 'GPS no disponible' : 'Sin salida registrada';
            return '<div class="cleg-gps-review-row is-missing"><div><strong>' . esc_html($label) . '</strong><span>' . esc_html($missing_text) . '</span></div><em>Gris</em></div>';
        }

        if ($point['outside']) {
            $miles = cleg_admin_meters_to_miles_label($point['distance']);
            $text = $miles !== '' ? 'Fuera de zona - ' . $miles . ' del geofence' : 'Fuera de zona';
            return '<div class="cleg-gps-review-row is-out"><div><strong>' . esc_html($label) . '</strong><span>' . esc_html($text) . '</span></div><a href="' . esc_url($point['map']) . '" target="_blank" rel="noopener">Ver GPS ' . esc_html($label) . '</a></div>';
        }

        return '<div class="cleg-gps-review-row is-in"><div><strong>' . esc_html($label) . '</strong><span>Dentro de zona</span></div><a href="' . esc_url($point['map']) . '" target="_blank" rel="noopener">Ver GPS ' . esc_html($label) . '</a></div>';
    }
}

if (!function_exists('cleg_admin_gps_review_box')) {
    function cleg_admin_gps_review_box($record) {
        if (!is_array($record)) {
            return '';
        }

        return '<div class="cleg-gps-review-box"><div class="cleg-gps-review-title">Verificacion GPS</div>'
            . cleg_admin_gps_review_item($record, 'in')
            . cleg_admin_gps_review_item($record, 'out')
            . '</div>';
    }
}

if (!function_exists('cleg_admin_row_form_id')) {
    function cleg_admin_row_form_id($record_id, $surface = '') {
        $suffix = $surface !== '' ? '-' . preg_replace('/[^A-Za-z0-9_-]/', '', (string) $surface) : '';
        return 'cleg-review-' . preg_replace('/[^A-Za-z0-9_-]/', '', (string) $record_id) . $suffix;
    }
}

if (!function_exists('cleg_admin_inline_job_select')) {
    function cleg_admin_inline_job_select($record, $job_sites, $form_id) {
        if (!cleg_admin_current_user_can_correct_hours()) {
            return '<strong>' . esc_html(cleg_admin_field($record, 'Job Site Name', 'Sin Job Site')) . '</strong>';
        }

        $current_job = cleg_admin_field($record, 'Job Site Name');
        $html = '<select class="cleg-inline-edit-field" name="correct_job_site" form="' . esc_attr($form_id) . '"><option value="">Mantener proyecto actual</option>';

        foreach ((array) $job_sites as $site) {
            $name = cleg_admin_field($site, 'Job Site Name');
            if ($name === '') {
                continue;
            }
            $html .= '<option value="' . esc_attr($name) . '" ' . selected($current_job, $name, false) . '>' . esc_html($name) . '</option>';
        }

        return $html . '</select>';
    }
}

if (!function_exists('cleg_admin_inline_time_input')) {
    function cleg_admin_inline_time_input($record, $field_name, $value, $form_id, $label = '') {
        if (!cleg_admin_current_user_can_correct_hours()) {
            return '';
        }

        $local_value = $value !== '' ? cleg_admin_datetime_input($value) : '';
        return ($label !== '' ? '<small class="cleg-inline-edit-label">' . esc_html($label) . '</small>' : '')
            . '<input class="cleg-inline-edit-field" type="datetime-local" name="' . esc_attr($field_name) . '" value="' . esc_attr($local_value) . '" form="' . esc_attr($form_id) . '">';
    }
}

if (!function_exists('cleg_admin_review_alert_popup')) {
    function cleg_admin_review_alert_popup($record) {
        if (!is_array($record)) {
            return '';
        }

        $items = array();
        $flags = cleg_admin_field($record, 'Audit Flags');
        $reason = cleg_admin_field($record, 'GPS Review Reason');
        $device = cleg_admin_field($record, 'Device ID');
        $previous = cleg_admin_field($record, 'Previous Device User');
        $current = cleg_admin_field($record, 'Portal Username');

        if ($flags !== '' && $flags !== '--') {
            $items[] = '<small><strong>Auditoria:</strong> ' . esc_html(cleg_admin_review_human_audit_text($flags)) . '</small>';
        }

        if ($reason !== '' && $reason !== '--') {
            $items[] = '<small><strong>GPS:</strong> ' . esc_html(cleg_admin_review_human_audit_text($reason)) . '</small>';
        }

        if (strpos($flags, 'Shared Device Detected') !== false || $previous !== '' || $device !== '') {
            $items[] = '<small><strong>Dispositivo:</strong> Actual ' . esc_html($current ?: '--') . ' / Anterior ' . esc_html($previous ?: '--') . '</small>';
            $items[] = '<small><strong>Device ID:</strong> ' . esc_html($device !== '' ? substr($device, 0, 22) : '--') . '</small>';
        }

        if (empty($items)) {
            return '';
        }

        return '<span class="cleg-review-alert-popup" tabindex="0"><span class="cleg-alert-dot" title="Ver alertas">!</span><span class="cleg-alert-body">' . implode('', $items) . '</span></span>';
    }
}

if (!function_exists('cleg_admin_review_form')) {
    function cleg_admin_review_form($record_id, $record = null, $job_sites = array(), $form_id = '') {
        if (!cleg_admin_current_user_can_review_hours()) {
            return '<span class="cleg-readonly-note">Sin permiso de revision</span>';
        }

        $is_open = is_array($record) && cleg_admin_field($record, 'Clock Out Time') === '';
        $manual_requested = is_array($record) && cleg_admin_field($record, 'Worker Manual Clock Out Requested') !== '';
        $can_accept = is_array($record);
        $status = is_array($record) ? cleg_admin_field($record, 'Approval Status') : '';
        $job_site = is_array($record) ? cleg_admin_field($record, 'Job Site Name') : '';
        $missing_job = cleg_admin_missing_job_site($job_site);
        $form_id = $form_id !== '' ? $form_id : cleg_admin_row_form_id($record_id);
        $review_intro = '';

        if ($status === 'Payroll Closed') {
            return '<span class="cleg-readonly-note">Solo consulta</span>';
        }

        $can_approve = cleg_admin_current_user_can_approve_hours();
        $can_correct = cleg_admin_current_user_can_correct_hours();
        $can_delete = cleg_admin_current_user_can_delete_hours();

        if ($manual_requested) {
            $review_intro .= '<p class="cleg-review-alert">Confirma la salida en Jornada. Quedara en revision.</p>';
        } elseif ($is_open) {
            $review_intro .= '<p class="cleg-review-alert">Abierta. Completa salida en Jornada; no se aprueba sola.</p>';
        }

        if ($missing_job) {
            $review_intro .= '<p class="cleg-review-alert">Falta Job Site. No se puede aprobar todavia.</p>';
        }

        if ($is_open) {
            $actions = $can_correct ? '<button class="is-approve cleg-close-shift-btn" type="submit" name="cleg_admin_action" value="admin_close">Cerrar jornada</button>' : '';
            if ($can_delete) {
                $actions .= '<div class="cleg-delete-popover"><strong>Motivo</strong><label><input type="radio" name="delete_reason" value="Error" checked> Error</label><label><input type="radio" name="delete_reason" value="Prueba de campo"> Prueba de campo</label><label><input type="radio" name="delete_reason" value="Otro"> Otro</label></div>';
                $actions .= '<button class="is-danger cleg-delete-btn" type="submit" name="cleg_admin_action" value="delete">Eliminar</button>';
            }
        } else {
            $primary_label = $manual_requested ? 'Guardar salida (sin aprobar)' : 'Guardar cambios (sin aprobar)';
            $actions = $can_correct ? '<button class="cleg-save-btn" type="submit" name="cleg_admin_action" value="' . esc_attr($manual_requested ? 'admin_close' : 'save_changes') . '">' . esc_html($primary_label) . '</button>' : '';
        }

        if (!$is_open && $status === 'Deleted') {
            $actions .= $can_correct ? '<button type="submit" name="cleg_admin_action" value="reopen">Mandar a revision</button>' : '';
        } elseif (!$is_open && $status === 'Approved') {
            $actions .= $can_correct ? '<button type="submit" name="cleg_admin_action" value="reopen">Mandar a revision</button>' : '';
            if ($can_delete) {
                $actions .= '<div class="cleg-delete-popover"><strong>Motivo</strong><label><input type="radio" name="delete_reason" value="Error" checked> Error</label><label><input type="radio" name="delete_reason" value="Prueba de campo"> Prueba de campo</label><label><input type="radio" name="delete_reason" value="Otro"> Otro</label></div>';
                $actions .= '<button class="is-danger cleg-delete-btn" type="submit" name="cleg_admin_action" value="delete">Eliminar</button>';
            }
        } elseif (!$is_open) {
            $actions .= $can_approve ? '<button class="is-approve cleg-accept-btn" type="submit" name="cleg_admin_action" value="approve" ' . disabled($missing_job || $is_open, true, false) . '>Aprobar jornada</button>' : '';
            if ($can_delete) {
                $actions .= '<div class="cleg-delete-popover"><strong>Motivo</strong><label><input type="radio" name="delete_reason" value="Error" checked> Error</label><label><input type="radio" name="delete_reason" value="Prueba de campo"> Prueba de campo</label><label><input type="radio" name="delete_reason" value="Otro"> Otro</label></div>';
                $actions .= '<button class="is-danger cleg-delete-btn" type="submit" name="cleg_admin_action" value="delete">Eliminar</button>';
            }
        }

        if ($actions === '') {
            return '<span class="cleg-readonly-note">Solo consulta</span>';
        }

        return '<form id="' . esc_attr($form_id) . '" class="cleg-inline-action cleg-review-form cleg-decision-form" method="post">'
            . wp_nonce_field('cleg_admin_time_action', 'cleg_admin_nonce', true, false)
            . '<input type="hidden" name="cleg_admin_record_id" value="' . esc_attr($record_id) . '">'
            . $review_intro
            . '<div class="cleg-review-submit-row">'
            . ($can_accept ? $actions : '')
            . '</div>'
            . '</form>';
    }
}

if (!function_exists('cleg_admin_handle_time_action')) {
    function cleg_admin_handle_time_action() {
        if (empty($_POST['cleg_admin_action'])) {
            return;
        }

        if (!cleg_admin_user_allowed()) {
            return;
        }

        if (!isset($_POST['cleg_admin_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_admin_nonce'])), 'cleg_admin_time_action')) {
            return;
        }

        $action = sanitize_text_field(wp_unslash($_POST['cleg_admin_action']));
        $record_id = isset($_POST['cleg_admin_record_id']) ? sanitize_text_field(wp_unslash($_POST['cleg_admin_record_id'])) : '';
        $user = wp_get_current_user();
        $actor_name = sanitize_text_field($user->display_name ?: $user->user_login);
        $fields = array();
        $redirect_base = remove_query_arg(array('_wp_http_referer', 'cleg_approved', 'cleg_undone', 'cleg_saved', 'cleg_manual_created'));
        $approve_actions = array('approve', 'bulk_approve');
        $correct_actions = array('create_manual_entry', 'admin_close', 'save_changes', 'reopen', 'undo_approval', 'bulk_reopen', 'field_mark_review');
        $delete_actions = array('delete', 'bulk_delete');

        if (in_array($action, $approve_actions, true) && !cleg_admin_current_user_can_approve_hours()) {
            wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('Esta cuenta puede ver horas, pero no tiene permiso para aprobarlas.'), $redirect_base));
            exit;
        }

        if (in_array($action, $correct_actions, true) && !cleg_admin_current_user_can_correct_hours()) {
            wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('Esta cuenta puede ver horas, pero no tiene permiso para corregirlas.'), $redirect_base));
            exit;
        }

        if (in_array($action, $delete_actions, true) && !cleg_admin_current_user_can_delete_hours()) {
            wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('Esta cuenta no tiene permiso para eliminar horas.'), $redirect_base));
            exit;
        }

        if ($action === 'create_manual_entry') {
            $employee_raw = isset($_POST['manual_employee']) ? sanitize_text_field(wp_unslash($_POST['manual_employee'])) : '';
            $employee_parts = array_pad(explode('|', $employee_raw, 3), 3, '');
            $employee_name = sanitize_text_field(rawurldecode($employee_parts[0]));
            $employee_username = sanitize_text_field(rawurldecode($employee_parts[1]));
            $employee_wp_id = absint(rawurldecode($employee_parts[2]));
            $manual_job_site = isset($_POST['manual_job_site']) ? sanitize_text_field(wp_unslash($_POST['manual_job_site'])) : '';
            $manual_clock_in_raw = isset($_POST['manual_clock_in']) ? sanitize_text_field(wp_unslash($_POST['manual_clock_in'])) : '';
            $manual_clock_out_raw = isset($_POST['manual_clock_out']) ? sanitize_text_field(wp_unslash($_POST['manual_clock_out'])) : '';
            $manual_clock_in = $manual_clock_in_raw !== '' ? cleg_admin_local_to_iso($manual_clock_in_raw) : '';
            $manual_clock_out = $manual_clock_out_raw !== '' ? cleg_admin_local_to_iso($manual_clock_out_raw) : '';
            $manual_reason = isset($_POST['manual_reason']) ? sanitize_text_field(wp_unslash($_POST['manual_reason'])) : 'Jornada manual';

            if ($employee_name === '' || $manual_job_site === '' || $manual_clock_in === '' || $manual_clock_out === '') {
                wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('Faltan datos para crear la jornada manual.'), $redirect_base));
                exit;
            }

            $manual_in_day = substr($manual_clock_in_raw, 0, 10);
            $manual_out_day = substr($manual_clock_out_raw, 0, 10);
            if ($manual_in_day === '' || $manual_out_day === '' || $manual_in_day !== $manual_out_day) {
                wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('La salida manual debe ser el mismo dia de la entrada. Divide la jornada en dos registros si cruza medianoche.'), $redirect_base));
                exit;
            }

            if (strtotime($manual_clock_out) <= strtotime($manual_clock_in)) {
                wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('La salida manual debe ser despues de la entrada.'), $redirect_base));
                exit;
            }

            if (function_exists('cleg_field_ops_validate_no_time_overlap')) {
                $overlap_check = cleg_field_ops_validate_no_time_overlap($employee_name, $employee_username, $employee_wp_id, $manual_clock_in, $manual_clock_out);
                if (is_wp_error($overlap_check)) {
                    wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode($overlap_check->get_error_message()), $redirect_base));
                    exit;
                }
            }

            $manual_fields = array(
                'Employee Name' => $employee_name,
                'Job Site Name' => $manual_job_site,
                'Clock In Time' => $manual_clock_in,
                'Clock Out Time' => $manual_clock_out,
                'Approval Status' => 'Manual Need Review',
                'Admin Notes' => cleg_admin_audit_line($actor_name, 'Jornada manual', '--', $manual_clock_in . ' - ' . $manual_clock_out, $manual_reason),
                'Audit Flags' => array('Manual entry by admin'),
            );

            if ($employee_username !== '') {
                $manual_fields['Portal Username'] = $employee_username;
            }

            if ($employee_wp_id > 0) {
                $manual_fields['WordPress User ID'] = $employee_wp_id;
            }

            $result = cleg_field_ops_request('POST', CLEG_AIRTABLE_TIME_TABLE, array(
                'body' => array(
                    'typecast' => true,
                    'records' => array(array('fields' => $manual_fields)),
                ),
            ));

            if (is_wp_error($result)) {
                wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode($result->get_error_message()), $redirect_base));
                exit;
            }

            wp_safe_redirect(add_query_arg(array('cleg_status' => 'pending', 'cleg_manual_created' => '1', 'cleg_refresh' => time()), $redirect_base));
            exit;
        }

        if (in_array($action, array('bulk_approve', 'bulk_delete', 'bulk_reopen'), true)) {
            $ids = isset($_POST['cleg_bulk_ids']) && is_array($_POST['cleg_bulk_ids']) ? array_map('sanitize_text_field', wp_unslash($_POST['cleg_bulk_ids'])) : array();
            $delete_reason = isset($_POST['delete_reason']) ? sanitize_text_field(wp_unslash($_POST['delete_reason'])) : '';
            $updated = 0;
            $blocked = 0;

            foreach ($ids as $bulk_id) {
                $record = cleg_admin_record_by_id($bulk_id);
                if (is_wp_error($record) || empty($record)) {
                    $blocked++;
                    continue;
                }

                $current_job = cleg_admin_field($record, 'Job Site Name');
                $current_notes = cleg_admin_field($record, 'Admin Notes');
                if (cleg_admin_field($record, 'Approval Status') === 'Payroll Closed') {
                    $blocked++;
                    continue;
                }

                if ($action === 'bulk_approve') {
                    if (cleg_admin_missing_job_site($current_job) || cleg_admin_field($record, 'Clock Out Time') === '') {
                        $blocked++;
                        continue;
                    }
                    if (function_exists('cleg_field_ops_validate_no_time_overlap')) {
                        $bulk_overlap = cleg_field_ops_validate_no_time_overlap(
                            cleg_admin_field($record, 'Employee Name'),
                            cleg_admin_field($record, 'Portal Username'),
                            absint(cleg_admin_field($record, 'WordPress User ID')),
                            cleg_admin_effective_clock_in($record),
                            cleg_admin_effective_clock_out($record),
                            $bulk_id
                        );
                        if (is_wp_error($bulk_overlap)) {
                            $blocked++;
                            continue;
                        }
                    }
                    $bulk_fields = array(
                        'Approval Status' => 'Approved',
                        'Approved By' => $actor_name,
                        'Admin Notes' => trim($current_notes . "\n" . cleg_admin_audit_line($actor_name, 'Approval Status', cleg_admin_field($record, 'Approval Status'), 'Approved')),
                    );
                } elseif ($action === 'bulk_reopen') {
                    $bulk_fields = array(
                        'Approval Status' => 'Pending Review',
                        'Admin Notes' => trim($current_notes . "\n" . cleg_admin_audit_line($actor_name, 'Approval Status', cleg_admin_field($record, 'Approval Status'), 'Pending Review', 'Mandada a revision')),
                    );
                } else {
                    $bulk_fields = array(
                        'Approval Status' => 'Deleted',
                        'Approved By' => $actor_name,
                        'Admin Notes' => trim($current_notes . "\n" . cleg_admin_audit_line($actor_name, 'Approval Status', cleg_admin_field($record, 'Approval Status'), 'Deleted', $delete_reason)),
                        'Audit Flags' => array('Deleted by admin'),
                    );
                }

                $result = cleg_field_ops_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
                    'body' => array('typecast' => true, 'records' => array(array('id' => $bulk_id, 'fields' => $bulk_fields))),
                ));

                if (is_wp_error($result)) {
                    $blocked++;
                } else {
                    $updated++;
                }
            }

            wp_safe_redirect(add_query_arg(array('cleg_saved' => $updated, 'cleg_blocked' => $blocked, 'cleg_refresh' => time()), $redirect_base));
            exit;
        }

        if ($record_id === '') {
            return;
        }

        $current_record = cleg_admin_record_by_id($record_id);
        if (is_wp_error($current_record) || empty($current_record)) {
            wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('No se encontro la hora seleccionada.'), $redirect_base));
            exit;
        }

        if (cleg_admin_field($current_record, 'Approval Status') === 'Payroll Closed') {
            wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('Payroll Closed es solo consulta. No se permiten modificaciones.'), $redirect_base));
            exit;
        }

        if ($action === 'field_mark_review') {
            $allowed_reasons = array('Falta salida', 'GPS raro', 'Llego tarde', 'Revisar viernes');
            $field_reason = isset($_POST['cleg_field_reason']) ? sanitize_text_field(wp_unslash($_POST['cleg_field_reason'])) : 'Revisar viernes';
            if (!in_array($field_reason, $allowed_reasons, true)) {
                $field_reason = 'Revisar viernes';
            }

            $field_flags = array('Campo Hoy: ' . $field_reason);
            $fields = array(
                'Approval Status' => 'Pending Review',
                'Admin Adjustment Note' => 'Marcado desde Campo Hoy: ' . $field_reason,
                'Admin Notes' => trim(cleg_admin_field($current_record, 'Admin Notes') . "\n" . cleg_admin_audit_line($actor_name, 'Campo Hoy', cleg_admin_field($current_record, 'Approval Status'), 'Pending Review', $field_reason)),
                'Audit Flags' => $field_flags,
            );

            if ($field_reason === 'Falta salida') {
                $fields['Worker Manual Clock Out Requested'] = true;
            }

            if ($field_reason === 'GPS raro') {
                $fields['GPS Review Required'] = true;
                $fields['GPS Review Reason'] = 'GPS raro marcado desde Campo Hoy';
            }

            $result = cleg_field_ops_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
                'body' => array(
                    'typecast' => true,
                    'records' => array(
                        array(
                            'id' => $record_id,
                            'fields' => $fields,
                        ),
                    ),
                ),
            ));

            if (is_wp_error($result)) {
                wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode($result->get_error_message()), $redirect_base));
                exit;
            }

            wp_safe_redirect(add_query_arg(array('cleg_saved' => '1', 'cleg_refresh' => time()), $redirect_base));
            exit;
        }

        if ($action === 'undo_approval') {
            $fields = array(
                'Approval Status' => 'Pending Review',
                'Admin Adjustment Note' => 'Aprobacion deshecha desde el aviso rapido.',
                'Admin Notes' => trim(cleg_admin_field($current_record, 'Admin Notes') . "\n" . cleg_admin_audit_line($actor_name, 'Approval Status', cleg_admin_field($current_record, 'Approval Status'), 'Pending Review', 'Aprobacion deshecha')),
            );
        }

        $adjusted_in = isset($_POST['admin_adjusted_clock_in']) ? cleg_admin_local_to_iso(sanitize_text_field(wp_unslash($_POST['admin_adjusted_clock_in']))) : '';
        $adjusted_out = isset($_POST['admin_adjusted_clock_out']) ? cleg_admin_local_to_iso(sanitize_text_field(wp_unslash($_POST['admin_adjusted_clock_out']))) : '';
        $admin_note = isset($_POST['admin_adjustment_note']) ? sanitize_textarea_field(wp_unslash($_POST['admin_adjustment_note'])) : '';
        $employee_note = isset($_POST['employee_visible_note']) ? sanitize_textarea_field(wp_unslash($_POST['employee_visible_note'])) : '';
        $correct_job_site = isset($_POST['correct_job_site']) ? sanitize_text_field(wp_unslash($_POST['correct_job_site'])) : '';
        $has_admin_change = $adjusted_in !== '' || $adjusted_out !== '' || $admin_note !== '' || $employee_note !== '' || $correct_job_site !== '';
        $audit_lines = array();
        $effective_job_site = $correct_job_site !== '' ? $correct_job_site : cleg_admin_field($current_record, 'Job Site Name');
        $current_status = cleg_admin_field($current_record, 'Approval Status');
        $current_job_site = cleg_admin_field($current_record, 'Job Site Name');
        $current_adjusted_in = cleg_admin_field($current_record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($current_record, 'Clock In Time');
        $current_adjusted_out = cleg_admin_field($current_record, 'Admin Adjusted Clock Out Time') ?: cleg_admin_field($current_record, 'Clock Out Time');
        $current_admin_note = cleg_admin_field($current_record, 'Admin Adjustment Note');
        $current_employee_note = cleg_admin_field($current_record, 'Employee Visible Admin Note');

        if ($action === 'delete') {
            $delete_reason = isset($_POST['delete_reason']) ? sanitize_text_field(wp_unslash($_POST['delete_reason'])) : '';
            $fields['Approval Status'] = 'Deleted';
            $fields['Approved By'] = $actor_name;
            $fields['Audit Flags'] = array('Deleted by admin');
            if (!cleg_admin_audit_values_equal($current_status, 'Deleted')) {
                $audit_lines[] = cleg_admin_audit_line($actor_name, 'Approval Status', $current_status, 'Deleted', $delete_reason);
            }
        } elseif ($action === 'reopen' || $action === 'undo_approval') {
            $fields['Approval Status'] = 'Pending Review';
            unset($fields['Approved By']);
            if (!cleg_admin_audit_values_equal($current_status, 'Pending Review')) {
                $audit_lines[] = cleg_admin_audit_line($actor_name, 'Approval Status', $current_status, 'Pending Review', 'Reabierta para revision');
            }
        } elseif ($action === 'approve') {
            if (cleg_admin_missing_job_site($effective_job_site)) {
                wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('No se puede aprobar sin Job Site valido.'), $redirect_base));
                exit;
            }
            if (cleg_admin_field($current_record, 'Clock Out Time') === '') {
                wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('No se puede aprobar una jornada abierta. Primero completa la salida y dejala en revision.'), $redirect_base));
                exit;
            }
            $fields['Approval Status'] = 'Approved';
            $fields['Approved By'] = $actor_name;
            if (!cleg_admin_audit_values_equal($current_status, 'Approved')) {
                $audit_lines[] = cleg_admin_audit_line($actor_name, 'Approval Status', $current_status, 'Approved');
            }
        } elseif ($action === 'admin_close' && $adjusted_out !== '') {
            $fields['Approval Status'] = 'Pending Review';
            if (!cleg_admin_audit_values_equal(cleg_admin_field($current_record, 'Clock Out Time'), $adjusted_out)) {
                $audit_lines[] = cleg_admin_audit_line($actor_name, 'Clock Out Time', cleg_admin_field($current_record, 'Clock Out Time'), $adjusted_out, 'Jornada cerrada por admin; pendiente de aprobacion');
            }
        } elseif ($action === 'admin_close') {
            $fields['Approval Status'] = 'Open';
        } elseif ($action === 'save_changes') {
            $fields['Approval Status'] = 'Pending Review';
            if (!cleg_admin_audit_values_equal($current_status, 'Pending Review')) {
                $audit_lines[] = cleg_admin_audit_line($actor_name, 'Revision', $current_status, 'Pending Review', 'Cambios guardados sin aprobar');
            }
        } else {
            $fields['Approval Status'] = 'Pending Review';
        }

        if ($correct_job_site !== '' && !cleg_admin_audit_values_equal($current_job_site, $correct_job_site)) {
            $fields['Job Site Name'] = $correct_job_site;
            $audit_lines[] = cleg_admin_audit_line($actor_name, 'Job Site Name', $current_job_site, $correct_job_site);
        }

        if ($adjusted_in !== '' && !cleg_admin_audit_values_equal($current_adjusted_in, $adjusted_in)) {
            $fields['Admin Adjusted Clock In Time'] = $adjusted_in;
            $audit_lines[] = cleg_admin_audit_line($actor_name, 'Admin Adjusted Clock In Time', $current_adjusted_in, $adjusted_in);
        }

        if ($adjusted_out !== '' && !cleg_admin_audit_values_equal($current_adjusted_out, $adjusted_out)) {
            $fields['Admin Adjusted Clock Out Time'] = $adjusted_out;
            if ($action !== 'admin_close') {
                $audit_lines[] = cleg_admin_audit_line($actor_name, 'Admin Adjusted Clock Out Time', $current_adjusted_out, $adjusted_out);
            }
        }

        if ($action === 'admin_close') {
            if ($adjusted_out === '') {
                if (!$has_admin_change) {
                    wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode('Para cerrar una jornada abierta, escribe la salida corregida.'), remove_query_arg(array('_wp_http_referer'))));
                    exit;
                }

                $fields['Admin Notes'] = trim(($fields['Admin Notes'] ?? '') . "\nOpen shift corrected by admin; no clock out registered yet.");
                $fields['GPS Review Required'] = true;
                $fields['Audit Flags'] = array('Admin Corrected Open Shift');
                unset($fields['Approved By']);
            } else {
                $fields['Clock Out Time'] = $adjusted_out;
                $fields['Worker Manual Clock Out Requested'] = false;
                $fields['GPS Review Required'] = false;
                $fields['Audit Flags'] = array('Admin Closed Shift');
                $fields['Admin Notes'] = trim(($fields['Admin Notes'] ?? '') . "\nAdmin closed open shift from review panel.");
            }
        }

        if ($action === 'save_changes' && $adjusted_out !== '' && cleg_admin_field($current_record, 'Clock Out Time') === '') {
            $fields['Clock Out Time'] = $adjusted_out;
            $fields['Worker Manual Clock Out Requested'] = false;
            $fields['GPS Review Required'] = false;
            if (!cleg_admin_audit_values_equal(cleg_admin_field($current_record, 'Clock Out Time'), $adjusted_out)) {
                $audit_lines[] = cleg_admin_audit_line($actor_name, 'Clock Out Time', cleg_admin_field($current_record, 'Clock Out Time'), $adjusted_out, 'Salida guardada sin aprobacion');
            }
        }

        if ($admin_note !== '' && !cleg_admin_audit_values_equal($current_admin_note, $admin_note)) {
            $fields['Admin Adjustment Note'] = $admin_note;
            $audit_lines[] = cleg_admin_audit_line($actor_name, 'Admin Adjustment Note', $current_admin_note, $admin_note);
        }

        if ($employee_note !== '' && !cleg_admin_audit_values_equal($current_employee_note, $employee_note)) {
            $fields['Employee Visible Admin Note'] = $employee_note;
            $audit_lines[] = cleg_admin_audit_line($actor_name, 'Employee Visible Admin Note', $current_employee_note, $employee_note);
        }

        if (!empty($audit_lines)) {
            $fields['Admin Notes'] = trim(cleg_admin_field($current_record, 'Admin Notes') . "\n" . implode("\n", $audit_lines));
        }

        if (function_exists('cleg_field_ops_validate_no_time_overlap') && in_array($action, array('approve', 'admin_close', 'save_changes'), true)) {
            $proposed_clock_in = $adjusted_in !== '' ? $adjusted_in : cleg_admin_effective_clock_in($current_record);
            $proposed_clock_out = $adjusted_out !== '' ? $adjusted_out : cleg_admin_effective_clock_out($current_record);
            if ($proposed_clock_in !== '' && $proposed_clock_out !== '') {
                $overlap_check = cleg_field_ops_validate_no_time_overlap(
                    cleg_admin_field($current_record, 'Employee Name'),
                    cleg_admin_field($current_record, 'Portal Username'),
                    absint(cleg_admin_field($current_record, 'WordPress User ID')),
                    $proposed_clock_in,
                    $proposed_clock_out,
                    $record_id
                );
                if (is_wp_error($overlap_check)) {
                    wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode($overlap_check->get_error_message()), $redirect_base));
                    exit;
                }
            }
        }

        $result = cleg_field_ops_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
            'body' => array(
                'typecast' => true,
                'records' => array(
                    array(
                        'id' => $record_id,
                        'fields' => $fields,
                    ),
                ),
            ),
        ));

        if (is_wp_error($result)) {
            wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode($result->get_error_message()), $redirect_base));
            exit;
        }

        if ($action === 'admin_close' && $adjusted_out === '' && $has_admin_change) {
            wp_safe_redirect(add_query_arg(array('cleg_saved' => '1', 'cleg_refresh' => time()), $redirect_base));
            exit;
        }

        if ($action === 'approve') {
            wp_safe_redirect(add_query_arg(array('cleg_approved' => rawurlencode($record_id), 'cleg_refresh' => time()), $redirect_base));
            exit;
        }

        if ($action === 'undo_approval') {
            wp_safe_redirect(add_query_arg(array('cleg_undone' => '1', 'cleg_refresh' => time()), $redirect_base));
            exit;
        }

        wp_safe_redirect(add_query_arg(array('cleg_saved' => '1', 'cleg_refresh' => time()), $redirect_base));
        exit;
    }
}

add_action('init', 'cleg_admin_handle_time_action');
add_shortcode('cleg_admin_horas', 'cleg_admin_horas_shortcode');
/**
 * END modulos/10-field-ops/07c-cleg-05b-admin-revision-horas.php
