/**
 * BEGIN modulos/10-field-ops/07d-cleg-05c-admin-tiempo-real.php
 * Module: field_ops
 * Target: 01-Snippets-Activos/07d-cleg-05c-admin-tiempo-real.php
 * Source path: modulos/10-field-ops/07d-cleg-05c-admin-tiempo-real.php
 */
/**
 * CLEG 05C - Admin Tiempo Real v1.5
 *
 * Pantallas /admin-tiempo-real/ y /admin-dispositivos/ para jornadas abiertas.
 * Generado desde CLEG 05 v2.18 durante refactor por pantalla.
 * No tocar CLEG 04 ni funciones del panel trabajador.
 * Visual: CLEG 03B - RRHH Design System.
 * v1.3 excluye registros borrados/cerrados de jornadas abiertas e integra el mapa junto a la lista.
 * v1.4 Tiempo real vuelve a contar toda fila sin salida para que el admin pueda verla/cerrarla aunque el estado este mal.
 * v1.5 cambia el enlace GPS de Google Maps a salto interno hacia el mapa operativo de la pagina.
 * v1.6 envia Revisar / cerrar directamente a Jornadas abiertas con semana y empleado.
 * v1.6 consume el wrapper Field Ops Data Access para jornadas abiertas y auditoria de dispositivos.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_admin_open_shift_formula')) {
    function cleg_admin_open_shift_formula() {
        return "{Clock Out Time}=BLANK()";
    }
}


if (!function_exists('cleg_admin_tiempo_real_shortcode')) {
    function cleg_admin_tiempo_real_shortcode() {
        $html = cleg_admin_page_open('live', 'Control en tiempo real', '');

        if (strpos($html, 'cleg-admin-empty') !== false) {
            return $html;
        }

        $open = function_exists('cleg_field_ops_get_live_presence')
            ? cleg_field_ops_get_live_presence(array('max_records' => 100))
            : cleg_admin_time_records(cleg_admin_open_shift_formula(), 100);

        if (is_wp_error($open)) {
            return $html . cleg_admin_error($open) . cleg_admin_page_close();
        }

        if (count($open) > 0) {
            $html .= '<div class="cleg-live-head"><strong>' . esc_html(count($open)) . '</strong><span>jornadas abiertas</span></div>';
        }
        $html .= cleg_admin_live_table($open);
        if (shortcode_exists('cleg_admin_gps_tracking')) {
            $html .= '<div class="cleg-live-map-slot">' . do_shortcode('[cleg_admin_gps_tracking]') . '</div>';
        }

        return $html . cleg_admin_page_close();
    }
}

if (!function_exists('cleg_admin_dispositivos_shortcode')) {
    function cleg_admin_dispositivos_shortcode() {
        $html = cleg_admin_page_open('devices', 'Auditoría de dispositivos', 'Detecta móviles usados por más de un trabajador.');

        if (strpos($html, 'cleg-admin-empty') !== false) {
            return $html;
        }

        $records = function_exists('cleg_field_ops_get_device_records')
            ? cleg_field_ops_get_device_records(array('max_records' => 100))
            : cleg_admin_time_records("{Device ID}!=''", 100);

        if (is_wp_error($records)) {
            return $html . cleg_admin_error($records) . cleg_admin_page_close();
        }

        $devices = array();

        foreach ($records as $record) {
            $device = cleg_admin_field($record, 'Device ID');
            if ($device === '') {
                continue;
            }
            $username = cleg_admin_field($record, 'Portal Username', 'sin_usuario');
            $devices[$device]['users'][$username] = true;
            $devices[$device]['last'] = $devices[$device]['last'] ?? $record;
            $devices[$device]['count'] = ($devices[$device]['count'] ?? 0) + 1;
        }

        uasort($devices, function ($a, $b) {
            return count($b['users']) <=> count($a['users']);
        });

        $html .= '<div class="cleg-panel"><h2>Móviles detectados</h2>';
        $mobile = '<div class="cleg-mobile-only cleg-mobile-card-stack" aria-label="Móviles detectados">';
        $table = '<div class="cleg-table-wrap cleg-desktop-table"><table><thead><tr><th>Riesgo</th><th>Device ID</th><th>Usuarios</th><th>Usos</th><th>Último Job Site</th></tr></thead><tbody>';

        foreach ($devices as $device => $info) {
            $users = array_keys($info['users']);
            $risk = count($users) > 1 ? 'Compartido' : 'Normal';
            $mobile .= '<article class="cleg-mobile-card"><div class="cleg-mobile-card-top"><div><span>Usuarios</span><strong>' . esc_html(implode(', ', $users)) . '</strong></div><span class="cleg-pill ' . esc_attr(count($users) > 1 ? 'is-warn' : 'is-ok') . '">' . esc_html($risk) . '</span></div><div class="cleg-mobile-facts"><div><small>Device ID</small><b><code>' . esc_html(substr($device, -8)) . '</code></b></div><div><small>Usos</small><b>' . esc_html($info['count']) . '</b></div></div><p>' . esc_html(cleg_admin_field($info['last'], 'Job Site Name', 'Sin proyecto')) . '</p></article>';
            $table .= '<tr><td><span class="cleg-pill ' . esc_attr(count($users) > 1 ? 'is-warn' : 'is-ok') . '">' . esc_html($risk) . '</span></td><td><code>' . esc_html(substr($device, 0, 22)) . '</code></td><td>' . esc_html(implode(', ', $users)) . '</td><td>' . esc_html($info['count']) . '</td><td>' . esc_html(cleg_admin_field($info['last'], 'Job Site Name')) . '</td></tr>';
        }

        if (empty($devices)) {
            $table .= '<tr><td colspan="5">Todavia no hay Device ID registrados.</td></tr>';
            $mobile .= '<article class="cleg-mobile-card"><strong>Todavía no hay móviles registrados.</strong></article>';
        }

        $html .= $mobile . '</div>' . $table . '</tbody></table></div></div>';

        return $html . cleg_admin_page_close();
    }
}

if (!function_exists('cleg_admin_device_alert')) {
    function cleg_admin_device_alert($record) {
        $flags = cleg_admin_field($record, 'Audit Flags');
        if (strpos($flags, 'Shared Device Detected') === false) {
            return '';
        }

        $device = cleg_admin_field($record, 'Device ID');
        $previous = cleg_admin_field($record, 'Previous Device User');
        $current = cleg_admin_field($record, 'Portal Username');

        return '<details class="cleg-device-alert"><summary>Dispositivo compartido detectado</summary><small>Actual: ' . esc_html($current ?: '--') . '</small><small>Anterior: ' . esc_html($previous ?: '--') . '</small><small>Device ID: ' . esc_html($device !== '' ? substr($device, 0, 22) : '--') . '</small></details>';
    }
}

if (!function_exists('cleg_admin_live_open_shift_review_url')) {
    function cleg_admin_live_open_shift_review_url($record) {
        $args = array(
            'cleg_status' => 'open',
        );

        $clock_in = cleg_admin_field($record, 'Clock In Time');
        if ($clock_in !== '') {
            try {
                list($week_start) = cleg_admin_week_bounds($clock_in);
                if ($week_start instanceof DateTimeInterface) {
                    $args['cleg_week'] = $week_start->format('Y-m-d');
                }
            } catch (Exception $e) {
                // Keep the link usable even if the source date is malformed.
            }
        }

        $employee = cleg_admin_field($record, 'Portal Username');
        if ($employee === '') {
            $employee = cleg_admin_field($record, 'Employee Name');
        }
        if ($employee !== '') {
            $args['cleg_employee'] = $employee;
        }

        return add_query_arg($args, home_url('/admin-horas/'));
    }
}

if (!function_exists('cleg_admin_live_table')) {
    function cleg_admin_live_table($records) {
        $mobile = '<div class="cleg-mobile-only cleg-mobile-card-stack" aria-label="Personas trabajando ahora">';
        $html = '<div class="cleg-panel cleg-live-table-panel"><h2>Trabajando ahora</h2><div class="cleg-table-wrap cleg-desktop-table"><table><thead><tr><th>Empleado</th><th>Usuario</th><th>Job Site</th><th>Entrada</th><th>GPS</th><th>Alertas</th><th>Accion</th></tr></thead><tbody>';

        foreach ($records as $record) {
            $map = cleg_admin_field($record, 'Clock In Map Link');
            $device_alert = cleg_admin_device_alert($record);
            $review_url = cleg_admin_live_open_shift_review_url($record);
            $mobile .= '<article class="cleg-mobile-card"><div class="cleg-mobile-card-top"><div><span>' . esc_html(cleg_admin_field($record, 'Portal Username')) . '</span><strong>' . esc_html(cleg_admin_field($record, 'Employee Name')) . '</strong></div><span class="cleg-pill is-warn">En jornada</span></div><div class="cleg-mobile-job">' . esc_html(cleg_admin_field($record, 'Job Site Name', 'Sin proyecto')) . '</div><div class="cleg-mobile-facts"><div><small>Entrada</small><b>' . esc_html(cleg_admin_date(cleg_admin_field($record, 'Clock In Time'))) . '</b></div><div><small>GPS</small><b>' . ($map !== '' ? 'Disponible' : 'Sin GPS') . '</b></div></div>' . ($device_alert !== '' ? '<details class="cleg-mobile-details"><summary>Ver alerta</summary>' . $device_alert . '</details>' : '') . '<a class="cleg-row-action" href="' . esc_url($review_url) . '">Revisar y cerrar</a></article>';
            $html .= '<tr><td>' . esc_html(cleg_admin_field($record, 'Employee Name')) . '</td><td>' . esc_html(cleg_admin_field($record, 'Portal Username')) . '</td><td>' . esc_html(cleg_admin_field($record, 'Job Site Name')) . '</td><td>' . esc_html(cleg_admin_date(cleg_admin_field($record, 'Clock In Time'))) . '</td><td>' . ($map !== '' ? '<a class="cleg-live-map-jump" href="#cleg-campo-mapa">Ver en mapa</a>' : 'Sin GPS') . '</td><td>' . ($device_alert !== '' ? $device_alert : '--') . '</td><td><a class="cleg-row-action" href="' . esc_url($review_url) . '">Revisar / cerrar</a></td></tr>';
        }

        if (empty($records)) {
            $html .= '<tr><td colspan="7">No hay jornadas abiertas.</td></tr>';
            $mobile .= '<article class="cleg-mobile-card"><strong>No hay jornadas abiertas.</strong><p>Cuando alguien marque entrada aparecerá aquí.</p></article>';
        }

        return $mobile . '</div>' . $html . '</tbody></table></div></div>';
    }
}

add_shortcode('cleg_admin_tiempo_real', 'cleg_admin_tiempo_real_shortcode');
add_shortcode('cleg_admin_dispositivos', 'cleg_admin_dispositivos_shortcode');
/**
 * END modulos/10-field-ops/07d-cleg-05c-admin-tiempo-real.php
