if (!function_exists('cleg_admin_employee_raw_field')) {
    function cleg_admin_employee_raw_field($record, $field, $default = null) {
        if (!is_array($record) || empty($record['fields']) || !is_array($record['fields'])) {
            return $default;
        }

        return array_key_exists($field, $record['fields']) ? $record['fields'][$field] : $default;
    }
}

if (!function_exists('cleg_admin_employee_amount')) {
    function cleg_admin_employee_amount($value, $default = 0) {
        if ($value === null || $value === '') {
            return $default;
        }

        if (is_array($value)) {
            return $default;
        }

        return is_numeric($value) ? (float) $value : $default;
    }
}

if (!function_exists('cleg_admin_employee_tax_profile')) {
    function cleg_admin_employee_tax_profile($employee) {
        $employee_id = is_array($employee) && !empty($employee['id']) ? sanitize_text_field($employee['id']) : '';
        $employee_name = is_array($employee) ? cleg_admin_field($employee, 'Employee Name') : '';
        if ($employee_id === '' || !function_exists('cleg_hr_core_request')) {
            return array();
        }

        $employee_lookup = $employee_name !== '' ? $employee_name : $employee_id;
        $response = cleg_hr_core_request('GET', CLEG_AIRTABLE_TAX_PROFILES_TABLE, array(
            'query' => array(
                'filterByFormula' => "FIND('" . cleg_admin_formula_text($employee_lookup) . "',ARRAYJOIN({Employee}))",
                'maxRecords' => 1,
            ),
        ));

        if (is_wp_error($response) || empty($response['records'][0]) || !is_array($response['records'][0])) {
            return array();
        }

        return $response['records'][0];
    }
}

