if (!function_exists('cleg_admin_employee_update_tax_profile')) {
    function cleg_admin_employee_update_tax_profile($employee_id, $employee_name) {
        if (empty($_POST['update_tax_profile']) || $employee_id === '' || !function_exists('cleg_hr_core_request')) {
            return;
        }

        $profile_id = isset($_POST['tax_profile_id']) ? sanitize_text_field(wp_unslash($_POST['tax_profile_id'])) : '';
        $opening_wages = isset($_POST['opening_sinot_wages']) ? max(0, (float) sanitize_text_field(wp_unslash($_POST['opening_sinot_wages']))) : 0;
        $opening_paid = isset($_POST['opening_sinot_paid']) ? max(0, (float) sanitize_text_field(wp_unslash($_POST['opening_sinot_paid']))) : 0;
        $fields = array(
            'SINOT Exempt' => !empty($_POST['sinot_exempt']),
            'Opening YTD SINOT Wages' => $opening_wages,
            'Opening YTD SINOT Paid' => $opening_paid,
        );

        if ($profile_id !== '') {
            cleg_hr_core_request('PATCH', CLEG_AIRTABLE_TAX_PROFILES_TABLE, array(
                'body' => array(
                    'records' => array(array('id' => $profile_id, 'fields' => $fields)),
                    'typecast' => true,
                ),
            ));
            return;
        }

        $fields['Profile Name'] = $employee_name . ' - Fiscal Profile ' . gmdate('Y');
        $fields['Employee'] = array($employee_id);
        $fields['Effective From'] = gmdate('Y') . '-01-01';

        cleg_hr_core_request('POST', CLEG_AIRTABLE_TAX_PROFILES_TABLE, array(
            'body' => array(
                'records' => array(array('fields' => $fields)),
                'typecast' => true,
            ),
        ));
    }
}

