}

if (!function_exists('cleg_admin_employee_iso_date')) {
    function cleg_admin_employee_iso_date($value) {
        $value = sanitize_text_field((string) $value);
        return preg_match('/^\d{4}-\d{2}-\d{2}$/', $value) ? $value : '';
    }
}

if (!function_exists('cleg_admin_employee_workdays_between')) {
    function cleg_admin_employee_workdays_between($start_date, $end_date) {
        $start_date = cleg_admin_employee_iso_date($start_date);
        $end_date = cleg_admin_employee_iso_date($end_date);
        if ($start_date === '' || $end_date === '') {
            return 0;
        }

        try {
            $start = new DateTime($start_date, new DateTimeZone('America/Puerto_Rico'));
            $end = new DateTime($end_date, new DateTimeZone('America/Puerto_Rico'));
        } catch (Exception $e) {
            return 0;
        }

        if ($end < $start) {
            return 0;
        }

        $days = 0;
        while ($start <= $end) {
            $weekday = (int) $start->format('N');
            if ($weekday >= 1 && $weekday <= 5) {
                $days++;
            }
            $start->modify('+1 day');
        }

        return $days;
    }
}

if (!function_exists('cleg_admin_employee_leave_balance_field')) {
    function cleg_admin_employee_leave_balance_field($leave_type) {
        $leave_type = sanitize_text_field($leave_type);
        if ($leave_type === 'Sick') {
            return 'PTO Sick Balance Hours';
        }
        if ($leave_type === 'Vacation') {
            return 'PTO Vacation Balance Hours';
        }
        return '';
    }
}

if (!function_exists('cleg_admin_employee_leave_preview')) {
    function cleg_admin_employee_leave_preview($employee, $record) {
        $leave_type = cleg_admin_field($record, 'Leave Type');
        $requested = cleg_admin_employee_amount(cleg_admin_employee_raw_field($record, 'Hours Count'), 0);
        $balance_field = cleg_admin_employee_leave_balance_field($leave_type);
        $primary_balance = $balance_field !== '' ? cleg_admin_employee_amount(cleg_admin_employee_raw_field($employee, $balance_field), 0) : 0;
        $admin_note = cleg_admin_field($record, 'Admin Note');
        $allow_vacation = strpos($admin_note, '[use_vacation_overflow=yes]') !== false;
        $vacation_balance = cleg_admin_employee_amount(cleg_admin_employee_raw_field($employee, 'PTO Vacation Balance Hours'), 0);
        $covered_primary = $balance_field !== '' ? min($primary_balance, $requested) : 0;
        $remaining = max(0, $requested - $covered_primary);
        $covered_vacation = ($leave_type === 'Sick' && $allow_vacation) ? min($vacation_balance, $remaining) : 0;
        $covered = $covered_primary + $covered_vacation;

        return array(
            'requested' => $requested,
            'covered' => $covered,
            'uncovered' => max(0, $requested - $covered),
            'balance_before' => $primary_balance,
            'balance_after' => max(0, $primary_balance - $covered_primary),
        );
    }
}

