            . '<label>Status<select name="leave_status"><option value="Approved">Approved</option><option value="Pending">Pending</option><option value="Draft">Draft</option></select></label>'
            . '<label>Fecha inicial<input name="leave_start_date" type="date" required></label>'
            . '<label>Fecha final<input name="leave_end_date" type="date" required></label>'
