            . '<label style="display:flex;gap:8px;align-items:center;"><input type="checkbox" name="leave_use_balance" value="1" checked> Estimar cobertura con balance disponible</label>'
            . '<label style="display:flex;gap:8px;align-items:center;"><input type="checkbox" name="leave_use_vacation_overflow" value="1"> Usar vacaciones para cubrir sobrante de enfermedad</label>'
            . '<label style="display:flex;gap:8px;align-items:center;"><input type="checkbox" name="leave_visible_paystub" value="1" checked> Mostrar en paystub</label>'
            . '<label>Nota interna<textarea name="leave_admin_note" rows="3" placeholder="Detalle para administracion"></textarea></label>'
            . '<label>Nota visible al empleado<textarea name="leave_employee_note" rows="3" placeholder="Texto limpio para expediente o paystub"></textarea></label>'
