if (!function_exists('cleg_admin_handle_employee_leave_action')) {
    function cleg_admin_handle_employee_leave_action() {
        if (!function_exists('cleg_hr_core_request')) {
            return new WP_Error('cleg_leave_missing_request', 'No esta disponible la conexion interna con Airtable.');
        }

        $employee_id = isset($_POST['employee_record_id']) ? sanitize_text_field(wp_unslash($_POST['employee_record_id'])) : '';
        $employee = cleg_admin_employee_record_by_id($employee_id);
        if (empty($employee)) {
            return new WP_Error('cleg_leave_employee_missing', 'No se encontro el expediente del trabajador.');
        }

        $employee_name = cleg_admin_field($employee, 'Employee Name');
        $leave_type = isset($_POST['leave_type']) ? sanitize_text_field(wp_unslash($_POST['leave_type'])) : 'Absence';
        $allowed_types = array('Sick', 'Vacation', 'Absence', 'Manual Adjustment', 'Unpaid Leave', 'Other');
        if (!in_array($leave_type, $allowed_types, true)) {
            $leave_type = 'Absence';
        }

        $status = isset($_POST['leave_status']) ? sanitize_text_field(wp_unslash($_POST['leave_status'])) : 'Approved';
        if (!in_array($status, array('Draft', 'Pending', 'Approved'), true)) {
            $status = 'Approved';
        }

        $start_date = isset($_POST['leave_start_date']) ? cleg_admin_employee_iso_date(wp_unslash($_POST['leave_start_date'])) : '';
        $end_date = isset($_POST['leave_end_date']) ? cleg_admin_employee_iso_date(wp_unslash($_POST['leave_end_date'])) : '';
        $work_days = cleg_admin_employee_workdays_between($start_date, $end_date);
        $hours_per_day = isset($_POST['leave_hours_per_day']) ? max(0, (float) sanitize_text_field(wp_unslash($_POST['leave_hours_per_day']))) : 0;
        if ($start_date === '' || $end_date === '' || $work_days <= 0 || $hours_per_day <= 0) {
            return new WP_Error('cleg_leave_invalid_dates', 'Verifica fechas y horas por dia.');
        }

        $hours_count = round($work_days * $hours_per_day, 2);
        $balance_field = cleg_admin_employee_leave_balance_field($leave_type);
        $use_balance = !empty($_POST['leave_use_balance']) && $balance_field !== '' && $status === 'Approved';
        $balance_before = $balance_field !== '' ? cleg_admin_employee_amount(cleg_admin_employee_raw_field($employee, $balance_field), 0) : 0;
        $used_hours = $use_balance ? min($balance_before, $hours_count) : 0;
        $balance_after = $use_balance ? max(0, $balance_before - $used_hours) : $balance_before;
        $uncovered_hours = $use_balance ? max(0, $hours_count - $used_hours) : $hours_count;
        $current_user = wp_get_current_user();
        $admin_note = isset($_POST['leave_admin_note']) ? sanitize_textarea_field(wp_unslash($_POST['leave_admin_note'])) : '';
        if (!empty($_POST['leave_use_vacation_overflow'])) {
            $admin_note = trim($admin_note . "\n[use_vacation_overflow=yes]");
        }

        $fields = array(
            'Leave Code' => 'CLEG-LEAVE-' . gmdate('Ymd-His'),
            'Employee' => array($employee_id),
            'Leave Type' => $leave_type,
            'Source' => 'Admin Manual Entry',
            'Status' => $status,
            'Start Date' => $start_date,
            'End Date' => $end_date,
            'Work Days Count' => $work_days,
            'Hours Count' => $hours_count,
            'Balance Before' => $balance_before,
            'Accrued Hours' => 0,
            'Used Hours' => $used_hours,
            'Balance After' => $balance_after,
            'Uncovered Hours' => $uncovered_hours,
            'Visible on Paystub' => !empty($_POST['leave_visible_paystub']),
            'Admin Note' => $admin_note,
            'Employee Note' => isset($_POST['leave_employee_note']) ? sanitize_textarea_field(wp_unslash($_POST['leave_employee_note'])) : '',
            'Created By' => $current_user && $current_user->exists() ? $current_user->user_login : 'Admin',
            'Created At' => gmdate('c'),
        );

        if ($fields['Admin Note'] === '') {
            $fields['Admin Note'] = 'Ausencia registrada manualmente desde el expediente de ' . $employee_name . '.';
        }
        if ($fields['Employee Note'] === '') {
            $fields['Employee Note'] = 'Ausencia registrada para el periodo del ' . $start_date . ' al ' . $end_date . '.';
        }

        $created = cleg_hr_core_request('POST', CLEG_AIRTABLE_LEAVE_LEDGER_TABLE, array(
            'body' => array(
                'records' => array(array('fields' => $fields)),
                'typecast' => true,
            ),
        ));

        if (is_wp_error($created)) {
            return $created;
        }

        return true;
    }
}


if (!function_exists('cleg_admin_employee_time_filter')) {
    function cleg_admin_employee_time_filter($employee) {
        $needles = array();
        foreach (array('Employee Name', 'Portal Username', 'Employee Email') as $field) {
            $value = is_array($employee) ? cleg_admin_field($employee, $field) : '';
            $value = strtolower(trim((string) $value));
            if ($value !== '') {
                $needles[$value] = true;
            }
        }

        $parts = array();
        foreach (array_keys($needles) as $needle) {
            $safe = cleg_admin_formula_text($needle);
            $parts[] = "OR(FIND('{$safe}',LOWER({Employee Name}))>0,FIND('{$safe}',LOWER({Portal Username}))>0)";
        }

        if (empty($parts)) {
            return '';
        }

        return count($parts) === 1 ? $parts[0] : 'OR(' . implode(',', $parts) . ')';
    }
}

if (!function_exists('cleg_admin_empleados_shortcode')) {
    function cleg_admin_empleados_shortcode() {
        $html = cleg_admin_page_open('employees', 'Trabajadores', 'Estado de usuarios del portal y campos clave.');

        if (strpos($html, 'cleg-admin-empty') !== false) {
            return $html;
        }

        $employees = cleg_admin_employees();

        if (is_wp_error($employees)) {
            return $html . cleg_admin_error($employees) . cleg_admin_page_close();
        }

        $selected_employee = isset($_GET['cleg_employee']) ? sanitize_text_field(wp_unslash($_GET['cleg_employee'])) : '';
        if ($selected_employee !== '') {
            $employee_record = null;
            foreach ($employees as $employee) {
                $username = cleg_admin_field($employee, 'Portal Username');
                $name = cleg_admin_field($employee, 'Employee Name');
                if ($selected_employee === $username || $selected_employee === $name) {
                    $employee_record = $employee;
                    break;
                }
            }

            $employee_name = is_array($employee_record) ? cleg_admin_field($employee_record, 'Employee Name', $selected_employee) : $selected_employee;
            $employee_username = is_array($employee_record) ? cleg_admin_field($employee_record, 'Portal Username') : $selected_employee;
            $filter = is_array($employee_record) ? cleg_admin_employee_time_filter($employee_record) : '';
            if ($filter === '') {
                $filter = "OR({Portal Username}='" . cleg_admin_formula_text($employee_username) . "',{Employee Name}='" . cleg_admin_formula_text($employee_name) . "')";
            }
            $employee_hours = cleg_admin_time_records($filter, 100);
            $job_sites = cleg_admin_job_sites();

            if (is_wp_error($employee_hours) || is_wp_error($job_sites)) {
                return $html . cleg_admin_error($employee_hours, $job_sites) . cleg_admin_page_close();
            }

            if (is_array($employee_record)) {
                $html .= cleg_admin_employee_edit_form($employee_record);
            }
            $html .= cleg_admin_context_hours_panel('Trabajador: ' . $employee_name, $employee_hours, $job_sites, home_url('/admin-empleados/'));
            if (is_array($employee_record)) {
                $html .= cleg_admin_employee_leave_panel($employee_record);
            }
        }

        $html .= cleg_admin_employee_form();
        $html .= '<div class="cleg-panel cleg-employee-table-panel"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:12px;"><h2 style="margin:0;">Trabajadores</h2></div><div class="cleg-table-wrap"><table><thead><tr><th>Nombre</th><th>Usuario</th><th>WP ID</th><th>Tipo</th><th>Status</th><th>Expediente</th></tr></thead><tbody>';

        foreach ($employees as $employee) {
            $role = cleg_admin_field($employee, 'Role');
            $wp_id = cleg_admin_field($employee, 'WordPress User ID');
            $needs_id = $role === 'Trabajador' && $wp_id === '';
            $employee_name = cleg_admin_field($employee, 'Employee Name');
            $employee_username = cleg_admin_field($employee, 'Portal Username');
            $employee_url = cleg_admin_context_url('/admin-empleados/', array('cleg_employee' => $employee_username ?: $employee_name));
            $tax_type = cleg_admin_field($employee, 'Payroll Tax Type', 'Employee - Full Payroll');
            $html .= '<tr class="' . esc_attr($needs_id ? 'needs-attention' : '') . '"><td><a class="cleg-cell-link" href="' . esc_url($employee_url) . '">' . esc_html($employee_name) . '</a></td><td><a class="cleg-cell-link" href="' . esc_url($employee_url) . '">' . esc_html($employee_username) . '</a></td><td>' . esc_html($wp_id ?: 'Pendiente') . '</td><td>' . esc_html(cleg_admin_employee_tax_type_label($tax_type)) . '</td><td>' . esc_html(cleg_admin_field($employee, 'Status')) . '</td><td><a class="cleg-row-action" href="' . esc_url($employee_url) . '">Ver expediente</a></td></tr>';
        }

        $html .= '</tbody></table></div></div>';

        return $html . cleg_admin_employee_layout_styles() . cleg_admin_page_close();
    }
}

