color:#06182d}.cleg-employee-document-panel p{margin:0 0 10px;color:#667085;font-weight:800}.cleg-document-upload-form{display:grid;grid-template-columns:repeat(3,minmax(160px,1fr));gap:10px}.cleg-document-upload-form .wide{grid-column:span 2}.cleg-document-upload-form button{align-self:end}.cleg-employee-leave-panel .cleg-leave-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;flex-wrap:wrap;margin-bottom:14px}.cleg-employee-leave-panel h2{margin:0 0 6px}.cleg-employee-leave-panel p{margin:0;color:#667085}.cleg-leave-balances{display:flex;gap:8px;flex-wrap:wrap}.cleg-leave-balances span{border:1px solid #d7dee8;border-radius:8px;padding:8px 10px;background:#f8fafc}.cleg-leave-history{margin-top:14px}.cleg-leave-form textarea{min-height:76px}@media(max-width:720px){.cleg-sinot-drawer-body,.cleg-document-upload-form{grid-template-columns:1fr}.cleg-document-upload-form .wide{grid-column:auto}}</style><script>(function(){function sync(root){var select=root.querySelector("[data-worker-type-select]");if(!select)return;var type=select.value;root.querySelectorAll("[data-worker-types]").forEach(function(el){var allowed=(el.getAttribute("data-worker-types")||"").split("|");el.classList.toggle("is-hidden",allowed.indexOf(type)===-1);});root.querySelectorAll("[data-worker-note]").forEach(function(el){el.classList.toggle("is-hidden",el.getAttribute("data-worker-note")!==type);});}document.addEventListener("change",function(event){if(event.target.matches("[data-worker-type-select]"))sync(event.target.closest("form")||document);});document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("form").forEach(sync);});})();</script>';
    }
}

if (!function_exists('cleg_admin_employee_roles_tab')) {
    function cleg_admin_employee_roles_tab() {
