            return '<div class="cleg-admin-roles-tab">' . $manager . '</div>';
        }

        $choices = cleg_admin_employee_role_choices();
        $html = '<div class="cleg-panel cleg-admin-roles-tab"><h2>Roles y permisos CLEG</h2><p>No se encontro activo el gestor avanzado de permisos. Se conserva el catalogo operativo usado por Airtable en Employees.Role.</p><div class="cleg-table-wrap"><table><thead><tr><th>Rol</th><th>Origen</th><th>Uso</th></tr></thead><tbody>';

        foreach ($choices as $role_label) {
            $tracks = cleg_admin_employee_role_tracks_time($role_label) ? 'Marca horas' : 'No marca horas por defecto';
            $html .= '<tr><td>' . esc_html($role_label) . '</td><td>Employees.Role</td><td>' . esc_html($tracks) . '</td></tr>';
        }

        return $html . '</tbody></table></div></div>';
    }
}

