if (!function_exists('cleg_admin_employee_role_choices')) {
    function cleg_admin_employee_role_choices($current_role = '') {
        $choices = array(
            'Trabajador' => 'Trabajador',
            'Administrador RRHH' => 'Administrador RRHH',
            'Ingeniero' => 'Ingeniero',
            'Supervisor' => 'Supervisor',
            'Vendedor' => 'Vendedor',
            'CLEG Procurement User' => 'CLEG Procurement User',
        );

        if (function_exists('cleg_starter_assignable_roles')) {
            $starter_roles = cleg_starter_assignable_roles();
            if (is_array($starter_roles) && !empty($starter_roles)) {
                foreach ($starter_roles as $role_label) {
                    $role_label = sanitize_text_field($role_label);
                    if ($role_label !== '') {
                        $choices[$role_label] = $role_label;
                    }
                }
            }
        }

        $current_role = sanitize_text_field($current_role);
        if ($current_role !== '' && !isset($choices[$current_role])) {
            $choices[$current_role] = $current_role . ' (actual)';
        }

        return $choices;
    }
}

if (!function_exists('cleg_admin_employee_role_select')) {
    function cleg_admin_employee_role_select($name, $current_role = '', $aria_label = 'Rol', $style = '') {
        $html = '<select name="' . esc_attr($name) . '" aria-label="' . esc_attr($aria_label) . '"' . ($style !== '' ? ' style="' . esc_attr($style) . '"' : '') . '>';

        foreach (cleg_admin_employee_role_choices($current_role) as $role_value => $role_label) {
            $html .= '<option value="' . esc_attr($role_value) . '" ' . selected($current_role, $role_value, false) . '>' . esc_html($role_label) . '</option>';
        }

        $html .= '</select>';
        return $html;
    }
}

if (!function_exists('cleg_admin_employee_role_key_from_label')) {
    function cleg_admin_employee_role_key_from_label($role_label) {
        $role_label = sanitize_text_field($role_label);

        if (function_exists('cleg_starter_role_key_by_label')) {
            return cleg_starter_role_key_by_label($role_label);
        }

        $fallback = array(
            'Trabajador' => 'trabajador',
            'Administrador RRHH' => 'cleg_rrhh_admin',
            'CLEG RRHH Admin' => 'cleg_rrhh_admin',
            'CLEG Procurement User' => 'cleg_procurement_user',
            'CLEG Procurement Admin' => 'cleg_procurement_admin',
        );

        return isset($fallback[$role_label]) ? $fallback[$role_label] : '';
    }
}

if (!function_exists('cleg_admin_employee_role_tracks_time')) {
    function cleg_admin_employee_role_tracks_time($role_label) {
        $role_key = cleg_admin_employee_role_key_from_label($role_label);
        if ($role_key !== '') {
            $role = get_role($role_key);
            if ($role) {
                return $role->has_cap('cleg_clock_own_hours');
            }
        }

        return in_array($role_label, array('Trabajador', 'Supervisor'), true);
    }
}

if (!function_exists('cleg_admin_employee_tax_type_label')) {
