            . '<label>Emision<input type="date" name="issue_date"></label>'
            . '<label>Expiracion<input type="date" name="expiration_date"></label>'
            . '<label class="checkline"><input type="checkbox" name="portal_visible" value="1"> Visible en portal</label>'
            . '<label class="wide">Notas<textarea name="document_notes" rows="2"></textarea></label>'
            . '<button type="submit">Subir documento</button>'
            . '</form></div>';
    }
}

if (!function_exists('cleg_admin_employee_ensure_wp_user')) {
    function cleg_admin_employee_ensure_wp_user($wp_id, $username, $name, $employee_role, $phone = '') {
        $wp_id = absint($wp_id);
        $username = sanitize_user($username, true);
        $name = sanitize_text_field($name);
        $role_key = cleg_admin_employee_role_key_from_label($employee_role);
        $role_key = $role_key !== '' && get_role($role_key) ? $role_key : 'subscriber';

        if ($wp_id > 0) {
            if ((int) get_current_user_id() !== (int) $wp_id && get_user_by('id', $wp_id)) {
                wp_update_user(array('ID' => $wp_id, 'role' => $role_key));
            }
            update_user_meta((int) $wp_id, 'cleg_tenant_role', $employee_role);
            update_user_meta((int) $wp_id, 'cleg_tenant_status', 'active');
            return $wp_id;
        }

        if ($username === '') {
            return 0;
        }

        $existing_id = username_exists($username);
        if ($existing_id) {
            if ((int) get_current_user_id() !== (int) $existing_id) {
                wp_update_user(array('ID' => (int) $existing_id, 'role' => $role_key, 'display_name' => $name));
            }
            update_user_meta((int) $existing_id, 'cleg_tenant_role', $employee_role);
            update_user_meta((int) $existing_id, 'cleg_tenant_status', 'active');
            return (int) $existing_id;
        }

        $email_base = sanitize_title($username);
        $email = $email_base !== '' ? $email_base . '@cleg-portal.local' : 'worker-' . time() . '@cleg-portal.local';
        if (email_exists($email)) {
            $email = $email_base . '-' . time() . '@cleg-portal.local';
        }

        $user_id = wp_insert_user(array(
            'user_login' => $username,
            'user_pass' => wp_generate_password(20, true, true),
            'user_email' => $email,
            'display_name' => $name,
            'nickname' => $name,
            'role' => $role_key,
        ));

        if (is_wp_error($user_id)) {
            return 0;
        }

        update_user_meta((int) $user_id, 'cleg_portal_created_from_employee', current_time('mysql'));
        if (function_exists('cleg_access_default_tenant')) {
            $tenant = cleg_access_default_tenant();
            update_user_meta((int) $user_id, 'cleg_tenant_id', $tenant['id']);
            update_user_meta((int) $user_id, 'cleg_tenant_slug', $tenant['slug']);
            update_user_meta((int) $user_id, 'cleg_tenant_name', $tenant['name']);
            update_user_meta((int) $user_id, 'cleg_tenant_status', 'active');
        }
        update_user_meta((int) $user_id, 'cleg_tenant_role', $employee_role);
        if ($phone !== '') {
            update_user_meta((int) $user_id, 'cleg_worker_phone', sanitize_text_field($phone));
        }

        return (int) $user_id;
    }
}

