if (!function_exists('cleg_admin_employee_edit_form')) {
    function cleg_admin_employee_edit_form($employee) {
        $id = sanitize_text_field($employee['id']);
        $status = cleg_admin_field($employee, 'Status', 'Active');
        $role = cleg_admin_field($employee, 'Role', 'Trabajador');
        $tax_type = cleg_admin_field($employee, 'Payroll Tax Type', 'Employee - Full Payroll');
        $is_employee = $tax_type === 'Employee - Full Payroll';
        $is_contractor = in_array($tax_type, array('Contractor - 10% Withholding', 'Contractor - No Withholding'), true);
        $is_admin_no_payroll = $tax_type === 'Admin / No Payroll';
        $html = '<div class="cleg-panel cleg-employee-profile-panel"><div class="cleg-profile-head"><div><h2>Expediente</h2><p>Rol, permisos, tipo de trabajador, payroll y documentos aplicables se editan aqui.</p></div><a class="cleg-row-action" href="' . esc_url(home_url('/admin-empleados/')) . '">Volver a trabajadores</a></div><form class="cleg-admin-form cleg-employee-profile-form" method="post">'
            . wp_nonce_field('cleg_admin_employee_action', 'cleg_admin_employee_nonce', true, false)
            . '<input type="hidden" name="cleg_admin_employee_action" value="update">'
            . '<input type="hidden" name="employee_record_id" value="' . esc_attr($id) . '">'
            . '<label>Nombre<input name="employee_name" value="' . esc_attr(cleg_admin_field($employee, 'Employee Name')) . '" required></label>'
            . '<label>Usuario<input name="portal_username" value="' . esc_attr(cleg_admin_field($employee, 'Portal Username')) . '" required></label>'
            . '<label>WP ID<input name="wp_user_id" type="number" min="1" value="' . esc_attr(cleg_admin_field($employee, 'WordPress User ID')) . '" placeholder="Se crea automatico si se deja vacio"></label>'
            . '<label>Telefono<input name="phone" value="' . esc_attr(cleg_admin_field($employee, 'Phone')) . '"></label>'
            . '<label>Departamento<input name="department" value="' . esc_attr(cleg_admin_field($employee, 'Department')) . '"></label>'
            . '<label>Rol' . cleg_admin_employee_role_select('employee_role', $role, 'Rol del trabajador') . '</label>'
            . '<label>Tipo de trabajador / payroll' . cleg_admin_employee_tax_type_select($tax_type) . '</label>'
            . cleg_admin_employee_worker_type_notes()
            . '<label>Status<select name="employee_status"><option value="Active" ' . selected($status, 'Active', false) . '>Active</option><option value="Inactive" ' . selected($status, 'Inactive', false) . '>Inactive</option></select></label>'
            . ($is_admin_no_payroll ? '<input type="hidden" name="payroll_period" value="Per Hour"><input type="hidden" name="payroll_amount" value="0"><input type="hidden" name="payroll_fixed_deductions" value="0"><input type="hidden" name="payroll_form_type" value="No aplica / revisar">' : '');

        if ($is_employee) {
            $html .= '<div class="cleg-employee-subsection"><h3>Payroll empleado</h3>'
                . '<label>Base de pago<select name="payroll_period"><option value="Per Hour" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Per Hour', false) . '>Por hora</option><option value="Per Day" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Per Day', false) . '>Por dia</option><option value="Biweekly" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Biweekly', false) . '>Quincenal</option><option value="Fixed Per Period" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Fixed Per Period', false) . '>Fijo por periodo</option></select></label>'
                . '<label>Monto payroll<input name="payroll_amount" type="number" min="0" step="0.01" inputmode="decimal" value="' . esc_attr(cleg_admin_field($employee, 'Payroll Amount')) . '"></label>'
                . '<label>Deducciones fijas<input name="payroll_fixed_deductions" type="number" min="0" step="0.01" inputmode="decimal" value="' . esc_attr(cleg_admin_field($employee, 'Payroll Fixed Deductions')) . '"></label>'
                . '<label class="wide">Notas payroll<textarea name="payroll_comments" rows="2">' . esc_textarea(cleg_admin_field($employee, 'Payroll Comments')) . '</textarea></label>'
                . cleg_admin_employee_sinot_profile_fields($employee)
                . '</div>';
        } elseif ($is_contractor) {
            $html .= '<div class="cleg-employee-subsection"><h3>Contratista</h3>'
                . '<label>Base de pago<select name="payroll_period"><option value="Per Hour" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Per Hour', false) . '>Por hora</option><option value="Per Day" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Per Day', false) . '>Por dia</option><option value="Biweekly" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Biweekly', false) . '>Quincenal</option><option value="Fixed Per Period" ' . selected(cleg_admin_field($employee, 'Payroll Period'), 'Fixed Per Period', false) . '>Fijo por periodo</option></select></label>'
                . '<label>Monto payroll<input name="payroll_amount" type="number" min="0" step="0.01" inputmode="decimal" value="' . esc_attr(cleg_admin_field($employee, 'Payroll Amount')) . '"></label>'
                . '<label>Forma fiscal<select name="payroll_form_type"><option value="480.6SP" ' . selected(cleg_admin_field($employee, 'Payroll Form Type'), '480.6SP', false) . '>480.6SP</option><option value="No aplica / revisar" ' . selected(cleg_admin_field($employee, 'Payroll Form Type'), 'No aplica / revisar', false) . '>No aplica / revisar</option></select></label>'
                . '<label class="wide">Notas contratista / retencion / relevo<textarea name="withholding_reason" rows="2">' . esc_textarea(cleg_admin_field($employee, 'Withholding Reason')) . '</textarea></label>'
                . '<label class="wide">Notas de pago contratista<textarea name="payroll_comments" rows="2">' . esc_textarea(cleg_admin_field($employee, 'Payroll Comments')) . '</textarea></label>'
                . '</div>';
        } elseif ($is_admin_no_payroll) {
            $html .= '<div class="cleg-employee-subsection"><h3>Acceso administrativo</h3>'
                . '<label class="wide">Notas administrativas<textarea name="payroll_comments" rows="2">' . esc_textarea(cleg_admin_field($employee, 'Payroll Comments')) . '</textarea></label>'
                . '</div>';
        }

        return $html
            . '<button type="submit">Guardar empleado</button>'
            . cleg_admin_sms_link($employee)
            . '</form>'
            . cleg_admin_employee_document_upload_panel($employee, $tax_type)
            . '</div>';
    }
}

if (!function_exists('cleg_admin_handle_employee_action')) {
    function cleg_admin_handle_employee_action() {
        if (empty($_POST['cleg_admin_employee_action'])) {
            return;
        }

        if (!cleg_admin_user_allowed()) {
            return;
        }

        if (!isset($_POST['cleg_admin_employee_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_admin_employee_nonce'])), 'cleg_admin_employee_action')) {
            return;
        }

        $employee_action = sanitize_text_field(wp_unslash($_POST['cleg_admin_employee_action']));

        if ($employee_action === 'create_leave') {
            $result = cleg_admin_handle_employee_leave_action();
            $redirect_args = array('cleg_saved' => is_wp_error($result) ? '' : 'leave');
            if (is_wp_error($result)) {
                $redirect_args['cleg_admin_error'] = $result->get_error_message();
            }
            wp_safe_redirect(add_query_arg($redirect_args, remove_query_arg(array('_wp_http_referer'))));
            exit;
        }

        $name = isset($_POST['employee_name']) ? sanitize_text_field(wp_unslash($_POST['employee_name'])) : '';
        $username = isset($_POST['portal_username']) ? sanitize_user(wp_unslash($_POST['portal_username']), true) : '';

        if ($name === '' || $username === '') {
            return;
        }

        $employee_role = isset($_POST['employee_role']) ? sanitize_text_field(wp_unslash($_POST['employee_role'])) : 'Trabajador';
        $tax_type = isset($_POST['payroll_tax_type']) ? sanitize_text_field(wp_unslash($_POST['payroll_tax_type'])) : 'Employee - Full Payroll';
        $allowed_tax_types = array('Employee - Full Payroll', 'Contractor - 10% Withholding', 'Contractor - No Withholding', 'Admin / No Payroll');
        if (!in_array($tax_type, $allowed_tax_types, true)) {
            $tax_type = 'Employee - Full Payroll';
        }

        $fields = array(
            'Employee Name' => $name,
            'Portal Username' => $username,
            'Role' => $employee_role,
            'Status' => isset($_POST['employee_status']) ? sanitize_text_field(wp_unslash($_POST['employee_status'])) : 'Active',
            'Time Tracking Required' => cleg_admin_employee_role_tracks_time($employee_role),
            'Payroll Tax Type' => $tax_type,
        );

        if (isset($_POST['payroll_form_type'])) {
            $form_type = sanitize_text_field(wp_unslash($_POST['payroll_form_type']));
            $fields['Payroll Form Type'] = in_array($form_type, array('W-2PR / 499R-2', '480.6SP', 'No aplica / revisar'), true) ? $form_type : 'No aplica / revisar';
        }

        if (isset($_POST['payroll_period']) || isset($_POST['payroll_amount'])) {
            $period = isset($_POST['payroll_period']) ? sanitize_text_field(wp_unslash($_POST['payroll_period'])) : 'Per Hour';
            $amount = isset($_POST['payroll_amount']) ? (float) sanitize_text_field(wp_unslash($_POST['payroll_amount'])) : 0;
            $fields['Payroll Period'] = in_array($period, array('Per Hour', 'Per Day', 'Biweekly', 'Fixed Per Period'), true) ? $period : 'Per Hour';
            $fields['Payroll Amount'] = max(0, $amount);
        }

        if (isset($_POST['payroll_fixed_deductions'])) {
            $fields['Payroll Fixed Deductions'] = max(0, (float) sanitize_text_field(wp_unslash($_POST['payroll_fixed_deductions'])));
        }

        if (isset($_POST['withholding_reason'])) {
            $fields['Withholding Reason'] = sanitize_textarea_field(wp_unslash($_POST['withholding_reason']));
        }

        if (isset($_POST['payroll_comments'])) {
            $fields['Payroll Comments'] = sanitize_textarea_field(wp_unslash($_POST['payroll_comments']));
        }

        $wp_id = isset($_POST['wp_user_id']) ? absint($_POST['wp_user_id']) : 0;
        $phone = isset($_POST['phone']) ? sanitize_text_field(wp_unslash($_POST['phone'])) : '';
        $wp_id = cleg_admin_employee_ensure_wp_user($wp_id, $username, $name, $employee_role, $phone);
        if ($wp_id > 0) {
            $fields['WordPress User ID'] = $wp_id;
        }

        if ($phone !== '') {
            $fields['Phone'] = $phone;
        }

        $department = isset($_POST['department']) ? sanitize_text_field(wp_unslash($_POST['department'])) : '';
        if ($department !== '') {
            $fields['Department'] = $department;
        }

        if ($employee_action === 'update') {
            $record_id = isset($_POST['employee_record_id']) ? sanitize_text_field(wp_unslash($_POST['employee_record_id'])) : '';
            if ($record_id === '') {
                return;
            }
            cleg_hr_core_request('PATCH', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
                'body' => array(
                    'records' => array(array('id' => $record_id, 'fields' => $fields)),
                    'typecast' => true,
                ),
            ));
            cleg_admin_employee_update_tax_profile($record_id, $name);
        } else {
            cleg_hr_core_request('POST', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
                'body' => array(
                    'records' => array(array('fields' => $fields)),
                    'typecast' => true,
                ),
            ));
        }

        wp_safe_redirect(remove_query_arg(array('_wp_http_referer')));
        exit;
    }
}

