if (!function_exists('cleg_admin_project_compact_list')) {
    function cleg_admin_project_compact_list($sites, $project_stats) {
        $html = '<div class="cleg-mobile-only cleg-project-compact-list">';

        foreach ($sites as $site) {
            $project_name = cleg_admin_field($site, 'Job Site Name');
            $project_url = cleg_admin_context_url('/admin-job-sites/', array('cleg_project' => $project_name));
            $stats = $project_stats[$project_name] ?? array('employees' => array(), 'week_hours' => 0, 'open' => 0);
            $html .= '<a class="cleg-project-compact-card" href="' . esc_url($project_url) . '"><div><strong>' . esc_html($project_name ?: 'Sin nombre') . '</strong><span>' . esc_html(cleg_admin_field($site, 'Address', 'Sin direccion')) . '</span></div><div class="cleg-project-compact-meta"><b>' . esc_html(count($stats['employees'] ?? array())) . '</b><small>empleados</small></div><div class="cleg-project-compact-meta"><b>' . esc_html(cleg_admin_hours_label((float) ($stats['week_hours'] ?? 0))) . '</b><small>semana</small></div><i>›</i></a>';
        }

        if (empty($sites)) {
            $html .= '<article class="cleg-mobile-card"><strong>Todavia no hay proyectos.</strong></article>';
        }

        return $html . '</div>';
    }
}

if (!function_exists('cleg_admin_job_sites_shortcode')) {
    function cleg_admin_job_sites_shortcode() {
        $html = cleg_admin_page_open('jobs', 'Proyectos y geofence');

        if (strpos($html, 'cleg-admin-empty') !== false) {
            return $html;
        }

        $sites = cleg_admin_job_sites();

        if (is_wp_error($sites)) {
            return $html . cleg_admin_error($sites) . cleg_admin_page_close();
        }

        $project_records = cleg_admin_time_records('', 100);
        if (is_wp_error($project_records)) {
            $project_records = array();
        }
        $project_stats = array();
        $now = new DateTime('now', new DateTimeZone('America/Puerto_Rico'));
        $week_key = $now->format('o-W');

        foreach ($project_records as $record) {
            $project = cleg_admin_field($record, 'Job Site Name', 'Sin proyecto');
            $clock_in = cleg_admin_field($record, 'Admin Adjusted Clock In Time') ?: cleg_admin_field($record, 'Clock In Time');
            $clock_out = cleg_admin_field($record, 'Admin Adjusted Clock Out Time') ?: cleg_admin_field($record, 'Worker Reported Clock Out Time') ?: cleg_admin_field($record, 'Clock Out Time');
            $employee = cleg_admin_field($record, 'Employee Name', cleg_admin_field($record, 'Portal Username', 'Sin empleado'));
            $project_stats[$project]['employees'][$employee] = true;
            $project_stats[$project]['open'] = ($project_stats[$project]['open'] ?? 0) + ($clock_out === '' ? 1 : 0);

            $dt = cleg_admin_pr_datetime($clock_in);
            if ($dt && $dt->format('o-W') === $week_key) {
                $effective_out = $clock_out !== '' ? $clock_out : $now->format('Y-m-d H:i:s');
                $project_stats[$project]['week_hours'] = ($project_stats[$project]['week_hours'] ?? 0) + cleg_admin_hours_float($clock_in, $effective_out);
            }
        }

        $selected_project = isset($_GET['cleg_project']) ? sanitize_text_field(wp_unslash($_GET['cleg_project'])) : '';
        if ($selected_project !== '') {
            $project_hours = cleg_admin_time_records("{Job Site Name}='" . cleg_admin_formula_text($selected_project) . "'", 100);

            if (is_wp_error($project_hours)) {
                return $html . cleg_admin_error($project_hours) . cleg_admin_page_close();
            }

            $html .= cleg_admin_context_hours_panel('Proyecto: ' . $selected_project, $project_hours, $sites, home_url('/admin-job-sites/'));
            $html .= '<div class="cleg-panel cleg-project-list-link"><div class="cleg-panel-head"><div><h2>Proyectos existentes</h2><p>La edicion de proyectos vive en la lista general. Esta vista es solo para consultar horas del proyecto seleccionado.</p></div><a class="cleg-row-action" href="' . esc_url(home_url('/admin-job-sites/')) . '">Ver lista de proyectos</a></div></div>';
            return $html . cleg_admin_page_close();
        }

        $html .= cleg_admin_job_site_form();
        $html .= cleg_admin_project_compact_list($sites, $project_stats);
        $html .= '<div class="cleg-panel cleg-project-table-panel"><h2>Proyectos existentes</h2><div class="cleg-table-wrap"><table><thead><tr><th>Proyecto</th><th>Direccion</th><th>Geofence</th><th>Status</th><th>Supervisor</th><th>Editar</th></tr></thead><tbody>';

        foreach ($sites as $site) {
            $record_id = sanitize_text_field($site['id']);
            $lat = cleg_admin_field($site, 'Latitude');
            $lng = cleg_admin_field($site, 'Longitude');
            $map_url = ($lat !== '' && $lng !== '') ? 'https://www.openstreetmap.org/?mlat=' . rawurlencode($lat) . '&mlon=' . rawurlencode($lng) . '#map=17/' . rawurlencode($lat) . '/' . rawurlencode($lng) : '';
            $project_name = cleg_admin_field($site, 'Job Site Name');
            $project_url = cleg_admin_context_url('/admin-job-sites/', array('cleg_project' => $project_name));
            $stats = $project_stats[$project_name] ?? array('employees' => array(), 'week_hours' => 0, 'open' => 0);
            $project_meta = '<span class="cleg-project-mini">&rsaquo; ' . count($stats['employees'] ?? array()) . ' empleados detectados</span><span class="cleg-project-mini">&rsaquo; ' . cleg_admin_hours_label((float) ($stats['week_hours'] ?? 0)) . ' semana</span>' . (!empty($stats['open']) ? '<span class="cleg-project-mini is-warn">&rsaquo; ' . (int) $stats['open'] . ' abierta(s)</span>' : '');
            $html .= '<tr><td><a class="cleg-cell-link" href="' . esc_url($project_url) . '"><strong>' . esc_html($project_name) . '</strong>' . $project_meta . '</a></td><td><a class="cleg-cell-link" href="' . esc_url($project_url) . '">' . esc_html(cleg_admin_field($site, 'Address')) . '</a></td><td>' . esc_html(cleg_admin_field($site, 'Allowed Radius Meters', '150')) . ' m<small>' . ($map_url !== '' ? '<a href="' . esc_url($map_url) . '" target="_blank" rel="noopener">Ver mapa</a>' : 'Sin coordenadas') . '</small></td><td>' . esc_html(cleg_admin_field($site, 'Status')) . '</td><td><a class="cleg-cell-link" href="' . esc_url($project_url) . '">' . esc_html(cleg_admin_field($site, 'Supervisor')) . '<small>' . esc_html(cleg_admin_field($site, 'Supervisor Email')) . '</small></a></td><td><div class="cleg-project-actions" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;"><a class="cleg-row-action" href="' . esc_url($project_url) . '">Ver horas</a>' . cleg_admin_job_site_form($site) . '</div></td></tr>';
        }

        if (empty($sites)) {
            $html .= '<tr><td colspan="6">Todavia no hay proyectos.</td></tr>';
        }

        $html .= '</tbody></table></div></div>';

        return $html . cleg_admin_page_close();
    }
}

