            . '<label class="cleg-check"><input type="checkbox" name="requires_geo" value="1" ' . checked((bool) $requires, true, false) . '> Requiere geofence</label>'
            . '<label>Supervisor<input name="supervisor" value="' . esc_attr($supervisor) . '"></label>'
            . '<label>Email supervisor<input name="supervisor_email" type="email" value="' . esc_attr($email) . '"></label>'
            . '<label>Notas<textarea name="job_site_notes" rows="2">' . esc_textarea($notes) . '</textarea></label>'
