if (!function_exists('cleg_admin_geocode_address')) {
    function cleg_admin_geocode_address($address) {
        $address = trim((string) $address);

        if ($address === '') {
            return false;
        }

        $url = add_query_arg(array(
            'format' => 'json',
            'limit' => 1,
            'q' => $address,
        ), 'https://nominatim.openstreetmap.org/search');

        $response = wp_remote_get($url, array(
            'timeout' => 15,
            'headers' => array(
                'User-Agent' => 'CLEG-RRHH-Portal/1.0; ' . home_url('/'),
            ),
        ));

        if (is_wp_error($response)) {
            return false;
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);

        if (empty($body[0]['lat']) || empty($body[0]['lon'])) {
            return false;
        }

        return array(
            'lat' => (float) $body[0]['lat'],
            'lng' => (float) $body[0]['lon'],
        );
    }
}

if (!function_exists('cleg_admin_valid_lat_lng')) {
    function cleg_admin_valid_lat_lng($lat, $lng) {
        if ($lat === '' || $lng === '' || !is_numeric($lat) || !is_numeric($lng)) {
            return false;
        }

        $lat = (float) $lat;
        $lng = (float) $lng;

        return $lat >= -90 && $lat <= 90 && $lng >= -180 && $lng <= 180;
    }
}

if (!function_exists('cleg_admin_handle_job_site_action')) {
    function cleg_admin_handle_job_site_action() {
        if (empty($_POST['cleg_admin_job_site_action'])) {
            return;
        }

        if (!cleg_admin_user_allowed()) {
            return;
        }

        if (!isset($_POST['cleg_admin_job_site_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_admin_job_site_nonce'])), 'cleg_admin_job_site_action')) {
            return;
        }

        $record_id = isset($_POST['job_site_record_id']) ? sanitize_text_field(wp_unslash($_POST['job_site_record_id'])) : '';
        $name = isset($_POST['job_site_name']) ? sanitize_text_field(wp_unslash($_POST['job_site_name'])) : '';
        $address = isset($_POST['job_site_address']) ? sanitize_textarea_field(wp_unslash($_POST['job_site_address'])) : '';

        if ($name === '' || $address === '') {
            return;
        }

        $radius = isset($_POST['allowed_radius']) ? max(25, (int) $_POST['allowed_radius']) : 150;
        $status = isset($_POST['job_site_status']) ? sanitize_text_field(wp_unslash($_POST['job_site_status'])) : 'Active';
        $posted_lat = isset($_POST['job_site_latitude']) ? sanitize_text_field(wp_unslash($_POST['job_site_latitude'])) : '';
        $posted_lng = isset($_POST['job_site_longitude']) ? sanitize_text_field(wp_unslash($_POST['job_site_longitude'])) : '';
        $geo = cleg_admin_valid_lat_lng($posted_lat, $posted_lng)
            ? array('lat' => (float) $posted_lat, 'lng' => (float) $posted_lng)
            : cleg_admin_geocode_address($address);
        $fields = array(
            'Job Site Name' => $name,
            'Address' => $address,
            'Allowed Radius Meters' => $radius,
            'Status' => in_array($status, array('Active', 'Inactive'), true) ? $status : 'Active',
            'Requires Geolocation' => !empty($_POST['requires_geo']),
            'Supervisor' => isset($_POST['supervisor']) ? sanitize_text_field(wp_unslash($_POST['supervisor'])) : '',
            'Supervisor Email' => isset($_POST['supervisor_email']) ? sanitize_email(wp_unslash($_POST['supervisor_email'])) : '',
            'Notes' => isset($_POST['job_site_notes']) ? sanitize_textarea_field(wp_unslash($_POST['job_site_notes'])) : '',
        );

        if (is_array($geo)) {
            $fields['Latitude'] = $geo['lat'];
            $fields['Longitude'] = $geo['lng'];
            $fields['Map Link'] = 'https://www.openstreetmap.org/?mlat=' . rawurlencode((string) $geo['lat']) . '&mlon=' . rawurlencode((string) $geo['lng']) . '#map=17/' . rawurlencode((string) $geo['lat']) . '/' . rawurlencode((string) $geo['lng']);
        }

        $body_record = array('fields' => $fields);
        if ($record_id !== '') {
            $body_record['id'] = $record_id;
            cleg_projects_request('PATCH', CLEG_AIRTABLE_JOBSITES_TABLE, array(
                'body' => array('records' => array($body_record), 'typecast' => true),
            ));
        } else {
            cleg_projects_request('POST', CLEG_AIRTABLE_JOBSITES_TABLE, array(
                'body' => array('records' => array($body_record), 'typecast' => true),
            ));
        }

        wp_safe_redirect(remove_query_arg(array('_wp_http_referer')));
        exit;
    }
}

if (!function_exists('cleg_admin_geofence_assets')) {
    function cleg_admin_geofence_assets() {
        static $printed = false;

        if ($printed) {
            return '';
        }

        $printed = true;

        return <<<'HTML'
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIINfQPDq0sMLdEAsl5a0KewM3ypJfwvGZM=" crossorigin="">
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script>
<script>
(function(){
  function num(value, fallback){
    var parsed = parseFloat(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }

  var leafletPromise = null;

  function loadAsset(kind, url){
    return new Promise(function(resolve, reject){
      var selector = kind === 'css' ? 'link[href="' + url + '"]' : 'script[src="' + url + '"]';
      var existing = document.querySelector(selector);
      if (existing) {
        if (kind === 'css' || existing.dataset.loaded === '1' || window.L) resolve();
        else {
          existing.addEventListener('load', resolve, {once:true});
          existing.addEventListener('error', function(){
            existing.remove();
            loadAsset(kind, url).then(resolve).catch(reject);
          }, {once:true});
          setTimeout(function(){
            if (!window.L && document.contains(existing)) {
              existing.remove();
              loadAsset(kind, url).then(resolve).catch(reject);
            }
          }, 900);
        }
        return;
      }
      var el = kind === 'css' ? document.createElement('link') : document.createElement('script');
      if (kind === 'css') {
        el.rel = 'stylesheet';
        el.href = url;
      } else {
        el.src = url;
        el.async = true;
      }
      el.addEventListener('load', function(){ el.dataset.loaded = '1'; resolve(); }, {once:true});
      el.addEventListener('error', reject, {once:true});
      document.head.appendChild(el);
    });
  }

  function ensureLeaflet(){
    if (window.L) return Promise.resolve();
    if (!leafletPromise) {
      leafletPromise = loadAsset('css', 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css')
        .then(function(){ return loadAsset('js', 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'); });
    }
    return leafletPromise;
  }

  function syncInputs(wrapper, latlng){
    var latInput = wrapper.querySelector('.cleg-geofence-lat');
    var lngInput = wrapper.querySelector('.cleg-geofence-lng');
    if (!latInput || !lngInput || !latlng) return;
    latInput.value = latlng.lat.toFixed(6);
    lngInput.value = latlng.lng.toFixed(6);
    updateSelected(wrapper, latlng);
    markDirty(wrapper.closest('details'));
  }

  function updateSelected(wrapper, latlng){
    var selected = wrapper ? wrapper.querySelector('.cleg-geofence-selected span') : null;
    if (!selected || !latlng) return;
    selected.textContent = latlng.lat.toFixed(6) + ', ' + latlng.lng.toFixed(6);
  }

  function refreshMap(wrapper){
    if (!wrapper || !wrapper._clegMap) return;
    [80, 180, 360, 700].forEach(function(delay){
      setTimeout(function(){
        wrapper._clegMap.invalidateSize(true);
        if (wrapper._clegMarker) {
          var current = wrapper._clegMarker.getLatLng();
          wrapper._clegMap.setView(current, wrapper._clegMap.getZoom(), {animate:false});
          wrapper._clegMarker.update();
        }
        if (wrapper._clegTileLayer && wrapper._clegTileLayer.redraw) wrapper._clegTileLayer.redraw();
      }, delay);
    });
  }

  function initPicker(wrapper){
    if (!wrapper) return;
    var attempts = parseInt(wrapper.dataset.initAttempts || '0', 10);
    if (!window.L) {
      if (attempts < 24) {
        wrapper.dataset.initAttempts = String(attempts + 1);
        ensureLeaflet().then(function(){ initPicker(wrapper); }).catch(function(){
          setTimeout(function(){ initPicker(wrapper); }, 240);
        });
      }
      return;
    }
    var mapEl = wrapper.querySelector('.cleg-geofence-map');
    if (!mapEl || (mapEl.offsetWidth === 0 && mapEl.offsetHeight === 0)) {
      if (attempts < 24) {
        wrapper.dataset.initAttempts = String(attempts + 1);
        setTimeout(function(){ initPicker(wrapper); }, 160);
      }
      return;
    }
    if (wrapper.dataset.ready === '1') { refreshMap(wrapper); return; }
    wrapper.dataset.initAttempts = '0';
    wrapper.dataset.ready = '1';

    var form = wrapper.closest('form');
    var radiusInput = form ? form.querySelector('.cleg-geofence-radius') : null;
    var latInput = wrapper.querySelector('.cleg-geofence-lat');
    var lngInput = wrapper.querySelector('.cleg-geofence-lng');
    var hasCoords = !!(latInput && latInput.value && lngInput && lngInput.value);
    var lat = num(wrapper.dataset.lat || (latInput && latInput.value), 18.2208);
    var lng = num(wrapper.dataset.lng || (lngInput && lngInput.value), -66.5901);
    var radius = Math.max(25, num(wrapper.dataset.radius || (radiusInput && radiusInput.value), 150));
    var center = [lat, lng];

    var map = L.map(mapEl, {scrollWheelZoom:true, tap:true, zoomControl:false}).setView(center, hasCoords ? 17 : 9);
    var tileLayer = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 20,
      attribution: '&copy; OpenStreetMap contributors'
    }).addTo(map);

    var markerIcon = L.divIcon({
      className: '',
      html: '<div class="cleg-geofence-marker" aria-hidden="true"></div>',
      iconSize: [34, 34],
      iconAnchor: [17, 17]
    });
    var marker = L.marker(center, {draggable:true, icon:markerIcon, zIndexOffset:1000}).addTo(map);
    var circle = L.circle(center, {
      radius: radius,
      color: '#c75000',
      weight: 2,
      fillColor: '#c75000',
      fillOpacity: 0.12
    }).addTo(map);
    updateSelected(wrapper, L.latLng(lat, lng));

    function setCenter(latlng, zoom){
      marker.setLatLng(latlng);
      circle.setLatLng(latlng);
      syncInputs(wrapper, latlng);
      map.setView(latlng, zoom || map.getZoom(), {animate:false});
      refreshMap(wrapper);
    }

    marker.on('dragend', function(){ setCenter(marker.getLatLng()); });
    map.on('click', function(event){ setCenter(event.latlng); });

    if (radiusInput) {
      radiusInput.addEventListener('input', function(){
        circle.setRadius(Math.max(25, num(radiusInput.value, 150)));
        markDirty(wrapper.closest('details'));
      });
    }

    if (latInput && lngInput) {
      [latInput, lngInput].forEach(function(input){
        input.addEventListener('change', function(){
          var manualLat = num(latInput.value, null);
          var manualLng = num(lngInput.value, null);
          if (manualLat !== null && manualLng !== null) {
            setCenter(L.latLng(manualLat, manualLng), 17);
          }
        });
      });
    }

    var current = wrapper.querySelector('.cleg-geofence-current');
    if (current && navigator.geolocation) {
      current.addEventListener('click', function(){
        navigator.geolocation.getCurrentPosition(function(position){
          setCenter(L.latLng(position.coords.latitude, position.coords.longitude), 18);
        });
      });
    }

    wrapper._clegMap = map;
    wrapper._clegMarker = marker;
    wrapper._clegTileLayer = tileLayer;
    refreshMap(wrapper);
  }

  function initVisible(scope){
    (scope || document).querySelectorAll('.cleg-geofence-picker').forEach(initPicker);
  }

  function queueInit(scope){
    [0, 80, 180, 360, 700, 1200].forEach(function(delay){
      setTimeout(function(){ initVisible(scope || document); }, delay);
    });
  }

  function markDirty(details){
    if (!details) return;
    details.classList.add('is-dirty');
  }

  function nudgeSave(details){
    if (!details) return;
    details.classList.remove('needs-save');
    void details.offsetWidth;
    details.classList.add('needs-save');
    setTimeout(function(){ details.classList.remove('needs-save'); }, 700);
  }

  function closeEditor(details, force){
    if (!details) return;
    if (details.classList.contains('is-dirty') && !force) {
      nudgeSave(details);
      return;
    }
    details.open = false;
    details.removeAttribute('open');
    details.classList.remove('is-dirty', 'needs-save');
  }

  document.addEventListener('DOMContentLoaded', function(){
    ensureLeaflet().catch(function(){});
    queueInit(document);
    document.querySelectorAll('.cleg-project-edit').forEach(function(details){
      var form = details.querySelector('form');
      if (form) {
        form.addEventListener('input', function(){ markDirty(details); });
        form.addEventListener('change', function(){ markDirty(details); });
        form.addEventListener('submit', function(){ details.classList.remove('is-dirty', 'needs-save'); });
      }
      var close = details.querySelector('.cleg-project-modal-close');
      if (close) {
        close.addEventListener('click', function(event){
          event.preventDefault();
          event.stopPropagation();
          if (details.classList.contains('is-dirty') && !window.confirm('Tienes cambios sin guardar. Deseas cerrar sin guardar?')) {
            nudgeSave(details);
            return;
          }
          closeEditor(details, true);
        });
      }
      var backdrop = details.querySelector('.cleg-project-modal-backdrop');
      if (backdrop) {
        backdrop.addEventListener('click', function(){ closeEditor(details, false); });
      }
    });
  });

  document.addEventListener('toggle', function(event){
    if (event.target && event.target.open && event.target.querySelector('.cleg-geofence-picker')) {
      queueInit(event.target);
    }
  }, true);
})();
</script>
HTML;
    }
}

