if (!defined('ABSPATH')) {
    exit;
}


if (!function_exists('cleg_admin_absence_dates')) {
    function cleg_admin_absence_dates($requests) {
        $dates = array();
        foreach ((array) $requests as $request) {
            $status = cleg_admin_field($request, 'Status');
            if ($status === 'Deleted') {
                continue;
            }
            $date = cleg_admin_absence_request_day($request);
            $timestamp = strtotime($date);
            if (!$timestamp) {
                continue;
            }
            $key = gmdate('Y-m-d', $timestamp);
            if (!isset($dates[$key])) {
                $dates[$key] = array();
            }
            $dates[$key][] = array(
                'employee' => cleg_admin_field($request, 'Employee Name', cleg_admin_field($request, 'Portal Username')),
                'type' => cleg_admin_field($request, 'Request Type', 'Solicitud'),
                'status' => $status ?: 'Pending',
                'details' => cleg_admin_field($request, 'Details'),
            );
        }
        return $dates;
    }
}

if (!function_exists('cleg_admin_absence_request_day')) {
    function cleg_admin_absence_request_day($request) {
        $details = cleg_admin_field($request, 'Details');
        if (preg_match('/Dia que faltaste:\s*(\d{4}-\d{2}-\d{2})/i', $details, $matches)) {
            return $matches[1];
        }

        return cleg_admin_field($request, 'Request Date');
    }
}

if (!function_exists('cleg_admin_absence_calendar')) {
    function cleg_admin_absence_calendar($requests) {
        $dates = cleg_admin_absence_dates($requests);
        $month_param = isset($_GET['cleg_abs_month']) ? sanitize_text_field(wp_unslash($_GET['cleg_abs_month'])) : '';
        $base = current_time('timestamp');
        if ($month_param !== '' && preg_match('/^\d{4}-\d{2}$/', $month_param)) {
            $candidate = strtotime($month_param . '-01 12:00:00');
            if ($candidate) {
                $base = $candidate;
            }
        }
        $start = strtotime(gmdate('Y-m-01', $base));
        $days = (int) gmdate('t', $start);
        $first_weekday = (int) gmdate('N', $start);
        $week_start = strtotime('monday this week', $base);
        $prev_month = gmdate('Y-m', strtotime('-1 month', $start));
        $next_month = gmdate('Y-m', strtotime('+1 month', $start));
        $week_keys = array();
        for ($i = 0; $i < 7; $i++) {
            $week_keys[] = gmdate('Y-m-d', strtotime('+' . $i . ' days', $week_start));
        }

        $html = '<style>.cleg-calendar-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.cleg-calendar-actions a{display:inline-flex;align-items:center;justify-content:center;min-height:38px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink)!important;-webkit-text-fill-color:var(--ink)!important;padding:8px 12px;font-size:12px;font-weight:900;text-decoration:none!important}.cleg-calendar-actions a:hover{background:#182537;color:#fff!important;-webkit-text-fill-color:#fff!important}</style><div class="cleg-absence-board"><div class="cleg-calendar-head"><div><strong>' . esc_html(wp_date('F Y', $base)) . '</strong><span>Vista mensual con agenda semanal de solicitudes.</span></div><div class="cleg-calendar-actions"><a href="' . esc_url(add_query_arg('cleg_abs_month', $prev_month)) . '">Mes anterior</a><a href="' . esc_url(remove_query_arg('cleg_abs_month')) . '">Mes actual</a><a href="' . esc_url(add_query_arg('cleg_abs_month', $next_month)) . '">Mes siguiente</a></div></div><div class="cleg-calendar-grid cleg-calendar-week"><span>L</span><span>M</span><span>X</span><span>J</span><span>V</span><span>S</span><span>D</span></div><div class="cleg-calendar-grid cleg-calendar-month">';

        for ($blank = 1; $blank < $first_weekday; $blank++) {
            $html .= '<span class="is-empty"></span>';
        }

        for ($day = 1; $day <= $days; $day++) {
            $key = gmdate('Y-m-', $start) . str_pad((string) $day, 2, '0', STR_PAD_LEFT);
            $items = $dates[$key] ?? array();
            $class = !empty($items) ? ' has-absence' : '';
            $titles = array();
            $day_details = '';

            foreach (array_slice($items, 0, 3) as $item) {
                $label = trim(($item['type'] ?? 'Solicitud') . ': ' . ($item['employee'] ?? ''));
                $detail = trim((string) ($item['details'] ?? ''));
                $titles[] = $detail !== '' ? $label . ' - ' . $detail : $label;
                $status_class = ($item['status'] ?? '') === 'Approved' ? 'is-ok' : (($item['status'] ?? '') === 'Rejected' ? 'is-bad' : 'is-warn');
                $day_details .= '<small class="' . esc_attr($status_class) . '"><b>' . esc_html($item['employee']) . '</b><em>' . esc_html($item['type']) . '</em></small>';
            }

            $title = !empty($titles) ? esc_attr(implode(' | ', array_unique($titles))) : '';
            $more = count($items) > 3 ? '<small class="is-more">+' . esc_html(count($items) - 3) . ' mas</small>' : '';
            $html .= '<span class="' . esc_attr(trim($class)) . '" title="' . $title . '"><b>' . esc_html($day) . '</b>' . (!empty($items) ? '<em>' . esc_html(count($items)) . '</em>' . $day_details . $more : '') . '</span>';
        }

        $html .= '</div><div class="cleg-absence-agenda"><div class="cleg-panel-head"><div><h3>Semana actual</h3></div></div>';
        foreach ($week_keys as $key) {
            $items = $dates[$key] ?? array();
            // $key is a civil date generated in UTC, not an instant to localize.
            $html .= '<section><strong>' . esc_html(wp_date('D m/d', strtotime($key . ' UTC'), new DateTimeZone('UTC'))) . '</strong>';
            if (empty($items)) {
                $html .= '<span class="cleg-absence-empty">Sin solicitudes</span>';
            }
            foreach ($items as $item) {
                $status_class = ($item['status'] ?? '') === 'Approved' ? 'is-ok' : (($item['status'] ?? '') === 'Rejected' ? 'is-bad' : 'is-warn');
                $html .= '<article><div><b>' . esc_html($item['employee']) . '</b><small>' . esc_html($item['type']) . ' · ' . esc_html($item['details'] ?: 'Sin razón escrita') . '</small></div><span class="cleg-pill ' . esc_attr($status_class) . '">' . esc_html($item['status']) . '</span></article>';
            }
            $html .= '</section>';
        }

        return $html . '</div></div>';
    }
}

if (!function_exists('cleg_admin_request_metric_link')) {
    function cleg_admin_request_metric_link($label, $value, $filter, $active_filter) {
        $args = $_GET;
        $args['cleg_request_filter'] = $filter;
        unset($args['_wp_http_referer']);
        $url = add_query_arg($args) . '#cleg-requests-table';
        $class = 'cleg-metric cleg-metric-link' . ($active_filter === $filter ? ' is-active' : '');

        return '<a class="' . esc_attr($class) . '" href="' . esc_url($url) . '"><strong>' . esc_html((string) $value) . '</strong><span>' . esc_html($label) . '</span><small>Ver en tabla</small></a>';
    }
}

if (!function_exists('cleg_admin_filter_hr_requests_for_table')) {
    function cleg_admin_filter_hr_requests_for_table($requests, $filter) {
        $filter = sanitize_key($filter);
        if (!in_array($filter, array('pending', 'approved', 'historic', 'absence'), true)) {
            return $requests;
        }

        return array_values(array_filter((array) $requests, function ($request) use ($filter) {
            $status = cleg_admin_field($request, 'Status');
            $type = cleg_admin_field($request, 'Request Type');

            if ($filter === 'pending') {
                return $status === '' || $status === 'Pending';
            }

            if ($filter === 'approved') {
                return $status === 'Approved';
            }

            if ($filter === 'historic') {
                return in_array($status, array('Rejected', 'Deleted'), true);
            }

            return $type === 'Ausencia' && $status !== 'Deleted';
        }));
    }
}

if (!function_exists('cleg_admin_hr_request_action_form')) {
    function cleg_admin_hr_request_action_form($request) {
        $id = sanitize_text_field($request['id'] ?? '');
        $status = cleg_admin_field($request, 'Status');

        if ($id === '' || $status === 'Deleted') {
            return '<small>Sin accion</small>';
        }

        $is_pending = ($status === '' || $status === 'Pending' || $status === 'Pending Review' || $status === 'Open');
        $decision = !$is_pending ? '<small>Decision tomada</small>' : '<form class="cleg-request-actions cleg-mobile-actions" method="post">'
            . wp_nonce_field('cleg_admin_hr_request_action', 'cleg_admin_hr_request_nonce', true, false)
            . '<input type="hidden" name="cleg_admin_hr_request_id" value="' . esc_attr($id) . '">'
            . '<button class="is-approve cleg-row-action" type="submit" name="cleg_admin_hr_request_action" value="approve">Aprobar</button>'
            . '</form>';

        return '<div class="cleg-request-action-stack">' . $decision
            . '<details class="cleg-request-delete"><summary class="cleg-row-action">Eliminar por error</summary><form class="cleg-inline-action" method="post">'
            . wp_nonce_field('cleg_admin_hr_request_action', 'cleg_admin_hr_request_nonce', true, false)
            . '<input type="hidden" name="cleg_admin_hr_request_id" value="' . esc_attr($id) . '">'
            . '<label>Motivo<input type="text" name="cleg_hr_delete_reason" required placeholder="Ej: creado por error"></label>'
            . '<button class="is-delete" type="submit" name="cleg_admin_hr_request_action" value="delete">Eliminar con auditoria</button>'
            . '</form></details></div>';
    }
}

if (!function_exists('cleg_admin_solicitudes_shortcode')) {
    function cleg_admin_solicitudes_shortcode() {
        $html = cleg_admin_page_open('requests', 'Solicitudes y ausencias', 'Ausencias, permisos y novedades enviadas por trabajadores.');

        if (strpos($html, 'cleg-admin-empty') !== false) {
            return $html;
        }

        $requests = cleg_admin_hr_requests(100);

        if (is_wp_error($requests)) {
            return $html . cleg_admin_error($requests) . cleg_admin_page_close();
        }

        $counts = cleg_admin_request_status_counts($requests);
        $groups = cleg_admin_split_hr_requests($requests);
        $absence_total = 0;
        foreach ($groups['operational'] as $request) {
            if (cleg_admin_field($request, 'Request Type') === 'Ausencia') {
                $absence_total++;
            }
        }
        $history_total = count($groups['history']);

        $html .= '<style>.cleg-requests-summary-table th,.cleg-requests-summary-table td{vertical-align:top}.cleg-requests-summary-table td strong{display:block;font-size:14px;line-height:1.25}.cleg-requests-summary-table td small{display:block;color:var(--muted);font-size:12px;line-height:1.35;margin-top:4px}.cleg-request-reason{display:block;max-width:360px;line-height:1.35}.cleg-request-group-actions summary{display:inline-flex;align-items:center;justify-content:center;min-height:34px;border-radius:8px;background:#eef2f7;color:var(--ink);padding:7px 10px;font-weight:900;cursor:pointer}.cleg-request-group-actions>div{display:grid;grid-template-columns:minmax(84px,.7fr) minmax(0,1fr);gap:8px;align-items:center;margin-top:8px}.cleg-request-group-actions .cleg-request-action-stack{margin:0}.cleg-requests-history{overflow:hidden}.cleg-requests-history>summary{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px 20px;cursor:pointer;list-style:none}.cleg-requests-history>summary::-webkit-details-marker{display:none}.cleg-requests-history>summary strong{display:block;color:var(--ink);font-size:18px}.cleg-requests-history>summary small{display:block;color:var(--muted);font-size:12px;margin-top:3px}.cleg-requests-history>.cleg-panel{border:0;border-top:1px solid var(--line);border-radius:0;box-shadow:none;margin:0}.cleg-requests-history>.cleg-panel>.cleg-panel-head{display:none}.cleg-requests-history .cleg-table-wrap{border:0;border-radius:0}@media(max-width:760px){.cleg-requests-summary-table thead{display:none}.cleg-requests-summary-table tr{display:grid;grid-template-columns:1fr;gap:8px;padding:12px}.cleg-requests-summary-table td{display:block;border:0!important;padding:0!important}.cleg-request-reason{max-width:none}}</style>';

        $html .= '<div class="cleg-metrics-grid cleg-metrics-grid-compact">'
            . '<div class="cleg-metric"><strong>' . esc_html((string) count($groups['approved'])) . '</strong><span>Aprobadas</span><small>Impactan la operacion</small></div>'
            . '<div class="cleg-metric"><strong>' . esc_html((string) $absence_total) . '</strong><span>Ausencias activas</span><small>Pendientes o aprobadas</small></div>'
            . '<div class="cleg-metric"><strong>' . esc_html((string) $history_total) . '</strong><span>Historial</span><small>Canceladas, rechazadas u otros estados</small></div>'
            . '</div>';

        $html .= '<div class="cleg-panel cleg-absence-panel"><div class="cleg-panel-head"><div><h2>Calendario de ausencias</h2></div></div>' . cleg_admin_absence_calendar($groups['operational']) . '</div>';

        if (!empty($groups['pending'])) {
            $html .= cleg_admin_requests_table($groups['pending'], 100, 'Por atender', 'Solicitudes nuevas o pendientes que requieren una decision.', false);
        }

        $html .= cleg_admin_requests_table($groups['approved'], 100, 'Aprobadas', 'Solicitudes confirmadas que pueden afectar agenda, ausencias u operacion.', false);

        $html .= '<details class="cleg-panel cleg-requests-history"><summary><span><strong>Historial</strong><small>' . esc_html((string) $history_total) . ' solicitud(es) canceladas, rechazadas u otros estados.</small></span></summary>'
            . cleg_admin_requests_table($groups['history'], 100, 'Historial', 'Registros conservados para auditoria y consulta; no requieren accion diaria.', false)
            . '</details>';

        return $html . cleg_admin_page_close();
    }
}

if (!function_exists('cleg_admin_handle_hr_request_action')) {
    function cleg_admin_handle_hr_request_action() {
        if (empty($_POST['cleg_admin_hr_request_action']) || empty($_POST['cleg_admin_hr_request_id'])) {
            return;
        }

        if (!cleg_admin_user_allowed()) {
            return;
        }

        if (!isset($_POST['cleg_admin_hr_request_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_admin_hr_request_nonce'])), 'cleg_admin_hr_request_action')) {
            return;
        }

        $action = sanitize_text_field(wp_unslash($_POST['cleg_admin_hr_request_action']));
        $record_id = sanitize_text_field(wp_unslash($_POST['cleg_admin_hr_request_id']));
        if (!in_array($action, array('approve', 'delete'), true)) {
            return;
        }

        $current_record = cleg_admin_hr_request_by_id($record_id);
        if (is_wp_error($current_record) || empty($current_record)) {
            return;
        }

        $old_status = cleg_admin_field($current_record, 'Status');
        $status = $action === 'approve' ? 'Approved' : 'Deleted';
        $delete_reason = isset($_POST['cleg_hr_delete_reason']) ? sanitize_text_field(wp_unslash($_POST['cleg_hr_delete_reason'])) : '';
        $reason = $action === 'delete' ? ($delete_reason !== '' ? $delete_reason : 'Creado por error') : '';
        $user = wp_get_current_user();
        $actor_name = $user && $user->exists() ? ($user->display_name ?: $user->user_login) : 'Admin';
        $current_notes = cleg_admin_field($current_record, 'Admin Notes');
        $employee = cleg_admin_field($current_record, 'Employee Name');
        $username = cleg_admin_field($current_record, 'Portal Username');
        $audit_label = $action === 'delete' ? 'Solicitud eliminada' : 'Status';

        cleg_forms_requests_request('PATCH', CLEG_AIRTABLE_HR_REQUESTS_TABLE, array(
            'body' => array(
                'records' => array(array(
                    'id' => $record_id,
                    'fields' => array(
                        'Status' => $status,
                        'Admin Notes' => trim($current_notes . "\n" . cleg_admin_audit_line($actor_name, $audit_label, $old_status, $status, $reason)),
                    ),
                )),
                'typecast' => true,
            ),
        ));

        cleg_admin_portal_audit('HR Request ' . $status, CLEG_AIRTABLE_HR_REQUESTS_TABLE, $record_id, $employee, $username, $old_status, $status, $reason);

        wp_safe_redirect(remove_query_arg(array('_wp_http_referer')));
        exit;
    }
}

add_action('init', 'cleg_admin_handle_hr_request_action');
add_shortcode('cleg_admin_solicitudes', 'cleg_admin_solicitudes_shortcode');

