if (!function_exists('cleg_tenant_admin_user_allowed')) {
    function cleg_tenant_admin_user_allowed(): bool {
        if (!is_user_logged_in()) {
            return false;
        }

        return current_user_can('manage_options')
            || current_user_can('edit_others_pages')
            || current_user_can('cleg_manage_employees')
            || current_user_can('cleg_manage_rrhh')
            || current_user_can('cleg_manage_roles')
            || current_user_can('cleg_manage_tenant');
    }
}

if (!function_exists('cleg_tenant_admin_is_superadmin')) {
    function cleg_tenant_admin_is_superadmin(): bool {
        return current_user_can('manage_options')
            || current_user_can('cleg_technical_full_access')
            || current_user_can('cleg_configure_modules')
            || current_user_can('cleg_manage_roles');
    }
}

if (!function_exists('cleg_tenant_admin_current_tenant')) {
    function cleg_tenant_admin_current_tenant(): array {
        $user_id = get_current_user_id();
        $tenant_id = $user_id > 0 ? (string) get_user_meta($user_id, 'cleg_tenant_id', true) : '';
        $tenant_slug = $user_id > 0 ? (string) get_user_meta($user_id, 'cleg_tenant_slug', true) : '';
        $tenant_name = $user_id > 0 ? (string) get_user_meta($user_id, 'cleg_tenant_name', true) : '';

        if ($tenant_id === '') {
            $tenant_id = 'cleg';
        }

        if ($tenant_slug === '') {
            $tenant_slug = sanitize_title($tenant_id);
        }

        if ($tenant_name === '') {
            $tenant_name = $tenant_id === 'cleg' ? 'Vantrexor' : strtoupper($tenant_slug);
        }

        return array(
            'id' => sanitize_key($tenant_id),
            'slug' => sanitize_title($tenant_slug),
            'name' => sanitize_text_field($tenant_name),
        );
    }
}

