if (!function_exists('cleg_tenant_admin_module_enabled')) {
    function cleg_tenant_admin_module_enabled(string $module_key, array $tenant): bool {
        if (function_exists('cleg_saas_module_enabled')) {
            return (bool) cleg_saas_module_enabled($module_key, $tenant['id']);
        }

        $enabled = get_option('cleg_tenant_modules_' . $tenant['id'], array());
        if (is_array($enabled) && array_key_exists($module_key, $enabled)) {
            return (bool) $enabled[$module_key];
        }

        return in_array($module_key, array('access_identity', 'tenant_admin', 'hr_core', 'forms_requests', 'payroll', 'field_ops', 'procurement_quotes'), true);
    }
}

if (!function_exists('cleg_tenant_admin_assignable_roles')) {
    function cleg_tenant_admin_assignable_roles(): array {
        $roles = array(
            'Trabajador' => 'Trabajador',
            'Supervisor' => 'Supervisor',
            'RRHH' => 'Recursos Humanos',
            'Admin empresa' => 'Admin empresa',
            'Solo lectura' => 'Solo lectura',
        );

        if (function_exists('cleg_starter_assignable_roles')) {
            $starter_roles = cleg_starter_assignable_roles();
            if (is_array($starter_roles) && !empty($starter_roles)) {
                foreach ($starter_roles as $role_label) {
                    $role_label = sanitize_text_field((string) $role_label);
                    if ($role_label !== '') {
                        $roles[$role_label] = $role_label;
                    }
                }
            }
        }

        return $roles;
    }
}

if (!function_exists('cleg_tenant_admin_role_key_from_label')) {
    function cleg_tenant_admin_role_key_from_label(string $role_label): string {
        $role_label = sanitize_text_field($role_label);

        if (function_exists('cleg_starter_role_key_by_label')) {
            $role_key = cleg_starter_role_key_by_label($role_label);
            if (is_string($role_key) && $role_key !== '' && get_role($role_key)) {
                return $role_key;
            }
        }

        $fallback = array(
            'Trabajador' => 'subscriber',
            'Supervisor' => 'subscriber',
            'RRHH' => 'subscriber',
            'Recursos Humanos' => 'subscriber',
            'Admin empresa' => 'subscriber',
            'Solo lectura' => 'subscriber',
        );

        return isset($fallback[$role_label]) && get_role($fallback[$role_label]) ? $fallback[$role_label] : 'subscriber';
    }
}

if (!function_exists('cleg_tenant_admin_role_select')) {
    function cleg_tenant_admin_role_select(string $name, string $current = ''): string {
        $html = '<select name="' . esc_attr($name) . '" required>';

        foreach (cleg_tenant_admin_assignable_roles() as $role_value => $role_label) {
            $html .= '<option value="' . esc_attr($role_value) . '" ' . selected($current, $role_value, false) . '>' . esc_html($role_label) . '</option>';
        }

        return $html . '</select>';
    }
}

if (!function_exists('cleg_tenant_admin_employee_role_tracks_time')) {
    function cleg_tenant_admin_employee_role_tracks_time(string $role_label): bool {
        if (function_exists('cleg_admin_employee_role_tracks_time')) {
            return cleg_admin_employee_role_tracks_time($role_label);
        }

        return in_array($role_label, array('Trabajador', 'Supervisor'), true);
    }
}

if (!function_exists('cleg_tenant_admin_employee_tax_type_for_role')) {
    function cleg_tenant_admin_employee_tax_type_for_role(string $role_label): string {
        return cleg_tenant_admin_employee_role_tracks_time($role_label) ? 'Employee - Full Payroll' : 'Admin / No Payroll';
    }
}

if (!function_exists('cleg_tenant_admin_formula_text')) {
    function cleg_tenant_admin_formula_text($value): string {
        if (function_exists('cleg_admin_formula_text')) {
            return cleg_admin_formula_text($value);
        }

        return str_replace("'", "\\'", (string) $value);
    }
}

if (!function_exists('cleg_tenant_admin_employee_record_fields')) {
    function cleg_tenant_admin_employee_record_fields($record): array {
        return (!empty($record['fields']) && is_array($record['fields'])) ? $record['fields'] : array();
    }
}

if (!function_exists('cleg_tenant_admin_employee_record_conflicts_user')) {
    function cleg_tenant_admin_employee_record_conflicts_user($record, WP_User $user): bool {
        $fields = cleg_tenant_admin_employee_record_fields($record);
        $record_wp_id = !empty($fields['WordPress User ID']) ? absint($fields['WordPress User ID']) : 0;
        $record_username = !empty($fields['Portal Username']) ? sanitize_user((string) $fields['Portal Username'], true) : '';

        if ($record_wp_id > 0 && $record_wp_id !== (int) $user->ID) {
            return true;
        }

        if ($record_username !== '' && $record_username !== sanitize_user($user->user_login, true)) {
            return true;
        }

        return false;
    }
}

if (!function_exists('cleg_tenant_admin_employee_record_by_formula')) {
    function cleg_tenant_admin_employee_record_by_formula(string $formula) {
        if (!defined('CLEG_AIRTABLE_EMPLOYEES_TABLE') || !function_exists('cleg_admin_records') || $formula === '') {
            return array();
        }

        $records = cleg_admin_records(CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'pageSize' => 1,
            'filterByFormula' => $formula,
        ));

        if (is_wp_error($records) || empty($records[0])) {
            return array();
        }

        return $records[0];
    }
}

if (!function_exists('cleg_tenant_admin_employee_record_for_user')) {
    function cleg_tenant_admin_employee_record_for_user(WP_User $user) {
        if (!defined('CLEG_AIRTABLE_EMPLOYEES_TABLE') || !function_exists('cleg_admin_records')) {
            return array();
        }

        $record = cleg_tenant_admin_employee_record_by_formula('{WordPress User ID}=' . (int) $user->ID);
        if (!empty($record)) {
            return $record;
        }

        if ($user->user_login !== '') {
            $record = cleg_tenant_admin_employee_record_by_formula("{Portal Username}='" . cleg_tenant_admin_formula_text(sanitize_user($user->user_login, true)) . "'");
            if (!empty($record) && !cleg_tenant_admin_employee_record_conflicts_user($record, $user)) {
                return $record;
            }
        }

        if ($user->user_email !== '') {
            $record = cleg_tenant_admin_employee_record_by_formula("LOWER({Email})=LOWER('" . cleg_tenant_admin_formula_text(sanitize_email($user->user_email)) . "')");
            if (!empty($record) && !cleg_tenant_admin_employee_record_conflicts_user($record, $user)) {
                return $record;
            }
        }

        return array();
    }
}

if (!function_exists('cleg_tenant_admin_name_token')) {
    function cleg_tenant_admin_name_token(string $value): string {
        $value = remove_accents($value);
        $value = strtolower($value);
        $value = preg_replace('/[^a-z0-9]+/', '', $value);
        return is_string($value) ? $value : '';
    }
}

if (!function_exists('cleg_tenant_admin_username_candidates')) {
    function cleg_tenant_admin_username_candidates(string $first_name, string $last_name, string $fallback_email = ''): array {
        $first_token = cleg_tenant_admin_name_token($first_name);
        $first_initial = $first_token !== '' ? substr($first_token, 0, 1) : '';
        $last_parts = preg_split('/\s+/', trim($last_name));
        $candidates = array();

        foreach ((array) $last_parts as $last_part) {
            $last_token = cleg_tenant_admin_name_token((string) $last_part);
            if ($first_initial !== '' && $last_token !== '') {
                $candidates[] = $first_initial . $last_token;
            }
        }

        if (empty($candidates) && $first_token !== '') {
            $candidates[] = $first_token;
        }

        if (empty($candidates) && $fallback_email !== '') {
            $email_parts = explode('@', $fallback_email);
            $email_base = cleg_tenant_admin_name_token((string) $email_parts[0]);
            if ($email_base !== '') {
                $candidates[] = $email_base;
            }
        }

        $candidates[] = 'user';
        return array_values(array_unique(array_filter($candidates)));
    }
}

if (!function_exists('cleg_tenant_admin_available_username')) {
    function cleg_tenant_admin_available_username(string $first_name, string $last_name, string $email = ''): string {
        foreach (cleg_tenant_admin_username_candidates($first_name, $last_name, $email) as $candidate) {
            $candidate = sanitize_user($candidate, true);
            if ($candidate !== '' && !username_exists($candidate)) {
                return $candidate;
            }
        }

        $base = sanitize_user(cleg_tenant_admin_username_candidates($first_name, $last_name, $email)[0] ?? 'user', true);
        $base = $base !== '' ? $base : 'user';
        $suffix = 2;
        do {
            $candidate = $base . $suffix;
            $suffix++;
        } while (username_exists($candidate));

        return $candidate;
    }
}

if (!function_exists('cleg_tenant_admin_sync_employee_record')) {
    function cleg_tenant_admin_sync_employee_record($user_id, string $role_label, string $phone = '', string $department = ''): void {
        $user = get_userdata(absint($user_id));
        if (!$user instanceof WP_User || !defined('CLEG_AIRTABLE_EMPLOYEES_TABLE') || !function_exists('cleg_admin_request')) {
            return;
        }

        $role_label = sanitize_text_field($role_label !== '' ? $role_label : 'Trabajador');
        $first = sanitize_text_field((string) get_user_meta($user->ID, 'first_name', true));
        $last = sanitize_text_field((string) get_user_meta($user->ID, 'last_name', true));
        $display_name = trim($first . ' ' . $last);
        if ($display_name === '') {
            $display_name = sanitize_text_field($user->display_name ?: $user->user_login);
        }

        $existing = cleg_tenant_admin_employee_record_for_user($user);
        $fields = array(
            'Employee Name' => $display_name,
            'Portal Username' => sanitize_user($user->user_login, true),
            'WordPress User ID' => (int) $user->ID,
            'Email' => sanitize_email($user->user_email),
            'Role' => $role_label,
            'Status' => get_user_meta($user->ID, 'cleg_tenant_status', true) === 'inactive' ? 'Inactive' : 'Active',
            'Time Tracking Required' => cleg_tenant_admin_employee_role_tracks_time($role_label),
        );

        if ($phone !== '') {
            $fields['Phone'] = sanitize_text_field($phone);
        }
        if ($department !== '') {
            $fields['Department'] = sanitize_text_field($department);
        }

        if (empty($existing)) {
            $fields['Payroll Tax Type'] = cleg_tenant_admin_employee_tax_type_for_role($role_label);
            $fields['Payroll Period'] = 'Per Hour';
            $fields['Payroll Amount'] = 0;
            $fields['Payroll Form Type'] = $fields['Payroll Tax Type'] === 'Admin / No Payroll' ? 'No aplica / revisar' : 'W-2PR / 499R-2';
            cleg_admin_request('POST', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
                'body' => array(
                    'records' => array(array('fields' => $fields)),
                    'typecast' => true,
                ),
            ));
            return;
        }

        cleg_admin_request('PATCH', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'body' => array(
                'records' => array(array('id' => sanitize_text_field($existing['id']), 'fields' => $fields)),
                'typecast' => true,
            ),
        ));
    }
}

if (!function_exists('cleg_tenant_admin_url')) {
    function cleg_tenant_admin_url(string $path, array $args = array()): string {
        if (function_exists('cleg_admin_context_url')) {
            return cleg_admin_context_url($path, $args);
        }

        $url = home_url($path);
        return !empty($args) ? add_query_arg($args, $url) : $url;
    }
}

if (!function_exists('cleg_tenant_admin_users')) {
    function cleg_tenant_admin_users(array $tenant): array {
        $users = get_users(array(
            'meta_key' => 'cleg_tenant_id',
            'meta_value' => $tenant['id'],
            'orderby' => 'display_name',
            'order' => 'ASC',
            'number' => 250,
        ));

        if (empty($users) && $tenant['id'] === 'cleg') {
            $users = get_users(array(
                'role__in' => array('administrator', 'editor', 'subscriber'),
                'orderby' => 'display_name',
                'order' => 'ASC',
                'number' => 250,
            ));
        }

        return is_array($users) ? $users : array();
    }
}

