if (!function_exists('cleg_tenant_admin_count_active_employees')) {
    function cleg_tenant_admin_count_active_employees(array $records): int {
        $count = 0;

        foreach ($records as $record) {
            $status = function_exists('cleg_admin_field') ? cleg_admin_field($record, 'Status') : '';
            if ($status === '' || strtolower($status) === 'active') {
                $count++;
            }
        }

        return $count;
    }
}

