if (!function_exists('cleg_tenant_admin_generate_pin')) {
    function cleg_tenant_admin_generate_pin(): string {
        return str_pad((string) wp_rand(0, 9999), 4, '0', STR_PAD_LEFT);
    }
}

if (!function_exists('cleg_tenant_admin_is_worker')) {
    function cleg_tenant_admin_is_worker(WP_User $user): bool {
        $tenant_role = strtolower(trim((string) get_user_meta($user->ID, 'cleg_tenant_role', true)));
        $roles = array_map('strtolower', (array) $user->roles);

        return $tenant_role === 'trabajador'
            || (bool) array_intersect(array('trabajador', 'worker', 'cleg_worker'), $roles);
    }
}

if (!function_exists('cleg_tenant_admin_store_pin_notice')) {
    function cleg_tenant_admin_store_pin_notice(WP_User $user, string $pin, string $mode = 'created'): void {
        $admin_id = get_current_user_id();
        if ($admin_id <= 0) {
            return;
        }

        set_transient('cleg_tenant_pin_notice_' . $admin_id, array(
            'user_id' => (int) $user->ID,
            'name' => sanitize_text_field($user->display_name ?: $user->user_login),
            'username' => sanitize_user($user->user_login, true),
            'pin' => preg_replace('/[^0-9]/', '', $pin),
            'mode' => $mode === 'reset' ? 'reset' : 'created',
        ), 10 * MINUTE_IN_SECONDS);
    }
}

if (!function_exists('cleg_tenant_admin_pin_notice')) {
    function cleg_tenant_admin_pin_notice(): string {
        $admin_id = get_current_user_id();
        if ($admin_id <= 0) {
            return '';
        }

        $key = 'cleg_tenant_pin_notice_' . $admin_id;
        $data = get_transient($key);
        if (!is_array($data) || empty($data['pin']) || empty($data['username'])) {
            return '';
        }

        delete_transient($key);
        $pin = preg_replace('/[^0-9]/', '', (string) $data['pin']);
        $username = sanitize_user((string) $data['username'], true);
        $title = !empty($data['mode']) && $data['mode'] === 'reset' ? 'PIN regenerado' : 'Trabajador creado';
        $copy_text = 'Usuario: ' . $username . ' | PIN: ' . $pin . ' | Acceso: ' . home_url('/acceso/');

        return '<section class="cleg-tenant-pin-notice" data-cleg-pin-notice>'
            . '<div><span>' . esc_html($title) . '</span><strong>' . esc_html((string) ($data['name'] ?? $username)) . '</strong><small>Copialo ahora. Por seguridad, el PIN no se podra consultar despues.</small></div>'
            . '<code>Usuario: ' . esc_html($username) . ' &nbsp; PIN: <b>' . esc_html($pin) . '</b></code>'
            . '<button type="button" data-cleg-copy-pin data-copy-text="' . esc_attr($copy_text) . '">Copiar usuario y PIN</button>'
            . '<script>(function(){var b=document.querySelector("[data-cleg-pin-notice] [data-cleg-copy-pin]");if(!b)return;b.addEventListener("click",function(){var t=b.getAttribute("data-copy-text")||"";var done=function(){b.textContent="Copiado";window.setTimeout(function(){b.textContent="Copiar usuario y PIN";},1800);};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(t).then(done);return;}var a=document.createElement("textarea");a.value=t;a.setAttribute("readonly","");a.style.position="fixed";a.style.opacity="0";document.body.appendChild(a);a.select();document.execCommand("copy");a.remove();done();});})();</script>'
            . '</section>';
    }
}

if (!function_exists('cleg_tenant_admin_handle_invite')) {
    function cleg_tenant_admin_handle_invite(): void {
        if (empty($_POST['cleg_tenant_admin_action'])) {
            return;
        }

        if (!cleg_tenant_admin_user_allowed()) {
            return;
        }

        if (!isset($_POST['cleg_tenant_admin_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_tenant_admin_nonce'])), 'cleg_tenant_admin_action')) {
            cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'security'));
        }

        $action = sanitize_text_field(wp_unslash($_POST['cleg_tenant_admin_action']));
        if (!in_array($action, array('invite_user', 'update_access_user', 'update_modules', 'reset_worker_pin'), true)) {
            return;
        }

        $tenant = cleg_tenant_admin_current_tenant();

        if ($action === 'update_modules') {
            if (!cleg_tenant_admin_is_superadmin()) {
                cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'security', 'cleg_tenant_tab' => 'modules'));
            }

            $existing_flags = get_option('cleg_saas_modules_' . $tenant['id'], array());
            $flags = is_array($existing_flags) ? $existing_flags : array();
            foreach (cleg_tenant_admin_module_catalog() as $module_key => $module) {
                if (empty($module['disableable'])) {
                    continue;
                }

                if (empty($module['visible'])) {
                    continue;
                }

                $field = 'module_' . sanitize_key($module_key);
                $flags[sanitize_key($module_key)] = !empty($_POST[$field]);
            }

            update_option('cleg_saas_modules_' . $tenant['id'], $flags, false);
            cleg_tenant_admin_write_audit($tenant, 'Modulos actualizados', 'Se guardo la configuracion de modulos de la empresa.', 'ok');
            cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'updated', 'cleg_tenant_tab' => 'modules'));
        }

        if ($action === 'update_access_user') {
            $user_id = isset($_POST['user_id']) ? absint($_POST['user_id']) : 0;
            $user = $user_id > 0 ? get_userdata($user_id) : false;
            $email = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
            $role_label = isset($_POST['tenant_role']) ? sanitize_text_field(wp_unslash($_POST['tenant_role'])) : 'Trabajador';
            $tenant_status = isset($_POST['tenant_status']) ? sanitize_key(wp_unslash($_POST['tenant_status'])) : 'active';
            $update_wp_role = !empty($_POST['update_wp_role']);

            if (!$user || $email === '' || !is_email($email)) {
                cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'missing', 'cleg_tenant_tab' => 'users'));
            }

            $email_owner = email_exists($email);
            if ($email_owner && (int) $email_owner !== $user_id) {
                cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'email_in_use', 'cleg_tenant_tab' => 'users'));
            }

            $update_args = array(
                'ID' => $user_id,
                'user_email' => $email,
            );

            if ($update_wp_role) {
                $update_args['role'] = cleg_tenant_admin_role_key_from_label($role_label);
            }

            $updated = wp_update_user($update_args);
            if (is_wp_error($updated)) {
                cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'update_error', 'cleg_tenant_tab' => 'users'));
            }

            update_user_meta($user_id, 'cleg_tenant_id', $tenant['id']);
            update_user_meta($user_id, 'cleg_tenant_slug', $tenant['slug']);
            update_user_meta($user_id, 'cleg_tenant_name', $tenant['name']);
            update_user_meta($user_id, 'cleg_tenant_role', $role_label);
            update_user_meta($user_id, 'cleg_tenant_status', $tenant_status === 'inactive' ? 'inactive' : 'active');
            cleg_tenant_admin_sync_employee_record($user_id, $role_label);
            cleg_tenant_admin_write_audit($tenant, 'Usuario actualizado', $user->user_login . ' - rol ' . $role_label, 'ok');

            cleg_tenant_admin_redirect_with_notice(array(
                'cleg_tenant_notice' => 'updated',
                'cleg_tenant_tab' => 'users',
            ));
        }

        if ($action === 'reset_worker_pin') {
            $user_id = isset($_POST['user_id']) ? absint($_POST['user_id']) : 0;
            $user = $user_id > 0 ? get_userdata($user_id) : false;
            $user_tenant = $user ? (string) get_user_meta($user_id, 'cleg_tenant_id', true) : '';

            if (!$user instanceof WP_User
                || !cleg_tenant_admin_is_worker($user)
                || ($user_tenant !== '' && $user_tenant !== $tenant['id'])) {
                cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'pin_not_allowed', 'cleg_tenant_tab' => 'users'));
            }

            $pin = cleg_tenant_admin_generate_pin();
            wp_set_password($pin, $user_id);
            cleg_tenant_admin_store_pin_notice($user, $pin, 'reset');
            cleg_tenant_admin_write_audit($tenant, 'PIN regenerado', $user->user_login . ' - trabajador', 'ok');

            cleg_tenant_admin_redirect_with_notice(array(
                'cleg_tenant_notice' => 'pin_ready',
                'cleg_tenant_tab' => 'users',
            ));
        }

        $first_name = isset($_POST['first_name']) ? sanitize_text_field(wp_unslash($_POST['first_name'])) : '';
        $last_name = isset($_POST['last_name']) ? sanitize_text_field(wp_unslash($_POST['last_name'])) : '';
        $email = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
        $phone = isset($_POST['phone']) ? sanitize_text_field(wp_unslash($_POST['phone'])) : '';
        $department = isset($_POST['department']) ? sanitize_text_field(wp_unslash($_POST['department'])) : '';
        $role_label = isset($_POST['tenant_role']) ? sanitize_text_field(wp_unslash($_POST['tenant_role'])) : 'Trabajador';
        $send_invite = !empty($_POST['send_invite']);
        $update_existing_role = !empty($_POST['update_existing_role']);

        if ($first_name === '' || $last_name === '' || ($email !== '' && !is_email($email))) {
            cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'missing'));
        }

        $display_name = trim($first_name . ' ' . $last_name);
        $candidate = cleg_tenant_admin_available_username($first_name, $last_name, $email);

        $role_key = cleg_tenant_admin_role_key_from_label($role_label);
        $existing_user_id = $email !== '' ? email_exists($email) : false;
        $created = false;
        $initial_pin = $role_label === 'Trabajador' ? cleg_tenant_admin_generate_pin() : '';

        if ($existing_user_id) {
            $user_id = (int) $existing_user_id;
            $update_args = array(
                'ID' => $user_id,
                'display_name' => $display_name,
                'first_name' => $first_name,
                'last_name' => $last_name,
            );

            if ($update_existing_role) {
                $update_args['role'] = $role_key;
            }

            wp_update_user($update_args);
        } else {
            $user_id = wp_insert_user(array(
                'user_login' => $candidate,
                'user_pass' => $initial_pin !== '' ? $initial_pin : wp_generate_password(24, true, true),
                'user_email' => $email,
                'display_name' => $display_name,
                'first_name' => $first_name,
                'last_name' => $last_name,
                'nickname' => $display_name,
                'role' => $role_key,
            ));

            if (is_wp_error($user_id)) {
                cleg_tenant_admin_redirect_with_notice(array('cleg_tenant_notice' => 'create_error'));
            }

            $created = true;
        }

        $user_id = (int) $user_id;
        update_user_meta($user_id, 'cleg_tenant_id', $tenant['id']);
        update_user_meta($user_id, 'cleg_tenant_slug', $tenant['slug']);
        update_user_meta($user_id, 'cleg_tenant_name', $tenant['name']);
        update_user_meta($user_id, 'cleg_tenant_role', $role_label);
        update_user_meta($user_id, 'cleg_tenant_status', 'active');
        update_user_meta($user_id, 'cleg_invited_by', get_current_user_id());
        update_user_meta($user_id, 'cleg_invited_at', current_time('mysql'));

        if ($phone !== '') {
            update_user_meta($user_id, 'cleg_worker_phone', $phone);
        }

        if ($department !== '') {
            update_user_meta($user_id, 'cleg_department', $department);
        }

        cleg_tenant_admin_sync_employee_record($user_id, $role_label, $phone, $department);

        if ($created && $initial_pin !== '') {
            $created_user = get_userdata($user_id);
            if ($created_user instanceof WP_User) {
                cleg_tenant_admin_store_pin_notice($created_user, $initial_pin, 'created');
            }
        }

        if ($send_invite && $email !== '' && is_email($email)) {
            $user = get_user_by('id', $user_id);
            if ($user) {
                $key = get_password_reset_key($user);
                if (!is_wp_error($key)) {
                    $reset_url = function_exists('cleg01_password_reset_url')
                        ? cleg01_password_reset_url($user->user_login, $key)
                        : add_query_arg(array(
                            'cleg_reset' => 'set',
                            'key' => rawurlencode($key),
                            'login' => rawurlencode($user->user_login),
                        ), home_url('/acceso/'));
                    $subject = $tenant['name'] . ' - acceso al portal';
                    $message = "Hola " . $display_name . ",\n\nTu acceso al portal ya esta listo.\n\nDefine tu contrasena aqui:\n" . $reset_url . "\n\nEntrada del portal:\n" . home_url('/acceso/') . "\n";
                    wp_mail($email, $subject, $message);
                }
            }
        }

        cleg_tenant_admin_write_audit($tenant, $created ? 'Usuario creado' : 'Usuario asociado', $email . ' - rol ' . $role_label, 'ok');

        cleg_tenant_admin_redirect_with_notice(array(
            'cleg_tenant_notice' => $created ? 'created' : 'updated',
            'cleg_tenant_tab' => 'users',
        ));
    }
}

add_action('init', 'cleg_tenant_admin_handle_invite');

if (!function_exists('cleg_tenant_admin_is_virtual_route')) {
    function cleg_tenant_admin_is_virtual_route(): bool {
        if (is_admin() || wp_doing_ajax()) {
            return false;
        }

        if (function_exists('cleg_starter_current_path')) {
            return cleg_starter_current_path() === 'administracion';
        }

        $path = isset($_SERVER['REQUEST_URI']) ? wp_parse_url(esc_url_raw(wp_unslash($_SERVER['REQUEST_URI'])), PHP_URL_PATH) : '/';
        return trim((string) $path, '/') === 'administracion';
    }
}

