if (!function_exists('cleg_tenant_admin_notice')) {
    function cleg_tenant_admin_notice(): string {
        $notice = isset($_GET['cleg_tenant_notice']) ? sanitize_text_field(wp_unslash($_GET['cleg_tenant_notice'])) : '';
        $pin_notice = function_exists('cleg_tenant_admin_pin_notice') ? cleg_tenant_admin_pin_notice() : '';
        if ($notice === '') {
            return $pin_notice;
        }

        $messages = array(
            'created' => array('is-success', 'Usuario creado', 'Se guardo la identidad, empresa, rol y datos base.'),
            'updated' => array('is-success', 'Usuario actualizado', 'La identidad, email, rol de empresa o estado quedaron guardados.'),
            'missing' => array('is-error', 'Faltan datos', 'Nombre, apellido y email valido son obligatorios.'),
            'security' => array('is-error', 'Solicitud no valida', 'Actualiza la pagina e intenta de nuevo.'),
            'create_error' => array('is-error', 'No se pudo crear', 'WordPress rechazo la creacion del usuario.'),
            'update_error' => array('is-error', 'No se pudo actualizar', 'WordPress rechazo el cambio del usuario.'),
            'email_in_use' => array('is-error', 'Email en uso', 'Ese correo ya pertenece a otro usuario.'),
            'pin_ready' => array('is-success', 'PIN actualizado', 'La clave anterior dejo de funcionar. Copia el nuevo PIN antes de salir.'),
            'pin_not_allowed' => array('is-error', 'No se pudo regenerar', 'Solo se puede regenerar el PIN de trabajadores de esta empresa.'),
        );

        if (!isset($messages[$notice])) {
            return $pin_notice;
        }

        $item = $messages[$notice];
        return '<div class="cleg-admin-notice ' . esc_attr($item[0]) . '"><strong>' . esc_html($item[1]) . '</strong><span>' . esc_html($item[2]) . '</span></div>' . $pin_notice;
    }
}

if (!function_exists('cleg_tenant_admin_tab')) {
    function cleg_tenant_admin_tab(): string {
        $tab = isset($_GET['cleg_tenant_tab']) ? sanitize_key(wp_unslash($_GET['cleg_tenant_tab'])) : 'overview';
        return array_key_exists($tab, cleg_tenant_admin_available_tabs()) ? $tab : 'overview';
    }
}

if (!function_exists('cleg_tenant_admin_available_tabs')) {
    function cleg_tenant_admin_available_tabs(): array {
        $tabs = array(
            'overview' => 'Resumen',
            'users' => 'Usuarios',
            'roles' => 'Roles',
            'modules' => 'Modulos',
        );

        if (cleg_tenant_admin_is_superadmin()) {
            $tabs['invites'] = 'Invitaciones';
            $tabs['audit'] = 'Auditoria';
        }

        return $tabs;
    }
}

if (!function_exists('cleg_tenant_admin_tabs')) {
    function cleg_tenant_admin_tabs(string $active): string {
        $tabs = cleg_tenant_admin_available_tabs();

        $html = '<nav class="cleg-tenant-tabs" aria-label="Administracion de empresa">';
        foreach ($tabs as $key => $label) {
            $html .= '<a class="' . esc_attr($active === $key ? 'is-active' : '') . '" href="' . esc_url(cleg_tenant_admin_tab_url($key)) . '">' . esc_html($label) . '</a>';
        }

        return $html . '</nav>';
    }
}

if (!function_exists('cleg_tenant_admin_metric')) {
    function cleg_tenant_admin_metric(string $label, string $value, string $hint = ''): string {
        return '<div class="cleg-metric cleg-tenant-metric"><strong>' . esc_html($value) . '</strong><span>' . esc_html($label) . '</span>' . ($hint !== '' ? '<small>' . esc_html($hint) . '</small>' : '') . '</div>';
    }
}

if (!function_exists('cleg_tenant_admin_help')) {
    function cleg_tenant_admin_help(string $text): string {
        return '<span class="cleg-admin-help" tabindex="0" role="button" aria-label="' . esc_attr($text) . '" title="' . esc_attr($text) . '">?</span>';
    }
}

if (!function_exists('cleg_tenant_admin_overview')) {
    function cleg_tenant_admin_overview(array $tenant, array $users, array $employees): string {
        $active_modules = 0;
        foreach (cleg_tenant_admin_module_catalog() as $module_key => $module) {
            if (!empty($module['visible']) && cleg_tenant_admin_module_enabled($module_key, $tenant)) {
                $active_modules++;
            }
        }

        $html = '<section class="cleg-tenant-hero">'
            . '<div><span>Empresa activa</span><h2>' . esc_html($tenant['name']) . '</h2></div>'
            . '<a class="cleg-tenant-primary" href="' . esc_url(cleg_tenant_admin_tab_url('users')) . '">Invitar usuario</a>'
            . '</section>';

        $html .= '<div class="cleg-metrics-grid cleg-tenant-metrics">'
            . cleg_tenant_admin_metric('Usuarios de acceso', (string) count($users), 'login y permisos')
            . cleg_tenant_admin_metric('Trabajadores activos', (string) cleg_tenant_admin_count_active_employees($employees), 'expediente operativo')
            . cleg_tenant_admin_metric('Modulos activos', (string) $active_modules, 'visibilidad por empresa')
            . cleg_tenant_admin_metric('Ruta admin', '/administracion/', 'modulo independiente')
            . '</div>';

        $html .= '<div class="cleg-admin-grid cleg-admin-grid-aside cleg-tenant-overview-grid">';
        $html .= '<section class="cleg-panel"><div class="cleg-panel-head"><div><h2>Acciones principales</h2></div>' . cleg_tenant_admin_help('Accesos rapidos para usuarios, roles y modulos de la empresa.') . '</div><div class="cleg-tenant-action-list">'
            . '<a href="' . esc_url(cleg_tenant_admin_tab_url('users')) . '"><b>Crear o actualizar usuario de acceso</b></a>'
            . '<a href="' . esc_url(cleg_tenant_admin_tab_url('roles')) . '"><b>Gestionar roles en un solo lugar</b></a>'
            . '<a href="' . esc_url(cleg_tenant_admin_tab_url('modules')) . '"><b>Revisar modulos de la empresa</b></a>'
            . '</div></section>';

        $pending = array(
            array('is-ok', 'Usuarios sincronizados con WP'),
            array('is-ok', 'Roles administrados desde Usuarios'),
            array('is-ok', 'Modulos visibles alineados'),
        );

        if (cleg_tenant_admin_is_superadmin()) {
            $pending[] = array('is-warn', 'Invitaciones con token dedicado pendiente');
            $pending[] = array('is-warn', 'Auditoria ampliable por tabla dedicada');
        }

        $html .= '<section class="cleg-panel"><div class="cleg-panel-head"><div><h2>Estado de la gestion</h2></div>' . cleg_tenant_admin_help('Estado breve de la configuracion administrativa de la empresa.') . '</div><div class="cleg-tenant-checks">';
        foreach ($pending as $item) {
            $html .= '<span class="' . esc_attr($item[0]) . '">' . esc_html($item[1]) . '</span>';
        }
        $html .= '</div></section>';

        return $html . '</div>';
    }
}

if (!function_exists('cleg_tenant_admin_invite_form')) {
    function cleg_tenant_admin_invite_form(): string {
        return '<details class="cleg-panel cleg-admin-create-drawer cleg-tenant-invite" open><summary><span>Crear / invitar usuario de acceso</span><b>Formulario</b></summary>'
            . '<form class="cleg-admin-form cleg-tenant-user-form" method="post">'
            . wp_nonce_field('cleg_tenant_admin_action', 'cleg_tenant_admin_nonce', true, false)
            . '<input type="hidden" name="cleg_tenant_admin_action" value="invite_user">'
            . '<label>Nombre<input name="first_name" required autocomplete="given-name"></label>'
            . '<label>Apellido<input name="last_name" required autocomplete="family-name"></label>'
            . '<label>Email opcional<input name="email" type="email" autocomplete="email" placeholder="No es obligatorio"></label>'
            . '<label>Telefono<input name="phone" autocomplete="tel"></label>'
            . '<label>Departamento / proyecto<input name="department"></label>'
            . '<label>Rol de acceso' . cleg_tenant_admin_role_select('tenant_role', 'Trabajador') . '</label>'
            . '<label class="checkline wide"><input type="checkbox" name="update_existing_role" value="1"> Si el email ya existe, actualizar tambien su rol de acceso</label>'
            . '<label class="checkline wide"><input type="checkbox" name="send_invite" value="1"> Si tiene email, enviar tambien enlace para crear contrasena</label>'
            . '<button type="submit">Guardar usuario de acceso</button>'
            . '</form></details>';
    }
}

if (!function_exists('cleg_tenant_admin_users_panel')) {
    function cleg_tenant_admin_users_panel(array $tenant, array $users): string {
        $html = cleg_tenant_admin_invite_form();
        $html .= '<section class="cleg-panel cleg-tenant-users-panel"><div class="cleg-panel-head"><div><h2>Usuarios de acceso</h2></div>' . cleg_tenant_admin_help('Usuarios asociados a esta empresa. Aqui se ajustan rol, estado y sincronizacion tecnica.') . '</div>';

        if (empty($users)) {
            return $html . '<div class="cleg-admin-empty"><h2>Sin usuarios asociados</h2><p>Invita el primer usuario para esta empresa.</p></div></section>';
        }

        $html .= '<div class="cleg-tenant-user-list">';
        foreach ($users as $user) {
            if (!$user instanceof WP_User) {
                continue;
            }

            $tenant_role = (string) get_user_meta($user->ID, 'cleg_tenant_role', true);
            $tenant_status = (string) get_user_meta($user->ID, 'cleg_tenant_status', true);
            $roles = implode(', ', array_map('sanitize_text_field', (array) $user->roles));
            $profile_url = cleg_tenant_admin_url('/admin-empleados/', array('cleg_employee' => $user->user_login));

            $is_worker = function_exists('cleg_tenant_admin_is_worker') && cleg_tenant_admin_is_worker($user);

            $html .= '<div class="cleg-tenant-user-entry"><form class="cleg-tenant-user-row" method="post">'
                . wp_nonce_field('cleg_tenant_admin_action', 'cleg_tenant_admin_nonce', true, false)
                . '<input type="hidden" name="cleg_tenant_admin_action" value="update_access_user">'
                . '<input type="hidden" name="user_id" value="' . esc_attr((string) $user->ID) . '">'
                . '<div class="cleg-tenant-user-id"><strong>' . esc_html($user->display_name ?: $user->user_login) . '</strong><small>' . esc_html($user->user_login) . ' - WP: ' . esc_html($roles ?: 'sin rol') . '</small></div>'
                . '<label>Email<input type="email" name="email" value="' . esc_attr($user->user_email) . '" required></label>'
                . '<label>Rol de empresa' . cleg_tenant_admin_role_select('tenant_role', $tenant_role ?: 'Trabajador') . '</label>'
                . '<label>Estado<select name="tenant_status"><option value="active" ' . selected($tenant_status ?: 'active', 'active', false) . '>Activo</option><option value="inactive" ' . selected($tenant_status, 'inactive', false) . '>Inactivo</option></select></label>'
                . '<label class="checkline"><input type="checkbox" name="update_wp_role" value="1"> Sincronizar rol tecnico WP</label>'
                . '<div class="cleg-tenant-user-actions"><button type="submit">Guardar</button><a class="cleg-row-action" href="' . esc_url($profile_url) . '">Expediente</a></div>'
                . '</form>';

            if ($is_worker) {
                $html .= '<form class="cleg-tenant-pin-actions" method="post" onsubmit="return window.confirm(\'Se invalidara el PIN actual de este trabajador. ¿Continuar?\');">'
                    . wp_nonce_field('cleg_tenant_admin_action', 'cleg_tenant_admin_nonce', true, false)
                    . '<input type="hidden" name="cleg_tenant_admin_action" value="reset_worker_pin">'
                    . '<input type="hidden" name="user_id" value="' . esc_attr((string) $user->ID) . '">'
                    . '<span>Acceso del trabajador</span><button type="submit">Regenerar PIN de 4 digitos</button>'
                    . '</form>';
            }

            $html .= '</div>';
        }

        return $html . '</div></section>';
    }
}

if (!function_exists('cleg_tenant_admin_roles_panel')) {
    function cleg_tenant_admin_roles_panel(): string {
        $html = '<section class="cleg-panel cleg-tenant-roles-panel"><div class="cleg-panel-head"><div><h2>Roles y permisos</h2></div>' . cleg_tenant_admin_help('Catalogo de roles de la empresa. Los cambios por usuario se guardan desde Usuarios.') . '</div>';

        if (function_exists('cleg_starter_roles_manager_shortcode') && cleg_tenant_admin_is_superadmin()) {
            return $html . '<div class="cleg-tenant-role-manager">' . cleg_starter_roles_manager_shortcode() . '</div></section>';
        }

        $html .= '<div class="cleg-tenant-role-grid">';

        $rows = array(
            'Admin empresa' => array('rol CLEG especifico', 'Gestiona usuarios, roles permitidos y configuracion de la empresa.', 'No ve otras empresas.'),
            'Recursos Humanos' => array('admin_rrhh', 'Gestiona trabajadores, expedientes, documentos, nomina permitida y solicitudes.', 'Acceso por modulo activo.'),
            'Supervisor' => array('supervisor', 'Revisa operacion, equipos, horas y solicitudes asignadas.', 'No administra configuracion global.'),
            'Trabajador' => array('subscriber', 'Usa panel, formularios, documentos y modulos permitidos.', 'Solo su informacion o la permitida.'),
            'Solo lectura' => array('subscriber / personalizado', 'Auditoria o consulta controlada.', 'Sin acciones destructivas.'),
        );

        foreach ($rows as $role => $data) {
            $html .= '<article class="cleg-tenant-role-card"><span>' . esc_html($data[0]) . '</span><h3>' . esc_html($role) . '</h3><p>' . esc_html($data[1]) . '</p><small>' . esc_html($data[2]) . '</small></article>';
        }

        return $html . '</div></section>';
    }
}

if (!function_exists('cleg_tenant_admin_modules_panel')) {
    function cleg_tenant_admin_modules_panel(array $tenant): string {
        $is_superadmin = cleg_tenant_admin_is_superadmin();
        $html = '<section class="cleg-panel cleg-tenant-modules-panel"><div class="cleg-panel-head"><div><h2>' . esc_html($is_superadmin ? 'Modulos de la empresa' : 'Modulos contratados') . '</h2></div>' . cleg_tenant_admin_help($is_superadmin ? 'Activa o apaga modulos para esta empresa.' : 'Modulos disponibles para esta empresa.') . '</div>';
        if ($is_superadmin) {
            $html .= '<form class="cleg-tenant-module-form" method="post">'
                . wp_nonce_field('cleg_tenant_admin_action', 'cleg_tenant_admin_nonce', true, false)
                . '<input type="hidden" name="cleg_tenant_admin_action" value="update_modules">';
        }
        $html .= '<div class="cleg-tenant-module-grid">';

        foreach (cleg_tenant_admin_module_catalog() as $module_key => $module) {
            if (empty($module['visible'])) {
                continue;
            }

            $enabled = cleg_tenant_admin_module_enabled($module_key, $tenant);
            $disableable = !empty($module['disableable']);
            $description = !empty($module['description']) ? (string) $module['description'] : 'Modulo operativo de la empresa.';
            $icon = function_exists('cleg_visual_module_icon') ? cleg_visual_module_icon((string) $module_key, 'cleg-tenant-module-icon') : '';
            $html .= '<article class="cleg-tenant-module ' . esc_attr($enabled ? 'is-on' : 'is-off') . '">'
                . '<div>' . $icon . '<span>' . esc_html($module['owner']) . '</span><h3>' . esc_html($module['label']) . '</h3><p>' . esc_html($description) . '</p></div>'
                . '<strong>' . esc_html($enabled ? 'Activo' : 'Inactivo') . '</strong>';
            if ($is_superadmin && $disableable) {
                $html .= '<label class="cleg-module-switch ' . esc_attr($enabled ? 'is-on' : 'is-off') . '"><input type="checkbox" name="module_' . esc_attr($module_key) . '" value="1" ' . checked($enabled, true, false) . '><span class="cleg-switch-track"><i></i></span><em>' . esc_html($enabled ? 'Activo' : 'Inactivo') . '</em></label>';
            } elseif (!$disableable) {
                $html .= '<em>Siempre activo</em>';
            } elseif ($enabled) {
                $html .= '<a href="' . esc_url(home_url($module['route'])) . '">Abrir modulo</a>';
            } else {
                $html .= '<em>Oculto para esta empresa</em>';
            }
            $html .= '</article>';
        }

        $html .= '</div>';
        if ($is_superadmin) {
            $html .= '<div class="cleg-tenant-module-actions"><button type="submit">Guardar modulos de la empresa</button></div></form>';
        }

        return $html . '</section>';
    }
}

if (!function_exists('cleg_tenant_admin_invites_panel')) {
    function cleg_tenant_admin_invites_panel(array $tenant, array $users): string {
        $html = '<section class="cleg-panel cleg-tenant-invites-panel"><div class="cleg-panel-head"><div><h2>Invitaciones</h2></div>' . cleg_tenant_admin_help('Ultimas invitaciones detectadas para esta empresa.') . '</div>';
        $html .= '<div class="cleg-table-wrap"><table><thead><tr><th>Usuario</th><th>Email</th><th>Invitado</th><th>Estado</th></tr></thead><tbody>';
        $rows = 0;
        foreach ($users as $user) {
            if (!$user instanceof WP_User) {
                continue;
            }
            $invited_at = (string) get_user_meta($user->ID, 'cleg_invited_at', true);
            if ($invited_at === '') {
                continue;
            }
            $rows++;
            $status = (string) get_user_meta($user->ID, 'cleg_tenant_status', true);
            $html .= '<tr><td><strong>' . esc_html($user->display_name ?: $user->user_login) . '</strong></td><td>' . esc_html($user->user_email) . '</td><td>' . esc_html($invited_at) . '</td><td><span class="cleg-pill is-ok">' . esc_html($status === 'inactive' ? 'Inactivo' : 'Activo') . '</span></td></tr>';
        }
        if ($rows === 0) {
            $html .= '<tr><td colspan="4">Todavia no hay invitaciones registradas para esta empresa.</td></tr>';
        }

        return $html . '</tbody></table></div></section>';
    }
}

if (!function_exists('cleg_tenant_admin_audit_panel')) {
    function cleg_tenant_admin_audit_panel(array $tenant): string {
        $html = '<section class="cleg-panel cleg-tenant-audit-panel"><div class="cleg-panel-head"><div><h2>Auditoria</h2></div>' . cleg_tenant_admin_help('Registro breve de acciones realizadas desde Administracion.') . '</div>';
        $html .= '<div class="cleg-table-wrap"><table><thead><tr><th>Evento</th><th>Detalle</th><th>Actor</th><th>Fecha</th></tr></thead><tbody>';
        $events = cleg_tenant_admin_audit_events($tenant);
        if (empty($events)) {
            $html .= '<tr><td colspan="4">Todavia no hay eventos registrados por esta pantalla.</td></tr>';
        }
        foreach ($events as $event) {
            $actor = !empty($event['actor']) ? get_userdata((int) $event['actor']) : false;
            $html .= '<tr><td><span class="cleg-pill ' . esc_attr(($event['status'] ?? '') === 'ok' ? 'is-ok' : 'is-warn') . '">' . esc_html((string) ($event['event'] ?? 'Evento')) . '</span></td><td>' . esc_html((string) ($event['detail'] ?? '')) . '</td><td>' . esc_html($actor ? $actor->display_name : 'Sistema') . '</td><td>' . esc_html((string) ($event['at'] ?? '')) . '</td></tr>';
        }

        return $html . '</tbody></table></div></section>';
    }
}

if (!function_exists('cleg_tenant_admin_styles')) {
    function cleg_tenant_admin_styles(): string {
        return <<<'HTML'
<style>
.cleg-module-admin-root{--cleg-app-bg:#f5f7f9;--cleg-app-surface:#fff;--cleg-app-surface-2:#eef2f5;--cleg-app-ink:#20252b;--cleg-app-muted:#65707c;--cleg-app-line:#d8e0e7;--cleg-app-orange:#c75000;--cleg-app-navy:#20252b;--cleg-app-shadow:0 18px 42px rgba(35,40,45,.08);background:var(--cleg-app-bg);padding:22px 0 34px;min-height:70vh;color:var(--cleg-app-ink)}
.cleg-module-admin-root .cleg-tenant-admin-shell{display:block!important;width:100%;max-width:none!important;margin:0!important;padding:0!important}
.cleg-module-admin-root *{box-sizing:border-box}
.cleg-module-admin-root .cleg-admin-header{width:min(1320px,calc(100% - 24px));margin:0 auto 12px;border-radius:22px;min-height:168px;padding:24px;display:flex;align-items:flex-end;justify-content:space-between;gap:18px;overflow:hidden;position:relative;background:linear-gradient(180deg,#fff,#f7fafc);box-shadow:0 18px 44px rgba(6,24,45,.08);color:#06182d!important;-webkit-text-fill-color:#06182d}
.cleg-module-admin-root .cleg-admin-header:before{content:"";position:absolute;inset:-35% auto auto 55%;width:420px;height:420px;border-radius:999px;background:radial-gradient(circle,rgba(26,108,255,.12),transparent 62%);pointer-events:none}
.cleg-module-admin-root .cleg-admin-header .cleg-command-copy{position:relative;z-index:1}
.cleg-module-admin-root .cleg-admin-header p{margin:0 0 8px;color:#506174!important;-webkit-text-fill-color:#506174;font-size:12px;text-transform:uppercase;font-weight:900;letter-spacing:0}
.cleg-module-admin-root .cleg-admin-header h1{margin:0;color:#071827!important;-webkit-text-fill-color:#071827;font-size:clamp(30px,4vw,52px);line-height:1.02;letter-spacing:0}
.cleg-module-admin-root .cleg-admin-header span{display:block;margin-top:8px;color:#506174!important;-webkit-text-fill-color:#506174;font-size:15px;font-weight:700;max-width:720px}
.cleg-module-admin-root .cleg-admin-mobile-menu{width:min(1320px,calc(100% - 24px));margin:0 auto 10px;border:1px solid var(--cleg-app-line);border-radius:8px;background:#fff;box-shadow:0 10px 24px rgba(35,40,45,.05);overflow:hidden}
.cleg-module-admin-root .cleg-admin-mobile-menu summary{list-style:none;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;color:var(--cleg-app-ink);font-weight:900}
.cleg-module-admin-root .cleg-admin-mobile-menu summary::-webkit-details-marker{display:none}
.cleg-module-admin-root .cleg-admin-mobile-menu summary span{color:var(--cleg-app-ink)}
.cleg-module-admin-root .cleg-admin-mobile-menu summary b{color:var(--cleg-app-orange)}
.cleg-module-admin-root .cleg-admin-mobile-menu div{display:grid;gap:6px;padding:0 10px 10px}
.cleg-module-admin-root .cleg-admin-mobile-menu a{display:flex;align-items:center;min-height:42px;padding:10px 12px;border-radius:16px;text-decoration:none;color:var(--cleg-app-ink);font-weight:800;box-shadow:0 10px 24px rgba(35,40,45,.05)}
.cleg-module-admin-root .cleg-admin-mobile-menu a.is-active{background:var(--cleg-app-navy);color:#fff!important}
.cleg-module-admin-root .cleg-admin-nav{width:min(1320px,calc(100% - 24px))!important;max-width:min(1320px,calc(100% - 24px))!important;margin:0 auto 14px!important;display:flex!important;align-items:center!important;gap:8px!important;border:1px solid rgba(6,24,45,.12);border-radius:16px;background:linear-gradient(180deg,#fff,#f7fafc);padding:8px!important;box-shadow:0 16px 36px rgba(6,24,45,.06)}
.cleg-module-admin-root .cleg-admin-nav a{display:inline-flex!important;align-items:center!important;justify-content:center!important;min-height:42px!important;padding:10px 14px!important;border-radius:999px!important;text-decoration:none!important;color:var(--cleg-app-ink)!important;font-weight:850!important;background:#fff!important;border:1px solid var(--cleg-app-line)!important;white-space:nowrap!important;box-shadow:0 10px 24px rgba(35,40,45,.05)!important}
.cleg-module-admin-root .cleg-admin-nav a.is-active{background:var(--cleg-app-navy)!important;color:#fff!important;border-color:var(--cleg-app-navy)!important}
.cleg-module-admin-root .cleg-admin-nav a.is-panel-link{margin-left:auto!important;background:#f8fafc!important;border-color:var(--cleg-app-line)!important}
.cleg-module-admin-root .cleg-admin-nav a.is-logout{background:#fff1e8!important;border-color:#ffd8c2!important;color:var(--cleg-app-orange)!important}
.cleg-tenant-tabs{display:flex;gap:8px;align-items:center;overflow:auto;padding:6px 2px 16px;margin:0 auto;width:min(1320px,calc(100% - 24px))}
