if (!function_exists('cleg_tenant_admin_center_shortcode')) {
    function cleg_tenant_admin_center_shortcode(): string {
        if (!cleg_tenant_admin_user_allowed()) {
            if (function_exists('cleg_admin_gate')) {
                return cleg_admin_gate();
            }

            return '<section class="cleg-admin-ui"><div class="cleg-admin-empty"><h2>No autorizado</h2><p>Esta pantalla es solo para administradores de empresa.</p></div></section>';
        }

        $tenant = cleg_tenant_admin_current_tenant();
        $users = cleg_tenant_admin_users($tenant);
        $employees = cleg_tenant_admin_employee_records();
        $tab = cleg_tenant_admin_tab();

        $html = '<section class="cleg-admin-ui cleg-tenant-admin-ui cleg-module-admin-root"><main class="cleg-admin-main cleg-admin-shell cleg-tenant-admin-shell">';
        if (function_exists('cleg_admin_page_header')) {
            $html .= cleg_admin_page_header('Administracion', 'Usuarios, permisos y modulos de la empresa.', array('eyebrow' => 'Vantrexor Administracion'));
        } else {
            $html .= '<header class="cleg-admin-header cleg-command-center"><div class="cleg-command-copy"><div class="cleg-app-brand-block">' . cleg_vantrexor_logo_markup('mark') . '<p class="cleg-app-kicker">Vantrexor Administracion</p></div><h1>Administracion</h1><span>Usuarios, permisos y modulos de la empresa.</span></div></header>';
        }
        $html .= cleg_tenant_admin_notice();
        if (function_exists('cleg_admin_nav')) {
            $html .= cleg_admin_nav('tenant-admin');
        }
        $html .= cleg_tenant_admin_tabs($tab);

        if ($tab === 'users') {
            $html .= cleg_tenant_admin_users_panel($tenant, $users);
        } elseif ($tab === 'roles') {
            $html .= cleg_tenant_admin_roles_panel();
        } elseif ($tab === 'modules') {
            $html .= cleg_tenant_admin_modules_panel($tenant);
        } elseif ($tab === 'invites' && cleg_tenant_admin_is_superadmin()) {
            $html .= cleg_tenant_admin_invites_panel($tenant, $users);
        } elseif ($tab === 'audit' && cleg_tenant_admin_is_superadmin()) {
            $html .= cleg_tenant_admin_audit_panel($tenant);
        } else {
            $html .= cleg_tenant_admin_overview($tenant, $users, $employees);
        }

        $html .= cleg_tenant_admin_styles();

        return $html . '</main></section>';
    }
}

add_shortcode('cleg_tenant_admin_center', 'cleg_tenant_admin_center_shortcode');
add_shortcode('cleg_admin_empresa', 'cleg_tenant_admin_center_shortcode');
