if (!function_exists('cleg_pwa_helper_v2_should_render')) {
    function cleg_pwa_helper_v2_should_render() {
        if (is_admin()) {
            return false;
        }

        $path = isset($_SERVER['REQUEST_URI']) ? sanitize_text_field(wp_unslash($_SERVER['REQUEST_URI'])) : '';

        return strpos($path, '/panel') !== false;
    }
}

