                    document.body.appendChild(bar);
                    document.body.appendChild(help);

                    const showHelp = function () { help.hidden = false; };
                    const hideHelp = function () { help.hidden = true; };

                    bar.querySelector('[data-cleg-pwa-install-btn]').addEventListener('click', async function () {
                        if (!installPrompt) {
                            showHelp();
                            return;
                        }
                        installPrompt.prompt();
                        await installPrompt.userChoice;
                        installPrompt = null;
                        bar.hidden = true;
                    });

                    bar.querySelector('[data-cleg-pwa-help-btn]').addEventListener('click', showHelp);
                    bar.querySelector('[data-cleg-pwa-close]').addEventListener('click', function () {
                        window.localStorage.setItem('cleg_pwa_install_dismissed_v2', '1');
                        bar.hidden = true;
                    });
                    help.querySelector('[data-cleg-pwa-help-close]').addEventListener('click', hideHelp);
                    help.addEventListener('click', function (event) { if (event.target === help) hideHelp(); });

                    window.setTimeout(function () { bar.hidden = false; }, isPanel ? 2200 : 900);
                    if (isPanel) {
                        window.setTimeout(function () { bar.hidden = true; }, 7000);
                    }
                };

                window.addEventListener('beforeinstallprompt', function (event) {
                    event.preventDefault();
                    installPrompt = event;
                    build();
                });

                if (document.readyState === 'loading') {
                    document.addEventListener('DOMContentLoaded', build);
                } else {
                    build();
                }
            })();
        </script>
