if (!function_exists('cleg_payroll_user_has_any_cap')) {
    function cleg_payroll_user_has_any_cap($user_id, array $caps) {
        $user_id = absint($user_id);
        if ($user_id <= 0) {
            return false;
        }

        foreach ($caps as $cap) {
            if (user_can($user_id, $cap)) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg_payroll_user_has_owner_signal')) {
    function cleg_payroll_user_has_owner_signal($user_id) {
        $user_id = absint($user_id);
        $user = $user_id > 0 ? get_userdata($user_id) : false;
        if (!$user instanceof WP_User) {
            return false;
        }

        $roles = isset($user->roles) ? (array) $user->roles : array();
        if (array_intersect($roles, array('administrator', 'cleg_owner', 'cleg_technical_admin'))) {
            return true;
        }

        $tenant_role = sanitize_text_field((string) get_user_meta($user_id, 'cleg_tenant_role', true));
        return in_array($tenant_role, array('Owner / Luis', 'Admin Tecnico / Alejandro Admin'), true);
    }
}

