if (!function_exists('cleg_payroll_records')) {
    function cleg_payroll_records($table, $query = array()) {
        $records = array();
        $offset = '';

        do {
            $page_query = $query;
            $page_query['pageSize'] = 100;

            if ($offset !== '') {
                $page_query['offset'] = $offset;
            }

            $response = cleg_payroll_request('GET', $table, array('query' => $page_query));

            if (is_wp_error($response)) {
                return $response;
            }

            $records = array_merge($records, $response['records'] ?? array());
            $offset = isset($response['offset']) ? sanitize_text_field($response['offset']) : '';
        } while ($offset !== '');

        return $records;
    }
}

if (!function_exists('cleg_payroll_field')) {
    function cleg_payroll_field($record, $field, $default = '') {
        $fields = $record['fields'] ?? array();
        $value = $fields[$field] ?? $default;

        if (is_array($value) && isset($value['name'])) {
            return sanitize_text_field($value['name']);
        }

        return is_scalar($value) ? sanitize_text_field((string) $value) : $default;
    }
}

if (!function_exists('cleg_payroll_period')) {
    function cleg_payroll_period() {
        $timezone = cleg_payroll_timezone();
        $default_end = cleg_payroll_last_closed_week_end();
        $end = isset($_REQUEST['payroll_week']) ? sanitize_text_field(wp_unslash($_REQUEST['payroll_week'])) : $default_end;

        if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $end)) {
            $end = $default_end;
        }

        try {
            $end_date = new DateTimeImmutable($end . ' 00:00:00', $timezone);
        } catch (Exception $e) {
            $end_date = new DateTimeImmutable($default_end . ' 00:00:00', $timezone);
        }

        if ((int) $end_date->format('w') !== 6) {
            $end_date = new DateTimeImmutable($default_end . ' 00:00:00', $timezone);
        }

        $start = $end_date->modify('-6 days')->format('Y-m-d');
        $end = $end_date->format('Y-m-d');

        return array($start, $end);
    }
}

if (!function_exists('cleg_payroll_timezone')) {
    function cleg_payroll_timezone() {
        return new DateTimeZone('America/Puerto_Rico');
    }
}

if (!function_exists('cleg_payroll_last_closed_week_end')) {
    function cleg_payroll_last_closed_week_end() {
        $now = new DateTimeImmutable('now', cleg_payroll_timezone());
        $last_saturday = $now->modify('last saturday');
        return $last_saturday->format('Y-m-d');
    }
}

if (!function_exists('cleg_payroll_airtable_datetime')) {
    function cleg_payroll_airtable_datetime($date, $time) {
        try {
            $local = new DateTimeImmutable($date . ' ' . $time, cleg_payroll_timezone());
        } catch (Exception $e) {
            $local = new DateTimeImmutable('now', cleg_payroll_timezone());
        }

        return $local->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s.000\Z');
    }
}

if (!function_exists('cleg_payroll_effective_clock_in_formula')) {
    function cleg_payroll_effective_clock_in_formula() {
