    }
}

if (!function_exists('cleg_payroll_week_options')) {
    function cleg_payroll_week_options($selected_end, $count = 18) {
        $timezone = cleg_payroll_timezone();
        $base_end = new DateTimeImmutable(cleg_payroll_last_closed_week_end() . ' 00:00:00', $timezone);
        $options = array();

        for ($i = 0; $i < $count; $i++) {
            $end_date = $base_end->modify('-' . $i . ' weeks');
            $start_date = $end_date->modify('-6 days');
            $value = $end_date->format('Y-m-d');
            $label = ($i === 0 ? 'Semana pasada: ' : 'Semana cerrada: ') . $start_date->format('d/m/Y') . ' - ' . $end_date->format('d/m/Y');
            $options[$value] = $label;
        }

        if ($selected_end !== '' && !isset($options[$selected_end])) {
            try {
                $selected = new DateTimeImmutable($selected_end . ' 00:00:00', $timezone);
                $options[$selected_end] = 'Semana cerrada: ' . $selected->modify('-6 days')->format('d/m/Y') . ' - ' . $selected->format('d/m/Y');
            } catch (Exception $e) {
                // Keep generated options only.
            }
        }

        return $options;
    }
}

