if (!function_exists('cleg_payroll_employee_key')) {
    function cleg_payroll_employee_key($record) {
        $wp_id = cleg_payroll_field($record, 'WordPress User ID');
        $username = cleg_payroll_field($record, 'Portal Username');
        $name = cleg_payroll_field($record, 'Employee Name');

        if ($wp_id !== '') {
            return 'wp_' . $wp_id;
        }

        if ($username !== '') {
            return 'user_' . strtolower($username);
        }

        return 'name_' . strtolower($name);
    }
}

if (!function_exists('cleg_payroll_is_payroll_employee')) {
    function cleg_payroll_is_payroll_employee($employee) {
        $name = strtolower(cleg_payroll_field($employee, 'Employee Name'));
        $username = strtolower(cleg_payroll_field($employee, 'Portal Username'));
        $role = cleg_payroll_field($employee, 'Role');
        $can_approve = cleg_payroll_field($employee, 'Can Approve Hours') !== '';

        if ($role === 'Administrador RRHH' || $can_approve) {
            return false;
        }

        if (strpos($name, 'alejandro') !== false && strpos($name, 'admin') !== false) {
            return false;
        }

        if (strpos($name, 'luis coll') !== false && strpos($name, 'admin') !== false) {
            return false;
        }

        if (strpos($username, 'alejandro') !== false && strpos($username, 'admin') !== false) {
            return false;
        }

        if (strpos($username, 'luis') !== false && strpos($username, 'admin') !== false) {
            return false;
        }

        return true;
    }
}

if (!function_exists('cleg_payroll_hours_between')) {
    function cleg_payroll_hours_between($clock_in, $clock_out) {
        $start = strtotime($clock_in);
        $end = strtotime($clock_out);

        if (!$start || !$end || $end <= $start) {
            return 0;
        }

        return ($end - $start) / HOUR_IN_SECONDS;
    }
}

if (!function_exists('cleg_payroll_format_hours')) {
    function cleg_payroll_format_hours($hours) {
        $total_minutes = (int) round(max(0, (float) $hours) * 60);
        $whole_hours = intdiv($total_minutes, 60);
        $minutes = $total_minutes % 60;

        if ($minutes === 0) {
            return $whole_hours . 'h';
        }

        return $whole_hours . 'h ' . $minutes . ' min';
    }
}

if (!function_exists('cleg_payroll_employee_start_date')) {
    function cleg_payroll_employee_start_date($employee) {
        $candidate_fields = array(
            'Payroll Start Date',
            'Employee Payroll Start Date',
            'Employee Start Date',
            'Hire Date',
            'Start Date',
            'Date Hired',
        );

        foreach ($candidate_fields as $field) {
            $value = cleg_payroll_field($employee, $field);
            if ($value === '') {
                continue;
            }

            $timestamp = strtotime($value);
            if ($timestamp) {
                return wp_date('Y-m-d', $timestamp);
            }
        }

        return '';
    }
}

