if (!function_exists('cleg_payroll_xls_cell')) {
    function cleg_payroll_xls_cell($value, $style = '', $type = null) {
        if ($value === null) {
            $value = '';
        }

        if ($type === null) {
            $type = is_numeric($value) && $value !== '' ? 'Number' : 'String';
        }

        $style_attr = $style !== '' ? ' ss:StyleID="' . cleg_payroll_xml($style) . '"' : '';
        return '<Cell' . $style_attr . '><Data ss:Type="' . cleg_payroll_xml($type) . '">' . cleg_payroll_xml($value) . '</Data></Cell>';
    }
}

if (!function_exists('cleg_payroll_xls_row')) {
    function cleg_payroll_xls_row($cells, $style = '') {
        $xml = '<Row>';
        foreach ($cells as $cell) {
            if (is_array($cell)) {
                $xml .= cleg_payroll_xls_cell($cell[0] ?? '', $cell[1] ?? $style, $cell[2] ?? null);
            } else {
                $xml .= cleg_payroll_xls_cell($cell, $style);
            }
        }
        return $xml . '</Row>';
    }
}

if (!function_exists('cleg_payroll_xls_sheet')) {
    function cleg_payroll_xls_sheet($name, $rows) {
        $xml = '<Worksheet ss:Name="' . cleg_payroll_xml(substr($name, 0, 31)) . '"><Table>';
        foreach ($rows as $row) {
            $xml .= is_array($row) ? cleg_payroll_xls_row($row) : $row;
        }
        return $xml . '</Table></Worksheet>';
    }
}

if (!function_exists('cleg_payroll_retention_percent')) {
