if (!function_exists('cleg_payroll_tax_rules')) {
    function cleg_payroll_tax_rules() {
        $rules = cleg_payroll_records(CLEG_AIRTABLE_PAYROLL_RULES_TABLE, array(
            'filterByFormula' => "AND({Tax Year}=2026,{Status}='Active')",
        ));

        if (is_wp_error($rules)) {
            return array();
        }

        $map = array();
        foreach ($rules as $rule) {
            $component = cleg_payroll_field($rule, 'Tax Component');
            if ($component === '') {
                continue;
            }

            $map[cleg_payroll_rule_key($component)] = array(
                'employee_rate' => cleg_payroll_number(cleg_payroll_raw_field($rule, 'Employee Rate'), 0),
                'employer_rate' => cleg_payroll_number(cleg_payroll_raw_field($rule, 'Employer Rate'), 0),
                'wage_base' => cleg_payroll_number(cleg_payroll_raw_field($rule, 'Wage Base Limit'), 0),
                'threshold' => cleg_payroll_number(cleg_payroll_raw_field($rule, 'Threshold Amount'), 0),
                'method' => cleg_payroll_field($rule, 'Calculation Method'),
            );
        }

        return $map;
    }
}

if (!function_exists('cleg_payroll_employee_tax_profiles')) {
    function cleg_payroll_employee_tax_profiles($start, $end) {
        $profiles = cleg_payroll_records(CLEG_AIRTABLE_TAX_PROFILES_TABLE, array(
            'filterByFormula' => "AND(OR({Effective From}=BLANK(),IS_BEFORE({Effective From},'{$end}T23:59:59.000Z')),OR({Effective To}=BLANK(),IS_AFTER({Effective To},'{$start}T00:00:00.000Z')))",
        ));

        if (is_wp_error($profiles)) {
            return array();
        }

        $map = array();
        foreach ($profiles as $profile) {
            $employee_links = cleg_payroll_raw_field($profile, 'Employee', array());
            if (!is_array($employee_links)) {
                continue;
            }

            foreach ($employee_links as $employee_id) {
                $employee_id = sanitize_text_field((string) $employee_id);
                if ($employee_id === '') {
                    continue;
                }

                $map[$employee_id] = array(
                    'profile_id' => sanitize_text_field($profile['id'] ?? ''),
                    'exempt_pr' => cleg_payroll_raw_field($profile, 'Exempt PR Withholding') ? true : false,
                    'fica_exempt' => cleg_payroll_raw_field($profile, 'FICA Exempt') ? true : false,
                    'contractor_override' => cleg_payroll_number(cleg_payroll_raw_field($profile, 'Contractor Withholding Override'), -1),
                    'additional_pr' => cleg_payroll_number(cleg_payroll_raw_field($profile, 'Additional PR Withholding'), 0),
                    'deduction_allowance' => cleg_payroll_number(cleg_payroll_raw_field($profile, 'Deduction Allowance Amount'), 0),
                    'sinot_exempt' => cleg_payroll_raw_field($profile, 'SINOT Exempt') ? true : false,
                    'opening_sinot_wages' => cleg_payroll_number(cleg_payroll_raw_field($profile, 'Opening YTD SINOT Wages'), 0),
                    'opening_sinot_paid' => cleg_payroll_number(cleg_payroll_raw_field($profile, 'Opening YTD SINOT Paid'), 0),
                    'certificate_status' => cleg_payroll_field($profile, 'Withholding Certificate Status'),
                    'document_verification_status' => cleg_payroll_field($profile, 'Document Verification Status'),
                    'document_expiration_date' => cleg_payroll_field($profile, 'Document Expiration Date'),
                    'verified_by' => cleg_payroll_field($profile, 'Verified By'),
                    'verified_at' => cleg_payroll_field($profile, 'Verified At'),
                    'filing_status' => cleg_payroll_field($profile, 'Filing Status PR'),
                    'dependents' => cleg_payroll_number(cleg_payroll_raw_field($profile, 'Dependents'), 0),
                    'notes' => cleg_payroll_field($profile, 'Notes'),
                );
            }
        }

        return $map;
    }
}

