if (!function_exists('cleg_payroll_monthly_pto_context')) {
    function cleg_payroll_monthly_pto_context($employee_id, $start) {
        $employee_id = sanitize_text_field((string) $employee_id);
        $month_start = substr($start, 0, 7) . '-01';
        if ($employee_id === '') {
            return array('eligible_hours' => 0, 'vacation_accrued' => 0, 'sick_accrued' => 0);
        }

        $lines = cleg_payroll_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'filterByFormula' => "AND(IS_AFTER({Period Start},'{$month_start}T00:00:00.000Z'),IS_BEFORE({Period Start},'{$start}T00:00:00.000Z'))",
        ));

        if (is_wp_error($lines)) {
            return array('eligible_hours' => 0, 'vacation_accrued' => 0, 'sick_accrued' => 0);
        }

        $context = array('eligible_hours' => 0, 'vacation_accrued' => 0, 'sick_accrued' => 0);
        foreach ($lines as $line) {
            $employee_links = cleg_payroll_raw_field($line, 'Employee', array());
            if (!is_array($employee_links) || !in_array($employee_id, array_map('strval', $employee_links), true)) {
                continue;
            }

            $detail = json_decode((string) cleg_payroll_raw_field($line, 'Calculation Detail JSON', ''), true);
            $pto = is_array($detail) && isset($detail['pto']) && is_array($detail['pto']) ? $detail['pto'] : array();
            $leave = is_array($detail) && isset($detail['leave']) && is_array($detail['leave']) ? $detail['leave'] : array();
            $worked = cleg_payroll_number(cleg_payroll_raw_field($line, 'Regular Hours'), 0) + cleg_payroll_number(cleg_payroll_raw_field($line, 'Overtime Hours'), 0);
            $paid_leave = cleg_payroll_number($leave['sick_paid_hours'] ?? 0, 0) + cleg_payroll_number($leave['vacation_paid_hours'] ?? 0, 0);
            $context['eligible_hours'] += cleg_payroll_number($pto['eligible_hours'] ?? ($worked + $paid_leave), 0);
            $context['vacation_accrued'] += cleg_payroll_number(cleg_payroll_raw_field($line, 'Vacation Accrued Hours', $pto['vacation_accrued'] ?? 0), 0);
            $context['sick_accrued'] += cleg_payroll_number(cleg_payroll_raw_field($line, 'Sick Accrued Hours', $pto['sick_accrued'] ?? 0), 0);
        }

        return $context;
    }
}

if (!function_exists('cleg_payroll_apply_leave_records')) {
    function cleg_payroll_apply_leave_records(&$row, $leaves) {
        if (empty($leaves) || !is_array($leaves)) {
            return;
        }

        $sick_balance = max(0, (float) ($row['pto_sick_balance'] ?? 0));
        $vacation_balance = max(0, (float) ($row['pto_vacation_balance'] ?? 0));
        $regular_hours_per_day = cleg_payroll_regular_hours_per_day($row);
        $hourly_rate = (float) ($row['amount'] ?? 0);
        if (($row['period'] ?? '') === 'Per Day' && $regular_hours_per_day > 0) {
            $hourly_rate = (float) ($row['amount'] ?? 0) / $regular_hours_per_day;
        }

        foreach ($leaves as $leave) {
            $type = cleg_payroll_field($leave, 'Leave Type');
            $requested = cleg_payroll_number(cleg_payroll_raw_field($leave, 'Hours Count'), 0);
            if ($requested <= 0) {
                continue;
            }

            $covered_sick = 0;
            $covered_vacation = 0;
            $unpaid = $requested;
            $legacy_balance_before = cleg_payroll_number(cleg_payroll_raw_field($leave, 'Balance Before'), 0);

            if ($type === 'Sick') {
                if ($legacy_balance_before > $sick_balance) {
                    $sick_balance = $legacy_balance_before;
                }
                $covered_sick = min($sick_balance, $requested);
                $sick_balance -= $covered_sick;
                $unpaid = max(0, $requested - $covered_sick);
                if ($unpaid > 0 && (!empty($row['leave_use_vacation_overflow']) || cleg_payroll_leave_uses_vacation_overflow($leave))) {
                    $covered_vacation = min($vacation_balance, $unpaid);
                    $vacation_balance -= $covered_vacation;
                    $unpaid = max(0, $unpaid - $covered_vacation);
                }
            } elseif ($type === 'Vacation') {
                if ($legacy_balance_before > $vacation_balance) {
                    $vacation_balance = $legacy_balance_before;
                }
                $covered_vacation = min($vacation_balance, $requested);
                $vacation_balance -= $covered_vacation;
                $unpaid = max(0, $requested - $covered_vacation);
            } elseif ($type === 'Unpaid Leave' || $type === 'Absence') {
                $unpaid = $requested;
            }

            $leave_pay_rate = max(0, $hourly_rate);
            $sick_pay = in_array(($row['period'] ?? ''), array('Per Hour', 'Per Day'), true) ? ($covered_sick * $leave_pay_rate) : 0;
            $vacation_pay = in_array(($row['period'] ?? ''), array('Per Hour', 'Per Day'), true) ? ($covered_vacation * $leave_pay_rate) : 0;

            $row['leave_requested_hours'] += $requested;
            $row['leave_sick_paid_hours'] += $covered_sick;
            $row['leave_vacation_paid_hours'] += $covered_vacation;
            $row['leave_unpaid_hours'] += $unpaid;
            $row['leave_paid_hours'] += ($covered_sick + $covered_vacation);
            $row['leave_sick_paid_amount'] += $sick_pay;
            $row['leave_vacation_paid_amount'] += $vacation_pay;
            $row['leave_paid_amount'] += ($sick_pay + $vacation_pay);
            $row['pto_sick_used'] += $covered_sick;
            $row['pto_vacation_used'] += $covered_vacation;
            $row['pto_sick_balance_after_usage'] = $sick_balance;
            $row['pto_vacation_balance_after_usage'] = $vacation_balance;
            $row['pto_eligible_hours'] += ($covered_sick + $covered_vacation);
            $leave_pay = $sick_pay + $vacation_pay;
            $row['regular_pay'] += $leave_pay;
            $row['pay'] += $leave_pay;
            $row['leave_rows'][] = array(
                'type' => $type,
                'start' => cleg_payroll_field($leave, 'Start Date'),
                'end' => cleg_payroll_field($leave, 'End Date'),
                'requested' => $requested,
                'sick_paid' => $covered_sick,
                'vacation_paid' => $covered_vacation,
                'unpaid' => $unpaid,
                'affects_pay' => ($covered_sick + $covered_vacation) > 0 || $unpaid > 0,
                'note' => cleg_payroll_field($leave, 'Employee Note', cleg_payroll_field($leave, 'Admin Note')),
            );
        }
    }
}

if (!function_exists('cleg_payroll_line_snapshots')) {
    function cleg_payroll_line_snapshots($start, $end) {
        $lines = cleg_payroll_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'filterByFormula' => "AND({Period Start}='{$start}',{Period End}='{$end}')",
        ));

        if (is_wp_error($lines)) {
            return array();
        }

        $snapshots = array();
        foreach ($lines as $line) {
            $employee_links = cleg_payroll_raw_field($line, 'Employee', array());
            if (!is_array($employee_links) || empty($employee_links[0])) {
                continue;
            }

            $employee_id = sanitize_text_field((string) $employee_links[0]);
            $detail = json_decode((string) cleg_payroll_raw_field($line, 'Calculation Detail JSON', ''), true);
            $detail_hours = is_array($detail) && isset($detail['hours']) && is_array($detail['hours']) ? $detail['hours'] : array();
            $detail_pay = is_array($detail) && isset($detail['pay']) && is_array($detail['pay']) ? $detail['pay'] : array();
            $detail_deductions = is_array($detail) && isset($detail['deductions']) && is_array($detail['deductions']) ? $detail['deductions'] : array();
            $detail_pto = is_array($detail) && isset($detail['pto']) && is_array($detail['pto']) ? $detail['pto'] : array();
            $detail_leave = is_array($detail) && isset($detail['leave']) && is_array($detail['leave']) ? $detail['leave'] : array();
            $gross_pay = cleg_payroll_number(cleg_payroll_raw_field($line, 'Gross Pay', $detail_pay['gross_pay'] ?? 0), 0);
            $net_pay = cleg_payroll_number(cleg_payroll_raw_field($line, 'Net Pay', $detail_pay['net_pay'] ?? 0), 0);
            $snapshot_rate = cleg_payroll_number($detail_pay['rate'] ?? 0, 0);
            $snapshot_plus_adjustments = cleg_payroll_number(cleg_payroll_raw_field($line, 'Plus Adjustments', $detail_pay['plus_adjustments'] ?? 0), 0);
            $line_fixed_total = cleg_payroll_number(cleg_payroll_raw_field($line, 'Fixed Deductions', 0), 0);
            $manual_deduction_field = cleg_payroll_raw_field($line, 'Manual Deduction', null);
            $manual_deduction_json = array_key_exists('manual_deduction', $detail_deductions) ? cleg_payroll_number($detail_deductions['manual_deduction'], 0) : 0;
            $detail_fixed_deductions = array_key_exists('fixed_deductions', $detail_deductions) ? cleg_payroll_number($detail_deductions['fixed_deductions'], 0) : 0;

            if ($manual_deduction_field !== null) {
                $manual_deduction = cleg_payroll_number($manual_deduction_field, 0);
            } elseif ($line_fixed_total > 0 && $detail_fixed_deductions <= 0) {
                $manual_deduction = $line_fixed_total;
            } else {
                $manual_deduction = $manual_deduction_json;
            }

            $fixed_deductions = max(0, $line_fixed_total - $manual_deduction);

            $snapshots[$employee_id] = array(
                'amount' => $snapshot_rate,
                'hours' => cleg_payroll_number($detail_hours['total'] ?? 0, 0),
                'regular_hours' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Regular Hours', $detail_hours['regular'] ?? 0), 0),
                'extra_hours' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Overtime Hours', $detail_hours['overtime'] ?? 0), 0),
                'regular_pay' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Regular Pay', $detail_pay['regular_pay'] ?? 0), 0),
                'extra_pay' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Overtime Pay', $detail_pay['overtime_pay'] ?? 0), 0),
                'manual_extra' => $snapshot_plus_adjustments,
                'gross_pay' => $gross_pay,
                'pay' => $gross_pay,
                'taxable_wages' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Taxable Wages', $gross_pay), $gross_pay),
                'social_security_employee' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Social Security Employee', $detail_deductions['social_security_employee'] ?? 0), 0),
                'medicare_employee' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Medicare Employee', $detail_deductions['medicare_employee'] ?? 0), 0),
                'pr_income_tax_withheld' => cleg_payroll_number(cleg_payroll_raw_field($line, 'PR Income Tax Withheld', $detail_deductions['pr_income_tax_withheld'] ?? 0), 0),
                'contractor_withholding' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Contractor Withholding', 0), 0),
                'sinot_employee' => cleg_payroll_number(cleg_payroll_raw_field($line, 'SINOT Employee', $detail_deductions['sinot_employee'] ?? 0), 0),
                'asume_garnishment' => cleg_payroll_number(cleg_payroll_raw_field($line, 'ASUME / Garnishment', 0), 0),
                'loan_advance_deduction' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Loan Advance Deduction', 0), 0),
                'health_voluntary_deduction' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Health / Voluntary Deduction', 0), 0),
                'fixed_deductions' => $fixed_deductions,
                'manual_deduction' => $manual_deduction,
                'period_pr_withholding' => cleg_payroll_number($detail_deductions['period_pr_withholding'] ?? 0, 0),
                'plus_adjustments' => $snapshot_plus_adjustments,
                'net_pay' => $net_pay,
                'total_deductions' => max(0, $gross_pay - $net_pay),
                'employer_social_security' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Employer Social Security', 0), 0),
                'employer_medicare' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Employer Medicare', 0), 0),
                'total_employer_cost' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Total Employer Cost', 0), 0),
                'pto_vacation_accrued' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Vacation Accrued Hours', $detail_pto['vacation_accrued'] ?? 0), 0),
                'pto_sick_accrued' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Sick Accrued Hours', $detail_pto['sick_accrued'] ?? 0), 0),
                'pto_vacation_balance_after' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Vacation Balance Hours', $detail_pto['vacation_balance_after'] ?? 0), 0),
                'pto_sick_balance_after' => cleg_payroll_number(cleg_payroll_raw_field($line, 'Sick Balance Hours', $detail_pto['sick_balance_after'] ?? 0), 0),
                'leave_requested_hours' => cleg_payroll_number($detail_leave['requested_hours'] ?? 0, 0),
                'leave_sick_paid_hours' => cleg_payroll_number($detail_leave['sick_paid_hours'] ?? 0, 0),
                'leave_vacation_paid_hours' => cleg_payroll_number($detail_leave['vacation_paid_hours'] ?? 0, 0),
                'leave_unpaid_hours' => cleg_payroll_number($detail_leave['unpaid_hours'] ?? 0, 0),
                'leave_paid_hours' => cleg_payroll_number($detail_leave['paid_hours'] ?? 0, 0),
                'leave_sick_paid_amount' => cleg_payroll_number($detail_leave['sick_paid_amount'] ?? 0, 0),
                'leave_vacation_paid_amount' => cleg_payroll_number($detail_leave['vacation_paid_amount'] ?? 0, 0),
                'leave_paid_amount' => cleg_payroll_number($detail_leave['paid_amount'] ?? 0, 0),
                'leave_use_vacation_overflow' => !empty($detail_leave['use_vacation_overflow']),
                'pto_sick_used' => cleg_payroll_number($detail_leave['sick_used_hours'] ?? 0, 0),
                'pto_vacation_used' => cleg_payroll_number($detail_leave['vacation_used_hours'] ?? 0, 0),
                'leave_rows' => isset($detail_leave['rows']) && is_array($detail_leave['rows']) ? $detail_leave['rows'] : array(),
                'calculation_status' => cleg_payroll_field($line, 'Calculation Status', 'Ready to Pay'),
                'review_notes' => cleg_payroll_field($line, 'Review Notes'),
            );
        }

        return $snapshots;
    }
}

if (!function_exists('cleg_payroll_component_amount')) {
    function cleg_payroll_component_amount($gross, $rate, $limit = 0, $threshold = 0, $method = 'Percent of gross', $ytd_wages = 0) {
        $gross = max(0, (float) $gross);
        $rate = max(0, (float) $rate);
        $limit = max(0, (float) $limit);
        $threshold = max(0, (float) $threshold);
        $ytd_wages = max(0, (float) $ytd_wages);

        if ($rate <= 0 || $gross <= 0) {
            return 0;
        }

        if ($method === 'Percent up to wage base' && $limit > 0) {
            $remaining = max(0, $limit - $ytd_wages);
            return min($gross, $remaining) * $rate;
        }

        if ($method === 'Percent above threshold' && $threshold > 0) {
            $previous_excess = max(0, $ytd_wages - $threshold);
            $current_excess = max(0, ($ytd_wages + $gross) - $threshold);
            return max(0, $current_excess - $previous_excess) * $rate;
        }

        return $gross * $rate;
    }
}

if (!function_exists('cleg_payroll_pr_personal_exemption_weekly')) {
    function cleg_payroll_pr_personal_exemption_weekly($filing_status) {
        $filing_status = trim((string) $filing_status);

        if ($filing_status === 'Married') {
            return 135.00;
        }

        if (in_array($filing_status, array('Single', 'Head of Household', 'Married Optional Computation'), true)) {
            return 67.00;
        }

        return 0.00;
    }
}

if (!function_exists('cleg_payroll_pr_income_tax_weekly')) {
    function cleg_payroll_pr_income_tax_weekly($gross, $profile) {
        $gross = max(0, (float) $gross);
        if ($gross <= 0 || empty($profile) || !is_array($profile)) {
            return 0;
        }

        $filing_status = $profile['filing_status'] ?? 'Not Provided';
        $dependents = max(0, (int) cleg_payroll_number($profile['dependents'] ?? 0, 0));
        $deduction_allowance = max(0, (float) cleg_payroll_number($profile['deduction_allowance'] ?? 0, 0));
        $exemption = cleg_payroll_pr_personal_exemption_weekly($filing_status) + ($dependents * 48.00) + $deduction_allowance;
        $subject_wages = max(0, $gross - $exemption);

        if ($subject_wages <= 173.10) {
            return 0;
        }

        if ($subject_wages <= 480.80) {
            return max(0, ($subject_wages * 0.07) - 12.10);
        }

        if ($subject_wages <= 798.10) {
            return max(0, ($subject_wages * 0.14) - 45.80);
        }

        if ($subject_wages <= 1182.70) {
            return max(0, ($subject_wages * 0.25) - 133.60);
        }

        return max(0, ($subject_wages * 0.33) - 228.20);
    }
}

if (!function_exists('cleg_payroll_apply_taxes')) {
    function cleg_payroll_apply_taxes(&$row, $rules, $profile) {
        $gross = max(0, (float) $row['pay']);
        $tax_type = cleg_payroll_default_tax_type($row['tax_type']);
        $fixed_deductions = max(0, (float) $row['fixed_deductions']);
        $manual_deduction = max(0, (float) ($row['manual_deduction'] ?? 0));
        $period_pr_withholding = max(0, (float) ($row['period_pr_withholding'] ?? 0));
        $plus_adjustments = max(0, (float) $row['plus_luis_total']) + max(0, (float) ($row['manual_extra'] ?? 0));

        $row['gross_pay'] = $gross;
        $row['taxable_wages'] = $tax_type === 'Employee - Full Payroll' ? $gross : 0;
        $row['social_security_employee'] = 0;
        $row['medicare_employee'] = 0;
        $row['pr_income_tax_withheld'] = 0;
        $row['contractor_withholding'] = 0;
        $row['sinot_employee'] = 0;
        $row['asume_garnishment'] = 0;
        $row['loan_advance_deduction'] = 0;
        $row['health_voluntary_deduction'] = 0;
        $row['employer_social_security'] = 0;
        $row['employer_medicare'] = 0;
        $row['fixed_deductions'] = $fixed_deductions;
        $row['manual_deduction'] = $manual_deduction;
        $row['period_pr_withholding'] = $period_pr_withholding;
        $row['plus_adjustments'] = $plus_adjustments;
        $row['calculation_status'] = 'Ready to Pay';
        $row['review_notes'] = '';
        $document_status = $profile['document_verification_status'] ?? '';
        $expiration = $profile['document_expiration_date'] ?? '';
        $expires_soon = false;
        if ($expiration !== '') {
            $expiration_ts = strtotime($expiration . ' 23:59:59');
            if ($expiration_ts && $expiration_ts < current_time('timestamp')) {
                $document_status = 'Expired';
                $row['calculation_status'] = 'Needs Review';
                $row['review_notes'] = 'Documento fiscal expirado.';
            } elseif ($expiration_ts && $expiration_ts <= current_time('timestamp') + (30 * DAY_IN_SECONDS)) {
                $expires_soon = true;
            }
        }

        if ($tax_type === 'Employee - Full Payroll') {
            $period_pr_withholding = 0;
            $row['period_pr_withholding'] = 0;
            $fica_exempt = !empty($profile['fica_exempt']);
            if (!$fica_exempt) {
                $ss_rule = $rules[cleg_payroll_rule_key('Social Security Employee')] ?? array();
                $medicare_rule = $rules[cleg_payroll_rule_key('Medicare Employee')] ?? array();
                $add_medicare_rule = $rules[cleg_payroll_rule_key('Additional Medicare Employee')] ?? array();
                $ytd_wages = cleg_payroll_number($row['ytd_taxable_wages'] ?? 0, 0);

                $row['social_security_employee'] = cleg_payroll_component_amount($gross, $ss_rule['employee_rate'] ?? 0.062, $ss_rule['wage_base'] ?? 184500, 0, $ss_rule['method'] ?? 'Percent up to wage base', $ytd_wages);
                $row['employer_social_security'] = cleg_payroll_component_amount($gross, $ss_rule['employer_rate'] ?? 0.062, $ss_rule['wage_base'] ?? 184500, 0, $ss_rule['method'] ?? 'Percent up to wage base', $ytd_wages);
                $row['medicare_employee'] = cleg_payroll_component_amount($gross, $medicare_rule['employee_rate'] ?? 0.0145, 0, 0, $medicare_rule['method'] ?? 'Percent of gross');
                $row['employer_medicare'] = cleg_payroll_component_amount($gross, $medicare_rule['employer_rate'] ?? 0.0145, 0, 0, $medicare_rule['method'] ?? 'Percent of gross');
                $row['medicare_employee'] += cleg_payroll_component_amount($gross, $add_medicare_rule['employee_rate'] ?? 0.009, 0, $add_medicare_rule['threshold'] ?? 200000, $add_medicare_rule['method'] ?? 'Percent above threshold', $ytd_wages);
                $sinot_rule = $rules[cleg_payroll_rule_key('SINOT Disability Insurance')] ?? array();
                if (!empty($sinot_rule) && empty($profile['sinot_exempt'])) {
                    $sinot_rate = cleg_payroll_number($sinot_rule['employee_rate'] ?? 0, 0);
                    $sinot_wage_base = cleg_payroll_number($sinot_rule['wage_base'] ?? 9000, 9000);
                    $sinot_ytd_wages = $ytd_wages + max(0, (float) ($profile['opening_sinot_wages'] ?? 0));
                    $sinot_amount = cleg_payroll_component_amount($gross, $sinot_rate, $sinot_wage_base, 0, $sinot_rule['method'] ?? 'Percent up to wage base', $sinot_ytd_wages);
                    $sinot_annual_cap = $sinot_rate > 0 && $sinot_wage_base > 0 ? $sinot_rate * $sinot_wage_base : 0;
                    if ($sinot_annual_cap > 0) {
                        $sinot_paid_to_date = max(0, (float) ($profile['opening_sinot_paid'] ?? 0)) + max(0, (float) ($row['ytd_sinot_paid'] ?? 0));
                        $sinot_amount = min($sinot_amount, max(0, $sinot_annual_cap - $sinot_paid_to_date));
                    }
                    $row['sinot_employee'] = $sinot_amount;
                }
            }

            if (!empty($profile['exempt_pr'])) {
                $row['pr_income_tax_withheld'] = 0;
            } else {
                $row['pr_income_tax_withheld'] = cleg_payroll_pr_income_tax_weekly($gross, $profile) + max(0, (float) ($profile['additional_pr'] ?? 0));
            }

            if (empty($profile) || ($profile['certificate_status'] ?? '') === 'Missing') {
                $row['calculation_status'] = 'Needs Review';
                $row['review_notes'] = 'Falta perfil fiscal/499 R-4 para calcular income tax PR exacto.';
            } elseif (in_array($document_status, array('Pending Review', 'Rejected', 'Expired'), true)) {
                $row['calculation_status'] = 'Needs Review';
                $row['review_notes'] = $document_status === 'Pending Review' ? 'Documento fiscal pendiente de verificacion.' : 'Documento fiscal requiere correccion o renovacion.';
            } elseif (($profile['filing_status'] ?? 'Not Provided') === 'Not Provided') {
                $row['calculation_status'] = 'Needs Review';
                $row['review_notes'] = 'Falta estado civil fiscal para calcular income tax PR con precision.';
            }
        } elseif ($tax_type === 'Contractor - 10% Withholding') {
            $override = isset($profile['contractor_override']) ? (float) $profile['contractor_override'] : -1;
            $rate = $override >= 0 ? $override : (float) ($row['retention_percent'] / 100);
            if ($rate <= 0) {
                $rate = 0.10;
            }
            $row['contractor_withholding'] = $gross * $rate;
        } else {
            $row['contractor_withholding'] = 0;
            if ($row['withholding_reason'] === '') {
                $row['calculation_status'] = 'Needs Review';
                $row['review_notes'] = 'Sin retencion: falta razon/relevo/documento.';
            }
        }

        if ($row['calculation_status'] !== 'Needs Review' && $expires_soon) {
            $row['review_notes'] = 'Documento fiscal vence pronto.';
        }

        $withheld = $row['social_security_employee'] + $row['medicare_employee'] + $row['pr_income_tax_withheld'] + $row['contractor_withholding'] + $row['sinot_employee'] + $row['asume_garnishment'] + $row['loan_advance_deduction'] + $row['health_voluntary_deduction'] + $fixed_deductions + $manual_deduction;
        $row['total_deductions'] = $withheld;
        $row['net_pay'] = max(0, $gross - $withheld);
        $row['total_employer_cost'] = $gross + $row['employer_social_security'] + $row['employer_medicare'];
    }
}

if (!function_exists('cleg_payroll_apply_line_snapshots')) {
    function cleg_payroll_apply_line_snapshots($rows, $line_snapshots) {
        if (empty($line_snapshots) || !is_array($line_snapshots)) {
            return $rows;
        }

        $snapshot_fields = array(
            'amount',
            'hours',
            'regular_hours',
            'extra_hours',
            'regular_pay',
            'extra_pay',
            'manual_extra',
            'pay',
            'gross_pay',
            'taxable_wages',
            'social_security_employee',
            'medicare_employee',
            'pr_income_tax_withheld',
            'contractor_withholding',
            'sinot_employee',
            'asume_garnishment',
            'loan_advance_deduction',
            'health_voluntary_deduction',
            'fixed_deductions',
            'manual_deduction',
            'period_pr_withholding',
            'plus_adjustments',
            'total_deductions',
            'net_pay',
            'employer_social_security',
            'employer_medicare',
            'total_employer_cost',
            'pto_vacation_accrued',
            'pto_sick_accrued',
            'pto_vacation_balance_after',
            'pto_sick_balance_after',
            'leave_requested_hours',
            'leave_sick_paid_hours',
            'leave_vacation_paid_hours',
            'leave_unpaid_hours',
            'leave_paid_hours',
            'leave_sick_paid_amount',
            'leave_vacation_paid_amount',
            'leave_paid_amount',
            'pto_sick_used',
            'pto_vacation_used',
        );

        foreach ($rows as &$row) {
            $employee_id = sanitize_text_field((string) ($row['id'] ?? ''));
            if ($employee_id === '' || empty($line_snapshots[$employee_id])) {
                continue;
            }

            $snapshot = $line_snapshots[$employee_id];
            foreach ($snapshot_fields as $field) {
                if (array_key_exists($field, $snapshot)) {
                    $row[$field] = cleg_payroll_number($snapshot[$field], $row[$field] ?? 0);
                }
            }

            if (!empty($snapshot['calculation_status'])) {
                $row['calculation_status'] = sanitize_text_field($snapshot['calculation_status']);
            }
            if (!empty($snapshot['review_notes'])) {
                $row['review_notes'] = sanitize_text_field($snapshot['review_notes']);
            }
            if (isset($snapshot['leave_rows']) && is_array($snapshot['leave_rows'])) {
                $row['leave_rows'] = $snapshot['leave_rows'];
            }
            $row['is_closed_snapshot'] = true;
        }
        unset($row);

        return $rows;
    }
}

if (!function_exists('cleg_payroll_data')) {
    function cleg_payroll_data($start, $end) {
        $rules = cleg_payroll_tax_rules();
        $tax_profiles = cleg_payroll_employee_tax_profiles($start, $end);
        $ytd_taxable_wages = cleg_payroll_ytd_taxable_wages($start);
        $ytd_sinot_paid = cleg_payroll_ytd_sinot_paid($start);
        $manual_extras = cleg_payroll_manual_extras($start, $end);
        $leave_map = cleg_payroll_leave_map($start, $end);
        $closed_entries = cleg_payroll_closed_entries($start, $end);
        $line_snapshots = !is_wp_error($closed_entries) && !empty($closed_entries) ? cleg_payroll_line_snapshots($start, $end) : array();

        $employees = cleg_payroll_records(CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'sort[0][field]' => 'Employee Name',
            'sort[0][direction]' => 'asc',
        ));

        if (is_wp_error($employees)) {
            return $employees;
        }

        $employee_map = array();

        foreach ($employees as $employee) {
            if (!cleg_payroll_is_payroll_employee($employee)) {
                continue;
            }

            $amount = (float) cleg_payroll_field($employee, 'Payroll Amount', '0');
            $period = cleg_payroll_field($employee, 'Payroll Period', 'Per Hour');
            $retention_percent = cleg_payroll_retention_percent(cleg_payroll_field($employee, 'Payroll Retention Percent', ''), 0);
            $tax_type = cleg_payroll_default_tax_type(cleg_payroll_field($employee, 'Payroll Tax Type'));

            if (!in_array($period, array('Per Hour', 'Per Day', 'Biweekly', 'Fixed Per Period'), true)) {
                $period = 'Per Hour';
            }

            $key = cleg_payroll_employee_key($employee);
            $employee_id = sanitize_text_field($employee['id']);
            $employee_start_date = cleg_payroll_employee_start_date($employee);
            $pto_vacation_balance = cleg_payroll_number(cleg_payroll_raw_field($employee, 'PTO Vacation Balance Hours'), 0);
            $pto_sick_balance = cleg_payroll_number(cleg_payroll_raw_field($employee, 'PTO Sick Balance Hours'), 0);
            $pto_vacation_rate = cleg_payroll_number(cleg_payroll_raw_field($employee, 'PTO Vacation Accrual Rate Hours'), cleg_payroll_default_vacation_accrual_rate());
            $pto_sick_rate = cleg_payroll_number(cleg_payroll_raw_field($employee, 'PTO Sick Accrual Rate Hours'), cleg_payroll_default_sick_accrual_rate());
            $regular_hours_per_day = cleg_payroll_number(cleg_payroll_raw_field($employee, 'Regular Hours Per Day'), cleg_payroll_regular_hours_per_day());
            $manual_extra = isset($manual_extras[$employee_id]['amount']) ? cleg_payroll_number($manual_extras[$employee_id]['amount'], 0) : 0;
            $manual_extra_note = isset($manual_extras[$employee_id]['note']) ? sanitize_text_field($manual_extras[$employee_id]['note']) : '';
            $manual_deduction = isset($manual_extras[$employee_id]['deduction']) ? cleg_payroll_number($manual_extras[$employee_id]['deduction'], 0) : 0;
            $manual_deduction_note = isset($manual_extras[$employee_id]['deduction_note']) ? sanitize_text_field($manual_extras[$employee_id]['deduction_note']) : '';
            $period_pr_withholding = isset($manual_extras[$employee_id]['pr_withholding']) ? cleg_payroll_number($manual_extras[$employee_id]['pr_withholding'], 0) : 0;
            $period_pr_note = isset($manual_extras[$employee_id]['pr_note']) ? sanitize_text_field($manual_extras[$employee_id]['pr_note']) : '';
            $leave_use_vacation_overflow = !empty($manual_extras[$employee_id]['leave_use_vacation_overflow']);
            if (isset($line_snapshots[$employee_id])) {
                $manual_deduction = cleg_payroll_number($line_snapshots[$employee_id]['manual_deduction'], $manual_deduction);
            }
            $employee_map[$key] = array(
                'id' => $employee_id,
                'name' => cleg_payroll_field($employee, 'Employee Name'),
                'username' => cleg_payroll_field($employee, 'Portal Username'),
                'wp_id' => cleg_payroll_field($employee, 'WordPress User ID'),
                'period' => $period,
                'amount' => $amount,
                'tax_type' => $tax_type,
                'employee_start_date' => $employee_start_date,
                'form_type' => cleg_payroll_field($employee, 'Payroll Form Type'),
                'retention_percent' => $retention_percent,
                'withholding_reason' => cleg_payroll_field($employee, 'Withholding Reason'),
                'regular_hours_per_day' => $regular_hours_per_day,
                'fixed_deductions' => cleg_payroll_number(cleg_payroll_raw_field($employee, 'Payroll Fixed Deductions'), 0),
                'invoice' => cleg_payroll_field($employee, 'Payroll Invoice Number'),
                'check' => cleg_payroll_field($employee, 'Payroll Check Number'),
                'payment_date' => cleg_payroll_field($employee, 'Payroll Payment Date'),
                'comments' => cleg_payroll_field($employee, 'Payroll Comments'),
                'tax_profile' => $tax_profiles[$employee_id] ?? array(),
                'ytd_taxable_wages' => $ytd_taxable_wages[$employee_id] ?? 0,
                'ytd_sinot_paid' => $ytd_sinot_paid[$employee_id] ?? 0,
                'hours' => 0,
                'pto_eligible_hours' => 0,
                'regular_hours' => 0,
                'extra_hours' => 0,
                'days' => array(),
                'day_hours' => array(),
                'day_entry_indexes' => array(),
                'entries' => 0,
                'entry_rows' => array(),
                'pay' => 0,
                'regular_pay' => 0,
                'extra_pay' => 0,
                'plus_luis_total' => 0,
                'manual_extra' => $manual_extra,
                'manual_extra_note' => $manual_extra_note,
                'manual_deduction' => $manual_deduction,
                'manual_deduction_note' => $manual_deduction_note,
                'period_pr_withholding' => $period_pr_withholding,
                'period_pr_note' => $period_pr_note,
                'leave_use_vacation_overflow' => $leave_use_vacation_overflow,
                'pto_vacation_balance' => $pto_vacation_balance,
                'pto_sick_balance' => $pto_sick_balance,
                'pto_vacation_rate' => $pto_vacation_rate,
                'pto_sick_rate' => $pto_sick_rate,
                'pto_vacation_accrued' => 0,
                'pto_sick_accrued' => 0,
                'pto_vacation_balance_after' => $pto_vacation_balance,
                'pto_sick_balance_after' => $pto_sick_balance,
                'pto_vacation_balance_after_usage' => $pto_vacation_balance,
                'pto_sick_balance_after_usage' => $pto_sick_balance,
                'pto_vacation_used' => 0,
                'pto_sick_used' => 0,
                'leave_requested_hours' => 0,
                'leave_paid_hours' => 0,
                'leave_sick_paid_hours' => 0,
                'leave_vacation_paid_hours' => 0,
                'leave_unpaid_hours' => 0,
                'leave_sick_paid_amount' => 0,
                'leave_vacation_paid_amount' => 0,
                'leave_paid_amount' => 0,
                'leave_rows' => array(),
            );
        }

        $range_start = cleg_payroll_airtable_datetime($start, '00:00:00');
        $range_end = cleg_payroll_airtable_datetime($end, '23:59:59');
        $effective_clock_in = cleg_payroll_effective_clock_in_formula();
        $formula = "AND(IS_AFTER({$effective_clock_in},'{$range_start}'),IS_BEFORE({$effective_clock_in},'{$range_end}'),OR({Approval Status}='Approved',{Approval Status}='Payroll Closed'))";
        $entries = cleg_payroll_records(CLEG_AIRTABLE_TIME_TABLE, array(
            'filterByFormula' => $formula,
            'sort[0][field]' => 'Clock In Time',
            'sort[0][direction]' => 'asc',
        ));

        if (is_wp_error($entries)) {
            return $entries;
        }

        foreach ($entries as $entry) {
            $fields = $entry['fields'] ?? array();
            $wp_id = isset($fields['WordPress User ID']) ? (string) $fields['WordPress User ID'] : '';
            $username = isset($fields['Portal Username']) ? strtolower(sanitize_text_field($fields['Portal Username'])) : '';
            $name = isset($fields['Employee Name']) ? strtolower(sanitize_text_field($fields['Employee Name'])) : '';
            $key = $wp_id !== '' ? 'wp_' . $wp_id : ($username !== '' ? 'user_' . $username : 'name_' . $name);

            if (!isset($employee_map[$key])) {
                continue;
            }

            $clock_in = isset($fields['Admin Adjusted Clock In Time']) ? sanitize_text_field($fields['Admin Adjusted Clock In Time']) : (isset($fields['Clock In Time']) ? sanitize_text_field($fields['Clock In Time']) : '');
            $clock_out = isset($fields['Admin Adjusted Clock Out Time']) ? sanitize_text_field($fields['Admin Adjusted Clock Out Time']) : (isset($fields['Clock Out Time']) ? sanitize_text_field($fields['Clock Out Time']) : '');
            $lunch_minutes = isset($fields['Lunch Minutes']) && is_numeric($fields['Lunch Minutes']) ? (float) $fields['Lunch Minutes'] : 30;
            $hours = max(0, cleg_payroll_hours_between($clock_in, $clock_out) - ($lunch_minutes / 60));
            $clock_in_timestamp = $clock_in !== '' ? strtotime($clock_in) : false;
            $is_weekend = $clock_in_timestamp ? in_array((int) wp_date('w', $clock_in_timestamp), array(0, 6), true) : false;
            $day_key = $clock_in_timestamp ? wp_date('Y-m-d', $clock_in_timestamp) : '';

            $employee_map[$key]['hours'] += $hours;
            $employee_start_date = $employee_map[$key]['employee_start_date'] ?? '';
            if ($employee_start_date === '' || ($day_key !== '' && $day_key >= $employee_start_date)) {
                $employee_map[$key]['pto_eligible_hours'] += $hours;
            }
            $employee_map[$key]['entries']++;
            $plus_luis = isset($fields['Plus Luis']) && is_numeric($fields['Plus Luis']) ? (float) $fields['Plus Luis'] : 0;
            $employee_map[$key]['plus_luis_total'] += $plus_luis;

            $entry_index = count($employee_map[$key]['entry_rows']);
            if ($day_key !== '') {
                $employee_map[$key]['days'][$day_key] = true;
                if (!isset($employee_map[$key]['day_hours'][$day_key])) {
                    $employee_map[$key]['day_hours'][$day_key] = array(
                        'hours' => 0,
                        'is_weekend' => $is_weekend,
                    );
                    $employee_map[$key]['day_entry_indexes'][$day_key] = array();
                }
                $employee_map[$key]['day_hours'][$day_key]['hours'] += $hours;
                $employee_map[$key]['day_hours'][$day_key]['is_weekend'] = $employee_map[$key]['day_hours'][$day_key]['is_weekend'] || $is_weekend;
                $employee_map[$key]['day_entry_indexes'][$day_key][] = $entry_index;
            }

            $employee_map[$key]['entry_rows'][] = array(
                'record_id' => sanitize_text_field($entry['id'] ?? ''),
                'timestamp' => $clock_in_timestamp ? (int) $clock_in_timestamp : 0,
                'day_key' => $day_key,
                'date' => $clock_in !== '' ? cleg_payroll_excel_date($clock_in) : '',
                'weekday' => $clock_in_timestamp ? cleg_payroll_day_es($clock_in_timestamp) : '',
                'name' => isset($fields['Employee Name']) ? sanitize_text_field($fields['Employee Name']) : $employee_map[$key]['name'],
                'job_site' => isset($fields['Job Site Name']) ? sanitize_text_field($fields['Job Site Name']) : '',
                'activity' => isset($fields['Activity']) ? sanitize_text_field($fields['Activity']) : '',
                'clock_in' => cleg_payroll_excel_time($clock_in),
                'clock_out' => cleg_payroll_excel_time($clock_out),
                'lunch' => $lunch_minutes,
                'hours' => $hours,
                'plus_luis' => $plus_luis,
                'regular_hours' => 0,
                'extra_hours' => 0,
                'is_weekend' => $is_weekend,
                'status' => isset($fields['Approval Status']) ? sanitize_text_field($fields['Approval Status']) : '',
            );
        }

        foreach ($employee_map as &$row) {
            $row['regular_hours'] = 0;
            $row['extra_hours'] = 0;
            foreach (($row['day_hours'] ?? array()) as $day_key => $day_info) {
                $day_hours = (float) ($day_info['hours'] ?? 0);
                $day_is_weekend = !empty($day_info['is_weekend']);
                $day_regular_hours = $day_is_weekend ? 0 : min($day_hours, 8);
                $day_extra_hours = $day_is_weekend ? $day_hours : max(0, $day_hours - 8);
                $row['regular_hours'] += $day_regular_hours;
                $row['extra_hours'] += $day_extra_hours;

                $remaining_regular = $day_regular_hours;
                foreach (($row['day_entry_indexes'][$day_key] ?? array()) as $entry_index) {
                    if (!isset($row['entry_rows'][$entry_index])) {
                        continue;
                    }
                    $entry_hours = (float) ($row['entry_rows'][$entry_index]['hours'] ?? 0);
                    $entry_regular = min($entry_hours, $remaining_regular);
                    $entry_extra = max(0, $entry_hours - $entry_regular);
                    $row['entry_rows'][$entry_index]['regular_hours'] = $entry_regular;
                    $row['entry_rows'][$entry_index]['extra_hours'] = $entry_extra;
                    $remaining_regular = max(0, $remaining_regular - $entry_regular);
                }
            }

            $days = count($row['days']);
            if ($row['period'] === 'Per Day') {
                $row['pay'] = $days * $row['amount'];
                $row['regular_pay'] = $row['pay'];
                $row['extra_pay'] = 0;
            } elseif ($row['period'] === 'Biweekly' || $row['period'] === 'Fixed Per Period') {
                $row['pay'] = $row['amount'];
                $row['regular_pay'] = $row['pay'];
                $row['extra_pay'] = 0;
            } else {
                $row['regular_pay'] = $row['regular_hours'] * $row['amount'];
                $row['extra_pay'] = $row['extra_hours'] * $row['amount'] * 1.5;
                $row['pay'] = $row['regular_pay'] + $row['extra_pay'];
            }
            $row['pay'] += (float) $row['plus_luis_total'] + (float) $row['manual_extra'];
            $row['days_count'] = $days;

            $employee_id = sanitize_text_field((string) ($row['id'] ?? ''));
            if ($employee_id !== '' && !empty($leave_map[$employee_id])) {
                cleg_payroll_apply_leave_records($row, $leave_map[$employee_id]);
            }

            if (cleg_payroll_default_tax_type($row['tax_type'] ?? '') === 'Employee - Full Payroll') {
                $pto_eligible_hours = max(0, (float) ($row['pto_eligible_hours'] ?? $row['hours']));
                if (cleg_payroll_employer_size_policy() === '12_or_less') {
                    $month_context = cleg_payroll_monthly_pto_context($row['id'] ?? '', $start);
                    $monthly_eligible_hours = $pto_eligible_hours + cleg_payroll_number($month_context['eligible_hours'] ?? 0, 0);
                    $regular_day = cleg_payroll_regular_hours_per_day($row);
                    $row['pto_vacation_accrued'] = ($monthly_eligible_hours >= 130 && cleg_payroll_number($month_context['vacation_accrued'] ?? 0, 0) <= 0) ? round(0.5 * $regular_day, 2) : 0;
                    $row['pto_sick_accrued'] = ($monthly_eligible_hours >= 130 && cleg_payroll_number($month_context['sick_accrued'] ?? 0, 0) <= 0) ? round(1 * $regular_day, 2) : 0;
                    $row['pto_monthly_eligible_hours'] = $monthly_eligible_hours;
                    $row['pto_policy'] = '12_or_less_130h_month';
                } else {
                    $row['pto_vacation_accrued'] = round($pto_eligible_hours * max(0, (float) ($row['pto_vacation_rate'] ?? 0)), 2);
                    $row['pto_sick_accrued'] = round($pto_eligible_hours * max(0, (float) ($row['pto_sick_rate'] ?? 0)), 2);
                    $row['pto_monthly_eligible_hours'] = $pto_eligible_hours;
                    $row['pto_policy'] = '13_or_more_hourly_accrual';
                }
                $row['pto_vacation_balance_after'] = round(max(0, (float) ($row['pto_vacation_balance_after_usage'] ?? $row['pto_vacation_balance'])) + (float) $row['pto_vacation_accrued'], 2);
                $row['pto_sick_balance_after'] = round(max(0, (float) ($row['pto_sick_balance_after_usage'] ?? $row['pto_sick_balance'])) + (float) $row['pto_sick_accrued'], 2);
            }
        }
        unset($row);

        foreach ($employee_map as &$row) {
            cleg_payroll_apply_taxes($row, $rules, $row['tax_profile']);
        }
        unset($row);

        $payroll_rows = array();
        foreach ($employee_map as $row) {
            if ((int) ($row['entries'] ?? 0) <= 0 && (float) ($row['leave_requested_hours'] ?? 0) <= 0) {
                continue;
            }

            $payroll_rows[] = $row;
        }

        $payroll_rows = cleg_payroll_apply_line_snapshots($payroll_rows, $line_snapshots);

        return $payroll_rows;
    }
}

if (!function_exists('cleg_payroll_pending_entries')) {
    function cleg_payroll_pending_entries($start, $end) {
        $range_start = cleg_payroll_airtable_datetime($start, '00:00:00');
        $range_end = cleg_payroll_airtable_datetime($end, '23:59:59');
        $effective_clock_in = cleg_payroll_effective_clock_in_formula();
        $formula = "AND(IS_AFTER({$effective_clock_in},'{$range_start}'),IS_BEFORE({$effective_clock_in},'{$range_end}'),OR({Approval Status}=BLANK(),{Approval Status}='Open',{Approval Status}='Pending Review',{Approval Status}='Review',{Approval Status}='Manual Need Review'))";

        $entries = cleg_payroll_records(CLEG_AIRTABLE_TIME_TABLE, array(
            'filterByFormula' => $formula,
            'sort[0][field]' => 'Clock In Time',
            'sort[0][direction]' => 'asc',
        ));

        if (is_wp_error($entries)) {
            return $entries;
        }

        return $entries;
    }
}

if (!function_exists('cleg_payroll_closed_entries')) {
    function cleg_payroll_closed_entries($start, $end) {
        $range_start = cleg_payroll_airtable_datetime($start, '00:00:00');
        $range_end = cleg_payroll_airtable_datetime($end, '23:59:59');
        $effective_clock_in = cleg_payroll_effective_clock_in_formula();
        $formula = "AND(IS_AFTER({$effective_clock_in},'{$range_start}'),IS_BEFORE({$effective_clock_in},'{$range_end}'),{Approval Status}='Payroll Closed')";

        $entries = cleg_payroll_records(CLEG_AIRTABLE_TIME_TABLE, array(
            'filterByFormula' => $formula,
            'sort[0][field]' => 'Clock In Time',
            'sort[0][direction]' => 'asc',
        ));

        if (is_wp_error($entries)) {
            return $entries;
        }

        return $entries;
    }
}

if (!function_exists('cleg_payroll_pending_summary')) {
    function cleg_payroll_pending_summary($entries) {
        if (empty($entries) || !is_array($entries)) {
            return '';
        }

        $items = array();
        foreach (array_slice($entries, 0, 5) as $entry) {
            $name = cleg_payroll_field($entry, 'Employee Name', 'Sin empleado');
            $status = cleg_payroll_field($entry, 'Approval Status', 'Sin estado');
            $clock_in = cleg_payroll_field($entry, 'Clock In Time');
            $date = $clock_in !== '' ? cleg_payroll_excel_date($clock_in) : '';
            $items[] = trim($name . ' - ' . $date . ' - ' . $status);
        }

        $extra = count($entries) > 5 ? ' y ' . (count($entries) - 5) . ' mas' : '';
        return implode('; ', $items) . $extra;
    }
}

if (!function_exists('cleg_payroll_update_rates')) {
    function cleg_payroll_update_rates() {
        if (empty($_POST['cleg_payroll_action']) || $_POST['cleg_payroll_action'] !== 'save_rates') {
            return;
        }

        if (!cleg_payroll_can_manage()) {
            return;
        }

        if (!isset($_POST['cleg_payroll_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_payroll_nonce'])), 'cleg_payroll_save_rates')) {
            return;
        }

        $amounts = isset($_POST['payroll_amount']) && is_array($_POST['payroll_amount']) ? wp_unslash($_POST['payroll_amount']) : array();
        $periods = isset($_POST['payroll_period']) && is_array($_POST['payroll_period']) ? wp_unslash($_POST['payroll_period']) : array();
        $manual_extra_amounts = isset($_POST['manual_extra']) && is_array($_POST['manual_extra']) ? wp_unslash($_POST['manual_extra']) : array();
        $manual_extra_notes = isset($_POST['manual_extra_note']) && is_array($_POST['manual_extra_note']) ? wp_unslash($_POST['manual_extra_note']) : array();
        $manual_deduction_amounts = isset($_POST['manual_deduction']) && is_array($_POST['manual_deduction']) ? wp_unslash($_POST['manual_deduction']) : array();
        $manual_deduction_notes = isset($_POST['manual_deduction_note']) && is_array($_POST['manual_deduction_note']) ? wp_unslash($_POST['manual_deduction_note']) : array();
        $period_pr_amounts = isset($_POST['period_pr_withholding']) && is_array($_POST['period_pr_withholding']) ? wp_unslash($_POST['period_pr_withholding']) : array();
        $period_pr_notes = isset($_POST['period_pr_note']) && is_array($_POST['period_pr_note']) ? wp_unslash($_POST['period_pr_note']) : array();
        $leave_vacation_overflow = isset($_POST['leave_use_vacation_overflow']) && is_array($_POST['leave_use_vacation_overflow']) ? wp_unslash($_POST['leave_use_vacation_overflow']) : array();
        list($start, $end) = cleg_payroll_period();
        $closed_entries = cleg_payroll_closed_entries($start, $end);
        if (!is_wp_error($closed_entries) && !empty($closed_entries)) {
            wp_safe_redirect(add_query_arg('payroll_locked', '1', wp_get_referer() ?: home_url('/payroll-rrhh/')));
            exit;
        }

        $manual_extras = array();
        $updates = array();

        foreach ($amounts as $record_id => $amount) {
            $record_id = sanitize_text_field($record_id);
            $period = isset($periods[$record_id]) ? sanitize_text_field($periods[$record_id]) : 'Per Hour';
            if (!in_array($period, array('Per Hour', 'Per Day', 'Biweekly', 'Fixed Per Period'), true)) {
                $period = 'Per Hour';
            }

            $updates[] = array(
                'id' => $record_id,
                'fields' => array(
                    'Payroll Amount' => max(0, (float) sanitize_text_field($amount)),
                    'Payroll Period' => $period,
                ),
            );

            $extra_amount = isset($manual_extra_amounts[$record_id]) ? max(0, (float) sanitize_text_field($manual_extra_amounts[$record_id])) : 0;
            $extra_note = isset($manual_extra_notes[$record_id]) ? sanitize_text_field($manual_extra_notes[$record_id]) : '';
            $deduction_amount = isset($manual_deduction_amounts[$record_id]) ? max(0, (float) sanitize_text_field($manual_deduction_amounts[$record_id])) : 0;
            $deduction_note = isset($manual_deduction_notes[$record_id]) ? sanitize_text_field($manual_deduction_notes[$record_id]) : '';
            $pr_amount = isset($period_pr_amounts[$record_id]) ? max(0, (float) sanitize_text_field($period_pr_amounts[$record_id])) : 0;
            $pr_note = isset($period_pr_notes[$record_id]) ? sanitize_text_field($period_pr_notes[$record_id]) : '';
            $use_vacation_overflow = !empty($leave_vacation_overflow[$record_id]);
            if ($extra_amount > 0 || $extra_note !== '' || $deduction_amount > 0 || $deduction_note !== '' || $pr_amount > 0 || $pr_note !== '' || $use_vacation_overflow) {
                $manual_extras[$record_id] = array(
                    'amount' => $extra_amount,
                    'note' => $extra_note,
                    'deduction' => $deduction_amount,
                    'deduction_note' => $deduction_note,
                    'pr_withholding' => $pr_amount,
                    'pr_note' => $pr_note,
                    'leave_use_vacation_overflow' => $use_vacation_overflow,
                );
            }
        }

        update_option(cleg_payroll_manual_extras_key($start, $end), $manual_extras, false);

        foreach (array_chunk($updates, 10) as $chunk) {
            cleg_payroll_request('PATCH', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
                'body' => array('records' => $chunk, 'typecast' => true),
            ));
        }

        wp_safe_redirect(add_query_arg('payroll_saved', '1', wp_get_referer() ?: home_url('/payroll-rrhh/')));
        exit;
    }
}

if (!function_exists('cleg_payroll_label')) {
