if (!function_exists('cleg_payroll_upload_certificate')) {
    function cleg_payroll_upload_certificate($input_name) {
        if (empty($_FILES[$input_name]) || empty($_FILES[$input_name]['name'])) {
            return '';
        }

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';

        $attachment_id = media_handle_upload($input_name, 0);
        if (is_wp_error($attachment_id)) {
            return '';
        }

        return esc_url_raw(wp_get_attachment_url($attachment_id));
    }
}

if (!function_exists('cleg_payroll_sheet_name')) {
    function cleg_payroll_sheet_name($row, $index) {
        $name = trim((string) ($row['name'] ?? 'Trabajador'));
        $name = preg_replace('/[\[\]\:\*\?\/\\\\]+/', ' ', $name);
        $name = preg_replace('/\s+/', ' ', $name);
        $prefix = str_pad((string) $index, 2, '0', STR_PAD_LEFT) . ' ';
        return substr($prefix . ($name !== '' ? $name : 'Trabajador'), 0, 31);
    }
}

if (!function_exists('cleg_payroll_employee_statement_rows')) {
    function cleg_payroll_employee_statement_rows($row, $start, $end) {
        $is_employee = cleg_payroll_default_tax_type($row['tax_type'] ?? '') === 'Employee - Full Payroll';
        $payment_timestamp = !empty($row['payment_date']) ? strtotime($row['payment_date']) : false;
        $payment_date = $payment_timestamp ? wp_date('m/d/Y', $payment_timestamp) : wp_date('m/d/Y');
        $retention_percent = cleg_payroll_retention_percent($row['retention_percent'] ?? 0, 0);

        if (!$is_employee) {
            $rows = array(
                array(array('C&L ENGINEERING GROUP LLC', 'brandTitle')),
                array(array('Contractor Payment Summary', 'section'), '', array('Periodo', 'muted'), $start . ' - ' . $end),
                array(),
                array(array('Contractor', 'header'), $row['name'] ?? '', array('Payment Date', 'header'), $payment_date),
                array(array('Form', 'header'), 'W-9 / 1099 contractor', array('Withholding Rate', 'header'), number_format($retention_percent, 2) . '%'),
                array(),
                array(array('Total Hours', 'header'), array(round((float) ($row['hours'] ?? 0), 2), 'num')),
                array(array('Gross Pay', 'header'), array(round((float) ($row['gross_pay'] ?? 0), 2), 'money')),
                array(array('Contractor Deduction', 'header'), array(round((float) ($row['contractor_withholding'] ?? 0), 2), 'money')),
                array(array('Total Paid', 'totalLabel'), array(round((float) ($row['net_pay'] ?? 0), 2), 'total')),
                array(),
                array(array('Useful Documentation', 'section')),
                array('W-9 on file', 'Verify from visible contractor documents in the portal.'),
                array('Hours rule', 'Contractor view shows total approved hours only; overtime is not separated.'),
                array(),
                array(array('Date', 'header'), array('Job Site / Obra', 'header'), array('Activity', 'header'), array('In', 'header'), array('Out', 'header'), array('Hours', 'header')),
            );

            foreach (($row['entry_rows'] ?? array()) as $entry) {
                $rows[] = array(
                    $entry['date'] ?? '',
                    $entry['job_site'] ?? '',
                    $entry['activity'] ?? '',
                    $entry['clock_in'] ?? '',
                    $entry['clock_out'] ?? '',
                    array(round((float) ($entry['hours'] ?? 0), 2), 'num'),
                );
            }

            return $rows;
        }

        $rows = array(
            array(array('C&L ENGINEERING GROUP LLC', 'brandTitle')),
            array(array('Employee Payroll Statement', 'section'), '', array('Periodo', 'muted'), $start . ' - ' . $end),
            array(),
            array(array('Employee', 'header'), $row['name'] ?? '', array('Payment Date', 'header'), $payment_date),
            array(array('Pay Type', 'header'), cleg_payroll_label($row['period'] ?? ''), array('Rate', 'header'), array(round((float) ($row['amount'] ?? 0), 2), 'money')),
            array(),
            array(array('Earnings', 'section')),
            array('Worked Hours', array(round((float) ($row['hours'] ?? 0), 2), 'num'), 'Regular Pay', array(round((float) ($row['regular_pay'] ?? 0), 2), 'money')),
            array('Paid Sick Hours', array(round((float) ($row['leave_sick_paid_hours'] ?? 0), 2), 'num'), 'Paid Vacation Hours', array(round((float) ($row['leave_vacation_paid_hours'] ?? 0), 2), 'num')),
            array('Paid Sick Pay', array(round((float) ($row['leave_sick_paid_amount'] ?? 0), 2), 'money'), 'Paid Vacation Pay', array(round((float) ($row['leave_vacation_paid_amount'] ?? 0), 2), 'money')),
            array('Unpaid Absence Hours', array(round((float) ($row['leave_unpaid_hours'] ?? 0), 2), 'num'), 'Requested Leave Hours', array(round((float) ($row['leave_requested_hours'] ?? 0), 2), 'num')),
            array('Overtime Hours', array(round((float) ($row['extra_hours'] ?? 0), 2), 'num'), 'Overtime Pay', array(round((float) ($row['extra_pay'] ?? 0), 2), 'money')),
            array('Other Adjustments', array(round((float) ($row['plus_adjustments'] ?? 0), 2), 'money'), 'Gross Pay', array(round((float) ($row['gross_pay'] ?? 0), 2), 'total')),
            array(),
            array(array('Deductions', 'section')),
            array('Social Security', array(round((float) ($row['social_security_employee'] ?? 0), 2), 'money'), 'Medicare', array(round((float) ($row['medicare_employee'] ?? 0), 2), 'money')),
            array('SINOT', array(round((float) ($row['sinot_employee'] ?? 0), 2), 'money'), 'Income Tax PR', array(round((float) ($row['pr_income_tax_withheld'] ?? 0), 2), 'money')),
            array('Manual / Other', array(round((float) (($row['manual_deduction'] ?? 0) + ($row['fixed_deductions'] ?? 0)), 2), 'money'), 'Total Deductions', array(round((float) ($row['total_deductions'] ?? 0), 2), 'money')),
            array(array('Net Pay', 'totalLabel'), array(round((float) ($row['net_pay'] ?? 0), 2), 'total')),
            array(),
            array(array('Vacation / Sick Accrual', 'section')),
            array('Vacation accrued this period', array(round((float) ($row['pto_vacation_accrued'] ?? 0), 2), 'num'), 'Vacation remaining balance', array(round((float) ($row['pto_vacation_balance_after'] ?? 0), 2), 'num')),
            array('Sick accrued this period', array(round((float) ($row['pto_sick_accrued'] ?? 0), 2), 'num'), 'Sick remaining balance', array(round((float) ($row['pto_sick_balance_after'] ?? 0), 2), 'num')),
            array(),
            array(array('Work Detail', 'section')),
            array(array('Date', 'header'), array('Job Site / Obra', 'header'), array('Activity', 'header'), array('In', 'header'), array('Out', 'header'), array('Regular H', 'header'), array('Extra H', 'header'), array('Total H', 'header')),
        );

        foreach (($row['entry_rows'] ?? array()) as $entry) {
            $rows[] = array(
                $entry['date'] ?? '',
                $entry['job_site'] ?? '',
                $entry['activity'] ?? '',
                $entry['clock_in'] ?? '',
                $entry['clock_out'] ?? '',
                array(round((float) ($entry['regular_hours'] ?? 0), 2), 'num'),
                array(round((float) ($entry['extra_hours'] ?? 0), 2), 'num'),
                array(round((float) ($entry['hours'] ?? 0), 2), 'num'),
            );
        }

        return $rows;
    }
}

if (!function_exists('cleg_payroll_sync_calculation_lines')) {
