            foreach (($row['entry_rows'] ?? array()) as $entry_row) {
                if (!empty($entry_row['record_id'])) {
                    $time_entry_ids[] = sanitize_text_field($entry_row['record_id']);
                }
            }
            $calculation_detail = array(
                'period' => array('start' => $start, 'end' => $end),
                'employee' => array('id' => $employee_id, 'name' => $row['name'] ?? '', 'username' => $row['username'] ?? '', 'wp_id' => $row['wp_id'] ?? ''),
                'hours' => array('total' => (float) ($row['hours'] ?? 0), 'regular' => (float) ($row['regular_hours'] ?? 0), 'overtime' => (float) ($row['extra_hours'] ?? 0)),
                'pay' => array('rate' => (float) ($row['amount'] ?? 0), 'regular_pay' => (float) ($row['regular_pay'] ?? 0), 'overtime_pay' => (float) ($row['extra_pay'] ?? 0), 'gross_pay' => (float) ($row['gross_pay'] ?? 0), 'net_pay' => (float) ($row['net_pay'] ?? 0)),
                'deductions' => array(
                    'social_security_employee' => (float) ($row['social_security_employee'] ?? 0),
                    'medicare_employee' => (float) ($row['medicare_employee'] ?? 0),
                    'pr_income_tax_withheld' => (float) ($row['pr_income_tax_withheld'] ?? 0),
                    'sinot_employee' => (float) ($row['sinot_employee'] ?? 0),
                    'ytd_sinot_paid_before_period' => (float) ($row['ytd_sinot_paid'] ?? 0),
                    'opening_sinot_wages' => (float) ($row['tax_profile']['opening_sinot_wages'] ?? 0),
                    'opening_sinot_paid' => (float) ($row['tax_profile']['opening_sinot_paid'] ?? 0),
                    'fixed_deductions' => (float) ($row['fixed_deductions'] ?? 0),
