                    'monthly_eligible_hours' => (float) ($row['pto_monthly_eligible_hours'] ?? 0),
                    'vacation_balance_before' => (float) ($row['pto_vacation_balance'] ?? 0),
                    'sick_balance_before' => (float) ($row['pto_sick_balance'] ?? 0),
                    'vacation_used' => (float) ($row['pto_vacation_used'] ?? 0),
                    'sick_used' => (float) ($row['pto_sick_used'] ?? 0),
                    'vacation_accrued' => (float) ($row['pto_vacation_accrued'] ?? 0),
                    'sick_accrued' => (float) ($row['pto_sick_accrued'] ?? 0),
                    'vacation_balance_after' => (float) ($row['pto_vacation_balance_after'] ?? 0),
                    'sick_balance_after' => (float) ($row['pto_sick_balance_after'] ?? 0),
                ),
                'leave' => array(
                    'requested_hours' => (float) ($row['leave_requested_hours'] ?? 0),
                    'paid_hours' => (float) ($row['leave_paid_hours'] ?? 0),
                    'sick_paid_hours' => (float) ($row['leave_sick_paid_hours'] ?? 0),
                    'vacation_paid_hours' => (float) ($row['leave_vacation_paid_hours'] ?? 0),
                    'unpaid_hours' => (float) ($row['leave_unpaid_hours'] ?? 0),
                    'sick_paid_amount' => (float) ($row['leave_sick_paid_amount'] ?? 0),
                    'vacation_paid_amount' => (float) ($row['leave_vacation_paid_amount'] ?? 0),
                    'paid_amount' => (float) ($row['leave_paid_amount'] ?? 0),
                    'use_vacation_overflow' => !empty($row['leave_use_vacation_overflow']),
                    'sick_used_hours' => (float) ($row['pto_sick_used'] ?? 0),
                    'vacation_used_hours' => (float) ($row['pto_vacation_used'] ?? 0),
                    'rows' => $row['leave_rows'] ?? array(),
                ),
                'status' => $row['calculation_status'] ?? '',
                'notes' => $review_notes,
            );

            $records[] = array(
                'fields' => array(
                    'Calculation Code' => 'CLEG-' . $start . '-' . $end . '-' . $employee_id,
                    'Employee' => array($employee_id),
                    'Period Start' => $start,
                    'Period End' => $end,
                    'Worker Tax Type' => $row['tax_type'],
                    'Regular Hours' => round((float) $row['regular_hours'], 2),
                    'Overtime Hours' => round((float) $row['extra_hours'], 2),
                    'Regular Pay' => round((float) $row['regular_pay'], 2),
                    'Overtime Pay' => round((float) $row['extra_pay'], 2),
                    'Gross Pay' => round((float) $row['gross_pay'], 2),
                    'Taxable Wages' => round((float) $row['taxable_wages'], 2),
                    'Social Security Employee' => round((float) $row['social_security_employee'], 2),
                    'Medicare Employee' => round((float) $row['medicare_employee'], 2),
                    'PR Income Tax Withheld' => round((float) $row['pr_income_tax_withheld'], 2),
                    'Contractor Withholding' => round((float) $row['contractor_withholding'], 2),
