                    'Loan Advance Deduction' => round((float) ($row['loan_advance_deduction'] ?? 0), 2),
                    'Health / Voluntary Deduction' => round((float) ($row['health_voluntary_deduction'] ?? 0), 2),
                    'Fixed Deductions' => round((float) $row['fixed_deductions'] + (float) ($row['manual_deduction'] ?? 0), 2),
                    'Plus Adjustments' => round((float) $row['plus_adjustments'], 2),
                    'Net Pay' => round((float) $row['net_pay'], 2),
                    'Employer Social Security' => round((float) $row['employer_social_security'], 2),
                    'Employer Medicare' => round((float) $row['employer_medicare'], 2),
                    'Total Employer Cost' => round((float) $row['total_employer_cost'], 2),
                    'Vacation Accrued Hours' => round((float) ($row['pto_vacation_accrued'] ?? 0), 2),
                    'Sick Accrued Hours' => round((float) ($row['pto_sick_accrued'] ?? 0), 2),
                    'Vacation Balance Hours' => round((float) ($row['pto_vacation_balance_after'] ?? 0), 2),
                    'Sick Balance Hours' => round((float) ($row['pto_sick_balance_after'] ?? 0), 2),
                    'Calculation Status' => $row['calculation_status'],
                    'Review Notes' => $review_notes,
                    'Pay Method' => 'Pending',
                    'Payment Reference' => $row['check'] ?? '',
                    'Employee Visible Notes' => $review_notes,
                    'Time Entries' => $time_entry_ids,
                    'Calculation Detail JSON' => wp_json_encode($calculation_detail),
                ),
            );
        }

        foreach (array_chunk($records, 10) as $chunk) {
            cleg_payroll_request('PATCH', CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
                'body' => array(
                    'records' => $chunk,
                    'performUpsert' => array(
                        'fieldsToMergeOn' => array('Calculation Code'),
                    ),
                    'typecast' => true,
                ),
            ));
        }
    }
}

if (!function_exists('cleg_payroll_update_employee_pto_balances')) {
    function cleg_payroll_update_employee_pto_balances($data) {
        if (empty($data)) {
            return;
        }

        $records = array();
        foreach ($data as $row) {
            if (cleg_payroll_default_tax_type($row['tax_type'] ?? '') !== 'Employee - Full Payroll') {
                continue;
            }

            $employee_id = sanitize_text_field($row['id'] ?? '');
            if ($employee_id === '') {
                continue;
            }

            $records[] = array(
                'id' => $employee_id,
                'fields' => array(
                    'PTO Vacation Balance Hours' => round((float) ($row['pto_vacation_balance_after'] ?? 0), 2),
                    'PTO Sick Balance Hours' => round((float) ($row['pto_sick_balance_after'] ?? 0), 2),
                ),
            );
        }

        foreach (array_chunk($records, 10) as $chunk) {
            cleg_payroll_request('PATCH', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
                'body' => array('records' => $chunk, 'typecast' => true),
            ));
        }
    }
}

if (!function_exists('cleg_payroll_close_time_entries')) {
    function cleg_payroll_close_time_entries($data) {
        $entry_ids = array();
        foreach ($data as $row) {
            foreach (($row['entry_rows'] ?? array()) as $entry_row) {
                $entry_id = sanitize_text_field($entry_row['record_id'] ?? '');
                if ($entry_id !== '') {
                    $entry_ids[$entry_id] = true;
                }
            }
        }

        if (empty($entry_ids)) {
            return;
        }

        $user = wp_get_current_user();
        $locked_by = $user && !empty($user->display_name) ? $user->display_name : 'CLEG Payroll';
        $locked_at = gmdate('Y-m-d\TH:i:s\Z');
        $records = array();

        foreach (array_keys($entry_ids) as $entry_id) {
            $records[] = array(
                'id' => $entry_id,
                'fields' => array(
                    'Approval Status' => 'Payroll Closed',
                    'Payroll Locked' => true,
                    'Payroll Locked At' => $locked_at,
                    'Payroll Locked By' => $locked_by,
                ),
            );
        }

        foreach (array_chunk($records, 10) as $chunk) {
            cleg_payroll_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
                'body' => array('records' => $chunk, 'typecast' => true),
            ));
        }
    }
}

if (!function_exists('cleg_payroll_period_lines')) {
    function cleg_payroll_period_lines($start, $end) {
        return cleg_payroll_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'filterByFormula' => "AND({Period Start}='{$start}',{Period End}='{$end}')",
        ));
    }
}

if (!function_exists('cleg_payroll_rollback_previous_week_records')) {
    function cleg_payroll_rollback_previous_week_records($start, $end) {
        if (!cleg_payroll_is_work_week($end)) {
            return new WP_Error('cleg_payroll_rollback_week', 'El rollback solo esta disponible para la semana anterior a la actual.');
        }

        $closed_entries = cleg_payroll_closed_entries($start, $end);
        if (is_wp_error($closed_entries)) {
            return $closed_entries;
        }

        $lines = cleg_payroll_period_lines($start, $end);
        if (is_wp_error($lines)) {
            return $lines;
        }

        if (empty($closed_entries) && empty($lines)) {
            return new WP_Error('cleg_payroll_rollback_empty', 'No hay payroll cerrado para revertir en esta semana.');
        }

        $time_entry_ids = array();
        foreach ($closed_entries as $entry) {
            $entry_id = sanitize_text_field($entry['id'] ?? '');
            if ($entry_id !== '') {
                $time_entry_ids[$entry_id] = true;
            }
        }

        $line_ids = array();
        foreach ($lines as $line) {
            $line_id = sanitize_text_field($line['id'] ?? '');
            if ($line_id !== '') {
                $line_ids[$line_id] = true;
            }

            $linked_entries = cleg_payroll_raw_field($line, 'Time Entries', array());
            if (is_array($linked_entries)) {
                foreach ($linked_entries as $linked_entry_id) {
                    $linked_entry_id = sanitize_text_field((string) $linked_entry_id);
                    if ($linked_entry_id !== '') {
                        $time_entry_ids[$linked_entry_id] = true;
                    }
                }
            }
        }

        $entry_records = array();
        foreach (array_keys($time_entry_ids) as $entry_id) {
            $entry_records[] = array(
                'id' => $entry_id,
                'fields' => array(
                    'Approval Status' => 'Approved',
                    'Payroll Locked' => false,
                ),
            );
        }

        foreach (array_chunk($entry_records, 10) as $chunk) {
            $response = cleg_payroll_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
                'body' => array('records' => $chunk, 'typecast' => true),
            ));

            if (is_wp_error($response)) {
                return $response;
            }
        }

        foreach (array_chunk(array_keys($line_ids), 10) as $chunk) {
            $response = cleg_payroll_request('DELETE', CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
                'query' => array('records' => $chunk),
            ));

            if (is_wp_error($response)) {
                return $response;
            }
        }

        return array(
            'time_entries' => count($time_entry_ids),
            'lines' => count($line_ids),
        );
    }
}

if (!function_exists('cleg_payroll_month_period')) {
    function cleg_payroll_month_period($month = '') {
        $timezone = cleg_payroll_timezone();
        $month = preg_match('/^\d{4}-\d{2}$/', (string) $month) ? (string) $month : wp_date('Y-m', null, $timezone);
        $start = new DateTimeImmutable($month . '-01 00:00:00', $timezone);
        return array($start->format('Y-m-d'), $start->modify('last day of this month')->format('Y-m-d'), $start->format('Y-m'));
    }
}

if (!function_exists('cleg_payroll_month_options')) {
    function cleg_payroll_month_options($selected_month, $count = 12) {
        $base = new DateTimeImmutable('first day of this month 00:00:00', cleg_payroll_timezone());
        $options = array();
        for ($i = 0; $i < $count; $i++) {
            $month = $base->modify('-' . $i . ' months');
            $value = $month->format('Y-m');
            $options[$value] = $month->format('m/Y');
        }
        if (!isset($options[$selected_month])) {
            $options[$selected_month] = $selected_month;
        }
        return $options;
    }
}

if (!function_exists('cleg_payroll_month_week_ranges')) {
    function cleg_payroll_month_week_ranges($month_start, $month_end) {
        $timezone = cleg_payroll_timezone();
        $cursor = new DateTimeImmutable($month_start . ' 00:00:00', $timezone);
        while ((int) $cursor->format('w') !== 6) {
            $cursor = $cursor->modify('+1 day');
        }

        $end = new DateTimeImmutable($month_end . ' 00:00:00', $timezone);
        $ranges = array();
        while ($cursor <= $end) {
            $ranges[] = array($cursor->modify('-6 days')->format('Y-m-d'), $cursor->format('Y-m-d'));
            $cursor = $cursor->modify('+1 week');
        }
        return $ranges;
    }
}

if (!function_exists('cleg_payroll_month_summary_from_data')) {
    function cleg_payroll_month_summary_from_data($data) {
        $summary = array();
        foreach ((array) $data as $row) {
            $key = sanitize_text_field((string) ($row['id'] ?? $row['name'] ?? ''));
            if ($key === '') {
                continue;
            }
            if (!isset($summary[$key])) {
                $summary[$key] = array(
                    'name' => sanitize_text_field((string) ($row['name'] ?? '')),
                    'hours' => 0,
                    'regular_hours' => 0,
                    'extra_hours' => 0,
                    'gross_pay' => 0,
                    'net_pay' => 0,
                    'periods' => 0,
                );
            }
            $summary[$key]['hours'] += (float) ($row['hours'] ?? 0);
            $summary[$key]['regular_hours'] += (float) ($row['regular_hours'] ?? 0);
            $summary[$key]['extra_hours'] += (float) ($row['extra_hours'] ?? 0);
            $summary[$key]['gross_pay'] += (float) ($row['gross_pay'] ?? $row['pay'] ?? 0);
            $summary[$key]['net_pay'] += (float) ($row['net_pay'] ?? $row['pay'] ?? 0);
            $summary[$key]['periods']++;
        }
        uasort($summary, function ($a, $b) {
            return strcasecmp($a['name'] ?? '', $b['name'] ?? '');
        });
        return $summary;
    }
}

if (!function_exists('cleg_payroll_month_summary_merge')) {
    function cleg_payroll_month_summary_merge($target, $source) {
        foreach ((array) $source as $key => $row) {
            if (!isset($target[$key])) {
                $target[$key] = $row;
                continue;
            }
            foreach (array('hours', 'regular_hours', 'extra_hours', 'gross_pay', 'net_pay', 'periods') as $field) {
                $target[$key][$field] += (float) ($row[$field] ?? 0);
            }
        }
        uasort($target, function ($a, $b) {
            return strcasecmp($a['name'] ?? '', $b['name'] ?? '');
        });
        return $target;
    }
}

if (!function_exists('cleg_payroll_month_summary_table')) {
    function cleg_payroll_month_summary_table($summary, $empty_message = 'Sin datos para este mes.') {
        $html = '<div class="cleg-payroll-month-table"><table><thead><tr><th>Trabajador</th><th>Horas</th><th>Regular</th><th>Extra</th><th>Bruto</th><th>Total pagado</th><th>Periodos</th></tr></thead><tbody>';
        foreach ((array) $summary as $row) {
            $html .= '<tr><td><strong>' . esc_html($row['name'] ?? '') . '</strong></td>'
                . '<td>' . esc_html(cleg_payroll_format_hours((float) ($row['hours'] ?? 0))) . '</td>'
                . '<td>' . esc_html(cleg_payroll_format_hours((float) ($row['regular_hours'] ?? 0))) . '</td>'
                . '<td>' . esc_html(cleg_payroll_format_hours((float) ($row['extra_hours'] ?? 0))) . '</td>'
                . '<td>$' . esc_html(number_format((float) ($row['gross_pay'] ?? 0), 2)) . '</td>'
                . '<td><strong>$' . esc_html(number_format((float) ($row['net_pay'] ?? 0), 2)) . '</strong></td>'
                . '<td>' . esc_html((string) absint($row['periods'] ?? 0)) . '</td></tr>';
        }
        if (empty($summary)) {
            $html .= '<tr><td colspan="7">' . esc_html($empty_message) . '</td></tr>';
        }
        return $html . '</tbody></table></div>';
    }
}

if (!function_exists('cleg_payroll_month_report')) {
    function cleg_payroll_month_report($selected_month) {
        list($month_start, $month_end, $month_value) = cleg_payroll_month_period($selected_month);
        $natural_data = cleg_payroll_data($month_start, $month_end);
        if (is_wp_error($natural_data)) {
            return '<div class="cleg-payroll-blocked"><strong>Error resumen mensual.</strong> ' . esc_html($natural_data->get_error_message()) . '</div>';
        }

        $paid_summary = array();
        $paid_ranges = cleg_payroll_month_week_ranges($month_start, $month_end);
        foreach ($paid_ranges as $range) {
            $period_lines = cleg_payroll_period_lines($range[0], $range[1]);
            if (is_wp_error($period_lines) || empty($period_lines)) {
                continue;
            }
            $period_data = cleg_payroll_data($range[0], $range[1]);
            if (!is_wp_error($period_data)) {
                $paid_summary = cleg_payroll_month_summary_merge($paid_summary, cleg_payroll_month_summary_from_data($period_data));
            }
        }

        $options = cleg_payroll_month_options($month_value);
        ob_start();
        ?>
        <section class="cleg-payroll-month-report">
            <form class="cleg-payroll-month-filter" method="get">
                <input type="hidden" name="payroll_report" value="month">
                <label>Mes
                    <select name="payroll_month" onchange="this.form.submit()">
                        <?php foreach ($options as $value => $label) : ?>
                            <option value="<?php echo esc_attr($value); ?>" <?php selected($month_value, $value); ?>><?php echo esc_html($label); ?></option>
                        <?php endforeach; ?>
                    </select>
                </label>
                <a href="<?php echo esc_url(home_url('/payroll-rrhh/')); ?>">Volver a semana</a>
            </form>
            <div class="cleg-payroll-month-grid">
                <article>
                    <h2>Mes natural</h2>
                    <p>Horas trabajadas entre <?php echo esc_html($month_start); ?> y <?php echo esc_html($month_end); ?>.</p>
                    <?php echo cleg_payroll_month_summary_table(cleg_payroll_month_summary_from_data($natural_data)); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                </article>
                <article>
                    <h2>Mes cobrado / contabilidad</h2>
                    <p>Semanas cerradas de Payroll cuyo cierre cae dentro del mes.</p>
                    <?php echo cleg_payroll_month_summary_table($paid_summary, 'Sin payroll cerrado dentro de este mes.'); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                </article>
            </div>
        </section>
        <?php
        return ob_get_clean();
    }
}

if (!function_exists('cleg_payroll_report_year_options')) {
    function cleg_payroll_report_year_options($selected_year, $count = 5) {
        $current = (int) wp_date('Y', null, cleg_payroll_timezone());
        $selected_year = preg_match('/^\d{4}$/', (string) $selected_year) ? (int) $selected_year : $current;
        $years = array();
        for ($i = 0; $i < $count; $i++) {
            $years[] = (string) ($current - $i);
        }
        if (!in_array((string) $selected_year, $years, true)) {
            $years[] = (string) $selected_year;
        }
        return $years;
    }
}

if (!function_exists('cleg_payroll_report_range')) {
    function cleg_payroll_report_range($mode, $month, $year) {
        $mode = $mode === 'year' ? 'year' : 'month';
        $timezone = cleg_payroll_timezone();
        if ($mode === 'year') {
            $year = preg_match('/^\d{4}$/', (string) $year) ? (string) $year : wp_date('Y', null, $timezone);
            return array($year . '-01-01', $year . '-12-31', $year, 'Año ' . $year);
        }
        list($start, $end, $value) = cleg_payroll_month_period($month);
        return array($start, $end, $value, 'Mes ' . date_i18n('m/Y', strtotime($start)));
    }
}

if (!function_exists('cleg_payroll_report_line_name')) {
    function cleg_payroll_report_line_name($line, $detail = array()) {
        $name = '';
        if (isset($detail['employee']['name'])) {
            $name = sanitize_text_field((string) $detail['employee']['name']);
        }
        if ($name === '') {
            $raw = cleg_payroll_raw_field($line, 'Employee', '');
            if (is_array($raw)) {
                $name = sanitize_text_field((string) reset($raw));
            } elseif (is_scalar($raw)) {
                $name = sanitize_text_field((string) $raw);
            }
        }
        return $name !== '' ? $name : 'Trabajador sin nombre';
    }
}

if (!function_exists('cleg_payroll_report_line_value')) {
    function cleg_payroll_report_line_value($line, $field, $detail_path = array(), $default = 0) {
        $value = cleg_payroll_raw_field($line, $field, null);
        if ($value !== null && $value !== '') {
            return cleg_payroll_number($value, $default);
        }

        $detail = json_decode((string) cleg_payroll_raw_field($line, 'Calculation Detail JSON', ''), true);
        $cursor = is_array($detail) ? $detail : array();
        foreach ($detail_path as $part) {
            if (!is_array($cursor) || !array_key_exists($part, $cursor)) {
                return (float) $default;
            }
            $cursor = $cursor[$part];
        }
        return cleg_payroll_number($cursor, $default);
    }
}

if (!function_exists('cleg_payroll_report_lines')) {
    function cleg_payroll_report_lines($start, $end, $provided_lines = null) {
        if (is_array($provided_lines) && !empty($provided_lines)) {
            $lines = $provided_lines;
        } else {
        $formula = "AND(OR({Period End}='{$start}',IS_AFTER({Period End},'{$start}')),OR({Period End}='{$end}',IS_BEFORE({Period End},'{$end}')))";
        $lines = cleg_payroll_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'filterByFormula' => $formula,
            'sort[0][field]' => 'Period End',
            'sort[0][direction]' => 'asc',
        ));
        }

        if (is_wp_error($lines)) {
            return $lines;
        }

        $normalized = array();
        foreach ($lines as $line) {
            $detail = json_decode((string) cleg_payroll_raw_field($line, 'Calculation Detail JSON', ''), true);
            $detail = is_array($detail) ? $detail : array();
            $employee_links = cleg_payroll_raw_field($line, 'Employee', array());
            $employee_id = is_array($employee_links) && !empty($employee_links[0]) ? sanitize_text_field((string) $employee_links[0]) : sanitize_text_field((string) ($detail['employee']['id'] ?? ''));
            $worker_type = cleg_payroll_default_tax_type(cleg_payroll_field($line, 'Worker Tax Type', $detail['employee']['tax_type'] ?? 'Employee - Full Payroll'));
            $gross = cleg_payroll_report_line_value($line, 'Gross Pay', array('pay', 'gross_pay'));
            $net = cleg_payroll_report_line_value($line, 'Net Pay', array('pay', 'net_pay'));
            $normalized[] = array(
                'employee_id' => $employee_id !== '' ? $employee_id : md5(cleg_payroll_report_line_name($line, $detail)),
                'name' => cleg_payroll_report_line_name($line, $detail),
                'worker_type' => $worker_type,
                'form_type' => cleg_payroll_field($line, 'Payroll Form Type', $worker_type === 'Employee - Full Payroll' ? 'W-2PR / 499R-2' : '480.6SP'),
                'period_start' => cleg_payroll_field($line, 'Period Start'),
                'period_end' => cleg_payroll_field($line, 'Period End'),
                'hours' => cleg_payroll_report_line_value($line, 'Regular Hours', array('hours', 'regular')) + cleg_payroll_report_line_value($line, 'Overtime Hours', array('hours', 'overtime')),
                'regular_hours' => cleg_payroll_report_line_value($line, 'Regular Hours', array('hours', 'regular')),
                'extra_hours' => cleg_payroll_report_line_value($line, 'Overtime Hours', array('hours', 'overtime')),
                'regular_pay' => cleg_payroll_report_line_value($line, 'Regular Pay', array('pay', 'regular_pay')),
                'extra_pay' => cleg_payroll_report_line_value($line, 'Overtime Pay', array('pay', 'overtime_pay')),
                'gross_pay' => $gross,
                'taxable_wages' => cleg_payroll_report_line_value($line, 'Taxable Wages', array(), $gross),
                'ss_employee' => cleg_payroll_report_line_value($line, 'Social Security Employee', array('deductions', 'social_security_employee')),
                'medicare_employee' => cleg_payroll_report_line_value($line, 'Medicare Employee', array('deductions', 'medicare_employee')),
                'sinot_employee' => cleg_payroll_report_line_value($line, 'SINOT Employee', array('deductions', 'sinot_employee')),
                'pr_income_tax' => cleg_payroll_report_line_value($line, 'PR Income Tax Withheld', array('deductions', 'pr_income_tax_withheld')),
                'contractor_withholding' => cleg_payroll_report_line_value($line, 'Contractor Withholding', array('deductions', 'contractor_withholding')),
                'fixed_deductions' => cleg_payroll_report_line_value($line, 'Fixed Deductions', array('deductions', 'fixed_deductions')),
                'manual_deduction' => cleg_payroll_report_line_value($line, 'Manual Deduction', array('deductions', 'manual_deduction')),
                'total_deductions' => cleg_payroll_report_line_value($line, 'Total Deductions', array(), max(0, $gross - $net)),
                'net_pay' => $net,
                'employer_ss' => cleg_payroll_report_line_value($line, 'Employer Social Security', array('employer', 'social_security')),
                'employer_medicare' => cleg_payroll_report_line_value($line, 'Employer Medicare', array('employer', 'medicare')),
                'employer_cost' => cleg_payroll_report_line_value($line, 'Total Employer Cost', array('employer', 'total_cost'), $gross + cleg_payroll_report_line_value($line, 'Employer Social Security', array('employer', 'social_security')) + cleg_payroll_report_line_value($line, 'Employer Medicare', array('employer', 'medicare'))),
                'vacation_accrued' => cleg_payroll_report_line_value($line, 'Vacation Accrued Hours', array('pto', 'vacation_accrued')),
                'sick_accrued' => cleg_payroll_report_line_value($line, 'Sick Accrued Hours', array('pto', 'sick_accrued')),
                'vacation_used' => cleg_payroll_report_line_value($line, 'Vacation Used Hours', array('leave', 'vacation_used_hours')),
                'sick_used' => cleg_payroll_report_line_value($line, 'Sick Used Hours', array('leave', 'sick_used_hours')),
                'vacation_balance' => cleg_payroll_report_line_value($line, 'Vacation Balance Hours', array('pto', 'vacation_balance_after')),
                'sick_balance' => cleg_payroll_report_line_value($line, 'Sick Balance Hours', array('pto', 'sick_balance_after')),
                'status' => cleg_payroll_field($line, 'Calculation Status', 'Ready to Pay'),
            );
        }

        return $normalized;
    }
}

if (!function_exists('cleg_payroll_report_filtered_lines')) {
    function cleg_payroll_report_filtered_lines($lines, $type) {
        $type = sanitize_key((string) $type);
        if ($type === 'employees') {
            return array_values(array_filter($lines, function ($line) {
                return ($line['worker_type'] ?? '') === 'Employee - Full Payroll';
            }));
        }
        if ($type === 'contractors') {
            return array_values(array_filter($lines, function ($line) {
                return ($line['worker_type'] ?? '') !== 'Employee - Full Payroll';
            }));
        }
        return $lines;
    }
}

if (!function_exists('cleg_payroll_report_lines_from_data')) {
    function cleg_payroll_report_lines_from_data($data, $start, $end) {
        $lines = array();
