            $gross = (float) ($row['gross_pay'] ?? $row['pay'] ?? 0);
            $net = (float) ($row['net_pay'] ?? 0);
            $lines[] = array(
                'employee_id' => sanitize_text_field((string) ($row['id'] ?? '')),
                'name' => (string) ($row['name'] ?? ''),
                'worker_type' => cleg_payroll_default_tax_type($row['tax_type'] ?? ''),
                'form_type' => (string) ($row['form_type'] ?? ''),
                'period_start' => $start,
                'period_end' => $end,
                'hours' => (float) ($row['hours'] ?? 0),
                'regular_hours' => (float) ($row['regular_hours'] ?? 0),
                'extra_hours' => (float) ($row['extra_hours'] ?? 0),
                'regular_pay' => (float) ($row['regular_pay'] ?? 0),
                'extra_pay' => (float) ($row['extra_pay'] ?? 0),
                'gross_pay' => $gross,
                'taxable_wages' => (float) ($row['taxable_wages'] ?? $gross),
                'ss_employee' => (float) ($row['social_security_employee'] ?? 0),
                'medicare_employee' => (float) ($row['medicare_employee'] ?? 0),
                'sinot_employee' => (float) ($row['sinot_employee'] ?? 0),
                'pr_income_tax' => (float) ($row['pr_income_tax_withheld'] ?? 0),
                'contractor_withholding' => (float) ($row['contractor_withholding'] ?? 0),
                'fixed_deductions' => (float) ($row['fixed_deductions'] ?? 0),
                'manual_deduction' => (float) ($row['manual_deduction'] ?? 0),
                'total_deductions' => (float) ($row['total_deductions'] ?? max(0, $gross - $net)),
                'net_pay' => $net,
                'employer_ss' => (float) ($row['employer_social_security'] ?? 0),
                'employer_medicare' => (float) ($row['employer_medicare'] ?? 0),
                'employer_cost' => (float) ($row['total_employer_cost'] ?? 0),
                'vacation_accrued' => (float) ($row['pto_vacation_accrued'] ?? 0),
                'sick_accrued' => (float) ($row['pto_sick_accrued'] ?? 0),
                'vacation_used' => (float) ($row['pto_vacation_used'] ?? 0),
                'sick_used' => (float) ($row['pto_sick_used'] ?? 0),
                'vacation_balance' => (float) ($row['pto_vacation_balance_after'] ?? 0),
                'sick_balance' => (float) ($row['pto_sick_balance_after'] ?? 0),
                'status' => (string) ($row['calculation_status'] ?? 'Ready to Pay'),
            );
        }
        return $lines;
    }
}

if (!function_exists('cleg_payroll_report_worker_filter')) {
    function cleg_payroll_report_worker_filter($lines, $worker_id) {
        $worker_id = sanitize_text_field((string) $worker_id);
        if ($worker_id === '' || $worker_id === 'all') {
            return $lines;
        }
        return array_values(array_filter($lines, function ($line) use ($worker_id) {
            return (string) ($line['employee_id'] ?? '') === $worker_id;
        }));
    }
}

if (!function_exists('cleg_payroll_report_deduction_items')) {
    function cleg_payroll_report_deduction_items($worker) {
        $items = array();
        $is_employee = ($worker['worker_type'] ?? '') === 'Employee - Full Payroll';
        if ($is_employee) {
            foreach (array('ss_employee' => 'SS', 'medicare_employee' => 'Medicare', 'sinot_employee' => 'SINOT', 'pr_income_tax' => 'Income Tax PR') as $field => $label) {
                if ((float) ($worker[$field] ?? 0) > 0) {
                    $items[] = $label . ' ' . cleg_payroll_money($worker[$field]);
                }
            }
        } elseif ((float) ($worker['contractor_withholding'] ?? 0) > 0) {
            $items[] = 'Retención 480 ' . cleg_payroll_money($worker['contractor_withholding']);
        }
        foreach (array('fixed_deductions' => 'Fijas', 'manual_deduction' => 'Manual') as $field => $label) {
            if ((float) ($worker[$field] ?? 0) > 0) {
                $items[] = $label . ' ' . cleg_payroll_money($worker[$field]);
            }
        }
        return $items;
    }
}

if (!function_exists('cleg_payroll_report_summary')) {
    function cleg_payroll_report_summary($lines) {
        $summary = array();
        foreach ((array) $lines as $line) {
            $key = $line['employee_id'] ?: md5($line['name']);
            if (!isset($summary[$key])) {
                $summary[$key] = array(
                    'employee_id' => $line['employee_id'],
                    'name' => $line['name'],
                    'worker_type' => $line['worker_type'],
                    'form_type' => $line['form_type'],
                    'periods' => array(),
                    'lines' => array(),
                );
                foreach (array('hours', 'regular_hours', 'extra_hours', 'regular_pay', 'extra_pay', 'gross_pay', 'taxable_wages', 'ss_employee', 'medicare_employee', 'sinot_employee', 'pr_income_tax', 'contractor_withholding', 'fixed_deductions', 'manual_deduction', 'total_deductions', 'net_pay', 'employer_ss', 'employer_medicare', 'employer_cost', 'vacation_accrued', 'sick_accrued', 'vacation_used', 'sick_used') as $field) {
                    $summary[$key][$field] = 0;
                }
                $summary[$key]['vacation_balance'] = 0;
                $summary[$key]['sick_balance'] = 0;
            }
            $period_key = ($line['period_start'] ?? '') . ' - ' . ($line['period_end'] ?? '');
            if (trim($period_key) !== '-') {
                $summary[$key]['periods'][$period_key] = true;
            }
            $summary[$key]['lines'][] = $line;
            foreach (array('hours', 'regular_hours', 'extra_hours', 'regular_pay', 'extra_pay', 'gross_pay', 'taxable_wages', 'ss_employee', 'medicare_employee', 'sinot_employee', 'pr_income_tax', 'contractor_withholding', 'fixed_deductions', 'manual_deduction', 'total_deductions', 'net_pay', 'employer_ss', 'employer_medicare', 'employer_cost', 'vacation_accrued', 'sick_accrued', 'vacation_used', 'sick_used') as $field) {
                $summary[$key][$field] += (float) ($line[$field] ?? 0);
            }
            // El saldo es un estado, no un acumulado: conservar el último cierre del trabajador.
            $summary[$key]['vacation_balance'] = (float) ($line['vacation_balance'] ?? $summary[$key]['vacation_balance']);
            $summary[$key]['sick_balance'] = (float) ($line['sick_balance'] ?? $summary[$key]['sick_balance']);
        }
        uasort($summary, function ($a, $b) {
            return strcasecmp($a['name'] ?? '', $b['name'] ?? '');
        });
        return $summary;
    }
}

if (!function_exists('cleg_payroll_report_totals')) {
    function cleg_payroll_report_totals($summary) {
        $totals = array('workers' => count($summary), 'periods' => 0);
        foreach (array('hours', 'gross_pay', 'net_pay', 'total_deductions', 'ss_employee', 'medicare_employee', 'sinot_employee', 'pr_income_tax', 'contractor_withholding', 'employer_ss', 'employer_medicare', 'employer_cost') as $field) {
            $totals[$field] = 0;
        }
        $periods = array();
        foreach ((array) $summary as $row) {
            foreach (($row['periods'] ?? array()) as $period => $_) {
                $periods[$period] = true;
            }
            foreach (array_keys($totals) as $field) {
                if ($field !== 'workers' && $field !== 'periods') {
                    $totals[$field] += (float) ($row[$field] ?? 0);
                }
            }
        }
        $totals['periods'] = count($periods);
        return $totals;
    }
}

if (!function_exists('cleg_payroll_report_csv_rows')) {
    function cleg_payroll_report_csv_rows($summary, $report) {
        $rows = array();
        if ($report === 'details') {
            $rows[] = array('Trabajador', 'Tipo', 'Periodo inicio', 'Periodo fin', 'Horas', 'Regular', 'Extra', 'Bruto', 'SS empleado', 'Medicare empleado', 'SINOT', 'Income Tax PR', 'Retencion contratista', 'Deducciones', 'Neto', 'SS patronal', 'Medicare patronal', 'Costo patronal');
            foreach ($summary as $worker) {
                foreach (($worker['lines'] ?? array()) as $line) {
                    $rows[] = array($line['name'], $line['worker_type'], $line['period_start'], $line['period_end'], round($line['hours'], 2), round($line['regular_hours'], 2), round($line['extra_hours'], 2), round($line['gross_pay'], 2), round($line['ss_employee'], 2), round($line['medicare_employee'], 2), round($line['sinot_employee'], 2), round($line['pr_income_tax'], 2), round($line['contractor_withholding'], 2), round($line['total_deductions'], 2), round($line['net_pay'], 2), round($line['employer_ss'], 2), round($line['employer_medicare'], 2), round($line['employer_cost'], 2));
                }
            }
            return $rows;
        }

        $rows[] = array('Trabajador', 'Tipo', 'Forma', 'Periodos', 'Horas', 'Regular', 'Extra', 'Bruto', 'SS empleado', 'Medicare empleado', 'SINOT', 'Income Tax PR', 'Retencion contratista', 'Deducciones', 'Neto pagado', 'SS patronal', 'Medicare patronal', 'Costo patronal', 'Vacaciones acum.', 'Enfermedad acum.');
        foreach ($summary as $worker) {
            if ($report === '480' && ($worker['worker_type'] ?? '') === 'Employee - Full Payroll') {
                continue;
            }
            if ($report === 'employees' && ($worker['worker_type'] ?? '') !== 'Employee - Full Payroll') {
                continue;
            }
            $rows[] = array($worker['name'], $worker['worker_type'], $worker['form_type'], count($worker['periods'] ?? array()), round($worker['hours'], 2), round($worker['regular_hours'], 2), round($worker['extra_hours'], 2), round($worker['gross_pay'], 2), round($worker['ss_employee'], 2), round($worker['medicare_employee'], 2), round($worker['sinot_employee'], 2), round($worker['pr_income_tax'], 2), round($worker['contractor_withholding'], 2), round($worker['total_deductions'], 2), round($worker['net_pay'], 2), round($worker['employer_ss'], 2), round($worker['employer_medicare'], 2), round($worker['employer_cost'], 2), round($worker['vacation_accrued'], 2), round($worker['sick_accrued'], 2));
        }
        return $rows;
    }
}

if (!function_exists('cleg_payroll_reports_export')) {
    function cleg_payroll_reports_export() {
        if (!cleg_payroll_can_view()) {
            wp_die('No autorizado.');
        }
        if (!isset($_GET['_wpnonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'cleg_payroll_reports_export')) {
            wp_die('Solicitud no valida.');
        }

        $mode = isset($_GET['report_mode']) ? sanitize_key(wp_unslash($_GET['report_mode'])) : 'month';
        $month = isset($_GET['report_month']) ? sanitize_text_field(wp_unslash($_GET['report_month'])) : '';
        $year = isset($_GET['report_year']) ? sanitize_text_field(wp_unslash($_GET['report_year'])) : '';
        $type = isset($_GET['worker_type']) ? sanitize_key(wp_unslash($_GET['worker_type'])) : 'all';
        $worker_id = isset($_GET['worker_id']) ? sanitize_text_field(wp_unslash($_GET['worker_id'])) : 'all';
        $report = isset($_GET['report_file']) ? sanitize_key(wp_unslash($_GET['report_file'])) : 'summary';
        list($start, $end, $period_value) = cleg_payroll_report_range($mode, $month, $year);
        $data = cleg_payroll_data($start, $end);
        if (!is_wp_error($data) && !empty($data)) {
            $lines = cleg_payroll_report_lines_from_data($data, $start, $end);
        } else {
            $lines = cleg_payroll_report_lines($start, $end, $period_lines);
        }
        if (is_wp_error($lines)) {
            wp_die(esc_html($lines->get_error_message()));
        }
        $summary = cleg_payroll_report_summary(cleg_payroll_report_worker_filter(cleg_payroll_report_filtered_lines($lines, $type), $worker_id));
        $rows = cleg_payroll_report_csv_rows($summary, $report);
        $filename = 'cleg-payroll-' . $report . '-' . $period_value . '.csv';

        nocache_headers();
        header('Content-Type: text/csv; charset=utf-8');
        header('Content-Disposition: attachment; filename="' . sanitize_file_name($filename) . '"');
        echo "\xEF\xBB\xBF";
        $out = fopen('php://output', 'w');
        foreach ($rows as $row) {
            fputcsv($out, $row);
        }
        fclose($out);
        exit;
    }
}
add_action('admin_post_cleg_payroll_reports_export', 'cleg_payroll_reports_export');

if (!function_exists('cleg_payroll_report_pdf_document')) {
    function cleg_payroll_report_pdf_document($content, $logo = '') {
        $objects = array();
        $objects[] = '<< /Type /Catalog /Pages 2 0 R >>';
        $objects[] = '<< /Type /Pages /Kids [3 0 R] /Count 1 >>';
        $xobject = $logo !== '' ? ' /XObject << /Logo 7 0 R >>' : '';
        $objects[] = '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R /F2 6 0 R >>' . $xobject . ' >> /Contents 4 0 R >>';
        $objects[] = '<< /Length ' . strlen($content) . " >>\nstream\n" . $content . "\nendstream";
        $objects[] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';
        $objects[] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>';
        if ($logo !== '') {
            $objects[] = '<< /Type /XObject /Subtype /Image /Width 180 /Height 180 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' . strlen($logo) . " >>\nstream\n" . $logo . "\nendstream";
        }
        $pdf = "%PDF-1.4\n";
        $offsets = array();
        foreach ($objects as $index => $object) {
            $offsets[] = strlen($pdf);
            $pdf .= ($index + 1) . " 0 obj\n" . $object . "\nendobj\n";
        }
        $xref = strlen($pdf);
        $pdf .= "xref\n0 " . (count($objects) + 1) . "\n0000000000 65535 f \n";
        foreach ($offsets as $offset) {
            $pdf .= sprintf("%010d 00000 n \n", $offset);
        }
        $pdf .= "trailer\n<< /Size " . (count($objects) + 1) . " /Root 1 0 R >>\nstartxref\n" . $xref . "\n%%EOF";
        return $pdf;
    }
}

if (!function_exists('cleg_payroll_report_pdf_text')) {
    function cleg_payroll_report_pdf_text($x, $y, $size, $text, $font = 'F1', $color = '0.04 0.09 0.17') {
