    }
}

if (!function_exists('cleg_payroll_report_pdf_summary')) {
    function cleg_payroll_report_pdf_summary($period_label, $summary, $report = 'summary') {
        $logo = function_exists('cleg_emp_payroll_pdf_logo_data') ? cleg_emp_payroll_pdf_logo_data() : '';
        $content = "q\n0.04 0.09 0.17 rg\n0 690 612 102 re\nf\nQ\n";
        if ($logo !== '') {
            $content .= "q\n72 0 0 72 500 706 cm\n/Logo Do\nQ\n";
        }
        $content .= cleg_payroll_report_pdf_text(42, 750, 19, 'C&L ENGINEERING GROUP LLC', 'F2', '1 1 1');
        $content .= cleg_payroll_report_pdf_text(42, 728, 10, 'Payroll', 'F1', '1 1 1');
        $content .= cleg_payroll_report_pdf_text(42, 668, 15, $period_label, 'F2');
        $content .= cleg_payroll_report_pdf_text(42, 650, 10, $report === 'details' ? 'Desglose de payroll y aportes' : 'Resumen contable de payroll', 'F1', '0.31 0.38 0.46');

        if ($report === 'details') {
            $content .= cleg_payroll_report_pdf_text(42, 622, 8, 'DETALLE POR TRABAJADOR — importes separados para revisión contable', 'F2', '0.04 0.09 0.17');
            $y = 600;
            $total_gross = 0;
            $total_deductions = 0;
            $total_net = 0;
            foreach (array_slice($summary, 0, 8) as $worker) {
                $gross = (float) ($worker['gross_pay'] ?? 0);
                $deductions = (float) ($worker['total_deductions'] ?? 0);
                $net = (float) ($worker['net_pay'] ?? 0);
                $total_gross += $gross;
                $total_deductions += $deductions;
                $total_net += $net;
                $content .= "0.95 0.96 0.98 rg\n42 " . ($y - 8) . " 528 48 re\nf\n";
                $content .= cleg_payroll_report_pdf_text(50, $y + 38, 9, cleg_payroll_report_pdf_truncate($worker['name'] ?? '', 30), 'F2');
                $content .= cleg_payroll_report_pdf_text(50, $y + 23, 7, 'Horas: ' . cleg_payroll_format_hours($worker['hours'] ?? 0) . ' | Regular: ' . cleg_payroll_format_hours($worker['regular_hours'] ?? 0) . ' | Extra: ' . cleg_payroll_format_hours($worker['extra_hours'] ?? 0));
                $content .= cleg_payroll_report_pdf_text(50, $y + 9, 7, 'Bruto: ' . cleg_payroll_money($gross) . ' | Neto: ' . cleg_payroll_money($net) . ' | Deducciones totales: ' . cleg_payroll_money($deductions));
                $deduction_items = cleg_payroll_report_deduction_items($worker);
                if ($deduction_items) {
                    $content .= cleg_payroll_report_pdf_text(50, $y - 5, 7, 'Deducciones: ' . implode(' | ', $deduction_items));
                }
                $benefit_items = array();
                foreach (array('employer_ss' => 'Aporte patronal SS', 'employer_medicare' => 'Medicare patronal') as $field => $label) {
                    if ((float) ($worker[$field] ?? 0) > 0) {
                        $benefit_items[] = $label . ': ' . cleg_payroll_money($worker[$field]);
                    }
                }
                foreach (array('vacation_accrued' => 'Vacaciones acum.', 'vacation_used' => 'Vacaciones usadas', 'vacation_balance' => 'Vacaciones saldo', 'sick_balance' => 'Enfermedad saldo') as $field => $label) {
                    if ((float) ($worker[$field] ?? 0) > 0) {
                        $benefit_items[] = $label . ': ' . cleg_payroll_format_hours($worker[$field]);
                    }
                }
                if ($benefit_items) {
                    $content .= cleg_payroll_report_pdf_text(50, $y - 33, 7, implode(' | ', $benefit_items), 'F1', '0.31 0.38 0.46');
                }
                $y -= 86;
            }
            $content .= "0.95 0.96 0.98 rg\n42 " . ($y + 8) . " 528 24 re\nf\n";
            $content .= cleg_payroll_report_pdf_text(50, $y + 16, 8, 'TOTALES', 'F2');
            $content .= cleg_payroll_report_pdf_text(300, $y + 16, 8, 'Bruto ' . cleg_payroll_money($total_gross), 'F2');
            $content .= cleg_payroll_report_pdf_text(410, $y + 16, 8, 'Deducciones ' . cleg_payroll_money($total_deductions), 'F2');
            $content .= cleg_payroll_report_pdf_text(510, $y + 16, 8, 'Neto ' . cleg_payroll_money($total_net), 'F2');
            return cleg_payroll_report_pdf_document($content, $logo);
        }

        $y = 620;
        $content .= "0.95 0.96 0.98 rg\n42 {$y} 528 24 re\n";
        $headers = array('Trabajador', 'Tipo', 'Horas', 'Bruto', 'Deducciones', 'Neto');
        $xs = array(48, 205, 315, 382, 452, 530);
        foreach ($headers as $i => $header) {
            $content .= cleg_payroll_report_pdf_text($xs[$i], $y + 8, 8, $header, 'F2', '0.31 0.38 0.46');
        }
        $y -= 25;
        $total_gross = 0;
        $total_deductions = 0;
        $total_net = 0;
        foreach (array_slice($summary, 0, 18) as $worker) {
            $total_gross += (float) ($worker['gross_pay'] ?? 0);
            $total_deductions += (float) ($worker['total_deductions'] ?? 0);
            $total_net += (float) ($worker['net_pay'] ?? 0);
            $content .= cleg_payroll_report_pdf_text(48, $y, 8, cleg_payroll_report_pdf_truncate($worker['name'] ?? '', 24));
            $content .= cleg_payroll_report_pdf_text(205, $y, 7, ($worker['worker_type'] ?? '') === 'Employee - Full Payroll' ? 'Empleado' : 'Contratista');
            $content .= cleg_payroll_report_pdf_text(315, $y, 8, cleg_payroll_format_hours($worker['hours'] ?? 0));
            $content .= cleg_payroll_report_pdf_text(382, $y, 8, cleg_payroll_money($worker['gross_pay'] ?? 0));
            $content .= cleg_payroll_report_pdf_text(452, $y, 8, cleg_payroll_money($worker['total_deductions'] ?? 0));
            $content .= cleg_payroll_report_pdf_text(530, $y, 8, cleg_payroll_money($worker['net_pay'] ?? 0));
            $content .= "0.84 0.86 0.89 RG\n42 " . ($y - 7) . " m\n570 " . ($y - 7) . " l\nS\n";
            $y -= 24;
        }
        $content .= "0.95 0.96 0.98 rg\n42 " . ($y - 5) . " 528 30 re\n";
        $content .= cleg_payroll_report_pdf_text(48, $y + 7, 8, 'TOTALES', 'F2');
        $content .= cleg_payroll_report_pdf_text(382, $y + 7, 8, cleg_payroll_money($total_gross), 'F2');
        $content .= cleg_payroll_report_pdf_text(452, $y + 7, 8, cleg_payroll_money($total_deductions), 'F2');
        $content .= cleg_payroll_report_pdf_text(530, $y + 7, 8, cleg_payroll_money($total_net), 'F2');
        return cleg_payroll_report_pdf_document($content, $logo);
    }
}

if (!function_exists('cleg_payroll_report_pdf_truncate')) {
    function cleg_payroll_report_pdf_truncate($value, $length = 24) {
        $value = (string) $value;
        return function_exists('mb_substr') ? mb_substr($value, 0, $length) : substr($value, 0, $length);
    }
}

if (!function_exists('cleg_payroll_reports_pdf_export')) {
    function cleg_payroll_reports_pdf_export() {
        if (!cleg_payroll_can_view()) {
            wp_die('No autorizado.');
        }
        if (!isset($_GET['_wpnonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'cleg_payroll_reports_pdf')) {
            wp_die('Solicitud no valida.');
        }
        $mode = isset($_GET['report_mode']) ? sanitize_key(wp_unslash($_GET['report_mode'])) : 'month';
        $month = isset($_GET['report_month']) ? sanitize_text_field(wp_unslash($_GET['report_month'])) : '';
        $year = isset($_GET['report_year']) ? sanitize_text_field(wp_unslash($_GET['report_year'])) : '';
        $type = isset($_GET['worker_type']) ? sanitize_key(wp_unslash($_GET['worker_type'])) : 'all';
        $worker_id = isset($_GET['worker_id']) ? sanitize_text_field(wp_unslash($_GET['worker_id'])) : 'all';
        $report = isset($_GET['report_file']) ? sanitize_key(wp_unslash($_GET['report_file'])) : 'summary_pdf';
        $base_report = preg_replace('/_pdf$/', '', $report);
        list($start, $end, $period_value, $period_label) = cleg_payroll_report_range($mode, $month, $year);
        $data = cleg_payroll_data($start, $end);
        $lines = (!is_wp_error($data) && !empty($data))
            ? cleg_payroll_report_lines_from_data($data, $start, $end)
            : cleg_payroll_report_lines($start, $end);
        if (is_wp_error($lines)) {
            wp_die(esc_html($lines->get_error_message()));
        }
        $filtered = cleg_payroll_report_worker_filter(cleg_payroll_report_filtered_lines($lines, $type), $worker_id);
        if ($base_report === '480') {
            $filtered = array_values(array_filter($filtered, function ($line) { return ($line['worker_type'] ?? '') !== 'Employee - Full Payroll'; }));
        } elseif ($base_report === 'employees') {
            $filtered = array_values(array_filter($filtered, function ($line) { return ($line['worker_type'] ?? '') === 'Employee - Full Payroll'; }));
        }
        $summary = cleg_payroll_report_summary($filtered);
        $pdf = cleg_payroll_report_pdf_summary($period_label, $summary, $base_report === 'details' ? 'details' : 'summary');
        $filename = 'cleg-payroll-' . $base_report . '-' . $period_value . '.pdf';
        nocache_headers();
        header('Content-Type: application/pdf');
        header('Content-Disposition: attachment; filename="' . sanitize_file_name($filename) . '"');
        header('Content-Length: ' . strlen($pdf));
        echo $pdf; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
        exit;
    }
}
add_action('admin_post_cleg_payroll_reports_pdf', 'cleg_payroll_reports_pdf_export');

if (!function_exists('cleg_payroll_closed_pdf_export')) {
    function cleg_payroll_closed_pdf_export() {
        if (!cleg_payroll_can_view()) {
            wp_die('No autorizado.');
        }
        if (!isset($_GET['_wpnonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'cleg_payroll_closed_pdf')) {
            wp_die('Solicitud no valida.');
        }
        list($start, $end) = cleg_payroll_period();
        $pending = cleg_payroll_pending_entries($start, $end);
        $closed = cleg_payroll_closed_entries($start, $end);
        $period_lines = cleg_payroll_period_lines($start, $end);
        if (!empty($pending) || (empty($closed) && empty($period_lines))) {
            wp_die('El payroll debe estar cerrado y sin horas pendientes antes de exportar el PDF.');
        }
        $data = cleg_payroll_data($start, $end);
        $lines = (!is_wp_error($data) && !empty($data))
            ? cleg_payroll_report_lines_from_data($data, $start, $end)
            : cleg_payroll_report_lines($start, $end, $period_lines);
        if (is_wp_error($lines)) {
            wp_die(esc_html($lines->get_error_message()));
        }
        $period_label = 'Semana cerrada ' . wp_date('m/d/Y', strtotime($start)) . ' - ' . wp_date('m/d/Y', strtotime($end));
        $pdf = cleg_payroll_report_pdf_summary($period_label, cleg_payroll_report_summary($lines), 'summary');
        $filename = 'cleg-payroll-cerrado-' . sanitize_file_name($end) . '.pdf';
        nocache_headers();
        header('Content-Type: application/pdf');
        header('Content-Disposition: attachment; filename="' . sanitize_file_name($filename) . '"');
        header('Content-Length: ' . strlen($pdf));
        echo $pdf; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
        exit;
    }
}
add_action('admin_post_cleg_payroll_closed_pdf', 'cleg_payroll_closed_pdf_export');

if (!function_exists('cleg_payroll_report_table')) {
    function cleg_payroll_report_table($summary) {
        if (empty($summary)) {
            return '<div class="cleg-payroll-report-empty"><h2>Sin cierres en este periodo</h2><p>Cuando Payroll se cierre, esta pantalla mostrara los totales reales para contabilidad.</p></div>';
        }
        $html = '<div class="cleg-payroll-report-table"><table><thead><tr><th>Trabajador</th><th>Horas</th><th>Bruto</th><th>Deducciones</th><th>Neto</th><th>Aportes patronales</th><th>Detalle</th></tr></thead><tbody>';
        foreach ($summary as $worker) {
            $employer = (float) ($worker['employer_ss'] ?? 0) + (float) ($worker['employer_medicare'] ?? 0);
            $html .= '<tr><td class="cleg-report-worker"><strong>' . esc_html($worker['name']) . ' <small>(' . esc_html(cleg_payroll_employee_display_type($worker['worker_type'])) . ')</small></strong><small>' . esc_html($worker['form_type']) . '</small></td>'
                . '<td class="cleg-report-hours"><strong>' . esc_html(cleg_payroll_format_hours($worker['hours'])) . '</strong><small>Reg ' . esc_html(cleg_payroll_format_hours($worker['regular_hours'])) . ' / Extra ' . esc_html(cleg_payroll_format_hours($worker['extra_hours'])) . '</small></td>'
                . '<td class="cleg-report-money">' . esc_html(cleg_payroll_money($worker['gross_pay'])) . '</td>'
                . '<td class="cleg-report-deductions"><strong>' . esc_html(cleg_payroll_money($worker['total_deductions'])) . '</strong><small>' . esc_html(implode(' · ', cleg_payroll_report_deduction_items($worker))) . '</small></td>'
                . '<td class="cleg-report-net"><strong>' . esc_html(cleg_payroll_money($worker['net_pay'])) . '</strong></td>'
                . '<td class="cleg-report-employer"><strong>' . esc_html(cleg_payroll_money($employer)) . '</strong><small>SS patronal ' . esc_html(cleg_payroll_money($worker['employer_ss'])) . ' · Medicare patronal ' . esc_html(cleg_payroll_money($worker['employer_medicare'])) . '</small></td>'
                . '<td class="cleg-report-detail"><details><summary>Desglose</summary><div class="cleg-payroll-report-breakdown">'
                . '<p><b>Periodos:</b> ' . esc_html((string) count($worker['periods'] ?? array())) . '</p>'
                . '<p><b>Regular pay:</b> ' . esc_html(cleg_payroll_money($worker['regular_pay'])) . ' · <b>Overtime pay:</b> ' . esc_html(cleg_payroll_money($worker['extra_pay'])) . '</p>'
                . '<p><b>Vacaciones acum.:</b> ' . esc_html(cleg_payroll_format_hours($worker['vacation_accrued'])) . ' · <b>Enfermedad acum.:</b> ' . esc_html(cleg_payroll_format_hours($worker['sick_accrued'])) . '</p>'
                . '</div></details></td></tr>';
        }
        return $html . '</tbody></table></div>';
    }
}

if (!function_exists('cleg_admin_payroll_reports_shortcode')) {
    function cleg_admin_payroll_reports_shortcode() {
