        $year = isset($_GET['report_year']) ? sanitize_text_field(wp_unslash($_GET['report_year'])) : wp_date('Y', null, cleg_payroll_timezone());
        $type = isset($_GET['worker_type']) ? sanitize_key(wp_unslash($_GET['worker_type'])) : 'all';
