body .cleg-payroll .cleg-payroll-report-table table{width:100%;min-width:1180px;border-collapse:separate;border-spacing:0;font-variant-numeric:tabular-nums}
body .cleg-payroll .cleg-payroll-report-table th,body .cleg-payroll .cleg-payroll-report-table td{padding:13px 14px;border-bottom:1px solid rgba(6,24,45,.08);vertical-align:middle;text-align:left}
body .cleg-payroll .cleg-payroll-report-table tbody tr:nth-child(even){background:#fbfdff}
body .cleg-payroll .cleg-payroll-report-table tbody tr:hover{background:#f6f9fc}
body .cleg-payroll .cleg-payroll-report-table th{position:sticky;top:0;z-index:1;background:#f7f9fc;color:#516579;font-size:11px;font-weight:1000;text-transform:uppercase;letter-spacing:.05em}
body .cleg-payroll .cleg-payroll-report-table td{color:#132238;font-size:14px;line-height:1.25}
body .cleg-payroll .cleg-payroll-report-table td strong,body .cleg-payroll .cleg-payroll-report-table td small{display:block}
body .cleg-payroll .cleg-payroll-report-table td small{margin-top:4px;color:#64748b;font-size:11px;font-weight:750;line-height:1.35}
body .cleg-payroll .cleg-report-type{max-width:170px;color:#26384d;font-weight:800}
body .cleg-payroll .cleg-report-money,body .cleg-payroll .cleg-report-net,body .cleg-payroll .cleg-report-deductions,body .cleg-payroll .cleg-report-employer{white-space:nowrap}
body .cleg-payroll .cleg-payroll-report-table details summary{display:inline-flex;align-items:center;justify-content:center;min-height:34px;border:1px solid rgba(6,24,45,.14);border-radius:999px;background:#fff;color:#06182d;padding:7px 12px;cursor:pointer;font-size:12px;font-weight:950;text-decoration:none;box-shadow:0 8px 20px rgba(6,24,45,.07)}
body .cleg-payroll .cleg-payroll-report-table details summary:hover{border-color:rgba(199,80,0,.38);background:#fff7f0}
body .cleg-payroll .cleg-payroll-report-breakdown{min-width:260px;margin-top:8px;border-radius:14px;background:#f7f9fc;padding:12px;color:#06182d}
body .cleg-payroll .cleg-payroll-report-breakdown p{margin:0 0 7px;font-size:13px;line-height:1.35}
body .cleg-payroll .cleg-payroll-report-empty{padding:26px;text-align:center;box-sizing:border-box}
body .cleg-payroll .cleg-payroll-report-empty h2{margin:0 0 8px;color:#06182d}
body .cleg-payroll .cleg-payroll-report-empty p{margin:0;color:#516579;font-weight:750}
@media(max-width:1200px){body .cleg-payroll .cleg-payroll-report-kpis{grid-template-columns:repeat(3,1fr)}body .cleg-payroll .cleg-payroll-report-hero{grid-template-columns:1fr}}
@media(max-width:760px){body .cleg-payroll .cleg-payroll-report-filters{grid-template-columns:1fr}body .cleg-payroll .cleg-payroll-report-kpis{grid-template-columns:1fr}body .cleg-payroll .cleg-payroll-report-actions{grid-template-columns:1fr}}
</style>
HTML;
    }
}

if (!function_exists('cleg_admin_payroll_shortcode')) {
    function cleg_admin_payroll_shortcode() {
        if (!cleg_payroll_allowed()) {
            return '<section class="cleg-payroll"><div class="cleg-payroll-empty"><h2>No autorizado</h2><p>Esta pantalla es solo para administradores.</p></div>' . cleg_payroll_styles() . '</section>';
        }

        list($start, $end) = cleg_payroll_period();
        $data = cleg_payroll_data($start, $end);
        $pending_entries = cleg_payroll_pending_entries($start, $end);
        $closed_entries = cleg_payroll_closed_entries($start, $end);
        $period_lines = cleg_payroll_period_lines($start, $end);

        if (is_wp_error($data)) {
            return '<section class="cleg-payroll"><div class="cleg-payroll-empty"><h2>Error</h2><p>' . esc_html($data->get_error_message()) . '</p></div>' . cleg_payroll_styles() . '</section>';
        }

        if (is_wp_error($pending_entries)) {
            return '<section class="cleg-payroll"><div class="cleg-payroll-empty"><h2>Error</h2><p>' . esc_html($pending_entries->get_error_message()) . '</p></div>' . cleg_payroll_styles() . '</section>';
        }

        if (is_wp_error($closed_entries)) {
            return '<section class="cleg-payroll"><div class="cleg-payroll-empty"><h2>Error</h2><p>' . esc_html($closed_entries->get_error_message()) . '</p></div>' . cleg_payroll_styles() . '</section>';
        }

        if (is_wp_error($period_lines)) {
            return '<section class="cleg-payroll"><div class="cleg-payroll-empty"><h2>Error</h2><p>' . esc_html($period_lines->get_error_message()) . '</p></div>' . cleg_payroll_styles() . '</section>';
        }

        $total_pay = 0;
        $total_hours = 0;
        $total_regular_hours = 0;
        $total_extra_hours = 0;
        foreach ($data as $row) {
            $total_pay += round((float) ($row['net_pay'] ?? $row['pay']), 2);
            $total_hours += (float) $row['hours'];
            $total_regular_hours += (float) ($row['regular_hours'] ?? 0);
            $total_extra_hours += (float) ($row['extra_hours'] ?? 0);
        }

        $closed_pdf_url = wp_nonce_url(add_query_arg(array(
            'action' => 'cleg_payroll_closed_pdf',
            'payroll_week' => $end,
            'cleg_pdf_cache' => gmdate('YmdHis'),
        ), admin_url('admin-post.php')), 'cleg_payroll_closed_pdf');
        $close_url = wp_nonce_url(add_query_arg(array(
            'action' => 'cleg_payroll_close',
            'payroll_week' => $end,
        ), admin_url('admin-post.php')), 'cleg_payroll_close');
        $week_options = cleg_payroll_week_options($end);
        $has_pending_entries = !empty($pending_entries);
        $has_closed_entries = !empty($closed_entries);
        $has_payroll_lines = !empty($period_lines);
        $has_closed_payroll = $has_closed_entries || $has_payroll_lines;
        $is_work_week = cleg_payroll_is_work_week($end);
        $can_edit_payroll = $is_work_week && !$has_closed_payroll;
        $can_rollback_payroll = $is_work_week && $has_closed_payroll && !$has_pending_entries && cleg_payroll_can_manage();

        ob_start();
        ?>
        <section class="cleg-payroll cleg-admin-ui">
            <main class="cleg-payroll-main cleg-payroll-shell cleg-admin-shell">
                <?php
                if (function_exists('cleg_admin_page_header')) {
                    echo cleg_admin_page_header('Payroll', '', array('eyebrow' => 'C&L Payroll')); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
                } else {
                    echo '<header class="cleg-admin-header"><div class="cleg-command-copy"><p>C&L RRHH</p><h1>Payroll</h1></div></header>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
                }

                if (function_exists('cleg_admin_nav')) {
                    echo cleg_admin_nav('payroll'); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
                } elseif (function_exists('cleg_rrhh_nav')) {
                    echo cleg_rrhh_nav('payroll'); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
                } else {
                    echo '<nav class="cleg-admin-nav"><a href="' . esc_url(home_url('/panel/')) . '">Panel</a><a href="' . esc_url(home_url('/admin-rrhh/')) . '">Control RRHH</a><a href="' . esc_url(home_url('/empleados/')) . '">Expedientes</a></nav>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
                }
                ?>

                <form class="cleg-payroll-filters" method="get">
                    <label>Semana cerrada
                        <select name="payroll_week" onchange="this.form.submit()">
                            <?php foreach ($week_options as $week_end => $week_label) : ?>
                                <option value="<?php echo esc_attr($week_end); ?>" <?php selected($end, $week_end); ?>><?php echo esc_html($week_label); ?></option>
                            <?php endforeach; ?>
                        </select>
                    </label>
                    <?php if ($has_pending_entries) : ?>
                        <span class="cleg-payroll-disabled">Export bloqueado</span>
                    <?php elseif (!$has_closed_payroll && $is_work_week) : ?>
                        <a href="<?php echo esc_url($close_url); ?>">Cerrar payroll</a>
                    <?php else : ?>
                        <a download href="<?php echo esc_url($closed_pdf_url); ?>">Descargar PDF</a>
                    <?php endif; ?>
                </form>

                <?php if ($has_pending_entries) : ?>
                    <div class="cleg-payroll-blocked">
                        <strong>Semana pendiente de revisar.</strong>
                        <?php echo esc_html(count($pending_entries)); ?> hora(s) pendientes.
                    </div>
                <?php endif; ?>

                <?php if ($has_closed_payroll && !$has_pending_entries) : ?>
                    <div class="cleg-payroll-notice">Semana cerrada en payroll. Solo consulta y exportacion; no se permiten ajustes.</div>
                <?php endif; ?>

                <?php if (isset($_GET['payroll_saved'])) : ?>
                    <div class="cleg-payroll-notice">Payroll guardado.</div>
                <?php endif; ?>

                <?php if (isset($_GET['payroll_locked'])) : ?>
                    <div class="cleg-payroll-blocked"><strong>Payroll cerrado.</strong> No se guardaron cambios porque esta semana ya esta bloqueada.</div>
                <?php endif; ?>

                <?php if (isset($_GET['payroll_closed'])) : ?>
                    <div class="cleg-payroll-notice">Payroll cerrado. Ya puedes exportar el PDF cerrado.</div>
                <?php endif; ?>

                <?php if (isset($_GET['payroll_rollback'])) : ?>
                    <div class="cleg-payroll-blocked"><strong>Rollback aplicado.</strong> Se reabrieron <?php echo esc_html((string) absint($_GET['rollback_entries'] ?? 0)); ?> registro(s) de tiempo y se eliminaron <?php echo esc_html((string) absint($_GET['rollback_lines'] ?? 0)); ?> linea(s) de payroll.</div>
                <?php endif; ?>

                <div class="cleg-payroll-metrics">
                    <span><strong>$<?php echo esc_html(number_format($total_pay, 2)); ?></strong><small>Total a pagar</small></span>
                    <span class="cleg-payroll-hours-card">
                        <strong><?php echo esc_html(cleg_payroll_format_hours($total_hours)); ?></strong>
                        <small>Horas calculadas</small>
                        <em><b>Reg.</b> <?php echo esc_html(cleg_payroll_format_hours($total_regular_hours)); ?> <b>Extra</b> <?php echo esc_html(cleg_payroll_format_hours($total_extra_hours)); ?></em>
                    </span>
                    <span><strong><?php echo esc_html(count($data)); ?></strong><small>Trabajadores</small></span>
                </div>

                <?php if ($can_rollback_payroll) : ?>
                    <details class="cleg-payroll-rollback">
                        <summary>
                            <span><strong>Rollback de la semana anterior</strong><small>Herramienta comprimida de recuperacion. Abrir para ver acciones y confirmaciones.</small></span>
                            <b>Ver contenido</b>
                        </summary>
                        <form class="cleg-payroll-rollback-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                            <?php wp_nonce_field('cleg_payroll_rollback_previous_week', 'cleg_payroll_rollback_nonce'); ?>
                            <input type="hidden" name="action" value="cleg_payroll_rollback_previous_week">
                            <input type="hidden" name="payroll_week" value="<?php echo esc_attr($end); ?>">
                            <div class="cleg-payroll-rollback-copy">
                                <strong>Contenido del rollback</strong>
                                <small>Revierte el cierre de esta semana, reabre las horas como Approved y elimina las lineas calculadas del periodo.</small>
                            </div>
                            <label class="cleg-payroll-rollback-check">
                                <input type="checkbox" name="cleg_payroll_rollback_confirm" value="1" required>
                                Confirmo que quiero revertir solo esta semana cerrada.
                            </label>
                            <label>
                                Escribe REVERTIR
                                <input type="text" name="cleg_payroll_rollback_phrase" value="" pattern="REVERTIR" autocomplete="off" required>
                            </label>
                            <button type="submit">Revertir payroll</button>
                        </form>
                    </details>
                <?php endif; ?>

                <form method="post" enctype="multipart/form-data">
                    <?php wp_nonce_field('cleg_payroll_save_rates', 'cleg_payroll_nonce'); ?>
                    <input type="hidden" name="cleg_payroll_action" value="save_rates">
                    <input type="hidden" name="payroll_week" value="<?php echo esc_attr($end); ?>">
                    <div class="cleg-payroll-table"><table>
                        <thead><tr><th>Trabajador</th><th>Horas</th><th class="regular-hours-col">H regular</th><th class="extra-hours-col">H extra</th><th>Bruto</th><th>Ajustes</th><th>Deduccion</th><th>Neto</th></tr></thead>
                        <tbody>
                        <?php foreach ($data as $row) : ?>
                            <?php $needs_review = ($row['calculation_status'] ?? '') === 'Needs Review'; ?>
                            <?php
                            $is_full_payroll_employee = cleg_payroll_default_tax_type($row['tax_type']) === 'Employee - Full Payroll';
                            $deduction_total = isset($row['total_deductions']) ? (float) $row['total_deductions'] : max(0, (float) ($row['gross_pay'] ?? 0) - (float) ($row['net_pay'] ?? 0));
                            $manual_extra_amount = (float) ($row['manual_extra'] ?? 0);
                            $manual_deduction_amount = (float) ($row['manual_deduction'] ?? 0);
                            $period_pr_amount = (float) ($row['period_pr_withholding'] ?? 0);
                            $calculated_pr_amount = (float) ($row['pr_income_tax_withheld'] ?? 0);
                            $has_manual_adjustment = $manual_extra_amount > 0 || $manual_deduction_amount > 0 || $period_pr_amount > 0 || !empty($row['manual_extra_note']) || !empty($row['manual_deduction_note']) || !empty($row['period_pr_note']);
                            $has_leave_period = !empty($row['leave_rows']) || (float) ($row['leave_requested_hours'] ?? 0) > 0;
                            $site_summary = array();
                            foreach (($row['entry_rows'] ?? array()) as $entry_row) {
                                $site_name = isset($entry_row['job_site']) && $entry_row['job_site'] !== '' ? $entry_row['job_site'] : 'Sin sitio';
                                if (!isset($site_summary[$site_name])) {
                                    $site_summary[$site_name] = array(
                                        'hours' => 0,
                                        'regular_hours' => 0,
                                        'extra_hours' => 0,
                                        'entries' => 0,
                                    );
                                }
                                $site_summary[$site_name]['hours'] += (float) ($entry_row['hours'] ?? 0);
                                $site_summary[$site_name]['regular_hours'] += (float) ($entry_row['regular_hours'] ?? 0);
                                $site_summary[$site_name]['extra_hours'] += (float) ($entry_row['extra_hours'] ?? 0);
                                $site_summary[$site_name]['entries']++;
                            }
                            ?>
                            <tr class="<?php echo esc_attr($needs_review ? 'needs-review' : 'ready-pay'); ?>">
                                <td class="worker-cell">
                                    <strong><?php echo esc_html($row['name']); ?></strong>
                                    <small><?php echo esc_html(cleg_payroll_employee_display_type($row['tax_type'])); ?> · <?php echo esc_html(cleg_payroll_label($row['period'])); ?> · $<?php echo esc_html(number_format($row['amount'], 2)); ?></small>
                                    <?php if ($needs_review && !empty($row['review_notes'])) : ?>
                                        <small class="review-note" title="<?php echo esc_attr($row['review_notes']); ?>">Revisar calculo</small>
                                    <?php endif; ?>
                                    <?php if ($has_leave_period) : ?>
                                        <details class="leave-period-detail">
                                            <summary>Ausencias del periodo</summary>
                                            <div>
                                                <p><span>Solicitadas</span><strong><?php echo esc_html(cleg_payroll_format_hours((float) ($row['leave_requested_hours'] ?? 0))); ?></strong></p>
                                                <p><span>Enfermedad pagada</span><strong><?php echo esc_html(cleg_payroll_format_hours((float) ($row['leave_sick_paid_hours'] ?? 0))); ?></strong></p>
                                                <p><span>Vacaciones pagadas</span><strong><?php echo esc_html(cleg_payroll_format_hours((float) ($row['leave_vacation_paid_hours'] ?? 0))); ?></strong></p>
                                                <p><span>No pagadas</span><strong><?php echo esc_html(cleg_payroll_format_hours((float) ($row['leave_unpaid_hours'] ?? 0))); ?></strong></p>
                                                <p><span>Pago por licencia</span><strong>$<?php echo esc_html(number_format((float) ($row['leave_paid_amount'] ?? 0), 2)); ?></strong></p>
                                                <?php foreach (($row['leave_rows'] ?? array()) as $leave_row) : ?>
                                                    <small><?php echo esc_html(($leave_row['start'] ?? '') . ' - ' . ($leave_row['end'] ?? '') . ': ' . ($leave_row['type'] ?? '') . ' · afecta pago: ' . (!empty($leave_row['affects_pay']) ? 'si' : 'no')); ?></small>
                                                <?php endforeach; ?>
                                                <?php if ($can_edit_payroll && (float) ($row['leave_unpaid_hours'] ?? 0) > 0) : ?>
                                                    <label class="leave-vacation-toggle">
                                                        <input type="checkbox" name="leave_use_vacation_overflow[<?php echo esc_attr($row['id']); ?>]" value="1" <?php checked(!empty($row['leave_use_vacation_overflow'])); ?>>
                                                        Usar vacaciones para cubrir sobrante
                                                    </label>
                                                    <small>Marca esta opcion y pulsa Guardar ajustes antes de cerrar payroll.</small>
                                                <?php endif; ?>
                                            </div>
                                        </details>
                                    <?php endif; ?>
                                    <input type="hidden" name="payroll_period[<?php echo esc_attr($row['id']); ?>]" value="<?php echo esc_attr($row['period']); ?>">
                                    <input type="hidden" name="payroll_amount[<?php echo esc_attr($row['id']); ?>]" value="<?php echo esc_attr(number_format($row['amount'], 2, '.', '')); ?>">
                                </td>
                                <td class="hours-cell">
                                    <details>
                                        <summary title="Abrir detalle de horas por sitio y registros"><strong><?php echo esc_html(cleg_payroll_format_hours($row['hours'])); ?></strong><small><?php echo esc_html((string) $row['days_count']); ?> dia(s) · Ver detalle</small></summary>
                                        <div class="hours-detail">
                                            <?php foreach ($site_summary as $site_name => $site_row) : ?>
                                                <p><span><?php echo esc_html($site_name); ?></span><strong><?php echo esc_html(cleg_payroll_format_hours($site_row['hours'])); ?></strong><small><?php echo esc_html((string) $site_row['entries']); ?> registro(s)</small></p>
                                            <?php endforeach; ?>
                                            <div class="entry-detail-table">
                                                <?php foreach (($row['entry_rows'] ?? array()) as $entry_row) : ?>
                                                    <?php
                                                    $weekday_letters = array(
                                                        'Lunes' => 'M',
                                                        'Martes' => 'T',
                                                        'Miercoles' => 'W',
                                                        'Miércoles' => 'W',
                                                        'Jueves' => 'T',
                                                        'Viernes' => 'F',
                                                        'Sabado' => 'S',
                                                        'Sábado' => 'S',
                                                        'Domingo' => 'S',
                                                    );
                                                    $weekday_letter = $weekday_letters[$entry_row['weekday'] ?? ''] ?? '';
                                                    ?>
                                                    <p>
                                                        <span><?php echo esc_html(trim($weekday_letter . ' ' . ($entry_row['date'] ?? '')) . ' · ' . ($entry_row['job_site'] ?? '')); ?></span>
                                                        <small><?php echo esc_html(($entry_row['clock_in'] ?? '') . ' - ' . ($entry_row['clock_out'] ?? '')); ?></small>
                                                        <strong><?php echo esc_html(cleg_payroll_format_hours((float) ($entry_row['hours'] ?? 0))); ?></strong>
                                                    </p>
                                                <?php endforeach; ?>
                                            </div>
                                        </div>
                                    </details>
                                </td>
                                <td class="regular-hours-col"><?php echo esc_html(cleg_payroll_format_hours($row['regular_hours'])); ?></td>
                                <td class="extra-hours-col"><?php echo esc_html(cleg_payroll_format_hours($row['extra_hours'])); ?></td>
                                <td class="gross-cell">
                                    <strong>$<?php echo esc_html(number_format($row['gross_pay'], 2)); ?></strong>
                                    <?php if ((float) ($row['leave_sick_paid_amount'] ?? 0) > 0) : ?>
                                        <small class="gross-note">Enfermedad pagada $<?php echo esc_html(number_format((float) ($row['leave_sick_paid_amount'] ?? 0), 2)); ?></small>
                                    <?php endif; ?>
                                    <?php if ((float) ($row['leave_vacation_paid_amount'] ?? 0) > 0) : ?>
                                        <small class="gross-note">Vacaciones pagadas $<?php echo esc_html(number_format((float) ($row['leave_vacation_paid_amount'] ?? 0), 2)); ?></small>
                                    <?php endif; ?>
                                    <?php if ($manual_extra_amount > 0) : ?>
                                        <small class="gross-note">Incluye extra +$<?php echo esc_html(number_format($manual_extra_amount, 2)); ?></small>
                                    <?php endif; ?>
                                </td>
                                <td class="adjustments-cell <?php echo esc_attr($has_manual_adjustment ? 'has-adjustment' : ''); ?>">
                                    <?php if ($manual_extra_amount > 0) : ?>
                                        <span class="adjustment-badge adjustment-plus" title="<?php echo esc_attr($row['manual_extra_note'] ?? ''); ?>">+ Extra $<?php echo esc_html(number_format($manual_extra_amount, 2)); ?></span>
                                    <?php endif; ?>
                                    <?php if ($manual_deduction_amount > 0) : ?>
                                        <span class="adjustment-badge adjustment-minus" title="<?php echo esc_attr($row['manual_deduction_note'] ?? ''); ?>">- Deduccion $<?php echo esc_html(number_format($manual_deduction_amount, 2)); ?></span>
                                    <?php endif; ?>
                                    <?php if ($is_full_payroll_employee && $calculated_pr_amount > 0) : ?>
                                        <span class="adjustment-badge adjustment-tax" title="<?php echo esc_attr($row['period_pr_note'] ?? 'Calculado automaticamente desde tax profile.'); ?>">PR tax $<?php echo esc_html(number_format($calculated_pr_amount, 2)); ?></span>
                                    <?php endif; ?>
                                    <details class="adjustment-details">
                                        <summary><?php echo $has_manual_adjustment ? esc_html('Editar ajustes') : esc_html('+ ajuste'); ?></summary>
                                        <?php if ($is_full_payroll_employee) : ?>
                                            <label>Income Tax PR calculado
                                                <input class="money-input" type="number" step="0.01" min="0" value="<?php echo esc_attr(number_format($calculated_pr_amount, 2, '.', '')); ?>" readonly>
                                            </label>
                                            <input class="note-input" type="text" value="<?php echo esc_attr($row['period_pr_note'] !== '' ? $row['period_pr_note'] : 'Automatico por tax profile'); ?>" readonly title="<?php echo esc_attr($row['period_pr_note'] ?? 'Automatico por tax profile'); ?>">
                                        <?php endif; ?>
                                        <label>Pago extra
                                            <input class="money-input" type="number" step="0.01" min="0" name="manual_extra[<?php echo esc_attr($row['id']); ?>]" value="<?php echo esc_attr(number_format($manual_extra_amount, 2, '.', '')); ?>" placeholder="0.00" <?php disabled(!$can_edit_payroll); ?>>
                                        </label>
                                        <input class="note-input" type="text" name="manual_extra_note[<?php echo esc_attr($row['id']); ?>]" value="<?php echo esc_attr($row['manual_extra_note'] ?? ''); ?>" placeholder="Nota de extra" title="<?php echo esc_attr($row['manual_extra_note'] ?? ''); ?>" <?php disabled(!$can_edit_payroll); ?>>
                                        <label>Deduccion al neto
                                            <input class="money-input" type="number" step="0.01" min="0" name="manual_deduction[<?php echo esc_attr($row['id']); ?>]" value="<?php echo esc_attr(number_format($manual_deduction_amount, 2, '.', '')); ?>" placeholder="0.00" <?php disabled(!$can_edit_payroll); ?>>
                                        </label>
                                        <input class="note-input" type="text" name="manual_deduction_note[<?php echo esc_attr($row['id']); ?>]" value="<?php echo esc_attr($row['manual_deduction_note'] ?? ''); ?>" placeholder="Nota de deduccion" title="<?php echo esc_attr($row['manual_deduction_note'] ?? ''); ?>" <?php disabled(!$can_edit_payroll); ?>>
                                        <?php if (!empty($row['manual_extra_note'])) : ?>
                                            <small class="floating-note" title="<?php echo esc_attr($row['manual_extra_note']); ?>">Nota extra guardada</small>
                                        <?php endif; ?>
                                        <?php if (!empty($row['manual_deduction_note'])) : ?>
                                            <small class="floating-note" title="<?php echo esc_attr($row['manual_deduction_note']); ?>">Nota deduccion guardada</small>
                                        <?php endif; ?>
                                        <?php if (!empty($row['period_pr_note'])) : ?>
                                            <small class="floating-note" title="<?php echo esc_attr($row['period_pr_note']); ?>">Nota PR guardada</small>
                                        <?php endif; ?>
                                    </details>
                                </td>
                                <td class="<?php echo esc_attr(($manual_deduction_amount > 0 || $calculated_pr_amount > 0 || (float) ($row['contractor_withholding'] ?? 0) > 0) ? 'deduction-cell has-deduction' : 'deduction-cell'); ?>">
                                    <strong>$<?php echo esc_html(number_format($deduction_total, 2)); ?></strong>
                                    <?php if ($is_full_payroll_employee) : ?>
                                        <small>SS $<?php echo esc_html(number_format((float) ($row['social_security_employee'] ?? 0), 2)); ?> · Med $<?php echo esc_html(number_format((float) ($row['medicare_employee'] ?? 0), 2)); ?></small>
                                        <small>SINOT $<?php echo esc_html(number_format((float) ($row['sinot_employee'] ?? 0), 2)); ?> · PR $<?php echo esc_html(number_format((float) ($row['pr_income_tax_withheld'] ?? 0), 2)); ?></small>
                                    <?php else : ?>
                                        <small>Retencion contratista $<?php echo esc_html(number_format((float) ($row['contractor_withholding'] ?? 0), 2)); ?></small>
                                    <?php endif; ?>
                                    <?php if ($manual_deduction_amount > 0) : ?><small>Manual $<?php echo esc_html(number_format($manual_deduction_amount, 2)); ?></small><?php endif; ?>
                                </td>
                                <td><strong>$<?php echo esc_html(number_format($row['net_pay'], 2)); ?></strong><small>Neto a pagar</small></td>
                            </tr>
                        <?php endforeach; ?>
                        </tbody>
                    </table></div>
                    <?php if ($can_edit_payroll) : ?>
                        <button class="cleg-payroll-save" type="submit">Guardar ajustes</button>
                    <?php endif; ?>
                </form>
            </main>
            <?php echo cleg_payroll_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            <?php echo function_exists('cleg_admin_desktop_menu_lock_styles') ? cleg_admin_desktop_menu_lock_styles() : ''; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
        </section>
        <?php
        return ob_get_clean();
    }
}

if (!function_exists('cleg_payroll_close')) {
    function cleg_payroll_close() {
        if (!cleg_payroll_can_manage()) {
            wp_die('No autorizado.');
        }

        if (!isset($_GET['_wpnonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'cleg_payroll_close')) {
            wp_die('Solicitud no valida.');
        }

        list($start, $end) = cleg_payroll_period();
        $pending_entries = cleg_payroll_pending_entries($start, $end);

        if (is_wp_error($pending_entries)) {
            wp_die(esc_html($pending_entries->get_error_message()));
        }

        if (!empty($pending_entries)) {
            wp_die('No se puede cerrar esta semana: quedan horas pendientes dentro del periodo. Revisa o elimina esas horas antes de payroll.');
        }

        $closed_entries = cleg_payroll_closed_entries($start, $end);
        if (!is_wp_error($closed_entries) && !empty($closed_entries)) {
            $redirect = wp_get_referer() ?: home_url('/payroll-rrhh/');
            wp_safe_redirect(add_query_arg(array(
                'payroll_week' => $end,
                'payroll_closed' => '1',
            ), remove_query_arg(array('payroll_saved'), $redirect)));
            exit;
        }

        $data = cleg_payroll_data($start, $end);

        if (is_wp_error($data)) {
            wp_die(esc_html($data->get_error_message()));
        }

        cleg_payroll_sync_calculation_lines($data, $start, $end);
        cleg_payroll_update_employee_pto_balances($data);
        cleg_payroll_close_time_entries($data);

        $redirect = wp_get_referer();
        if (!$redirect) {
            $redirect = home_url('/panel/');
        }

        $redirect = remove_query_arg(array('payroll_saved', 'payroll_closed'), $redirect);
        wp_safe_redirect(add_query_arg(array(
            'payroll_week' => $end,
            'payroll_closed' => '1',
        ), $redirect));
        exit;
    }
}

if (!function_exists('cleg_payroll_rollback_previous_week')) {
    function cleg_payroll_rollback_previous_week() {
        if (!cleg_payroll_can_manage()) {
            wp_die('No autorizado.');
        }

        if (!isset($_POST['cleg_payroll_rollback_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_payroll_rollback_nonce'])), 'cleg_payroll_rollback_previous_week')) {
            wp_die('Solicitud no valida.');
        }

        $confirmed = isset($_POST['cleg_payroll_rollback_confirm']) && sanitize_text_field(wp_unslash($_POST['cleg_payroll_rollback_confirm'])) === '1';
        $phrase = isset($_POST['cleg_payroll_rollback_phrase']) ? strtoupper(trim(sanitize_text_field(wp_unslash($_POST['cleg_payroll_rollback_phrase'])))) : '';

        if (!$confirmed || $phrase !== 'REVERTIR') {
            wp_die('Rollback cancelado: falta la doble confirmacion de seguridad.');
        }

        list($start, $end) = cleg_payroll_period();
        $result = cleg_payroll_rollback_previous_week_records($start, $end);

        if (is_wp_error($result)) {
            wp_die(esc_html($result->get_error_message()));
        }

        $redirect = wp_get_referer();
        if (!$redirect) {
            $redirect = home_url('/panel/');
        }

        $redirect = remove_query_arg(array('payroll_saved', 'payroll_closed', 'payroll_locked', 'payroll_rollback', 'rollback_entries', 'rollback_lines'), $redirect);
        wp_safe_redirect(add_query_arg(array(
            'payroll_week' => $end,
            'payroll_rollback' => '1',
            'rollback_entries' => absint($result['time_entries'] ?? 0),
            'rollback_lines' => absint($result['lines'] ?? 0),
        ), $redirect));
        exit;
    }
}

if (!function_exists('cleg_payroll_export')) {
    function cleg_payroll_export() {
        if (!cleg_payroll_can_manage()) {
            wp_die('No autorizado.');
        }

        if (!isset($_GET['_wpnonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'cleg_payroll_export')) {
            wp_die('Solicitud no valida.');
        }

        list($start, $end) = cleg_payroll_period();
        $pending_entries = cleg_payroll_pending_entries($start, $end);

        if (is_wp_error($pending_entries)) {
            wp_die(esc_html($pending_entries->get_error_message()));
        }

        if (!empty($pending_entries)) {
            wp_die('No se puede exportar/cerrar esta semana: quedan horas pendientes dentro del periodo. Revisa o elimina esas horas antes de payroll.');
        }

        $data = cleg_payroll_data($start, $end);

        if (is_wp_error($data)) {
            wp_die(esc_html($data->get_error_message()));
        }

        cleg_payroll_sync_calculation_lines($data, $start, $end);

        $detail_rows = array();
        foreach ($data as $employee_row) {
            foreach (($employee_row['entry_rows'] ?? array()) as $entry_row) {
                $detail_rows[] = $entry_row;
            }
        }

        usort($detail_rows, function ($a, $b) {
            $time_compare = ((int) ($a['timestamp'] ?? 0)) <=> ((int) ($b['timestamp'] ?? 0));
            return $time_compare !== 0 ? $time_compare : strcmp($a['name'] ?? '', $b['name'] ?? '');
        });

        $total_pay = 0;
        foreach ($data as $row) {
            $total_pay += round((float) ($row['net_pay'] ?? $row['pay']), 2);
        }

        $detail_sheet_rows = array(
            array(array('C&L ENGINEERING GROUP LLC - Detalle de horas', 'title')),
            array('Inicio semana', $start, 'Fin semana', $end),
            array(),
            array(
                array('Dia #', 'header'), array('Dia', 'header'), array('Fecha', 'header'), array('Empleado', 'header'),
                array('Job Site / Obra', 'header'), array('Actividad', 'header'), array('Entrada', 'header'), array('Salida', 'header'),
                array('Almuerzo min', 'header'), array('Horas calc', 'header'), array('Plus Luis', 'header'), array('H extra', 'header'),
                array('H regular', 'header'), array('Aprobado', 'header'),
            ),
        );

        foreach ($detail_rows as $entry) {
            $timestamp = !empty($entry['timestamp']) ? (int) $entry['timestamp'] : false;
            $detail_sheet_rows[] = array(
                array($timestamp ? wp_date('w', $timestamp) : '', 'num'),
                $entry['weekday'] ?? '',
                $entry['date'] ?? '',
                $entry['name'] ?? '',
                $entry['job_site'] ?? '',
                $entry['activity'] ?? '',
                $entry['clock_in'] ?? '',
                $entry['clock_out'] ?? '',
                array((float) ($entry['lunch'] ?? 0), 'num'),
                array(round((float) ($entry['hours'] ?? 0), 2), 'num'),
                array(round((float) ($entry['plus_luis'] ?? 0), 2), 'money'),
                array(round((float) ($entry['extra_hours'] ?? 0), 2), 'num'),
                array(round((float) ($entry['regular_hours'] ?? 0), 2), 'num'),
                $entry['status'] ?? '',
            );
        }

        $summary_sheet_rows = array(
            array(array('C&L ENGINEERING GROUP LLC - Resumen de nomina', 'title')),
            array('Inicio semana', $start, 'Fin semana', $end),
            array(),
            array(
                array('Empleado', 'header'), array('Total H', 'header'), array('H regular', 'header'), array('H extra', 'header'),
                array('Rate', 'header'), array('Regular Pay', 'header'), array('Overtime Pay', 'header'), array('Gross Pay', 'header'),
                array('SS Employee', 'header'), array('Medicare', 'header'), array('SINOT', 'header'), array('Income Tax PR', 'header'),
                array('Manual Deduction', 'header'), array('Net Pay', 'header'), array('Status', 'header'),
            ),
        );

        foreach ($data as $row) {
            $summary_sheet_rows[] = array(
                $row['name'] ?? '',
                array(round((float) ($row['hours'] ?? 0), 2), 'num'),
                array(round((float) ($row['regular_hours'] ?? 0), 2), 'num'),
                array(round((float) ($row['extra_hours'] ?? 0), 2), 'num'),
                array(round((float) ($row['amount'] ?? 0), 2), 'money'),
                array(round((float) ($row['regular_pay'] ?? 0), 2), 'money'),
                array(round((float) ($row['extra_pay'] ?? 0), 2), 'money'),
                array(round((float) ($row['gross_pay'] ?? 0), 2), 'money'),
                array(round((float) ($row['social_security_employee'] ?? 0), 2), 'money'),
                array(round((float) ($row['medicare_employee'] ?? 0), 2), 'money'),
                array(round((float) ($row['sinot_employee'] ?? 0), 2), 'money'),
                array(round((float) ($row['pr_income_tax_withheld'] ?? 0), 2), 'money'),
                array(round((float) ($row['manual_deduction'] ?? 0), 2), 'money'),
                array(round((float) ($row['net_pay'] ?? 0), 2), 'total'),
                $row['calculation_status'] ?? '',
            );
        }

        $summary_sheet_rows[] = array('', '', '', '', '', '', '', '', '', '', '', '', 'TOTAL NET PAY', array(round($total_pay, 2), 'total'));

        $payment_sheet_rows = array(
            array(array('C&L ENGINEERING GROUP LLC - Pago y deducciones', 'title')),
            array('Inicio semana', $start, 'Fin semana', $end),
            array(),
            array(
                array('Name', 'header'), array('Type', 'header'), array('Form', 'header'), array('Invoice#', 'header'), array('Check', 'header'),
                array('Date', 'header'), array('Gross Pay', 'header'), array('SS Employee', 'header'), array('Medicare Employee', 'header'),
                array('SINOT Employee', 'header'), array('PR Income Tax', 'header'), array('Contractor Withholding', 'header'),
                array('Fixed Deductions', 'header'), array('Manual Deduction', 'header'), array('Plus/Adjustments', 'header'),
                array('Total Deductions', 'header'), array('Net Pay', 'header'), array('Status', 'header'), array('Comments', 'header'),
            ),
        );

        foreach ($data as $row) {
            $payment_timestamp = !empty($row['payment_date']) ? strtotime($row['payment_date']) : false;
            $payment_date = $payment_timestamp ? wp_date('m/d/Y', $payment_timestamp) : wp_date('m/d/Y');
            $payment_comments = trim(($row['comments'] ?? '') . ' ' . ($row['review_notes'] ?? ''));
            if (!empty($row['period_pr_note'])) {
                $payment_comments = trim($payment_comments . ' Income Tax PR: ' . $row['period_pr_note']);
            }
            if (!empty($row['manual_extra_note'])) {
                $payment_comments = trim($payment_comments . ' Extra manual: ' . $row['manual_extra_note']);
            }
            if (!empty($row['manual_deduction_note'])) {
                $payment_comments = trim($payment_comments . ' Deduccion manual: ' . $row['manual_deduction_note']);
            }

            $payment_sheet_rows[] = array(
                $row['name'] ?? '',
                $row['tax_type'] ?? '',
                $row['form_type'] ?? '',
                $row['invoice'] ?? '',
                $row['check'] ?? '',
                $payment_date,
                array(round((float) ($row['gross_pay'] ?? 0), 2), 'money'),
                array(round((float) ($row['social_security_employee'] ?? 0), 2), 'money'),
                array(round((float) ($row['medicare_employee'] ?? 0), 2), 'money'),
                array(round((float) ($row['sinot_employee'] ?? 0), 2), 'money'),
                array(round((float) ($row['pr_income_tax_withheld'] ?? 0), 2), 'money'),
                array(round((float) ($row['contractor_withholding'] ?? 0), 2), 'money'),
                array(round((float) ($row['fixed_deductions'] ?? 0), 2), 'money'),
                array(round((float) ($row['manual_deduction'] ?? 0), 2), 'money'),
                array(round((float) ($row['plus_adjustments'] ?? 0), 2), 'money'),
                array(round((float) ($row['total_deductions'] ?? 0), 2), 'money'),
                array(round((float) ($row['net_pay'] ?? 0), 2), 'total'),
                $row['calculation_status'] ?? '',
                $payment_comments,
            );
        }

        $payment_sheet_rows[] = array('', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'TOTAL NET PAY', array(round($total_pay, 2), 'total'));

        header('Content-Type: application/vnd.ms-excel; charset=utf-8');
        header('Content-Disposition: attachment; filename="cleg-payroll-' . sanitize_file_name($start . '-to-' . $end) . '.xls"');
        header('Pragma: no-cache');
        header('Expires: 0');

        echo '<?xml version="1.0" encoding="UTF-8"?>';
        echo '<?mso-application progid="Excel.Sheet"?>';
        echo '<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">';
        echo '<Styles>';
        echo '<Style ss:ID="brandTitle"><Font ss:Bold="1" ss:Size="18" ss:Color="#FFFFFF"/><Interior ss:Color="#06182D" ss:Pattern="Solid"/></Style>';
        echo '<Style ss:ID="section"><Font ss:Bold="1" ss:Size="12" ss:Color="#FFFFFF"/><Interior ss:Color="#C75000" ss:Pattern="Solid"/></Style>';
        echo '<Style ss:ID="muted"><Font ss:Bold="1" ss:Color="#506174"/></Style>';
        echo '<Style ss:ID="title"><Font ss:Bold="1" ss:Size="14"/><Interior ss:Color="#D9E2F3" ss:Pattern="Solid"/></Style>';
        echo '<Style ss:ID="header"><Font ss:Bold="1"/><Interior ss:Color="#DBE5F1" ss:Pattern="Solid"/><Borders><Border ss:Position="Bottom" ss:LineStyle="Continuous" ss:Weight="1"/></Borders></Style>';
        echo '<Style ss:ID="money"><NumberFormat ss:Format="$#,##0.00"/></Style>';
        echo '<Style ss:ID="num"><NumberFormat ss:Format="0.00"/></Style>';
        echo '<Style ss:ID="totalLabel"><Font ss:Bold="1"/><Interior ss:Color="#E7F1DD" ss:Pattern="Solid"/></Style>';
        echo '<Style ss:ID="total"><Font ss:Bold="1"/><Interior ss:Color="#92D050" ss:Pattern="Solid"/><NumberFormat ss:Format="$#,##0.00"/></Style>';
        echo '</Styles>';
        echo cleg_payroll_xls_sheet('01 Detalle de horas', $detail_sheet_rows);
        echo cleg_payroll_xls_sheet('02 Resumen nomina', $summary_sheet_rows);
        echo cleg_payroll_xls_sheet('03 Pago y deducciones', $payment_sheet_rows);
        $sheet_index = 4;
        foreach ($data as $row) {
            echo cleg_payroll_xls_sheet(cleg_payroll_sheet_name($row, $sheet_index), cleg_payroll_employee_statement_rows($row, $start, $end));
            $sheet_index++;
        }
        echo '</Workbook>';
        exit;
    }
}

if (!function_exists('cleg_payroll_styles')) {
    function cleg_payroll_styles() {
        return <<<'CSS'
<style>
.cleg-payroll{background:#f4f7fb;color:#06182d;min-height:100svh;padding:clamp(22px,4vw,56px)}
.cleg-payroll *{box-sizing:border-box}
.cleg-payroll-shell{width:min(100%,1280px);margin:0 auto}
.cleg-payroll-filters a{color:#06182d;font-weight:900;text-decoration:none}
.cleg-payroll-filters,.cleg-payroll-metrics,.cleg-payroll-rollback,.cleg-payroll-table,.cleg-payroll form:not(.cleg-payroll-rollback){width:min(1320px,calc(100% - 24px));max-width:min(1320px,calc(100% - 24px));margin-left:auto;margin-right:auto}
.cleg-payroll-filters,.cleg-payroll-metrics{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:14px}
.cleg-payroll-filters{align-items:end;background:#fff;border:1px solid rgba(6,24,45,.12);border-radius:14px;padding:14px}
