.cleg-payroll-filters a{display:inline-flex;align-items:center;background:#c75000}
.cleg-payroll-disabled{display:inline-flex;align-items:center;background:#98a4b3!important;cursor:not-allowed}
.cleg-payroll-week-note,.cleg-payroll-blocked,.cleg-payroll-metrics span,.cleg-payroll-notice{background:#fff;border:1px solid rgba(6,24,45,.12);border-radius:14px;padding:16px;min-width:180px}
.cleg-payroll-week-note{margin-bottom:14px;color:#516579;font-weight:800}
.cleg-payroll-blocked{margin-bottom:14px;background:#fff8ed;border-color:#ffd8a8;color:#7a3a00;font-weight:800}
