if (!function_exists('cleg_auto_worker_pin')) {
    function cleg_auto_worker_pin() {
        return str_pad((string) wp_rand(0, 9999), 4, '0', STR_PAD_LEFT);
    }
}

if (!function_exists('cleg_auto_worker_admin_allowed')) {
    function cleg_auto_worker_admin_allowed() {
        if (function_exists('cleg_admin_user_allowed')) {
            return cleg_admin_user_allowed();
        }

        return is_user_logged_in() && current_user_can('manage_options');
    }
}

if (!function_exists('cleg_auto_worker_error_redirect')) {
    function cleg_auto_worker_error_redirect($message) {
        $url = wp_get_referer() ?: home_url('/admin-empleados/');
        wp_safe_redirect(add_query_arg('cleg_admin_error', rawurlencode($message), $url));
        exit;
    }
}

if (!function_exists('cleg_auto_worker_success_notice')) {
    function cleg_auto_worker_success_notice($data) {
        $admin_id = get_current_user_id();
        if ($admin_id > 0) {
            set_transient('cleg_auto_worker_notice_' . $admin_id, $data, 10 * MINUTE_IN_SECONDS);
        }
    }
}

if (!function_exists('cleg_auto_worker_handle_create')) {
    function cleg_auto_worker_handle_create() {
        if (
            empty($_POST['cleg_admin_employee_action'])
            || sanitize_text_field(wp_unslash($_POST['cleg_admin_employee_action'])) !== 'create'
        ) {
            return;
        }

        if (!cleg_auto_worker_admin_allowed()) {
            return;
        }

        if (
            !isset($_POST['cleg_admin_employee_nonce'])
            || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_admin_employee_nonce'])), 'cleg_admin_employee_action')
        ) {
            cleg_auto_worker_error_redirect('Solicitud no valida.');
        }

        if (!function_exists('cleg_admin_request')) {
            cleg_auto_worker_error_redirect('Falta CLEG 05 activo antes de crear trabajadores.');
        }

        $name = isset($_POST['employee_name']) ? sanitize_text_field(wp_unslash($_POST['employee_name'])) : '';
        $username = isset($_POST['portal_username']) ? sanitize_user(wp_unslash($_POST['portal_username']), true) : '';
        $email = isset($_POST['employee_email']) ? sanitize_email(wp_unslash($_POST['employee_email'])) : '';
        $phone = isset($_POST['phone']) ? sanitize_text_field(wp_unslash($_POST['phone'])) : '';
        $department = isset($_POST['department']) ? sanitize_text_field(wp_unslash($_POST['department'])) : '';
        $employee_role = isset($_POST['employee_role']) ? sanitize_text_field(wp_unslash($_POST['employee_role'])) : 'Trabajador';
        $tax_type = isset($_POST['payroll_tax_type']) ? sanitize_text_field(wp_unslash($_POST['payroll_tax_type'])) : 'Employee - Full Payroll';
        $form_type = isset($_POST['payroll_form_type']) ? sanitize_text_field(wp_unslash($_POST['payroll_form_type'])) : 'No aplica / revisar';
        $period = isset($_POST['payroll_period']) ? sanitize_text_field(wp_unslash($_POST['payroll_period'])) : 'Per Hour';
        $amount = isset($_POST['payroll_amount']) ? (float) sanitize_text_field(wp_unslash($_POST['payroll_amount'])) : 0;
        $withholding_reason = isset($_POST['withholding_reason']) ? sanitize_textarea_field(wp_unslash($_POST['withholding_reason'])) : '';

        $allowed_tax_types = array('Employee - Full Payroll', 'Contractor - 10% Withholding', 'Contractor - No Withholding', 'Admin / No Payroll');
        if (!in_array($tax_type, $allowed_tax_types, true)) {
            $tax_type = 'Employee - Full Payroll';
        }

        $allowed_forms = array('W-2PR / 499R-2', '480.6SP', 'No aplica / revisar');
        if (!in_array($form_type, $allowed_forms, true)) {
            $form_type = $tax_type === 'Employee - Full Payroll' ? 'W-2PR / 499R-2' : '480.6SP';
        }

        if ($name === '' || $username === '') {
            cleg_auto_worker_error_redirect('Escribe nombre y usuario del trabajador.');
        }

        if (username_exists($username)) {
            cleg_auto_worker_error_redirect('Ese usuario ya existe en WordPress.');
        }

        if ($email !== '' && email_exists($email)) {
            cleg_auto_worker_error_redirect('Ese email ya existe en WordPress.');
        }

        if (!get_role('trabajador')) {
            add_role('trabajador', 'Trabajador', array('read' => true));
        }

        $pin = cleg_auto_worker_pin();
        $role_key = function_exists('cleg_admin_employee_role_key_from_label') ? cleg_admin_employee_role_key_from_label($employee_role) : '';
        $role_key = $role_key !== '' && get_role($role_key) ? $role_key : 'trabajador';

        $user_data = array(
            'user_login' => $username,
            'user_pass' => $pin,
            'display_name' => $name,
            'nickname' => $name,
            'role' => $role_key,
        );

        if ($email !== '') {
            $user_data['user_email'] = $email;
        }

        $wp_user_id = wp_insert_user($user_data);

        if (is_wp_error($wp_user_id)) {
            cleg_auto_worker_error_redirect('No se pudo crear el usuario WordPress: ' . $wp_user_id->get_error_message());
        }

        $valid_periods = array('Per Hour', 'Per Day', 'Biweekly', 'Fixed Per Period');
        $tracks_time = function_exists('cleg_admin_employee_role_tracks_time') ? cleg_admin_employee_role_tracks_time($employee_role) : true;

        $fields = array(
            'Employee Name' => $name,
            'Portal Username' => $username,
            'WordPress User ID' => (int) $wp_user_id,
            'Role' => $employee_role,
            'Status' => 'Active',
            'Time Tracking Required' => $tracks_time,
            'Payroll Tax Type' => $tax_type,
            'Payroll Form Type' => $form_type,
            'Payroll Period' => in_array($period, $valid_periods, true) ? $period : 'Per Hour',
            'Payroll Amount' => max(0, $amount),
        );

        if ($withholding_reason !== '') {
            $fields['Withholding Reason'] = $withholding_reason;
        }

        if ($email !== '') {
            $fields['Email'] = $email;
        }

        if ($phone !== '') {
            $fields['Phone'] = $phone;
        }

        if ($department !== '') {
            $fields['Department'] = $department;
        }

        if (function_exists('cleg_access_default_tenant')) {
            $tenant = cleg_access_default_tenant();
            update_user_meta((int) $wp_user_id, 'cleg_tenant_id', $tenant['id']);
            update_user_meta((int) $wp_user_id, 'cleg_tenant_slug', $tenant['slug']);
            update_user_meta((int) $wp_user_id, 'cleg_tenant_name', $tenant['name']);
        }
        update_user_meta((int) $wp_user_id, 'cleg_tenant_role', $employee_role);
        update_user_meta((int) $wp_user_id, 'cleg_tenant_status', 'active');

        $response = cleg_admin_request('POST', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'body' => array(
                'records' => array(array('fields' => $fields)),
                'typecast' => true,
            ),
        ));

        if (is_wp_error($response)) {
            if (!function_exists('wp_delete_user')) {
                require_once ABSPATH . 'wp-admin/includes/user.php';
            }

            wp_delete_user((int) $wp_user_id);
            cleg_auto_worker_error_redirect('No se pudo crear en Airtable. Se cancelo el usuario WordPress.');
        }

        cleg_auto_worker_success_notice(array(
            'name' => $name,
            'username' => $username,
            'pin' => $pin,
            'phone' => $phone,
        ));

        wp_safe_redirect(add_query_arg('cleg_worker_created', '1', home_url('/admin-empleados/')));
        exit;
    }
}

add_action('init', 'cleg_auto_worker_handle_create', 1);

