/**
 * CLEG 12 - Live Map Real
 */
/**
 * CLEG 12 - Live Map Real v1.2
 *
 * Code Snippets: pegar SIN la primera linea <?php.
 *
 * Objetivo:
 * - Reemplazar el shortcode [cleg_admin_live_map] de CLEG 11 por un mapa real.
 * - Usa Leaflet + OpenStreetMap.
 * - Incluye boton "Agrandar mapa".
 * - Incluye atajos solo a trabajadores activos y proyectos con trabajadores activos.
 * - Corrige render del mapa ampliado.
 *
 * Importante:
 * - Este snippet debe estar activo DESPUES de CLEG 11.
 * - No cambia payroll ni auditoria.
 */

function cleg12_shortcode_live_map_real() {
    if (!function_exists('cleg11_is_rrhh_admin') || !function_exists('cleg11_fetch_open_entries')) {
        return '<div class="cleg11-notice is-error">CLEG 12 requiere CLEG 11 activo.</div>';
    }

    if (!cleg11_is_rrhh_admin()) {
        return '<div class="cleg11-notice">Acceso restringido.</div>';
    }

    $entries = cleg11_fetch_open_entries();
    $sites = cleg11_fetch_job_sites();

    if (is_wp_error($entries) || is_wp_error($sites)) {
        return '<div class="cleg11-notice is-error">No se pudo cargar el mapa. Revisa token/permisos de Airtable.</div>';
    }

    $site_map = array();
    foreach ($sites as $site) {
        $name = cleg11_at($site, 'Job Site Name', '');
        if ($name) {
            $site_map[$name] = $site;
        }
    }

    $active_project_names = array();
    foreach ($entries as $entry) {
        $project_name = trim((string) cleg11_at($entry, 'Job Site Name', ''));
        if ($project_name !== '') {
            $active_project_names[$project_name] = true;
        }
    }

    $markers = array();
    $shortcuts = array();

    foreach ($sites as $site) {
        $site_name = cleg11_at($site, 'Job Site Name', 'Proyecto');
        if (!isset($active_project_names[$site_name])) {
            continue;
        }

        $lat = cleg11_at($site, 'Latitude', '');
        $lng = cleg11_at($site, 'Longitude', '');
        if ($lat === '' || $lng === '') {
            continue;
        }

        $site_marker = array(
            'type' => 'site',
            'label' => $site_name,
            'subtitle' => cleg11_at($site, 'Address', ''),
            'lat' => (float) $lat,
            'lng' => (float) $lng,
            'radius' => (float) cleg11_at($site, 'Allowed Radius Meters', 0),
        );
        $markers[] = $site_marker;
        $shortcuts[] = $site_marker;
    }

    foreach ($entries as $entry) {
        $lat = cleg11_at($entry, 'Clock In Latitude', '');
        $lng = cleg11_at($entry, 'Clock In Longitude', '');
        if ($lat === '' || $lng === '') {
            continue;
        }

        $geo = cleg11_entry_geofence_label($entry);
        $worker_marker = array(
            'type' => 'worker',
            'label' => cleg11_at($entry, 'Employee Name', 'Empleado'),
            'subtitle' => cleg11_at($entry, 'Job Site Name', 'Sin proyecto'),
            'status' => $geo['text'],
            'statusClass' => $geo['class'],
            'lat' => (float) $lat,
            'lng' => (float) $lng,
            'clockIn' => cleg11_dt_pr(cleg11_at($entry, 'Clock In Time', ''), 'M j, g:i a'),
            'mapsUrl' => cleg11_google_maps_url($lat, $lng),
            'timeline' => cleg11_render_timeline($entry),
        );
        $markers[] = $worker_marker;
        $shortcuts[] = $worker_marker;
    }

    $map_id = 'cleg12-map-' . wp_rand(1000, 9999);
    $modal_id = $map_id . '-modal';
    $json = wp_json_encode($markers);

    ob_start();
    cleg12_assets();
    ?>
    <section class="cleg12-wrap">
        <div class="cleg12-head">
            <div>
                <p class="cleg12-eyebrow">Tiempo real</p>
                <h2>Trabajando ahora</h2>
                <p>Mapa real de empleados activos, proyectos, ubicacion y estado de zona.</p>
            </div>
            <div class="cleg12-head-actions">
                <strong class="cleg12-count"><?php echo esc_html(count($entries)); ?> activos</strong>
                <button type="button" class="cleg12-expand" data-cleg12-open="<?php echo esc_attr($modal_id); ?>">Agrandar mapa</button>
            </div>
        </div>

        <?php if (!empty($shortcuts)) : ?>
            <div class="cleg12-shortcuts" aria-label="Atajos del mapa">
                <?php foreach ($shortcuts as $marker) :
                    if ($marker['type'] !== 'worker' && $marker['type'] !== 'site') {
                        continue;
                    }
                    $label = ($marker['type'] === 'worker' ? 'Trabajador: ' : 'Proyecto: ') . $marker['label'];
                    ?>
                    <button type="button" data-cleg12-focus="<?php echo esc_attr($marker['lat'] . ',' . $marker['lng']); ?>">
                        <?php echo esc_html($label); ?>
                    </button>
                <?php endforeach; ?>
            </div>
        <?php endif; ?>

        <div class="cleg12-grid">
            <div class="cleg12-map" id="<?php echo esc_attr($map_id); ?>" data-markers="<?php echo esc_attr($json); ?>"></div>

            <div class="cleg12-list">
                <?php if (!$entries) : ?>
                    <div class="cleg12-empty">No hay jornadas abiertas ahora.</div>
                <?php endif; ?>

                <?php foreach ($entries as $entry) :
                    $geo = cleg11_entry_geofence_label($entry);
                    $lat = cleg11_at($entry, 'Clock In Latitude', '');
                    $lng = cleg11_at($entry, 'Clock In Longitude', '');
                    ?>
                    <article class="cleg12-card">
                        <div class="cleg12-card-top">
                            <div>
                                <h3><?php echo esc_html(cleg11_at($entry, 'Employee Name', 'Empleado')); ?></h3>
                                <p><?php echo esc_html(cleg11_at($entry, 'Job Site Name', 'Sin proyecto')); ?></p>
                            </div>
                            <span class="cleg12-badge <?php echo esc_attr($geo['class']); ?>"><?php echo esc_html($geo['text']); ?></span>
                        </div>
                        <?php echo cleg11_render_timeline($entry); ?>
                        <div class="cleg12-actions">
                            <span>Entrada: <?php echo esc_html(cleg11_dt_pr(cleg11_at($entry, 'Clock In Time', ''), 'M j, g:i a')); ?></span>
                            <?php if ($lat !== '' && $lng !== '') : ?>
                                <a href="<?php echo esc_url(cleg11_google_maps_url($lat, $lng)); ?>" target="_blank" rel="noopener">Abrir GPS</a>
                            <?php endif; ?>
                        </div>
                    </article>
                <?php endforeach; ?>
            </div>
        </div>
    </section>

    <div class="cleg12-modal" id="<?php echo esc_attr($modal_id); ?>" aria-hidden="true">
        <div class="cleg12-modal-panel">
            <div class="cleg12-modal-bar">
                <strong>Mapa en tiempo real</strong>
                <button type="button" data-cleg12-close="<?php echo esc_attr($modal_id); ?>">Cerrar</button>
            </div>
            <div class="cleg12-map cleg12-map-large" id="<?php echo esc_attr($map_id); ?>-large" data-markers="<?php echo esc_attr($json); ?>"></div>
        </div>
    </div>
    <?php
    return ob_get_clean();
}

add_shortcode('cleg_admin_live_map', 'cleg12_shortcode_live_map_real');

