        .cleg12-shortcuts button:hover{background:#06182d;color:#fff}
        .cleg12-grid{display:grid;grid-template-columns:minmax(380px,.95fr) minmax(420px,1.05fr);gap:14px;align-items:stretch}
        .cleg12-map{min-height:390px;border:1px solid rgba(6,24,45,.12);border-radius:8px;overflow:hidden;background:#eef3f8;z-index:1}
        .cleg12-list{max-height:460px;overflow:auto;display:grid;gap:10px;align-content:start;padding-right:2px}
        .cleg12-card{padding:13px;border:1px solid rgba(6,24,45,.12);border-radius:8px;background:#fff}
        .cleg12-card-top{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:start;margin-bottom:10px}
        .cleg12-card h3{margin:0 0 3px;color:#06182d;font-size:16px;line-height:1.15}
