        .cleg12-badge{display:inline-flex;max-width:240px;min-height:26px;align-items:center;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:950;line-height:1.15;text-align:right;white-space:normal;border:1px solid rgba(6,24,45,.12);background:#eef3f8;color:#31465d}
        .cleg12-badge.is-inside{background:#eaf7f0;color:#0f7a4f;border-color:rgba(15,122,79,.22)}
