        .cleg12-site-marker{background:#0b4f8f;border:3px solid #fff;border-radius:999px;box-shadow:0 8px 16px rgba(6,24,45,.24)}
        .cleg12-popup strong{display:block;margin-bottom:3px;color:#06182d}
        .cleg12-popup small{display:block;color:#51657c}
        @media(max-width:980px){.cleg12-wrap{width:calc(100vw - 24px);padding:14px}.cleg12-head,.cleg12-grid{grid-template-columns:1fr}.cleg12-map{min-height:320px}.cleg12-head-actions{justify-content:flex-start}.cleg12-badge{max-width:none;text-align:left}}
    </style>
    <script>
        (function(){
            window.cleg12Maps = window.cleg12Maps || [];

            function markerIcon(type){
                return L.divIcon({
                    className: type === 'worker' ? 'cleg12-worker-marker' : 'cleg12-site-marker',
                    html: '',
                    iconSize: type === 'worker' ? [22,22] : [18,18],
                    iconAnchor: type === 'worker' ? [11,11] : [9,9]
                });
            }

            function initMap(el){
                if (!el || el.dataset.ready === '1' || typeof L === 'undefined') return null;
                el.dataset.ready = '1';
                var markers = [];
                try { markers = JSON.parse(el.dataset.markers || '[]'); } catch(e) {}

                var map = L.map(el, { scrollWheelZoom: false });
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    maxZoom: 20,
                    attribution: '&copy; OpenStreetMap'
                }).addTo(map);

                var bounds = [];
                markers.forEach(function(item){
                    if (typeof item.lat !== 'number' || typeof item.lng !== 'number') return;
                    var popup = '<div class=\"cleg12-popup\"><strong>' + escapeHtml(item.label || '') + '</strong><small>' + escapeHtml(item.subtitle || '') + '</small>';
                    if (item.status) popup += '<small>' + escapeHtml(item.status) + '</small>';
                    if (item.clockIn) popup += '<small>Entrada: ' + escapeHtml(item.clockIn) + '</small>';
                    popup += '</div>';
                    L.marker([item.lat, item.lng], { icon: markerIcon(item.type) }).addTo(map).bindPopup(popup);
                    if (item.type === 'site' && item.radius && item.radius > 0) {
                        L.circle([item.lat, item.lng], { radius: item.radius, color: '#0b4f8f', weight: 1, fillColor: '#0b4f8f', fillOpacity: .08 }).addTo(map);
                    }
                    bounds.push([item.lat, item.lng]);
                });

                fitMap(map, bounds);

                setTimeout(function(){ map.invalidateSize(); }, 250);
                window.cleg12Maps.push({ map: map, bounds: bounds, el: el });
                return map;
            }

            function fitMap(map, bounds){
                if (!map) return;
                if (bounds && bounds.length) {
                    map.fitBounds(bounds, { padding: [34, 34], maxZoom: 16 });
                } else {
                    map.setView([18.2208, -66.5901], 9);
                }
            }

            function refreshMaps(){
                window.cleg12Maps.forEach(function(item){
                    if (!item || !item.map) return;
                    item.map.invalidateSize(true);
                    fitMap(item.map, item.bounds || []);
                });
            }

            function escapeHtml(text){
                return String(text || '').replace(/[&<>'\"]/g, function(c){
                    return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c];
                });
            }

            function boot(){
                document.querySelectorAll('.cleg12-map').forEach(initMap);
                document.querySelectorAll('[data-cleg12-focus]').forEach(function(btn){
                    btn.addEventListener('click', function(){
                        var parts = String(btn.getAttribute('data-cleg12-focus') || '').split(',');
                        var lat = parseFloat(parts[0]);
                        var lng = parseFloat(parts[1]);
                        if (!isFinite(lat) || !isFinite(lng)) return;
                        window.cleg12Maps.forEach(function(item){
                            if (!item || !item.map) return;
                            item.map.setView([lat, lng], 17);
                            setTimeout(function(){ item.map.invalidateSize(true); }, 80);
                        });
                    });
                });
                document.querySelectorAll('[data-cleg12-open]').forEach(function(btn){
                    btn.addEventListener('click', function(){
                        var modal = document.getElementById(btn.getAttribute('data-cleg12-open'));
                        if (!modal) return;
                        modal.classList.add('is-open');
                        modal.setAttribute('aria-hidden', 'false');
                        setTimeout(function(){ document.querySelectorAll('.cleg12-map-large').forEach(initMap); refreshMaps(); }, 80);
                        setTimeout(refreshMaps, 250);
                        setTimeout(refreshMaps, 600);
                        setTimeout(refreshMaps, 1100);
                    });
                });
                document.querySelectorAll('[data-cleg12-close]').forEach(function(btn){
                    btn.addEventListener('click', function(){
                        var modal = document.getElementById(btn.getAttribute('data-cleg12-close'));
                        if (!modal) return;
                        modal.classList.remove('is-open');
                        modal.setAttribute('aria-hidden', 'true');
                    });
                });
            }

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', boot);
            } else {
                boot();
            }
        })();
    </script>
    <?php
}
