if (!function_exists('cleg_emp_payroll_date')) {
    function cleg_emp_payroll_date($value) {
        $timestamp = strtotime((string) $value);
        return $timestamp ? wp_date('m/d/Y', $timestamp) : '';
    }
}

if (!function_exists('cleg_emp_payroll_formula_text')) {
    function cleg_emp_payroll_formula_text($value) {
        return str_replace("'", "\\'", (string) $value);
    }
}

if (!function_exists('cleg_emp_payroll_first_employee_by_formula')) {
    function cleg_emp_payroll_first_employee_by_formula($formula) {
        $employees = cleg_emp_payroll_records(CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'filterByFormula' => $formula,
            'maxRecords' => 1,
        ));

        if (is_wp_error($employees) || empty($employees[0])) {
            return null;
        }

        return $employees[0];
    }
}

if (!function_exists('cleg_emp_payroll_record_links_include')) {
    function cleg_emp_payroll_record_links_include($record, $field, $record_id) {
        $record_id = sanitize_text_field((string) $record_id);
        $links = cleg_emp_payroll_raw_field($record, $field, array());

        if ($record_id === '' || !is_array($links)) {
            return false;
        }

        foreach ($links as $link) {
            if (is_array($link) && sanitize_text_field((string) ($link['id'] ?? '')) === $record_id) {
                return true;
            }

            if (is_scalar($link) && sanitize_text_field((string) $link) === $record_id) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg_emp_payroll_current_employee')) {
    function cleg_emp_payroll_current_employee() {
        $user = wp_get_current_user();
        if (!$user || empty($user->ID)) {
            return null;
        }

        $employee = cleg_emp_payroll_first_employee_by_formula('{WordPress User ID}=' . (int) $user->ID);
        if ($employee) {
            return $employee;
        }

        if (!empty($user->user_login)) {
            $username = cleg_emp_payroll_formula_text(sanitize_user($user->user_login));
            $employee = cleg_emp_payroll_first_employee_by_formula("LOWER({Portal Username})=LOWER('{$username}')");
            if ($employee) {
                return $employee;
            }
        }

        if (!empty($user->user_email)) {
            $email = cleg_emp_payroll_formula_text(sanitize_email($user->user_email));
            $employee = cleg_emp_payroll_first_employee_by_formula("LOWER({Email})=LOWER('{$email}')");
            if ($employee) {
                return $employee;
            }
        }

        return null;
    }
}

if (!function_exists('cleg_emp_payroll_profile')) {
    function cleg_emp_payroll_profile($employee_id) {
        $profiles = cleg_emp_payroll_records(CLEG_AIRTABLE_TAX_PROFILES_TABLE, array(
            'maxRecords' => 100,
        ));

        if (is_wp_error($profiles) || empty($profiles)) {
            return null;
        }

        foreach ($profiles as $profile) {
            if (cleg_emp_payroll_record_links_include($profile, 'Employee', $employee_id)) {
                return $profile;
            }
        }

        return null;
    }
}

if (!function_exists('cleg_emp_payroll_lines')) {
    function cleg_emp_payroll_lines($employee_id) {
        $lines = cleg_emp_payroll_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'sort[0][field]' => 'Period End',
            'sort[0][direction]' => 'desc',
            'maxRecords' => 100,
        ));

        if (is_wp_error($lines)) {
            return array();
        }

        $matched = array_values(array_filter($lines, function ($line) use ($employee_id) {
            return cleg_emp_payroll_record_links_include($line, 'Employee', $employee_id);
        }));

        return array_slice($matched, 0, 24);
    }
}

if (!function_exists('cleg_emp_payroll_line_for_employee')) {
    function cleg_emp_payroll_line_for_employee($line_id, $employee_id) {
        $line_id = sanitize_text_field((string) $line_id);
        $employee_id = sanitize_text_field((string) $employee_id);

        if ($line_id === '' || $employee_id === '') {
            return null;
        }

        $line_id = cleg_emp_payroll_formula_text($line_id);
        $lines = cleg_emp_payroll_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'filterByFormula' => "RECORD_ID()='{$line_id}'",
            'maxRecords' => 1,
        ));

        if (is_wp_error($lines) || empty($lines)) {
            return null;
        }

        return cleg_emp_payroll_record_links_include($lines[0], 'Employee', $employee_id) ? $lines[0] : null;
    }
}

if (!function_exists('cleg_emp_payroll_status_label')) {
    function cleg_emp_payroll_status_label($status) {
        $labels = array(
            'Ready to Pay' => 'Lista',
            'Paid' => 'Pagada',
            'Draft' => 'Borrador',
            'Needs Review' => 'En revision',
        );

        return $labels[$status] ?? ($status !== '' ? $status : 'Sin estado');
    }
}

if (!function_exists('cleg_emp_payroll_pdf_download')) {
    function cleg_emp_payroll_pdf_download() {
        if (!is_user_logged_in()) {
            wp_die('Acceso requerido.');
        }

        $line_id = isset($_GET['line_id']) ? sanitize_text_field(wp_unslash($_GET['line_id'])) : '';
        if ($line_id === '' || !isset($_GET['_wpnonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_GET['_wpnonce'])), 'cleg_employee_payroll_pdf_' . $line_id)) {
            wp_die('Solicitud no valida.');
        }

        $employee = cleg_emp_payroll_current_employee();
        if (!$employee) {
            wp_die('No encontramos tu ficha de trabajador.');
        }

        $employee_id = sanitize_text_field($employee['id'] ?? '');
        $employee_tax_type = cleg_emp_payroll_field($employee, 'Payroll Tax Type', 'Employee - Full Payroll');
        if ($employee_tax_type !== 'Employee - Full Payroll') {
            wp_die('Este portal de nominas esta disponible solo para empleados.');
        }

        $line = cleg_emp_payroll_line_for_employee($line_id, $employee_id);
        if (!$line) {
            wp_die('Esta nomina no pertenece a tu usuario o ya no esta disponible.');
        }

        $line_tax_type = cleg_emp_payroll_field($line, 'Worker Tax Type', $employee_tax_type);
        if ($line_tax_type !== 'Employee - Full Payroll') {
            wp_die('Este comprobante no pertenece al portal de nominas de empleados.');
        }

        $name = cleg_emp_payroll_field($employee, 'Employee Name');
        $period = cleg_emp_payroll_date(cleg_emp_payroll_field($line, 'Period Start')) . ' - ' . cleg_emp_payroll_date(cleg_emp_payroll_field($line, 'Period End'));
        $gross_pay = (float) cleg_emp_payroll_field($line, 'Gross Pay', 0);
        $net_pay = (float) cleg_emp_payroll_field($line, 'Net Pay', 0);
        $pdf_data = array(
            'logo' => cleg_emp_payroll_pdf_logo_data(),
            'employee_name' => $name,
            'period' => $period,
            'generated_at' => wp_date('m/d/Y h:i a'),
            'worker_tax_type' => cleg_emp_payroll_field($line, 'Worker Tax Type', cleg_emp_payroll_field($employee, 'Payroll Tax Type')),
            'regular_hours' => cleg_emp_payroll_field($line, 'Regular Hours', 0),
            'overtime_hours' => cleg_emp_payroll_field($line, 'Overtime Hours', 0),
            'gross_pay' => $gross_pay,
            'net_pay' => $net_pay,
            'total_deductions' => max(0, $gross_pay - $net_pay),
            'earnings' => array(
                array('Pago regular', cleg_emp_payroll_field($line, 'Regular Pay', 0)),
                array('Pago overtime', cleg_emp_payroll_field($line, 'Overtime Pay', 0)),
                array('Ajustes / plus', cleg_emp_payroll_field($line, 'Plus Adjustments', 0)),
                array('Bruto', $gross_pay),
            ),
            'deductions' => array(
                array('Seguro Social', cleg_emp_payroll_field($line, 'Social Security Employee', 0)),
                array('Medicare', cleg_emp_payroll_field($line, 'Medicare Employee', 0)),
                array('Income Tax PR', cleg_emp_payroll_field($line, 'PR Income Tax Withheld', 0)),
                array('SINOT', cleg_emp_payroll_field($line, 'SINOT Employee', 0)),
                array('ASUME / embargo', cleg_emp_payroll_field($line, 'ASUME / Garnishment', 0)),
                array('Prestamo / anticipo', cleg_emp_payroll_field($line, 'Loan Advance Deduction', 0)),
                array('Plan medico / voluntario', cleg_emp_payroll_field($line, 'Health / Voluntary Deduction', 0)),
                array('Otras deducciones', cleg_emp_payroll_field($line, 'Fixed Deductions', 0)),
            ),
            'note' => cleg_emp_payroll_field($line, 'Employee Visible Notes'),
        );

        $pdf = cleg_emp_payroll_build_pdf($pdf_data);
        $filename = 'cleg-paystub-' . sanitize_file_name($period . '-' . $name) . '.pdf';

        nocache_headers();
        header('Content-Type: application/pdf');
        header('Content-Disposition: attachment; filename="' . $filename . '"');
        header('Content-Length: ' . strlen($pdf));
        echo $pdf; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
        exit;
    }
}

if (!function_exists('cleg_emp_payroll_shortcode')) {
    function cleg_emp_payroll_shortcode() {
