            return '<section class="cleg-emp-payroll"><div class="empty"><h2>Acceso requerido</h2><p>Inicia sesion para ver tus nominas.</p></div>' . cleg_emp_payroll_styles() . '</section>';
        }

        $employee = cleg_emp_payroll_current_employee();
        if (!$employee) {
            return '<section class="cleg-emp-payroll"><div class="empty"><h2>No encontramos tu ficha</h2><p>Comunicate con oficina para enlazar tu acceso de trabajador.</p></div>' . cleg_emp_payroll_styles() . '</section>';
        }

        $name = cleg_emp_payroll_field($employee, 'Employee Name');
