        if ($tax_type !== 'Employee - Full Payroll') {
            return '<section class="cleg-emp-payroll"><div class="shell"><header class="hero"><div><p>Portal de empleado</p><h2>Mis nominas</h2><span>' . esc_html($name) . '</span></div><a class="back-btn" href="' . esc_url(home_url('/panel/')) . '">Volver al panel</a></header><div class="empty"><h2>No aplica</h2><p>Este portal muestra nominas solo para empleados con payroll completo. Si eres contratista, tu informacion de pago se gestiona por oficina y no se publica aqui.</p></div></div>' . cleg_emp_payroll_styles() . '</section>';
        }

        $employee_id = sanitize_text_field($employee['id']);
        $profile = cleg_emp_payroll_profile($employee_id);
        $all_lines = cleg_emp_payroll_lines($employee_id);
        $lines = array_values(array_filter($all_lines, function ($line) {
            return cleg_emp_payroll_field($line, 'Worker Tax Type', 'Employee - Full Payroll') === 'Employee - Full Payroll';
        }));
        $latest = $lines[0] ?? null;
        $form_type = cleg_emp_payroll_field($employee, 'Payroll Form Type', 'No aplica / revisar');
        $doc_status = $profile ? cleg_emp_payroll_field($profile, 'Document Verification Status', 'Pending Review') : 'Pending Review';
