        $certificate_status = $profile ? cleg_emp_payroll_field($profile, 'Withholding Certificate Status', 'Missing') : 'Missing';
        $latest_net = $latest ? cleg_emp_payroll_field($latest, 'Net Pay', '0') : '0';
