    function cleg_center_employee_role_choices($current_role = '') {
        $choices = array(
            'Trabajador' => 'Trabajador',
            'Administrador RRHH' => 'Administrador RRHH',
            'Ingeniero' => 'Ingeniero',
            'Supervisor' => 'Supervisor',
            'Vendedor' => 'Vendedor',
            'CLEG Procurement User' => 'CLEG Procurement User',
        );

        if (function_exists('cleg_admin_employee_role_choices')) {
            foreach (cleg_admin_employee_role_choices($current_role) as $role_label) {
                $role_label = sanitize_text_field($role_label);
                if ($role_label !== '') {
                    $choices[$role_label] = $role_label;
                }
            }
        } elseif (function_exists('cleg_starter_assignable_roles')) {
            foreach (cleg_starter_assignable_roles() as $role_label) {
                $role_label = sanitize_text_field($role_label);
                if ($role_label !== '') {
                    $choices[$role_label] = $role_label;
                }
            }
        }

        $current_role = sanitize_text_field($current_role);
        if ($current_role !== '' && !isset($choices[$current_role])) {
            $choices[$current_role] = $current_role . ' (actual)';
        }

        return $choices;
    }
}

