    }
}

if (!function_exists('cleg_center_workdays_between')) {
    function cleg_center_workdays_between($start_date, $end_date) {
        $start_date = cleg_center_iso_date($start_date);
        $end_date = cleg_center_iso_date($end_date);

        if ($start_date === '' || $end_date === '') {
            return 0;
        }

        try {
            $tz = new DateTimeZone('America/Puerto_Rico');
            $start = new DateTimeImmutable($start_date, $tz);
            $end = new DateTimeImmutable($end_date, $tz);
        } catch (Exception $e) {
            return 0;
        }

        if ($end < $start) {
            return 0;
        }

        $days = 0;
        for ($cursor = $start; $cursor <= $end; $cursor = $cursor->modify('+1 day')) {
            $weekday = (int) $cursor->format('N');
            if ($weekday <= 5) {
                $days++;
            }
        }

        return $days;
    }
}

