if (!function_exists('cleg_center_document_health')) {
    function cleg_center_document_health($documents) {
        $today = current_time('timestamp');
        $expiring = 0;
        $expired = 0;
        $pending = 0;

        foreach ($documents as $document) {
            $status = cleg_center_field($document, 'Verification Status');
            $expiration = cleg_center_field($document, 'Expiration Date');

            if (in_array($status, array('Pending Review', 'Rejected'), true)) {
                $pending++;
            }

            if ($expiration !== '') {
                $ts = strtotime($expiration . ' 23:59:59');
                if ($ts && $ts < $today) {
                    $expired++;
                } elseif ($ts && $ts <= $today + (30 * DAY_IN_SECONDS)) {
                    $expiring++;
                }
            }
        }

        if ($expired > 0) {
            return array('class' => 'danger', 'label' => $expired . ' expirado(s)');
        }

        if ($expiring > 0) {
            return array('class' => 'warn', 'label' => $expiring . ' por vencer');
        }

        if ($pending > 0) {
            return array('class' => 'warn', 'label' => $pending . ' por revisar');
        }

        $count = count($documents);
        return $count > 0 ? array('class' => 'ok', 'label' => $count . ' documento(s)') : array('class' => 'neutral', 'label' => '');
    }
}

if (!function_exists('cleg_center_status_class')) {
    function cleg_center_status_class($status, $expiration = '') {
        if ($expiration !== '') {
            $ts = strtotime($expiration . ' 23:59:59');
            if ($ts && $ts < current_time('timestamp')) {
                return 'danger';
            }
            if ($ts && $ts <= current_time('timestamp') + (30 * DAY_IN_SECONDS)) {
                return 'warn';
            }
        }

        if (in_array($status, array('Verified', 'Active'), true)) {
            return 'ok';
        }

        if (in_array($status, array('Expired', 'Rejected', 'Inactive'), true)) {
            return 'danger';
        }

        return 'warn';
    }
}

