if (!function_exists('cleg_center_payroll_lines')) {
    function cleg_center_payroll_lines($employee_id, $limit = 24) {
        $employee_id = sanitize_text_field((string) $employee_id);
        if ($employee_id === '') {
            return array();
        }

        $lines = cleg_center_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'sort[0][field]' => 'Period End',
            'sort[0][direction]' => 'desc',
            'maxRecords' => 100,
        ));

        if (is_wp_error($lines)) {
            return array();
        }

        $matched = array_values(array_filter($lines, function ($line) use ($employee_id) {
            $links = cleg_center_raw($line, 'Employee', array());
            return is_array($links) && in_array($employee_id, array_map('strval', $links), true);
        }));

        return array_slice($matched, 0, max(1, min(100, (int) $limit)));
    }
}

if (!function_exists('cleg_center_payroll_summary')) {
    function cleg_center_payroll_summary($lines) {
        $summary = array(
            'gross_pay' => 0,
            'net_pay' => 0,
            'employee_withheld' => 0,
            'employer_cost' => 0,
            'employer_taxes' => 0,
            'periods' => 0,
            'last_period' => '',
        );

        foreach ($lines as $line) {
            $summary['periods']++;
            $gross = cleg_center_number_value(cleg_center_raw($line, 'Gross Pay', 0));
            $net = cleg_center_number_value(cleg_center_raw($line, 'Net Pay', 0));
            $employer_cost = cleg_center_number_value(cleg_center_raw($line, 'Total Employer Cost', 0));
            $employer_taxes = cleg_center_number_value(cleg_center_raw($line, 'Employer Social Security', 0)) + cleg_center_number_value(cleg_center_raw($line, 'Employer Medicare', 0));
            $summary['gross_pay'] += $gross;
            $summary['net_pay'] += $net;
            $summary['employee_withheld'] += max(0, $gross - $net);
            $summary['employer_cost'] += $employer_cost > 0 ? $employer_cost : ($gross + $employer_taxes);
            $summary['employer_taxes'] += $employer_taxes;
            if ($summary['last_period'] === '') {
                $start = cleg_center_field($line, 'Period Start');
                $end = cleg_center_field($line, 'Period End');
                $summary['last_period'] = trim($start . ($end !== '' ? ' - ' . $end : ''));
            }
        }

        return $summary;
    }
}

if (!function_exists('cleg_center_handle_save')) {
    function cleg_center_handle_save() {
        if (empty($_POST['cleg_center_action'])) {
            return;
        }

        if (!cleg_center_allowed()) {
            return;
        }

        if (!isset($_POST['cleg_center_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_center_nonce'])), 'cleg_center_save')) {
            return;
        }

        $action = sanitize_text_field(wp_unslash($_POST['cleg_center_action']));
        $employee_id = isset($_POST['employee_id']) ? sanitize_text_field(wp_unslash($_POST['employee_id'])) : '';
        $redirect = wp_get_referer() ?: home_url('/empleados/');

        if ($employee_id === '') {
            wp_safe_redirect(add_query_arg('center_error', 'missing_employee', $redirect));
            exit;
        }

        if ($action === 'create_employee_leave') {
            $employee_response = cleg_center_request('GET', CLEG_AIRTABLE_EMPLOYEES_TABLE, array('record_id' => $employee_id));
            $employee_record = is_array($employee_response) && isset($employee_response['id']) ? $employee_response : array();
            $leave_type = sanitize_text_field(wp_unslash($_POST['leave_type'] ?? 'Sick'));
            $status = sanitize_text_field(wp_unslash($_POST['leave_status'] ?? 'Approved'));
            $start_date = cleg_center_iso_date(wp_unslash($_POST['leave_start_date'] ?? ''));
            $end_date = cleg_center_iso_date(wp_unslash($_POST['leave_end_date'] ?? ''));
            $hours_per_day = max(0.25, (float) sanitize_text_field(wp_unslash($_POST['leave_hours_per_day'] ?? 8)));
            $allowed_types = array('Sick', 'Vacation', 'Absence', 'Unpaid', 'Other');
            $allowed_status = array('Approved', 'Pending', 'Rejected');

            if (!in_array($leave_type, $allowed_types, true)) {
                $leave_type = 'Sick';
            }

            if (!in_array($status, $allowed_status, true)) {
                $status = 'Approved';
            }

            $work_days = cleg_center_workdays_between($start_date, $end_date);

            if ($work_days <= 0) {
                wp_safe_redirect(add_query_arg(array('employee_id' => $employee_id, 'center_error' => 'invalid_leave_dates'), home_url('/empleados/')));
                exit;
            }

            $hours_count = round($work_days * $hours_per_day, 2);
            $balance_field = cleg_center_leave_balance_field($leave_type);
            $balance_before = $balance_field !== '' && !empty($employee_record) ? cleg_center_number_value(cleg_center_raw($employee_record, $balance_field, 0)) : 0.0;
            $uses_balance = !empty($_POST['leave_use_balance']) && $balance_field !== '' && $status === 'Approved';
            $used_hours = $uses_balance ? min($balance_before, $hours_count) : 0.0;
            $balance_after = $uses_balance ? max(0, $balance_before - $used_hours) : $balance_before;
            $uncovered_hours = $uses_balance ? max(0, $hours_count - $used_hours) : $hours_count;
            $current_user = wp_get_current_user();
            $created_by = $current_user && $current_user->exists() ? ($current_user->display_name ?: $current_user->user_login) : 'Admin';
            $admin_note = sanitize_textarea_field(wp_unslash($_POST['leave_admin_note'] ?? ''));
            if (!empty($_POST['leave_use_vacation_overflow'])) {
                $admin_note = trim($admin_note . "\n[use_vacation_overflow=yes]");
            }

            cleg_center_request('POST', CLEG_AIRTABLE_LEAVE_LEDGER_TABLE, array(
                'body' => array(
                    'records' => array(array(
                        'fields' => array(
                            'Leave Code' => 'LEAVE-' . gmdate('Ymd-His') . '-' . cleg_center_slug(cleg_center_field($employee_record, 'Employee Name', 'Empleado')),
                            'Employee' => array($employee_id),
                            'Leave Type' => $leave_type,
                            'Source' => 'Admin Manual Entry',
                            'Status' => $status,
                            'Start Date' => $start_date,
                            'End Date' => $end_date,
                            'Work Days Count' => $work_days,
                            'Hours Count' => $hours_count,
                            'Balance Before' => $balance_before,
                            'Accrued Hours' => 0,
                            'Used Hours' => $used_hours,
                            'Balance After' => $balance_after,
                            'Uncovered Hours' => $uncovered_hours,
                            'Visible on Paystub' => !empty($_POST['leave_visible_paystub']),
                            'Admin Note' => $admin_note,
                            'Employee Note' => sanitize_textarea_field(wp_unslash($_POST['leave_employee_note'] ?? '')),
                            'Created By' => $created_by,
                            'Created At' => gmdate('c'),
                        ),
                    )),
                    'typecast' => true,
                ),
            ));

            wp_safe_redirect(add_query_arg(array('employee_id' => $employee_id, 'center_saved' => 'leave'), home_url('/empleados/')));
            exit;
        }

        if ($action === 'save_employee_profile') {
            $period = sanitize_text_field(wp_unslash($_POST['payroll_period'] ?? 'Per Hour'));
            $tax_type = sanitize_text_field(wp_unslash($_POST['payroll_tax_type'] ?? 'Employee - Full Payroll'));
            $form_type = sanitize_text_field(wp_unslash($_POST['payroll_form_type'] ?? 'No aplica / revisar'));
            $status = sanitize_text_field(wp_unslash($_POST['employee_status'] ?? 'Active'));
            $role = sanitize_text_field(wp_unslash($_POST['employee_role'] ?? 'Trabajador'));

            $allowed_periods = array('Per Hour', 'Per Day', 'Biweekly', 'Fixed Per Period');
            $allowed_tax_types = array('Employee - Full Payroll', 'Contractor - 10% Withholding', 'Contractor - No Withholding', 'Admin / No Payroll');
            $allowed_forms = array('W-2PR / 499R-2', '480.6SP', 'No aplica / revisar');
            $allowed_status = array('Active', 'Inactive');

            if (!in_array($period, $allowed_periods, true)) {
                $period = 'Per Hour';
            }

            if (!in_array($tax_type, $allowed_tax_types, true)) {
                $tax_type = 'Employee - Full Payroll';
            }

            if (!in_array($form_type, $allowed_forms, true)) {
                $form_type = 'No aplica / revisar';
            }

            if (!in_array($status, $allowed_status, true)) {
                $status = 'Active';
            }

            $employee_fields = array(
                'Employee Name' => sanitize_text_field(wp_unslash($_POST['employee_name'] ?? '')),
                'Email' => sanitize_email(wp_unslash($_POST['employee_email'] ?? '')),
                'Phone' => sanitize_text_field(wp_unslash($_POST['employee_phone'] ?? '')),
                'Department' => sanitize_text_field(wp_unslash($_POST['employee_department'] ?? '')),
                'Status' => $status,
                'Role' => $role,
                'Portal Username' => sanitize_user(wp_unslash($_POST['portal_username'] ?? '')),
                'Payroll Amount' => max(0, (float) sanitize_text_field(wp_unslash($_POST['payroll_amount'] ?? 0))),
                'Payroll Period' => $period,
                'Payroll Tax Type' => $tax_type,
                'Payroll Form Type' => $form_type,
                'Payroll Fixed Deductions' => max(0, (float) sanitize_text_field(wp_unslash($_POST['payroll_fixed_deductions'] ?? 0))),
                'Withholding Reason' => sanitize_textarea_field(wp_unslash($_POST['withholding_reason'] ?? '')),
                'Payroll Comments' => sanitize_textarea_field(wp_unslash($_POST['payroll_comments'] ?? '')),
            );

            $wp_user_id = sanitize_text_field(wp_unslash($_POST['wp_user_id'] ?? ''));
            if ($wp_user_id !== '' && is_numeric($wp_user_id)) {
                $employee_fields['WordPress User ID'] = (int) $wp_user_id;
            }

            cleg_center_request('PATCH', CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
                'body' => array(
                    'records' => array(array('id' => $employee_id, 'fields' => $employee_fields)),
                    'typecast' => true,
                ),
            ));

            $profile_id = sanitize_text_field(wp_unslash($_POST['tax_profile_id'] ?? ''));
            $certificate_status = sanitize_text_field(wp_unslash($_POST['certificate_status'] ?? 'Missing'));
            $document_status = sanitize_text_field(wp_unslash($_POST['document_status'] ?? 'Pending Review'));
            $filing_status = sanitize_text_field(wp_unslash($_POST['filing_status'] ?? 'Not Provided'));

            $allowed_certificate = array('Received', 'Missing', 'Expired', 'Not Applicable');
            $allowed_document = array('Pending Review', 'Verified', 'Rejected', 'Expired', 'Not Required');
            $allowed_filing = array('Single', 'Married', 'Married Optional Computation', 'Head of Household', 'Not Provided');

            if (!in_array($certificate_status, $allowed_certificate, true)) {
                $certificate_status = 'Missing';
            }

            if (!in_array($document_status, $allowed_document, true)) {
                $document_status = 'Pending Review';
            }

            if (!in_array($filing_status, $allowed_filing, true)) {
                $filing_status = 'Not Provided';
            }

            $tax_fields = array(
                'Profile Name' => sanitize_text_field(wp_unslash($_POST['employee_name'] ?? 'Empleado')) . ' - Fiscal Profile ' . gmdate('Y'),
                'Employee' => array($employee_id),
                'Effective From' => gmdate('Y') . '-01-01',
                'Filing Status PR' => $filing_status,
                'Dependents' => max(0, (int) sanitize_text_field(wp_unslash($_POST['dependents'] ?? 0))),
                'Deduction Allowance Amount' => max(0, (float) sanitize_text_field(wp_unslash($_POST['deduction_allowance'] ?? 0))),
                'Additional PR Withholding' => max(0, (float) sanitize_text_field(wp_unslash($_POST['additional_pr'] ?? 0))),
                'Exempt PR Withholding' => !empty($_POST['exempt_pr']),
                'FICA Exempt' => !empty($_POST['fica_exempt']),
                'SINOT Exempt' => !empty($_POST['sinot_exempt']),
                'Opening YTD SINOT Wages' => max(0, (float) sanitize_text_field(wp_unslash($_POST['opening_sinot_wages'] ?? 0))),
                'Opening YTD SINOT Paid' => max(0, (float) sanitize_text_field(wp_unslash($_POST['opening_sinot_paid'] ?? 0))),
                'Contractor Withholding Override' => sanitize_text_field(wp_unslash($_POST['contractor_override'] ?? '')) !== '' ? max(0, (float) sanitize_text_field(wp_unslash($_POST['contractor_override']))) / 100 : null,
                'Withholding Certificate Status' => $certificate_status,
                'Document Verification Status' => $document_status,
                'Notes' => sanitize_textarea_field(wp_unslash($_POST['tax_notes'] ?? '')),
            );

            $document_expiration = sanitize_text_field(wp_unslash($_POST['tax_document_expiration'] ?? ''));
            if ($document_expiration !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $document_expiration)) {
                $tax_fields['Document Expiration Date'] = $document_expiration;
            }

            if ($document_status === 'Verified') {
                $current_user = wp_get_current_user();
                $tax_fields['Verified By'] = $current_user->display_name ?: $current_user->user_login;
                $tax_fields['Verified At'] = current_time('c');
            }

            $certificate_url = cleg_center_upload_file('tax_certificate_file');
            if ($certificate_url !== '') {
                $tax_fields['Withholding Certificate File'] = array(array('url' => $certificate_url));
                $tax_fields['Withholding Certificate Status'] = 'Received';
                $tax_fields['Document Verification Status'] = 'Pending Review';
            }

            if ($profile_id !== '') {
                cleg_center_request('PATCH', CLEG_AIRTABLE_TAX_PROFILES_TABLE, array(
                    'body' => array(
                        'records' => array(array('id' => $profile_id, 'fields' => $tax_fields)),
                        'typecast' => true,
                    ),
                ));
            } else {
                cleg_center_request('POST', CLEG_AIRTABLE_TAX_PROFILES_TABLE, array(
                    'body' => array(
                        'records' => array(array('fields' => $tax_fields)),
                        'typecast' => true,
                    ),
                ));
            }

            wp_safe_redirect(add_query_arg(array('employee_id' => $employee_id, 'center_saved' => '1'), home_url('/empleados/')));
            exit;
        }

        if ($action === 'add_employee_document') {
            $file_url = cleg_center_upload_file('employee_document_file');
            $document_type = sanitize_text_field(wp_unslash($_POST['document_type'] ?? 'Otro'));
            $employee_name = sanitize_text_field(wp_unslash($_POST['employee_name'] ?? 'Empleado'));
            $issue_date = sanitize_text_field(wp_unslash($_POST['issue_date'] ?? ''));
            $expiration_date = sanitize_text_field(wp_unslash($_POST['expiration_date'] ?? ''));
            $owner_type = sanitize_text_field(wp_unslash($_POST['document_owner_type'] ?? 'Both'));

            if ($file_url === '') {
                wp_safe_redirect(add_query_arg(array('employee_id' => $employee_id, 'center_error' => 'missing_file'), $redirect));
                exit;
            }

            $doc_fields = array(
                'Document Code' => 'DOC-' . gmdate('Ymd-His') . '-' . cleg_center_slug($employee_name),
                'Employee' => array($employee_id),
                'Document Type' => $document_type,
                'Document File' => array(array('url' => $file_url)),
                'Verification Status' => 'Pending Review',
                'AI Precheck Status' => 'Not Checked',
                'Portal Visible' => !empty($_POST['portal_visible']),
                'Document Owner Type' => in_array($owner_type, array('Employee', 'Contractor', 'Both'), true) ? $owner_type : 'Both',
                'Notes' => sanitize_textarea_field(wp_unslash($_POST['document_notes'] ?? '')),
            );

            if ($issue_date !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $issue_date)) {
                $doc_fields['Issue Date'] = $issue_date;
            }

            if ($expiration_date !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $expiration_date)) {
                $doc_fields['Expiration Date'] = $expiration_date;
            }

            cleg_center_request('POST', CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE, array(
                'body' => array(
                    'records' => array(array('fields' => $doc_fields)),
                    'typecast' => true,
                ),
            ));

            wp_safe_redirect(add_query_arg(array('employee_id' => $employee_id, 'center_saved' => 'document'), $redirect));
            exit;
        }

        if ($action === 'update_employee_document') {
            $document_id = sanitize_text_field(wp_unslash($_POST['document_id'] ?? ''));
            $verification_status = sanitize_text_field(wp_unslash($_POST['verification_status'] ?? 'Pending Review'));
            $allowed_document = array('Pending Review', 'Verified', 'Rejected', 'Expired', 'Not Required');

            if ($document_id !== '' && in_array($verification_status, $allowed_document, true)) {
                $fields = array(
                    'Verification Status' => $verification_status,
                    'Notes' => sanitize_textarea_field(wp_unslash($_POST['document_notes'] ?? '')),
                    'Portal Visible' => !empty($_POST['portal_visible']),
                );

                if ($verification_status === 'Verified') {
                    $current_user = wp_get_current_user();
                    $fields['Verified By'] = $current_user->display_name ?: $current_user->user_login;
                    $fields['Verified At'] = current_time('c');
                }

                cleg_center_request('PATCH', CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE, array(
                    'body' => array(
                        'records' => array(array('id' => $document_id, 'fields' => $fields)),
                        'typecast' => true,
                    ),
                ));
            }

            wp_safe_redirect(add_query_arg(array('employee_id' => $employee_id, 'center_saved' => 'document_status'), $redirect));
            exit;
        }
    }
}

if (!function_exists('cleg_employee_center_shortcode')) {
