                    </header>

                    <?php echo cleg_center_employee_submenu('list'); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
        <?php endif; ?>

                <?php if (isset($_GET['center_saved'])) : ?>
                    <div class="cleg-center-notice">Cambios guardados correctamente.</div>
                <?php endif; ?>

                <?php if (!$selected) : ?>
                    <?php
                    $active_count = 0;
                    $employee_count = 0;
                    $contractor_count = 0;
                    $expiring_count = 0;
                    foreach ($employees as $employee) {
                        $id = sanitize_text_field($employee['id'] ?? '');
                        $status = cleg_center_field($employee, 'Status');
                        $tax_type = cleg_center_field($employee, 'Payroll Tax Type', 'Employee - Full Payroll');
                        $health = cleg_center_document_health($documents[$id] ?? array());
                        if ($status === 'Active') {
                            $active_count++;
