                    $is_employee = $tax_type === 'Employee - Full Payroll';
                    $is_contractor = in_array($tax_type, array('Contractor - 10% Withholding', 'Contractor - No Withholding'), true);
                    $is_admin_no_payroll = $tax_type === 'Admin / No Payroll';
                    $document_options = cleg_center_document_upload_options($required_docs, $tax_type);
                    $payroll_summary = $is_employee ? cleg_center_payroll_summary(cleg_center_payroll_lines($employee_id)) : array();
                    ?>
