                        <div class="hero-badges">
                            <span class="pill <?php echo esc_attr($tax_type === 'Employee - Full Payroll' ? 'ok' : 'neutral'); ?>"><?php echo esc_html($tax_type); ?></span>
                            <span class="pill <?php echo esc_attr(cleg_center_status_class(cleg_center_field($selected, 'Status', 'Active'))); ?>"><?php echo esc_html(cleg_center_field($selected, 'Status', 'Active')); ?></span>
                        </div>
                    </div>

                    <form class="cleg-profile-form" method="post" enctype="multipart/form-data">
                        <?php wp_nonce_field('cleg_center_save', 'cleg_center_nonce'); ?>
                        <input type="hidden" name="cleg_center_action" value="save_employee_profile">
                        <input type="hidden" name="employee_id" value="<?php echo esc_attr($employee_id); ?>">
                        <input type="hidden" name="tax_profile_id" value="<?php echo esc_attr($profile['id']); ?>">

                        <div class="profile-section">
                            <h3>Datos personales</h3>
                            <div class="grid">
                                <label>Nombre<input name="employee_name" value="<?php echo esc_attr(cleg_center_field($selected, 'Employee Name')); ?>"></label>
                                <label>Email<input type="email" name="employee_email" value="<?php echo esc_attr(cleg_center_field($selected, 'Email')); ?>"></label>
                                <label>Telefono<input name="employee_phone" value="<?php echo esc_attr(cleg_center_field($selected, 'Phone')); ?>"></label>
                                <label>Puesto / Departamento<input name="employee_department" value="<?php echo esc_attr(cleg_center_field($selected, 'Department')); ?>"></label>
                                <label>Usuario portal<input name="portal_username" value="<?php echo esc_attr(cleg_center_field($selected, 'Portal Username')); ?>"></label>
                                <label>WordPress User ID<input type="number" min="0" name="wp_user_id" value="<?php echo esc_attr(cleg_center_field($selected, 'WordPress User ID')); ?>"></label>
                                <label>Rol<?php echo cleg_center_employee_role_select(cleg_center_field($selected, 'Role', 'Trabajador')); ?></label>
                                <label>Estado<select name="employee_status"><option value="Active" <?php selected(cleg_center_field($selected, 'Status'), 'Active'); ?>>Active</option><option value="Inactive" <?php selected(cleg_center_field($selected, 'Status'), 'Inactive'); ?>>Inactive</option></select></label>
                            </div>
                        </div>

                        <div class="profile-section">
                            <h3>Payroll</h3>
                            <div class="grid">
                                <label>Tipo de trabajador / payroll
                                    <select name="payroll_tax_type">
                                        <option value="Employee - Full Payroll" <?php selected($tax_type, 'Employee - Full Payroll'); ?>>Empleado - payroll completo</option>
                                        <option value="Contractor - 10% Withholding" <?php selected($tax_type, 'Contractor - 10% Withholding'); ?>>Contratista - retencion 10%</option>
                                        <option value="Contractor - No Withholding" <?php selected($tax_type, 'Contractor - No Withholding'); ?>>Contratista - sin retencion / relevo</option>
                                        <option value="Admin / No Payroll" <?php selected($tax_type, 'Admin / No Payroll'); ?>>Administrativo / sin payroll</option>
                                    </select>
                                    <small>Este campo solo se cambia aqui. Payroll lo lee en modo consulta.</small>
                                </label>
                                <?php if ($is_employee) : ?>
                                <label class="checkline"><input type="checkbox" name="sinot_exempt" value="1" <?php checked($profile['sinot_exempt']); ?>> Exento SINOT / no descontar SINOT</label>
                                <label>Salarios SINOT previos<input type="number" min="0" step="0.01" name="opening_sinot_wages" value="<?php echo esc_attr($profile['opening_sinot_wages']); ?>"></label>
                                <label>SINOT pagado previo<input type="number" min="0" step="0.01" name="opening_sinot_paid" value="<?php echo esc_attr($profile['opening_sinot_paid']); ?>"></label>
                                <label>Payroll Amount<input type="number" step="0.01" min="0" name="payroll_amount" value="<?php echo esc_attr(cleg_center_money_value(cleg_center_raw($selected, 'Payroll Amount', 0))); ?>"></label>
                                <label>Payroll Period
                                    <select name="payroll_period">
                                        <option value="Per Hour" <?php selected(cleg_center_field($selected, 'Payroll Period'), 'Per Hour'); ?>>Por hora</option>
                                        <option value="Per Day" <?php selected(cleg_center_field($selected, 'Payroll Period'), 'Per Day'); ?>>Por dia</option>
                                        <option value="Biweekly" <?php selected(cleg_center_field($selected, 'Payroll Period'), 'Biweekly'); ?>>Quincenal</option>
                                        <option value="Fixed Per Period" <?php selected(cleg_center_field($selected, 'Payroll Period'), 'Fixed Per Period'); ?>>Fijo por periodo</option>
                                    </select>
