                                <label>Forma fiscal
                                    <select name="payroll_form_type">
                                        <option value="W-2PR / 499R-2" <?php selected(cleg_center_field($selected, 'Payroll Form Type'), 'W-2PR / 499R-2'); ?>>W-2PR / 499R-2</option>
                                        <option value="480.6SP" <?php selected(cleg_center_field($selected, 'Payroll Form Type'), '480.6SP'); ?>>480.6SP</option>
