                                <label>Deducciones fijas<input type="number" step="0.01" min="0" name="payroll_fixed_deductions" value="<?php echo esc_attr(cleg_center_money_value(cleg_center_raw($selected, 'Payroll Fixed Deductions', 0))); ?>"></label>
                                <label class="wide">Notas de payroll<textarea name="payroll_comments" rows="2"><?php echo esc_textarea(cleg_center_field($selected, 'Payroll Comments')); ?></textarea></label>
                                <?php elseif ($is_contractor) : ?>
                                <label>Forma fiscal
                                    <select name="payroll_form_type">
                                        <option value="480.6SP" <?php selected(cleg_center_field($selected, 'Payroll Form Type'), '480.6SP'); ?>>480.6SP</option>
