                                <label>Retencion contratista %<input type="number" min="0" step="0.01" name="contractor_override" value="<?php echo esc_attr($profile['contractor_override'] !== '' ? cleg_center_money_value(((float) $profile['contractor_override']) * 100) : ''); ?>"></label>
                                <label class="wide">Razon sin retencion / notas de relevo<textarea name="withholding_reason" rows="2"><?php echo esc_textarea(cleg_center_field($selected, 'Withholding Reason')); ?></textarea></label>
                                <label class="wide">Notas de pago contratista<textarea name="payroll_comments" rows="2"><?php echo esc_textarea(cleg_center_field($selected, 'Payroll Comments')); ?></textarea></label>
                                <?php else : ?>
                                <input type="hidden" name="payroll_form_type" value="No aplica / revisar">
                                <input type="hidden" name="payroll_amount" value="0">
                                <input type="hidden" name="payroll_period" value="Per Hour">
                                <input type="hidden" name="payroll_fixed_deductions" value="0">
                                <label class="wide">Notas administrativas<textarea name="payroll_comments" rows="2"><?php echo esc_textarea(cleg_center_field($selected, 'Payroll Comments')); ?></textarea></label>
