                                    <select name="filing_status">
                                        <option value="Not Provided" <?php selected($profile['filing_status'], 'Not Provided'); ?>>No provisto</option>
                                        <option value="Single" <?php selected($profile['filing_status'], 'Single'); ?>>Soltero</option>
                                        <option value="Married" <?php selected($profile['filing_status'], 'Married'); ?>>Casado</option>
                                        <option value="Married Optional Computation" <?php selected($profile['filing_status'], 'Married Optional Computation'); ?>>Casado computo opcional</option>
                                        <option value="Head of Household" <?php selected($profile['filing_status'], 'Head of Household'); ?>>Jefe de familia</option>
                                    </select>
                                </label>
                                <label>Dependientes<input type="number" min="0" step="1" name="dependents" value="<?php echo esc_attr((string) (int) $profile['dependents']); ?>"></label>
                                <label>Concesion / deduccion<input type="number" min="0" step="0.01" name="deduction_allowance" value="<?php echo esc_attr($profile['deduction_allowance']); ?>"></label>
                                <label>Retencion PR adicional<input type="number" min="0" step="0.01" name="additional_pr" value="<?php echo esc_attr($profile['additional_pr']); ?>"></label>
                                <?php else : ?>
