                                <input type="hidden" name="dependents" value="0">
                                <input type="hidden" name="deduction_allowance" value="0">
                                <input type="hidden" name="additional_pr" value="0">
                                <label>Override contratista %<input type="number" min="0" step="0.01" name="contractor_override" value="<?php echo esc_attr($profile['contractor_override'] !== '' ? cleg_center_money_value(((float) $profile['contractor_override']) * 100) : ''); ?>"></label>
                                <?php endif; ?>
