                                    <select name="certificate_status">
                                        <option value="Missing" <?php selected($profile['certificate_status'], 'Missing'); ?>>Falta</option>
                                        <option value="Received" <?php selected($profile['certificate_status'], 'Received'); ?>>Recibido</option>
                                        <option value="Expired" <?php selected($profile['certificate_status'], 'Expired'); ?>>Expirado</option>
                                        <option value="Not Applicable" <?php selected($profile['certificate_status'], 'Not Applicable'); ?>>No aplica</option>
                                    </select>
                                </label>
                                <label>Verificacion
