                                        <option value="Pending Review" <?php selected($profile['document_status'], 'Pending Review'); ?>>Pendiente revisar</option>
                                        <option value="Verified" <?php selected($profile['document_status'], 'Verified'); ?>>Verificado</option>
                                        <option value="Rejected" <?php selected($profile['document_status'], 'Rejected'); ?>>Rechazado</option>
                                        <option value="Expired" <?php selected($profile['document_status'], 'Expired'); ?>>Expirado</option>
                                        <option value="Not Required" <?php selected($profile['document_status'], 'Not Required'); ?>>No requerido</option>
                                    </select>
                                </label>
                                <label>Expira<input type="date" name="tax_document_expiration" value="<?php echo esc_attr($profile['document_expiration']); ?>"></label>
                                <label>Adjuntar <?php echo esc_html($is_employee ? '499 R-4' : 'W-9 / relevo'); ?><input type="file" name="tax_certificate_file" accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx"></label>
                                <?php if ($is_employee) : ?>
                                <label class="checkline"><input type="checkbox" name="exempt_pr" value="1" <?php checked($profile['exempt_pr']); ?>> Exento retencion PR</label>
