                        <input type="hidden" name="deduction_allowance" value="0">
                        <input type="hidden" name="additional_pr" value="0">
                        <input type="hidden" name="certificate_status" value="Not Applicable">
                        <input type="hidden" name="document_status" value="Not Required">
                        <input type="hidden" name="contractor_override" value="">
                        <?php endif; ?>

                        <button class="primary-save" style="display:flex;margin:14px auto 0;" type="submit">Guardar expediente</button>
