                                    $required_name = cleg_center_field($required_doc, 'Required Document');
                                    $uploaded = cleg_center_required_document_uploaded($required_name, $employee_docs);
                                    ?>
                                    <span class="pill <?php echo esc_attr($uploaded ? 'ok' : 'warn'); ?>"><?php echo esc_html($required_name); ?> · <?php echo esc_html($uploaded ? 'cargado' : 'pendiente'); ?></span>
                                <?php endforeach; ?>
                            </div>
                        <?php endif; ?>
