                            <input type="hidden" name="cleg_center_action" value="add_employee_document">
                            <input type="hidden" name="employee_id" value="<?php echo esc_attr($employee_id); ?>">
                            <input type="hidden" name="employee_name" value="<?php echo esc_attr(cleg_center_field($selected, 'Employee Name')); ?>">
                            <div class="grid">
                                <label>Tipo documento<select name="document_type"><?php foreach ($document_options as $option_value => $option_label) : ?><option value="<?php echo esc_attr($option_value); ?>"><?php echo esc_html($option_label); ?></option><?php endforeach; ?></select></label>
