                                <label>Expiracion<input type="date" name="expiration_date"></label>
                                <label>Aplica a<select name="document_owner_type"><option value="<?php echo esc_attr($is_employee ? 'Employee' : ($is_contractor ? 'Contractor' : 'Both')); ?>"><?php echo esc_html($is_employee ? 'Employee' : ($is_contractor ? 'Contractor' : 'Both')); ?></option><option>Both</option><option>Employee</option><option>Contractor</option></select></label>
                                <label class="checkline"><input type="checkbox" name="portal_visible" value="1"> Visible en portal</label>
                                <label class="wide">Notas<textarea name="document_notes" rows="2"></textarea></label>
                            </div>
                            <button class="secondary-save" type="submit">Subir documento</button>
                        </form>

                        <div class="doc-list">
                            <?php if (empty($employee_docs)) : ?>
                                <p class="empty-copy">Todavia no hay documentos cargados para este trabajador.</p>
                            <?php endif; ?>
                            <?php foreach ($employee_docs as $document) : ?>
                                <?php
                                $doc_id = sanitize_text_field($document['id'] ?? '');
                                $status = cleg_center_field($document, 'Verification Status', 'Pending Review');
                                $expiration = cleg_center_field($document, 'Expiration Date');
                                $files = cleg_center_raw($document, 'Document File', array());
                                $file_url = is_array($files) && !empty($files[0]['url']) ? esc_url($files[0]['url']) : '';
                                ?>
                                <form class="doc-card" method="post">
                                    <?php wp_nonce_field('cleg_center_save', 'cleg_center_nonce'); ?>
                                    <input type="hidden" name="cleg_center_action" value="update_employee_document">
                                    <input type="hidden" name="employee_id" value="<?php echo esc_attr($employee_id); ?>">
                                    <input type="hidden" name="document_id" value="<?php echo esc_attr($doc_id); ?>">
                                    <div>
                                        <strong><?php echo esc_html(cleg_center_field($document, 'Document Type')); ?></strong>
                                        <small><?php echo esc_html(cleg_center_field($document, 'Document Code')); ?></small>
                                        <span class="pill <?php echo esc_attr(cleg_center_status_class($status, $expiration)); ?>"><?php echo esc_html($status); ?></span>
                                        <?php if ($expiration !== '') : ?><small>Expira: <?php echo esc_html($expiration); ?></small><?php endif; ?>
                                    </div>
                                    <div class="doc-actions">
                                        <?php if ($file_url !== '') : ?><a href="<?php echo esc_url($file_url); ?>" target="_blank" rel="noopener">Ver archivo</a><?php endif; ?>
                                        <select name="verification_status">
                                            <option value="Pending Review" <?php selected($status, 'Pending Review'); ?>>Pendiente</option>
                                            <option value="Verified" <?php selected($status, 'Verified'); ?>>Verificado</option>
                                            <option value="Rejected" <?php selected($status, 'Rejected'); ?>>Rechazado</option>
                                            <option value="Expired" <?php selected($status, 'Expired'); ?>>Expirado</option>
                                            <option value="Not Required" <?php selected($status, 'Not Required'); ?>>No requerido</option>
                                        </select>
                                        <label class="checkline"><input type="checkbox" name="portal_visible" value="1" <?php checked(cleg_center_bool(cleg_center_raw($document, 'Portal Visible', false))); ?>> Portal</label>
                                        <textarea name="document_notes" rows="2"><?php echo esc_textarea(cleg_center_field($document, 'Notes')); ?></textarea>
                                        <button type="submit">Actualizar</button>
                                    </div>
                                </form>
                            <?php endforeach; ?>
                        </div>
                    </div>

                    <?php if ($is_employee) : ?>
                        <?php echo cleg_center_leave_panel($selected); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                    <?php endif; ?>
                <?php endif; ?>
                </div>
                <?php echo cleg_center_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                <?php echo cleg_center_leave_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                <?php echo cleg_center_bridge_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                <?php if ($use_common_shell) : ?>
                    <?php echo cleg_center_embedded_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                </div>
                    <?php echo cleg_admin_page_close(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
                <?php else : ?>
            </section>
                <?php endif; ?>
        <?php
        return ob_get_clean();
    }
}

if (!function_exists('cleg_center_leave_styles')) {
    function cleg_center_leave_styles() {
        return '<style>.leave-section .leave-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:12px}.leave-section .leave-head p{margin:0!important;color:#506174!important;font-weight:700;line-height:1.45}.leave-balances{display:flex;gap:8px;flex-wrap:wrap}.leave-balances span{display:inline-flex;gap:8px;align-items:center;border:1px solid rgba(7,24,39,.12);border-radius:8px;background:#f8fafc!important;padding:8px 10px;color:#506174!important;font-weight:900}.leave-balances strong{color:#071827!important}.leave-drawer{border:1px solid rgba(7,24,39,.1);border-radius:12px;background:#f8fafc!important;padding:0;margin-bottom:14px}.leave-drawer summary{display:flex;align-items:center;justify-content:space-between;gap:12px;cursor:pointer;padding:13px 14px;font-weight:900;color:#071827!important}.leave-drawer summary b{font-size:12px;border-radius:999px;background:#182537!important;color:#fff!important;-webkit-text-fill-color:#fff!important;padding:6px 10px}.leave-form{padding:0 14px 14px}.leave-history{margin-top:10px}.leave-table-wrap{overflow:auto;border:1px solid rgba(7,24,39,.1);border-radius:12px;background:#fff!important}.leave-table-wrap table{min-width:760px!important}.leave-table-wrap th,.leave-table-wrap td{padding:11px 10px!important}@media(max-width:720px){.leave-section .leave-head{display:grid}.leave-balances{display:grid;grid-template-columns:1fr}.leave-drawer summary{align-items:flex-start}.leave-drawer summary b{white-space:nowrap}}</style>';
    }
}

