if (!function_exists('cleg_center_employee_submenu')) {
    function cleg_center_employee_submenu($active = 'list') {
        $items = array(
            'list' => array(home_url('/admin-empleados/'), 'Trabajadores'),
        );
        $links = '';

        foreach ($items as $key => $item) {
            $links .= '<a' . ($active === $key ? ' class="is-active"' : '') . ' href="' . esc_url($item[0]) . '">' . esc_html($item[1]) . '</a>';
        }

        return '<nav class="cleg-subnav cleg-employee-center-submenu" aria-label="Submenu Trabajadores">' . $links . '</nav>';
    }
}

if (!function_exists('cleg_center_redirect_legacy_roles_tab')) {
    function cleg_center_redirect_legacy_roles_tab() {
        if (is_admin() || wp_doing_ajax() || !is_page('admin-empleados')) {
            return;
        }

        $is_roles_tab = isset($_GET['cleg_roles']) && sanitize_text_field(wp_unslash($_GET['cleg_roles'])) === '1';
        if (!$is_roles_tab) {
            return;
        }

        $target = function_exists('cleg_starter_roles_admin_url')
            ? cleg_starter_roles_admin_url()
            : add_query_arg('cleg_tenant_tab', 'roles', home_url('/administracion/'));

        wp_safe_redirect($target);
        exit;
    }
}

add_action('template_redirect', 'cleg_center_redirect_legacy_roles_tab', 1);

if (!function_exists('cleg_center_admin_empleados_bridge')) {
    function cleg_center_admin_empleados_bridge($content) {
        if (!is_page('admin-empleados') || !in_the_loop() || !is_main_query() || !cleg_center_allowed()) {
            return $content;
        }

        $bridge = cleg_center_employee_submenu('list');
        $styled_content = $content . cleg_center_bridge_styles();

        if (false !== strpos($styled_content, '</nav>')) {
            return preg_replace('/<\/nav>/', '</nav>' . $bridge, $styled_content, 1);
        }

        return $bridge . $styled_content;
    }
}

if (!function_exists('cleg_center_roles_submenu_after_starter')) {
    function cleg_center_roles_submenu_after_starter($content) {
        if (!is_page('admin-empleados') || !in_the_loop() || !is_main_query() || !cleg_center_allowed()) {
            return $content;
        }

        $is_roles_tab = isset($_GET['cleg_roles']) && sanitize_text_field(wp_unslash($_GET['cleg_roles'])) === '1';
        if (!$is_roles_tab || false !== strpos($content, 'cleg-employee-center-submenu')) {
            return $content;
        }

        return $content . cleg_center_bridge_styles();
    }
}

if (!function_exists('cleg_employee_center_auto_page')) {
    function cleg_employee_center_auto_page($content) {
        if (!is_page('empleados') || !in_the_loop() || !is_main_query()) {
            return $content;
        }

        if (has_shortcode($content, 'cleg_employee_center')) {
            return $content;
        }

        return do_shortcode('[cleg_employee_center]');
    }
}

