/**
 * BEGIN modulos/09-documents/16-cleg-15-employee-documents-portal-v1.php
 * Module: hr_core
 * Target: 01-Snippets-Activos/16-cleg-15-employee-documents-portal-v1.php
 * Source path: modulos/09-documents/16-cleg-15-employee-documents-portal-v1.php
 */
/**
 * CLEG 15 - Employee Documents Portal v1.3
 */
/**
 * CLEG 15 - Employee Documents Portal v1
 */
/**
 * Vantrexor
 * Snippet: Portal del trabajador - Mis documentos v1
 * Shortcode: [cleg_employee_documents]
 * Compatible con Code Snippets.
 *
 * Proposito:
 * - Permitir que el trabajador consulte documentos visibles desde Employee Center.
 * - Mostrar vencimientos y estados sin permitir modificaciones.
 * - Montar automaticamente el modulo en /mis-documentos/ aunque la pagina este vacia.
 *
 * Pegar sin la primera linea <?php en Code Snippets.
 * v1.3 enlaza usuario autenticado por prioridad exacta y filtra documentos/nominas por record ID exacto.
 * v1.2 separa vista Employee/Contractor y agrega resumen payroll/PTO en documentos del trabajador.
 * v1.1 aplica Fase 2 visual: encabezado oscuro grande y botones consistentes, sin tocar logica ni Airtable.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!defined('CLEG_ADMIN_AIRTABLE_TOKEN')) {
    if (defined('CLEG_RRHH_AIRTABLE_PAT') && CLEG_RRHH_AIRTABLE_PAT) {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', CLEG_RRHH_AIRTABLE_PAT);
    } elseif (defined('CLEG_AIRTABLE_PAT') && CLEG_AIRTABLE_PAT) {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', CLEG_AIRTABLE_PAT);
    } elseif (function_exists('cleg_secure_config_get')) {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', cleg_secure_config_get('admin_airtable_token', cleg_secure_config_get('airtable_pat', '')));
    } else {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', '');
    }
}

if (!defined('CLEG_AIRTABLE_BASE_ID')) {
    define('CLEG_AIRTABLE_BASE_ID', function_exists('cleg_secure_config_get') ? cleg_secure_config_get('admin_airtable_base_id', cleg_secure_config_get('airtable_base_id', '')) : '');
}

if (!defined('CLEG_AIRTABLE_EMPLOYEES_TABLE')) {
    define('CLEG_AIRTABLE_EMPLOYEES_TABLE', 'Employees');
}

if (!defined('CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE')) {
    define('CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE', 'Employee Documents');
}

if (!defined('CLEG_AIRTABLE_PAYROLL_LINES_TABLE')) {
    define('CLEG_AIRTABLE_PAYROLL_LINES_TABLE', 'Payroll Calculation Lines');
}

if (!function_exists('cleg_docs_ready')) {
    function cleg_docs_ready() {
        if (function_exists('cleg_integrations_airtable_ready')) {
            return cleg_integrations_airtable_ready('documents')
                || cleg_integrations_airtable_ready('hr_core')
                || cleg_integrations_airtable_ready('payroll');
        }

        return CLEG_ADMIN_AIRTABLE_TOKEN !== '' && CLEG_ADMIN_AIRTABLE_TOKEN !== 'REEMPLAZAR_AIRTABLE_PAT';
    }
}

if (!function_exists('cleg_docs_airtable_module_for_table')) {
    function cleg_docs_airtable_module_for_table($table) {
        $table = (string) $table;

        if (defined('CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE') && $table === CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE) {
            return 'documents';
        }

        if (defined('CLEG_AIRTABLE_PAYROLL_LINES_TABLE') && $table === CLEG_AIRTABLE_PAYROLL_LINES_TABLE) {
            return 'payroll';
        }

        return 'hr_core';
    }
}

if (!function_exists('cleg_docs_request')) {
    function cleg_docs_request($method, $table, $args = array()) {
        if (function_exists('cleg_integrations_airtable_request')) {
            $query = (!empty($args['query']) && is_array($args['query'])) ? $args['query'] : array();
            $body = !empty($args['body']) ? $args['body'] : null;
            if (!empty($args['record_id'])) {
                $query['record_id'] = sanitize_text_field((string) $args['record_id']);
            }

            return cleg_integrations_airtable_request(cleg_docs_airtable_module_for_table($table), $method, $table, $query, $body);
        }

        if (!cleg_docs_ready()) {
            return new WP_Error('cleg_docs_token', 'Airtable no esta configurado.');
        }

        $url = 'https://api.airtable.com/v0/' . rawurlencode(CLEG_AIRTABLE_BASE_ID) . '/' . rawurlencode($table);

        if (!empty($args['query']) && is_array($args['query'])) {
            $url = add_query_arg($args['query'], $url);
        }

        $request = array(
            'method' => $method,
            'timeout' => 20,
            'headers' => array(
                'Authorization' => 'Bearer ' . CLEG_ADMIN_AIRTABLE_TOKEN,
                'Content-Type' => 'application/json',
            ),
        );

        if (!empty($args['body'])) {
            $request['body'] = wp_json_encode($args['body']);
        }

        $response = wp_remote_request($url, $request);

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        $body = json_decode(wp_remote_retrieve_body($response), true);

        if ($code < 200 || $code >= 300) {
            $message = isset($body['error']['message']) ? $body['error']['message'] : 'Airtable rechazo la solicitud.';
            return new WP_Error('cleg_docs_airtable', $message);
        }

        return is_array($body) ? $body : array();
    }
}

if (!function_exists('cleg_docs_records')) {
    function cleg_docs_records($table, $query = array()) {
        $records = array();
        $offset = '';

        do {
            $page_query = $query;
            $page_query['pageSize'] = 100;

            if ($offset !== '') {
                $page_query['offset'] = $offset;
            }

            $response = cleg_docs_request('GET', $table, array('query' => $page_query));

            if (is_wp_error($response)) {
                return $response;
            }

            $records = array_merge($records, $response['records'] ?? array());
            $offset = isset($response['offset']) ? sanitize_text_field($response['offset']) : '';
        } while ($offset !== '');

        return $records;
    }
}

if (!function_exists('cleg_docs_formula_text')) {
    function cleg_docs_formula_text($value) {
        return str_replace("'", "\\'", (string) $value);
    }
}

if (!function_exists('cleg_docs_employee_by_formula')) {
    function cleg_docs_employee_by_formula($formula) {
        $employees = cleg_docs_records(CLEG_AIRTABLE_EMPLOYEES_TABLE, array(
            'filterByFormula' => $formula,
            'maxRecords' => 1,
        ));

        if (is_wp_error($employees) || empty($employees[0])) {
            return null;
        }

        return $employees[0];
    }
}

if (!function_exists('cleg_docs_record_links_include')) {
    function cleg_docs_record_links_include($record, $field, $record_id) {
        $record_id = sanitize_text_field((string) $record_id);
        $links = cleg_docs_raw($record, $field, array());

        if ($record_id === '' || !is_array($links)) {
            return false;
        }

        foreach ($links as $link) {
            if (is_array($link) && sanitize_text_field((string) ($link['id'] ?? '')) === $record_id) {
                return true;
            }

            if (is_scalar($link) && sanitize_text_field((string) $link) === $record_id) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg_docs_field')) {
    function cleg_docs_field($record, $field, $default = '') {
        $fields = $record['fields'] ?? array();
        $value = $fields[$field] ?? $default;

        if (is_array($value) && isset($value['name'])) {
            return sanitize_text_field($value['name']);
        }

        return is_scalar($value) ? sanitize_text_field((string) $value) : $default;
    }
}

if (!function_exists('cleg_docs_raw')) {
    function cleg_docs_raw($record, $field, $default = null) {
        $fields = $record['fields'] ?? array();
        return array_key_exists($field, $fields) ? $fields[$field] : $default;
    }
}

if (!function_exists('cleg_docs_number')) {
    function cleg_docs_number($value, $default = 0) {
        if ($value === '' || $value === null) {
            return (float) $default;
        }

        return is_numeric($value) ? (float) $value : (float) $default;
    }
}

if (!function_exists('cleg_docs_date')) {
    function cleg_docs_date($value) {
        $timestamp = strtotime((string) $value);
        return $timestamp ? wp_date('m/d/Y', $timestamp) : '';
    }
}

if (!function_exists('cleg_docs_employee')) {
    function cleg_docs_employee() {
        $user = wp_get_current_user();
        if (!$user || empty($user->ID)) {
            return null;
        }

        $employee = cleg_docs_employee_by_formula('{WordPress User ID}=' . (int) $user->ID);
        if ($employee) {
            return $employee;
        }

        if (!empty($user->user_login)) {
            $username = cleg_docs_formula_text(sanitize_user($user->user_login));
            $employee = cleg_docs_employee_by_formula("LOWER({Portal Username})=LOWER('{$username}')");
            if ($employee) {
                return $employee;
            }
        }

        if (!empty($user->user_email)) {
            $email = cleg_docs_formula_text(sanitize_email($user->user_email));
            $employee = cleg_docs_employee_by_formula("LOWER({Email})=LOWER('{$email}')");
            if ($employee) {
                return $employee;
            }
        }

        return null;
    }
}

if (!function_exists('cleg_docs_payroll_lines')) {
    function cleg_docs_payroll_lines($employee_id, $limit = 24) {
        $employee_id = sanitize_text_field((string) $employee_id);
        if ($employee_id === '') {
            return array();
        }

        $lines = cleg_docs_records(CLEG_AIRTABLE_PAYROLL_LINES_TABLE, array(
            'sort[0][field]' => 'Period End',
            'sort[0][direction]' => 'desc',
            'maxRecords' => 100,
        ));

        if (is_wp_error($lines)) {
            return array();
        }

        $matched = array_values(array_filter($lines, function ($line) use ($employee_id) {
            return cleg_docs_record_links_include($line, 'Employee', $employee_id);
        }));

        return array_slice($matched, 0, max(1, min(100, (int) $limit)));
    }
}

if (!function_exists('cleg_docs_payroll_summary')) {
    function cleg_docs_payroll_summary($lines) {
        $summary = array(
            'periods' => 0,
            'hours' => 0,
            'gross_pay' => 0,
            'net_pay' => 0,
            'contractor_withholding' => 0,
            'last_period' => '',
            'vacation_accrued' => 0,
            'sick_accrued' => 0,
        );

        foreach ($lines as $line) {
            $summary['periods']++;
            $detail = json_decode((string) cleg_docs_raw($line, 'Calculation Detail JSON', ''), true);
            $hours = is_array($detail) && isset($detail['hours']['total']) ? $detail['hours']['total'] : (cleg_docs_number(cleg_docs_raw($line, 'Regular Hours'), 0) + cleg_docs_number(cleg_docs_raw($line, 'Overtime Hours'), 0));
            $summary['hours'] += cleg_docs_number($hours, 0);
            $summary['gross_pay'] += cleg_docs_number(cleg_docs_raw($line, 'Gross Pay'), 0);
            $summary['net_pay'] += cleg_docs_number(cleg_docs_raw($line, 'Net Pay'), 0);
            $summary['contractor_withholding'] += cleg_docs_number(cleg_docs_raw($line, 'Contractor Withholding'), 0);
            $summary['vacation_accrued'] += cleg_docs_number(cleg_docs_raw($line, 'Vacation Accrued Hours'), 0);
            $summary['sick_accrued'] += cleg_docs_number(cleg_docs_raw($line, 'Sick Accrued Hours'), 0);
            if ($summary['last_period'] === '') {
                $summary['last_period'] = cleg_docs_date(cleg_docs_field($line, 'Period End'));
            }
        }

        return $summary;
    }
}

if (!function_exists('cleg_docs_file_info')) {
    function cleg_docs_file_info($document) {
        $files = cleg_docs_raw($document, 'Document File', array());
        return array(
            'url' => is_array($files) && !empty($files[0]['url']) ? esc_url($files[0]['url']) : '',
            'name' => is_array($files) && !empty($files[0]['filename']) ? sanitize_text_field($files[0]['filename']) : cleg_docs_field($document, 'Document Type', 'Documento'),
        );
    }
}

if (!function_exists('cleg_docs_find_w9')) {
    function cleg_docs_find_w9($documents) {
        foreach ($documents as $document) {
            $type = strtolower(cleg_docs_field($document, 'Document Type', ''));
            $code = strtolower(cleg_docs_field($document, 'Document Code', ''));
            if (strpos($type, 'w-9') !== false || strpos($type, 'w9') !== false || strpos($code, 'w-9') !== false || strpos($code, 'w9') !== false) {
                return $document;
            }
        }

        return null;
    }
}

if (!function_exists('cleg_docs_for_employee')) {
    function cleg_docs_for_employee($employee_id, $tax_type) {
        $employee_id = sanitize_text_field((string) $employee_id);
        $tax_type = sanitize_text_field((string) $tax_type);

        if ($employee_id === '') {
            return array();
        }

        $owner = $tax_type === 'Employee - Full Payroll' ? 'Employee' : 'Contractor';
        $owner = cleg_docs_formula_text($owner);
        $formula = "AND({Portal Visible}=TRUE(),OR({Document Owner Type}='Both',{Document Owner Type}='{$owner}',{Document Owner Type}=BLANK()))";

        $documents = cleg_docs_records(CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE, array(
            'filterByFormula' => $formula,
            'sort[0][field]' => 'Expiration Date',
            'sort[0][direction]' => 'asc',
            'maxRecords' => 100,
        ));

        if (is_wp_error($documents)) {
            return array();
        }

        return array_values(array_filter($documents, function ($document) use ($employee_id) {
            return cleg_docs_record_links_include($document, 'Employee', $employee_id);
        }));
    }
}

if (!function_exists('cleg_docs_status')) {
    function cleg_docs_status($record) {
        $status = cleg_docs_field($record, 'Verification Status', 'Pending Review');
        $expiration = cleg_docs_field($record, 'Expiration Date');
        $class = 'warn';
        $label = $status;

        if ($expiration !== '') {
            $ts = strtotime($expiration . ' 23:59:59');
            if ($ts && $ts < current_time('timestamp')) {
                return array('class' => 'danger', 'label' => 'Expirado', 'hint' => 'Vencio el ' . cleg_docs_date($expiration));
            }
            if ($ts && $ts <= current_time('timestamp') + (30 * DAY_IN_SECONDS)) {
                return array('class' => 'warn', 'label' => 'Vence pronto', 'hint' => 'Expira el ' . cleg_docs_date($expiration));
            }
        }

        if ($status === 'Verified' || $status === 'Not Required') {
            $class = 'ok';
        } elseif ($status === 'Rejected' || $status === 'Expired') {
            $class = 'danger';
        }

        $hint = $expiration !== '' ? 'Expira el ' . cleg_docs_date($expiration) : 'Sin expiracion registrada';
        return array('class' => $class, 'label' => $label, 'hint' => $hint);
    }
}

if (!function_exists('cleg_employee_documents_shortcode')) {
    function cleg_employee_documents_shortcode() {
        if (!is_user_logged_in()) {
            return '<section class="cleg-docs"><div class="empty"><h2>Acceso requerido</h2><p>Inicia sesion para ver tus documentos.</p></div>' . cleg_docs_styles() . '</section>';
        }

        if (!cleg_docs_ready()) {
            return '<section class="cleg-docs"><div class="empty"><h2>Conexion pendiente</h2><p>La oficina aun no configuro la conexion de documentos.</p></div>' . cleg_docs_styles() . '</section>';
        }

        $employee = cleg_docs_employee();
        if (!$employee) {
            return '<section class="cleg-docs"><div class="empty"><h2>No encontramos tu ficha</h2><p>Comunicate con oficina para enlazar tu acceso de trabajador.</p></div>' . cleg_docs_styles() . '</section>';
        }

        $employee_id = sanitize_text_field($employee['id'] ?? '');
        $name = cleg_docs_field($employee, 'Employee Name');
        $tax_type = cleg_docs_field($employee, 'Payroll Tax Type', 'Employee - Full Payroll');
        $is_employee = $tax_type === 'Employee - Full Payroll';
        $retention_percent = cleg_docs_number(cleg_docs_raw($employee, 'Payroll Retention Percent'), 0);
        if ($retention_percent > 0 && $retention_percent <= 1) {
            $retention_percent *= 100;
        }
        $payroll_lines = cleg_docs_payroll_lines($employee_id);
        $payroll_summary = cleg_docs_payroll_summary($payroll_lines);
        $documents = cleg_docs_for_employee($employee_id, $tax_type);
        $latest_line = !empty($payroll_lines[0]) ? $payroll_lines[0] : null;
        $latest_gross = $latest_line ? cleg_docs_number(cleg_docs_raw($latest_line, 'Gross Pay'), 0) : 0;
        $latest_net = $latest_line ? cleg_docs_number(cleg_docs_raw($latest_line, 'Net Pay'), 0) : 0;
        $latest_deductions = max(0, $latest_gross - $latest_net);
        $latest_period = $latest_line ? cleg_docs_date(cleg_docs_field($latest_line, 'Period End')) : '';
        $w9_document = cleg_docs_find_w9($documents);
        $w9_file = $w9_document ? cleg_docs_file_info($w9_document) : array('url' => '', 'name' => '');

        ob_start();
        ?>
        <section class="cleg-docs">
            <div class="shell">
                <header class="hero">
                    <div>
                        <p>Portal del trabajador</p>
                        <h2>Mis documentos</h2>
                        <span><?php echo esc_html($name); ?></span>
                    </div>
                    <a class="back-btn" href="<?php echo esc_url(home_url('/panel/')); ?>">Volver al panel</a>
                </header>

                <?php if ($is_employee) : ?>
                    <?php if ($latest_line) : ?>
                    <div class="simple-paystub employee">
                        <div class="stub-head">
                            <div><small>Payroll mas reciente</small><strong><?php echo esc_html($latest_period !== '' ? $latest_period : 'Sin cierre aun'); ?></strong></div>
                            <a href="<?php echo esc_url(home_url('/mis-nominas/')); ?>">Ver mi Payroll</a>
                        </div>
                        <div class="stub-grid">
                            <span><small>Gross pay</small><strong>$<?php echo esc_html(number_format($latest_gross, 2)); ?></strong></span>
                            <span><small>Deducciones</small><strong>$<?php echo esc_html(number_format($latest_deductions, 2)); ?></strong></span>
                            <span class="net"><small>Net pay</small><strong>$<?php echo esc_html(number_format($latest_net, 2)); ?></strong></span>
                        </div>
                    </div>
                    <div class="pto-simple">
                        <span><small>Vacaciones disponibles</small><strong><?php echo esc_html(number_format(cleg_docs_number(cleg_docs_raw($employee, 'PTO Vacation Balance Hours'), 0), 2)); ?> h</strong></span>
                        <span><small>Enfermedad disponible</small><strong><?php echo esc_html(number_format(cleg_docs_number(cleg_docs_raw($employee, 'PTO Sick Balance Hours'), 0), 2)); ?> h</strong></span>
                    </div>
                    <?php else : ?>
                    <div class="empty"><h2>Payroll aún no publicado</h2><p>La oficina todavía no ha publicado un cierre de nómina para tu cuenta.</p></div>
                    <?php endif; ?>
                <?php else : ?>
                    <?php if ((float) $payroll_summary['hours'] > 0 || (float) $payroll_summary['net_pay'] > 0 || (float) $payroll_summary['contractor_withholding'] > 0) : ?>
                    <div class="contractor-simple">
                        <span><small>Total cobrado</small><strong>$<?php echo esc_html(number_format((float) $payroll_summary['net_pay'], 2)); ?></strong></span>
                        <span><small>Deduccion <?php echo esc_html(number_format($retention_percent, 2)); ?>%</small><strong>$<?php echo esc_html(number_format((float) $payroll_summary['contractor_withholding'], 2)); ?></strong></span>
                        <span><small>Horas totales</small><strong><?php echo esc_html(number_format((float) $payroll_summary['hours'], 2)); ?> h</strong></span>
                    </div>
                    <?php else : ?>
                    <div class="empty"><h2>Pagos aún no publicados</h2><p>La oficina todavía no ha publicado pagos o horas para tu cuenta.</p></div>
                    <?php endif; ?>
                    <div class="w9-simple">
                        <small>W-9</small>
                        <?php if (!empty($w9_file['url'])) : ?>
                            <strong><?php echo esc_html($w9_file['name']); ?></strong>
                            <a href="<?php echo esc_url($w9_file['url']); ?>" target="_blank" rel="noopener">Ver / descargar W-9</a>
                        <?php else : ?>
                            <strong>No visible todavia</strong>
                            <p>Cuando oficina cargue el W-9 y lo marque visible, aparecera aqui.</p>
                        <?php endif; ?>
                    </div>
                <?php endif; ?>
            </div>
            <?php echo cleg_docs_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            <?php echo cleg_docs_role_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
        </section>
        <?php
        return ob_get_clean();
    }
}

if (!function_exists('cleg_docs_auto_page')) {
    function cleg_docs_auto_page($content) {
        if (!is_page('mis-documentos') || !in_the_loop() || !is_main_query()) {
            return $content;
        }

        if (has_shortcode($content, 'cleg_employee_documents')) {
            return $content;
        }

        return do_shortcode('[cleg_employee_documents]');
    }
}

