/**
 * CLEG 16 - Document Alerts v1
 */
/**
 * CLEG 16 - Document Alerts v1.3 - Desktop menu lock
 */
/**
 * Vantrexor
 * Snippet: Alertas administrativas de documentos v1.1
 * Shortcode: [cleg_document_alerts]
 * v1.2 aplica Fase 2 visual: encabezado oscuro y botones grandes, sin tocar logica ni Airtable.
 * v1.3 corrige solo escritorio: menu bajo encabezado y botones unificados, sin tocar movil ni logica.
 * Compatible con Code Snippets.
 *
 * Proposito:
 * - Mostrar documentos expirados, por vencer y pendientes de revision.
 * - Usar la tabla Employee Documents creada para Employee Center.
 * - Montarse automaticamente encima de /empleados/.
 *
 * Pegar sin la primera linea <?php en Code Snippets.
 * v1.1 refuerza colores contra estilos del tema y agrega regreso al dashboard.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!defined('CLEG_ADMIN_AIRTABLE_TOKEN')) {
    if (defined('CLEG_RRHH_AIRTABLE_PAT') && CLEG_RRHH_AIRTABLE_PAT) {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', CLEG_RRHH_AIRTABLE_PAT);
    } elseif (defined('CLEG_AIRTABLE_PAT') && CLEG_AIRTABLE_PAT) {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', CLEG_AIRTABLE_PAT);
    } elseif (function_exists('cleg_secure_config_get')) {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', cleg_secure_config_get('admin_airtable_token', cleg_secure_config_get('airtable_pat', '')));
    } else {
        define('CLEG_ADMIN_AIRTABLE_TOKEN', '');
    }
}

if (!defined('CLEG_AIRTABLE_BASE_ID')) {
    define('CLEG_AIRTABLE_BASE_ID', function_exists('cleg_secure_config_get') ? cleg_secure_config_get('admin_airtable_base_id', cleg_secure_config_get('airtable_base_id', '')) : '');
}

if (!defined('CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE')) {
    define('CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE', 'Employee Documents');
}

if (!function_exists('cleg_alerts_ready')) {
    function cleg_alerts_ready() {
        if (function_exists('cleg_integrations_airtable_ready')) {
            return cleg_integrations_airtable_ready('documents');
        }

        return CLEG_ADMIN_AIRTABLE_TOKEN !== '' && CLEG_ADMIN_AIRTABLE_TOKEN !== 'REEMPLAZAR_AIRTABLE_PAT';
    }
}

if (!function_exists('cleg_alerts_allowed')) {
    function cleg_alerts_allowed() {
        return is_user_logged_in() && (current_user_can('manage_options') || current_user_can('edit_pages'));
    }
}

if (!function_exists('cleg_alerts_request')) {
    function cleg_alerts_request($method, $table, $args = array()) {
        if (function_exists('cleg_integrations_airtable_request')) {
            $query = (!empty($args['query']) && is_array($args['query'])) ? $args['query'] : array();
            $body = !empty($args['body']) ? $args['body'] : null;
            if (!empty($args['record_id'])) {
                $query['record_id'] = sanitize_text_field((string) $args['record_id']);
            }

            return cleg_integrations_airtable_request('documents', $method, $table, $query, $body);
        }

        if (!cleg_alerts_ready()) {
            return new WP_Error('cleg_alerts_token', 'Airtable no esta configurado.');
        }

        $url = 'https://api.airtable.com/v0/' . rawurlencode(CLEG_AIRTABLE_BASE_ID) . '/' . rawurlencode($table);

        if (!empty($args['query']) && is_array($args['query'])) {
            $url = add_query_arg($args['query'], $url);
        }

        $request = array(
            'method' => $method,
            'timeout' => 20,
            'headers' => array(
                'Authorization' => 'Bearer ' . CLEG_ADMIN_AIRTABLE_TOKEN,
                'Content-Type' => 'application/json',
            ),
        );

        if (!empty($args['body'])) {
            $request['body'] = wp_json_encode($args['body']);
        }

        $response = wp_remote_request($url, $request);

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        $body = json_decode(wp_remote_retrieve_body($response), true);

        if ($code < 200 || $code >= 300) {
            $message = isset($body['error']['message']) ? $body['error']['message'] : 'Airtable rechazo la solicitud.';
            return new WP_Error('cleg_alerts_airtable', $message);
        }

        return is_array($body) ? $body : array();
    }
}

if (!function_exists('cleg_alerts_records')) {
    function cleg_alerts_records($query = array()) {
        $records = array();
        $offset = '';

        do {
            $page_query = $query;
            $page_query['pageSize'] = 100;

            if ($offset !== '') {
                $page_query['offset'] = $offset;
            }

            $response = cleg_alerts_request('GET', CLEG_AIRTABLE_EMPLOYEE_DOCUMENTS_TABLE, array('query' => $page_query));

            if (is_wp_error($response)) {
                return $response;
            }

            $records = array_merge($records, $response['records'] ?? array());
            $offset = isset($response['offset']) ? sanitize_text_field($response['offset']) : '';
        } while ($offset !== '');

        return $records;
    }
}

if (!function_exists('cleg_alerts_field')) {
    function cleg_alerts_field($record, $field, $default = '') {
        $fields = $record['fields'] ?? array();
        $value = $fields[$field] ?? $default;

        if (is_array($value) && isset($value['name'])) {
            return sanitize_text_field($value['name']);
        }

        if (is_array($value)) {
            return implode(', ', array_map('sanitize_text_field', array_filter(array_map('strval', $value))));
        }

        return is_scalar($value) ? sanitize_text_field((string) $value) : $default;
    }
}

if (!function_exists('cleg_alerts_raw')) {
    function cleg_alerts_raw($record, $field, $default = null) {
        $fields = $record['fields'] ?? array();
        return array_key_exists($field, $fields) ? $fields[$field] : $default;
    }
}

if (!function_exists('cleg_alerts_date')) {
    function cleg_alerts_date($value) {
        $timestamp = strtotime((string) $value);
        return $timestamp ? wp_date('m/d/Y', $timestamp) : '';
    }
}

if (!function_exists('cleg_alerts_employee_name')) {
    function cleg_alerts_employee_name($record) {
        $employee = cleg_alerts_raw($record, 'Employee', array());
        if (is_array($employee)) {
            $names = array();
            foreach ($employee as $item) {
                if (is_array($item) && !empty($item['name'])) {
                    $names[] = sanitize_text_field($item['name']);
                } elseif (is_scalar($item)) {
                    $names[] = sanitize_text_field((string) $item);
                }
            }

            if (!empty($names)) {
                return implode(', ', $names);
            }
        }

        return 'Trabajador';
    }
}

if (!function_exists('cleg_alerts_classify')) {
    function cleg_alerts_classify($record) {
        $status = cleg_alerts_field($record, 'Verification Status', 'Pending Review');
        $expiration = cleg_alerts_field($record, 'Expiration Date');
        $now = current_time('timestamp');

        if ($expiration !== '') {
            $ts = strtotime($expiration . ' 23:59:59');
            if ($ts && $ts < $now) {
                return array('bucket' => 'expired', 'label' => 'Expirado', 'class' => 'danger', 'sort' => $ts);
            }
            if ($ts && $ts <= $now + (30 * DAY_IN_SECONDS)) {
                return array('bucket' => 'soon', 'label' => 'Vence pronto', 'class' => 'warn', 'sort' => $ts);
            }
        }

        if (in_array($status, array('Pending Review', 'Rejected'), true)) {
            return array('bucket' => 'pending', 'label' => $status === 'Rejected' ? 'Rechazado' : 'Pendiente', 'class' => 'warn', 'sort' => $expiration !== '' ? strtotime($expiration) : PHP_INT_MAX);
        }

        return array('bucket' => 'ok', 'label' => $status, 'class' => 'ok', 'sort' => $expiration !== '' ? strtotime($expiration) : PHP_INT_MAX);
    }
}

if (!function_exists('cleg_document_alerts_shortcode')) {
    function cleg_document_alerts_shortcode($atts = array()) {
        if (!cleg_alerts_allowed()) {
            return '';
        }

        if (!cleg_alerts_ready()) {
            return '<section class="cleg-doc-alerts"><div class="empty">Falta configurar Airtable para alertas de documentos.</div>' . cleg_alerts_styles() . '</section>';
        }

        $atts = shortcode_atts(array('limit' => 20), $atts, 'cleg_document_alerts');
        $limit = max(1, min(100, (int) $atts['limit']));
        $documents = cleg_alerts_records(array(
            'sort[0][field]' => 'Expiration Date',
            'sort[0][direction]' => 'asc',
        ));

        if (is_wp_error($documents)) {
            return '<section class="cleg-doc-alerts"><div class="empty">' . esc_html($documents->get_error_message()) . '</div>' . cleg_alerts_styles() . '</section>';
        }

        $rows = array();
        $counts = array('expired' => 0, 'soon' => 0, 'pending' => 0, 'ok' => 0);

        foreach ($documents as $document) {
            $classification = cleg_alerts_classify($document);
            $counts[$classification['bucket']]++;

            if ($classification['bucket'] !== 'ok') {
                $rows[] = array(
                    'record' => $document,
                    'classification' => $classification,
                );
            }
        }

        usort($rows, function ($a, $b) {
            $rank = array('expired' => 0, 'soon' => 1, 'pending' => 2, 'ok' => 3);
            $a_bucket = $a['classification']['bucket'];
            $b_bucket = $b['classification']['bucket'];
            if ($rank[$a_bucket] !== $rank[$b_bucket]) {
                return $rank[$a_bucket] <=> $rank[$b_bucket];
            }
            return ($a['classification']['sort'] ?? PHP_INT_MAX) <=> ($b['classification']['sort'] ?? PHP_INT_MAX);
        });

        $rows = array_slice($rows, 0, $limit);

        ob_start();
        ?>
        <section class="cleg-doc-alerts">
            <div class="alerts-shell">
                <div class="alerts-head">
                    <div>
                    <p>Vantrexor RRHH</p>
                        <h2>Alertas de documentos</h2>
                        <span>Documentos expirados, por vencer o pendientes de revision.</span>
                    </div>
                    <nav>
                        <a href="<?php echo esc_url(home_url('/admin-rrhh/')); ?>">Dashboard</a>
                        <a href="<?php echo esc_url(home_url('/empleados/')); ?>">Expedientes</a>
                        <a href="<?php echo esc_url(home_url('/payroll-rrhh/')); ?>">Payroll</a>
                    </nav>
                </div>

                <div class="alert-metrics">
                    <span class="danger"><strong><?php echo esc_html((string) $counts['expired']); ?></strong><small>Expirados</small></span>
                    <span class="warn"><strong><?php echo esc_html((string) $counts['soon']); ?></strong><small>Vencen en 30 dias</small></span>
                    <span class="warn"><strong><?php echo esc_html((string) $counts['pending']); ?></strong><small>Pendientes/rechazados</small></span>
                    <span class="ok"><strong><?php echo esc_html((string) $counts['ok']); ?></strong><small>Sin alerta</small></span>
                </div>

                <div class="alerts-list">
                    <?php if (empty($rows)) : ?>
                        <div class="empty">No hay documentos expirados, por vencer o pendientes de revision.</div>
                    <?php endif; ?>

                    <?php foreach ($rows as $row) : ?>
                        <?php
                        $record = $row['record'];
                        $classification = $row['classification'];
                        $expiration = cleg_alerts_field($record, 'Expiration Date');
                        $files = cleg_alerts_raw($record, 'Document File', array());
                        $file_url = is_array($files) && !empty($files[0]['url']) ? esc_url($files[0]['url']) : '';
                        ?>
                        <article class="alert-row <?php echo esc_attr($classification['class']); ?>">
                            <div>
                                <strong><?php echo esc_html(cleg_alerts_employee_name($record)); ?></strong>
                                <small><?php echo esc_html(cleg_alerts_field($record, 'Document Type', 'Documento')); ?> · <?php echo esc_html(cleg_alerts_field($record, 'Document Code')); ?></small>
                            </div>
                            <span class="pill <?php echo esc_attr($classification['class']); ?>"><?php echo esc_html($classification['label']); ?></span>
                            <span><?php echo esc_html($expiration !== '' ? cleg_alerts_date($expiration) : 'Sin expiracion'); ?></span>
                            <span><?php echo esc_html(cleg_alerts_field($record, 'Verification Status', 'Pending Review')); ?></span>
                            <?php if ($file_url !== '') : ?>
                                <a href="<?php echo esc_url($file_url); ?>" target="_blank" rel="noopener">Ver archivo</a>
                            <?php else : ?>
                                <span>Sin archivo</span>
                            <?php endif; ?>
                        </article>
                    <?php endforeach; ?>
                </div>
            </div>
            <?php echo cleg_alerts_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
        </section>
        <?php
        return ob_get_clean();
    }
}

if (!function_exists('cleg_document_alerts_auto_empleados')) {
    function cleg_document_alerts_auto_empleados($content) {
        if (!is_page('empleados') || !in_the_loop() || !is_main_query()) {
            return $content;
        }

        if (!cleg_alerts_allowed()) {
            return $content;
        }

        if (has_shortcode($content, 'cleg_document_alerts')) {
            return $content;
        }

        return do_shortcode('[cleg_document_alerts]') . $content;
    }
}

