/**
 * CLEG 03B - RRHH Design System v1
 */
/**
 * CLEG 03B - Vantrexor Design System v5.2 - Visual shell unificado
 *
 * Objetivo:
 * - Centralizar el CSS visual operativo de Vantrexor.
 * - Leer identidad, tokens, catalogo e iconos desde CLEG 00B Visual System Core.
 * - Unificar pantallas admin, payroll, empleados, documentos, formularios y compras.
 * - No tocar la vista trabajador ni la logica de CLEG 04.
 * - Mantener el panel trabajador aislado: no usar selectores sobre .cleg-worker-app.
 * - No pisar el Command Center de /panel/ con selectores globales.
 * - v2.5 oculta la barra WordPress en pantallas RRHH, corrige ancho seguro y refuerza Employee Center/perfiles.
 * - v2.6 compacta el mapa GPS cuando vive junto a la tabla de jornadas abiertas en Tiempo real.
 * - v2.7 evita overflow horizontal/corte derecho del mapa en /admin-tiempo-real/.
 * - v2.8 compacta nombres/listas GPS y protege botones de navegacion como Payroll.
 * - v2.9 da aire al encabezado Payroll y estiliza salto interno al mapa de Tiempo real.
 * - v3.0 refuerza GPS en Revision de horas: verde dentro de zona, rojo fuera y textos legibles.
 * - v3.1 corrige contraste del detalle GPS movil y permite scroll en lista de activos.
 * - v3.2 corrige seleccion de todos los activos en desktop y contencion del acordeon movil.
 * - v3.3 corrige contraste del trabajador activo, scroll, ancho y lectura interna del GPS movil.
 * - v3.4 unifica estilos, tamanos, botones, paneles, tablas, inputs, metricas y estados de modulos internos usando Procurement como base visual.
 * - v3.5 abre los contenedores Astra de Procurement, corrige la clase real .cleg-procurement y refuerza la vista comun desktop/tablet.
 * - v3.6 iguala el aviso de atencion como cuadrado numerico, devuelve Panel/Cerrar al extremo derecho y ajusta prioridades.
 * - v3.7 fija contrato visual: encabezado grande estable, aviso en la misma linea, menu fijo y submenus internos con botones grandes tipo Bandeja.
 * - v3.8 refuerza prioridad y resetea reglas antiguas del Customizer: encabezado y atencion al mismo nivel; Panel/Cerrar al final derecho de la barra.
 * - v3.9 aplica Fase 1 a pantallas RRHH hermanas: encabezado oscuro grande, acciones fuera del encabezado y menu principal estable.
 * - v4.0 corrige solo escritorio: menu principal bajo encabezado, submenus debajo y botones unificados sin tocar movil.
 * - v4.1 centraliza cabecera/menu web para RRHH y Payroll, sin CSS adicional.
 * - v4.2 agrega cierre final web-only para que cabecera/menu ganen sobre estilos heredados y Payroll comparta la misma estructura.
 * - v4.3 elimina gap superior web, alinea tokens con guia visual y normaliza submenus tipo Bandeja.
 * - v4.4 aplica contencion web segun documento visual 26: sin gap superior, sin desborde y paneles alineados.
 * - v4.5 oculta shell/header/footer del tema en modulos internos web y refuerza margen cero sin CSS adicional.
 * - v4.6 elimina gap superior heredado, recupera ancho comun en filtros/mapas y protege Command Center web.
 * - v4.8 alinea tarjetas de contexto y renombra Empleados operativo a Trabajadores.
 * - v4.9 desactiva el bump superior de WordPress/admin bar en rutas RRHH y refuerza reset plain sin depender de :has().
 * - v5.0 agrega body class propia y reset final del shell interno para eliminar gap superior persistente.
 * - v5.1 replica el patron de Compras: wrapper sin padding y main interno como superficie principal.
 * - v5.2 separa core visual temprano y deja este modulo como capa CSS/correcciones visuales.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_rrhh_nav')) {
    function cleg_rrhh_nav($active = '') {
        if ($active !== 'tenant-admin' && function_exists('cleg_admin_nav')) {
            return cleg_admin_nav($active);
        }

        if ($active === 'tenant-admin') {
            return '<nav class="cleg-admin-nav cleg-admin-nav-tenant-admin" aria-label="Navegacion Administracion">'
                . '<a href="' . esc_url(home_url('/panel/')) . '">Panel</a>'
                . '<a class="is-logout" href="' . esc_url(wp_logout_url(home_url('/acceso/'))) . '">Cerrar sesion</a>'
                . '</nav>';
        }

        $items = array(
            'dashboard' => array('Control RRHH', home_url('/admin-rrhh/')),
            'employees' => array('Trabajadores', home_url('/admin-empleados/')),
            'requests' => array('Solicitudes', home_url('/admin-solicitudes/')),
        );
        $utility_items = array(
            'panel' => array('Panel', home_url('/panel/'), 'is-panel-link'),
            'logout' => array('Cerrar sesion', wp_logout_url(home_url('/acceso/')), 'is-logout'),
        );

        $html = '<nav class="cleg-admin-nav cleg-rrhh-nav" aria-label="Navegacion RRHH">';

        foreach ($items as $key => $item) {
            $class = $key === $active ? 'is-active' : '';
            $html .= '<a class="' . esc_attr($class) . '" href="' . esc_url($item[1]) . '">' . esc_html($item[0]) . '</a>';
        }
        foreach ($utility_items as $item) {
            $html .= '<a class="' . esc_attr($item[2]) . '" href="' . esc_url($item[1]) . '">' . esc_html($item[0]) . '</a>';
        }

        return $html . '</nav>';
    }
}

if (!function_exists('cleg_rrhh_design_path')) {
    function cleg_rrhh_design_path() {
        $uri = isset($_SERVER['REQUEST_URI']) ? sanitize_text_field(wp_unslash($_SERVER['REQUEST_URI'])) : '/';
        $path = parse_url($uri, PHP_URL_PATH);
        $path = $path ? '/' . trim($path, '/') . '/' : '/';
        return $path === '//' ? '/' : $path;
    }
}

if (!function_exists('cleg_rrhh_design_should_print')) {
    function cleg_rrhh_design_should_print() {
        $paths = array(
            '/panel/',
            '/admin-rrhh/',
            '/admin-horas/',
            '/admin-tiempo-real/',
            '/admin-dispositivos/',
            '/admin-empleados/',
            '/admin-job-sites/',
            '/admin-solicitudes/',
            '/payroll-rrhh/',
            '/empleados/',
            '/mis-nominas/',
            '/mis-documentos/',
            '/formularios/',
            '/admin-procurement/',
        );

        return in_array(cleg_rrhh_design_path(), $paths, true);
    }
}

if (!function_exists('cleg_rrhh_design_disable_admin_bar_gap')) {
    function cleg_rrhh_design_disable_admin_bar_gap() {
        if (!cleg_rrhh_design_should_print()) {
            return;
        }

        add_filter('show_admin_bar', '__return_false', 9999);
        remove_action('wp_head', '_admin_bar_bump_cb');
    }

    cleg_rrhh_design_disable_admin_bar_gap();
    add_action('init', 'cleg_rrhh_design_disable_admin_bar_gap', 0);
    add_action('wp', 'cleg_rrhh_design_disable_admin_bar_gap', 0);
    add_action('wp_head', 'cleg_rrhh_design_disable_admin_bar_gap', 0);
}

if (!function_exists('cleg_rrhh_design_body_class')) {
    function cleg_rrhh_design_body_class($classes) {
        if (cleg_rrhh_design_should_print()) {
            $classes[] = 'cleg-rrhh-shell-page';
        }

        return array_values(array_unique($classes));
    }

    add_filter('body_class', 'cleg_rrhh_design_body_class', 999);
}

