umns:1fr 1fr;gap:8px;margin:0!important;background:#fff!important;padding:10px!important}.cleg-worker-note{grid-column:1 / -1;margin:0;border:1px solid rgba(6,24,45,.1);border-radius:10px;background:#f8fafc!important;color:#516579!important;padding:9px}.cleg-audit-trail pre{white-space:pre-wrap;max-height:180px;overflow:auto;border-radius:0 0 12px 12px;background:#fff!important;color:#516579!important;padding:10px!important;font-size:12px}
