.cleg-geofence-picker{grid-column:1 / -1;border:1px solid var(--line);border-radius:14px;background:#fff;padding:10px;display:grid;gap:10px}
.cleg-geofence-map{width:100%;height:320px;border-radius:12px;overflow:hidden;background:#edf1f6;border:1px solid var(--line);position:relative;z-index:1}
.cleg-admin-mini-form .cleg-geofence-map{height:360px}
.cleg-geofence-picker .leaflet-control-container .leaflet-top,.cleg-geofence-picker .leaflet-control-container .leaflet-bottom{z-index:700!important}
.cleg-geofence-picker .leaflet-control-zoom{border:0!important;box-shadow:0 12px 28px rgba(6,24,45,.2)!important}
.cleg-geofence-picker .leaflet-control-zoom a{width:38px!important;height:38px!important;line-height:38px!important;background:#fff!important;color:#06182d!important;font-size:24px!important;font-weight:950!important}
.cleg-geofence-map .leaflet-pane,.cleg-geofence-map .leaflet-tile,.cleg-geofence-map .leaflet-marker-icon,.cleg-geofence-map .leaflet-marker-shadow,.cleg-geofence-map .leaflet-tile-container,.cleg-geofence-map .leaflet-pane>svg,.cleg-geofence-map .leaflet-pane>canvas,.cleg-geofence-map .leaflet-zoom-box,.cleg-geofence-map .leaflet-image-layer,.cleg-geofence-map .leaflet-layer{position:absolute!important;left:0;top:0}
