.cleg-geofence-map .leaflet-tile-pane{z-index:200!important}.cleg-geofence-map .leaflet-overlay-pane{z-index:400!important}.cleg-geofence-map .leaflet-marker-pane{z-index:600!important}
.cleg-geofence-map .leaflet-control-container .leaflet-top,.cleg-geofence-map .leaflet-control-container .leaflet-bottom{position:absolute!important;z-index:1000!important;pointer-events:none!important}
.cleg-geofence-map .leaflet-control-container .leaflet-top{top:10px!important}.cleg-geofence-map .leaflet-control-container .leaflet-right{right:10px!important}.cleg-geofence-map .leaflet-control{pointer-events:auto!important;float:left!important;clear:both!important}
.cleg-geofence-map-zoom{position:absolute;right:12px;top:12px;z-index:900;display:grid;gap:6px}
.cleg-geofence-picker .leaflet-control-zoom+.cleg-geofence-map-zoom,.cleg-geofence-map .cleg-geofence-map-zoom{display:none!important}
.cleg-geofence-map-zoom button{width:40px!important;height:40px!important;min-height:40px!important;padding:0!important;border:1px solid rgba(6,24,45,.14)!important;border-radius:12px!important;background:#fff!important;color:#06182d!important;font-size:24px!important;font-weight:950!important;line-height:1!important;box-shadow:0 12px 28px rgba(6,24,45,.2)!important}
.cleg-geofence-center-pin{position:absolute;left:50%;top:50%;z-index:850;width:34px;height:34px;border:3px solid #fff;border-radius:999px;background:#c75000;box-shadow:0 12px 26px rgba(6,24,45,.34),0 0 0 6px rgba(199,80,0,.22);transform:translate(-50%,-50%);pointer-events:none}
.cleg-geofence-center-pin:after{content:"";position:absolute;left:50%;top:50%;width:10px;height:10px;border-radius:999px;background:#fff;transform:translate(-50%,-50%)}
.cleg-geofence-marker{position:relative;width:34px;height:34px;border:3px solid #fff;border-radius:999px;background:#c75000;box-shadow:0 12px 26px rgba(6,24,45,.34),0 0 0 6px rgba(199,80,0,.22)}
.cleg-geofence-marker:after{content:"";position:absolute;left:50%;top:50%;width:10px;height:10px;border-radius:999px;background:#fff;transform:translate(-50%,-50%)}
.cleg-geofence-selected{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid rgba(199,80,0,.24);border-radius:12px;background:#fff7ed;color:#7c2d12;padding:10px 12px}
.cleg-geofence-selected strong{font-size:12px;font-weight:950;text-transform:uppercase;color:#9f3f00}
.cleg-geofence-selected span{color:#7c2d12;font-size:13px;font-weight:850;text-align:right}
.cleg-geofence-toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}
.cleg-geofence-toolbar button{align-self:auto!important;border:0;border-radius:999px;background:var(--navy);color:#fff;padding:9px 12px;font-weight:950;cursor:pointer}
.cleg-geofence-toolbar span{color:var(--muted);font-size:12px;font-weight:850;text-transform:none}
.cleg-geofence-coords{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.cleg-geofence-picker .leaflet-container{font:inherit}.cleg-geofence-picker .leaflet-control-attribution{font-size:10px}
.cleg-project-edit .cleg-project-modal-backdrop{display:none}
.cleg-project-edit[open] .cleg-project-modal-backdrop{display:block;position:fixed;inset:0;z-index:9998;background:rgba(6,24,45,.42);backdrop-filter:blur(3px)}
.cleg-project-edit[open] .cleg-admin-mini-form{position:fixed;right:24px;top:72px;z-index:9999;width:min(840px,calc(100vw - 48px));max-height:calc(100svh - 96px);overflow:auto;border:1px solid var(--line);border-radius:18px;background:#fff;padding:18px;box-shadow:0 28px 70px rgba(6,24,45,.28)}
.cleg-project-edit[open] .cleg-admin-mini-form:before{content:"Modificar proyecto y geofence";display:block;margin:0 44px 10px 0;color:var(--ink);font-size:20px;font-weight:950;text-transform:none}
.cleg-project-modal-close{position:absolute!important;right:14px;top:14px;width:36px!important;height:36px!important;min-height:36px!important;padding:0!important;border-radius:999px!important;background:#edf1f6!important;color:var(--ink)!important;font-size:24px!important;line-height:1!important;display:grid!important;place-items:center!important}
.cleg-project-edit.is-dirty .cleg-admin-mini-form button[type="submit"]{box-shadow:0 0 0 4px rgba(199,80,0,.18),0 12px 26px rgba(199,80,0,.22)!important;background:var(--orange)!important}
.cleg-project-edit.needs-save .cleg-admin-mini-form button[type="submit"]{animation:clegSaveShake .42s ease both}
@keyframes clegSaveShake{10%,90%{transform:translateX(-1px)}20%,80%{transform:translateX(2px)}30%,50%,70%{transform:translateX(-4px)}40%,60%{transform:translateX(4px)}}
.cleg-inline-edit-label{display:block;margin-top:7px;color:var(--muted)!important;font-size:11px!important;font-weight:950!important;text-transform:uppercase}
.cleg-time-inline{padding:0!important;overflow:hidden}.cleg-time-inline summary{list-style:none;cursor:pointer;padding:10px}.cleg-time-inline summary::-webkit-details-marker{display:none}.cleg-time-inline summary em{display:inline-flex;align-items:center;justify-content:center;border:1px solid rgba(6,24,45,.14);border-radius:8px;background:#fff;color:#06182d;padding:5px 7px;font-size:10px;font-style:normal;font-weight:950;text-transform:uppercase}.cleg-time-inline[open] summary{border-bottom:1px solid rgba(6,24,45,.1);background:#fff}.cleg-time-inline-body{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:end;padding:10px;background:#fff}.cleg-time-inline-body .cleg-inline-edit-label{grid-column:1 / -1;margin:0}.cleg-inline-time-save{align-self:stretch;border:0!important;border-radius:8px!important;background:#182537!important;color:#fff!important;padding:8px 10px!important;font-size:12px!important;font-weight:950!important;white-space:nowrap;cursor:pointer}.cleg-segment-audit{grid-column:1 / -1;border:1px solid rgba(6,24,45,.12);border-radius:12px;background:#fff;color:var(--ink);overflow:hidden}.cleg-segment-audit summary{display:flex!important;align-items:center;justify-content:space-between;gap:10px;border-radius:0!important;background:#f8fafc!important;color:#516579!important;padding:9px 11px!important;font-size:11px!important;font-weight:950!important;text-transform:uppercase;cursor:pointer;list-style:none}.cleg-segment-audit summary::-webkit-details-marker{display:none}.cleg-segment-audit summary em{border:1px solid rgba(6,24,45,.12);border-radius:8px;background:#fff;color:#06182d;padding:4px 7px;font-style:normal}.cleg-segment-audit>div{display:grid;gap:8px;padding:10px}.cleg-segment-audit .cleg-gps-audit-note{margin:0}.cleg-segment-audit .cleg-audit-list{max-height:190px;padding:0;background:transparent}
@media(max-width:760px){.cleg-time-edit-head{gap:6px}.cleg-time-edit-head b{font-size:12px;line-height:1.2}.cleg-time-kind{padding:3px 6px;font-size:9px}.cleg-gps-mini{width:28px;height:28px}.cleg-time-inline-body{grid-template-columns:1fr}.cleg-inline-time-save{width:100%;min-height:38px}.cleg-review-notes>div{grid-template-columns:1fr}.cleg-segment-audit>div{padding:8px}.cleg-segment-audit .cleg-audit-list{max-height:170px}}
.cleg-readonly-hours-list{display:grid;gap:10px}.cleg-readonly-hour-row{display:grid;grid-template-columns:minmax(180px,1.25fr) minmax(130px,.9fr) minmax(130px,.9fr) minmax(90px,.55fr) auto;gap:10px;align-items:center;border:1px solid var(--line);border-radius:14px;background:#fff;padding:12px}.cleg-readonly-hour-row strong,.cleg-readonly-hour-row b{display:block;color:var(--ink);line-height:1.15}.cleg-readonly-hour-row small,.cleg-readonly-hour-row span{display:block;color:var(--muted);font-size:11px;font-weight:900;text-transform:uppercase}.cleg-project-consult-note{display:grid;align-content:start;gap:10px}.cleg-project-list-link{margin-top:14px}
@media(max-width:820px){.cleg-readonly-hour-row{grid-template-columns:1fr 1fr}.cleg-readonly-hour-row>div:first-child{grid-column:1 / -1}.cleg-project-edit[open] .cleg-admin-mini-form{left:12px;right:12px;top:52px;width:auto;max-height:calc(100svh - 76px)}.cleg-admin-mini-form .cleg-geofence-map{height:320px}}
