.cleg-admin-ui{--ink:#06182d;--muted:#516579;--line:rgba(6,24,45,.12);--orange:#c75000;--navy:#182537;--soft:#f4f7fb;--good:#107344;--bad:#9a1f1f;background:radial-gradient(circle at top left,rgba(199,80,0,.08),transparent 34%),#f4f7fb;color:var(--ink);padding:clamp(22px,4vw,56px);min-height:100svh}.cleg-admin-ui *{box-sizing:border-box}.cleg-admin-shell{width:min(1560px,calc(100vw - 48px));margin:0 auto}.cleg-admin-header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:18px}.cleg-admin-header p{margin:0 0 5px;color:var(--muted);font-size:12px;font-weight:950;text-transform:uppercase}.cleg-admin-header h1{margin:0;color:var(--ink);font-size:clamp(30px,5vw,48px);line-height:1;letter-spacing:0}.cleg-admin-header span{display:block;margin-top:8px;color:var(--muted)}.cleg-admin-header a,.cleg-admin-empty a{color:var(--ink);font-weight:950;text-decoration:none}.cleg-admin-nav{display:flex;gap:8px;overflow-x:auto;padding:8px 0 22px}.cleg-admin-nav a{white-space:nowrap;border:1px solid var(--line);border-radius:999px;background:#fff;color:var(--ink);padding:10px 14px;font-weight:950;text-decoration:none}.cleg-admin-nav a.is-active{background:var(--navy);color:#fff}.cleg-command-strip{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:0 0 14px;border:1px solid rgba(6,24,45,.1);border-radius:18px;background:linear-gradient(180deg,#fff,#f7fafc);color:#fff;padding:18px 20px;box-shadow:0 18px 42px rgba(6,24,45,.14)}.cleg-command-strip span{display:block;color:rgba(255,255,255,.68);font-size:12px;font-weight:950;text-transform:uppercase}.cleg-command-strip strong{display:block;margin-top:3px;font-size:18px}.cleg-command-strip a{border-radius:999px;background:#fff;color:var(--navy);padding:10px 13px;font-weight:950;text-decoration:none;white-space:nowrap}.cleg-admin-notice{margin:0 0 14px;border-radius:14px;padding:13px 15px;font-weight:950}.cleg-admin-notice.is-error{background:#fff3e8;color:#9f3f00;border:1px s