@media(max-width:820px){.cleg-readonly-hour-row{grid-template-columns:1fr 1fr}.cleg-readonly-hour-row>div:first-child{grid-column:1 / -1}.cleg-project-edit[open] .cleg-admin-mini-form{left:12px;right:12px;top:52px;width:auto;max-height:calc(100svh - 76px)}.cleg-admin-mini-form .cleg-geofence-map{height:320px}}
