/* CLEG 17B admin GPS tracking migrated styles */
            .cleg17-gps-panel{width:min(1560px,calc(100vw - 48px));max-width:min(1560px,calc(100vw - 48px));margin:26px auto;padding:0;color:#172033;font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;box-sizing:border-box}
            .cleg17-gps-panel *{box-sizing:border-box}
            .cleg17-gps-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:14px}
            .cleg17-gps-kicker{font-size:12px;font-weight:800;text-transform:uppercase;color:#64748b;letter-spacing:0}
            .cleg17-gps-title{margin:2px 0 0;font-size:24px;line-height:1.15;font-weight:900;color:#0f172a}
            .cleg17-gps-note{margin:4px 0 0;color:#64748b;font-size:13px;max-width:760px}
            .cleg17-gps-controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
            .cleg17-gps-controls input{height:38px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#0f172a;padding:0 10px;font-size:13px}
            .cleg17-gps-filterbar{display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:4px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}
            .cleg17-gps-filterbar button{height:30px;border:0;border-radius:6px;background:#f1f5f9;color:#334155;font-size:12px;font-weight:900;padding:0 9px;cursor:pointer}
            .cleg17-gps-filterbar button.is-active{background:#0f172a;color:#fff}
            .cleg17-gps-refresh{height:38px;border:0;border-radius:8px;background:#0f172a;color:#fff;font-weight:800;padding:0 14px;cursor:pointer}
            .cleg17-gps-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:0 0 14px}
            .cleg17-gps-stat{border:1px solid #e2e8f0;border-radius:8px;background:#fff;padding:12px}
            .cleg17-gps-stat strong{display:block;font-size:22px;line-height:1;color:#0f172a}
            .cleg17-gps-stat span{display:block;margin-top:5px;font-size:12px;color:#64748b;font-weight:700}
            .cleg17-gps-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,420px);gap:14px;align-items:stretch}
            .cleg17-gps-map-wrap{position:relative;border:1px solid #dbe3ee;border-radius:8px;overflow:hidden;background:#eef2f7;min-height:620px;height:620px}
            .cleg17-gps-map{height:620px;width:100%;z-index:1}
            .cleg17-gps-map-empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;padding:24px;background:rgba(248,250,252,.86);z-index:2;color:#475569;font-weight:800}
            .cleg17-gps-side{border:1px solid #e2e8f0;border-radius:8px;background:#fff;height:620px;display:grid;grid-template-rows:auto minmax(0,1fr) auto;overflow:hidden;min-height:0}
            .cleg-live-map-slot{margin:14px 0 0}
            .cleg-live-map-slot,.cleg-live-map-slot .cleg17-gps-panel,.cleg-live-map-slot .cleg17-gps-layout,.cleg-live-map-slot .cleg17-gps-map-wrap,.cleg-live-map-slot .cleg17-gps-side{max-width:100%;min-width:0;box-sizing:border-box}
            .cleg-live-map-slot .cleg17-gps-panel{width:100%;max-width:100%;margin:0;padding:0;overflow:hidden}
            .cleg-live-map-slot .cleg17-gps-head{margin-bottom:10px}
            .cleg-live-map-slot .cleg17-gps-stats{margin-bottom:10px}
            .cleg-live-map-slot .cleg17-gps-layout{width:100%;grid-template-columns:minmax(0,1fr) minmax(320px,400px);gap:12px}
            .cleg-live-map-slot .cleg17-gps-map-wrap,.cleg-live-map-slot .cleg17-gps-map,.cleg-live-map-slot .cleg17-gps-side{height:460px;min-height:460px}
            .cleg-live-map-slot .cleg17-gps-side{grid-template-rows:auto minmax(0,1fr) auto;min-height:0}
            .cleg17-gps-side-head{padding:13px;border-bottom:1px solid #e2e8f0}
            .cleg17-gps-side-head strong{display:block;color:#0f172a;font-size:15px}
            .cleg17-gps-side-head span{display:block;margin-top:3px;color:#64748b;font-size:12px}
            .cleg17-gps-list{overflow:auto;min-height:0}
            .cleg17-gps-worker{width:100%;display:grid;grid-template-columns:1fr auto;gap:8px;text-align:left;padding:12px 13px;border:0;border-bottom:1px solid #edf2f7;background:#fff;cursor:pointer}
            .cleg17-gps-worker:hover,.cleg17-gps-worker.is-active{background:#f8fafc}
            .cleg17-gps-worker-name{display:block;font-weight:900;color:#0f172a;font-size:13px;line-height:1.18;word-break:normal;overflow-wrap:anywhere}
            .cleg17-gps-worker-meta{display:block;margin-top:4px;color:#64748b;font-size:11px;line-height:1.35}
            .cleg17-gps-badge{display:inline-flex;align-items:center;justify-content:center;height:24px;border-radius:999px;padding:0 9px;font-size:11px;font-weight:900;border:1px solid transparent;white-space:nowrap}
            .cleg17-gps-badge.fresh{background:#dcfce7;color:#166534;border-color:#86efac}
            .cleg17-gps-badge.stale{background:#fef9c3;color:#854d0e;border-color:#fde68a}
            .cleg17-gps-badge.old{background:#fee2e2;color:#991b1b;border-color:#fecaca}
            .cleg17-gps-badge.missing{background:#e2e8f0;color:#334155;border-color:#cbd5e1}
            .cleg17-gps-badge.entry{background:#dbeafe;color:#1d4ed8;border-color:#93c5fd}
            .cleg17-gps-detail{border-top:1px solid #e2e8f0;padding:13px;min-height:150px;background:#f8fafc;overflow:auto}
            .cleg17-gps-detail h4{margin:0 0 8px;color:#0f172a;font-size:15px}
            .cleg17-gps-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px}
            .cleg17-gps-detail-grid div{background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:8px}
            .cleg17-gps-detail-grid span{display:block;color:#64748b;font-size:11px;font-weight:800}
            .cleg17-gps-detail-grid strong{display:block;margin-top:2px;color:#0f172a;font-size:13px}
            .cleg17-gps-jump{display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:center;margin:10px 0}
            .cleg17-gps-jump button{height:30px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#0f172a;font-size:12px;font-weight:900;padding:0 9px;cursor:pointer}
            .cleg17-gps-jump button:disabled{opacity:.42;cursor:not-allowed}
            .cleg17-gps-jump input{width:100%;accent-color:#0f172a}
            .cleg17-gps-route{display:flex;gap:6px;overflow:auto;padding-bottom:3px}
            .cleg17-gps-route-point{flex:0 0 auto;border:1px solid #dbe3ee;background:#fff;border-radius:8px;padding:6px 8px;font-size:11px;color:#475569;cursor:pointer;text-align:left}
            .cleg17-gps-route-point.is-active{border-color:#0f172a;background:#0f172a;color:#fff}
            .cleg17-gps-status{margin-top:10px;color:#64748b;font-size:12px}
            .cleg17-gps-loading{opacity:.58;pointer-events:none}
            @media(max-width:900px){
                .cleg17-gps-panel{width:min(100% - 28px,1560px);max-width:min(100% - 28px,1560px)}
                .cleg17-gps-head{align-items:flex-start;flex-direction:column}
                .cleg17-gps-stats{grid-template-columns:repeat(2,minmax(0,1fr))}
                .cleg17-gps-layout{grid-template-columns:1fr}
                .cleg17-gps-map-wrap,.cleg17-gps-side{min-height:auto;height:auto}
                .cleg17-gps-map{height:430px}
                .cleg17-gps-side{grid-template-rows:auto auto auto}
                .cleg17-gps-list{max-height:260px}
            }

