    body .cleg17-gps-worker-status{display:inline-flex!important;align-items:center!important;gap:6px!important;min-width:max-content!important;border-radius:8px!important;padding:6px 9px!important;font-size:12px!important;font-weight:950!important;line-height:1!important;color:#06182d!important;-webkit-text-fill-color:#06182d!important;background:#eef3f8!important}
    body .cleg17-gps-worker-status:before{content:"";display:inline-block;width:8px;height:8px;border-radius:999px;background:#64748b}
    body .cleg17-gps-worker-status.fresh{background:#e8f8ef!important;color:#107344!important;-webkit-text-fill-color:#107344!important}
    body .cleg17-gps-worker-status.fresh:before{background:#107344}
    body .cleg17-gps-worker-status.stale{background:#fff7d6!important;color:#875600!important;-webkit-text-fill-color:#875600!important}
    body .cleg17-gps-worker-status.stale:before{background:#ca8a04}
    body .cleg17-gps-worker-status.old{background:#ffe8e8!important;color:#9a1f1f!important;-webkit-text-fill-color:#9a1f1f!important}
    body .cleg17-gps-worker-status.old:before{background:#9a1f1f}
    body .cleg17-gps-worker-status.missing{background:#edf1f6!important;color:#475569!important;-webkit-text-fill-color:#475569!important}
    body .cleg17-gps-worker-status.missing:before{background:#64748b}
    body .cleg17-gps-panel .cleg17-gps-worker,
    body .cleg17-gps-panel .cleg17-gps-worker:hover,
    body .cleg17-gps-panel .cleg17-gps-worker.is-active,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker:hover,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker.is-active,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker:hover,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker.is-active{background:#fff!important;color:#07182d!important;-webkit-text-fill-color:#07182d!important;border-radius:8px!important;transform:none!important;scale:1!important;text-shadow:none!important}
    body .cleg17-gps-panel .cleg17-gps-worker.is-active,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker.is-active,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker.is-active{border-color:#2f6f9f!important;box-shadow:0 0 0 2px rgba(47,111,159,.24),0 8px 18px rgba(6,24,45,.05)!important}
    body .cleg17-gps-panel .cleg17-gps-worker-name,
    body .cleg17-gps-panel .cleg17-gps-worker-meta,
    body .cleg17-gps-panel .cleg17-gps-worker.is-active .cleg17-gps-worker-name,
    body .cleg17-gps-panel .cleg17-gps-worker.is-active .cleg17-gps-worker-meta,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker-name,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker-meta,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker.is-active .cleg17-gps-worker-name,
    body .cleg-admin-ui .cleg17-gps-panel .cleg17-gps-worker.is-active .cleg17-gps-worker-meta,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker-name,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker-meta,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker.is-active .cleg17-gps-worker-name,
    body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker.is-active .cleg17-gps-worker-meta{color:#07182d!important;-webkit-text-fill-color:#07182d!important;writing-mode:horizontal-tb!important;text-orientation:mixed!important;transform:none!important;scale:1!important}
    body .cleg17-gps-detail-grid{display:none!important}
    @media(max-width:760px){
        body .cleg17-gps-title{font-size:22px!important}
        body .cleg17-gps-note,
        body .cleg17-gps-worker-meta,
        body .cleg17-gps-status{font-size:12px!important}
        body .cleg17-gps-panel .cleg17-gps-worker,
        body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker{grid-template-columns:minmax(0,1fr)!important;min-width:0!important;width:100%!important}
        body .cleg17-gps-panel .cleg17-gps-worker-mainline,
        body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker-mainline{display:grid!important;grid-template-columns:minmax(0,1fr)!important;gap:6px!important;align-items:start!important;justify-content:start!important;width:100%!important;min-width:0!important}
        body .cleg17-gps-panel .cleg17-gps-worker-name,
        body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker-name{display:block!important;min-width:0!important;width:100%!important;max-width:100%!important;white-space:normal!important;word-break:normal!important;overflow-wrap:break-word!important;writing-mode:horizontal-tb!important;text-orientation:mixed!important;line-height:1.18!important}
        body .cleg17-gps-panel .cleg17-gps-worker-status,
        body .cleg-admin-ui .cleg-field-gps-drawer .cleg17-gps-worker-status{justify-self:start!important;max-width:100%!important;min-width:0!important;white-space:nowrap!important;writing-mode:horizontal-tb!important;text-orientation:mixed!important}
    }
    </style>

    <script>
    (function () {
        [].slice.call(document.querySelectorAll('[data-cleg17-gps]')).forEach(function (root) {
        if (!root || root.dataset.ready === '1') {
            return;
        }
        root.dataset.ready = '1';

        var state = {map:null, markers:{}, routes:{}, jobMarkers:[], pointMarker:null, pointMarkers:[], data:null, selected:null, selectedPointIndex:null, filter:'all', showAllPoints:true, started:false};
        var ajaxUrl = root.getAttribute('data-ajax-url');
        var nonce = root.getAttribute('data-nonce');
        var mapEl = root.querySelector('.cleg17-gps-map');
        var emptyEl = root.querySelector('.cleg17-gps-map-empty');
        var listEl = root.querySelector('.cleg17-gps-list');
        var detailEl = root.querySelector('.cleg17-gps-detail');
        var filterBarEl = root.querySelector('.cleg17-gps-filterbar');
        var dateEl = root.querySelector('.cleg17-gps-date');
        var generatedEl = root.querySelector('.cleg17-gps-generated');
        var togglePointsEl = root.querySelector('.cleg17-gps-toggle-points');

        function loadAsset(type, url) {
            return new Promise(function (resolve, reject) {
                if (type === 'css') {
                    if ([].slice.call(document.styleSheets).some(function (sheet) { return sheet.href && sheet.href.indexOf(url) !== -1; })) {
                        resolve();
                        return;
                    }
                    var link = document.createElement('link');
                    link.rel = 'stylesheet';
                    link.href = url;
                    link.onload = resolve;
                    link.onerror = reject;
                    document.head.appendChild(link);
                    return;
                }
                var script = document.createElement('script');
                script.src = url;
                script.onload = resolve;
                script.onerror = reject;
                document.head.appendChild(script);
            });
        }

        function ensureLeaflet() {
            if (window.L) {
                return Promise.resolve();
            }
            return loadAsset('css', 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css')
                .then(function () { return loadAsset('js', 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'); });
        }

        function statusLabel(status) {
            return {fresh:'Reciente', stale:'Atrasada', old:'Vieja', missing:'Sin GPS'}[status] || 'Sin datos';
        }

        function statusColor(status) {
            return {fresh:'#16a34a', stale:'#ca8a04', old:'#dc2626', missing:'#64748b'}[status] || '#64748b';
        }

        function pointLabel(point) {
            if (!point) {
                return 'Senal';
            }
            if (point.label) {
                return String(point.label);
            }
            if (point.source) {
                return String(point.source);
            }
            if (point.type === 'entrada') {
                return 'Entrada';
            }
            if (point.type === 'salida') {
                return 'Salida';
            }
            if (point.type === 'ping') {
                return 'Ping GPS';
            }
            return 'Senal';
        }

        function esc(value) {
            return String(value === null || value === undefined ? '' : value).replace(/[&<>"']/g, function (char) {
                return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char];
            });
        }

        function markerIcon(worker) {
            var color = statusColor(worker.status);
            return L.divIcon({
                className: '',
                html: '<div style="width:20px;height:20px;border-radius:8px;background:' + color + ';border:3px solid #fff;box-shadow:0 6px 16px rgba(15,23,42,.28)"></div>',
                iconSize: [20,20],
                iconAnchor: [10,10],
                popupAnchor: [0,-12]
            });
        }

        function jobSiteIcon() {
            return L.divIcon({
                className: '',
                html: '<div style="width:22px;height:22px;border-radius:7px;background:#06182d;border:3px solid #ffffff;box-shadow:0 8px 18px rgba(6,24,45,.3);position:relative"><span style="position:absolute;left:5px;top:5px;width:6px;height:6px;border-radius:999px;background:#ffffff"></span></div>',
                iconSize: [22,22],
                iconAnchor: [11,11],
                popupAnchor: [0,-12]
            });
        }

        function initMap() {
            if (state.map) {
                return;
            }
            state.map = L.map(mapEl, {scrollWheelZoom:true, zoomControl:false}).setView([18.2208, -66.5901], 9);
            L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                maxZoom: 19,
                attribution: '&copy; OpenStreetMap'
            }).addTo(state.map);
        }

        function clearMap() {
            Object.keys(state.markers).forEach(function (key) {
                state.map.removeLayer(state.markers[key]);
            });
            Object.keys(state.routes).forEach(function (key) {
                state.map.removeLayer(state.routes[key]);
            });
            state.jobMarkers.forEach(function (marker) {
                state.map.removeLayer(marker);
            });
            state.pointMarkers.forEach(function (marker) {
                state.map.removeLayer(marker);
            });
            state.markers = {};
            state.routes = {};
            state.jobMarkers = [];
            state.pointMarkers = [];
            if (state.pointMarker) {
                state.map.removeLayer(state.pointMarker);
                state.pointMarker = null;
            }
        }

        function visibleWorkers() {
            var data = state.data && state.data.workers ? state.data.workers : [];
            var filter = state.filter || 'all';
            return data.filter(function (worker) {
                if (filter === 'all') return true;
                if (filter === 'active') return !!worker.open_shift;
                return worker.status === filter;
            });
        }

        function visibleJobSites(workers) {
            var sites = state.data && state.data.job_sites ? state.data.job_sites : [];
            var activeProjects = {};
            workers.forEach(function (worker) {
                if (worker.project) activeProjects[String(worker.project).toLowerCase()] = true;
            });
            return sites.filter(function (site) {
                return !!activeProjects[String(site.name || '').toLowerCase()];
            });
        }

        function drawMap() {
            initMap();
            clearMap();

            var workers = visibleWorkers();
            var bounds = [];
            workers.forEach(function (worker) {
                if (!worker.latest) {
                    return;
                }
                var latest = worker.latest;
                var popup = '<strong>' + esc(worker.name) + '</strong><br>' +
                    esc(worker.project || '') + '<br>' +
                    'Ultima senal: ' + esc(pointLabel(latest)) + '<br>' +
                    'Hora: ' + esc(latest.time || '-') + '<br>' +
                    'Precision: ' + esc(latest.accuracy || '-') + ' m<br>' +
                    'Estado: ' + statusLabel(worker.status);
                var marker = L.marker([latest.lat, latest.lng], {icon: markerIcon(worker)}).addTo(state.map).bindPopup(popup);
                marker.on('click', function () { selectWorker(worker.key, false); });
                state.markers[worker.key] = marker;
                bounds.push([latest.lat, latest.lng]);

                var showRoute = !!state.showAllPoints || worker.key === state.selected;
                if (showRoute && worker.route && worker.route.length > 1) {
                    var points = worker.route.map(function (point) { return [point.lat, point.lng]; });
                    state.routes[worker.key] = L.polyline(points, {
                        color: statusColor(worker.status),
                        weight: worker.key === state.selected ? 5 : 3,
                        opacity: worker.key === state.selected ? .92 : .38
                    }).addTo(state.map);
                    bounds = bounds.concat(points);
                }

                if (state.showAllPoints && worker.route && worker.route.length) {
                    worker.route.forEach(function (point, index) {
                        var pointMarker = L.circleMarker([point.lat, point.lng], {
                            radius: index === worker.route.length - 1 ? 6 : 4,
                            color: '#ffffff',
                            weight: 2,
                            fillColor: statusColor(worker.status),
                            fillOpacity: index === worker.route.length - 1 ? .96 : .62
                        }).addTo(state.map).bindPopup(
                            '<strong>' + esc(worker.name) + '</strong><br>' +
                            'Senal ' + esc(index + 1) + ' de ' + esc(worker.route.length) + '<br>' +
                            'Tipo: ' + esc(pointLabel(point)) + '<br>' +
                            'Hora: ' + esc(point.time || '-') + '<br>' +
                            'Precision: ' + esc(point.accuracy || '-') + ' m'
                        );
                        state.pointMarkers.push(pointMarker);
                        bounds.push([point.lat, point.lng]);
                    });
                }
            });

            visibleJobSites(workers).forEach(function (site) {
                if (site.lat === null || site.lng === null || site.lat === undefined || site.lng === undefined) {
                    return;
                }
                var popup = '<strong>Jobsite: ' + esc(site.name) + '</strong><br>' +
                    esc(site.address || '') + '<br>' +
                    (site.radius ? 'Radio: ' + esc(site.radius) + ' m<br>' : '') +
                    (site.status ? 'Estado: ' + esc(site.status) : '');
                var marker = L.marker([site.lat, site.lng], {icon: jobSiteIcon(), zIndexOffset:-200}).addTo(state.map).bindPopup(popup);
                state.jobMarkers.push(marker);
                bounds.push([site.lat, site.lng]);
                if (site.radius) {
                    var circle = L.circle([site.lat, site.lng], {
                        radius: parseFloat(site.radius) || 0,
                        color: '#06182d',
                        weight: 1,
                        opacity: .28,
                        fillColor: '#1677b9',
                        fillOpacity: .06
                    }).addTo(state.map);
                    state.jobMarkers.push(circle);
                }
            });

            emptyEl.style.display = bounds.length ? 'none' : 'flex';
            emptyEl.textContent = workers.length ? 'Hay trabajadores en la lista, pero no hay coordenadas GPS para este filtro.' : 'No hay tracking GPS para este filtro o fecha.';

            if (bounds.length) {
                state.map.fitBounds(bounds, {padding:[28,28], maxZoom:16});
            }
            drawSelectedPoint(false);
            setTimeout(function () { state.map.invalidateSize(); }, 80);
        }

        function renderStats() {
            var summary = (state.data && state.data.summary) || {};
            ['active','fresh','stale','missing','pings'].forEach(function (key) {
                var el = root.querySelector('[data-stat="' + key + '"]');
                if (!el) return;
                var value = parseInt(summary[key] || 0, 10);
                el.textContent = value;
                var card = el.closest('.cleg17-gps-stat');
                if (card) card.style.display = value > 0 ? '' : 'none';
            });
            [].slice.call(filterBarEl.querySelectorAll('[data-filter]')).forEach(function (button) {
                var filter = button.getAttribute('data-filter') || 'all';
                var value = filter === 'all' ? (summary.workers || 0) : (summary[filter] || 0);
                button.style.display = filter === 'all' || value > 0 ? '' : 'none';
                if (button.classList.contains('is-active') && button.style.display === 'none') {
                    state.filter = 'all';
                    button.classList.remove('is-active');
                    var allButton = filterBarEl.querySelector('[data-filter="all"]');
                    if (allButton) allButton.classList.add('is-active');
                }
            });
            generatedEl.textContent = state.data ? ('Actualizado ' + state.data.generated + ' - ' + state.data.label) : 'Esperando datos...';
        }

        function renderList() {
            var workers = visibleWorkers();
            if (!workers.length) {
                listEl.innerHTML = '<div style="padding:16px;color:#64748b;font-weight:800">No hay trabajadores para este filtro.</div>';
                return;
            }
            listEl.innerHTML = workers.map(function (worker) {
                var last = worker.latest ? worker.latest.time : 'Sin señal';
                var ago = worker.minutes_ago === null || worker.minutes_ago === undefined ? '' : ' - hace ' + worker.minutes_ago + ' min';
                var lastType = worker.latest ? pointLabel(worker.latest) + ' ' : '';
                return '<button type="button" class="cleg17-gps-worker ' + (worker.key === state.selected ? 'is-active' : '') + '" data-worker="' + esc(worker.key) + '">' +
                    '<span class="cleg17-gps-worker-mainline"><span class="cleg17-gps-worker-name">' + esc(worker.name) + '</span><span class="cleg17-gps-worker-status ' + worker.status + '">' + statusLabel(worker.status) + '</span></span>' +
                    '<span class="cleg17-gps-worker-meta">' + esc(worker.project || 'Sin proyecto') + ' - Última señal: ' + esc(lastType + last) + esc(ago) + ' - ' + esc(worker.ping_count || 0) + ' señales</span>' +
                    '</button>';
            }).join('');
        }

        function getSelectedWorker() {
            var workers = state.data && state.data.workers ? state.data.workers : [];
            return workers.find(function (item) { return item.key === state.selected; }) || null;
        }

        function drawSelectedPoint(center) {
            if (!state.map) {
                return;
            }

            if (state.pointMarker) {
                state.map.removeLayer(state.pointMarker);
                state.pointMarker = null;
            }

            var worker = getSelectedWorker();
            if (!worker || !worker.route || !worker.route.length || state.selectedPointIndex === null) {
                return;
            }

            var point = worker.route[state.selectedPointIndex];
            if (!point) {
                return;
            }

            state.pointMarker = L.circleMarker([point.lat, point.lng], {
                radius: 9,
                color: '#0f172a',
                weight: 3,
                fillColor: '#f97316',
                fillOpacity: .95
            }).addTo(state.map).bindPopup(
                '<strong>' + esc(worker.name) + '</strong><br>' +
                'Senal ' + esc(state.selectedPointIndex + 1) + ' de ' + esc(worker.route.length) + '<br>' +
                'Tipo: ' + esc(pointLabel(point)) + '<br>' +
                'Hora: ' + esc(point.time || '-') + '<br>' +
                'Precision: ' + esc(point.accuracy || '-') + ' m'
            );

            if (center) {
                state.map.setView([point.lat, point.lng], 17);
                state.pointMarker.openPopup();
            }
        }

        function selectPoint(index, center) {
            var worker = getSelectedWorker();
            if (!worker || !worker.route || !worker.route.length) {
                state.selectedPointIndex = null;
                return;
            }

            var max = worker.route.length - 1;
            state.selectedPointIndex = Math.max(0, Math.min(max, parseInt(index, 10) || 0));
            renderDetail(worker);
            drawMap();
            drawSelectedPoint(center);
        }

        function renderDetail(worker) {
            if (!worker) {
                return;
            }

            var latest = worker.latest;
            var routeItems = (worker.route || []).map(function (point, index) {
                return '<button type="button" class="cleg17-gps-route-point ' + (index === state.selectedPointIndex ? 'is-active' : '') + '" data-point="' + index + '">' + esc(pointLabel(point)) + '<br>' + esc(point.time || '-') + '</button>';
            }).join('');

            var total = worker.route && worker.route.length ? worker.route.length : 0;
            var current = state.selectedPointIndex === null ? 0 : state.selectedPointIndex;
            var currentPoint = total ? worker.route[current] : null;
            var jump = total ? (
                '<div class="cleg17-gps-jump">' +
                '<button type="button" class="cleg17-gps-prev" ' + (current <= 0 ? 'disabled' : '') + '>Anterior</button>' +
                '<input type="range" class="cleg17-gps-slider" min="0" max="' + esc(total - 1) + '" value="' + esc(current) + '" aria-label="Senales del recorrido">' +
                '<button type="button" class="cleg17-gps-next" ' + (current >= total - 1 ? 'disabled' : '') + '>Siguiente</button>' +
                '</div>'
            ) : '';

            detailEl.innerHTML = '<h4>' + esc(worker.name) + '</h4>' +
                '<p class="cleg17-gps-status">' + esc(worker.project || '-') + ' - ' + statusLabel(worker.status) + ' - ' + (total ? esc(total + ' señales') : 'Sin señales') + '</p>' +
                jump +
                '<div class="cleg17-gps-route">' + (routeItems || '<span class="cleg17-gps-status">No hay recorrido para esta fecha.</span>') + '</div>';
        }

        function selectWorker(key, center) {
            var workers = state.data && state.data.workers ? state.data.workers : [];
            var worker = workers.find(function (item) { return item.key === key; });
            if (!worker) {
                return;
            }
            state.selected = key;
            state.selectedPointIndex = worker.route && worker.route.length ? worker.route.length - 1 : null;
            renderList();
            renderDetail(worker);

            drawMap();
            drawSelectedPoint(center);
        }

        function renderAll() {
            renderStats();
            renderList();
            drawMap();
            if (state.selected) {
                var previous = state.selected;
                var previousPoint = state.selectedPointIndex;
                selectWorker(previous, false);
                if (previousPoint !== null) {
                    selectPoint(previousPoint, false);
                }
            }
        }

        function fitAll() {
            state.filter = 'all';
            [].slice.call(filterBarEl.querySelectorAll('[data-filter]')).forEach(function (item) {
                item.classList.toggle('is-active', item.getAttribute('data-filter') === 'all');
            });
            state.selected = null;
            state.selectedPointIndex = null;
            renderAll();
        }

        function fetchData() {
            root.classList.add('cleg17-gps-loading');
            var body = new URLSearchParams();
            body.set('action', 'cleg17_admin_tracking_data');
            body.set('nonce', nonce);
            body.set('date', dateEl.value || '');
            return fetch(ajaxUrl, {
                method: 'POST',
                credentials: 'same-origin',
                headers: {'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},
                body: body.toString()
            }).then(function (response) {
                return response.json();
            }).then(function (json) {
                if (!json || !json.success) {
                    throw new Error(json && json.data && json.data.message ? json.data.message : 'No se pudo cargar el tracking.');
                }
                state.data = json.data;
                if (!state.selected && state.data.workers && state.data.workers[0]) {
                    state.selected = state.data.workers[0].key;
                }
                renderAll();
            }).catch(function (error) {
                emptyEl.style.display = 'flex';
                emptyEl.textContent = error.message || 'No se pudo cargar el tracking GPS.';
            }).finally(function () {
                root.classList.remove('cleg17-gps-loading');
            });
        }

        listEl.addEventListener('click', function (event) {
            var button = event.target.closest('[data-worker]');
            if (button) {
                selectWorker(button.getAttribute('data-worker'), true);
            }
        });
        detailEl.addEventListener('click', function (event) {
            var point = event.target.closest('[data-point]');
            if (point) {
                selectPoint(point.getAttribute('data-point'), true);
                return;
            }
            if (event.target.closest('.cleg17-gps-prev')) {
                selectPoint((state.selectedPointIndex || 0) - 1, true);
                return;
            }
            if (event.target.closest('.cleg17-gps-next')) {
                selectPoint((state.selectedPointIndex || 0) + 1, true);
            }
        });
        detailEl.addEventListener('input', function (event) {
            if (event.target.classList.contains('cleg17-gps-slider')) {
                selectPoint(event.target.value, true);
            }
        });
        filterBarEl.addEventListener('click', function (event) {
            var button = event.target.closest('[data-filter]');
            if (!button) {
                return;
            }
            state.filter = button.getAttribute('data-filter') || 'all';
            [].slice.call(filterBarEl.querySelectorAll('[data-filter]')).forEach(function (item) {
                item.classList.toggle('is-active', item === button);
            });
            renderAll();
        });
        dateEl.addEventListener('change', function () {
            state.selected = null;
            fetchData();
        });
        root.querySelector('.cleg17-gps-refresh').addEventListener('click', fetchData);
        root.querySelector('.cleg17-gps-fit-all').addEventListener('click', fitAll);
        if (togglePointsEl) {
            togglePointsEl.addEventListener('click', function () {
                state.showAllPoints = !state.showAllPoints;
                if (state.showAllPoints) {
                    state.filter = 'all';
                    state.selected = null;
                    state.selectedPointIndex = null;
                    [].slice.call(filterBarEl.querySelectorAll('[data-filter]')).forEach(function (item) {
                        item.classList.toggle('is-active', item.getAttribute('data-filter') === 'all');
                    });
                }
                togglePointsEl.classList.toggle('is-active', state.showAllPoints);
                togglePointsEl.setAttribute('data-show-points', state.showAllPoints ? '1' : '0');
                togglePointsEl.textContent = state.showAllPoints ? 'Ocultar todas las señales' : 'Ver todas las señales';
                renderAll();
                if (state.map) {
                    setTimeout(function () { state.map.invalidateSize(); }, 120);
                }
            });
        }

        function startTracking() {
            if (state.started) {
                if (state.map) {
                    setTimeout(function () { state.map.invalidateSize(); }, 120);
                }
                return;
            }
            state.started = true;
            root.classList.remove('is-mobile-waiting');
            ensureLeaflet().then(function () {
                initMap();
                fetchData();
                setInterval(fetchData, 60000);
            }).catch(function () {
                emptyEl.style.display = 'flex';
                emptyEl.textContent = 'No se pudo cargar Leaflet para mostrar el mapa.';
            });
        }

        window.addEventListener('resize', function () {
            if (state.map) {
                setTimeout(function () { state.map.invalidateSize(); }, 120);
            }
        });
        if (root.closest('details')) {
            root.closest('details').addEventListener('toggle', function (event) {
                if (!event.currentTarget.open) {
                    return;
                }
                setTimeout(function () {
                    if (state.map) {
                        state.map.invalidateSize();
                        fitAll();
                        return;
                    }
                    startTracking();
                }, 160);
            });
        }

        startTracking();
        });
    })();
    </script>
    <?php
    return ob_get_clean();
}

add_shortcode('cleg_admin_gps_tracking', 'cleg17_admin_gps_tracking_shortcode');

add_filter('the_content', function ($content) {
    if (is_admin() || !is_page('admin-tiempo-real') || !cleg17_is_rrhh_admin()) {
        return $content;
