    if (false !== strpos($content, '[cleg_admin_gps_tracking]') || false !== strpos($content, '[cleg_admin_tiempo_real]') || false !== strpos($content, 'data-cleg17-gps')) {
        return $content;
    }

    return $content . "\n" . do_shortcode('[cleg_admin_gps_tracking]');
}, 40);
