/**
 * CLEG 18 - Command Center
 */
/**
 * CLEG 18 - Command Center v1.6 - Arranque inmediato para loader remoto
 *
 * Uso: mantiene /panel/ con el shortcode existente [cleg_panel_rrhh],
 * y contiene la vista administrativa separada de CLEG 04.
 *
 * Dependencia:
 * - CLEG 04 - Worker Panel Protected debe seguir activo.
 * - Este snippet debe estar activo despues de CLEG 04.
 *
 * Que hace:
 * - Si entra un administrador a /panel/, muestra el Vantrexor Command Center.
 * - Si entra un trabajador, delega intacto al render original de CLEG 04.
 * - Si un admin usa ?cleg_view=trabajador, tambien delega a CLEG 04.
 * - No toca marcado, GPS, geofence, AJAX, Airtable ni vistas del trabajador.
 * - v1.5 centra el panel, estabiliza tarjetas web y elimina descripcion visible segun documento visual.
 * - v1.6 restaura el override aunque el bundle remoto cargue despues de init.
 * - v1.7 deja Proyecto inaccesible y muestra modal Coming soon.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_command_center_bootstrap')) {
    function cleg_command_center_bootstrap() {
        remove_shortcode('cleg_panel_rrhh');
        add_shortcode('cleg_panel_rrhh', 'cleg_command_center_shortcode');
    }
}
add_action('init', 'cleg_command_center_bootstrap', 999);

if (did_action('init')) {
    cleg_command_center_bootstrap();
}

if (!function_exists('cleg_command_center_original_panel')) {
    function cleg_command_center_original_panel($atts = array()) {
        if (function_exists('cleg_panel_rrhh_shortcode')) {
            return cleg_panel_rrhh_shortcode($atts);
        }

        $login_url = home_url('/acceso/');

        return '<section class="cleg-command-wrap"><div class="cleg-command-shell"><p class="cleg-command-eyebrow">Portal Vantrexor</p><h2>Panel no disponible</h2><p>El modulo de trabajador todavia no esta cargado. Activa primero CLEG 04 y luego este snippet.</p><a class="cleg-command-link" href="' . esc_url($login_url) . '">Volver a acceso</a></div>' . cleg_command_center_styles() . '</section>';
    }
}

if (!function_exists('cleg_command_center_is_admin_user')) {
    function cleg_command_center_is_admin_user($user) {
        if (!$user || empty($user->ID)) {
            return false;
        }

        if (function_exists('cleg_starter_user_can_command_center')) {
            return cleg_starter_user_can_command_center();
        }

        if (current_user_can('manage_options')) {
            return true;
        }

        if (function_exists('cleg_app_get_employee') && function_exists('cleg_app_user_can_admin')) {
            $employee = cleg_app_get_employee($user);
            if (cleg_app_user_can_admin($user, $employee)) {
                return true;
            }
        }

        $admin_roles = array('administrator', 'editor', 'hr_manager', 'rrhh', 'cleg_admin');

        return !empty($user->roles) && (bool) array_intersect($admin_roles, (array) $user->roles);
    }
}

if (!function_exists('cleg_command_center_module_enabled')) {
    function cleg_command_center_module_enabled($module_key) {
        $module_key = sanitize_key((string) $module_key);
        if ($module_key === '') {
            return true;
        }

        if (function_exists('cleg_saas_module_enabled')) {
            return (bool) cleg_saas_module_enabled($module_key);
        }

        if (function_exists('cleg_shell_module_enabled')) {
            return (bool) cleg_shell_module_enabled($module_key);
        }

        return true;
    }
}

if (!function_exists('cleg_command_center_shortcode')) {
    function cleg_command_center_shortcode($atts = array()) {
        if (!is_user_logged_in()) {
            return cleg_command_center_original_panel($atts);
        }

        $user = wp_get_current_user();
        $force_worker = current_user_can('manage_options')
            && isset($_GET['cleg_view'])
            && sanitize_text_field(wp_unslash($_GET['cleg_view'])) === 'trabajador';

        if ($force_worker || !cleg_command_center_module_enabled('command_center') || !cleg_command_center_is_admin_user($user)) {
            return cleg_command_center_original_panel($atts);
        }

        return cleg_command_center_render($user);
    }
}

if (!function_exists('cleg_command_center_attention_summary')) {
    function cleg_command_center_attention_summary() {
        $summary = array(
            'label'  => 'Todo estable',
            'count'  => 0,
            'detail' => current_time('M j, g:i a') . ' PR',
            'url'    => home_url('/admin-rrhh/'),
            'tone'   => 'is-calm',
        );

        $field_enabled = cleg_command_center_module_enabled('field_ops');
        $forms_enabled = cleg_command_center_module_enabled('forms_requests');

        if (!$field_enabled && !$forms_enabled) {
            return $summary;
        }

        if (
            ($field_enabled && (!function_exists('cleg_admin_time_records') || !function_exists('cleg_admin_status_counts') || !function_exists('cleg_admin_field')))
            || ($forms_enabled && (!function_exists('cleg_admin_hr_requests') || !function_exists('cleg_admin_request_status_counts')))
        ) {
            return $summary;
        }

        $time_entries = $field_enabled ? cleg_admin_time_records('', 100) : array();
        $open_entries = $field_enabled ? cleg_admin_time_records('{Clock Out Time}=BLANK()', 100) : array();
        $hr_requests = $forms_enabled ? cleg_admin_hr_requests(100) : array();

        if ($field_enabled && (is_wp_error($time_entries) || is_wp_error($open_entries))) {
            return $summary;
        }

        if ($forms_enabled && is_wp_error($hr_requests)) {
            $hr_requests = array();
        }

        $status_counts = $field_enabled ? cleg_admin_status_counts($time_entries) : array();
        $status_counts['Open'] = $field_enabled && is_array($open_entries) ? count($open_entries) : 0;
        $request_counts = $forms_enabled ? cleg_admin_request_status_counts($hr_requests) : array();

        $shared_devices = 0;
        $missing_gps = 0;

        foreach ((array) $time_entries as $record) {
            $flags = cleg_admin_field($record, 'Audit Flags');

            if (strpos($flags, 'Shared Device Detected') !== false) {
                $shared_devices++;
            }

            if (strpos($flags, 'Missing GPS') !== false) {
                $missing_gps++;
            }
        }

        $hour_attention_count = max((int) ($status_counts['Pending Review'] ?? 0), (int) ($status_counts['Open'] ?? 0));
        $other_attention_count = (int) ($request_counts['Pending'] ?? 0) + (int) $missing_gps + (int) $shared_devices;
        $attention_count = $hour_attention_count + $other_attention_count;

        if ($field_enabled && $hour_attention_count > 0) {
            $attention_url = function_exists('cleg_admin_context_url')
                ? cleg_admin_context_url('/admin-horas/', array('cleg_status' => 'pending'))
                : home_url('/admin-horas/');
        } elseif ($forms_enabled && (int) ($request_counts['Pending'] ?? 0) > 0) {
            $attention_url = home_url('/admin-solicitudes/');
        } else {
            $attention_url = home_url('/admin-rrhh/');
        }

        return array(
            'label'  => $attention_count > 0 ? 'Atencion requerida' : 'Todo estable',
            'count'  => $attention_count,
            'detail' => $hour_attention_count . ' horas/rev + ' . $other_attention_count . ' alertas',
            'url'    => $attention_url,
            'tone'   => $attention_count > 0 ? 'is-hot' : 'is-calm',
        );
    }
}

