if (!function_exists('cleg_command_center_scripts')) {
    function cleg_command_center_scripts() {
        return <<<'HTML'
<script>
(function(){
  function ready(callback){
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', callback, {once:true});
      return;
    }
    callback();
  }

  ready(function(){
    var root = document.querySelector('.cleg-command-center-v2');
    if (!root) return;
    var modal = document.getElementById('cleg-command-coming-soon');
    var lastTrigger = null;

    function openComingSoon(trigger){
      if (!modal) return;
      lastTrigger = trigger || null;
      modal.hidden = false;
      document.body.classList.add('cleg-command-modal-open');
      var close = modal.querySelector('.cleg-command-modal-close');
      if (close) close.focus();
    }

    function closeComingSoon(){
      if (!modal) return;
      modal.hidden = true;
      document.body.classList.remove('cleg-command-modal-open');
      if (lastTrigger && lastTrigger.focus) lastTrigger.focus();
    }

    if (modal) {
      modal.addEventListener('click', function(event){
        if (event.target === modal || event.target.closest('.cleg-command-modal-close')) {
          event.preventDefault();
          closeComingSoon();
        }
      });
      document.addEventListener('keydown', function(event){
        if (event.key === 'Escape' && !modal.hidden) {
          closeComingSoon();
        }
      });
    }

    root.addEventListener('click', function(event){
      var card = event.target.closest('.cleg-command-card');
      if (!card || !root.contains(card)) return;
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || card.target === '_blank') return;

      event.preventDefault();
      if (card.getAttribute('data-cleg-command-locked') === '1') {
        openComingSoon(card);
        return;
      }
      var href = card.getAttribute('href');
      if (!href) return;

      if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        window.location.href = href;
        return;
      }

      var rect = card.getBoundingClientRect();
      var clone = card.cloneNode(true);
      clone.classList.add('cleg-command-transition-clone');
      clone.removeAttribute('href');
      clone.style.top = rect.top + 'px';
      clone.style.left = rect.left + 'px';
      clone.style.width = rect.width + 'px';
      clone.style.height = rect.height + 'px';
      clone.style.padding = window.getComputedStyle(card).padding;

      document.body.classList.add('cleg-command-is-transitioning');
      document.body.appendChild(clone);

      requestAnimationFrame(function(){
        clone.classList.add('is-active');
      });

      window.setTimeout(function(){
        window.location.href = href;
      }, 520);
    });
  });
})();
</script>
HTML;
    }
}
