/**
 * CLEG 19B - Procurement Support Layer v1.0
 *
 * Capa backend pasiva para helpers de permisos, hashes e idempotencia.
 * No registra hooks, no renderiza interfaz y no escribe datos al cargar.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_procurement_user_can_manage')) {
    function cleg_procurement_user_can_manage($user = null) {
        $user = $user ?: wp_get_current_user();

        if (!$user || empty($user->ID)) {
            return false;
        }

        if (user_can($user, 'manage_options') || user_can($user, 'cleg_manage_procurement')) {
            return true;
        }

        return user_can($user, 'cleg_manage_procurement');
    }
}

if (!function_exists('cleg_procurement_normalize_payload_for_hash')) {
    function cleg_procurement_normalize_payload_for_hash($payload) {
        if (is_array($payload)) {
            ksort($payload);
            foreach ($payload as $key => $value) {
                $payload[$key] = cleg_procurement_normalize_payload_for_hash($value);
            }
            return $payload;
        }

        if (is_bool($payload) || is_int($payload) || is_float($payload) || $payload === null) {
            return $payload;
        }

        return trim((string) $payload);
    }
}

if (!function_exists('cleg_procurement_payload_hash')) {
    function cleg_procurement_payload_hash($payload) {
        $normalized = cleg_procurement_normalize_payload_for_hash($payload);
        $encoded = wp_json_encode($normalized, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

        if (!is_string($encoded)) {
            $encoded = '';
        }

        return hash('sha256', $encoded);
    }
}

if (!function_exists('cleg_procurement_idempotency_key')) {
    function cleg_procurement_idempotency_key($entity_type, $operation, $source, $stable_id, $payload = array()) {
        $parts = array(
            'procurement',
            sanitize_key((string) $entity_type),
            sanitize_key((string) $operation),
            sanitize_key((string) $source),
            sanitize_key((string) $stable_id),
            cleg_procurement_payload_hash($payload),
        );

        return implode(':', array_filter($parts, static function ($part) {
            return $part !== '';
        }));
    }
}

if (!function_exists('cleg_procurement_healthcheck')) {
    function cleg_procurement_healthcheck($data = null) {
        $data = is_array($data) ? $data : (function_exists('cleg_procurement_get_data') ? cleg_procurement_get_data() : array());
        $requests = isset($data['requests']) && is_array($data['requests']) ? $data['requests'] : array();
        $quotes = isset($data['quotes']) && is_array($data['quotes']) ? $data['quotes'] : array();
        $pos = isset($data['pos']) && is_array($data['pos']) ? $data['pos'] : array();
        $updates = function_exists('cleg_procurement_all_pending_agent_updates') ? cleg_procurement_all_pending_agent_updates() : array();

        $pending_updates = 0;
        $closed_updates = 0;
        foreach ($updates as $update) {
            $status = is_array($update) ? sanitize_key((string) ($update['status'] ?? 'pending')) : 'pending';
            if (in_array($status, array('applied', 'dismissed'), true)) {
                $closed_updates++;
            } else {
                $pending_updates++;
            }
        }

        $warnings = array();
        foreach ($quotes as $quote_key => $quote_value) {
            if (is_array($quote_value) && isset($quote_value['request_id']) && !isset($requests[$quote_key])) {
                $warnings[] = 'quote_not_grouped_by_request:' . sanitize_key((string) $quote_key);
            }
        }

        return array(
            'module' => 'procurement',
            'checked_at' => current_time('mysql'),
            'requests' => count($requests),
            'quote_groups' => count($quotes),
            'purchase_orders' => count($pos),
            'pending_updates' => $pending_updates,
            'closed_updates' => $closed_updates,
            'airtable_ready' => function_exists('cleg_procurement_airtable_ready') ? (bool) cleg_procurement_airtable_ready() : false,
            'sharepoint_graph_ready' => function_exists('cleg_procurement_sharepoint_graph_ready') ? (bool) cleg_procurement_sharepoint_graph_ready() : false,
            'warnings' => $warnings,
        );
    }
}
