if (!function_exists('cleg_procurement_user_can_access')) {
    function cleg_procurement_user_can_access($user = null) {
        if (!cleg_procurement_module_enabled()) {
            return false;
        }

        $user = $user ?: wp_get_current_user();

        if (!$user || empty($user->ID)) {
            return false;
        }

        if (current_user_can('manage_options')) {
            return true;
        }

        if (function_exists('cleg_starter_user_can_procurement') && cleg_starter_user_can_procurement()) {
            return true;
        }

        if (function_exists('cleg_command_center_is_admin_user') && cleg_command_center_is_admin_user($user)) {
            return true;
        }

        $allowed = cleg_procurement_allowed_roles();
        return !empty($user->roles) && (bool) array_intersect($allowed, (array) $user->roles);
    }
}

if (!function_exists('cleg_procurement_user_can_manage_requests')) {
    function cleg_procurement_user_can_manage_requests($user = null) {
        $user = $user ?: wp_get_current_user();

        if (!$user || empty($user->ID)) {
            return false;
        }

        if (user_can($user, 'manage_options') || user_can($user, 'cleg_manage_procurement')) {
            return true;
        }

        return function_exists('cleg_procurement_user_can_manage') && cleg_procurement_user_can_manage($user);
    }
}

