}

if (!function_exists('cleg_procurement_normalize_owner_token')) {
    function cleg_procurement_normalize_owner_token($value) {
        return strtolower(trim(remove_accents((string) $value)));
    }
}

if (!function_exists('cleg_procurement_request_belongs_to_user')) {
    function cleg_procurement_request_belongs_to_user($request, $user = null) {
        $user = $user ?: wp_get_current_user();

        if (!$user || empty($user->ID) || !is_array($request)) {
            return false;
        }

        $user_id = (string) (int) $user->ID;
        foreach (array('requester_user_id', 'requested_by_user_id', 'wp_user_id', 'WordPress User ID') as $id_key) {
            if (!empty($request[$id_key]) && (string) (int) $request[$id_key] === $user_id) {
                return true;
            }
        }

        $tokens = array_filter(array_map('cleg_procurement_normalize_owner_token', array(
            $user->display_name,
            $user->user_login,
            $user->user_email,
            get_user_meta($user->ID, 'nickname', true),
            trim((string) get_user_meta($user->ID, 'first_name', true) . ' ' . (string) get_user_meta($user->ID, 'last_name', true)),
        )));

        $request_values = array_filter(array_map('cleg_procurement_normalize_owner_token', array(
            $request['requester'] ?? '',
            $request['created_by'] ?? '',
            $request['requester_login'] ?? '',
            $request['requester_email'] ?? '',
            $request['portal_username'] ?? '',
            $request['Portal Username'] ?? '',
            $request['Requested By Name'] ?? '',
            $request['Requested By Email'] ?? '',
        )));

        return (bool) array_intersect($tokens, $request_values);
    }
}

if (!function_exists('cleg_procurement_filter_requests_for_user')) {
    function cleg_procurement_filter_requests_for_user($requests, $user = null) {
        $user = $user ?: wp_get_current_user();

        if (!is_array($requests)) {
            return array();
        }

        if (cleg_procurement_user_can_view_all_requests($user)) {
            return $requests;
        }

        if (!$user || empty($user->ID) || !user_can($user, 'cleg_view_own_purchase_requests')) {
            return array();
        }

        return array_filter($requests, function ($request) use ($user) {
            return cleg_procurement_request_belongs_to_user($request, $user);
        });
    }
}

if (!function_exists('cleg_procurement_user_can_view_request')) {
    function cleg_procurement_user_can_view_request($request, $user = null) {
        $user = $user ?: wp_get_current_user();

        return cleg_procurement_user_can_view_all_requests($user)
            || (user_can($user, 'cleg_view_own_purchase_requests') && cleg_procurement_request_belongs_to_user($request, $user));
    }
}

if (!function_exists('cleg_procurement_user_can_edit_request')) {
    function cleg_procurement_user_can_edit_request($request, $user = null) {
        $user = $user ?: wp_get_current_user();

        return cleg_procurement_user_can_manage_requests($user);
    }
}

if (!function_exists('cleg_procurement_require_manage_action')) {
    function cleg_procurement_require_manage_action() {
        if (!cleg_procurement_user_can_manage_requests(wp_get_current_user())) {
            wp_die(esc_html__('Acceso restringido.', 'cleg'));
        }
    }
}

if (!function_exists('cleg_procurement_require_request_edit')) {
