        }
    }
}

if (!function_exists('cleg_procurement_guard')) {
    function cleg_procurement_guard() {
        if (!is_user_logged_in()) {
            wp_safe_redirect(add_query_arg('cleg_redirect', rawurlencode('/admin-procurement/'), home_url('/acceso/')));
            exit;
        }

        if (!cleg_procurement_user_can_access()) {
            wp_die(esc_html__('No tienes acceso al modulo de procurement.', 'cleg'));
        }
    }
}

if (!function_exists('cleg_procurement_is_page_request')) {
    function cleg_procurement_is_page_request() {
        if (is_admin()) {
            return false;
        }

        $uri = isset($_SERVER['REQUEST_URI']) ? sanitize_text_field(wp_unslash($_SERVER['REQUEST_URI'])) : '';
        $path = parse_url($uri, PHP_URL_PATH);
        $path = '/' . trim((string) $path, '/') . '/';

        return $path === '/admin-procurement/';
    }
}

