if (!function_exists('cleg_procurement_airtable_date')) {
    function cleg_procurement_airtable_date($value) {
        $value = trim((string) $value);
        if ($value === '') {
            return '';
        }

        $timestamp = strtotime($value);
        return $timestamp ? gmdate('Y-m-d', $timestamp) : '';
    }
}

if (!function_exists('cleg_procurement_airtable_datetime')) {
    function cleg_procurement_airtable_datetime($value) {
        $value = trim((string) $value);
        if ($value === '') {
            return '';
        }

        $timestamp = strtotime($value);
        return $timestamp ? gmdate('c', $timestamp) : '';
    }
}

if (!function_exists('cleg_procurement_client_response_options')) {
    function cleg_procurement_client_response_options() {
        return array('Pendiente', 'Aceptada', 'Rechazada', 'Necesita revision', 'Sin respuesta');
    }
}

if (!function_exists('cleg_procurement_client_follow_up_due_date')) {
    function cleg_procurement_client_follow_up_due_date($request, $urgent = false) {
        $urgent_terms = strtolower(remove_accents(trim((string) (($request['priority'] ?? '') . ' ' . ($request['urgency_reason'] ?? '') . ' ' . ($request['urgency_notes'] ?? '')))));
        $urgent = $urgent || preg_match('/urgente|detiene|hoy|24|emergency|critical|alta/', $urgent_terms);
        $timestamp = current_time('timestamp');

        if ($urgent) {
            return date_i18n('Y-m-d', strtotime('+1 day', $timestamp));
        }

        $days_added = 0;
        while ($days_added < 3) {
            $timestamp = strtotime('+1 day', $timestamp);
            $weekday = (int) date_i18n('N', $timestamp);
            if ($weekday <= 5) {
                $days_added++;
            }
        }

        return date_i18n('Y-m-d', $timestamp);
    }
}

if (!function_exists('cleg_procurement_client_days_since')) {
    function cleg_procurement_client_days_since($sent_at) {
        $timestamp = strtotime((string) $sent_at);
        if (!$timestamp) {
            return null;
        }

        $today = strtotime(current_time('Y-m-d'));
        $sent = strtotime(gmdate('Y-m-d', $timestamp));
        return $today && $sent ? max(0, (int) floor(($today - $sent) / DAY_IN_SECONDS)) : null;
    }
}

if (!function_exists('cleg_procurement_client_quote_context')) {
    function cleg_procurement_client_quote_context($quote) {
        $status = trim((string) ($quote['client_response_status'] ?? ''));
        $sent_at = trim((string) ($quote['client_sent_at'] ?? ''));
        $due = cleg_procurement_airtable_date($quote['client_follow_up_due_date'] ?? '');
        $days = cleg_procurement_client_days_since($sent_at);
        $today = current_time('Y-m-d');
        $closed = in_array($status, array('Aceptada', 'Rechazada', 'Sin respuesta'), true);
        $label = $status !== '' ? $status : 'No enviada';
        $tone = 'neutral';
        $alert = '';

        if ($closed) {
            $tone = $status === 'Aceptada' ? 'ok' : 'muted';
            $alert = 'Cerrado';
        } elseif ($sent_at !== '') {
            $tone = 'warn';
            $label = $status !== '' ? $status : 'Pendiente';
            $alert = $days === null ? 'Enviado al cliente' : 'Enviado hace ' . $days . ' dia' . ($days === 1 ? '' : 's');
            if ($due !== '' && $due <= $today) {
                $tone = 'danger';
                $alert = 'Toca seguimiento';
            }
        }

        return array(
            'label' => $label,
            'tone' => $tone,
            'alert' => $alert,
            'due' => $due,
            'days' => $days,
        );
    }
}

if (!function_exists('cleg_procurement_display_datetime')) {
    function cleg_procurement_display_datetime($value) {
        $value = trim((string) $value);
        if ($value === '') {
            return 'Pendiente';
        }

        $timestamp = strtotime($value);
        if (!$timestamp) {
            return $value;
        }

        return date_i18n('Y-m-d H:i', $timestamp);
    }
}

if (!function_exists('cleg_procurement_airtable_scalar')) {
    function cleg_procurement_airtable_scalar($fields, $name, $default = '') {
        if (!is_array($fields) || !array_key_exists($name, $fields)) {
            return $default;
        }

        $value = $fields[$name];
        if (is_array($value)) {
            return isset($value[0]) ? (string) $value[0] : $default;
        }

        if (is_bool($value)) {
            return $value ? '1' : '';
        }

        return (string) $value;
    }
}

if (!function_exists('cleg_procurement_attachment_key')) {
    function cleg_procurement_attachment_key($attachment) {
        if (is_array($attachment)) {
            $url = isset($attachment['url']) ? strtolower(trim((string) $attachment['url'])) : '';
            if ($url !== '') {
                $parts = wp_parse_url($url);
                $path = isset($parts['path']) ? strtolower((string) $parts['path']) : $url;
                $query = isset($parts['query']) ? strtolower((string) $parts['query']) : '';
                return md5($path . '|' . $query);
            }

            foreach (array('id', 'filename', 'name') as $key) {
                if (!empty($attachment[$key])) {
                    return sanitize_key((string) $attachment[$key]);
                }
            }
        }

        $value = strtolower(trim((string) $attachment));
        return $value !== '' ? md5($value) : '';
    }
}

if (!function_exists('cleg_procurement_dedupe_attachments')) {
    function cleg_procurement_dedupe_attachments($attachments) {
        $clean = array();
        $seen = array();

        foreach ((array) $attachments as $attachment) {
            $url = '';
            if (is_array($attachment)) {
                $url = isset($attachment['url']) ? esc_url_raw((string) $attachment['url']) : '';
            } else {
                $url = esc_url_raw((string) $attachment);
                $attachment = array('url' => $url);
            }

            if ($url === '') {
                continue;
            }

            $key = cleg_procurement_attachment_key($attachment);
            if ($key === '' || isset($seen[$key])) {
                continue;
            }

            $seen[$key] = true;
            $clean[] = array_filter(array(
                'id' => isset($attachment['id']) ? sanitize_text_field((string) $attachment['id']) : '',
                'url' => $url,
                'name' => isset($attachment['name']) ? sanitize_text_field((string) $attachment['name']) : '',
                'filename' => isset($attachment['filename']) ? sanitize_text_field((string) $attachment['filename']) : '',
                'type' => isset($attachment['type']) ? sanitize_text_field((string) $attachment['type']) : '',
            ), function ($value) {
                return $value !== '';
            });
        }

        return $clean;
    }
}

if (!function_exists('cleg_procurement_attachment_is_image')) {
    function cleg_procurement_attachment_is_image($attachment) {
        $type = is_array($attachment) ? strtolower((string) ($attachment['type'] ?? '')) : '';
        if ($type !== '' && strpos($type, 'image/') === 0) {
            return true;
        }

        $url = is_array($attachment) ? (string) ($attachment['url'] ?? '') : (string) $attachment;
        $path = strtolower((string) parse_url($url, PHP_URL_PATH));
        return (bool) preg_match('/\.(jpe?g|png|gif|webp|avif|svg)$/', $path);
    }
}

if (!function_exists('cleg_procurement_attachment_kind')) {
    function cleg_procurement_attachment_kind($attachment) {
        $type = is_array($attachment) ? strtolower((string) ($attachment['type'] ?? '')) : '';
        $url = is_array($attachment) ? (string) ($attachment['url'] ?? '') : (string) $attachment;
        $path = strtolower((string) parse_url($url, PHP_URL_PATH));

        if ($type !== '') {
            if (strpos($type, 'image/') === 0) {
                return 'image';
            }
            if (strpos($type, 'audio/') === 0) {
                return 'audio';
            }
            if (strpos($type, 'video/') === 0) {
                return 'video';
            }
            if ($type === 'application/pdf') {
                return 'pdf';
            }
        }

        if (preg_match('/\.(jpe?g|png|gif|webp|avif|svg|heic|heif|bmp|tiff?)$/', $path)) {
            return 'image';
        }
        if (preg_match('/\.(mp3|m4a|aac|wav|ogg|oga|opus|webm)$/', $path)) {
            return 'audio';
        }
        if (preg_match('/\.(mp4|mov|webm|m4v)$/', $path)) {
            return 'video';
        }
        if (preg_match('/\.pdf$/', $path)) {
            return 'pdf';
        }

        return 'document';
    }
}

if (!function_exists('cleg_procurement_attachment_name')) {
    function cleg_procurement_attachment_name($attachment, $fallback = 'Adjunto') {
        if (is_array($attachment)) {
            $name = (string) (($attachment['name'] ?? '') ?: ($attachment['filename'] ?? ''));
            if ($name !== '') {
                return $name;
            }

            $url = (string) ($attachment['url'] ?? '');
        } else {
            $url = (string) $attachment;
        }

        $basename = basename((string) parse_url($url, PHP_URL_PATH));
        return $basename !== '' ? $basename : $fallback;
    }
}

if (!function_exists('cleg_procurement_quote_documents')) {
    function cleg_procurement_quote_documents($quote) {
        return cleg_procurement_dedupe_attachments(array_merge(
            (array) ($quote['files'] ?? array()),
            (array) ($quote['quote_documents'] ?? array())
        ));
    }
}

if (!function_exists('cleg_procurement_airtable_attachment_urls')) {
    function cleg_procurement_airtable_attachment_urls($fields, $name) {
        if (!is_array($fields) || empty($fields[$name]) || !is_array($fields[$name])) {
            return array();
        }

        $attachments = array();
        foreach ($fields[$name] as $attachment) {
            if (!is_array($attachment) || empty($attachment['url'])) {
                continue;
            }

            $attachments[] = array(
                'id' => isset($attachment['id']) ? sanitize_text_field($attachment['id']) : 0,
                'url' => esc_url_raw($attachment['url']),
                'name' => isset($attachment['filename']) ? sanitize_text_field($attachment['filename']) : '',
                'type' => isset($attachment['type']) ? sanitize_text_field($attachment['type']) : '',
            );
        }

        return cleg_procurement_dedupe_attachments($attachments);
    }
}

if (!function_exists('cleg_procurement_airtable_attachments_from_payload')) {
    function cleg_procurement_airtable_attachments_from_payload($payload, $keys = null) {
        if (!is_array($payload)) {
            return array();
        }

        $sources = array();
        $keys = is_array($keys) ? $keys : array('files', 'file_urls', 'attachments', 'documents');
        foreach ($keys as $key) {
            if (!empty($payload[$key])) {
                $sources = array_merge($sources, (array) $payload[$key]);
            }
        }

        if (!empty($payload['file_url'])) {
            $sources[] = $payload['file_url'];
        }

        $attachments = array();
        foreach ($sources as $file) {
            $url = '';
            $filename = '';

            if (is_array($file)) {
                $url = (string) ($file['url'] ?? $file['download_url'] ?? '');
                $filename = sanitize_file_name((string) ($file['filename'] ?? $file['name'] ?? ''));
            } elseif (is_string($file)) {
                $url = $file;
            }

            if ($url === '' || !wp_http_validate_url($url)) {
                continue;
            }

            $attachment = array('url' => esc_url_raw($url));
            if ($filename !== '') {
                $attachment['filename'] = $filename;
            }
            $attachments[] = $attachment;
        }

        return cleg_procurement_dedupe_attachments($attachments);
    }
}

if (!function_exists('cleg_procurement_upload_reference_images')) {
    function cleg_procurement_upload_reference_images($field_name) {
        if (empty($_FILES[$field_name]) || empty($_FILES[$field_name]['name'])) {
            return array();
        }

        if (!function_exists('media_handle_upload')) {
            require_once ABSPATH . 'wp-admin/includes/file.php';
            require_once ABSPATH . 'wp-admin/includes/media.php';
            require_once ABSPATH . 'wp-admin/includes/image.php';
        }

        $files = $_FILES[$field_name];
        $uploaded = array();
        $count = is_array($files['name']) ? count($files['name']) : 1;

        for ($index = 0; $index < $count; $index++) {
            $file = array(
                'name' => is_array($files['name']) ? $files['name'][$index] : $files['name'],
                'type' => is_array($files['type']) ? $files['type'][$index] : $files['type'],
                'tmp_name' => is_array($files['tmp_name']) ? $files['tmp_name'][$index] : $files['tmp_name'],
                'error' => is_array($files['error']) ? $files['error'][$index] : $files['error'],
                'size' => is_array($files['size']) ? $files['size'][$index] : $files['size'],
            );

            if ((int) $file['error'] !== UPLOAD_ERR_OK || empty($file['tmp_name'])) {
                continue;
            }

            $_FILES['cleg_procurement_single_upload'] = $file;
            $attachment_id = media_handle_upload('cleg_procurement_single_upload', 0);

            if (!is_wp_error($attachment_id)) {
                $url = wp_get_attachment_url($attachment_id);
                if ($url) {
                    $uploaded[] = array(
                        'id' => $attachment_id,
                        'url' => esc_url_raw($url),
                        'name' => sanitize_text_field((string) ($file['name'] ?? '')),
                        'filename' => sanitize_text_field((string) ($file['name'] ?? '')),
                        'type' => sanitize_text_field((string) ($file['type'] ?? '')),
                    );
                }
            }
        }

        unset($_FILES['cleg_procurement_single_upload']);
        return cleg_procurement_dedupe_attachments($uploaded);
    }
}

if (!function_exists('cleg_procurement_upload_recorded_audio')) {
    function cleg_procurement_upload_recorded_audio() {
        $data_url = isset($_POST['cleg_recorded_audio_data']) ? (string) wp_unslash($_POST['cleg_recorded_audio_data']) : '';
        if ($data_url === '' || strpos($data_url, 'data:audio/') !== 0 || strpos($data_url, ';base64,') === false) {
            return array();
        }

        if (!function_exists('wp_upload_bits')) {
            require_once ABSPATH . 'wp-admin/includes/file.php';
        }
        if (!function_exists('wp_generate_attachment_metadata')) {
            require_once ABSPATH . 'wp-admin/includes/image.php';
        }

        list($header, $payload) = explode(';base64,', $data_url, 2);
        $mime = sanitize_mime_type(str_replace('data:', '', $header));
        $allowed_mimes = array(
            'audio/mp4' => 'm4a',
            'audio/aac' => 'aac',
            'audio/wav' => 'wav',
            'audio/x-wav' => 'wav',
            'audio/ogg' => 'ogg',
            'audio/opus' => 'opus',
            'audio/webm' => 'webm',
            'audio/mpeg' => 'mp3',
            'audio/mp3' => 'mp3',
        );

        if (!isset($allowed_mimes[$mime])) {
            return array();
        }

        $binary = base64_decode($payload, true);
        if ($binary === false || strlen($binary) < 128 || strlen($binary) > 15 * 1024 * 1024) {
            return array();
        }

        $posted_name = sanitize_file_name(wp_unslash($_POST['cleg_recorded_audio_name'] ?? ''));
        $extension = $allowed_mimes[$mime];
        if ($posted_name === '' || !preg_match('/\.' . preg_quote($extension, '/') . '$/i', $posted_name)) {
            $posted_name = 'solicitud-audio-' . gmdate('Ymd-His') . '.' . $extension;
        }

        $upload = wp_upload_bits($posted_name, null, $binary);
        if (!empty($upload['error']) || empty($upload['file']) || empty($upload['url'])) {
            return array();
        }

        $attachment_id = wp_insert_attachment(array(
            'post_mime_type' => $mime,
            'post_title' => sanitize_text_field(pathinfo($posted_name, PATHINFO_FILENAME)),
            'post_content' => '',
            'post_status' => 'inherit',
        ), $upload['file']);

        if (is_wp_error($attachment_id)) {
            return array();
        }

        $metadata = wp_generate_attachment_metadata($attachment_id, $upload['file']);
        if (!is_wp_error($metadata) && is_array($metadata)) {
            wp_update_attachment_metadata($attachment_id, $metadata);
        }

        return array(array(
            'id' => $attachment_id,
            'url' => esc_url_raw($upload['url']),
            'name' => sanitize_text_field($posted_name),
            'filename' => sanitize_text_field($posted_name),
            'type' => sanitize_text_field($mime),
        ));
    }
}

if (!function_exists('cleg_procurement_has_uploaded_recorded_audio')) {
    function cleg_procurement_has_uploaded_recorded_audio($uploads) {
        $posted_name = sanitize_file_name(wp_unslash($_POST['cleg_recorded_audio_name'] ?? ''));
        foreach ((array) $uploads as $upload) {
            $type = (string) ($upload['type'] ?? '');
            $name = sanitize_file_name((string) ($upload['filename'] ?? ($upload['name'] ?? '')));
            if (strpos($type, 'audio/') === 0 && ($posted_name === '' || $name === $posted_name)) {
                return true;
            }
        }
        return false;
    }
}

if (!function_exists('cleg_procurement_collect_reference_uploads')) {
