        $uploads = cleg_procurement_upload_reference_images($field_name);
        if (!cleg_procurement_has_uploaded_recorded_audio($uploads)) {
            $uploads = array_merge($uploads, cleg_procurement_upload_recorded_audio());
        }
        return cleg_procurement_dedupe_attachments($uploads);
    }
}

