if (!function_exists('cleg_procurement_airtable_data')) {
    function cleg_procurement_airtable_data() {
        if (!cleg_procurement_airtable_ready()) {
            return new WP_Error('cleg_procurement_airtable_missing', 'Airtable no esta configurado para Compras.');
        }

        $request_records = cleg_admin_records(CLEG_PROC_AIRTABLE_REQUESTS_TABLE, array(
            'pageSize' => 100,
            'sort[0][field]' => 'Created Date',
            'sort[0][direction]' => 'desc',
        ));

        if (is_wp_error($request_records)) {
            return $request_records;
        }

        $item_records = cleg_admin_records(CLEG_PROC_AIRTABLE_ITEMS_TABLE, array('pageSize' => 100));
        if (is_wp_error($item_records)) {
            $item_records = array();
        }

        $quote_records = cleg_admin_records(CLEG_PROC_AIRTABLE_QUOTES_TABLE, array('pageSize' => 100));
        if (is_wp_error($quote_records)) {
            $quote_records = array();
        }

        $po_records = cleg_admin_records(CLEG_PROC_AIRTABLE_POS_TABLE, array('pageSize' => 100));
        if (is_wp_error($po_records)) {
            $po_records = array();
        }

        $shipment_records = cleg_admin_records(CLEG_PROC_AIRTABLE_SHIPMENTS_TABLE, array('pageSize' => 100));
        if (is_wp_error($shipment_records)) {
            $shipment_records = array();
        }

        $items_by_request = array();
        foreach ($item_records as $record) {
            $fields = isset($record['fields']) && is_array($record['fields']) ? $record['fields'] : array();
            $linked = isset($fields['Procurement Requests']) && is_array($fields['Procurement Requests']) ? $fields['Procurement Requests'] : array();
            foreach ($linked as $request_record_id) {
                $items_by_request[$request_record_id][] = array(
                    '_airtable_id' => sanitize_text_field($record['id'] ?? ''),
                    'fields' => $fields,
                );
            }
        }

        $data = array(
            'requests' => array(),
            'quotes' => array(),
            'pos' => array(),
            'next_request' => count($request_records) + 1,
            'next_po' => 1,
            'audit' => array(),
            'source' => 'airtable',
        );

        $code_by_record_id = array();
        foreach ($request_records as $record) {
            $request = cleg_procurement_request_from_airtable($record, $items_by_request);
            $data['requests'][$request['id']] = $request;
            if (!empty($request['airtable_id'])) {
                $code_by_record_id[$request['airtable_id']] = $request['id'];
            }
        }

        foreach ($quote_records as $record) {
            $fields = isset($record['fields']) && is_array($record['fields']) ? $record['fields'] : array();
            $linked = isset($fields['Procurement Requests']) && is_array($fields['Procurement Requests']) ? $fields['Procurement Requests'] : array();
            foreach ($linked as $request_record_id) {
                if (empty($code_by_record_id[$request_record_id])) {
                    continue;
                }

                $request_code = $code_by_record_id[$request_record_id];
                if (!isset($data['quotes'][$request_code])) {
                    $data['quotes'][$request_code] = array();
                }

                $data['quotes'][$request_code][] = array(
                    'airtable_id' => sanitize_text_field($record['id'] ?? ''),
                    'vendor' => cleg_procurement_airtable_scalar($fields, 'Vendor Name Snapshot', ''),
                    'contact' => cleg_procurement_airtable_scalar($fields, 'Contact Snapshot', ''),
                    'amount' => cleg_procurement_airtable_scalar($fields, 'Quote Amount', '0'),
                    'eta' => cleg_procurement_airtable_scalar($fields, 'Lead Time', ''),
                    'expires' => cleg_procurement_airtable_scalar($fields, 'Expiration Date', ''),
                    'risk' => cleg_procurement_airtable_scalar($fields, 'Can Meet Required Delivery Date', ''),
                    'quote_status' => cleg_procurement_airtable_scalar($fields, 'Quote Status', 'Received'),
                    'can_meet_required_delivery_date' => cleg_procurement_airtable_scalar($fields, 'Can Meet Required Delivery Date', 'Unknown'),
                    'recommended' => cleg_procurement_airtable_scalar($fields, 'Recommended', '') ? 'yes' : 'no',
                    'notes' => cleg_procurement_airtable_scalar($fields, 'Recommendation Reason', cleg_procurement_airtable_scalar($fields, 'Delivery Risk Notes', '')),
                    'estimated_delivery_to_pr' => cleg_procurement_airtable_scalar($fields, 'Estimated Delivery to PR', ''),
                    'delivery_risk_notes' => cleg_procurement_airtable_scalar($fields, 'Delivery Risk Notes', ''),
                    'supplier_contact_person' => cleg_procurement_airtable_scalar($fields, 'Supplier Contact Person', ''),
                    'supplier_contact_email' => cleg_procurement_airtable_scalar($fields, 'Supplier Contact Email', ''),
                    'supplier_contact_phone' => cleg_procurement_airtable_scalar($fields, 'Supplier Contact Phone', ''),
                    'decision_support_notes' => cleg_procurement_airtable_scalar($fields, 'Decision Support Notes', ''),
                    'client_response_status' => cleg_procurement_airtable_scalar($fields, 'Client Response Status', ''),
                    'client_sent_at' => cleg_procurement_airtable_scalar($fields, 'Client Sent At', ''),
                    'client_follow_up_due_date' => cleg_procurement_airtable_scalar($fields, 'Client Follow Up Due Date', ''),
                    'client_response_at' => cleg_procurement_airtable_scalar($fields, 'Client Response At', ''),
                    'client_follow_up_count' => cleg_procurement_airtable_scalar($fields, 'Client Follow Up Count', ''),
                    'client_last_follow_up_date' => cleg_procurement_airtable_scalar($fields, 'Client Last Follow Up Date', ''),
                    'client_decision_notes' => cleg_procurement_airtable_scalar($fields, 'Client Decision Notes', ''),
                    'client_follow_up_status' => cleg_procurement_airtable_scalar($fields, 'Client Follow Up Status', ''),
                    'client_days_since_sent' => cleg_procurement_airtable_scalar($fields, 'Client Days Since Sent', ''),
                    'files' => cleg_procurement_airtable_attachment_urls($fields, 'Quote Documents'),
                );
            }
        }

        $tracking_by_po_record_id = array();
        foreach ($shipment_records as $record) {
            $fields = isset($record['fields']) && is_array($record['fields']) ? $record['fields'] : array();
            $po_links = isset($fields['Procurement POs']) && is_array($fields['Procurement POs']) ? $fields['Procurement POs'] : array();
            $tracking_number = cleg_procurement_airtable_scalar($fields, 'Tracking Number', '');
            if ($tracking_number === '') {
                continue;
            }

            foreach ($po_links as $po_record_id) {
                $po_record_id = sanitize_text_field((string) $po_record_id);
                if ($po_record_id !== '' && empty($tracking_by_po_record_id[$po_record_id])) {
                    $tracking_by_po_record_id[$po_record_id] = $tracking_number;
                }
            }
        }

        foreach ($po_records as $record) {
            $fields = isset($record['fields']) && is_array($record['fields']) ? $record['fields'] : array();
            $linked = isset($fields['Procurement Requests']) && is_array($fields['Procurement Requests']) ? $fields['Procurement Requests'] : array();
            $po_airtable_id = sanitize_text_field($record['id'] ?? '');

            foreach ($linked as $request_record_id) {
                if (empty($code_by_record_id[$request_record_id])) {
                    continue;
                }

                $request_code = $code_by_record_id[$request_record_id];
                $po_number = cleg_procurement_airtable_scalar($fields, 'PO Number', sanitize_text_field($record['id'] ?? ''));
                if ($po_number === '') {
                    continue;
                }

                $quote_links = isset($fields['Procurement Quotes']) && is_array($fields['Procurement Quotes']) ? $fields['Procurement Quotes'] : array();
                $po = array(
                    'id' => $po_number,
                    'airtable_id' => $po_airtable_id,
                    'request_id' => $request_code,
                    'vendor' => cleg_procurement_airtable_scalar($fields, 'Vendor Name Snapshot', ''),
                    'amount' => cleg_procurement_airtable_scalar($fields, 'Total', cleg_procurement_airtable_scalar($fields, 'Subtotal', '0')),
                    'eta' => cleg_procurement_airtable_scalar($fields, 'Estimated Arrival', ''),
                    'ordered_date' => cleg_procurement_airtable_scalar($fields, 'Ordered Date', cleg_procurement_airtable_scalar($fields, 'PO Date', '')),
                    'status' => cleg_procurement_airtable_scalar($fields, 'PO Status', 'Ordered'),
                    'tracking' => $tracking_by_po_record_id[$po_airtable_id] ?? '',
                    'received_qty' => 0,
                    'quote_airtable_id' => isset($quote_links[0]) ? sanitize_text_field($quote_links[0]) : '',
                    'created_at' => cleg_procurement_airtable_scalar($fields, 'PO Date', ''),
                    'updated_at' => cleg_procurement_airtable_scalar($fields, 'Ordered Date', cleg_procurement_airtable_scalar($fields, 'PO Date', '')),
                );

                $data['pos'][$po_number] = $po;

                if (isset($data['requests'][$request_code])) {
                    if (empty($data['requests'][$request_code]['po_airtable_ids']) || !is_array($data['requests'][$request_code]['po_airtable_ids'])) {
                        $data['requests'][$request_code]['po_airtable_ids'] = array();
                    }
                    if (!empty($po['airtable_id'])) {
                        $data['requests'][$request_code]['po_airtable_ids'][] = $po['airtable_id'];
                        $data['requests'][$request_code]['po_airtable_ids'] = array_values(array_unique($data['requests'][$request_code]['po_airtable_ids']));
                    }
                }
            }
        }

        return $data;
    }
}

if (!function_exists('cleg_procurement_get_data')) {
    function cleg_procurement_get_data() {
        $legacy_data = get_option('cleg_procurement_data_v1');
        $airtable_data = cleg_procurement_airtable_data();
        if (!is_wp_error($airtable_data) && is_array($airtable_data)) {
            if (is_array($legacy_data)) {
                $legacy_data = wp_parse_args($legacy_data, array(
                    'requests' => array(),
                    'quotes' => array(),
                    'pos' => array(),
                    'audit' => array(),
                    'provider_history' => array(),
                    'history_hidden' => array(),
                    'history_overrides' => array(),
                ));

                foreach ($legacy_data['quotes'] as $id => $quotes) {
                    if (!isset($airtable_data['quotes'][$id])) {
                        $airtable_data['quotes'][$id] = $quotes;
                    } elseif (is_array($quotes)) {
                        $airtable_data['quotes'][$id] = array_merge((array) $airtable_data['quotes'][$id], $quotes);
                    }
                }
                $airtable_data['quotes'] = cleg_procurement_dedupe_quotes_by_request($airtable_data['quotes']);

                if (!empty($legacy_data['pos']) && is_array($legacy_data['pos'])) {
                    $airtable_data['pos'] = array_merge((array) $legacy_data['pos'], (array) $airtable_data['pos']);
                }

                if (!empty($legacy_data['audit']) && is_array($legacy_data['audit'])) {
                    $airtable_data['audit'] = array_merge((array) $legacy_data['audit'], (array) $airtable_data['audit']);
                }

                if (!empty($legacy_data['provider_history']) && is_array($legacy_data['provider_history'])) {
                    $airtable_data['provider_history'] = $legacy_data['provider_history'];
                }

                if (!empty($legacy_data['history_hidden']) && is_array($legacy_data['history_hidden'])) {
                    $airtable_data['history_hidden'] = $legacy_data['history_hidden'];
                }

                if (!empty($legacy_data['history_overrides']) && is_array($legacy_data['history_overrides'])) {
                    $airtable_data['history_overrides'] = $legacy_data['history_overrides'];
                }
            }

            $airtable_data['requests'] = cleg_procurement_apply_request_overrides(cleg_procurement_dedupe_requests($airtable_data['requests']));
            $airtable_data['quotes'] = cleg_procurement_dedupe_quotes_by_request($airtable_data['quotes']);
            return $airtable_data;
        }

        $data = $legacy_data;

        if (!is_array($data) || empty($data['requests'])) {
            $data = cleg_procurement_default_data();
            update_option('cleg_procurement_data_v1', $data, false);
        }

        $data = wp_parse_args($data, array(
            'requests' => array(),
            'quotes' => array(),
            'pos' => array(),
            'next_request' => 1,
            'next_po' => 1,
            'audit' => array(),
            'source' => 'wordpress',
        ));

        $data['requests'] = cleg_procurement_apply_request_overrides(cleg_procurement_dedupe_requests($data['requests']));
        $data['quotes'] = cleg_procurement_dedupe_quotes_by_request($data['quotes']);
        return $data;
    }
}

if (!function_exists('cleg_procurement_request_overrides')) {
    function cleg_procurement_request_overrides() {
        $persistent = get_option('cleg_procurement_request_overrides_v1');
        $persistent = is_array($persistent) ? $persistent : array();
        $temporary = get_transient('cleg_procurement_request_overrides_v1');
        $temporary = is_array($temporary) ? $temporary : array();
        return array_merge($persistent, $temporary);
    }
}

if (!function_exists('cleg_procurement_set_request_override')) {
    function cleg_procurement_set_request_override($id, $fields) {
        $key = cleg_procurement_request_key(array('id' => $id), $id);
        if (!$key || !is_array($fields)) {
            return;
        }

        $overrides = cleg_procurement_request_overrides();
        $overrides[$key] = array_merge((array) ($overrides[$key] ?? array()), $fields);
        $overrides[$key]['updated_at'] = current_time('mysql');
        update_option('cleg_procurement_request_overrides_v1', $overrides, false);
        set_transient('cleg_procurement_request_overrides_v1', $overrides, 12 * HOUR_IN_SECONDS);
    }
}

if (!function_exists('cleg_procurement_apply_request_overrides')) {
    function cleg_procurement_apply_request_overrides($requests) {
        if (!is_array($requests)) {
            return array();
        }

        $overrides = cleg_procurement_request_overrides();

        foreach ($requests as $id => $request) {
            $key = cleg_procurement_request_key($request, $id);
            if ($key && isset($overrides[$key]) && is_array($overrides[$key])) {
                $requests[$id] = array_merge($request, $overrides[$key]);
            }
            if (is_array($requests[$id])) {
                $requests[$id]['status'] = cleg_procurement_normalize_status($requests[$id]['status'] ?? '', $requests[$id]['requester'] ?? '');
            }
        }

        return $requests;
    }
}

if (!function_exists('cleg_procurement_request_key')) {
    function cleg_procurement_request_key($request, $fallback = '') {
        if (!is_array($request)) {
            return sanitize_key((string) $fallback);
        }

        $id = trim((string) ($request['id'] ?? $fallback));
        if ($id === '') {
            $id = trim((string) ($request['airtable_id'] ?? $fallback));
        }

        return sanitize_key(strtoupper($id));
    }
}

if (!function_exists('cleg_procurement_request_timestamp')) {
    function cleg_procurement_request_timestamp($request) {
        if (!is_array($request)) {
            return 0;
        }

        $updated = strtotime((string) ($request['updated_at'] ?? ''));
        if ($updated) {
            return $updated;
        }

        $created = strtotime((string) ($request['created_at'] ?? ''));
        return $created ?: 0;
    }
}

if (!function_exists('cleg_procurement_pick_request_version')) {
    function cleg_procurement_pick_request_version($current, $candidate) {
        if (!is_array($current)) {
            return $candidate;
        }

        if (!is_array($candidate)) {
            return $current;
        }

        $current_cancelled = cleg_procurement_request_is_cancelled($current);
        $candidate_cancelled = cleg_procurement_request_is_cancelled($candidate);
        if ($candidate_cancelled && !$current_cancelled) {
            return $candidate;
        }
        if ($current_cancelled && !$candidate_cancelled) {
            return $current;
        }

        $current_has_airtable = !empty($current['airtable_id']);
        $candidate_has_airtable = !empty($candidate['airtable_id']);
        if ($candidate_has_airtable && !$current_has_airtable) {
            return $candidate;
        }
        if ($current_has_airtable && !$candidate_has_airtable) {
            return $current;
        }

        return cleg_procurement_request_timestamp($candidate) >= cleg_procurement_request_timestamp($current) ? $candidate : $current;
    }
}

if (!function_exists('cleg_procurement_dedupe_requests')) {
    function cleg_procurement_dedupe_requests($requests) {
        if (!is_array($requests)) {
            return array();
        }

        $deduped = array();
        $key_to_id = array();

        foreach ($requests as $id => $request) {
            if (!is_array($request)) {
                continue;
            }

            $request['id'] = trim((string) ($request['id'] ?? $id));
            if ($request['id'] === '') {
                $request['id'] = (string) $id;
            }

            $key = cleg_procurement_request_key($request, $id);
            if ($key === '') {
                $key = sanitize_key((string) $id);
            }

            if (isset($key_to_id[$key])) {
                $existing_id = $key_to_id[$key];
                $picked = cleg_procurement_pick_request_version($deduped[$existing_id], $request);
                if (($picked['id'] ?? '') !== $existing_id && !isset($deduped[$picked['id']])) {
                    unset($deduped[$existing_id]);
                    $existing_id = $picked['id'];
                    $key_to_id[$key] = $existing_id;
                }
                $deduped[$existing_id] = $picked;
                continue;
            }

            $key_to_id[$key] = $request['id'];
            $deduped[$request['id']] = $request;
        }

        return $deduped;
    }
}

if (!function_exists('cleg_procurement_save_data')) {
    function cleg_procurement_save_data($data) {
        if (isset($data['source']) && $data['source'] === 'airtable') {
            $overlay = get_option('cleg_procurement_data_v1');
            $overlay = is_array($overlay) ? $overlay : array();
            foreach (array('quotes', 'pos', 'audit', 'provider_history', 'history_hidden', 'history_overrides') as $key) {
                if (isset($data[$key]) && is_array($data[$key])) {
                    $overlay[$key] = $data[$key];
                }
            }
            $overlay['source'] = 'wordpress_overlay';
            update_option('cleg_procurement_data_v1', $overlay, false);
            return;
        }

        update_option('cleg_procurement_data_v1', $data, false);
    }
}

if (!function_exists('cleg_procurement_quote_fingerprint')) {
    function cleg_procurement_quote_fingerprint($quote) {
        $quote = is_array($quote) ? $quote : array();
        $parts = array(
            sanitize_text_field((string) ($quote['vendor'] ?? '')),
            sanitize_text_field((string) ($quote['contact'] ?? '')),
            sanitize_text_field((string) ($quote['amount'] ?? '')),
            sanitize_text_field((string) ($quote['eta'] ?? '')),
            sanitize_text_field((string) ($quote['estimated_delivery_to_pr'] ?? '')),
            sanitize_text_field((string) ($quote['expires'] ?? '')),
        );

        return md5(strtolower(implode('|', array_map('trim', $parts))));
    }
}

if (!function_exists('cleg_procurement_quotes_are_same')) {
    function cleg_procurement_quotes_are_same($left, $right) {
        $left = is_array($left) ? $left : array();
        $right = is_array($right) ? $right : array();
        $left_id = sanitize_text_field((string) ($left['airtable_id'] ?? ''));
        $right_id = sanitize_text_field((string) ($right['airtable_id'] ?? ''));

        if ($left_id !== '' && $right_id !== '') {
            return $left_id === $right_id;
        }

        return cleg_procurement_quote_fingerprint($left) === cleg_procurement_quote_fingerprint($right);
    }
}

if (!function_exists('cleg_procurement_dedupe_quote_list')) {
    function cleg_procurement_dedupe_quote_list($quotes) {
        $deduped = array();
        foreach ((array) $quotes as $quote) {
            if (!is_array($quote)) {
                continue;
            }

            $key = cleg_procurement_quote_fingerprint($quote);

            if (!isset($deduped[$key])) {
                $deduped[$key] = $quote;
                continue;
            }

            $current_has_airtable = !empty($deduped[$key]['airtable_id']);
            $candidate_has_airtable = !empty($quote['airtable_id']);
            $deduped[$key] = $candidate_has_airtable && !$current_has_airtable ? array_merge($deduped[$key], $quote) : array_merge($quote, $deduped[$key]);
        }

        return array_values($deduped);
    }
}

if (!function_exists('cleg_procurement_dedupe_quotes_by_request')) {
    function cleg_procurement_dedupe_quotes_by_request($quotes_by_request) {
        foreach ((array) $quotes_by_request as $request_id => $quotes) {
            $quotes_by_request[$request_id] = cleg_procurement_dedupe_quote_list($quotes);
        }

        return $quotes_by_request;
    }
}

if (!function_exists('cleg_procurement_quote_exists')) {
    function cleg_procurement_quote_exists($quotes, $quote) {
        foreach ((array) $quotes as $existing) {
            if (cleg_procurement_quotes_are_same($existing, $quote)) {
                return true;
            }
        }

        return false;
    }
}

if (!function_exists('cleg_procurement_redact_sensitive_value')) {
    function cleg_procurement_redact_sensitive_value($value) {
        if (is_array($value)) {
            $clean = array();
            foreach ($value as $key => $item) {
                $key_string = strtolower((string) $key);
                if (preg_match('/(token|secret|password|passwd|authorization|bearer|pat|api[_-]?key|key)/', $key_string)) {
                    $clean[$key] = '[redacted]';
                    continue;
                }
                $clean[$key] = cleg_procurement_redact_sensitive_value($item);
            }
            return $clean;
        }

        if (is_string($value)) {
            $value = preg_replace('/Bearer\s+[A-Za-z0-9._~+\-\/]+=*/i', 'Bearer [redacted]', $value);
            $value = preg_replace('/(key|token|secret|password|pat)=([^&\s]+)/i', '$1=[redacted]', $value);
            return sanitize_textarea_field($value);
        }

        return $value;
    }
}

if (!function_exists('cleg_procurement_operation_key')) {
    function cleg_procurement_operation_key($entity_type, $operation, $source, $stable_id, $payload = array()) {
        if (function_exists('cleg_procurement_idempotency_key')) {
            return cleg_procurement_idempotency_key($entity_type, $operation, $source, $stable_id, $payload);
        }

        $seed = array(
            'entity_type' => sanitize_key((string) $entity_type),
            'operation' => sanitize_key((string) $operation),
            'source' => sanitize_key((string) $source),
            'stable_id' => sanitize_text_field((string) $stable_id),
            'payload' => cleg_procurement_redact_sensitive_value($payload),
        );

        return hash('sha256', wp_json_encode($seed));
    }
}

if (!function_exists('cleg_procurement_operation_log')) {
    function cleg_procurement_operation_log() {
        $log = get_option('cleg_procurement_operation_log_v1', array());
        return is_array($log) ? $log : array();
    }
}

if (!function_exists('cleg_procurement_operation_record')) {
    function cleg_procurement_operation_record($key, $status, $meta = array()) {
        $key = sanitize_key((string) $key);
        if ($key === '') {
            return;
        }

        $log = cleg_procurement_operation_log();
        $log[$key] = array(
            'key' => $key,
            'status' => sanitize_key((string) $status),
            'recorded_at' => current_time('mysql'),
            'meta' => cleg_procurement_redact_sensitive_value(is_array($meta) ? $meta : array()),
        );

        update_option('cleg_procurement_operation_log_v1', array_slice($log, -500, null, true), false);
    }
}

if (!function_exists('cleg_procurement_operation_status')) {
    function cleg_procurement_operation_status($key) {
        $key = sanitize_key((string) $key);
        if ($key === '') {
            return '';
        }

        $log = cleg_procurement_operation_log();
        return isset($log[$key]['status']) ? sanitize_key((string) $log[$key]['status']) : '';
    }
}

if (!function_exists('cleg_procurement_operation_is_done')) {
    function cleg_procurement_operation_is_done($key) {
        return in_array(cleg_procurement_operation_status($key), array('applied', 'dismissed', 'completed'), true);
    }
}

if (!function_exists('cleg_procurement_error_message')) {
    function cleg_procurement_error_message($error) {
        if (is_wp_error($error)) {
            return $error->get_error_message();
        }

        if (is_scalar($error)) {
            return (string) $error;
        }

        return 'Error no especificado.';
    }
}

if (!function_exists('cleg_procurement_error_queue_add')) {
    function cleg_procurement_error_queue_add($context, $error, $payload = array(), $retryable = true) {
        $queue = get_option('cleg_procurement_error_queue_v1', array());
        $queue = is_array($queue) ? $queue : array();
        $context = sanitize_key((string) $context);
        $message = cleg_procurement_error_message($error);
        $payload = cleg_procurement_redact_sensitive_value(is_array($payload) ? $payload : array());

        $id = cleg_procurement_operation_key('procurement_error', $context, 'wordpress', $message, $payload);
        $queue[$id] = array(
            'id' => $id,
            'context' => $context,
            'message' => sanitize_textarea_field($message),
            'payload' => $payload,
            'retryable' => (bool) $retryable,
            'status' => 'open',
            'attempts' => isset($queue[$id]['attempts']) ? absint($queue[$id]['attempts']) + 1 : 1,
            'last_seen_at' => current_time('mysql'),
        );

        if (empty($queue[$id]['first_seen_at'])) {
            $queue[$id]['first_seen_at'] = current_time('mysql');
        }

        update_option('cleg_procurement_error_queue_v1', array_slice($queue, -200, null, true), false);
    }
}

if (!function_exists('cleg_procurement_error_queue_items')) {
    function cleg_procurement_error_queue_items($status = '', $limit = 20) {
        $queue = get_option('cleg_procurement_error_queue_v1', array());
        $queue = is_array($queue) ? $queue : array();
        $status = sanitize_key((string) $status);
        $limit = max(1, min(100, absint($limit)));

        uasort($queue, function ($a, $b) {
            $a_time = is_array($a) ? (strtotime((string) ($a['last_seen_at'] ?? $a['first_seen_at'] ?? '')) ?: 0) : 0;
            $b_time = is_array($b) ? (strtotime((string) ($b['last_seen_at'] ?? $b['first_seen_at'] ?? '')) ?: 0) : 0;
            return $b_time <=> $a_time;
        });

        $items = array();
        foreach ($queue as $id => $error) {
            if (!is_array($error)) {
                continue;
            }

            $error_status = sanitize_key((string) ($error['status'] ?? 'open'));
            if ($status !== '' && $error_status !== $status) {
                continue;
            }

            $error['id'] = sanitize_key((string) ($error['id'] ?? $id));
            $error['context'] = sanitize_key((string) ($error['context'] ?? 'unknown'));
            $error['message'] = sanitize_textarea_field((string) ($error['message'] ?? ''));
            $error['status'] = $error_status;
            $error['attempts'] = absint($error['attempts'] ?? 0);
            $error['retryable'] = !empty($error['retryable']);
            $error['first_seen_at'] = sanitize_text_field((string) ($error['first_seen_at'] ?? ''));
            $error['last_seen_at'] = sanitize_text_field((string) ($error['last_seen_at'] ?? ''));
            $error['payload'] = cleg_procurement_redact_sensitive_value(is_array($error['payload'] ?? null) ? $error['payload'] : array());
            $items[] = $error;

            if (count($items) >= $limit) {
                break;
            }
        }

        return $items;
    }
}

if (!function_exists('cleg_procurement_error_queue_action_url')) {
    function cleg_procurement_error_queue_action_url($error_id, $queue_action) {
        $error_id = sanitize_key((string) $error_id);
        $queue_action = sanitize_key((string) $queue_action);
        if ($error_id === '' || !in_array($queue_action, array('resolve', 'archive', 'reopen', 'retry'), true)) {
            return '';
        }

        $url = add_query_arg(array(
            'action' => 'cleg_procurement_error_queue_action',
            'queue_action' => $queue_action,
            'error_id' => $error_id,
        ), admin_url('admin-post.php'));

        return wp_nonce_url($url, 'cleg_procurement_error_queue_' . $queue_action . '_' . $error_id);
    }
}

if (!function_exists('cleg_procurement_error_queue_update_status')) {
    function cleg_procurement_error_queue_update_status($error_id, $queue_action, $note = '') {
        $error_id = sanitize_key((string) $error_id);
        $queue_action = sanitize_key((string) $queue_action);
        if ($error_id === '' || !in_array($queue_action, array('resolve', 'archive', 'reopen', 'retry'), true)) {
            return false;
        }

        $queue = get_option('cleg_procurement_error_queue_v1', array());
        $queue = is_array($queue) ? $queue : array();
        if (empty($queue[$error_id]) || !is_array($queue[$error_id])) {
            return false;
        }

        $user = wp_get_current_user();
        $user_label = $user && !empty($user->user_login) ? sanitize_text_field((string) $user->user_login) : 'system';
        $now = current_time('mysql');
        $note = sanitize_textarea_field((string) $note);

        if (empty($queue[$error_id]['resolution_log']) || !is_array($queue[$error_id]['resolution_log'])) {
            $queue[$error_id]['resolution_log'] = array();
        }

        $new_status = 'open';
        if ($queue_action === 'resolve') {
            $new_status = 'resolved';
            $queue[$error_id]['resolved_at'] = $now;
            $queue[$error_id]['resolved_by'] = $user_label;
        } elseif ($queue_action === 'archive') {
            $new_status = 'archived';
            $queue[$error_id]['archived_at'] = $now;
            $queue[$error_id]['archived_by'] = $user_label;
        } elseif ($queue_action === 'reopen') {
            $new_status = 'open';
            $queue[$error_id]['reopened_at'] = $now;
            $queue[$error_id]['reopened_by'] = $user_label;
        } elseif ($queue_action === 'retry') {
            $new_status = 'open';
            $queue[$error_id]['retry_requested_at'] = $now;
            $queue[$error_id]['retry_requested_by'] = $user_label;
            $queue[$error_id]['retry_requested'] = true;
        }

        $queue[$error_id]['status'] = $new_status;
        $queue[$error_id]['last_action'] = $queue_action;
        $queue[$error_id]['last_action_at'] = $now;
        $queue[$error_id]['last_action_by'] = $user_label;
        $queue[$error_id]['resolution_log'][] = array(
            'action' => $queue_action,
            'status' => $new_status,
            'at' => $now,
            'by' => $user_label,
            'note' => $note,
        );
        $queue[$error_id]['resolution_log'] = array_slice($queue[$error_id]['resolution_log'], -20);

        update_option('cleg_procurement_error_queue_v1', $queue, false);
        cleg_procurement_operation_record(
            cleg_procurement_operation_key('error_queue', $queue_action, 'wordpress', $error_id),
            $new_status,
            array(
                'error_id' => $error_id,
                'queue_action' => $queue_action,
                'user' => $user_label,
            )
        );

        delete_transient('cleg_procurement_healthcheck_status_last_update');
        return true;
    }
}

if (!function_exists('cleg_procurement_handle_error_queue_action')) {
    function cleg_procurement_handle_error_queue_action() {
        if (!cleg_procurement_private_sync_enabled() || !is_user_logged_in() || !cleg_procurement_user_can_manage(wp_get_current_user())) {
            wp_die(esc_html__('Acceso restringido.', 'cleg'));
        }

        $error_id = sanitize_key((string) ($_REQUEST['error_id'] ?? ''));
        $queue_action = sanitize_key((string) ($_REQUEST['queue_action'] ?? ''));
        if ($error_id === '' || !in_array($queue_action, array('resolve', 'archive', 'reopen', 'retry'), true)) {
            wp_safe_redirect(add_query_arg(array('proc_view' => 'ia', 'proc_notice' => 'error_queue_invalid'), home_url('/admin-procurement/')));
            exit;
        }

        check_admin_referer('cleg_procurement_error_queue_' . $queue_action . '_' . $error_id);

        $updated = cleg_procurement_error_queue_update_status($error_id, $queue_action, sanitize_textarea_field((string) wp_unslash($_REQUEST['note'] ?? '')));
        wp_safe_redirect(add_query_arg(array(
            'proc_view' => 'ia',
            'proc_notice' => $updated ? 'error_queue_updated' : 'error_queue_missing',
        ), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_procurement_error_queue_action', 'cleg_procurement_handle_error_queue_action');

if (!function_exists('cleg_procurement_error_queue_summary')) {
    function cleg_procurement_error_queue_summary() {
        $queue = get_option('cleg_procurement_error_queue_v1', array());
        $queue = is_array($queue) ? $queue : array();
        $summary = array(
            'total' => count($queue),
            'open' => 0,
            'retryable_open' => 0,
            'resolved' => 0,
            'archived' => 0,
            'by_context' => array(),
            'last_error' => null,
        );

        foreach ($queue as $error) {
            if (!is_array($error)) {
                continue;
            }

            $status = sanitize_key((string) ($error['status'] ?? 'open'));
            $context = sanitize_key((string) ($error['context'] ?? 'unknown'));
            $summary['by_context'][$context] = isset($summary['by_context'][$context]) ? $summary['by_context'][$context] + 1 : 1;

            if ($status === 'open') {
                $summary['open']++;
                if (!empty($error['retryable'])) {
                    $summary['retryable_open']++;
                }
            } elseif ($status === 'resolved') {
                $summary['resolved']++;
            } elseif ($status === 'archived') {
                $summary['archived']++;
            }

            $last_seen = strtotime((string) ($error['last_seen_at'] ?? '')) ?: 0;
            $current_last = is_array($summary['last_error']) ? (strtotime((string) ($summary['last_error']['last_seen_at'] ?? '')) ?: 0) : 0;
            if ($last_seen >= $current_last) {
                $summary['last_error'] = array(
                    'context' => $context,
                    'message' => sanitize_textarea_field((string) ($error['message'] ?? '')),
                    'attempts' => absint($error['attempts'] ?? 0),
                    'last_seen_at' => sanitize_text_field((string) ($error['last_seen_at'] ?? '')),
                    'retryable' => !empty($error['retryable']),
                );
            }
        }

        ksort($summary['by_context']);
        return $summary;
    }
}

if (!function_exists('cleg_procurement_operation_log_summary')) {
    function cleg_procurement_operation_log_summary() {
        $log = cleg_procurement_operation_log();
        $summary = array(
            'total' => count($log),
            'by_status' => array(),
            'last_operation' => null,
        );

        foreach ($log as $operation) {
            if (!is_array($operation)) {
                continue;
            }

            $status = sanitize_key((string) ($operation['status'] ?? 'unknown'));
            $summary['by_status'][$status] = isset($summary['by_status'][$status]) ? $summary['by_status'][$status] + 1 : 1;

            $recorded = strtotime((string) ($operation['recorded_at'] ?? '')) ?: 0;
            $current_last = is_array($summary['last_operation']) ? (strtotime((string) ($summary['last_operation']['recorded_at'] ?? '')) ?: 0) : 0;
            if ($recorded >= $current_last) {
                $summary['last_operation'] = array(
                    'key' => sanitize_key((string) ($operation['key'] ?? '')),
                    'status' => $status,
                    'recorded_at' => sanitize_text_field((string) ($operation['recorded_at'] ?? '')),
                    'meta' => cleg_procurement_redact_sensitive_value((array) ($operation['meta'] ?? array())),
                );
            }
        }

        ksort($summary['by_status']);
        return $summary;
    }
}

if (!function_exists('cleg_procurement_user_can_view_healthcheck')) {
