if (!function_exists('cleg_procurement_controlled_healthcheck')) {
    function cleg_procurement_controlled_healthcheck() {
        $data = cleg_procurement_get_data();
        $updates = cleg_procurement_all_pending_agent_updates();
        $pending_updates = 0;
        $closed_updates = 0;

        foreach ($updates as $update) {
            if (!is_array($update)) {
                continue;
            }

            $status = sanitize_key((string) ($update['status'] ?? 'pending'));
            if ($status === 'pending') {
                $pending_updates++;
            } else {
                $closed_updates++;
            }
        }

        $last_sharepoint_sync = get_option('cleg_procurement_last_sharepoint_sync', array());
        $last_sharepoint_sync = is_array($last_sharepoint_sync) ? cleg_procurement_redact_sensitive_value($last_sharepoint_sync) : array();

        $checks = array(
            'airtable_ready' => cleg_procurement_airtable_ready(),
            'sharepoint_graph_ready' => cleg_procurement_sharepoint_graph_ready(),
            'error_queue_open' => 0,
            'pending_updates' => $pending_updates,
        );

        $error_summary = cleg_procurement_error_queue_summary();
        $checks['error_queue_open'] = absint($error_summary['open'] ?? 0);

        return array(
            'module' => 'procurement_quotes',
            'version' => cleg_procurement_healthcheck_current_version(),
            'checked_at' => current_time('mysql'),
            'data_source' => sanitize_key((string) ($data['source'] ?? 'unknown')),
            'counts' => array(
                'requests' => isset($data['requests']) && is_array($data['requests']) ? count($data['requests']) : 0,
                'quotes_groups' => isset($data['quotes']) && is_array($data['quotes']) ? count($data['quotes']) : 0,
                'pos' => isset($data['pos']) && is_array($data['pos']) ? count($data['pos']) : 0,
                'audit' => isset($data['audit']) && is_array($data['audit']) ? count($data['audit']) : 0,
                'pending_updates' => $pending_updates,
                'closed_updates' => $closed_updates,
            ),
            'checks' => $checks,
            'operation_log' => cleg_procurement_operation_log_summary(),
            'error_queue' => $error_summary,
            'open_errors' => cleg_procurement_error_queue_items('open', 10),
            'last_sharepoint_sync' => $last_sharepoint_sync,
        );
    }
}

if (!function_exists('cleg_procurement_healthcheck_markdown')) {
    function cleg_procurement_healthcheck_markdown($health) {
        $lines = array(
            '# CLEG Compras Healthcheck',
            '',
            'Updated: ' . sanitize_text_field((string) ($health['checked_at'] ?? current_time('mysql'))),
            'Module version: ' . sanitize_text_field((string) ($health['version'] ?? 'unknown')),
            '',
            '## Summary',
            '- Data source: `' . sanitize_key((string) ($health['data_source'] ?? 'unknown')) . '`',
            '- Airtable ready: ' . (!empty($health['checks']['airtable_ready']) ? 'yes' : 'no'),
            '- SharePoint Graph ready: ' . (!empty($health['checks']['sharepoint_graph_ready']) ? 'yes' : 'no'),
            '- Pending updates: ' . absint($health['counts']['pending_updates'] ?? 0),
            '- Error queue open: ' . absint($health['error_queue']['open'] ?? 0),
            '- Retryable open errors: ' . absint($health['error_queue']['retryable_open'] ?? 0),
            '- Manual refresh: ' . esc_url_raw(wp_nonce_url(add_query_arg('action', 'cleg_procurement_refresh_healthcheck', admin_url('admin-post.php')), 'cleg_procurement_refresh_healthcheck')),
            '',
            '## Counts',
            '- Requests: ' . absint($health['counts']['requests'] ?? 0),
            '- Quote groups: ' . absint($health['counts']['quotes_groups'] ?? 0),
            '- POs: ' . absint($health['counts']['pos'] ?? 0),
            '- Audit entries: ' . absint($health['counts']['audit'] ?? 0),
            '- Closed updates: ' . absint($health['counts']['closed_updates'] ?? 0),
            '',
            '## Operation Log',
            '- Total operations: ' . absint($health['operation_log']['total'] ?? 0),
        );

        foreach ((array) ($health['operation_log']['by_status'] ?? array()) as $status => $count) {
            $lines[] = '- ' . sanitize_key((string) $status) . ': ' . absint($count);
        }

        $lines[] = '';
        $lines[] = '## Error Queue';
        $lines[] = '- Total errors: ' . absint($health['error_queue']['total'] ?? 0);
        $lines[] = '- Resolved errors: ' . absint($health['error_queue']['resolved'] ?? 0);
        $lines[] = '- Archived errors: ' . absint($health['error_queue']['archived'] ?? 0);
        foreach ((array) ($health['error_queue']['by_context'] ?? array()) as $context => $count) {
            $lines[] = '- ' . sanitize_key((string) $context) . ': ' . absint($count);
        }

        if (!empty($health['open_errors']) && is_array($health['open_errors'])) {
            $lines[] = '';
            $lines[] = '## Open Error Actions';
            foreach ($health['open_errors'] as $error) {
                if (!is_array($error) || empty($error['id'])) {
                    continue;
                }

                $error_id = sanitize_key((string) $error['id']);
                $lines[] = '';
                $lines[] = '### ' . sanitize_key((string) ($error['context'] ?? 'unknown'));
                $lines[] = '- ID: `' . $error_id . '`';
                $lines[] = '- Message: ' . sanitize_textarea_field((string) ($error['message'] ?? ''));
                $lines[] = '- Attempts: ' . absint($error['attempts'] ?? 0);
                $lines[] = '- Last seen: ' . sanitize_text_field((string) ($error['last_seen_at'] ?? ''));
                $lines[] = '- Resolve: ' . esc_url_raw(cleg_procurement_error_queue_action_url($error_id, 'resolve'));
                $lines[] = '- Retry request: ' . esc_url_raw(cleg_procurement_error_queue_action_url($error_id, 'retry'));
                $lines[] = '- Archive: ' . esc_url_raw(cleg_procurement_error_queue_action_url($error_id, 'archive'));
            }
        }

        if (!empty($health['error_queue']['last_error']) && is_array($health['error_queue']['last_error'])) {
            $last = $health['error_queue']['last_error'];
            $lines[] = '';
            $lines[] = '## Last Error';
            $lines[] = '- Context: `' . sanitize_key((string) ($last['context'] ?? '')) . '`';
            $lines[] = '- Message: ' . sanitize_textarea_field((string) ($last['message'] ?? ''));
            $lines[] = '- Attempts: ' . absint($last['attempts'] ?? 0);
            $lines[] = '- Last seen: ' . sanitize_text_field((string) ($last['last_seen_at'] ?? ''));
            $lines[] = '- Retryable: ' . (!empty($last['retryable']) ? 'yes' : 'no');
        }

        if (!empty($health['last_sharepoint_sync'])) {
            $lines[] = '';
            $lines[] = '## Last SharePoint Sync';
            foreach ((array) $health['last_sharepoint_sync'] as $key => $value) {
                if (is_scalar($value)) {
                    $lines[] = '- ' . sanitize_key((string) $key) . ': ' . sanitize_text_field((string) $value);
                }
            }
        }

        return implode("\n", $lines) . "\n";
    }
}

if (!function_exists('cleg_procurement_write_healthcheck_status_page')) {
    function cleg_procurement_write_healthcheck_status_page($force = false) {
        $last_update = (int) get_transient('cleg_procurement_healthcheck_status_last_update');
        $last_snapshot = get_option('cleg_procurement_healthcheck_last_snapshot_v1', array());
        $last_version = is_array($last_snapshot) ? sanitize_text_field((string) ($last_snapshot['version'] ?? '')) : '';
        if (!$force && $last_update && time() - $last_update < 300 && $last_version === cleg_procurement_healthcheck_current_version()) {
            return false;
        }

        $health = cleg_procurement_controlled_healthcheck();
        $content = cleg_procurement_healthcheck_markdown($health);
        $existing = get_page_by_path('cleg-procurement-healthcheck-status', OBJECT, 'page');
        $post_data = array(
            'post_title' => 'CLEG Compras Healthcheck Status',
            'post_name' => 'cleg-procurement-healthcheck-status',
            'post_content' => $content,
            'post_status' => 'private',
            'post_type' => 'page',
            'comment_status' => 'closed',
            'ping_status' => 'closed',
        );

        if ($existing && !empty($existing->ID)) {
            $post_data['ID'] = (int) $existing->ID;
            wp_update_post(wp_slash($post_data));
        } else {
            wp_insert_post(wp_slash($post_data));
        }

        set_transient('cleg_procurement_healthcheck_status_last_update', time(), 5 * MINUTE_IN_SECONDS);
        update_option('cleg_procurement_healthcheck_last_snapshot_v1', $health, false);
        return true;
    }
}

if (!function_exists('cleg_procurement_update_healthcheck_status_page')) {
    function cleg_procurement_update_healthcheck_status_page($force = false) {
        if (!is_user_logged_in() || !cleg_procurement_user_can_view_healthcheck(wp_get_current_user())) {
