if (!function_exists('cleg_procurement_next_request_number')) {
    function cleg_procurement_next_request_number($data) {
        $next = max(1, absint($data['next_request'] ?? 1));
        $year = gmdate('Y');
        $requests = isset($data['requests']) && is_array($data['requests']) ? $data['requests'] : array();

        foreach ($requests as $request) {
            $code = is_array($request) ? (string) ($request['id'] ?? '') : '';
            if ($code && preg_match('/(?:CLEG-)?REQ-' . preg_quote($year, '/') . '-(\d+)/i', $code, $matches)) {
                $next = max($next, absint($matches[1]) + 1);
            }
        }

        return $next;
    }
}

if (!function_exists('cleg_procurement_airtable_priority')) {
    function cleg_procurement_airtable_priority($priority) {
        $map = array(
            'Alta' => 'High',
            'Urgente' => 'Urgent',
            'Detiene trabajo hoy' => 'Stops work today',
        );

        return $map[$priority] ?? ($priority ?: 'Normal');
    }
}

if (!function_exists('cleg_procurement_airtable_delivery_location')) {
    function cleg_procurement_airtable_delivery_location($location) {
        $allowed = array('Puerto Rico', 'Job Site / Project', 'Office', 'Direct to client', 'Supplier pickup', 'Other / confirm');
        if (in_array($location, $allowed, true)) {
            return $location;
        }
        if ($location === 'Oficina') {
            return 'Office';
        }
        if ($location === 'Otro / por confirmar') {
            return 'Other / confirm';
        }

        return $location ? 'Job Site / Project' : 'Puerto Rico';
    }
}

if (!function_exists('cleg_procurement_airtable_project_status')) {
    function cleg_procurement_airtable_project_status($project) {
        if ($project === 'Project Pending') {
            return 'Project pending';
        }
        if ($project === 'Troubleshooting / Urgente') {
            return 'Troubleshooting temporary';
        }

        return $project ? 'Assigned' : 'Project pending';
    }
}

if (!function_exists('cleg_procurement_airtable_requester_role')) {
    function cleg_procurement_airtable_requester_role($requester) {
        $normalized = strtolower(remove_accents((string) $requester));
        if (strpos($normalized, 'luis') !== false) {
            return 'Luis';
        }
        if (strpos($normalized, 'alejandro') !== false) {
            return 'Alejandro';
        }

        return 'Vendor / Field';
    }
}

if (!function_exists('cleg_procurement_create_airtable_request')) {
    function cleg_procurement_create_airtable_request($request, $item_fields) {
        if (!cleg_procurement_airtable_ready()) {
