if (!function_exists('cleg_procurement_request_client_status_from_quote')) {
    function cleg_procurement_request_client_status_from_quote($quote) {
        $status = trim((string) ($quote['client_response_status'] ?? ''));
        if ($status === 'Aceptada') {
            return 'Aceptado por cliente';
        }
        if ($status === 'Rechazada') {
            return 'Rechazado por cliente';
        }
        if ($status === 'Sin respuesta') {
            return 'Sin respuesta / descartado';
        }
        if ($status === 'Necesita revision') {
            return 'Requiere revision';
        }
        if (!empty($quote['client_last_follow_up_date'])) {
            return 'Seguimiento pendiente';
        }
        if (!empty($quote['client_sent_at'])) {
            return 'Enviado al cliente';
        }

        return 'No enviado al cliente';
    }
}

