if (!function_exists('cleg_procurement_add_airtable_history')) {
    function cleg_procurement_add_airtable_history($request, $history) {
        if (!cleg_procurement_airtable_ready()) {
            return false;
        }

        $files = array();
        foreach ((array) ($history['files'] ?? array()) as $file) {
            if (is_array($file) && !empty($file['url'])) {
                $files[] = array('url' => esc_url_raw($file['url']));
            } elseif (is_string($file) && wp_http_validate_url($file)) {
                $files[] = array('url' => esc_url_raw($file));
            }
        }

        $fields = array(
            'Product / Equipment Name' => sanitize_text_field((string) ($history['item'] ?? ($request['item'] ?? 'Item pendiente'))),
            'Category' => sanitize_text_field((string) ($history['category'] ?? 'Other')),
            'Manufacturer / Brand' => sanitize_text_field((string) ($history['brand'] ?? $history['manufacturer'] ?? '')),
            'Model / Part Number' => sanitize_text_field((string) ($history['model'] ?? $history['part_number'] ?? $history['reference'] ?? '')),
            'Specs Summary' => sanitize_textarea_field((string) ($history['specs'] ?? $history['notes'] ?? '')),
            'Last Quoted Price' => sanitize_text_field((string) ($history['price'] ?? $history['amount'] ?? '')),
            'Last Quote Date' => cleg_procurement_airtable_date(!empty($history['quote_date']) ? $history['quote_date'] : current_time('Y-m-d')),
            'Last Vendor Snapshot' => sanitize_text_field((string) ($history['vendor'] ?? 'Proveedor pendiente')),
            'Typical Lead Time' => sanitize_text_field((string) ($history['lead_time'] ?? $history['eta'] ?? '')),
            'Usage Notes' => sanitize_textarea_field((string) ($history['notes'] ?? ('Fuente: ' . ($history['source_request'] ?? ($request['id'] ?? ''))))),
        );

        if (!empty($request['item_airtable_id'])) {
            $fields['Procurement Items'] = array($request['item_airtable_id']);
        }

        if ($files) {
            $fields['Documents / Datasheets'] = $files;
        }

        $response = cleg_admin_request('POST', CLEG_PROC_AIRTABLE_HISTORY_TABLE, array(
            'body' => array(
                'records' => array(array('fields' => $fields)),
                'typecast' => true,
            ),
        ));

        if (is_wp_error($response)) {
            return false;
        }

        return !empty($response['records'][0]['id']) ? sanitize_text_field($response['records'][0]['id']) : true;
    }
}

