if (!function_exists('cleg_procurement_update_airtable_history_row')) {
    function cleg_procurement_update_airtable_history_row($source, $record_id, $payload) {
        if (!cleg_procurement_airtable_ready() || $record_id === '') {
            return false;
        }

        $source = sanitize_key($source);
        $record_id = sanitize_text_field($record_id);
        $fields = array();
        $table = '';

        if ($source === 'airtable_history') {
            $table = CLEG_PROC_AIRTABLE_HISTORY_TABLE;
            $fields = array(
                'Product / Equipment Name' => $payload['item'],
                'Model / Part Number' => $payload['reference'],
                'Last Quoted Price' => $payload['price'],
                'Last Vendor Snapshot' => $payload['vendor'],
                'Typical Lead Time' => $payload['lead_time'],
                'Usage Notes' => $payload['notes'],
            );
            if ($payload['date'] !== '') {
                $fields['Last Quote Date'] = $payload['date'];
            }
        } elseif ($source === 'airtable_quote') {
            $table = CLEG_PROC_AIRTABLE_QUOTES_TABLE;
            $fields = array(
                'Vendor Name Snapshot' => $payload['vendor'],
                'Quoted Item / Scope' => $payload['item'],
                'Quote Amount' => $payload['price'],
                'Currency' => $payload['currency'],
                'Lead Time' => $payload['lead_time'],
                'Quote Code' => $payload['reference'],
                'Recommendation Reason' => $payload['notes'],
            );
            if ($payload['date'] !== '') {
                $fields['Expiration Date'] = $payload['date'];
            }
        } elseif ($source === 'airtable_vendor') {
            $table = CLEG_PROC_AIRTABLE_VENDORS_TABLE;
            $fields = array(
                'Vendor Name' => $payload['vendor'],
                'Brands / Lines' => $payload['item'],
                'Typical Lead Time' => $payload['lead_time'],
                'Notes' => $payload['notes'],
            );
            if ($payload['reference'] !== '') {
                if (wp_http_validate_url($payload['reference'])) {
                    $fields['Website'] = esc_url_raw($payload['reference']);
                } elseif (is_email($payload['reference'])) {
                    $fields['Email'] = sanitize_email($payload['reference']);
                } else {
                    $fields['Phone'] = sanitize_text_field($payload['reference']);
                }
            }
        }

        if ($table === '' || !$fields) {
            return false;
        }

        $response = cleg_admin_request('PATCH', $table, array(
            'body' => array(
                'records' => array(
                    array(
                        'id' => $record_id,
                        'fields' => $fields,
                    ),
                ),
                'typecast' => true,
            ),
        ));

        if (is_wp_error($response)) {
            return false;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        return $code >= 200 && $code < 300;
    }
}

if (!function_exists('cleg_procurement_add_airtable_followup')) {
    function cleg_procurement_add_airtable_followup($request, $update, $note = '') {
        if (empty($request['airtable_id']) || !cleg_procurement_airtable_ready()) {
            return false;
        }

        $payload = isset($update['payload']) && is_array($update['payload']) ? $update['payload'] : array();
        $type = sanitize_key((string) ($update['type'] ?? 'note'));
        $follow_type = in_array($type, array('tracking', 'eta', 'file'), true) ? 'Tracking follow up' : 'Vendor confirmation';
        if ($type === 'quote') {
            $follow_type = 'Quote clarification';
        }

        $attachments = cleg_procurement_airtable_attachments_from_payload($payload);
        $fields = array(
            'Follow Up Code' => 'FU-' . gmdate('Ymd-His') . '-' . substr(sanitize_key((string) ($request['id'] ?? 'REQ')), 0, 18),
            'Follow Up Type' => $follow_type,
            'Status' => 'Open',
            'Owner' => 'Alejandro',
            'Priority' => cleg_procurement_airtable_priority($request['priority'] ?? 'Normal'),
            'Subject' => sanitize_text_field((string) ($update['label'] ?? 'Actualizacion recibida')),
            'Notes' => sanitize_textarea_field($note ?: (string) ($update['value'] ?? '')),
            'Procurement Requests' => array($request['airtable_id']),
        );

        if ($type === 'eta') {
            $eta = cleg_procurement_airtable_date($payload['eta'] ?? $update['value'] ?? '');
            if ($eta) {
                $fields['Due Date'] = $eta;
            }
        }

        if ($attachments) {
            $fields['Attachments'] = $attachments;
        }

        $response = cleg_admin_request('POST', CLEG_PROC_AIRTABLE_FOLLOWUPS_TABLE, array(
            'body' => array(
                'records' => array(array('fields' => $fields)),
                'typecast' => true,
            ),
        ));

        if (is_wp_error($response)) {
            return false;
        }

        return !empty($response['records'][0]['id']) ? sanitize_text_field($response['records'][0]['id']) : true;
    }
}

if (!function_exists('cleg_procurement_recommended_quote')) {
    function cleg_procurement_recommended_quote($quotes) {
        if (!is_array($quotes)) {
            return array();
        }

        foreach ($quotes as $quote) {
            if (is_array($quote) && ($quote['recommended'] ?? 'no') === 'yes' && !cleg_procurement_quote_is_inactive($quote)) {
                return $quote;
            }
        }

        foreach ($quotes as $quote) {
            if (is_array($quote) && !cleg_procurement_quote_is_inactive($quote)) {
                return $quote;
            }
        }

        return array();
    }
}

if (!function_exists('cleg_procurement_quote_is_inactive')) {
    function cleg_procurement_quote_is_inactive($quote) {
        if (!is_array($quote)) {
            return true;
        }

        if (($quote['voided'] ?? '') === 'yes') {
            return true;
        }

        $client_status = strtolower(trim(remove_accents((string) ($quote['client_response_status'] ?? ''))));
        if (in_array($client_status, array('rechazada', 'sin respuesta'), true)) {
            return true;
        }

        $status = strtolower(trim(remove_accents((string) ($quote['quote_status'] ?? ''))));
        return in_array($status, array('cancelled', 'canceled', 'cancelada', 'cancelado', 'closed', 'cerrada', 'cerrado', 'rejected', 'rechazada', 'rechazado', 'voided', 'anulada', 'anulado'), true);
    }
}

if (!function_exists('cleg_procurement_add_airtable_po')) {
    function cleg_procurement_add_airtable_po($request, $po, $quote = array()) {
        if (empty($request['airtable_id']) || !cleg_procurement_airtable_ready()) {
            return false;
        }

        $eta = cleg_procurement_airtable_date($po['eta'] ?? '');
        $ordered_date = cleg_procurement_airtable_date($po['ordered_date'] ?? current_time('Y-m-d'));
        $amount = sanitize_text_field((string) ($po['amount'] ?? '0'));
        $quote_airtable_id = sanitize_text_field((string) ($quote['airtable_id'] ?? $po['quote_airtable_id'] ?? ''));

        $po_number = sanitize_text_field((string) ($po['id'] ?? ''));
        if ($po_number === '') {
            return false;
        }

        $fields = array(
            'PO Number' => $po_number,
            'PO Status' => !empty($po['tracking']) ? 'In Transit' : 'Ordered',
            'Vendor Name Snapshot' => sanitize_text_field((string) ($po['vendor'] ?? 'Proveedor pendiente')),
            'PO Date' => $ordered_date,
            'Ordered Date' => $ordered_date,
            'Subtotal' => $amount,
            'Total' => $amount,
            'Notes' => sanitize_textarea_field((string) ($po['notes'] ?? ('PO QuickBooks asignada desde solicitud ' . ($request['id'] ?? '')))),
            'Procurement Requests' => array($request['airtable_id']),
        );

        if ($eta) {
            $fields['Estimated Arrival'] = $eta;
        }

        if ($quote_airtable_id && preg_match('/^rec[a-zA-Z0-9]{14}$/', $quote_airtable_id)) {
            $fields['Procurement Quotes'] = array($quote_airtable_id);
        }

        $response = cleg_admin_request('POST', CLEG_PROC_AIRTABLE_POS_TABLE, array(
            'body' => array(
                'records' => array(array('fields' => $fields)),
                'typecast' => true,
            ),
        ));

        if (is_wp_error($response)) {
            return false;
        }

        $po_airtable_id = !empty($response['records'][0]['id']) ? sanitize_text_field($response['records'][0]['id']) : '';

        if ($po_airtable_id && !empty($quote_airtable_id) && preg_match('/^rec[a-zA-Z0-9]{14}$/', $quote_airtable_id)) {
            cleg_admin_request('PATCH', CLEG_PROC_AIRTABLE_QUOTES_TABLE, array(
                'body' => array(
                    'records' => array(
                        array(
                            'id' => $quote_airtable_id,
                            'fields' => array(
                                'Quote Status' => 'Selected',
                                'Purchase Orders' => array($po_airtable_id),
                            ),
                        ),
                    ),
                    'typecast' => true,
                ),
            ));
        }

        $request_status = !empty($po['tracking']) ? 'In Transit' : 'PO Created';
        $request_note = !empty($po['tracking']) ? 'Compra en camino: ' : 'PO creada: ';
        cleg_procurement_update_airtable_status($request, $request_status, $request_note . ($po['id'] ?? ''));
        return $po_airtable_id ?: true;
    }
}

