if (!function_exists('cleg_procurement_add_airtable_shipment')) {
    function cleg_procurement_add_airtable_shipment($request, $update, $note = '') {
        if (!cleg_procurement_airtable_ready()) {
            return false;
        }

        $payload = isset($update['payload']) && is_array($update['payload']) ? $update['payload'] : array();
        $type = sanitize_key((string) ($update['type'] ?? 'tracking'));
        $tracking_number = sanitize_text_field((string) ($payload['tracking_number'] ?? $payload['tracking'] ?? ($type === 'tracking' ? ($update['value'] ?? '') : '')));
        $eta = cleg_procurement_airtable_date($payload['eta'] ?? $payload['estimated_arrival'] ?? ($type === 'eta' ? ($update['value'] ?? '') : ''));
        $po_airtable_id = sanitize_text_field((string) ($payload['po_airtable_id'] ?? $payload['purchase_order_airtable_id'] ?? ''));
        $attachments = cleg_procurement_airtable_attachments_from_payload($payload);

        $status = $tracking_number ? 'In Transit' : 'Pending tracking';
        if (!empty($payload['shipment_status'])) {
            $candidate = sanitize_text_field((string) $payload['shipment_status']);
            if (in_array($candidate, array('Pending tracking', 'Label created', 'In Transit', 'Delayed', 'Out for delivery', 'Delivered partial', 'Delivered complete', 'Lost / Issue', 'Cancelled'), true)) {
                $status = $candidate;
            }
        }

        $fields = array(
            'Shipment Code' => 'SHIP-' . gmdate('Ymd-His') . '-' . substr(sanitize_key((string) ($request['id'] ?? 'REQ')), 0, 18),
            'Shipment Status' => $status,
            'Notes' => sanitize_textarea_field($note ?: (string) ($update['value'] ?? '')),
        );

        $scalar_map = array(
            'Carrier' => $payload['carrier'] ?? '',
            'Tracking Number' => $tracking_number,
            'Tracking URL' => $payload['tracking_url'] ?? $payload['url'] ?? '',
            'Ship From' => $payload['ship_from'] ?? '',
            'Ship To / Delivery Location' => $payload['ship_to'] ?? $payload['delivery_location'] ?? ($request['delivery_location'] ?? ''),
            'Delay Reason' => $payload['delay_reason'] ?? '',
            'Follow Up Owner' => $payload['follow_up_owner'] ?? 'Alejandro',
            'Last Follow Up Date' => $payload['last_follow_up_date'] ?? current_time('Y-m-d'),
            'Next Follow Up Date' => $payload['next_follow_up_date'] ?? '',
        );

        foreach ($scalar_map as $field => $value) {
            $value = is_scalar($value) ? trim((string) $value) : '';
            if ($value !== '') {
                $fields[$field] = in_array($field, array('Tracking URL'), true) ? esc_url_raw($value) : sanitize_text_field($value);
            }
        }

        if ($eta) {
            $fields['Estimated Arrival'] = $eta;
        }

        $actual_arrival = cleg_procurement_airtable_date($payload['actual_arrival'] ?? '');
        if ($actual_arrival) {
            $fields['Actual Arrival'] = $actual_arrival;
        }

        if ($attachments) {
            $fields['Shipping Documents'] = $attachments;
        }

        if ($po_airtable_id && preg_match('/^rec[a-zA-Z0-9]{14}$/', $po_airtable_id)) {
            $fields['Procurement POs'] = array($po_airtable_id);
        }

        $response = cleg_admin_request('POST', CLEG_PROC_AIRTABLE_SHIPMENTS_TABLE, array(
            'body' => array(
                'records' => array(array('fields' => $fields)),
                'typecast' => true,
            ),
        ));

        if (is_wp_error($response)) {
            return false;
        }

        if (!empty($po_airtable_id) && preg_match('/^rec[a-zA-Z0-9]{14}$/', $po_airtable_id)) {
            $po_fields = array('PO Status' => 'In Transit');
            if ($eta) {
                $po_fields['Estimated Arrival'] = $eta;
            }

            cleg_admin_request('PATCH', CLEG_PROC_AIRTABLE_POS_TABLE, array(
                'body' => array(
                    'records' => array(
                        array(
                            'id' => $po_airtable_id,
                            'fields' => $po_fields,
                        ),
                    ),
                    'typecast' => true,
                ),
            ));
        }

        return !empty($response['records'][0]['id']) ? sanitize_text_field($response['records'][0]['id']) : true;
    }
}

