if (!function_exists('cleg_procurement_request_stage')) {
    function cleg_procurement_request_stage($request) {
        if (cleg_procurement_request_is_cancelled($request)) {
            return 'cancelled';
        }

        $status = cleg_procurement_normalize_status((string) ($request['status'] ?? ''));
        if (in_array($status, array('PO Created', 'Ordered', 'In Transit', 'Partially Received'), true)) {
            return 'po';
        }

        if (in_array($status, array('Received', 'Closed'), true)) {
            return 'done';
        }

        return 'pre_po';
    }
}

if (!function_exists('cleg_procurement_stage_requests')) {
    function cleg_procurement_stage_requests($requests, $stage) {
        if (!is_array($requests)) {
            return array();
        }

        return array_filter($requests, function ($request) use ($stage) {
            $request_stage = cleg_procurement_request_stage($request);
            if ($stage === 'all') {
                return !in_array($request_stage, array('cancelled', 'done'), true);
            }

            return $request_stage === $stage;
        });
    }
}

if (!function_exists('cleg_procurement_stage_count')) {
    function cleg_procurement_stage_count($requests, $stage) {
        return count(cleg_procurement_stage_requests($requests, $stage));
    }
}

if (!function_exists('cleg_procurement_status_is_cancelled')) {
    function cleg_procurement_status_is_cancelled($status) {
        $normalized = strtolower(trim(remove_accents((string) $status)));
        return in_array($normalized, array('cancelled', 'canceled', 'cancelada', 'cancelado'), true);
    }
}

if (!function_exists('cleg_procurement_request_is_cancelled')) {
    function cleg_procurement_request_is_cancelled($request) {
        if (!is_array($request)) {
            return false;
        }

        if (cleg_procurement_status_is_cancelled($request['status'] ?? '')) {
            return true;
        }

        if (($request['voided'] ?? '') === 'yes') {
            return true;
        }

        return false;
    }
}

