if (!function_exists('cleg_procurement_related_pos')) {
    function cleg_procurement_related_pos($data, $request) {
        $request_id = (string) ($request['id'] ?? '');
        $pos = isset($data['pos']) && is_array($data['pos']) ? $data['pos'] : array();

        if ($request_id === '') {
            return array();
        }

        return array_values(array_filter($pos, function ($po) use ($request_id) {
            return is_array($po) && (string) ($po['request_id'] ?? '') === $request_id;
        }));
    }
}

if (!function_exists('cleg_procurement_primary_po')) {
    function cleg_procurement_primary_po($pos) {
        $primary = null;

        foreach ((array) $pos as $po) {
            if (!is_array($po)) {
                continue;
            }

            if ($primary === null) {
                $primary = $po;
                continue;
            }

            $current_time = strtotime((string) ($po['updated_at'] ?? $po['ordered_date'] ?? $po['created_at'] ?? '')) ?: 0;
            $primary_time = strtotime((string) ($primary['updated_at'] ?? $primary['ordered_date'] ?? $primary['created_at'] ?? '')) ?: 0;
            if ($current_time >= $primary_time) {
                $primary = $po;
            }
        }

        return is_array($primary) ? $primary : array();
    }
}

