if (!function_exists('cleg_procurement_default_board_columns')) {
    function cleg_procurement_default_board_columns() {
        return array('priority', 'requested', 'project', 'item', 'quantity', 'state', 'price', 'quotes', 'po', 'relevant_date', 'action');
    }
}

if (!function_exists('cleg_procurement_selected_board_columns')) {
    function cleg_procurement_selected_board_columns() {
        $options = cleg_procurement_board_column_options();
        $selected = array();
        $raw = wp_unslash($_GET['proc_cols'] ?? '');

        if (is_array($raw)) {
            $raw_columns = $raw;
        } elseif (is_string($raw) && trim($raw) !== '') {
            $raw_columns = explode(',', $raw);
        } else {
            $raw_columns = array();
        }

        if ($raw_columns) {
            foreach ($raw_columns as $column) {
                $column = sanitize_key($column);
                if (isset($options[$column])) {
                    $selected[] = $column;
                }
            }
        }

        $selected = array_values(array_unique($selected));
        return $selected ? $selected : cleg_procurement_default_board_columns();
    }
}

if (!function_exists('cleg_procurement_board_grid_template')) {
    function cleg_procurement_board_grid_template($columns) {
        $options = cleg_procurement_board_column_options();
        $widths = array();

        foreach ((array) $columns as $column) {
            if (isset($options[$column]['width'])) {
                $widths[] = $options[$column]['width'];
            }
        }

        return $widths ? implode(' ', $widths) : '1fr';
    }
}

if (!function_exists('cleg_procurement_best_quote')) {
    function cleg_procurement_best_quote($quotes) {
        $best = null;

        foreach ((array) $quotes as $quote) {
            if (cleg_procurement_quote_is_inactive($quote)) {
                continue;
            }

            if (($quote['recommended'] ?? '') === 'yes') {
                return $quote;
            }

            if ($best === null) {
                $best = $quote;
                continue;
            }

            $current_amount = is_numeric($quote['amount'] ?? null) ? (float) $quote['amount'] : PHP_FLOAT_MAX;
            $best_amount = is_numeric($best['amount'] ?? null) ? (float) $best['amount'] : PHP_FLOAT_MAX;
            if ($current_amount < $best_amount) {
                $best = $quote;
            }
        }

        return $best;
    }
}

if (!function_exists('cleg_procurement_relevant_date_summary')) {
    function cleg_procurement_relevant_date_summary($request, $data) {
        $request_id = (string) ($request['id'] ?? '');
        $related_pos = cleg_procurement_related_pos($data, $request);
        $primary_po = cleg_procurement_primary_po($related_pos);
        $quotes = isset($data['quotes'][$request_id]) && is_array($data['quotes'][$request_id]) ? cleg_procurement_active_quotes($data['quotes'][$request_id]) : array();
        $best_quote = cleg_procurement_best_quote($quotes);

        if ($primary_po && trim((string) ($primary_po['eta'] ?? '')) !== '') {
            return array('value' => cleg_procurement_format_board_date($primary_po['eta']), 'label' => 'Llegada estimada');
        }

        if ($primary_po && trim((string) ($primary_po['ordered_date'] ?? '')) !== '') {
            return array('value' => cleg_procurement_format_board_date($primary_po['ordered_date']), 'label' => 'Ordenado');
        }

        if ($best_quote && trim((string) ($best_quote['estimated_delivery_to_pr'] ?? '')) !== '') {
            return array('value' => cleg_procurement_format_board_date($best_quote['estimated_delivery_to_pr']), 'label' => 'Llegada cotizada');
        }

        if ($best_quote && trim((string) ($best_quote['eta'] ?? '')) !== '') {
            return array('value' => (string) $best_quote['eta'], 'label' => 'Entrega suplidor');
        }

        return array(
            'value' => cleg_procurement_format_board_date($request['required_delivery_date'] ?? ($request['due_date'] ?? '')),
            'label' => 'Entrega requerida',
        );
    }
}

if (!function_exists('cleg_procurement_request_commercial_summary')) {
    function cleg_procurement_request_commercial_summary($request, $data) {
        $request_id = (string) ($request['id'] ?? '');
        $quantity = trim((string) ($request['quantity'] ?? ''));
        $unit = trim((string) ($request['unit'] ?? ''));
        $quantity_label = trim(($quantity !== '' ? $quantity : '1') . ' ' . $unit);
        $related_pos = cleg_procurement_related_pos($data, $request);
        $quotes = isset($data['quotes'][$request_id]) && is_array($data['quotes'][$request_id]) ? $data['quotes'][$request_id] : array();
        $best_quote = cleg_procurement_best_quote($quotes);
        $primary_po = cleg_procurement_primary_po($related_pos);

        $po_ids = array();
        foreach ($related_pos as $po) {
            $po_id = trim((string) ($po['id'] ?? ''));
            if ($po_id !== '') {
                $po_ids[] = $po_id;
            }
        }
        $po_ids = array_values(array_unique($po_ids));

        $amount = '';
        $amount_source = 'Pendiente';
        $vendor = '';
        $eta = '';
        $eta_label = 'Llegada / ETA';
        $order_status = '';
        $tracking = '';

        if ($primary_po) {
            $amount = (string) ($primary_po['amount'] ?? '');
            $amount_source = 'PO';
            $vendor = (string) ($primary_po['vendor'] ?? '');
            $eta = (string) ($primary_po['eta'] ?? '');
            $order_status = (string) ($primary_po['status'] ?? 'Ordenada');
            $tracking = (string) ($primary_po['tracking'] ?? '');
        } elseif ($best_quote) {
            $amount = (string) ($best_quote['amount'] ?? '');
            $amount_source = 'Estimado';
            $vendor = (string) ($best_quote['vendor'] ?? '');
            $eta = (string) ($best_quote['estimated_delivery_to_pr'] ?? ($best_quote['eta'] ?? ''));
            $order_status = 'Cotizado';
        }

        if ($eta === '') {
            $eta = (string) ($request['required_delivery_date'] ?? ($request['due_date'] ?? ''));
            $eta_label = 'Entrega requerida';
        }

        $price_label = $amount !== '' && is_numeric($amount) ? cleg_procurement_money($amount) : ($amount !== '' ? $amount : 'Pendiente');
        $po_label = $po_ids ? implode(', ', array_slice($po_ids, 0, 2)) : 'Sin PO';
        if (count($po_ids) > 2) {
            $po_label .= ' +' . (count($po_ids) - 2);
        }

        return array(
            'quantity' => $quantity_label !== '' ? $quantity_label : '1',
            'price' => $price_label,
            'price_source' => $amount_source,
            'po' => $po_label,
            'po_count' => count($po_ids),
            'ordered_at' => !empty($primary_po['ordered_date']) ? (string) $primary_po['ordered_date'] : (!empty($primary_po['created_at']) ? (string) $primary_po['created_at'] : 'Pendiente'),
            'status' => $order_status ?: ((string) ($request['status'] ?? 'Pendiente')),
            'vendor' => $vendor !== '' ? $vendor : 'Proveedor pendiente',
            'eta' => $eta !== '' ? $eta : 'Pendiente',
            'eta_label' => $eta_label,
            'tracking' => $tracking !== '' ? $tracking : 'Pendiente',
        );
    }
}

if (!function_exists('cleg_procurement_request_last_activity_label')) {
    function cleg_procurement_request_last_activity_label($request, $data) {
        $request_id = (string) ($request['id'] ?? '');
        $dates = array_filter(array(
            (string) ($request['updated_at'] ?? ''),
            (string) ($request['created_at'] ?? ''),
        ));

        foreach (cleg_procurement_request_quotes($request, $data) as $quote) {
            if (!is_array($quote)) {
                continue;
            }
            $dates[] = (string) ($quote['updated_at'] ?? ($quote['created_at'] ?? ($quote['expires'] ?? '')));
        }

        foreach (cleg_procurement_related_pos($data, $request) as $po) {
            $dates[] = (string) ($po['updated_at'] ?? ($po['ordered_date'] ?? ($po['created_at'] ?? '')));
        }

        if (!empty($data['audit']) && is_array($data['audit'])) {
            foreach ($data['audit'] as $entry) {
                if (!is_array($entry) || (string) ($entry['request_id'] ?? '') !== $request_id) {
                    continue;
                }
                $dates[] = (string) ($entry['created_at'] ?? ($entry['date'] ?? ''));
            }
        }

        $latest_timestamp = 0;
        foreach ($dates as $date) {
            $timestamp = strtotime((string) $date);
            if ($timestamp && $timestamp > $latest_timestamp) {
                $latest_timestamp = $timestamp;
            }
        }

        return $latest_timestamp ? date_i18n('M j', $latest_timestamp) : 'Sin actividad';
    }
}

if (!function_exists('cleg_procurement_active_quotes')) {
    function cleg_procurement_active_quotes($quotes) {
        return array_values(array_filter((array) $quotes, function ($quote) {
            return !cleg_procurement_quote_is_inactive($quote);
        }));
    }
}

if (!function_exists('cleg_procurement_request_quotes')) {
    function cleg_procurement_request_quotes($request, $data) {
        $request_id = (string) ($request['id'] ?? '');
        return isset($data['quotes'][$request_id]) && is_array($data['quotes'][$request_id]) ? cleg_procurement_dedupe_quote_list($data['quotes'][$request_id]) : array();
    }
}

if (!function_exists('cleg_procurement_numeric_amount')) {
    function cleg_procurement_numeric_amount($amount) {
        return is_numeric($amount) ? (float) $amount : null;
    }
}

if (!function_exists('cleg_procurement_request_decision_context')) {
    function cleg_procurement_request_decision_context($request, $data) {
        $quotes = cleg_procurement_request_quotes($request, $data);
        $active_quotes = cleg_procurement_active_quotes($quotes);
        $quote_count = count($active_quotes);
        $related_pos = cleg_procurement_related_pos($data, $request);
        $primary_po = cleg_procurement_primary_po($related_pos);
        $summary = cleg_procurement_request_commercial_summary($request, $data);
        $request_status = cleg_procurement_normalize_status($request['status'] ?? '');
        $client_quote = array();
        foreach ((array) $quotes as $quote) {
            if (!is_array($quote)) {
                continue;
            }
            if (!empty($quote['client_response_status']) || !empty($quote['client_sent_at'])) {
                $client_quote = $quote;
                if (($quote['recommended'] ?? '') === 'yes') {
                    break;
                }
            }
        }
        if (!$client_quote) {
            $client_quote = cleg_procurement_recommended_quote($active_quotes);
        }
        if (!$client_quote && $active_quotes) {
            $client_quote = reset($active_quotes);
        }
        $client_context = $client_quote ? cleg_procurement_client_quote_context($client_quote) : array();
        $state = 'needs_quotes';
        $label = 'Conseguir cotizaciones';
        $tone = 'warn';
        $action = 'Registrar cotizacion que llegue';

        if (cleg_procurement_request_is_cancelled($request)) {
            $state = 'closed';
            $label = 'Cancelada';
            $tone = 'muted';
            $action = 'Consultar historial';
        } elseif (in_array($request_status, array('Received', 'Closed'), true)) {
            $state = 'received';
            $label = 'Recibido / cerrado';
            $tone = 'ok';
            $action = 'Revisar recepcion';
        } elseif (in_array($request_status, array('In Transit', 'Ordered', 'PO Created', 'Partially Received'), true)) {
            $state = 'ordered_eta';
            $label = $request_status === 'PO Created' ? 'PO creada' : ($request_status === 'Partially Received' ? 'Recibido parcial' : 'En camino');
            $tone = 'ok';
            $action = 'Actualizar recepcion';
        } elseif ($primary_po) {
            $po_status = strtolower((string) ($primary_po['status'] ?? ''));
            $eta = trim((string) ($primary_po['eta'] ?? ''));
            if (preg_match('/received|closed|delivered complete|recibido|cerrad/', $po_status)) {
                $state = 'received';
                $label = 'Recibido / cerrado';
                $tone = 'ok';
                $action = 'Revisar recepcion';
            } elseif (preg_match('/transit|tracking|out for delivery|ordered|po created|pending tracking|label created/', $po_status)) {
                $state = 'ordered_eta';
                $label = 'En camino';
                $tone = 'ok';
                $action = 'Actualizar recepcion';
            } elseif ($eta !== '') {
                $state = 'ordered_eta';
                $label = 'Ordenado con llegada';
                $tone = 'ok';
                $action = 'Actualizar tracking o recepcion';
            } else {
                $state = 'ordered_no_eta';
                $label = 'Ordenado sin llegada';
                $tone = 'warn';
                $action = 'Pedir ETA / tracking';
            }
        } elseif (!empty($client_quote['client_response_status']) || !empty($client_quote['client_sent_at'])) {
            $client_status = (string) ($client_quote['client_response_status'] ?? '');
            if ($client_status === 'Aceptada') {
                $state = 'client_accepted';
                $label = 'Aceptado por cliente';
                $tone = 'ok';
                $action = 'Listo para comprar';
            } elseif (in_array($client_status, array('Rechazada', 'Sin respuesta'), true)) {
                $state = 'client_closed';
                $label = $client_status === 'Rechazada' ? 'Rechazado por cliente' : 'Descartado sin respuesta';
                $tone = 'muted';
                $action = 'Archivar / revisar historial';
            } elseif (($client_context['tone'] ?? '') === 'danger') {
                $state = 'client_follow_up_due';
                $label = 'Seguimiento cliente vencido';
                $tone = 'warn';
                $action = 'Contactar cliente ahora';
            } else {
                $state = 'client_pending';
                $label = 'Enviado al cliente';
                $tone = 'action';
                $action = $client_context['alert'] ?? 'Esperar respuesta cliente';
            }
        } elseif ($quote_count >= 2) {
            $state = 'compare';
            $label = 'Comparar y decidir';
            $tone = 'action';
            $action = 'Escoger proveedor / crear PO';
        } elseif ($quote_count === 1) {
            $state = 'review_quote';
            $label = 'Revisar cotizacion';
            $tone = 'action';
            $action = 'Comparar o crear PO';
        }

        return array(
            'state' => $state,
            'label' => $label,
            'tone' => $tone,
            'action' => $action,
            'quote_count' => $quote_count,
            'quotes' => $quotes,
            'active_quotes' => $active_quotes,
            'summary' => $summary,
            'primary_po' => $primary_po,
        );
    }
}

if (!function_exists('cleg_procurement_board_decision_counts')) {
    function cleg_procurement_board_decision_counts($requests, $data) {
        $counts = array(
            'open' => 0,
            'needs_quotes' => 0,
            'compare' => 0,
            'ordered_no_eta' => 0,
            'ordered_eta' => 0,
            'overdue' => 0,
            'estimated_pending' => 0,
        );
        $today = current_time('Y-m-d');

        foreach ((array) $requests as $request) {
            $context = cleg_procurement_request_decision_context($request, $data);
            $counts['open']++;
            if (isset($counts[$context['state']])) {
                $counts[$context['state']]++;
            } elseif (($context['state'] ?? '') === 'review_quote') {
                $counts['compare']++;
            }

            $required = cleg_procurement_airtable_date($request['required_delivery_date'] ?? ($request['due_date'] ?? ''));
            if ($required && $required < $today && !in_array($context['state'], array('received', 'closed'), true)) {
                $counts['overdue']++;
            }

            $best_quote = cleg_procurement_best_quote($context['active_quotes'] ?? array());
            if (!$context['primary_po'] && $best_quote && is_numeric($best_quote['amount'] ?? null)) {
                $counts['estimated_pending'] += (float) $best_quote['amount'];
            }
        }

        return $counts;
    }
}

if (!function_exists('cleg_procurement_render_decision_snapshot')) {
    function cleg_procurement_render_decision_snapshot($requests, $data) {
        $counts = cleg_procurement_board_decision_counts($requests, $data);
        ob_start();
        ?>
        <div class="cleg-proc-decision-snapshot" aria-label="Resumen de decisiones">
            <div><strong><?php echo esc_html((string) $counts['open']); ?></strong><span>Abiertas</span></div>
            <div><strong><?php echo esc_html((string) $counts['needs_quotes']); ?></strong><span>Sin cotizacion</span></div>
            <div><strong><?php echo esc_html((string) $counts['compare']); ?></strong><span>Por decidir</span></div>
            <div><strong><?php echo esc_html((string) ($counts['ordered_no_eta'] + $counts['ordered_eta'])); ?></strong><span>En camino</span></div>
            <div><strong><?php echo esc_html((string) $counts['overdue']); ?></strong><span>Atrasadas</span></div>
            <div><strong><?php echo esc_html(cleg_procurement_money($counts['estimated_pending'])); ?></strong><span>Estimado pendiente</span></div>
        </div>
        <?php
        return ob_get_clean();
    }
}

