        }

        $active_quotes = cleg_procurement_active_quotes($quotes);
        $best_quote = cleg_procurement_best_quote($active_quotes);
        $best_fingerprint = $best_quote ? cleg_procurement_quote_fingerprint($best_quote) : '';

        ob_start();
        ?>
        <?php if ($active_quotes) : ?>
            <div class="cleg-proc-quote-matrix-head" aria-hidden="true">
                <span>Suplidor</span><span>Total</span><span>Entrega</span><span>Validez</span><span>Riesgo</span><span>Evidencia</span><span>Accion</span>
            </div>
            <div class="cleg-proc-quote-cards cleg-proc-quote-matrix" aria-label="Comparacion de cotizaciones">
                <?php foreach ($quotes as $quote_index => $quote) : ?>
                    <?php
