if (!function_exists('cleg_procurement_user_can_internal_ai')) {
    function cleg_procurement_user_can_internal_ai($user = null) {
        if (!cleg_procurement_private_sync_enabled()) {
            return false;
        }

        $user = $user ?: wp_get_current_user();
        if (!$user || empty($user->ID)) {
            return false;
        }

        if (function_exists('cleg_command_center_is_admin_user') && cleg_command_center_is_admin_user($user)) {
            return true;
        }

        return current_user_can('manage_options');
    }
}

if (!function_exists('cleg_procurement_ai_score')) {
    function cleg_procurement_ai_score($request) {
        $score = 0;
        if (empty($request['conditions'])) {
            $score += 4;
        }
        if (in_array(($request['technical_risk'] ?? ''), array('High', 'Unknown'), true)) {
            $score += 3;
        }
        if (in_array(($request['information_level'] ?? ''), array('Missing critical data', 'Field note only', ''), true)) {
            $score += 3;
        }
        if (empty($request['rfq_draft'])) {
            $score += 2;
        }
        if (in_array(($request['status'] ?? ''), array('Researching', 'Needs Luis Approval', 'Submitted by Vendor'), true)) {
            $score += 1;
        }

        return $score;
    }
}

if (!function_exists('cleg_procurement_ai_requests')) {
    function cleg_procurement_ai_requests($requests) {
        $queue = array_filter($requests, function ($request) {
            if (cleg_procurement_request_is_cancelled($request)) {
                return false;
            }

            $status = cleg_procurement_normalize_status($request['status'] ?? '', $request['requester'] ?? '');

            return !in_array($status, array('Received', 'Closed'), true);
        });

        uasort($queue, function ($a, $b) {
            $score_diff = cleg_procurement_ai_score($b) <=> cleg_procurement_ai_score($a);
            if ($score_diff !== 0) {
                return $score_diff;
            }

            return cleg_procurement_priority_weight($a['priority'] ?? 'Normal') <=> cleg_procurement_priority_weight($b['priority'] ?? 'Normal');
        });

        return $queue;
    }
}

if (!function_exists('cleg_procurement_ai_recommendation')) {
    function cleg_procurement_ai_recommendation($request) {
        if (empty($request['conditions'])) {
            return 'Pedir uso tecnico, specs, foto o modelo antes de enviar RFQ.';
        }

        if (($request['substitute'] ?? 'Si') === 'No') {
            return 'Preparar RFQ como reemplazo exacto y confirmar part number con proveedor.';
        }

        if (in_array(($request['technical_risk'] ?? ''), array('High', 'Unknown'), true)) {
            return 'Revisar compatibilidad tecnica antes de recomendar compra.';
        }

        if (empty($request['rfq_draft'])) {
            return 'Generar borrador RFQ con precio, disponibilidad, lead time y entrega a Puerto Rico.';
        }

        return $request['item_next_action'] ?? ($request['next_action'] ?? 'Lista para revisar y enviar RFQ.');
    }
}

if (!function_exists('cleg_procurement_purchase_intent_from_substitute')) {
    function cleg_procurement_purchase_intent_from_substitute($substitute) {
        return $substitute === 'No' ? 'Exact replacement only' : 'Quote equivalent accepted';
    }
}

if (!function_exists('cleg_procurement_priority_weight')) {
    function cleg_procurement_priority_weight($priority) {
        $weights = array(
            'Detiene trabajo hoy' => 1,
            'Urgente' => 2,
            'Alta' => 3,
            'Normal' => 4,
        );

        return $weights[$priority] ?? 5;
    }
}

if (!function_exists('cleg_procurement_sort_requests')) {
    function cleg_procurement_sort_requests($requests) {
        uasort($requests, function ($a, $b) {
            $priority_a = cleg_procurement_priority_weight($a['priority'] ?? 'Normal');
            $priority_b = cleg_procurement_priority_weight($b['priority'] ?? 'Normal');
            if ($priority_a !== $priority_b) {
                return $priority_a <=> $priority_b;
            }

            $delivery_a = $a['required_delivery_date'] ?? ($a['due_date'] ?? '');
            $delivery_b = $b['required_delivery_date'] ?? ($b['due_date'] ?? '');
            $delivery_a = $delivery_a ?: '9999-12-31';
            $delivery_b = $delivery_b ?: '9999-12-31';
            if ($delivery_a !== $delivery_b) {
                return strcmp($delivery_a, $delivery_b);
            }

            return strcmp($a['created_at'] ?? '', $b['created_at'] ?? '');
        });

        return $requests;
    }
}

if (!function_exists('cleg_procurement_request_matches_order_filter')) {
    function cleg_procurement_request_matches_order_filter($request, $filter, $data = array()) {
        $filter = sanitize_key((string) $filter);
        if ($filter === '') {
            return true;
        }

        $related_pos = cleg_procurement_related_pos($data, $request);
        $primary_po = cleg_procurement_primary_po($related_pos);
        $status = strtolower((string) ($primary_po['status'] ?? ($request['status'] ?? '')));
        $eta = trim((string) ($primary_po['eta'] ?? ''));
        $tracking = trim((string) ($primary_po['tracking'] ?? ''));
        $context = cleg_procurement_request_decision_context($request, $data);

        if ($filter === 'needs_quote') {
            return ($context['state'] ?? '') === 'needs_quotes';
        }

        if ($filter === 'quoting') {
            return in_array(($context['state'] ?? ''), array('review_quote', 'compare'), true) && empty($primary_po);
        }

        if ($filter === 'ready_decision') {
            $recommended = cleg_procurement_best_quote($context['active_quotes'] ?? array());
            return (($context['state'] ?? '') === 'compare' || (($recommended['recommended'] ?? '') === 'yes')) && empty($primary_po);
        }

        if ($filter === 'ordered') {
            return !empty($primary_po) || in_array($request['status'] ?? '', array('PO Created', 'Ordered'), true);
        }

        if ($filter === 'in_transit') {
            return strpos($status, 'transit') !== false || strpos($status, 'delivery') !== false || $tracking !== '';
        }

        if ($filter === 'with_eta') {
            return $eta !== '';
        }

        if ($filter === 'without_eta') {
            return (!empty($primary_po) || in_array(cleg_procurement_normalize_status($request['status'] ?? ''), array('PO Created', 'Ordered', 'In Transit'), true)) && $eta === '';
        }

        if ($filter === 'received') {
            return strpos($status, 'received') !== false || strpos($status, 'delivered complete') !== false || strpos($status, 'closed') !== false;
        }

        if ($filter === 'problem') {
            $risk = strtolower((string) ($request['technical_risk'] ?? ''));
            $missing = trim((string) ($request['item_missing_information'] ?? ''));
            return in_array($risk, array('high', 'unknown'), true) || $missing !== '' || ($context['tone'] ?? '') === 'warn';
        }

        return true;
    }
}

if (!function_exists('cleg_procurement_filter_requests')) {
    function cleg_procurement_filter_requests($requests, $filters, $data = array()) {
        $query = strtolower(trim((string) ($filters['q'] ?? '')));
        $priority = (string) ($filters['priority'] ?? '');
        $status = (string) ($filters['status'] ?? '');
        $order_state = sanitize_key((string) ($filters['order_state'] ?? ''));

        return array_filter($requests, function ($request) use ($query, $priority, $status, $order_state, $data) {
            if ($priority && ($request['priority'] ?? '') !== $priority) {
                return false;
            }

            if ($status && ($request['status'] ?? '') !== $status) {
                return false;
            }

            if (!cleg_procurement_request_matches_order_filter($request, $order_state, $data)) {
                return false;
            }

            if (!$query) {
                return true;
            }

            $quote_terms = array();
            foreach (cleg_procurement_request_quotes($request, $data) as $quote) {
                if (!is_array($quote)) {
                    continue;
                }
                $quote_terms[] = $quote['vendor'] ?? '';
                $quote_terms[] = $quote['contact'] ?? '';
            }

            $po_terms = array();
            foreach (cleg_procurement_related_pos($data, $request) as $po) {
                if (!is_array($po)) {
                    continue;
                }
                $po_terms[] = $po['id'] ?? '';
                $po_terms[] = $po['vendor'] ?? '';
                $po_terms[] = $po['tracking'] ?? '';
            }

            $haystack = strtolower(implode(' ', array_merge(array(
                $request['id'] ?? '',
                $request['item'] ?? '',
                $request['project'] ?? '',
                $request['preferred_brand_model'] ?? '',
                $request['requester'] ?? '',
                $request['priority'] ?? '',
                $request['status'] ?? '',
                $request['delivery_location'] ?? '',
                $request['conditions'] ?? '',
            ), $quote_terms, $po_terms)));

            return strpos($haystack, $query) !== false;
        });
    }
}

if (!function_exists('cleg_procurement_select_options')) {
    function cleg_procurement_select_options($options, $selected) {
        $selected = (string) $selected;
        $html = '';
        if ($selected !== '' && !in_array($selected, $options, true)) {
            $html .= '<option value="' . esc_attr($selected) . '" selected>' . esc_html($selected) . '</option>';
        }

        foreach ($options as $option) {
            $html .= '<option value="' . esc_attr($option) . '"' . selected($selected, $option, false) . '>' . esc_html($option) . '</option>';
        }

        return $html;
    }
}

if (!function_exists('cleg_procurement_handle_create_request')) {
    function cleg_procurement_handle_create_request() {
        cleg_procurement_guard();
        check_admin_referer('cleg_procurement_create_request');

        $data = cleg_procurement_get_data();
        $next = cleg_procurement_next_request_number($data);
        $id = 'CLEG-REQ-' . gmdate('Y') . '-' . str_pad((string) $next, 4, '0', STR_PAD_LEFT);
        $user = wp_get_current_user();
        $requester = sanitize_text_field(wp_unslash($_POST['requester'] ?? ''));
        $is_luis = strtolower($requester) === 'luis coll';
        $quote_due_date = cleg_procurement_airtable_date(wp_unslash($_POST['quote_due_date'] ?? ''));
        $required_delivery_date = cleg_procurement_airtable_date(wp_unslash($_POST['required_delivery_date'] ?? ''));
        $conditions = sanitize_textarea_field(wp_unslash($_POST['conditions'] ?? ''));
        $reference = esc_url_raw(wp_unslash($_POST['reference'] ?? ''));
        $reference_images = cleg_procurement_collect_reference_uploads('reference_images');
        $delivery_location = sanitize_text_field(wp_unslash($_POST['delivery_location'] ?? 'Puerto Rico'));
        $urgency_reason = sanitize_text_field(wp_unslash($_POST['urgency_reason'] ?? 'Cotizacion requerida pronto'));
        $urgency_notes = sanitize_textarea_field(wp_unslash($_POST['urgency_notes'] ?? ''));
        $item_name = sanitize_text_field(wp_unslash($_POST['item'] ?? ''));
        $quantity = max(1, absint($_POST['quantity'] ?? 1));
        $unit = sanitize_text_field(wp_unslash($_POST['unit'] ?? 'Unidad'));
        $substitute = sanitize_text_field(wp_unslash($_POST['substitute'] ?? 'Pendiente'));
        $purchase_intent = cleg_procurement_purchase_intent_from_substitute($substitute);

        $data['requests'][$id] = array(
            'id' => $id,
            'item' => $item_name,
            'project' => sanitize_text_field(wp_unslash($_POST['project'] ?? 'Project Pending')),
            'requester' => $requester ?: ($user && $user->ID ? $user->display_name : 'Usuario'),
            'requester_user_id' => $user && $user->ID ? (int) $user->ID : 0,
            'requester_login' => $user && $user->ID ? sanitize_user($user->user_login, true) : '',
            'requester_email' => $user && $user->ID ? sanitize_email($user->user_email) : '',
            'quantity' => $quantity,
            'unit' => $unit,
            'quote_due_date' => $quote_due_date,
            'required_delivery_date' => $required_delivery_date,
            'due_date' => $required_delivery_date ?: $quote_due_date,
            'delivery_location' => $delivery_location,
            'priority' => sanitize_text_field(wp_unslash($_POST['priority'] ?? 'Normal')),
            'substitute' => $substitute,
            'conditions' => $conditions,
            'reference' => $reference,
            'reference_images' => $reference_images,
            'purchase_intent' => $purchase_intent,
            'urgency_reason' => $urgency_reason,
            'urgency_notes' => $urgency_notes,
            'status' => $is_luis ? 'Researching' : 'Submitted by Vendor',
            'created_by' => $user && $user->ID ? $user->display_name : 'Usuario',
            'created_at' => current_time('mysql'),
            'updated_at' => current_time('mysql'),
        );

        $item_fields = array(
            'Item Code' => $id . '-ITEM-01',
            'Item Description' => $item_name,
            'Category' => sanitize_text_field(wp_unslash($_POST['intake_category'] ?? 'Other')),
            'Quantity' => $quantity,
            'Unit' => $unit,
            'Preferred Brand / Model' => sanitize_text_field(wp_unslash($_POST['preferred_brand_model'] ?? '')),
            'Substitute Accepted' => $substitute,
            'Required Date' => $required_delivery_date ?: $quote_due_date,
            'Technical Specs' => $conditions,
            'Special Conditions' => $urgency_notes,
            'Item Status' => 'Needs classification',
            'Intake Category' => sanitize_text_field(wp_unslash($_POST['intake_category'] ?? 'Industrial component')),
            'Information Level' => $conditions ? 'Usable for RFQ' : 'Missing critical data',
            'Purchase Intent' => $purchase_intent,
            'Item Missing Information' => $conditions ? '' : 'Faltan uso tecnico, specs, foto, modelo o condiciones de aplicacion.',
            'Technical Risk' => $conditions ? 'Medium' : 'High',
            'RFQ Ready' => (bool) $conditions,
            'RFQ Template Type' => 'General technical RFQ',
            'RFQ Draft' => 'Please quote the following item for Vantrexor: ' . $item_name . '. Include price, availability, lead time, estimated delivery to Puerto Rico, warranty/conditions, and ' . ($substitute === 'No' ? 'confirm exact replacement only.' : 'confirm if an equivalent is being offered.'),
            'Item Next Action' => $conditions ? 'Enviar RFQ a suplidores y comparar alternativas.' : 'Pedir datos tecnicos minimos antes de enviar RFQ.',
        );

        $airtable_attachments = cleg_procurement_airtable_attachments($reference_images);
        if ($airtable_attachments) {
            $item_fields['Attachments'] = $airtable_attachments;
        }

        $airtable_saved = cleg_procurement_create_airtable_request($data['requests'][$id], $item_fields);
        if (!$airtable_saved && isset($data['source']) && $data['source'] === 'airtable') {
            unset($data['requests'][$id]);
            wp_safe_redirect(add_query_arg(array('proc_view' => 'solicitar', 'proc_notice' => 'airtable_create_failed'), home_url('/admin-procurement/')));
            exit;
        }

        $data['next_request'] = $next + 1;
        cleg_procurement_add_audit($data, 'Solicitud creada', $id, $data['requests'][$id]['item']);
        cleg_procurement_save_data($data);

        wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($id), 'proc_notice' => 'created'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_create_request', 'cleg_procurement_handle_create_request');

if (!function_exists('cleg_procurement_handle_update_status')) {
    function cleg_procurement_handle_update_status() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_update_status');

        $id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        $status = sanitize_text_field(wp_unslash($_POST['status'] ?? ''));
        $return_view = sanitize_key(wp_unslash($_POST['return_view'] ?? 'detalle'));
        $statuses = cleg_procurement_statuses();
        $data = cleg_procurement_get_data();

        if ($id && isset($data['requests'][$id]) && isset($statuses[$status])) {
            $old = $data['requests'][$id]['status'];
            $data['requests'][$id]['status'] = $status;
            $data['requests'][$id]['updated_at'] = current_time('mysql');
            cleg_procurement_set_request_override($id, array(
                'status' => $status,
                'voided' => cleg_procurement_status_is_cancelled($status) ? 'yes' : 'no',
            ));
            cleg_procurement_add_audit($data, 'Estado actualizado', $id, $old . ' -> ' . $status);
            $airtable_saved = cleg_procurement_update_airtable_status($data['requests'][$id], $status);
            if (!$airtable_saved && ($data['source'] ?? '') === 'airtable') {
                $data['source'] = 'wordpress';
            }
            cleg_procurement_save_data($data);
        }

        $redirect_args = array('proc_notice' => 'status');
        if ($return_view === 'pendientes') {
            $redirect_args['proc_view'] = 'pendientes';
        } else {
            $redirect_args['proc_view'] = 'detalle';
            $redirect_args['proc_request'] = rawurlencode($id);
        }

        wp_safe_redirect(add_query_arg($redirect_args, home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_update_status', 'cleg_procurement_handle_update_status');

