if (!function_exists('cleg_procurement_handle_delete_request_attachments')) {
    function cleg_procurement_handle_delete_request_attachments() {
        cleg_procurement_guard();
        check_admin_referer('cleg_procurement_delete_request_attachments');

        $id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        $keys = array();
        foreach ((array) ($_POST['attachment_keys'] ?? array()) as $key) {
            $key = sanitize_text_field(wp_unslash($key));
            if ($key !== '') {
                $keys[] = $key;
            }
        }

        $single_key = sanitize_text_field(wp_unslash($_POST['attachment_key_single'] ?? ''));
        if ($single_key !== '') {
            $keys[] = $single_key;
        }

        $keys = array_values(array_unique($keys));
        $data = cleg_procurement_get_data();

        if ($id && $keys && isset($data['requests'][$id])) {
            $request = $data['requests'][$id];
            cleg_procurement_require_request_edit($request);
            $attachments = cleg_procurement_dedupe_attachments($request['reference_images'] ?? array());
            $remaining = array();

            foreach ($attachments as $attachment) {
                $key = cleg_procurement_attachment_key($attachment);
                if ($key === '' || !in_array($key, $keys, true)) {
                    $remaining[] = $attachment;
                }
            }

            $request['reference_images'] = cleg_procurement_dedupe_attachments($remaining);
            $request['updated_at'] = current_time('mysql');
            $request['_sync_attachments'] = true;
            $data['requests'][$id] = $request;
            cleg_procurement_set_request_override($id, array(
                'reference_images' => $request['reference_images'],
                'updated_at' => $request['updated_at'],
            ));

            $item_fields = array(
                'Item Description' => sanitize_text_field((string) ($request['item'] ?? '')),
                'Quantity' => $request['quantity'] ?? 1,
                'Unit' => sanitize_text_field((string) ($request['unit'] ?? 'Unidad')),
                'Preferred Brand / Model' => sanitize_text_field((string) ($request['preferred_brand_model'] ?? '')),
                'Substitute Accepted' => sanitize_text_field((string) ($request['substitute'] ?? 'Pendiente')),
                'Required Date' => $request['required_delivery_date'] ?: ($request['quote_due_date'] ?? ''),
                'Technical Specs' => sanitize_textarea_field((string) ($request['conditions'] ?? '')),
                'Special Conditions' => sanitize_textarea_field((string) ($request['urgency_notes'] ?? '')),
                'Item Status' => sanitize_text_field((string) ($request['item_status'] ?? 'Needs classification')),
                'Intake Category' => sanitize_text_field((string) ($request['intake_category'] ?? 'Industrial component')),
                'Information Level' => sanitize_text_field((string) ($request['information_level'] ?? 'Usable for RFQ')),
                'Purchase Intent' => sanitize_text_field((string) ($request['purchase_intent'] ?? '')),
                'Item Missing Information' => sanitize_textarea_field((string) ($request['item_missing_information'] ?? '')),
                'Technical Risk' => sanitize_text_field((string) ($request['technical_risk'] ?? 'Medium')),
                'RFQ Ready' => in_array(($request['information_level'] ?? ''), array('Complete', 'Usable for RFQ'), true),
                'RFQ Template Type' => sanitize_text_field((string) ($request['rfq_template_type'] ?? 'General technical RFQ')),
                'RFQ Draft' => sanitize_textarea_field((string) ($request['rfq_draft'] ?? '')),
                'Item Next Action' => sanitize_text_field((string) ($request['item_next_action'] ?? ($request['next_action'] ?? ''))),
            );

            cleg_procurement_update_airtable_request_info($request, $item_fields);
            cleg_procurement_add_audit($data, 'Adjuntos eliminados', $id, count($keys) . ' archivo(s)');
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($id), 'proc_notice' => 'attachments_deleted'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_delete_request_attachments', 'cleg_procurement_handle_delete_request_attachments');

