                'Technical Specs' => sanitize_textarea_field((string) ($request['conditions'] ?? '')),
                'Special Conditions' => sanitize_textarea_field((string) ($request['urgency_notes'] ?? '')),
                'Item Status' => sanitize_text_field((string) ($request['item_status'] ?? 'Needs classification')),
                'Intake Category' => sanitize_text_field((string) ($request['intake_category'] ?? 'Industrial component')),
                'Information Level' => sanitize_text_field((string) ($request['information_level'] ?? 'Usable for RFQ')),
                'Purchase Intent' => sanitize_text_field((string) ($request['purchase_intent'] ?? '')),
                'Item Missing Information' => sanitize_textarea_field((string) ($request['item_missing_information'] ?? '')),
                'Technical Risk' => sanitize_text_field((string) ($request['technical_risk'] ?? 'Medium')),
                'RFQ Ready' => in_array(($request['information_level'] ?? ''), array('Complete', 'Usable for RFQ'), true),
                'RFQ Template Type' => sanitize_text_field((string) ($request['rfq_template_type'] ?? 'General technical RFQ')),
                'RFQ Draft' => sanitize_textarea_field((string) ($request['rfq_draft'] ?? '')),
                'Item Next Action' => sanitize_text_field((string) ($request['item_next_action'] ?? ($request['next_action'] ?? ''))),
            );

            $data['requests'][$id] = $request;
            $airtable_request_saved = cleg_procurement_update_airtable_request_info($request, $item_fields);
            if (!$airtable_request_saved && ($data['source'] ?? '') === 'airtable') {
                $data['source'] = 'wordpress';
            }

            if ($po_id !== '' && isset($data['pos'][$po_id]) && (string) ($data['pos'][$po_id]['request_id'] ?? '') === $id) {
                $allowed_statuses = cleg_procurement_po_status_options();
                $po_status = sanitize_text_field(wp_unslash($_POST['po_status'] ?? ($data['pos'][$po_id]['status'] ?? 'Ordered')));
                if (!in_array($po_status, $allowed_statuses, true)) {
                    $po_status = 'Ordered';
                }

                $previous_tracking = trim((string) ($data['pos'][$po_id]['tracking'] ?? ''));
                $data['pos'][$po_id]['amount'] = sanitize_text_field(wp_unslash($_POST['po_amount'] ?? ($data['pos'][$po_id]['amount'] ?? '0')));
                $data['pos'][$po_id]['eta'] = cleg_procurement_airtable_date(wp_unslash($_POST['po_eta'] ?? ($data['pos'][$po_id]['eta'] ?? '')));
                $data['pos'][$po_id]['ordered_date'] = cleg_procurement_airtable_date(wp_unslash($_POST['ordered_date'] ?? ($data['pos'][$po_id]['ordered_date'] ?? '')));
                $data['pos'][$po_id]['tracking'] = sanitize_text_field(wp_unslash($_POST['tracking'] ?? ($data['pos'][$po_id]['tracking'] ?? '')));
                $data['pos'][$po_id]['status'] = $po_status;
                if ($quick_note !== '') {
                    $data['pos'][$po_id]['quick_update_note'] = $quick_note;
                }
                $data['pos'][$po_id]['updated_at'] = current_time('mysql');

                $po_saved = cleg_procurement_update_airtable_po_details($data['pos'][$po_id]);
                if (!$po_saved && ($data['source'] ?? '') === 'airtable') {
                    $data['source'] = 'wordpress';
                }

                $current_tracking = trim((string) ($data['pos'][$po_id]['tracking'] ?? ''));
                if ($current_tracking !== '' && $current_tracking !== $previous_tracking && !empty($data['pos'][$po_id]['airtable_id']) && cleg_procurement_po_has_quickbooks_number($po_id)) {
                    $shipment_update = array(
                        'type' => 'tracking',
                        'label' => 'Tracking de PO QuickBooks',
                        'value' => $current_tracking,
                        'payload' => array(
                            'tracking_number' => $current_tracking,
                            'eta' => $data['pos'][$po_id]['eta'] ?? '',
                            'po_airtable_id' => $data['pos'][$po_id]['airtable_id'],
                            'shipment_status' => 'In Transit',
                        ),
                    );
                    $shipment_id = cleg_procurement_add_airtable_shipment($request, $shipment_update, 'Tracking guardado para PO QuickBooks ' . $po_id);
                    if ($shipment_id) {
                        $data['pos'][$po_id]['shipment_airtable_id'] = is_string($shipment_id) ? $shipment_id : '';
                        $data['requests'][$id]['shipment_airtable_ids'][] = is_string($shipment_id) ? $shipment_id : '';
                    } elseif (($data['source'] ?? '') === 'airtable') {
                        $data['source'] = 'wordpress';
                    }
                }

                if (isset($data['requests'][$id])) {
                    $data['requests'][$id]['status'] = in_array($po_status, array('Received', 'Closed', 'Delivered complete'), true) ? 'Received' : ($current_tracking !== '' ? 'In Transit' : ($data['requests'][$id]['status'] ?? $request['status']));
                    if ($current_tracking !== '') {
                        $data['requests'][$id]['tracking_number'] = $current_tracking;
                    }
                    $data['requests'][$id]['updated_at'] = current_time('mysql');
                }
            }

            if ($quick_note !== '') {
                cleg_procurement_add_audit($data, 'Nota agregada desde bandeja', $id, $quick_note);
            } else {
                cleg_procurement_add_audit($data, 'Datos basicos actualizados', $id, 'Bandeja');
            }
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array(
            'proc_view' => 'pendientes',
            'proc_stage' => $stage ?: 'all',
            'proc_notice' => 'quick_updated',
        ), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_quick_update_basics', 'cleg_procurement_handle_quick_update_basics');

if (!function_exists('cleg_procurement_handle_add_quote')) {
    function cleg_procurement_handle_add_quote() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_add_quote');

        $id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        $data = cleg_procurement_get_data();

        if ($id && isset($data['requests'][$id])) {
            if (!isset($data['quotes'][$id]) || !is_array($data['quotes'][$id])) {
                $data['quotes'][$id] = array();
            }

            $quote_documents = cleg_procurement_upload_reference_images('quote_documents');
            $quote = array(
                'vendor' => sanitize_text_field(wp_unslash($_POST['vendor'] ?? '')),
                'contact' => sanitize_text_field(wp_unslash($_POST['contact'] ?? '')),
                'supplier_contact_person' => sanitize_text_field(wp_unslash($_POST['supplier_contact_person'] ?? '')),
                'supplier_contact_email' => sanitize_email(wp_unslash($_POST['supplier_contact_email'] ?? '')),
                'supplier_contact_phone' => sanitize_text_field(wp_unslash($_POST['supplier_contact_phone'] ?? '')),
                'amount' => sanitize_text_field(wp_unslash($_POST['amount'] ?? '0')),
                'eta' => sanitize_text_field(wp_unslash($_POST['eta'] ?? '')),
                'expires' => sanitize_text_field(wp_unslash($_POST['expires'] ?? '')),
                'risk' => sanitize_text_field(wp_unslash($_POST['risk'] ?? 'Medio')),
                'quote_status' => 'Received',
                'estimated_delivery_to_pr' => cleg_procurement_airtable_date(wp_unslash($_POST['estimated_delivery_to_pr'] ?? '')),
                'can_meet_required_delivery_date' => sanitize_text_field(wp_unslash($_POST['can_meet_required_delivery_date'] ?? 'Unknown')),
                'delivery_risk_notes' => sanitize_textarea_field(wp_unslash($_POST['delivery_risk_notes'] ?? '')),
                'recommended' => isset($_POST['recommended']) ? 'yes' : 'no',
                'notes' => sanitize_textarea_field(wp_unslash($_POST['notes'] ?? '')),
                'decision_support_notes' => sanitize_textarea_field(wp_unslash($_POST['decision_support_notes'] ?? '')),
                'client_response_status' => sanitize_text_field(wp_unslash($_POST['client_response_status'] ?? '')),
                'client_sent_at' => cleg_procurement_airtable_datetime(wp_unslash($_POST['client_sent_at'] ?? '')),
                'client_follow_up_due_date' => cleg_procurement_airtable_date(wp_unslash($_POST['client_follow_up_due_date'] ?? '')),
                'client_response_at' => cleg_procurement_airtable_datetime(wp_unslash($_POST['client_response_at'] ?? '')),
                'client_follow_up_count' => absint($_POST['client_follow_up_count'] ?? 0),
                'client_last_follow_up_date' => cleg_procurement_airtable_date(wp_unslash($_POST['client_last_follow_up_date'] ?? '')),
                'client_decision_notes' => sanitize_textarea_field(wp_unslash($_POST['client_decision_notes'] ?? '')),
                'files' => $quote_documents,
            );

            if (cleg_procurement_quote_exists($data['quotes'][$id], $quote)) {
                wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($id), 'proc_notice' => 'quote_duplicate'), home_url('/admin-procurement/')));
                exit;
            }

            $airtable_quote_id = cleg_procurement_add_airtable_quote($data['requests'][$id], $quote);
            if (is_string($airtable_quote_id) && $airtable_quote_id !== '') {
                $quote['airtable_id'] = $airtable_quote_id;
            }

            if (!$airtable_quote_id) {
                $data['quotes'][$id][] = $quote;
                $data['quotes'][$id] = cleg_procurement_dedupe_quote_list($data['quotes'][$id]);
            }

            cleg_procurement_upsert_provider_history_from_quote($data, $data['requests'][$id], $quote);
            $data['requests'][$id]['status'] = 'Quotes Received';
            $data['requests'][$id]['updated_at'] = current_time('mysql');
            cleg_procurement_add_audit($data, 'Cotizacion agregada', $id, sanitize_text_field(wp_unslash($_POST['vendor'] ?? '')));
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($id), 'proc_notice' => 'quote'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_add_quote', 'cleg_procurement_handle_add_quote');

if (!function_exists('cleg_procurement_handle_update_quote')) {
    function cleg_procurement_handle_update_quote() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_update_quote');

        $id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        $quote_index = absint($_POST['quote_index'] ?? 0);
        $quote_action = sanitize_text_field(wp_unslash($_POST['quote_action'] ?? 'update'));
        $data = cleg_procurement_get_data();

        if ($id && isset($data['requests'][$id]) && isset($data['quotes'][$id][$quote_index])) {
            $existing = is_array($data['quotes'][$id][$quote_index]) ? $data['quotes'][$id][$quote_index] : array();
            $note = sanitize_textarea_field(wp_unslash($_POST['notes'] ?? ($existing['notes'] ?? '')));
            $quote_documents = cleg_procurement_dedupe_attachments(array_merge(
                cleg_procurement_quote_documents($existing),
                cleg_procurement_upload_reference_images('quote_documents')
            ));

            $quote = wp_parse_args(array(
                'vendor' => sanitize_text_field(wp_unslash($_POST['vendor'] ?? ($existing['vendor'] ?? ''))),
                'contact' => sanitize_text_field(wp_unslash($_POST['contact'] ?? ($existing['contact'] ?? ''))),
                'supplier_contact_person' => sanitize_text_field(wp_unslash($_POST['supplier_contact_person'] ?? ($existing['supplier_contact_person'] ?? ''))),
                'supplier_contact_email' => sanitize_email(wp_unslash($_POST['supplier_contact_email'] ?? ($existing['supplier_contact_email'] ?? ''))),
                'supplier_contact_phone' => sanitize_text_field(wp_unslash($_POST['supplier_contact_phone'] ?? ($existing['supplier_contact_phone'] ?? ''))),
                'amount' => sanitize_text_field(wp_unslash($_POST['amount'] ?? ($existing['amount'] ?? '0'))),
                'eta' => sanitize_text_field(wp_unslash($_POST['eta'] ?? ($existing['eta'] ?? ''))),
                'expires' => cleg_procurement_airtable_date(wp_unslash($_POST['expires'] ?? ($existing['expires'] ?? ''))),
                'risk' => sanitize_text_field(wp_unslash($_POST['risk'] ?? ($existing['risk'] ?? 'Medio'))),
                'quote_status' => sanitize_text_field(wp_unslash($_POST['quote_status'] ?? ($existing['quote_status'] ?? 'Received'))),
                'estimated_delivery_to_pr' => cleg_procurement_airtable_date(wp_unslash($_POST['estimated_delivery_to_pr'] ?? ($existing['estimated_delivery_to_pr'] ?? ''))),
                'can_meet_required_delivery_date' => sanitize_text_field(wp_unslash($_POST['can_meet_required_delivery_date'] ?? ($existing['can_meet_required_delivery_date'] ?? 'Unknown'))),
                'delivery_risk_notes' => sanitize_textarea_field(wp_unslash($_POST['delivery_risk_notes'] ?? ($existing['delivery_risk_notes'] ?? ''))),
                'recommended' => in_array($quote_action, array('client_sent', 'client_follow_up'), true) ? ($existing['recommended'] ?? 'no') : (isset($_POST['recommended']) ? 'yes' : 'no'),
                'notes' => $note,
                'decision_support_notes' => sanitize_textarea_field(wp_unslash($_POST['decision_support_notes'] ?? ($existing['decision_support_notes'] ?? ''))),
                'client_response_status' => sanitize_text_field(wp_unslash($_POST['client_response_status'] ?? ($existing['client_response_status'] ?? ''))),
                'client_sent_at' => cleg_procurement_airtable_datetime(wp_unslash($_POST['client_sent_at'] ?? ($existing['client_sent_at'] ?? ''))),
                'client_follow_up_due_date' => cleg_procurement_airtable_date(wp_unslash($_POST['client_follow_up_due_date'] ?? ($existing['client_follow_up_due_date'] ?? ''))),
                'client_response_at' => cleg_procurement_airtable_datetime(wp_unslash($_POST['client_response_at'] ?? ($existing['client_response_at'] ?? ''))),
                'client_follow_up_count' => isset($_POST['client_follow_up_count']) ? absint($_POST['client_follow_up_count']) : absint($existing['client_follow_up_count'] ?? 0),
                'client_last_follow_up_date' => cleg_procurement_airtable_date(wp_unslash($_POST['client_last_follow_up_date'] ?? ($existing['client_last_follow_up_date'] ?? ''))),
                'client_decision_notes' => sanitize_textarea_field(wp_unslash($_POST['client_decision_notes'] ?? ($existing['client_decision_notes'] ?? ''))),
                'files' => $quote_documents,
            ), $existing);

            if ($quote_action === 'client_sent') {
                $quote['client_response_status'] = 'Pendiente';
                $quote['client_sent_at'] = current_time('mysql');
                $quote['client_follow_up_due_date'] = cleg_procurement_client_follow_up_due_date($data['requests'][$id]);
                $quote['client_follow_up_count'] = absint($quote['client_follow_up_count'] ?? 0);
            } elseif ($quote_action === 'client_follow_up') {
                $quote['client_response_status'] = $quote['client_response_status'] ?: 'Pendiente';
                $quote['client_sent_at'] = $quote['client_sent_at'] ?: current_time('mysql');
                $quote['client_follow_up_count'] = absint($quote['client_follow_up_count'] ?? 0) + 1;
                $quote['client_last_follow_up_date'] = current_time('Y-m-d');
                $quote['client_follow_up_due_date'] = cleg_procurement_client_follow_up_due_date($data['requests'][$id]);
            }

            if (in_array($quote['client_response_status'] ?? '', array('Aceptada', 'Rechazada', 'Sin respuesta'), true) && empty($quote['client_response_at'])) {
                $quote['client_response_at'] = current_time('mysql');
            }

            if ($quote_action === 'void') {
                $void_reason = sanitize_textarea_field(wp_unslash($_POST['void_reason'] ?? 'Cotizacion creada por error.'));
                $quote['quote_status'] = 'Cancelled';
                $quote['recommended'] = 'no';
                $quote['voided'] = 'yes';
                $quote['void_reason'] = $void_reason ?: 'Cotizacion creada por error.';
                $quote['delivery_risk_notes'] = trim(($quote['delivery_risk_notes'] ?? '') . "\n" . 'Anulada: ' . $quote['void_reason']);
            }

            if (($quote['recommended'] ?? 'no') === 'yes' && isset($data['quotes'][$id]) && is_array($data['quotes'][$id])) {
                foreach ($data['quotes'][$id] as $other_index => $other_quote) {
                    if ((int) $other_index === (int) $quote_index || !is_array($other_quote)) {
                        continue;
                    }
                    $data['quotes'][$id][$other_index]['recommended'] = 'no';
                }
            }

            $data['quotes'][$id][$quote_index] = $quote;
            cleg_procurement_upsert_provider_history_from_quote($data, $data['requests'][$id], $quote);
            $airtable_saved = cleg_procurement_update_airtable_quote($quote);
            $has_client_data = in_array($quote_action, array('client_sent', 'client_follow_up'), true) || !empty($quote['client_response_status']) || !empty($quote['client_sent_at']) || !empty($quote['client_follow_up_due_date']);
            $request_client_saved = true;
            if ($has_client_data) {
                $request_client_saved = cleg_procurement_update_airtable_request_client_summary($data['requests'][$id], $quote);
                $data['requests'][$id]['client_approval_status'] = cleg_procurement_request_client_status_from_quote($quote);
                $data['requests'][$id]['client_sent_at'] = $quote['client_sent_at'] ?? '';
                $data['requests'][$id]['client_follow_up_due_date'] = $quote['client_follow_up_due_date'] ?? '';
                $data['requests'][$id]['client_follow_up_count'] = $quote['client_follow_up_count'] ?? 0;
                $data['requests'][$id]['client_last_follow_up_date'] = $quote['client_last_follow_up_date'] ?? '';
                $data['requests'][$id]['client_decision_notes'] = $quote['client_decision_notes'] ?? '';
            }
            if (!$airtable_saved && ($data['source'] ?? '') === 'airtable') {
                $data['source'] = 'wordpress';
            }
            if (!$request_client_saved && ($data['source'] ?? '') === 'airtable') {
                $data['source'] = 'wordpress';
            }
            $audit_label = $quote_action === 'void' ? 'Cotizacion anulada' : ($quote_action === 'client_sent' ? 'Cotizacion enviada al cliente' : ($quote_action === 'client_follow_up' ? 'Seguimiento cliente registrado' : 'Cotizacion actualizada'));
            cleg_procurement_add_audit($data, $audit_label, $id, $quote['vendor']);
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($id), 'proc_notice' => $quote_action === 'void' ? 'quote_voided' : 'quote_updated'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_update_quote', 'cleg_procurement_handle_update_quote');

if (!function_exists('cleg_procurement_handle_create_po')) {
    function cleg_procurement_handle_create_po() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_create_po');

        $id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        $data = cleg_procurement_get_data();

        if ($id && isset($data['requests'][$id])) {
            $po_id = sanitize_text_field(wp_unslash($_POST['quickbooks_po'] ?? $_POST['po_number'] ?? ''));
            if ($po_id === '') {
                wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($id), 'proc_notice' => 'po_missing_quickbooks'), home_url('/admin-procurement/')));
                exit;
            }

            $request = $data['requests'][$id];
            $recommended_quote = cleg_procurement_recommended_quote($data['quotes'][$id] ?? array());

            $po = array(
                'id' => $po_id,
                'request_id' => $id,
                'vendor' => sanitize_text_field(wp_unslash($_POST['vendor'] ?? '')),
                'amount' => sanitize_text_field(wp_unslash($_POST['amount'] ?? '0')),
                'eta' => sanitize_text_field(wp_unslash($_POST['eta'] ?? '')),
                'tracking' => '',
                'quote_airtable_id' => sanitize_text_field((string) ($recommended_quote['airtable_id'] ?? '')),
                'received_qty' => 0,
                'status' => 'Ordered',
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            );

            $airtable_po_id = cleg_procurement_add_airtable_po($request, $po, $recommended_quote);
            if ($airtable_po_id) {
                $po['airtable_id'] = is_string($airtable_po_id) ? $airtable_po_id : '';
            } elseif (($data['source'] ?? '') === 'airtable') {
                $data['source'] = 'wordpress';
            }

            if (!empty($po['airtable_id']) && !empty($po['eta'])) {
                $shipment_update = array(
                    'type' => 'eta',
                    'label' => 'ETA inicial de PO QuickBooks',
                    'value' => $po['eta'],
                    'payload' => array(
                        'eta' => $po['eta'],
                        'po_airtable_id' => $po['airtable_id'],
                        'shipment_status' => 'Pending tracking',
                    ),
                );
                $shipment_id = cleg_procurement_add_airtable_shipment($request, $shipment_update, 'ETA inicial para PO QuickBooks ' . $po_id);
                if ($shipment_id) {
                    $po['shipment_airtable_id'] = is_string($shipment_id) ? $shipment_id : '';
                }
            }

            $data['pos'][$po_id] = $po;
            $data['requests'][$id]['status'] = 'Ordered';
            $data['requests'][$id]['updated_at'] = current_time('mysql');
            if (!empty($po['airtable_id'])) {
                $data['requests'][$id]['po_airtable_ids'][] = $po['airtable_id'];
            }
            cleg_procurement_add_audit($data, 'PO QuickBooks asignada', $po_id, 'Solicitud ' . $id);
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($id), 'proc_notice' => 'po_quickbooks'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_create_po', 'cleg_procurement_handle_create_po');

if (!function_exists('cleg_procurement_handle_update_po_tracking')) {
    function cleg_procurement_handle_update_po_tracking() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_update_po_tracking');

        $request_id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        $po_id = sanitize_text_field(wp_unslash($_POST['po_id'] ?? ''));
        $tracking = sanitize_text_field(wp_unslash($_POST['tracking'] ?? ''));
        $eta = sanitize_text_field(wp_unslash($_POST['eta'] ?? ''));
        $data = cleg_procurement_get_data();

        if ($request_id && $po_id && $tracking !== '' && isset($data['requests'][$request_id], $data['pos'][$po_id]) && (string) ($data['pos'][$po_id]['request_id'] ?? '') === $request_id) {
            $request = $data['requests'][$request_id];
            $data['pos'][$po_id]['tracking'] = $tracking;
            if ($eta !== '') {
                $data['pos'][$po_id]['eta'] = $eta;
            }
            $data['pos'][$po_id]['status'] = 'In Transit';
            $data['pos'][$po_id]['updated_at'] = current_time('mysql');
            $data['requests'][$request_id]['status'] = 'In Transit';
            $data['requests'][$request_id]['tracking_number'] = $tracking;
            $data['requests'][$request_id]['updated_at'] = current_time('mysql');

            if (!empty($data['pos'][$po_id]['airtable_id'])) {
                $shipment_update = array(
                    'type' => 'tracking',
                    'label' => 'Tracking de PO QuickBooks',
                    'value' => $tracking,
                    'payload' => array(
                        'tracking_number' => $tracking,
                        'eta' => $eta ?: ($data['pos'][$po_id]['eta'] ?? ''),
                        'po_airtable_id' => $data['pos'][$po_id]['airtable_id'],
                        'shipment_status' => 'In Transit',
                    ),
                );
                $shipment_id = cleg_procurement_add_airtable_shipment($request, $shipment_update, 'Tracking guardado para PO QuickBooks ' . $po_id);
                if ($shipment_id) {
                    $data['pos'][$po_id]['shipment_airtable_id'] = is_string($shipment_id) ? $shipment_id : '';
                    $data['requests'][$request_id]['shipment_airtable_ids'][] = is_string($shipment_id) ? $shipment_id : '';
                } elseif (($data['source'] ?? '') === 'airtable') {
                    $data['source'] = 'wordpress';
                }
            }

            cleg_procurement_add_audit($data, 'Tracking guardado', $po_id, $tracking);
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($request_id), 'proc_notice' => $tracking === '' ? 'tracking_missing' : 'tracking_updated'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_update_po_tracking', 'cleg_procurement_handle_update_po_tracking');

if (!function_exists('cleg_procurement_handle_receive_po')) {
    function cleg_procurement_handle_receive_po() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_receive_po');

        $po_id = sanitize_text_field(wp_unslash($_POST['po_id'] ?? ''));
        $status = sanitize_text_field(wp_unslash($_POST['receipt_status'] ?? 'Partially Received'));
        $note = sanitize_textarea_field(wp_unslash($_POST['receipt_note'] ?? ''));
        $data = cleg_procurement_get_data();
        $request_id = '';

        if ($po_id && isset($data['pos'][$po_id])) {
            if (!cleg_procurement_po_has_quickbooks_number($po_id)) {
                $request_id = $data['pos'][$po_id]['request_id'] ?? '';
                wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($request_id), 'proc_notice' => 'po_missing_quickbooks'), home_url('/admin-procurement/')));
                exit;
            }

            $status = in_array($status, array('Partially Received', 'Received', 'Closed'), true) ? $status : 'Partially Received';
            $data['pos'][$po_id]['status'] = $status;
            $data['pos'][$po_id]['receipt_note'] = $note;
            $data['pos'][$po_id]['received_at'] = current_time('mysql');
            $data['pos'][$po_id]['updated_at'] = current_time('mysql');
            $request_id = $data['pos'][$po_id]['request_id'];

            if (!empty($data['pos'][$po_id]['airtable_id'])) {
                cleg_procurement_update_airtable_po_details($data['pos'][$po_id]);
            }

            if ($request_id && isset($data['requests'][$request_id])) {
                $data['requests'][$request_id]['status'] = $status;
                $data['requests'][$request_id]['updated_at'] = current_time('mysql');
            }

            cleg_procurement_add_audit($data, 'Recepcion actualizada', $po_id, $status . ' - ' . $note);
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode($request_id), 'proc_notice' => 'received'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_receive_po', 'cleg_procurement_handle_receive_po');

if (!function_exists('cleg_procurement_handle_update_history_row')) {
    function cleg_procurement_handle_update_history_row() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_update_history_row');

        $source = sanitize_key(wp_unslash($_POST['history_source'] ?? ''));
        $record_id = sanitize_text_field(wp_unslash($_POST['history_id'] ?? ''));
        $request_id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        $quote_index = isset($_POST['quote_index']) ? absint($_POST['quote_index']) : null;
        $provider_index = isset($_POST['provider_index']) ? sanitize_text_field(wp_unslash($_POST['provider_index'])) : null;
        $history_key = sanitize_text_field(wp_unslash($_POST['history_key'] ?? ''));
        $payload = cleg_procurement_history_update_payload();
        $data = cleg_procurement_get_data();
        $saved = false;

        if (in_array($source, array('airtable_history', 'airtable_quote', 'airtable_vendor'), true)) {
            $saved = cleg_procurement_update_airtable_history_row($source, $record_id, $payload);
        }

        if (!$saved && $source === 'local_quote' && $request_id !== '' && $quote_index !== null && isset($data['quotes'][$request_id][$quote_index])) {
            $existing = is_array($data['quotes'][$request_id][$quote_index]) ? $data['quotes'][$request_id][$quote_index] : array();
            $quote = wp_parse_args(array(
                'vendor' => $payload['vendor'],
                'amount' => $payload['price'],
                'currency' => $payload['currency'],
                'eta' => $payload['lead_time'],
                'expires' => $payload['date'],
                'notes' => $payload['notes'],
                'delivery_risk_notes' => $payload['notes'],
                'updated_at' => current_time('mysql'),
            ), $existing);
            if (!empty($payload['item'])) {
                $quote['item'] = $payload['item'];
            }
            if (!empty($payload['reference'])) {
                $quote['reference'] = $payload['reference'];
            }
            $data['quotes'][$request_id][$quote_index] = $quote;
            if (!empty($quote['airtable_id'])) {
                cleg_procurement_update_airtable_quote($quote);
            }
            cleg_procurement_add_audit($data, 'Historico actualizado', $request_id, $payload['vendor'] . ' - ' . $payload['item']);
            cleg_procurement_save_data($data);
            $saved = true;
        }

        if (!$saved && $source === 'local_provider_history' && $provider_index !== null) {
            if (!isset($data['provider_history']) || !is_array($data['provider_history'])) {
                $data['provider_history'] = array();
            }
            $existing = isset($data['provider_history'][$provider_index]) && is_array($data['provider_history'][$provider_index]) ? $data['provider_history'][$provider_index] : array();
            $data['provider_history'][$provider_index] = wp_parse_args(array(
                'vendor' => $payload['vendor'],
                'item' => $payload['item'],
                'price' => $payload['price'],
                'currency' => $payload['currency'],
                'lead_time' => $payload['lead_time'],
                'reference' => $payload['reference'],
                'quote_date' => $payload['date'],
                'notes' => $payload['notes'],
                'updated_at' => current_time('mysql'),
            ), $existing);
            cleg_procurement_add_audit($data, 'Historico actualizado', $record_id ?: 'provider_history', $payload['vendor'] . ' - ' . $payload['item']);
            cleg_procurement_save_data($data);
            $saved = true;
        }

        if (!$saved && $history_key !== '') {
            if (!isset($data['history_overrides']) || !is_array($data['history_overrides'])) {
                $data['history_overrides'] = array();
            }
            $data['history_overrides'][$history_key] = array(
                'vendor' => $payload['vendor'],
                'item' => $payload['item'],
                'price' => $payload['price'],
                'currency' => $payload['currency'],
                'lead_time' => $payload['lead_time'],
                'reference' => $payload['reference'],
                'date' => $payload['date'],
                'notes' => $payload['notes'],
                'source' => 'Historico ajustado en web',
                'updated_at' => current_time('mysql'),
            );
            cleg_procurement_add_audit($data, 'Historico ajustado localmente', $record_id ?: $history_key, $payload['vendor'] . ' - ' . $payload['item']);
            cleg_procurement_save_data($data);
            $saved = true;
        }

        wp_safe_redirect(add_query_arg(array(
            'proc_view' => 'historial',
            'proc_notice' => $saved ? 'history_updated' : 'history_update_failed',
        ), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_update_history_row', 'cleg_procurement_handle_update_history_row');

if (!function_exists('cleg_procurement_handle_create_history_row')) {
    function cleg_procurement_handle_create_history_row() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_create_history_row');

        $payload = cleg_procurement_history_update_payload();
        $data = cleg_procurement_get_data();
        $saved = false;
        $airtable_id = '';

        if (cleg_procurement_airtable_ready()) {
            $airtable_result = cleg_procurement_add_airtable_history(array(), array(
                'vendor' => $payload['vendor'],
                'item' => $payload['item'],
                'price' => $payload['price'],
                'currency' => $payload['currency'],
                'lead_time' => $payload['lead_time'],
                'reference' => $payload['reference'],
                'quote_date' => $payload['date'],
                'notes' => $payload['notes'],
            ));
            if ($airtable_result) {
                $saved = true;
                $airtable_id = is_string($airtable_result) ? $airtable_result : '';
            }
        }

        if (!$saved) {
            if (!isset($data['provider_history']) || !is_array($data['provider_history'])) {
                $data['provider_history'] = array();
            }
            $local_id = 'HIST-' . gmdate('Ymd-His') . '-' . wp_generate_password(4, false, false);
            $data['provider_history'][$local_id] = array(
                'id' => $local_id,
                'vendor' => $payload['vendor'] ?: 'Proveedor pendiente',
                'item' => $payload['item'] ?: 'Item pendiente',
                'price' => $payload['price'],
                'currency' => $payload['currency'] ?: 'USD',
                'lead_time' => $payload['lead_time'],
                'reference' => $payload['reference'],
                'quote_date' => $payload['date'],
                'notes' => $payload['notes'],
                'created_at' => current_time('mysql'),
            );
            cleg_procurement_add_audit($data, 'Historico creado local', $local_id, $payload['vendor'] . ' - ' . $payload['item']);
            cleg_procurement_save_data($data);
            $saved = true;
        } else {
            cleg_procurement_add_audit($data, 'Historico creado', $airtable_id ?: 'airtable_history', $payload['vendor'] . ' - ' . $payload['item']);
            cleg_procurement_save_data($data);
        }

        wp_safe_redirect(add_query_arg(array(
            'proc_view' => 'historial',
            'proc_notice' => $saved ? 'history_created' : 'history_create_failed',
        ), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_create_history_row', 'cleg_procurement_handle_create_history_row');

if (!function_exists('cleg_procurement_handle_delete_history_row')) {
    function cleg_procurement_handle_delete_history_row() {
        cleg_procurement_guard();
        cleg_procurement_require_manage_action();
        check_admin_referer('cleg_procurement_delete_history_row');

        $source = sanitize_key(wp_unslash($_POST['history_source'] ?? ''));
        $record_id = sanitize_text_field(wp_unslash($_POST['history_id'] ?? ''));
        $provider_index = isset($_POST['provider_index']) ? sanitize_text_field(wp_unslash($_POST['provider_index'])) : '';
        $request_id = isset($_POST['request_id']) ? sanitize_text_field(wp_unslash($_POST['request_id'])) : '';
        $quote_index = isset($_POST['quote_index']) ? sanitize_text_field(wp_unslash($_POST['quote_index'])) : '';
        $history_key = sanitize_text_field(wp_unslash($_POST['history_key'] ?? ''));
        $data = cleg_procurement_get_data();
        $deleted = false;

        if ($source === 'airtable_history' && $record_id !== '') {
            $deleted = cleg_procurement_delete_airtable_history_row($source, $record_id);
        }

        if (!$deleted && $source === 'local_provider_history' && $provider_index !== '') {
            if (isset($data['provider_history']) && is_array($data['provider_history']) && array_key_exists($provider_index, $data['provider_history'])) {
                $before = is_array($data['provider_history'][$provider_index]) ? $data['provider_history'][$provider_index] : array();
                unset($data['provider_history'][$provider_index]);
                cleg_procurement_add_audit($data, 'Historico eliminado', $record_id ?: 'provider_history', trim(($before['vendor'] ?? '') . ' - ' . ($before['item'] ?? '')));
                cleg_procurement_save_data($data);
                $deleted = true;
            }
        }

        if (!$deleted) {
            if ($history_key === '') {
                $history_key = cleg_procurement_history_row_key_from_parts($source, $record_id, $provider_index, $request_id, $quote_index);
            }
            if ($history_key !== '') {
                if (!isset($data['history_hidden']) || !is_array($data['history_hidden'])) {
                    $data['history_hidden'] = array();
                }
                $data['history_hidden'][$history_key] = current_time('mysql');
                cleg_procurement_add_audit($data, 'Historico ocultado', $record_id ?: $history_key, $source ?: 'historial');
                cleg_procurement_save_data($data);
                $deleted = true;
            }
        }

        wp_safe_redirect(add_query_arg(array(
            'proc_view' => 'historial',
            'proc_notice' => $deleted ? 'history_deleted' : 'history_delete_failed',
        ), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_delete_history_row', 'cleg_procurement_handle_delete_history_row');

if (!function_exists('cleg_procurement_metric_count')) {
    function cleg_procurement_metric_count($requests, $statuses) {
        $count = 0;
        foreach ($requests as $request) {
            if (in_array($request['status'], $statuses, true)) {
                $count++;
            }
        }
        return $count;
    }
}

if (!function_exists('cleg_procurement_selected_request')) {
    function cleg_procurement_selected_request($data) {
        $selected = sanitize_text_field(wp_unslash($_GET['proc_request'] ?? ''));
        if ($selected && isset($data['requests'][$selected])) {
            return $selected;
        }

        $requests = cleg_procurement_sort_requests($data['requests']);
        foreach ($requests as $request) {
            if (!cleg_procurement_request_is_cancelled($request)) {
                return $request['id'] ?? '';
            }
        }

        $ids = array_keys($requests);
        return $ids ? $ids[0] : '';
    }
}

