if (!function_exists('cleg_procurement_agent_export_pos_for_request')) {
    function cleg_procurement_agent_export_pos_for_request($request, $pos) {
        $request_id = (string) ($request['id'] ?? '');
        $rows = array();

        if (!is_array($pos) || $request_id === '') {
            return $rows;
        }

        foreach ($pos as $po) {
            if (!is_array($po) || (string) ($po['request_id'] ?? '') !== $request_id) {
                continue;
            }

            $rows[] = array(
                'id' => (string) ($po['id'] ?? ''),
                'po_airtable_id' => (string) ($po['airtable_id'] ?? ''),
                'status' => (string) ($po['status'] ?? ''),
                'vendor' => (string) ($po['vendor'] ?? ''),
                'amount' => (string) ($po['amount'] ?? ''),
                'eta' => (string) ($po['eta'] ?? ''),
                'tracking' => (string) ($po['tracking'] ?? ''),
                'quote_airtable_id' => (string) ($po['quote_airtable_id'] ?? ''),
                'shipment_airtable_id' => (string) ($po['shipment_airtable_id'] ?? ''),
                'created_at' => (string) ($po['created_at'] ?? ''),
                'updated_at' => (string) ($po['updated_at'] ?? ''),
            );
        }

        return $rows;
    }
}

if (!function_exists('cleg_procurement_agent_export_po_airtable_ids')) {
    function cleg_procurement_agent_export_po_airtable_ids($request, $po_rows) {
        $ids = array();

        foreach ((array) ($request['po_airtable_ids'] ?? array()) as $id) {
            $id = sanitize_text_field((string) $id);
            if ($id !== '') {
                $ids[] = $id;
            }
        }

        foreach ($po_rows as $po) {
            $id = sanitize_text_field((string) ($po['po_airtable_id'] ?? ''));
            if ($id !== '') {
                $ids[] = $id;
            }
        }

        return array_values(array_unique($ids));
    }
}

if (!function_exists('cleg_procurement_agent_export_rows')) {
    function cleg_procurement_agent_export_rows($requests, $pos = array()) {
        $rows = array();

        foreach ($requests as $request) {
            if (cleg_procurement_request_is_cancelled($request)) {
                continue;
            }

            $po_rows = cleg_procurement_agent_export_pos_for_request($request, $pos);
            $po_airtable_ids = cleg_procurement_agent_export_po_airtable_ids($request, $po_rows);

            $rows[] = array(
                'id' => (string) ($request['id'] ?? ''),
                'airtable_id' => (string) ($request['airtable_id'] ?? ''),
                'item' => (string) ($request['item'] ?? ''),
                'project' => (string) ($request['project'] ?? ''),
                'requester' => (string) ($request['requester'] ?? ''),
                'priority' => (string) ($request['priority'] ?? 'Normal'),
                'status' => cleg_procurement_normalize_status($request['status'] ?? '', $request['requester'] ?? ''),
                'quantity' => $request['quantity'] ?? '',
                'unit' => (string) ($request['unit'] ?? ''),
                'quote_due_date' => (string) ($request['quote_due_date'] ?? ''),
                'required_delivery_date' => (string) ($request['required_delivery_date'] ?? ''),
                'delivery_location' => (string) ($request['delivery_location'] ?? ''),
                'substitute' => (string) ($request['substitute'] ?? ''),
                'technical_need' => (string) ($request['conditions'] ?? ''),
                'preferred_brand_model' => (string) ($request['preferred_brand_model'] ?? ''),
                'information_level' => (string) ($request['information_level'] ?? ''),
                'missing_information' => (string) ($request['item_missing_information'] ?? ''),
                'technical_risk' => (string) ($request['technical_risk'] ?? ''),
                'rfq_template_type' => (string) ($request['rfq_template_type'] ?? ''),
                'rfq_draft' => (string) ($request['rfq_draft'] ?? ''),
                'next_action' => (string) ($request['item_next_action'] ?? ($request['next_action'] ?? '')),
                'urgency_reason' => (string) ($request['urgency_reason'] ?? ''),
                'urgency_notes' => (string) ($request['urgency_notes'] ?? ''),
                'field_completeness' => (string) ($request['field_completeness'] ?? ''),
                'blocked_by' => (string) ($request['blocked_by'] ?? ''),
                'po_airtable_ids' => $po_airtable_ids,
                'primary_po_airtable_id' => (string) ($po_airtable_ids[0] ?? ''),
                'purchase_orders' => $po_rows,
                'created_at' => (string) ($request['created_at'] ?? ''),
                'updated_at' => (string) ($request['updated_at'] ?? ''),
            );
        }

        return $rows;
    }
}

if (!function_exists('cleg_procurement_agent_export_payload')) {
    function cleg_procurement_agent_export_payload($source) {
        if (isset($source['requests']) && is_array($source['requests'])) {
            $requests = $source['requests'];
            $pos = isset($source['pos']) && is_array($source['pos']) ? $source['pos'] : array();
        } else {
            $requests = is_array($source) ? $source : array();
            $pos = array();
        }

        $active_rows = cleg_procurement_agent_export_rows($requests, $pos);
        $assistant_queue = cleg_procurement_agent_export_rows(cleg_procurement_ai_requests($requests), $pos);
        $generated_at = gmdate('c');

        $payload = array(
            'schema' => 'cleg.procurement.agent_export.v2',
            'generated_at' => $generated_at,
            'source' => 'WordPress Compras',
            'agent_name' => 'Agente asistente de compras industriales',
            'sharepoint_contract' => array(
                'requests_path' => CLEG_PROC_SHAREPOINT_REQUESTS_PATH,
                'incoming_updates_path' => CLEG_PROC_SHAREPOINT_INCOMING_PATH,
                'processed_path' => CLEG_PROC_SHAREPOINT_PROCESSED_PATH,
                'canonical_index' => CLEG_PROC_SHAREPOINT_REQUESTS_PATH . '/index.json',
                'request_file_pattern' => CLEG_PROC_SHAREPOINT_REQUESTS_PATH . '/{request_id}.json',
                'incoming_update_pattern' => CLEG_PROC_SHAREPOINT_INCOMING_PATH . '/{request_id}-{timestamp}.json',
            ),
            'rules' => array(
                'test_mode' => false,
                'do_not_purchase' => true,
                'cancelled_requests_excluded' => true,
                'missing_data_must_not_be_invented' => true,
                'tracking_eta_should_use_po_airtable_id_when_available' => true,
            ),
            'counts' => array(
                'active_requests' => count($active_rows),
                'assistant_queue' => count($assistant_queue),
            ),
            'assistant_queue' => $assistant_queue,
            'active_requests' => $active_rows,
        );

        $payload['sharepoint_files'] = cleg_procurement_agent_export_sharepoint_files($payload);

        return $payload;
    }
}

if (!function_exists('cleg_procurement_agent_export_sharepoint_files')) {
    function cleg_procurement_agent_export_sharepoint_files($payload) {
        $active_rows = isset($payload['active_requests']) && is_array($payload['active_requests']) ? $payload['active_requests'] : array();
        $generated_at = (string) ($payload['generated_at'] ?? gmdate('c'));

        $index = array(
            'schema' => 'cleg.procurement.web_sync.index.v2',
            'generated_at' => $generated_at,
            'source' => 'WordPress Compras',
            'rules' => $payload['rules'] ?? array(),
            'counts' => array(
                'active_requests' => count($active_rows),
            ),
            'requests' => array(),
        );

        $files = array();
        foreach ($active_rows as $row) {
            $request_id = sanitize_file_name((string) ($row['id'] ?? ''));
            if ($request_id === '') {
                continue;
            }

            $path = trailingslashit(CLEG_PROC_SHAREPOINT_REQUESTS_PATH) . $request_id . '.json';
            $index['requests'][] = array(
                'id' => (string) ($row['id'] ?? ''),
                'status' => (string) ($row['status'] ?? ''),
                'item' => (string) ($row['item'] ?? ''),
                'path' => $path,
                'primary_po_airtable_id' => (string) ($row['primary_po_airtable_id'] ?? ''),
                'po_airtable_ids' => isset($row['po_airtable_ids']) && is_array($row['po_airtable_ids']) ? $row['po_airtable_ids'] : array(),
                'updated_at' => (string) ($row['updated_at'] ?? ''),
            );

            $files[] = array(
                'path' => $path,
                'content_type' => 'application/json',
                'conflict_behavior' => 'replace',
                'body' => array(
                    'schema' => 'cleg.procurement.request.v2',
                    'generated_at' => $generated_at,
                    'request' => $row,
                    'rules' => $payload['rules'] ?? array(),
                    'incoming_updates_path' => CLEG_PROC_SHAREPOINT_INCOMING_PATH,
                ),
            );
        }

        array_unshift($files, array(
            'path' => trailingslashit(CLEG_PROC_SHAREPOINT_REQUESTS_PATH) . 'index.json',
            'content_type' => 'application/json',
            'conflict_behavior' => 'replace',
            'body' => $index,
        ));

        $files[] = array(
            'path' => trailingslashit(CLEG_PROC_SHAREPOINT_REQUESTS_PATH) . 'package-latest.json',
            'content_type' => 'application/json',
            'conflict_behavior' => 'replace',
            'body' => array_diff_key($payload, array('sharepoint_files' => true)),
        );

        return $files;
    }
}

if (!function_exists('cleg_procurement_agent_update_candidates')) {
    function cleg_procurement_agent_update_candidates($request) {
        $updates = array();
        $request_id = (string) ($request['id'] ?? '');

        if (!empty($request['agent_updates']) && is_array($request['agent_updates'])) {
            foreach ($request['agent_updates'] as $update) {
                $normalized = cleg_procurement_normalize_agent_update($update, $request_id);
                if (!$normalized) {
                    continue;
                }

                if (cleg_procurement_agent_update_is_closed($normalized['id'])) {
                    continue;
                }

                $updates[] = $normalized;
            }
        }

        $field_map = array(
            'incoming_quote_total' => array('Cotizacion recibida', 'quote'),
            'incoming_vendor' => array('Proveedor detectado', 'quote'),
            'incoming_tracking_number' => array('Tracking recibido', 'tracking'),
            'incoming_eta' => array('ETA recibida', 'eta'),
            'incoming_quote_file' => array('Archivo de cotizacion', 'file'),
        );

        foreach ($field_map as $field => $config) {
            if (!empty($request[$field])) {
                $normalized = cleg_procurement_normalize_agent_update(array(
                    'id' => $request_id . '-' . $field,
                    'request_id' => $request_id,
                    'label' => $config[0],
                    'type' => $config[1],
                    'value' => (string) $request[$field],
                    'source' => 'SharePoint',
                ), $request_id);

                if (!$normalized || cleg_procurement_agent_update_is_closed($normalized['id'])) {
                    continue;
                }

                $updates[] = $normalized;
            }
        }

        foreach (cleg_procurement_pending_agent_updates($request_id) as $update) {
            $updates[] = $update;
        }

        return $updates;
    }
}

if (!function_exists('cleg_procurement_normalize_agent_update')) {
    function cleg_procurement_normalize_agent_update($update, $fallback_request_id = '') {
        if (!is_array($update)) {
            return null;
        }

        $payload = isset($update['payload']) && is_array($update['payload']) ? $update['payload'] : array();
        $request_id = sanitize_text_field((string) ($update['request_id'] ?? $update['request'] ?? $payload['request_id'] ?? $fallback_request_id));
        if ($request_id === '') {
            return null;
        }

        $type = sanitize_key((string) ($update['type'] ?? $payload['type'] ?? 'note'));
        if ($type === 'provider_history') {
            $type = 'history';
        }

        if (!in_array($type, array('quote', 'tracking', 'eta', 'file', 'note', 'history'), true)) {
            $type = 'note';
        }

        $value = sanitize_textarea_field((string) ($update['value'] ?? $update['summary'] ?? $payload['value'] ?? $payload['summary'] ?? ''));
        if ($value === '' && !empty($payload)) {
            $value = sanitize_textarea_field(wp_json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
        }

        if ($value === '') {
            return null;
        }

        $raw_id = (string) ($update['id'] ?? $update['update_id'] ?? '');
        $update_id = $raw_id !== '' ? sanitize_key($raw_id) : sanitize_key($request_id . '-' . $type . '-' . md5($value));

        return array(
            'id' => $update_id,
            'request_id' => $request_id,
            'type' => $type,
            'label' => sanitize_text_field((string) ($update['label'] ?? $payload['label'] ?? 'Actualizacion recibida')),
            'value' => $value,
            'source' => sanitize_text_field((string) ($update['source'] ?? 'SharePoint')),
            'status' => sanitize_key((string) ($update['status'] ?? 'pending')),
            'payload' => $payload,
            'received_at' => sanitize_text_field((string) ($update['received_at'] ?? current_time('mysql'))),
        );
    }
}

if (!function_exists('cleg_procurement_all_pending_agent_updates')) {
    function cleg_procurement_all_pending_agent_updates() {
        $updates = get_option('cleg_procurement_agent_updates_v1', array());
        return is_array($updates) ? $updates : array();
    }
}

if (!function_exists('cleg_procurement_agent_update_status')) {
    function cleg_procurement_agent_update_status($update_id) {
        $update_id = sanitize_key((string) $update_id);
        if ($update_id === '') {
            return '';
        }

        $updates = cleg_procurement_all_pending_agent_updates();
        return isset($updates[$update_id]['status']) ? sanitize_key((string) $updates[$update_id]['status']) : '';
    }
}

if (!function_exists('cleg_procurement_agent_update_is_closed')) {
    function cleg_procurement_agent_update_is_closed($update_id) {
        return in_array(cleg_procurement_agent_update_status($update_id), array('applied', 'dismissed'), true);
    }
}

if (!function_exists('cleg_procurement_pending_agent_updates')) {
    function cleg_procurement_pending_agent_updates($request_id = '') {
        $pending = array();
        foreach (cleg_procurement_all_pending_agent_updates() as $update) {
            $normalized = cleg_procurement_normalize_agent_update($update);
            if (!$normalized || $normalized['status'] !== 'pending') {
                continue;
            }
            if ($request_id !== '' && $normalized['request_id'] !== $request_id) {
                continue;
            }
            $pending[] = $normalized;
        }
        return $pending;
    }
}

if (!function_exists('cleg_procurement_store_agent_updates')) {
    function cleg_procurement_store_agent_updates($incoming) {
        if (!is_array($incoming)) {
            return 0;
        }

        $stored = cleg_procurement_all_pending_agent_updates();
        $added = 0;

        foreach ($incoming as $update) {
            $normalized = cleg_procurement_normalize_agent_update($update);
            if (!$normalized) {
                continue;
            }

            $existing_status = isset($stored[$normalized['id']]['status']) ? (string) $stored[$normalized['id']]['status'] : '';
            if ($existing_status === 'applied' || $existing_status === 'dismissed') {
                continue;
            }

            $stored[$normalized['id']] = $normalized;
            $added++;
        }

        update_option('cleg_procurement_agent_updates_v1', $stored, false);
        return $added;
    }
}

if (!function_exists('cleg_procurement_updates_from_sharepoint_document')) {
    function cleg_procurement_updates_from_sharepoint_document($document, $source = 'SharePoint') {
        if (!is_array($document)) {
            return array();
        }

        if (isset($document['updates']) && is_array($document['updates'])) {
            $updates = $document['updates'];
        } elseif (isset($document['incoming_updates']) && is_array($document['incoming_updates'])) {
            $updates = $document['incoming_updates'];
        } elseif (isset($document[0]) && is_array($document[0])) {
            $updates = $document;
        } else {
            $updates = array($document);
        }

        $normalized = array();
        foreach ($updates as $update) {
            if (!is_array($update)) {
                continue;
            }
            if (empty($update['source'])) {
                $update['source'] = $source;
            }
            $normalized[] = $update;
        }

        return $normalized;
    }
}

if (!function_exists('cleg_procurement_pull_agent_updates_from_endpoint')) {
    function cleg_procurement_pull_agent_updates_from_endpoint($force = false) {
        if (!cleg_procurement_module_enabled() || !cleg_procurement_private_sync_enabled()) {
            return 0;
        }

        $graph_added = cleg_procurement_pull_agent_updates_from_sharepoint_graph();
        if ($graph_added && !$force) {
            return $graph_added;
        }

        $endpoint = trim((string) CLEG_PROC_SHAREPOINT_INCOMING_ENDPOINT);
        if ($endpoint === '' || !wp_http_validate_url($endpoint)) {
            return $graph_added;
        }

        $last_pull = (int) get_option('cleg_procurement_agent_updates_last_pull', 0);
        if (!$force && $last_pull > 0 && (time() - $last_pull) < 120) {
            return 0;
        }

        $headers = array('X-CLEG-Source' => 'wordpress-procurement');
        if (CLEG_PROC_SHAREPOINT_SYNC_SECRET !== '') {
            $headers['X-CLEG-Sync-Secret'] = CLEG_PROC_SHAREPOINT_SYNC_SECRET;
        }

        $response = wp_remote_get($endpoint, array(
            'timeout' => 20,
            'headers' => $headers,
        ));

        update_option('cleg_procurement_agent_updates_last_pull', time(), false);

        if (is_wp_error($response)) {
            return $graph_added;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        if ($code < 200 || $code >= 300) {
            return $graph_added;
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);
        if (!is_array($body)) {
            return $graph_added;
        }

        $updates = cleg_procurement_updates_from_sharepoint_document($body, 'SharePoint endpoint');
        return $graph_added + cleg_procurement_store_agent_updates($updates);
    }
}

if (!function_exists('cleg_procurement_render_agent_update_action')) {
    function cleg_procurement_render_agent_update_action($update) {
        if (empty($update['id']) || empty($update['request_id']) || ($update['status'] ?? 'pending') !== 'pending') {
            return '<span class="cleg-proc-mini-status">Sin accion</span>';
