                <input type="hidden" name="request_id" value="<?php echo esc_attr($update['request_id']); ?>">
                <button class="cleg-proc-btn is-secondary" type="submit">Aplicar</button>
            </form>
            <form class="cleg-proc-agent-dismiss-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                <?php wp_nonce_field('cleg_proc_dismiss_agent_update_' . $update['id']); ?>
                <input type="hidden" name="action" value="cleg_proc_dismiss_agent_update">
