                <button class="cleg-proc-btn is-ghost" type="submit">Descartar</button>
            </form>
        </div>
        <?php
        return ob_get_clean();
    }
}

if (!function_exists('cleg_procurement_mark_agent_update')) {
    function cleg_procurement_mark_agent_update($update_id, $status) {
        $update_id = sanitize_key((string) $update_id);
        if ($update_id === '') {
            return;
        }

        $updates = cleg_procurement_all_pending_agent_updates();
        if (empty($updates[$update_id]) || !is_array($updates[$update_id])) {
            $updates[$update_id] = array(
                'id' => $update_id,
                'status' => 'pending',
            );
        }

        $status = sanitize_key($status);
        $closed_at = current_time('mysql');
        $updates[$update_id]['status'] = $status;
        $updates[$update_id]['closed_at'] = $closed_at;

        if ($status === 'applied') {
            $updates[$update_id]['applied_at'] = $closed_at;
        } elseif ($status === 'dismissed') {
            $updates[$update_id]['dismissed_at'] = $closed_at;
        }

        update_option('cleg_procurement_agent_updates_v1', $updates, false);
    }
}

if (!function_exists('cleg_procurement_handle_apply_agent_update')) {
    function cleg_procurement_handle_apply_agent_update() {
        if (!cleg_procurement_private_sync_enabled() || !is_user_logged_in() || !cleg_procurement_user_can_manage(wp_get_current_user())) {
            wp_die(esc_html__('Acceso restringido.', 'cleg'));
        }

        $update_id = sanitize_key((string) ($_POST['update_id'] ?? ''));
        $request_id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        check_admin_referer('cleg_proc_apply_agent_update_' . $update_id);

        $updates = cleg_procurement_all_pending_agent_updates();
        $update = isset($updates[$update_id]) ? cleg_procurement_normalize_agent_update($updates[$update_id]) : null;
        $data = cleg_procurement_get_data();

        if (!$update && !empty($data['requests'][$request_id])) {
            foreach (cleg_procurement_agent_update_candidates($data['requests'][$request_id]) as $candidate) {
                if (($candidate['id'] ?? '') === $update_id) {
                    $update = $candidate;
                    break;
                }
            }
        }

        if (!$update || $update['request_id'] !== $request_id) {
            wp_safe_redirect(add_query_arg(array('proc_view' => 'ia', 'proc_notice' => 'agent_update_missing'), home_url('/admin-procurement/')));
            exit;
        }

        if (empty($data['requests'][$request_id])) {
            wp_safe_redirect(add_query_arg(array('proc_view' => 'ia', 'proc_notice' => 'agent_update_missing'), home_url('/admin-procurement/')));
            exit;
        }

        $request = $data['requests'][$request_id];
        $payload = isset($update['payload']) && is_array($update['payload']) ? $update['payload'] : array();
        $note = $update['label'] . ': ' . $update['value'];
        $operation_key = cleg_procurement_operation_key('agent_update', 'apply', 'wordpress', $update_id, array(
            'request_id' => $request_id,
            'type' => $update['type'],
            'payload' => $payload,
        ));

        if (cleg_procurement_operation_is_done($operation_key)) {
            cleg_procurement_mark_agent_update($update_id, 'applied');
            wp_safe_redirect(add_query_arg(array('proc_view' => 'ia', 'proc_notice' => 'agent_update_applied'), home_url('/admin-procurement/')));
            exit;
        }

        if ($update['type'] === 'quote') {
            $quote = array(
                'id' => cleg_procurement_new_id('QUOTE'),
                'request_id' => $request_id,
                'vendor' => sanitize_text_field((string) ($payload['vendor'] ?? $request['incoming_vendor'] ?? 'Proveedor pendiente')),
                'contact' => sanitize_text_field((string) ($payload['contact'] ?? '')),
                'amount' => sanitize_text_field((string) ($payload['amount'] ?? $payload['quote_total'] ?? $update['value'])),
                'currency' => sanitize_text_field((string) ($payload['currency'] ?? 'USD')),
                'eta' => sanitize_text_field((string) ($payload['eta'] ?? $request['incoming_eta'] ?? '')),
                'estimated_delivery_to_pr' => sanitize_text_field((string) ($payload['estimated_delivery_to_pr'] ?? $payload['delivery_to_pr'] ?? '')),
                'can_meet_required_delivery_date' => sanitize_text_field((string) ($payload['can_meet_required_delivery_date'] ?? 'Unknown')),
                'expires' => sanitize_text_field((string) ($payload['expires'] ?? '')),
                'recommended' => sanitize_text_field((string) ($payload['recommended'] ?? 'no')),
                'delivery_risk_notes' => sanitize_textarea_field((string) ($payload['delivery_risk_notes'] ?? '')),
                'notes' => sanitize_textarea_field((string) ($payload['notes'] ?? $note)),
                'files' => $payload['files'] ?? $payload['file_urls'] ?? $payload['attachments'] ?? array(),
                'quote_status' => 'Received',
                'created_at' => current_time('mysql'),
            );

            $airtable_quote_id = cleg_procurement_add_airtable_quote($request, $quote);
            if ($airtable_quote_id) {
                $quote['airtable_id'] = is_string($airtable_quote_id) ? $airtable_quote_id : '';
                $data['requests'][$request_id]['status'] = 'Quotes Received';
            } elseif (($data['source'] ?? '') === 'airtable') {
                cleg_procurement_error_queue_add('airtable_quote_create_failed', 'No se pudo crear cotizacion en Airtable.', array(
                    'request_id' => $request_id,
                    'update_id' => $update_id,
                    'quote' => $quote,
                ));
                $data['source'] = 'wordpress';
            }
            if (!isset($data['quotes'][$request_id]) || !is_array($data['quotes'][$request_id])) {
                $data['quotes'][$request_id] = array();
            }
            $data['quotes'][$request_id][] = $quote;
            cleg_procurement_add_airtable_audit_event($request, 'Quote received', $note, $payload);
        } elseif ($update['type'] === 'history') {
            $files = array();
            foreach ((array) ($payload['files'] ?? $payload['file_urls'] ?? array()) as $file) {
                if (is_array($file) && !empty($file['url'])) {
                    $files[] = array('url' => esc_url_raw($file['url']));
                } elseif (is_string($file) && wp_http_validate_url($file)) {
                    $files[] = array('url' => esc_url_raw($file));
                }
            }

            $history = array(
                'id' => cleg_procurement_new_id('HIST'),
                'request_id' => $request_id,
                'vendor' => sanitize_text_field((string) ($payload['vendor'] ?? 'Proveedor pendiente')),
                'item' => sanitize_text_field((string) ($payload['item'] ?? $request['item'] ?? 'Item pendiente')),
                'price' => sanitize_text_field((string) ($payload['price'] ?? $payload['amount'] ?? '')),
                'currency' => sanitize_text_field((string) ($payload['currency'] ?? 'USD')),
                'lead_time' => sanitize_text_field((string) ($payload['lead_time'] ?? $payload['eta'] ?? '')),
                'reference' => sanitize_text_field((string) ($payload['reference'] ?? $payload['part_reference'] ?? $request_id)),
                'source_request' => sanitize_text_field((string) ($payload['source_request'] ?? $request_id)),
                'quote_date' => sanitize_text_field((string) ($payload['quote_date'] ?? current_time('Y-m-d'))),
                'notes' => sanitize_textarea_field((string) ($payload['notes'] ?? $note)),
                'files' => $files,
                'created_at' => current_time('mysql'),
            );

            $airtable_history_id = cleg_procurement_add_airtable_history($request, $history);
            if ($airtable_history_id) {
                $history['airtable_id'] = is_string($airtable_history_id) ? $airtable_history_id : '';
            } elseif (($data['source'] ?? '') === 'airtable') {
                cleg_procurement_error_queue_add('airtable_history_create_failed', 'No se pudo crear historico de proveedor en Airtable.', array(
                    'request_id' => $request_id,
                    'update_id' => $update_id,
                    'history' => $history,
                ));
                $data['source'] = 'wordpress';
            }

            if (empty($data['provider_history']) || !is_array($data['provider_history'])) {
                $data['provider_history'] = array();
            }
            $data['provider_history'][$history['id']] = $history;
        } else {
            if ($update['type'] === 'tracking') {
                $data['requests'][$request_id]['tracking_number'] = $update['value'];
                $note = 'Tracking recibido: ' . $update['value'];
                if (!empty($payload['carrier'])) {
                    $note .= ' | Carrier: ' . sanitize_text_field((string) $payload['carrier']);
                }
                if (!empty($payload['tracking_url'])) {
                    $note .= ' | URL: ' . esc_url_raw((string) $payload['tracking_url']);
                }
                $shipment_id = cleg_procurement_add_airtable_shipment($request, $update, $note);
                if ($shipment_id) {
                    $data['requests'][$request_id]['shipment_airtable_ids'][] = is_string($shipment_id) ? $shipment_id : '';
                } elseif (($data['source'] ?? '') === 'airtable') {
                    cleg_procurement_error_queue_add('airtable_shipment_create_failed', 'No se pudo crear shipment en Airtable.', array(
                        'request_id' => $request_id,
                        'update_id' => $update_id,
                        'update' => $update,
                    ));
                    $data['source'] = 'wordpress';
                }
                cleg_procurement_add_airtable_followup($request, $update, $note);
                cleg_procurement_add_airtable_audit_event($request, 'Tracking updated', $note, $payload);
            } elseif ($update['type'] === 'eta') {
                $data['requests'][$request_id]['eta'] = $update['value'];
                $note = 'ETA recibida: ' . $update['value'];
                $shipment_id = cleg_procurement_add_airtable_shipment($request, $update, $note);
                if ($shipment_id) {
                    $data['requests'][$request_id]['shipment_airtable_ids'][] = is_string($shipment_id) ? $shipment_id : '';
                } elseif (($data['source'] ?? '') === 'airtable') {
                    cleg_procurement_error_queue_add('airtable_shipment_create_failed', 'No se pudo crear shipment en Airtable.', array(
                        'request_id' => $request_id,
                        'update_id' => $update_id,
                        'update' => $update,
                    ));
                    $data['source'] = 'wordpress';
                }
                cleg_procurement_add_airtable_followup($request, $update, $note);
                cleg_procurement_add_airtable_audit_event($request, 'Tracking updated', $note, $payload);
            } elseif ($update['type'] === 'file') {
                $data['requests'][$request_id]['agent_files'][] = array(
                    'label' => $update['label'],
                    'value' => $update['value'],
                    'source' => $update['source'],
                    'received_at' => $update['received_at'],
                );
                $note = 'Archivo recibido: ' . $update['value'];
                cleg_procurement_add_airtable_followup($request, $update, $note);
                cleg_procurement_add_airtable_audit_event($request, 'Info requested', $note, $payload);
            } else {
                cleg_procurement_add_airtable_followup($request, $update, $note);
                cleg_procurement_add_airtable_audit_event($request, 'Status changed', $note, $payload);
            }

            if (!empty($request['airtable_id'])) {
                $status_updated = cleg_procurement_update_airtable_status($request, $request['status'] ?? 'Researching', $note);
                if (!$status_updated) {
                    cleg_procurement_error_queue_add('airtable_status_update_failed', 'No se pudo actualizar estado de solicitud en Airtable.', array(
                        'request_id' => $request_id,
                        'update_id' => $update_id,
                        'airtable_id' => $request['airtable_id'] ?? '',
                    ));
                }
            } elseif (($data['source'] ?? '') === 'airtable') {
                cleg_procurement_error_queue_add('airtable_request_link_missing', 'Solicitud Airtable sin airtable_id local al aplicar update.', array(
                    'request_id' => $request_id,
                    'update_id' => $update_id,
                ), false);
                $data['source'] = 'wordpress';
            }
        }

        $data['requests'][$request_id]['next_action'] = $note;
        $data['requests'][$request_id]['updated_at'] = current_time('mysql');
        cleg_procurement_add_audit($data, 'Actualizacion del asistente aplicada', $request_id, $note);
        cleg_procurement_mark_agent_update($update_id, 'applied');
        cleg_procurement_operation_record($operation_key, 'applied', array(
            'request_id' => $request_id,
            'update_id' => $update_id,
            'type' => $update['type'],
        ));
        cleg_procurement_save_data($data);

        wp_safe_redirect(add_query_arg(array('proc_view' => 'ia', 'proc_notice' => 'agent_update_applied'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_apply_agent_update', 'cleg_procurement_handle_apply_agent_update');

if (!function_exists('cleg_procurement_handle_dismiss_agent_update')) {
    function cleg_procurement_handle_dismiss_agent_update() {
        if (!cleg_procurement_private_sync_enabled() || !is_user_logged_in() || !cleg_procurement_user_can_manage(wp_get_current_user())) {
            wp_die(esc_html__('Acceso restringido.', 'cleg'));
        }

        $update_id = sanitize_key((string) ($_POST['update_id'] ?? ''));
        $request_id = sanitize_text_field(wp_unslash($_POST['request_id'] ?? ''));
        check_admin_referer('cleg_proc_dismiss_agent_update_' . $update_id);

        if ($update_id !== '') {
            $operation_key = cleg_procurement_operation_key('agent_update', 'dismiss', 'wordpress', $update_id, array(
                'request_id' => $request_id,
            ));

            if (cleg_procurement_operation_is_done($operation_key)) {
                cleg_procurement_mark_agent_update($update_id, 'dismissed');
                wp_safe_redirect(add_query_arg(array('proc_view' => 'ia', 'proc_notice' => 'agent_update_dismissed'), home_url('/admin-procurement/')));
                exit;
            }

            $updates = cleg_procurement_all_pending_agent_updates();
            if (empty($updates[$update_id])) {
                $updates[$update_id] = array(
                    'id' => $update_id,
                    'request_id' => $request_id,
                    'type' => 'note',
                    'label' => 'Actualizacion descartada',
                    'value' => 'Descartada manualmente',
                    'source' => 'WordPress',
                    'status' => 'pending',
                    'received_at' => current_time('mysql'),
                );
                update_option('cleg_procurement_agent_updates_v1', $updates, false);
            }

            cleg_procurement_mark_agent_update($update_id, 'dismissed');
            cleg_procurement_operation_record($operation_key, 'dismissed', array(
                'request_id' => $request_id,
                'update_id' => $update_id,
            ));
        }

        wp_safe_redirect(add_query_arg(array('proc_view' => 'ia', 'proc_notice' => 'agent_update_dismissed'), home_url('/admin-procurement/')));
        exit;
    }
}
add_action('admin_post_cleg_proc_dismiss_agent_update', 'cleg_procurement_handle_dismiss_agent_update');

if (!function_exists('cleg_procurement_sharepoint_graph_ready')) {
    function cleg_procurement_sharepoint_graph_ready() {
        if (!cleg_procurement_module_enabled() || !cleg_procurement_private_sync_enabled()) {
            return false;
        }

        return CLEG_PROC_SHAREPOINT_GRAPH_TENANT_ID !== ''
            && CLEG_PROC_SHAREPOINT_GRAPH_CLIENT_ID !== ''
            && CLEG_PROC_SHAREPOINT_GRAPH_CLIENT_SECRET !== ''
            && CLEG_PROC_SHAREPOINT_GRAPH_DRIVE_ID !== '';
    }
}

if (!function_exists('cleg_procurement_sharepoint_graph_token')) {
    function cleg_procurement_sharepoint_graph_token() {
        if (!cleg_procurement_sharepoint_graph_ready()) {
            return new WP_Error('cleg_procurement_sharepoint_graph_missing', 'Credenciales Graph no configuradas.');
        }

        $cached = get_transient('cleg_procurement_sharepoint_graph_token');
        if (is_string($cached) && $cached !== '') {
            return $cached;
        }

        $token_url = 'https://login.microsoftonline.com/' . rawurlencode(CLEG_PROC_SHAREPOINT_GRAPH_TENANT_ID) . '/oauth2/v2.0/token';
        $response = wp_remote_post($token_url, array(
            'timeout' => 20,
            'headers' => array(
                'Content-Type' => 'application/x-www-form-urlencoded',
            ),
            'body' => array(
                'client_id' => CLEG_PROC_SHAREPOINT_GRAPH_CLIENT_ID,
                'client_secret' => CLEG_PROC_SHAREPOINT_GRAPH_CLIENT_SECRET,
                'scope' => 'https://graph.microsoft.com/.default',
                'grant_type' => 'client_credentials',
            ),
        ));

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        if ($code < 200 || $code >= 300) {
            return new WP_Error('cleg_procurement_sharepoint_graph_auth_failed', 'Graph auth respondio HTTP ' . $code . '.');
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);
        $token = isset($body['access_token']) ? (string) $body['access_token'] : '';
        if ($token === '') {
            return new WP_Error('cleg_procurement_sharepoint_graph_token_missing', 'Graph no devolvio access_token.');
        }

        $ttl = isset($body['expires_in']) ? max(300, absint($body['expires_in']) - 120) : 3300;
        set_transient('cleg_procurement_sharepoint_graph_token', $token, $ttl);
        return $token;
    }
}

if (!function_exists('cleg_procurement_sharepoint_graph_upload_json')) {
    function cleg_procurement_sharepoint_graph_upload_json($file, $token) {
        if (!is_array($file) || empty($file['path'])) {
            return new WP_Error('cleg_procurement_sharepoint_file_missing', 'Archivo SharePoint sin ruta.');
        }

        $path = ltrim((string) $file['path'], '/');
        $body = wp_json_encode($file['body'] ?? array(), JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if (!is_string($body)) {
            return new WP_Error('cleg_procurement_sharepoint_file_encode_failed', 'No se pudo generar JSON para SharePoint.');
        }

        $upload_url = 'https://graph.microsoft.com/v1.0/drives/'
            . rawurlencode(CLEG_PROC_SHAREPOINT_GRAPH_DRIVE_ID)
            . '/root:/'
            . str_replace('%2F', '/', rawurlencode($path))
            . ':/content';

        $response = wp_remote_request($upload_url, array(
            'method' => 'PUT',
            'timeout' => 25,
            'headers' => array(
                'Authorization' => 'Bearer ' . $token,
                'Content-Type' => $file['content_type'] ?? 'application/json',
            ),
            'body' => $body,
        ));

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        if ($code < 200 || $code >= 300) {
            return new WP_Error('cleg_procurement_sharepoint_upload_failed', 'Graph upload respondio HTTP ' . $code . ' para ' . $path . '.');
        }

        return true;
    }
}

if (!function_exists('cleg_procurement_sharepoint_graph_json_request')) {
    function cleg_procurement_sharepoint_graph_json_request($url, $token) {
        $response = wp_remote_get($url, array(
            'timeout' => 25,
            'headers' => array(
                'Authorization' => 'Bearer ' . $token,
                'Accept' => 'application/json',
            ),
        ));

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        if ($code < 200 || $code >= 300) {
            return new WP_Error('cleg_procurement_sharepoint_graph_get_failed', 'Graph respondio HTTP ' . $code . '.');
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);
        if (!is_array($body)) {
            return new WP_Error('cleg_procurement_sharepoint_graph_json_invalid', 'Graph devolvio JSON invalido.');
        }

        return $body;
    }
}

if (!function_exists('cleg_procurement_sharepoint_graph_download_json')) {
    function cleg_procurement_sharepoint_graph_download_json($path, $token) {
        $path = ltrim((string) $path, '/');
        if ($path === '') {
            return new WP_Error('cleg_procurement_sharepoint_path_missing', 'Ruta SharePoint vacia.');
        }

        $url = 'https://graph.microsoft.com/v1.0/drives/'
            . rawurlencode(CLEG_PROC_SHAREPOINT_GRAPH_DRIVE_ID)
            . '/root:/'
            . str_replace('%2F', '/', rawurlencode($path))
            . ':/content';

        $response = wp_remote_get($url, array(
            'timeout' => 25,
            'headers' => array(
                'Authorization' => 'Bearer ' . $token,
                'Accept' => 'application/json',
            ),
        ));

        if (is_wp_error($response)) {
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        if ($code < 200 || $code >= 300) {
            return new WP_Error('cleg_procurement_sharepoint_download_failed', 'Graph download respondio HTTP ' . $code . ' para ' . $path . '.');
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);
        if (!is_array($body)) {
            return new WP_Error('cleg_procurement_sharepoint_download_invalid', 'Archivo incoming invalido: ' . $path . '.');
        }

        return $body;
    }
}

if (!function_exists('cleg_procurement_pull_agent_updates_from_sharepoint_graph')) {
    function cleg_procurement_pull_agent_updates_from_sharepoint_graph() {
        if (!cleg_procurement_sharepoint_graph_ready()) {
            return 0;
        }

        $token = cleg_procurement_sharepoint_graph_token();
        if (is_wp_error($token)) {
            cleg_procurement_error_queue_add('sharepoint_graph_token_failed', $token, array(
                'operation' => 'pull_agent_updates',
            ));
            return 0;
        }

        $folder = trim(CLEG_PROC_SHAREPOINT_INCOMING_PATH, '/');
        if ($folder === '') {
            return 0;
        }

        $list_url = 'https://graph.microsoft.com/v1.0/drives/'
            . rawurlencode(CLEG_PROC_SHAREPOINT_GRAPH_DRIVE_ID)
            . '/root:/'
            . str_replace('%2F', '/', rawurlencode($folder))
            . ':/children?$select=name,file,folder,lastModifiedDateTime,size';

        $listing = cleg_procurement_sharepoint_graph_json_request($list_url, $token);
        if (is_wp_error($listing) || empty($listing['value']) || !is_array($listing['value'])) {
            cleg_procurement_error_queue_add('sharepoint_graph_list_failed', is_wp_error($listing) ? $listing : 'Listado SharePoint vacio o invalido.', array(
                'operation' => 'pull_agent_updates',
                'folder' => $folder,
            ));
            return 0;
        }

        $processed = get_option('cleg_procurement_processed_incoming_files_v1', array());
        $processed = is_array($processed) ? $processed : array();
        $incoming = array();

        foreach ($listing['value'] as $item) {
            $name = sanitize_file_name((string) ($item['name'] ?? ''));
            if ($name === '' || substr($name, -5) !== '.json') {
                continue;
            }

            $file_key = sanitize_key($name . '-' . ($item['lastModifiedDateTime'] ?? '') . '-' . ($item['size'] ?? ''));
            if (isset($processed[$file_key])) {
                continue;
            }

            $document = cleg_procurement_sharepoint_graph_download_json($folder . '/' . $name, $token);
            if (is_wp_error($document)) {
                cleg_procurement_error_queue_add('sharepoint_graph_download_failed', $document, array(
                    'operation' => 'pull_agent_updates',
                    'file' => $name,
                ));
                continue;
            }

            $updates = cleg_procurement_updates_from_sharepoint_document($document, 'SharePoint: ' . $name);
            if ($updates) {
                $incoming = array_merge($incoming, $updates);
            }

            $processed[$file_key] = current_time('mysql');
        }

        if ($incoming) {
            update_option('cleg_procurement_processed_incoming_files_v1', array_slice($processed, -300, null, true), false);
            return cleg_procurement_store_agent_updates($incoming);
        }

        return 0;
    }
}

if (!function_exists('cleg_procurement_write_agent_export_to_sharepoint')) {
    function cleg_procurement_write_agent_export_to_sharepoint($payload) {
        if (!cleg_procurement_sharepoint_graph_ready()) {
            return new WP_Error('cleg_procurement_sharepoint_graph_missing', 'Credenciales Graph no configuradas.');
        }

        $files = isset($payload['sharepoint_files']) && is_array($payload['sharepoint_files']) ? $payload['sharepoint_files'] : array();
        if (!$files) {
            return new WP_Error('cleg_procurement_sharepoint_files_missing', 'El paquete no contiene archivos canonicos.');
        }

        $token = cleg_procurement_sharepoint_graph_token();
        if (is_wp_error($token)) {
            cleg_procurement_error_queue_add('sharepoint_graph_token_failed', $token, array(
                'operation' => 'write_agent_export',
            ));
            return $token;
        }

        $written = 0;
        foreach ($files as $file) {
            $result = cleg_procurement_sharepoint_graph_upload_json($file, $token);
            if (is_wp_error($result)) {
                cleg_procurement_error_queue_add('sharepoint_graph_upload_failed', $result, array(
                    'operation' => 'write_agent_export',
                    'path' => $file['path'] ?? '',
                ));
                return $result;
            }
            $written++;
        }

        update_option('cleg_procurement_last_sharepoint_sync', array(
            'synced_at' => current_time('mysql'),
            'written_files' => $written,
            'requests_path' => CLEG_PROC_SHAREPOINT_REQUESTS_PATH,
        ), false);

        return $written;
    }
}

if (!function_exists('cleg_procurement_send_agent_export_to_endpoint')) {
    function cleg_procurement_send_agent_export_to_endpoint($payload) {
        if (!cleg_procurement_module_enabled()) {
            return new WP_Error('cleg_procurement_module_disabled', 'Compras no esta activo para este tenant.');
        }

        if (!cleg_procurement_private_sync_enabled()) {
            return new WP_Error('cleg_procurement_private_sync_disabled', 'Extension privada de sincronizacion desactivada.');
        }

        if (cleg_procurement_sharepoint_graph_ready()) {
            return cleg_procurement_write_agent_export_to_sharepoint($payload);
        }

        $endpoint = trim((string) CLEG_PROC_SHAREPOINT_SYNC_ENDPOINT);
        if ($endpoint === '' || !wp_http_validate_url($endpoint)) {
            return new WP_Error('cleg_procurement_sharepoint_endpoint_missing', 'Endpoint de sincronizacion SharePoint no configurado.');
        }

        $headers = array(
            'Content-Type' => 'application/json; charset=utf-8',
            'X-CLEG-Source' => 'wordpress-procurement',
        );

        if (CLEG_PROC_SHAREPOINT_SYNC_SECRET !== '') {
            $headers['X-CLEG-Sync-Secret'] = CLEG_PROC_SHAREPOINT_SYNC_SECRET;
        }

        $response = wp_remote_post($endpoint, array(
            'timeout' => 25,
            'headers' => $headers,
            'body' => wp_json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
        ));

        if (is_wp_error($response)) {
            cleg_procurement_error_queue_add('sharepoint_endpoint_post_failed', $response, array(
                'operation' => 'send_agent_export',
                'endpoint' => $endpoint,
            ));
            return $response;
        }

        $code = (int) wp_remote_retrieve_response_code($response);
        if ($code < 200 || $code >= 300) {
            $error = new WP_Error('cleg_procurement_sharepoint_endpoint_failed', 'Endpoint SharePoint respondio HTTP ' . $code . '.');
            cleg_procurement_error_queue_add('sharepoint_endpoint_http_failed', $error, array(
                'operation' => 'send_agent_export',
                'endpoint' => $endpoint,
                'http_code' => $code,
            ));
            return $error;
        }

        return true;
    }
}

if (!function_exists('cleg_procurement_download_agent_export')) {
    function cleg_procurement_download_agent_export() {
        if (!cleg_procurement_private_sync_enabled() || !is_user_logged_in() || !cleg_procurement_user_can_internal_ai(wp_get_current_user())) {
            wp_die(esc_html__('Acceso restringido.', 'cleg'));
        }

        check_admin_referer('cleg_procurement_agent_export');

        $data = cleg_procurement_get_data();
        $payload = cleg_procurement_agent_export_payload($data);
        cleg_procurement_pull_agent_updates_from_endpoint(true);

        if (cleg_procurement_sharepoint_graph_ready() || CLEG_PROC_SHAREPOINT_SYNC_ENDPOINT !== '') {
            $sent = cleg_procurement_send_agent_export_to_endpoint($payload);
            wp_safe_redirect(add_query_arg(array(
                'proc_view' => 'ia',
                'proc_notice' => is_wp_error($sent) ? 'agent_sync_failed' : 'agent_sync_success',
            ), home_url('/admin-procurement/')));
            exit;
        }

        nocache_headers();
        header('Content-Type: application/json; charset=utf-8');
        header('Content-Disposition: attachment; filename="agente-compras-industriales-' . gmdate('Y-m-d-His') . '.json"');
        echo wp_json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        exit;
    }
}
add_action('admin_post_cleg_procurement_download_agent_export', 'cleg_procurement_download_agent_export');

