                <?php if (!$queue) : ?>
                    <div class="cleg-proc-empty"><strong>Sin tareas del asistente</strong><p>Las solicitudes activas tienen clasificacion suficiente por ahora.</p></div>
                <?php endif; ?>
            </div>
        </section>
        <?php
        return ob_get_clean();
    }
}

if (!function_exists('cleg_procurement_history_scalar')) {
    function cleg_procurement_history_scalar($fields, $names, $default = '') {
        foreach ((array) $names as $name) {
            $value = cleg_procurement_airtable_scalar($fields, $name, null);
            if ($value !== null && $value !== '') {
                return $value;
            }
        }

        return $default;
    }
}

if (!function_exists('cleg_procurement_history_row_key_from_parts')) {
    function cleg_procurement_history_row_key_from_parts($source, $record_id = '', $provider_index = '', $request_id = '', $quote_index = '') {
        $raw = implode('|', array(
            sanitize_key((string) $source),
            sanitize_text_field((string) $record_id),
            sanitize_text_field((string) $provider_index),
            sanitize_text_field((string) $request_id),
            sanitize_text_field((string) $quote_index),
        ));

        return md5($raw);
    }
}

if (!function_exists('cleg_procurement_history_row_key')) {
    function cleg_procurement_history_row_key($row) {
        return cleg_procurement_history_row_key_from_parts(
            (string) ($row['_history_source'] ?? ''),
            (string) ($row['_history_id'] ?? ''),
            (string) ($row['_provider_index'] ?? ''),
            (string) ($row['_request_id'] ?? ''),
            (string) ($row['_quote_index'] ?? '')
        );
    }
}

if (!function_exists('cleg_procurement_apply_history_local_state')) {
    function cleg_procurement_apply_history_local_state($rows, $data) {
        $hidden = isset($data['history_hidden']) && is_array($data['history_hidden']) ? $data['history_hidden'] : array();
        $overrides = isset($data['history_overrides']) && is_array($data['history_overrides']) ? $data['history_overrides'] : array();
        $clean = array();

        foreach ($rows as $row) {
            if (!is_array($row)) {
                continue;
            }

            $key = cleg_procurement_history_row_key($row);
            if ($key !== '' && !empty($hidden[$key])) {
                continue;
            }

            if ($key !== '' && isset($overrides[$key]) && is_array($overrides[$key])) {
                $row = wp_parse_args($overrides[$key], $row);
                $row['_history_local_override'] = 'yes';
            }

            $row['_history_key'] = $key;
            $clean[] = $row;
        }

        return $clean;
    }
}

if (!function_exists('cleg_procurement_provider_history_key_from_quote')) {
    function cleg_procurement_provider_history_key_from_quote($request, $quote) {
        $quote_id = trim((string) ($quote['airtable_id'] ?? ''));
        if ($quote_id === '') {
            $quote_id = trim((string) ($quote['id'] ?? ''));
        }

        if ($quote_id !== '') {
            return 'QUOTE-HIST-' . md5('quote|' . strtolower($quote_id));
        }

        $request_id = trim((string) ($request['id'] ?? ''));
        $vendor_key = sanitize_title((string) ($quote['vendor'] ?? ''));
        $item_key = sanitize_title((string) ($request['item'] ?? ($quote['item'] ?? '')));

        return 'QUOTE-HIST-' . md5(strtolower($request_id . '|' . $vendor_key . '|' . $item_key));
    }
}

if (!function_exists('cleg_procurement_provider_history_notes_from_quote')) {
    function cleg_procurement_provider_history_notes_from_quote($request, $quote) {
        $parts = array();
        $contact = trim(implode(' · ', array_filter(array(
            (string) ($quote['supplier_contact_person'] ?? ''),
            (string) ($quote['supplier_contact_email'] ?? ''),
            (string) ($quote['supplier_contact_phone'] ?? ''),
        ))));

        $summary_fields = array(
            'Proveedor' => (string) ($quote['vendor'] ?? ''),
            'Contacto' => $contact,
            'Estado cotizacion' => (string) ($quote['quote_status'] ?? ''),
            'Monto' => trim((string) ($quote['currency'] ?? 'USD') . ' ' . (string) ($quote['amount'] ?? '')),
            'Lead time / ETA' => (string) (($quote['estimated_delivery_to_pr'] ?? '') ?: ($quote['eta'] ?? '')),
            'Fecha requerida' => (string) ($request['required_date'] ?? ''),
            'Puede cumplir fecha' => (string) ($quote['can_meet_required_delivery_date'] ?? ''),
            'Solicitud' => (string) ($request['id'] ?? ''),
        );

        foreach ($summary_fields as $label => $value) {
            $value = trim($value);
            if ($value !== '') {
                $parts[] = $label . ': ' . $value;
            }
        }

        foreach (array('notes' => 'Notas', 'delivery_risk_notes' => 'Riesgo/entrega', 'decision_support_notes' => 'Decision', 'why_recommended' => 'Motivo recomendado') as $key => $label) {
            $value = trim((string) ($quote[$key] ?? ''));
            if ($value !== '') {
                $parts[] = $label . ': ' . $value;
            }
        }

        return implode("\n", array_values(array_unique($parts)));
    }
}

if (!function_exists('cleg_procurement_history_merge_notes')) {
    function cleg_procurement_history_merge_notes($primary, $secondary) {
        $parts = array();
        foreach (array($primary, $secondary) as $notes) {
            foreach (preg_split('/\r\n|\r|\n/', (string) $notes) as $line) {
                $line = trim($line);
                if ($line !== '') {
                    $parts[] = $line;
                }
            }
        }

        return implode("\n", array_values(array_unique($parts)));
    }
}

if (!function_exists('cleg_procurement_history_dedupe_key')) {
    function cleg_procurement_history_dedupe_key($row) {
        $quote_id = trim((string) ($row['_quote_airtable_id'] ?? $row['quote_airtable_id'] ?? ''));
        if ($quote_id === '') {
            $quote_id = trim((string) ($row['_history_id'] ?? ''));
            if (!in_array((string) ($row['_history_source'] ?? ''), array('airtable_quote', 'local_quote'), true)) {
                $quote_id = '';
            }
        }

        if ($quote_id !== '') {
            return 'quote|' . strtolower($quote_id);
        }

        return 'vendor|' . sanitize_key(
            (string) ($row['vendor'] ?? '') . '|' .
            (string) ($row['item'] ?? '') . '|' .
            (string) ($row['reference'] ?? '')
        );
    }
}

if (!function_exists('cleg_procurement_merge_history_rows')) {
    function cleg_procurement_merge_history_rows($base, $incoming) {
        foreach ($incoming as $key => $value) {
            if ($key === 'files') {
                $base['files'] = cleg_procurement_dedupe_attachments(array_merge((array) ($base['files'] ?? array()), (array) $value));
                continue;
            }
            if ($key === 'notes') {
                $base['notes'] = cleg_procurement_history_merge_notes($base['notes'] ?? '', $value);
                continue;
            }
            if (($base[$key] ?? '') === '' && $value !== '') {
                $base[$key] = $value;
            }
        }

        return $base;
    }
}

if (!function_exists('cleg_procurement_upsert_provider_history_from_quote')) {
    function cleg_procurement_upsert_provider_history_from_quote(&$data, $request, $quote) {
        if (!is_array($request) || !is_array($quote)) {
            return;
        }

        $vendor = trim((string) ($quote['vendor'] ?? ''));
        if ($vendor === '') {
            return;
        }

        if (!isset($data['provider_history']) || !is_array($data['provider_history'])) {
            $data['provider_history'] = array();
        }

        $request_id = (string) ($request['id'] ?? '');
        $history_key = cleg_procurement_provider_history_key_from_quote($request, $quote);
        $legacy_key = 'QUOTE-HIST-' . md5(strtolower($request_id . '|' . $vendor . '|' . (string) ($request['item'] ?? '') . '|' . (string) ($quote['amount'] ?? '')));
        if ($legacy_key !== $history_key && isset($data['provider_history'][$legacy_key]) && is_array($data['provider_history'][$legacy_key])) {
            $data['provider_history'][$history_key] = wp_parse_args($data['provider_history'][$history_key] ?? array(), $data['provider_history'][$legacy_key]);
            unset($data['provider_history'][$legacy_key]);
        }
        $existing = isset($data['provider_history'][$history_key]) && is_array($data['provider_history'][$history_key]) ? $data['provider_history'][$history_key] : array();

        $data['provider_history'][$history_key] = wp_parse_args(array(
            'id' => $history_key,
            'quote_airtable_id' => (string) ($quote['airtable_id'] ?? ''),
            'quote_id' => (string) ($quote['id'] ?? ''),
            'vendor' => $vendor,
            'item' => (string) ($request['item'] ?? ($quote['item'] ?? 'Item pendiente')),
            'price' => (string) ($quote['amount'] ?? ''),
            'currency' => (string) ($quote['currency'] ?? 'USD'),
            'lead_time' => (string) ($quote['eta'] ?? ''),
            'reference' => $request_id,
            'source_request' => $request_id,
            'quote_status' => (string) ($quote['quote_status'] ?? ''),
            'supplier_contact_person' => (string) ($quote['supplier_contact_person'] ?? ''),
            'supplier_contact_email' => (string) ($quote['supplier_contact_email'] ?? ''),
            'supplier_contact_phone' => (string) ($quote['supplier_contact_phone'] ?? ''),
            'estimated_delivery_to_pr' => (string) ($quote['estimated_delivery_to_pr'] ?? ''),
            'can_meet_required_delivery_date' => (string) ($quote['can_meet_required_delivery_date'] ?? ''),
            'delivery_risk_notes' => (string) ($quote['delivery_risk_notes'] ?? ''),
            'decision_support_notes' => (string) ($quote['decision_support_notes'] ?? ''),
            'quote_date' => (string) ($quote['created_at'] ?? current_time('mysql')),
            'notes' => cleg_procurement_provider_history_notes_from_quote($request, $quote),
            'files' => isset($quote['files']) && is_array($quote['files']) ? cleg_procurement_dedupe_attachments($quote['files']) : array(),
            'updated_at' => current_time('mysql'),
        ), $existing);
    }
}

if (!function_exists('cleg_procurement_history_rows_from_airtable')) {
    function cleg_procurement_history_rows_from_airtable() {
        if (!cleg_procurement_airtable_ready()) {
            return array();
        }

        $records = cleg_admin_records(CLEG_PROC_AIRTABLE_HISTORY_TABLE, array('pageSize' => 100));
        if (is_wp_error($records) || !is_array($records)) {
            return array();
        }

        $rows = array();
        foreach ($records as $record) {
            $fields = isset($record['fields']) && is_array($record['fields']) ? $record['fields'] : array();
            $vendor = cleg_procurement_history_scalar($fields, array('Last Vendor Snapshot', 'Vendor', 'Supplier', 'Provider', 'Proveedor', 'Vendor Name', 'Vendor Name Snapshot'), '');
            $item = cleg_procurement_history_scalar($fields, array('Product / Equipment Name', 'Item', 'Item Description', 'Item / Part', 'Product / Item', 'Quoted Item / Scope', 'Part Number'), '');
            $price = cleg_procurement_history_scalar($fields, array('Last Quoted Price', 'Price', 'Unit Price', 'Quote Amount', 'Quoted Price', 'Last Price'), '');

            if ($vendor === '' && $item === '' && $price === '') {
                continue;
            }

            $rows[] = array(
                '_history_source' => 'airtable_history',
                '_history_id' => sanitize_text_field((string) ($record['id'] ?? '')),
                'vendor' => $vendor ?: 'Proveedor pendiente',
                'item' => $item ?: 'Item pendiente',
                'price' => $price,
                'currency' => cleg_procurement_history_scalar($fields, array('Currency', 'Moneda'), 'USD'),
                'reference' => cleg_procurement_history_scalar($fields, array('Model / Part Number', 'Reference', 'Reference Code', 'Part Reference', 'Manufacturer Reference', 'Request Code', 'RFQ'), ''),
                'lead_time' => cleg_procurement_history_scalar($fields, array('Typical Lead Time', 'Lead Time', 'ETA', 'Delivery Time'), ''),
                'source' => cleg_procurement_history_scalar($fields, array('Source', 'Source Request', 'Request Code'), 'Airtable History'),
                'date' => cleg_procurement_history_scalar($fields, array('Last Quote Date', 'Quote Date', 'Created Date', 'Date'), ''),
                'notes' => cleg_procurement_history_scalar($fields, array('Usage Notes', 'Specs Summary', 'Notes', 'Recommendation Reason', 'Delivery Risk Notes'), ''),
                'files' => cleg_procurement_dedupe_attachments(array_merge(
                    cleg_procurement_airtable_attachment_urls($fields, 'Attachments'),
                    cleg_procurement_airtable_attachment_urls($fields, 'Files'),
                    cleg_procurement_airtable_attachment_urls($fields, 'Documents / Datasheets')
                )),
            );
        }

        return $rows;
    }
}

