if (!function_exists('cleg_procurement_history_rows')) {
    function cleg_procurement_history_rows($data) {
        $rows = cleg_procurement_history_rows_from_airtable();
        $rows = array_merge($rows, cleg_procurement_history_rows_from_airtable_quotes());
        $rows = array_merge($rows, cleg_procurement_history_rows_from_airtable_vendors());
        $requests = isset($data['requests']) && is_array($data['requests']) ? $data['requests'] : array();
        $quotes = isset($data['quotes']) && is_array($data['quotes']) ? $data['quotes'] : array();
        $provider_history = isset($data['provider_history']) && is_array($data['provider_history']) ? $data['provider_history'] : array();

        foreach ($provider_history as $history_index => $history) {
            if (!is_array($history)) {
                continue;
            }

            $rows[] = array(
                '_history_source' => 'local_provider_history',
                '_history_id' => (string) ($history['id'] ?? $history_index),
                '_provider_index' => (string) $history_index,
                '_quote_airtable_id' => (string) ($history['quote_airtable_id'] ?? ''),
                'vendor' => (string) ($history['vendor'] ?? 'Proveedor pendiente'),
                'item' => (string) ($history['item'] ?? 'Item pendiente'),
                'price' => (string) ($history['price'] ?? ''),
                'currency' => (string) ($history['currency'] ?? 'USD'),
                'reference' => (string) ($history['reference'] ?? $history['source_request'] ?? ''),
                'lead_time' => (string) ($history['lead_time'] ?? ''),
                'source' => 'Actualizacion aprobada',
                'date' => (string) ($history['quote_date'] ?? $history['created_at'] ?? ''),
                'notes' => (string) ($history['notes'] ?? ''),
                'quote_status' => (string) ($history['quote_status'] ?? ''),
                'supplier_contact_person' => (string) ($history['supplier_contact_person'] ?? ''),
                'supplier_contact_email' => (string) ($history['supplier_contact_email'] ?? ''),
                'supplier_contact_phone' => (string) ($history['supplier_contact_phone'] ?? ''),
                'files' => isset($history['files']) && is_array($history['files']) ? cleg_procurement_dedupe_attachments($history['files']) : array(),
            );
        }

        foreach ($quotes as $request_id => $request_quotes) {
            if (!is_array($request_quotes)) {
                continue;
            }

            $request = isset($requests[$request_id]) && is_array($requests[$request_id]) ? $requests[$request_id] : array();
            foreach ($request_quotes as $quote_index => $quote) {
                if (!is_array($quote) || (($quote['voided'] ?? '') === 'yes')) {
                    continue;
                }

                $files = array();
                if (!empty($quote['files']) && is_array($quote['files'])) {
                    $files = cleg_procurement_dedupe_attachments($quote['files']);
                }

                $rows[] = array(
                    '_history_source' => 'local_quote',
                    '_history_id' => (string) ($quote['id'] ?? ($request_id . '-' . $quote_index)),
                    '_quote_airtable_id' => (string) ($quote['airtable_id'] ?? ''),
                    '_request_id' => (string) $request_id,
                    '_quote_index' => (int) $quote_index,
                    'vendor' => (string) ($quote['vendor'] ?? 'Proveedor pendiente'),
                    'item' => (string) ($request['item'] ?? ($quote['item'] ?? 'Item pendiente')),
                    'price' => (string) ($quote['amount'] ?? ''),
                    'currency' => 'USD',
                    'reference' => (string) $request_id,
                    'lead_time' => (string) ($quote['eta'] ?? ''),
                    'source' => 'Cotizacion',
                    'date' => (string) ($quote['created_at'] ?? $quote['expires'] ?? ''),
                    'notes' => cleg_procurement_provider_history_notes_from_quote($request, $quote),
                    'quote_status' => (string) ($quote['quote_status'] ?? ''),
                    'supplier_contact_person' => (string) ($quote['supplier_contact_person'] ?? ''),
                    'supplier_contact_email' => (string) ($quote['supplier_contact_email'] ?? ''),
                    'supplier_contact_phone' => (string) ($quote['supplier_contact_phone'] ?? ''),
                    'files' => $files,
                );
            }
        }

        $rows = cleg_procurement_apply_history_local_state($rows, $data);

        $unique = array();
        foreach ($rows as $row) {
            if (!is_array($row)) {
                continue;
            }
            $key = cleg_procurement_history_dedupe_key($row);
            if ($key === '') {
                $key = md5(wp_json_encode($row));
            }
            if (!isset($unique[$key])) {
                $unique[$key] = $row;
            } else {
                $unique[$key] = cleg_procurement_merge_history_rows($unique[$key], $row);
            }
        }

        $rows = array_values($unique);

        uasort($rows, function ($a, $b) {
            $vendor_compare = strcasecmp((string) ($a['vendor'] ?? ''), (string) ($b['vendor'] ?? ''));
            if ($vendor_compare !== 0) {
                return $vendor_compare;
            }

            return strcasecmp((string) ($a['item'] ?? ''), (string) ($b['item'] ?? ''));
        });

        return array_values($rows);
    }
}

if (!function_exists('cleg_procurement_render_provider_history_panel')) {
    function cleg_procurement_render_provider_history_panel($data, $base_url, $detail_url = '', $show_ai = true) {
        $query = sanitize_text_field(wp_unslash($_GET['proc_history_q'] ?? ''));
        $rows = cleg_procurement_history_rows($data);

        if ($query !== '') {
            $needle = strtolower(remove_accents($query));
            $rows = array_values(array_filter($rows, function ($row) use ($needle) {
                $haystack = strtolower(remove_accents(implode(' ', array(
                    $row['vendor'] ?? '',
                    $row['item'] ?? '',
                    $row['reference'] ?? '',
                    $row['notes'] ?? '',
                ))));
                return strpos($haystack, $needle) !== false;
            }));
        }
        $history_filters_open = $query !== '';

        $grouped = array();
        foreach ($rows as $row) {
            $vendor = trim((string) ($row['vendor'] ?? 'Proveedor pendiente'));
            if ($vendor === '') {
                $vendor = 'Proveedor pendiente';
            }
            $grouped[$vendor][] = $row;
        }

        ob_start();
        ?>
        <section class="cleg-proc-panel cleg-proc-history-panel">
            <div class="cleg-proc-panel-head">
                <div>
                    <h2>Historico de proveedores</h2>
                </div>
                <span class="cleg-proc-badge is-neutral"><?php echo esc_html((string) count($rows)); ?> registros</span>
                <?php echo cleg_procurement_render_mobile_menu('historial', $base_url, $detail_url, $show_ai); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            </div>
            <details class="cleg-proc-filterbox cleg-proc-history-create" id="nuevo-historico">
                <summary>Crear nuevo <span>registro manual</span></summary>
                <form class="cleg-proc-history-new-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                    <input type="hidden" name="action" value="cleg_proc_create_history_row">
                    <?php wp_nonce_field('cleg_procurement_create_history_row'); ?>
                    <label>Proveedor
                        <input type="text" name="vendor" required placeholder="Ej. Grainger">
                    </label>
                    <label>Item
                        <input type="text" name="item" required placeholder="Ej. Siemens 3RB3113">
                    </label>
                    <label>Precio
                        <input type="text" name="price" placeholder="Pendiente">
                    </label>
                    <label>Moneda
                        <input type="text" name="currency" value="USD">
                    </label>
