if (!function_exists('cleg_admin_procurement_shortcode')) {
    function cleg_admin_procurement_shortcode() {
        if (!is_user_logged_in()) {
            return '<section class="cleg-procurement"><div class="cleg-proc-empty"><h2>Compras</h2><p>Inicia sesion para entrar al modulo.</p><a class="cleg-proc-btn" href="' . esc_url(add_query_arg('cleg_redirect', rawurlencode('/admin-procurement/'), home_url('/acceso/'))) . '">Ir a acceso</a></div>' . cleg_procurement_styles() . '</section>';
        }

        if (!cleg_procurement_user_can_access()) {
            return '<section class="cleg-procurement"><div class="cleg-proc-empty"><h2>Acceso restringido</h2><p>Este modulo esta disponible solo para Luis, Alejandro y usuarios autorizados de procurement.</p></div>' . cleg_procurement_styles() . '</section>';
        }

        $data = cleg_procurement_get_data();
        $user = wp_get_current_user();
        $show_ai = cleg_procurement_user_can_internal_ai($user);
        $show_all_requests = cleg_procurement_user_can_view_all_requests($user);
        $show_history = $show_all_requests;
        $all_requests = isset($data['requests']) && is_array($data['requests']) ? $data['requests'] : array();
        $requests = cleg_procurement_filter_requests_for_user($all_requests, $user);
        $scoped_data = $data;
        $scoped_data['requests'] = $requests;
        $selected_id = cleg_procurement_selected_request($scoped_data);
        $selected = $selected_id && isset($requests[$selected_id]) ? $requests[$selected_id] : null;
        $statuses = cleg_procurement_statuses();
        $view = sanitize_key(wp_unslash($_GET['proc_view'] ?? ''));
        if (!in_array($view, array('solicitar', 'pendientes', 'canceladas', 'detalle', 'ia', 'historial'), true)) {
            $view = sanitize_text_field(wp_unslash($_GET['proc_request'] ?? '')) ? 'detalle' : 'pendientes';
        }
        if ($view === 'ia' && !$show_ai) {
            $view = 'pendientes';
        }
        if ($view === 'historial' && !$show_history) {
            $view = 'pendientes';
        }
        $stage_definitions = cleg_procurement_stage_definitions();
        $stage = sanitize_key(wp_unslash($_GET['proc_stage'] ?? 'all'));
        if ($view === 'canceladas') {
            $stage = 'cancelled';
            $view = 'pendientes';
        }
        if (!isset($stage_definitions[$stage])) {
            $stage = 'all';
        }
        $base_url = home_url('/admin-procurement/');
        $detail_url = $selected_id ? add_query_arg(array('proc_view' => 'detalle', 'proc_request' => rawurlencode((string) $selected_id)), $base_url) : add_query_arg('proc_view', 'pendientes', $base_url);
        $filters = array(
            'q' => sanitize_text_field(wp_unslash($_GET['proc_q'] ?? '')),
            'priority' => sanitize_text_field(wp_unslash($_GET['proc_priority'] ?? '')),
            'status' => sanitize_text_field(wp_unslash($_GET['proc_status'] ?? '')),
            'order_state' => sanitize_key(wp_unslash($_GET['proc_order_state'] ?? '')),
        );
        $filters_open = $filters['q'] || $filters['priority'] || $filters['status'] || $filters['order_state'];
        $active_requests = array_filter($requests, function ($request) {
            return !cleg_procurement_request_is_cancelled($request);
        });
        $cancelled_requests = array_filter($requests, function ($request) {
            return cleg_procurement_request_is_cancelled($request);
        });
        $board_source = cleg_procurement_stage_requests($requests, $stage);
        $board_filters = $filters;
        if ($stage === 'cancelled') {
            $board_filters['status'] = '';
        }
        $board_requests = cleg_procurement_sort_requests(cleg_procurement_filter_requests($board_source, $board_filters, $scoped_data));
        $priority_options = array('Normal', 'Alta', 'Urgente', 'Detiene trabajo hoy');
        $order_filter_options = cleg_procurement_order_filter_options();
        $board_column_options = cleg_procurement_board_column_options();
        $board_columns = cleg_procurement_selected_board_columns();
        $board_grid_template = cleg_procurement_board_grid_template($board_columns);

        $requests = cleg_procurement_sort_requests($requests);
        $logout_url = wp_logout_url(home_url('/acceso/'));
        $attention_count = cleg_procurement_stage_count($requests, 'pre_po');

        ob_start();
        ?>
        <section class="cleg-procurement cleg-proc-view-<?php echo esc_attr($view); ?> cleg-proc-stage-<?php echo esc_attr($stage); ?>" aria-label="CLEG Compras">
            <?php echo cleg_procurement_styles(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            <?php echo cleg_procurement_upload_preview_script(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            <div class="cleg-proc-app">
                <aside class="cleg-proc-sidebar" aria-label="Navegacion Compras">
                    <div class="cleg-proc-brand">
                        <small>Vantrexor</small>
                        <strong>Compras</strong>
                    </div>
                    <nav class="cleg-proc-nav">
                        <a class="<?php echo esc_attr($view === 'pendientes' ? 'is-active' : ''); ?>" href="<?php echo esc_url(add_query_arg(array('proc_view' => 'pendientes', 'proc_stage' => 'all'), $base_url)); ?>">Bandeja de entrada</a>
                        <a class="<?php echo esc_attr($view === 'solicitar' ? 'is-active' : ''); ?>" href="<?php echo esc_url(add_query_arg('proc_view', 'solicitar', $base_url)); ?>">Nueva solicitud</a>
                        <a href="<?php echo esc_url(home_url('/admin-recibos/')); ?>">Recibos</a>
                        <?php if ($show_history) : ?>
                            <a class="<?php echo esc_attr($view === 'historial' ? 'is-active' : ''); ?>" href="<?php echo esc_url(add_query_arg('proc_view', 'historial', $base_url)); ?>">Historico</a>
                        <?php endif; ?>
                        <?php if ($show_ai) : ?>
                            <a class="<?php echo esc_attr($view === 'ia' ? 'is-active' : ''); ?>" href="<?php echo esc_url(add_query_arg('proc_view', 'ia', $base_url)); ?>">Asistente</a>
