if (!function_exists('cleg_procurement_render_standalone_page')) {
    function cleg_procurement_render_standalone_page() {
        if (!cleg_procurement_is_page_request()) {
            return;
        }

        if (!is_user_logged_in()) {
            wp_safe_redirect(add_query_arg('cleg_redirect', rawurlencode('/admin-procurement/'), home_url('/acceso/')));
            exit;
        }

        show_admin_bar(false);
        status_header(200);
        nocache_headers();
        ?>
        <!doctype html>
        <html <?php language_attributes(); ?>>
        <head>
            <meta charset="<?php bloginfo('charset'); ?>">
            <meta name="viewport" content="width=device-width, initial-scale=1">
            <title>Compras - Vantrexor</title>
            <?php wp_head(); ?>
            <style id="cleg-procurement-critical-reset">
                html{margin-top:0!important;padding-top:0!important}
                body.cleg-procurement-standalone{margin:0!important;padding:0!important}
            </style>
        </head>
        <body <?php body_class('cleg-procurement-standalone'); ?>>
            <?php echo do_shortcode('[cleg_admin_procurement]'); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
            <?php wp_footer(); ?>
        </body>
        </html>
        <?php
        exit;
    }
}
add_action('template_redirect', 'cleg_procurement_render_standalone_page', 0);

if (!function_exists('cleg_procurement_render_detail')) {
    function cleg_procurement_render_detail($request, $data) {
        $statuses = cleg_procurement_statuses();
        $quotes = isset($data['quotes'][$request['id']]) && is_array($data['quotes'][$request['id']]) ? $data['quotes'][$request['id']] : array();
        $related_pos = cleg_procurement_related_pos($data, $request);
        $has_po = !empty($related_pos);
        $commercial_summary = cleg_procurement_request_commercial_summary($request, $data);
        $project_options = array('Argos Dorado Plant', 'Argos Terminal San Juan', 'Medtronic Humacao', 'Medtronic Villalba', 'Medtronic Juncos', 'Carriotech Dorado', 'Oficina', 'Project Pending', 'Troubleshooting / Urgente', 'New Industrial Service');
        $unit_options = array('Unidad', 'Set', 'Paquete', 'Pie', 'Metro', 'Servicio', 'Viaje');
        $priority_options = array('Normal', 'Alta', 'Urgente', 'Detiene trabajo hoy');
        $delivery_options = array('Puerto Rico', 'Argos Dorado Plant', 'Argos Terminal San Juan', 'Medtronic Humacao', 'Medtronic Villalba', 'Medtronic Juncos', 'Oficina', 'Otro / por confirmar');
        $substitute_options = array('Si', 'No', 'Interno', 'Depende, requiere aprobacion', 'Pendiente');
        $purchase_options = array('Quote equivalent accepted', 'Exact replacement only', 'Application solution needed', 'Travel / logistics', 'Service quote');
        $info_options = array('Complete', 'Usable for RFQ', 'Missing critical data', 'Field note only');
        $risk_options = array('Low', 'Medium', 'High', 'Unknown');
        $rfq_template_options = array('General technical RFQ', 'Exact replacement RFQ', 'Equivalent accepted RFQ', 'Service RFQ', 'Travel / logistics quote');
        $quote_status_options = array('Received', 'Under Review', 'Recommended', 'Rejected', 'Cancelled');
        $delivery_fit_options = array('Unknown', 'Yes', 'No', 'Risk');
        $decision_context = cleg_procurement_request_decision_context($request, $data);
        $current_user = wp_get_current_user();
        $show_history = cleg_procurement_user_can_view_all_requests($current_user);
        $can_manage_request = cleg_procurement_user_can_manage_requests($current_user);
        $can_edit_request = cleg_procurement_user_can_edit_request($request, $current_user);
        $selected_quote = cleg_procurement_recommended_quote($quotes);
        $selected_quote_eta = '';
        if ($selected_quote) {
            $selected_quote_eta = (string) ($selected_quote['estimated_delivery_to_pr'] ?? '');
            if ($selected_quote_eta === '') {
                $selected_quote_eta = (string) ($selected_quote['eta'] ?? '');
            }
        }

        ob_start();
        ?>
        <article>
            <span class="cleg-proc-badge <?php echo esc_attr(cleg_procurement_badge_class($request['status'])); ?>"><?php echo esc_html($statuses[$request['status']] ?? $request['status']); ?></span>
            <h3><?php echo esc_html($request['item']); ?></h3>
            <p class="cleg-proc-muted"><?php echo esc_html($request['project']); ?> · Solicitado por <?php echo esc_html($request['requester']); ?></p>
            <section class="cleg-proc-decision-hero" aria-label="Decision de compra">
                <div>
                    <span class="cleg-proc-decision-pill is-<?php echo esc_attr($decision_context['tone']); ?>"><?php echo esc_html($decision_context['label']); ?></span>
                </div>
            </section>
            <?php if (!empty($request['client_approval_status']) || !empty($request['client_follow_up_due_date'])) : ?>
                <section class="cleg-proc-client-summary" aria-label="Aprobacion de cliente">
                    <span><b><?php echo esc_html($request['client_approval_status'] ?? 'No enviado al cliente'); ?></b><small>Estado cliente</small></span>
                    <span><b><?php echo esc_html(!empty($request['client_sent_at']) ? cleg_procurement_display_datetime($request['client_sent_at']) : 'Sin envio'); ?></b><small>Enviado</small></span>
                    <span><b><?php echo esc_html($request['client_follow_up_due_date'] ?? 'Sin fecha'); ?></b><small>Proximo seguimiento</small></span>
                    <span><b><?php echo esc_html((string) ($request['client_follow_up_count'] ?? '0')); ?></b><small>Seguimientos</small></span>
                </section>
            <?php endif; ?>
            <nav class="cleg-proc-detail-tabs" aria-label="Secciones de requisicion">
                <a href="#resumen-solicitud">Resumen</a>
                <a href="#cotizaciones">Cotizaciones</a>
                <a href="#ordenes">PO / Tracking</a>
                <?php if ($show_history) : ?>
                    <a href="#historial-solicitud">Historial</a>
                <?php endif; ?>
                <?php if (!empty($request['reference_images'])) : ?>
                    <a href="#adjuntos-solicitud">Adjuntos</a>
                <?php endif; ?>
            </nav>
            <div class="cleg-proc-detail-actions" aria-label="Ficha de requisicion">
                <button class="cleg-proc-btn is-secondary" type="button" data-cleg-view-request>Ver ficha</button>
                <button class="cleg-proc-btn is-ghost" type="button" data-cleg-print-request>Imprimir ficha</button>
                <button class="cleg-proc-btn is-ghost" type="button" data-cleg-download-request>Descargar ficha</button>
            </div>

            <section class="cleg-proc-print-sheet" data-cleg-print-sheet aria-label="Ficha imprimible de requisicion">
                <h2><?php echo esc_html($request['item']); ?></h2>
                <p><?php echo esc_html($request['id']); ?> · <?php echo esc_html($request['project']); ?> · <?php echo esc_html($statuses[$request['status']] ?? $request['status']); ?></p>
                <dl>
                    <div><dt>Solicitado por</dt><dd><?php echo esc_html($request['requester']); ?></dd></div>
                    <div><dt>Cantidad</dt><dd><?php echo esc_html((string) ($request['quantity'] ?? '1') . ' ' . (string) ($request['unit'] ?? '')); ?></dd></div>
                    <div><dt>Entrega requerida</dt><dd><?php echo esc_html($request['required_delivery_date'] ?? $request['due_date'] ?? 'Pendiente'); ?></dd></div>
                    <div><dt>Destino</dt><dd><?php echo esc_html($request['delivery_location'] ?? 'Pendiente'); ?></dd></div>
                    <div><dt>Referencia</dt><dd><?php echo esc_html($request['preferred_brand_model'] ?? 'Pendiente'); ?></dd></div>
                    <div><dt>Estado decision</dt><dd><?php echo esc_html($decision_context['label']); ?></dd></div>
                    <div><dt>Precio / PO</dt><dd><?php echo esc_html($commercial_summary['price'] . ' · ' . $commercial_summary['po']); ?></dd></div>
                    <div><dt>Tracking</dt><dd><?php echo esc_html($commercial_summary['tracking']); ?></dd></div>
                </dl>
                <?php if (!empty($request['conditions'])) : ?>
                    <h3>Datos tecnicos</h3>
                    <p><?php echo esc_html($request['conditions']); ?></p>
                <?php endif; ?>
                <?php if (!empty($request['item_missing_information'])) : ?>
                    <h3>Falta confirmar</h3>
                    <p><?php echo esc_html($request['item_missing_information']); ?></p>
                <?php endif; ?>
                <?php if ($selected_quote) : ?>
                    <h3>Cotizacion seleccionada</h3>
                    <p><?php echo esc_html(($selected_quote['vendor'] ?? 'Proveedor') . ' · ' . cleg_procurement_money($selected_quote['amount'] ?? 0) . ' · ETA: ' . ($selected_quote_eta ?: 'Pendiente')); ?></p>
                    <?php if (!empty($selected_quote['supplier_contact_person']) || !empty($selected_quote['supplier_contact_email']) || !empty($selected_quote['supplier_contact_phone'])) : ?>
                        <p><?php echo esc_html(trim((string) ($selected_quote['supplier_contact_person'] ?? '') . ' · ' . (string) ($selected_quote['supplier_contact_email'] ?? '') . ' · ' . (string) ($selected_quote['supplier_contact_phone'] ?? ''), " \t\n\r\0\x0B·")); ?></p>
                    <?php endif; ?>
                <?php endif; ?>
            </section>

            <details class="cleg-proc-subsection cleg-proc-summary-editor" id="resumen-solicitud">
                <summary>Datos basicos <span><?php echo esc_html($commercial_summary['eta_label']); ?>: <?php echo esc_html($commercial_summary['eta']); ?></span></summary>
