            .cleg-procurement input:-webkit-autofill,.cleg-procurement input:-webkit-autofill:hover,.cleg-procurement input:-webkit-autofill:focus,.cleg-procurement input:-webkit-autofill:active,.cleg-procurement textarea:-webkit-autofill,.cleg-procurement textarea:-webkit-autofill:hover,.cleg-procurement textarea:-webkit-autofill:focus,.cleg-procurement select:-webkit-autofill,.cleg-procurement select:-webkit-autofill:hover,.cleg-procurement select:-webkit-autofill:focus{-webkit-text-fill-color:var(--p-ink)!important;box-shadow:0 0 0 1000px #fff inset!important;background-color:#fff!important;caret-color:var(--p-ink)!important;transition:background-color 9999s ease-out 0s}
