            .cleg-proc-toggle span{min-height:40px;border:1px solid var(--p-line);border-radius:var(--p-radius);background:#fff;display:flex;align-items:center;justify-content:center;font-weight:850}
            .cleg-proc-toggle input:checked+span{background:linear-gradient(135deg,var(--p-blue) 0%,var(--p-blue-2) 100%);border-color:var(--p-blue);color:#fff}
            .cleg-proc-toggle-wide{max-width:360px}
            .cleg-proc-attach-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;align-items:start}
