            .cleg-proc-attach-action{position:relative;display:grid!important;place-items:center;gap:4px;min-height:62px;border:0;border-radius:0;background:transparent;color:var(--p-ink)!important;text-align:center;text-transform:none!important;cursor:pointer;padding:4px 2px;transition:transform .16s ease}
            .cleg-proc-attach-action:hover{transform:translateY(-1px);background:transparent}
            .cleg-proc-attach-action input[type="file"]{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;opacity:0!important;padding:0!important;cursor:pointer}
            .cleg-proc-attach-action strong{font-size:10px;line-height:1.05;color:var(--p-ink)}
            .cleg-proc-attach-action small{display:none}
            .cleg-proc-attach-icon{width:34px;height:34px;border-radius:10px;background:#fff;border:1px solid rgba(216,224,232,.95);display:inline-grid;place-items:center;position:relative;box-shadow:0 8px 16px rgba(7,24,39,.08)}
            .cleg-proc-attach-icon.is-camera,.cleg-proc-attach-icon.is-video,.cleg-proc-attach-icon.is-gallery,.cleg-proc-attach-icon.is-file{background:#fff}
            .cleg-proc-attach-icon:before,.cleg-proc-attach-icon:after{content:"";position:absolute;display:block}
            .cleg-proc-attach-icon.is-camera:before{width:18px;height:13px;border:2px solid #071827;border-radius:4px;top:13px;left:8px}
            .cleg-proc-attach-icon.is-camera:after{width:6px;height:6px;border:2px solid #071827;border-radius:999px;top:15px;left:14px;box-shadow:-5px -7px 0 -3px #071827}
            .cleg-proc-attach-icon.is-video:before{width:15px;height:12px;border:2px solid #071827;border-radius:4px;left:7px;top:12px}
            .cleg-proc-attach-icon.is-video:after{border-top:6px solid transparent;border-bottom:6px solid transparent;border-left:8px solid #071827;right:6px;top:12px}
            .cleg-proc-attach-icon.is-gallery:before{width:18px;height:14px;border:2px solid #071827;border-radius:4px;left:8px;top:10px}
            .cleg-proc-attach-icon.is-gallery:after{width:11px;height:7px;border-left:2px solid #071827;border-bottom:2px solid #071827;transform:rotate(-45deg);left:12px;top:16px;box-shadow:8px -8px 0 -6px #071827}
            .cleg-proc-attach-icon.is-file:before{width:14px;height:18px;border:2px solid #071827;border-radius:3px;left:10px;top:8px;background:transparent}
            .cleg-proc-attach-icon.is-file:after{width:7px;height:7px;border-top:2px solid #071827;border-right:2px solid #071827;right:10px;top:8px;background:#fff}

            /* CLEG procurement attachment icons - phased approved reference */
            .cleg-procurement .cleg-proc-attach-icon.is-camera,.cleg-procurement .cleg-proc-attach-icon.is-video,.cleg-procurement .cleg-proc-attach-icon.is-gallery,.cleg-procurement .cleg-proc-attach-icon.is-file{background-size:cover!important;background-position:center!important;background-repeat:no-repeat!important;background-color:#07111d!important;border:0!important;box-shadow:0 8px 16px rgba(6,24,45,.18)!important}
            .cleg-procurement .cleg-proc-attach-icon.is-camera:before,.cleg-procurement .cleg-proc-attach-icon.is-camera:after,.cleg-procurement .cleg-proc-attach-icon.is-video:before,.cleg-procurement .cleg-proc-attach-icon.is-video:after,.cleg-procurement .cleg-proc-attach-icon.is-gallery:before,.cleg-procurement .cleg-proc-attach-icon.is-gallery:after,.cleg-procurement .cleg-proc-attach-icon.is-file:before,.cleg-procurement .cleg-proc-attach-icon.is-file:after{display:none!important;content:none!important}
            .cleg-procurement .cleg-proc-attach-icon.is-camera{background-image:url("data:image/webp;base64,")!important}
            .cleg-procurement .cleg-proc-attach-icon.is-video{background-image:url("data:image/webp;base64,")!important}
            .cleg-procurement .cleg-proc-attach-icon.is-gallery{background-image:url("data:image/webp;base64,")!important}
            .cleg-procurement .cleg-proc-attach-icon.is-file{background-image:url("data:image/webp;base64,")!important}
            /* End CLEG procurement attachment icons - phased approved reference */
            .cleg-proc-attach-preview{display:grid;gap:3px;min-height:0}
            .cleg-proc-attach-chip{display:grid;grid-template-columns:30px minmax(0,1fr) 22px;align-items:center;gap:5px;min-height:32px;border:1px solid var(--p-line);border-radius:7px;background:#fff;padding:3px;color:var(--p-ink);box-shadow:0 6px 12px rgba(6,24,45,.06)}
            .cleg-proc-attach-chip img,.cleg-proc-attach-chip video{width:30px;height:24px;object-fit:cover;border-radius:5px;background:#eef2f5}
            .cleg-proc-attach-chip span{font-size:10px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
            .cleg-proc-attach-chip button{width:22px;height:22px;min-height:22px;border:0;border-radius:999px;background:#edf1f6;color:#06182d;font-weight:950;line-height:1;cursor:pointer;padding:0}
            .cleg-proc-request-audio{display:grid;justify-items:center;gap:8px;min-height:72px;border:1px solid #c4d0dc;border-radius:8px;background:#f8fafc;padding:12px 10px;text-align:center}
            .cleg-proc-audio-record-btn{width:44px;height:44px;min-width:44px;min-height:44px;border:1px solid #7d1f1f;border-radius:999px;background:#a82424;color:#fff;display:inline-grid;place-items:center;padding:0;cursor:pointer;box-shadow:0 8px 16px rgba(168,36,36,.22);transition:transform .15s ease,box-shadow .15s ease,background .15s ease}
            .cleg-proc-audio-record-btn span{width:14px;height:14px;border-radius:999px;background:#fff;display:block}
            .cleg-proc-audio-record-btn:hover{background:#8f2525;box-shadow:0 10px 20px rgba(168,36,36,.28)}
            .cleg-proc-audio-record-btn.is-recording{background:#d62828;box-shadow:0 0 0 6px rgba(168,36,36,.16),0 10px 20px rgba(168,36,36,.26);animation:clegProcAudioPulse 1.1s ease-in-out infinite}
            .cleg-proc-audio-record-btn.is-recording span{width:16px;height:16px;border-radius:4px}
            .cleg-proc-request-audio small{color:#65707c;font-size:12px;font-weight:850;text-transform:none}
            .cleg-proc-request-audio-preview{position:relative;width:min(360px,100%);display:grid;gap:6px;border:1px solid #c4d0dc;border-radius:8px;background:#fff;padding:9px 38px 9px 9px;box-shadow:0 8px 18px rgba(6,24,45,.07)}
            .cleg-proc-request-audio-preview[hidden]{display:none!important}
            .cleg-proc-request-audio-preview audio{width:100%;min-width:0}
            .cleg-proc-request-audio-preview strong{display:block;color:#06182d;font-size:12px;line-height:1.25;overflow-wrap:anywhere;text-align:left}
            .cleg-proc-audio-remove{position:absolute;top:7px;right:7px;width:24px;height:24px;min-height:24px;border:1px solid #d8b8b8;border-radius:999px;background:#fff;color:#8f2525;padding:0;font-size:16px;font-weight:950;line-height:1;display:inline-grid;place-items:center;cursor:pointer}
            .cleg-proc-mic-help{position:fixed;inset:0;z-index:999999;background:rgba(6,24,45,.58);display:none;align-items:center;justify-content:center;padding:18px}
            .cleg-proc-mic-help.is-open{display:flex}
            .cleg-proc-mic-help-card{width:min(520px,100%);border:1px solid #d8e0e7;border-radius:8px;background:#fff;color:#06182d;box-shadow:0 24px 70px rgba(6,24,45,.28);padding:18px;display:grid;gap:12px}
            .cleg-proc-mic-help-card h3{margin:0;font-size:18px;line-height:1.2}
            .cleg-proc-mic-help-card p{margin:0;color:#43505d;font-size:13px;line-height:1.45}
            .cleg-proc-mic-help-card ul{margin:0;padding-left:18px;display:grid;gap:7px;color:#43505d;font-size:13px;line-height:1.4}
            .cleg-proc-mic-help-card button{justify-self:end}
            @keyframes clegProcAudioPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.04)}}
            .cleg-proc-saved-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}
            .cleg-proc-saved-file{display:grid;gap:8px;align-items:stretch;border:1px solid #aebdcc;border-radius:8px;background:#fff;padding:9px;color:var(--p-ink)!important;text-decoration:none!important;min-width:0;box-shadow:0 8px 18px rgba(6,24,45,.07)}
            .cleg-proc-saved-file.is-media{grid-template-columns:1fr}
            .cleg-proc-saved-file img,.cleg-proc-saved-file video{width:100%;height:112px;object-fit:cover;border-radius:7px;background:#eef2f5}
            .cleg-proc-saved-file audio{width:100%}
            .cleg-proc-saved-file.is-document img,.cleg-proc-saved-file.is-document video{width:54px;height:42px}
            .cleg-proc-saved-file strong{font-size:12px;line-height:1.25;white-space:normal;overflow-wrap:anywhere}
            .cleg-proc-attachment-preview{display:grid;grid-template-columns:1fr;gap:7px;width:100%;border:0;background:transparent;color:var(--p-ink);text-align:left;padding:0;cursor:zoom-in}
            .cleg-proc-attachment-preview .cleg-proc-file-mark{width:54px;height:42px}
            .cleg-proc-attachment-actions{display:flex;align-items:center;justify-content:space-between;gap:8px;border-top:1px solid #c4d0dc;padding-top:8px}
            .cleg-proc-attachment-actions label{display:flex;align-items:center;gap:6px;margin:0;color:#43505d;font-size:12px;font-weight:850;text-transform:none}
            .cleg-proc-attachment-actions input{width:auto;min-height:auto}
            .cleg-proc-mini-danger{width:28px;height:28px;min-height:28px;border:1px solid #b94343;border-radius:999px;background:#fff;color:#8f2525;padding:0;font-size:18px;font-weight:950;line-height:1;cursor:pointer;display:inline-grid;place-items:center}
            .cleg-proc-attachment-bulk{display:none;justify-content:center;gap:10px;flex-wrap:wrap;margin-top:12px}
            .cleg-proc-attachment-manager.has-selection .cleg-proc-attachment-bulk{display:flex}
            .cleg-proc-attachment-modal{position:fixed;inset:0;z-index:99999;display:none;align-items:center;justify-content:center;background:rgba(6,24,45,.68);padding:20px}
            .cleg-proc-attachment-modal.is-open{display:flex}
            .cleg-proc-attachment-modal-card{width:min(980px,96vw);max-height:92vh;display:grid;gap:10px;border:1px solid #8fa0b1;border-radius:8px;background:#fff;padding:12px;box-shadow:0 24px 60px rgba(0,0,0,.28)}
            .cleg-proc-attachment-modal-close{justify-self:end;border:1px solid #9dadbd;border-radius:7px;background:#f4f7fa;color:#06182d;padding:7px 10px;font-weight:850;cursor:pointer}
            .cleg-proc-attachment-modal-title{display:block;color:#06182d;font-size:14px;line-height:1.25;overflow-wrap:anywhere}
            .cleg-proc-attachment-modal-body{display:grid;gap:10px;min-height:0}
            .cleg-proc-attachment-modal-body img,.cleg-proc-attachment-modal-body video{max-width:100%;max-height:72vh;object-fit:contain;border-radius:7px;background:#eef2f5;margin:auto}
            .cleg-proc-attachment-modal-body audio{width:100%}
            .cleg-proc-attachment-modal-body iframe{width:100%;height:72vh;border:1px solid #aebdcc;border-radius:7px;background:#fff}
            .cleg-proc-print-sheet{display:none}
            .cleg-proc-print-sheet h2,.cleg-proc-print-sheet h3,.cleg-proc-print-sheet p{margin:0;color:#06182d}
            .cleg-proc-readonly-summary{display:grid;gap:12px;padding:14px}
            .cleg-proc-readonly-summary dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0}
            .cleg-proc-readonly-summary dl div{border:1px solid #d8e0e7;border-radius:8px;background:#fff;padding:9px}
            .cleg-proc-readonly-summary dt{color:#65707c;font-size:10px;font-weight:900;text-transform:uppercase}
            .cleg-proc-readonly-summary dd{margin:2px 0 0;color:#06182d;font-size:13px;font-weight:850;overflow-wrap:anywhere}
            .cleg-proc-readonly-summary h4{margin:0;color:#06182d;font-size:14px}
            .cleg-proc-readonly-summary p{margin:0;color:#43505d;line-height:1.45}
            .cleg-proc-print-sheet dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}
            .cleg-proc-print-sheet dl div{border:1px solid #d8e0e7;border-radius:7px;padding:8px}
            .cleg-proc-print-sheet dt{font-size:10px;font-weight:900;text-transform:uppercase;color:#65707c}
            .cleg-proc-print-sheet dd{margin:2px 0 0;font-size:13px;font-weight:850;color:#06182d}
            .cleg-proc-file-mark{width:42px;height:36px;border-radius:6px;background:#edf1f6;position:relative;display:block}
            .cleg-proc-file-mark:before{content:"";position:absolute;width:16px;height:20px;border:2px solid #06182d;border-radius:3px;left:12px;top:7px}
            .cleg-proc-file-mark:after{content:"";position:absolute;width:8px;height:8px;border-top:2px solid #06182d;border-right:2px solid #06182d;right:12px;top:7px}
            .cleg-proc-tabs{display:flex;gap:6px;padding:8px;border-bottom:1px solid var(--p-line);background:var(--p-panel-2);overflow-x:auto;align-items:center}
            .cleg-proc-tabs a,.cleg-proc-tabs span{border:1px solid transparent;background:transparent;border-radius:var(--p-radius);padding:8px 11px;color:var(--p-muted);white-space:nowrap;min-height:36px;text-decoration:none;font-weight:800;font-size:14px;display:inline-flex;align-items:center;gap:7px}
            .cleg-proc-tabs a small{display:inline-flex;align-items:center;justify-content:center;min-width:22px;min-height:22px;border-radius:999px;background:rgba(101,112,124,.12);color:var(--p-muted);font-size:11px;line-height:1;font-weight:900}
            .cleg-proc-tabs a.is-active{background:#fff;border-color:var(--p-line);color:var(--p-ink)}
            .cleg-proc-tabs a.is-active small{background:var(--p-blue-soft);color:var(--p-blue)}
            .cleg-proc-tabs span{margin-left:auto;font-size:12px;font-weight:750}
            .cleg-proc-filterbox{border-bottom:1px solid var(--p-line);background:#fff}
            .cleg-proc-filterbox summary{cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:42px;padding:10px 18px;font-weight:850;color:var(--p-ink);list-style:none}
            .cleg-proc-filterbox summary::-webkit-details-marker{display:none}
            .cleg-proc-filterbox summary:after{content:"Abrir";font-size:12px;color:var(--p-muted);font-weight:800}
            .cleg-proc-filterbox[open] summary:after{content:"Cerrar"}
            .cleg-proc-filterbox summary span{color:var(--p-muted);font-size:12px;font-weight:800;margin-left:auto}
            .cleg-proc-filterbar{display:grid;grid-template-columns:minmax(220px,1.35fr) minmax(140px,.65fr) minmax(160px,.78fr) minmax(160px,.82fr) auto auto;gap:10px;align-items:end;padding:14px 16px;border-bottom:1px solid var(--p-line);background:#fff}
            .cleg-proc-view-canceladas .cleg-proc-filterbar{grid-template-columns:minmax(220px,1.4fr) minmax(150px,.7fr) auto auto}
            .cleg-proc-list{display:grid;max-height:760px;overflow:auto}
            .cleg-proc-request-row{display:block;border-bottom:1px solid var(--p-line);color:var(--p-ink);background:#fff;transition:background .16s ease}
            .cleg-proc-request-row:hover,.cleg-proc-request-row.is-active,.cleg-proc-request-row[open]{background:#fafbfc}
            .cleg-proc-request-row summary{cursor:pointer;display:grid;grid-template-columns:minmax(260px,1fr) minmax(150px,180px) minmax(130px,170px) 48px;gap:12px;align-items:center;padding:14px 18px;list-style:none;min-height:76px}
            .cleg-proc-request-row summary::-webkit-details-marker{display:none}
            .cleg-proc-request-row summary:after{content:"Abrir";font-size:11px;color:var(--p-muted);font-weight:850;text-align:right}
            .cleg-proc-request-row[open] summary:after{content:"Cerrar"}
            .cleg-proc-request-row strong{display:block;color:var(--p-ink);font-size:15px;line-height:1.26;margin-top:0}
            .cleg-proc-request-row small,.cleg-proc-muted,.cleg-proc-detail small{display:block;color:var(--p-muted);margin-top:3px;line-height:1.35}
            .cleg-proc-request-row summary>.cleg-proc-badge{justify-self:start;max-width:100%;white-space:normal;text-align:left}
            .cleg-proc-request-meta{display:grid!important;grid-template-columns:minmax(0,1fr);gap:2px;align-items:center;justify-items:start}
            .cleg-proc-request-meta span{font-weight:850;color:var(--p-muted)}
            .cleg-proc-request-meta em{font-style:normal;font-size:10px;color:#9aa4af;font-weight:750;letter-spacing:0}
            .cleg-proc-request-more{display:grid;grid-template-columns:minmax(160px,1fr) minmax(130px,.8fr) minmax(120px,.72fr) minmax(120px,.72fr) minmax(220px,1.05fr) 86px;gap:10px;align-items:center;padding:0 14px 12px 14px}
            .cleg-proc-request-more div{border:1px solid var(--p-line);border-radius:var(--p-radius);padding:8px;background:#fff}
            .cleg-proc-request-more strong,.cleg-proc-request-more small{display:block}
            .cleg-proc-request-more strong{font-size:13px;color:var(--p-ink);line-height:1.25;margin:0}
            .cleg-proc-request-more small{font-size:11px;color:var(--p-muted);font-weight:750;margin-top:2px}
            .cleg-proc-inline-status{display:grid;grid-template-columns:minmax(0,1fr) minmax(96px,auto);gap:8px;align-items:end}
            .cleg-proc-inline-status label{font-size:11px;font-weight:900;color:var(--p-muted)}
            .cleg-proc-inline-status select{width:100%;min-height:38px;border:1px solid var(--p-line);border-radius:var(--p-radius);padding:8px 9px;background:#fff;color:var(--p-ink);font-weight:850}
            .cleg-proc-auto-save{display:inline-flex;align-items:center;justify-content:center;min-height:38px;border:1px solid var(--p-line);border-radius:var(--p-radius);padding:7px 9px;background:#fafbfc;color:var(--p-muted);font-size:11px;font-weight:850;line-height:1.15;text-align:center}
            .cleg-proc-inline-status select.is-saving,.cleg-proc-inline-form select.is-saving{box-shadow:0 0 0 3px rgba(35,105,165,.16);border-color:#2369a5}
            .cleg-proc-detail-panel .cleg-proc-mobile-back{display:inline-flex;align-items:center;min-height:36px}
            .cleg-proc-badge{display:inline-flex;align-items:center;width:fit-content;border-radius:999px;padding:5px 8px;font-size:12px;font-weight:800;white-space:nowrap;line-height:1.2}
            .cleg-proc-badge.is-warning{background:var(--p-orange-soft);color:var(--p-orange)}
            .cleg-proc-badge.is-good{background:var(--p-green-soft);color:var(--p-green)}
            .cleg-proc-badge.is-bad{background:var(--p-red-soft);color:var(--p-red)}
            .cleg-proc-badge.is-neutral{background:var(--p-blue-soft);color:var(--p-blue)}
            .cleg-proc-empty{min-height:290px;display:grid;place-content:center;text-align:center;color:var(--p-muted);padding:32px;background:#fff}
            .cleg-proc-empty strong,.cleg-proc-empty h3{color:var(--p-ink);font-size:18px;margin:0 0 6px}
            .cleg-proc-empty p{margin:0;color:var(--p-muted)}
            .cleg-proc-detail h3{margin:0 0 4px;font-size:22px;color:var(--p-ink);line-height:1.15}
            .cleg-proc-mobile-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:14px 0 2px}
            .cleg-proc-facts{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:16px 0}
            .cleg-proc-facts div{border:1px solid var(--p-line);border-radius:var(--p-radius);padding:11px;background:#fafbfc}
            .cleg-proc-facts span,.cleg-proc-facts strong{display:block}
            .cleg-proc-facts span{font-size:12px;color:var(--p-muted);font-weight:700;text-transform:uppercase}
            .cleg-proc-facts strong{margin-top:4px;color:var(--p-ink)}
            .cleg-proc-summary-editor{border:1px solid var(--p-line);border-radius:8px;background:#fbfcfd;padding:12px;margin-top:14px}
            .cleg-proc-summary-form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;align-items:end;margin:10px 0 0!important}
            .cleg-proc-summary-form label{display:grid;gap:5px;min-width:0;color:var(--p-muted);font-size:11px;font-weight:900;text-transform:uppercase}
            .cleg-proc-summary-form input,.cleg-proc-summary-form select,.cleg-proc-summary-form textarea{width:100%;min-width:0;max-width:100%;box-sizing:border-box;border:1px solid var(--p-line);border-radius:8px;background:#fff;color:var(--p-ink);font-size:13px;font-weight:700;line-height:1.25;padding:8px 9px;box-shadow:none}
            .cleg-proc-summary-form textarea{resize:vertical;min-height:74px}
            .cleg-proc-summary-form .is-wide,.cleg-proc-summary-form .cleg-proc-summary-facts{grid-column:1/-1}
            .cleg-proc-summary-form .cleg-proc-btn{grid-column:1/span 2;justify-self:start;width:auto;min-width:min(240px,100%)}
            .cleg-proc-summary-facts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
            .cleg-proc-summary-facts div{border:1px solid var(--p-line);border-radius:8px;background:#fff;padding:9px;min-width:0}
            .cleg-proc-summary-facts span,.cleg-proc-summary-facts strong{display:block;min-width:0;overflow-wrap:anywhere}
            .cleg-proc-summary-facts span{font-size:10px;color:var(--p-muted);font-weight:900;text-transform:uppercase}
            .cleg-proc-summary-facts strong{font-size:13px;color:var(--p-ink);margin-top:3px}
            .cleg-proc-note{background:var(--p-orange-soft);border:1px solid rgba(199,80,0,.18);border-radius:var(--p-radius);padding:12px;color:#5b351a;line-height:1.45}
            .cleg-proc-inline-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(130px,auto);gap:10px;align-items:end;margin:14px 0 20px}
            .cleg-proc-update-form{display:grid;grid-template-columns:1fr;gap:9px;margin:10px 0 18px}
            .cleg-proc-update-form .cleg-proc-btn{width:100%}
            .cleg-proc-details,.cleg-proc-danger-details,.cleg-proc-quote-edit{border:1px solid var(--p-line);border-radius:var(--p-radius);background:#fff;margin:10px 0;overflow:hidden}
            .cleg-proc-details summary,.cleg-proc-danger-details summary,.cleg-proc-quote-edit summary{cursor:pointer;padding:12px 14px;font-weight:850;color:var(--p-ink);list-style:none}
            .cleg-proc-details summary::-webkit-details-marker,.cleg-proc-danger-details summary::-webkit-details-marker,.cleg-proc-quote-edit summary::-webkit-details-marker{display:none}
            .cleg-proc-details summary:after,.cleg-proc-danger-details summary:after,.cleg-proc-quote-edit summary:after{content:"Abrir";float:right;color:var(--p-muted);font-size:12px}
            .cleg-proc-details[open] summary:after,.cleg-proc-danger-details[open] summary:after,.cleg-proc-quote-edit[open] summary:after{content:"Cerrar"}
            .cleg-proc-details form,.cleg-proc-quote-edit form{padding:0 14px 14px}
            .cleg-proc-danger-details{border-color:rgba(168,36,36,.28);background:var(--p-red-soft)}
            .cleg-proc-danger-details form{padding:0 14px 14px}
            .cleg-proc-subsection{border-top:1px solid var(--p-line);padding-top:18px;margin-top:18px}
            .cleg-proc-subsection h4{margin:0 0 12px;font-size:18px;color:var(--p-ink)}
