if (!function_exists('cleg_procurement_upload_preview_script')) {
    function cleg_procurement_upload_preview_script() {
        static $printed = false;
        if ($printed) {
            return '';
        }
        $printed = true;

        return <<<'HTML'
        <script id="cleg-procurement-upload-preview">
        (function(){
            var stepLabels = {1:"describe lo que necesitas",2:"define entrega y prioridad",3:"agrega detalles opcionales"};
            function syncRequestStep(form, number){
                if (!form) return;
                var current = String(number || 1);
                form.querySelectorAll("[data-proc-form-step]").forEach(function(step){
                    var active = step.getAttribute("data-proc-form-step") === current;
                    step.hidden = !active;
                    step.classList.toggle("is-active", active);
                    step.querySelectorAll("input,select,textarea").forEach(function(control){ control.disabled = !active; });
                });
                form.querySelectorAll("[data-proc-step-link]").forEach(function(link){
                    var active = link.getAttribute("data-proc-step-link") === current;
                    link.classList.toggle("is-active", active);
                    link.setAttribute("aria-current", active ? "step" : "false");
                });
                var status = form.querySelector("[data-proc-step-status]");
                if (status) status.textContent = "Paso " + current + " de 3: " + stepLabels[current] + ".";
            }
            function initRequestWizard(){
                document.querySelectorAll(".cleg-proc-request-form form").forEach(function(form){
                    if (form.getAttribute("data-proc-wizard-ready") === "1") return;
                    form.setAttribute("data-proc-wizard-ready", "1");
                    syncRequestStep(form, 1);
                    form.addEventListener("click", function(event){
                        var next = event.target.closest("[data-proc-step-next]");
                        var back = event.target.closest("[data-proc-step-back]");
                        var link = event.target.closest("[data-proc-step-link]");
                        var target = next ? next.getAttribute("data-proc-step-next") : (back ? back.getAttribute("data-proc-step-back") : (link ? link.getAttribute("data-proc-step-link") : ""));
                        if (!target) return;
                        event.preventDefault();
                        var active = form.querySelector('[data-proc-form-step].is-active');
                        if (next && active && !active.querySelector("input,select,textarea").closest("form").reportValidity()) return;
                        syncRequestStep(form, target);
                        var heading = form.querySelector('[data-proc-form-step="' + target + '"]');
                        if (heading) heading.scrollIntoView({behavior:"smooth",block:"start"});
                    });
                });
            }
            document.addEventListener("submit", function(event){
                var form = event.target.closest(".cleg-proc-request-form form");
                if (!form) return;
                form.querySelectorAll("[data-proc-form-step] input,[data-proc-form-step] select,[data-proc-form-step] textarea").forEach(function(control){ control.disabled = false; });
            }, true);
            if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", initRequestWizard, {once:true}); else initRequestWizard();
            function syncInputFiles(input, files){
                if (!input) return false;
                try {
                    var transfer = new DataTransfer();
                    files.forEach(function(file){ transfer.items.add(file); });
                    input.files = transfer.files;
                    input.dispatchEvent(new Event("change", {bubbles:true}));
                    return input.files && input.files.length === files.length;
                } catch (error) {
                    return false;
                }
            }
            function thumbFor(file){
                if (file.type && file.type.indexOf("image/") === 0) {
                    return "<img alt=\"\" src=\"" + URL.createObjectURL(file) + "\">";
                }
                if (file.type && file.type.indexOf("video/") === 0) {
                    return "<video muted playsinline preload=\"metadata\" src=\"" + URL.createObjectURL(file) + "\"></video>";
                }
                if (file.type && file.type.indexOf("audio/") === 0) {
                    return "<span class=\"cleg-proc-file-mark\" aria-hidden=\"true\"></span>";
                }
                return "<span class=\"cleg-proc-file-mark\" aria-hidden=\"true\"></span>";
            }
            function escapeHtml(value){
                return String(value || "").replace(/[&<>"']/g,function(char){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char];});
            }
            function attachmentKind(url, fallback){
                var path = String(url || "").split("?")[0].toLowerCase();
                if (/\.(jpe?g|png|gif|webp|avif|svg|heic|heif|bmp|tiff?)$/.test(path)) return "image";
                if (/\.(mp4|mov|webm|m4v)$/.test(path)) return "video";
                if (/\.(mp3|m4a|aac|wav|ogg|oga|opus)$/.test(path)) return "audio";
                if (/\.pdf$/.test(path)) return "pdf";
                return fallback || "document";
            }
            function render(input){
                var slot = input.closest(".cleg-proc-attach-slot");
                var preview = slot ? slot.querySelector(".cleg-proc-attach-preview") : null;
                if (!preview) return;
                var files = Array.prototype.slice.call(input.files || []);
                preview.innerHTML = files.map(function(file,index){
                    return "<div class=\"cleg-proc-attach-chip\" data-file-index=\"" + index + "\">" + thumbFor(file) + "<span title=\"" + escapeHtml(file.name) + "\">" + escapeHtml(file.name) + "</span><button type=\"button\" aria-label=\"Quitar " + escapeHtml(file.name) + "\">x</button></div>";
                }).join("");
            }
            function hasFiles(form){
                return Array.prototype.slice.call(form.querySelectorAll("input[type=file]")).some(function(input){
                    return input.files && input.files.length;
                });
            }
            function markSubmitting(form){
                if (!form || !form.closest(".cleg-procurement")) return;
                if (form.getAttribute("data-cleg-proc-submitting") === "1") return false;
                form.setAttribute("data-cleg-proc-submitting", "1");
                var button = form.querySelector("button[type=submit],input[type=submit]");
                var status = form.querySelector(".cleg-proc-upload-status");
                var message = hasFiles(form) ? "Subiendo archivos..." : "Guardando...";
                if (!status) {
                    status = document.createElement("span");
                    status.className = "cleg-proc-upload-status";
                    status.setAttribute("aria-live", "polite");
                    if (button && button.parentNode) {
                        button.parentNode.insertBefore(status, button.nextSibling);
                    } else {
                        form.appendChild(status);
                    }
                }
                status.textContent = message;
                if (button) {
                    button.setAttribute("aria-busy", "true");
                    if (!button.getAttribute("data-cleg-label")) {
                        button.setAttribute("data-cleg-label", button.value || button.textContent || "");
                    }
                    if (button.tagName.toLowerCase() === "input") {
                        button.value = message;
                    } else {
                        button.textContent = message;
                    }
                    button.disabled = true;
                }
                return true;
            }
            var activeRequestRecording = null;
            function requestAudioInput(button){
                var form = button ? button.closest("form") : null;
                return form ? form.querySelector("[data-cleg-request-audio-input]") : null;
            }
            function requestRecordingStatus(button){
                var form = button ? button.closest("form") : null;
                return form ? form.querySelector("[data-cleg-request-recording-status]") : null;
            }
            function requestAudioPreview(input){
                var form = input ? input.closest("form") : null;
                return form ? form.querySelector("[data-cleg-request-audio-preview]") : null;
            }
            function requestAudioFallbackFields(context){
                var form = context ? context.closest("form") : null;
                return {
                    form: form,
                    data: form ? form.querySelector("[data-cleg-request-audio-data]") : null,
                    name: form ? form.querySelector("[data-cleg-request-audio-name]") : null,
                    type: form ? form.querySelector("[data-cleg-request-audio-type]") : null
                };
            }
            function clearRequestAudioFallback(context){
                var fields = requestAudioFallbackFields(context);
                if (fields.form) fields.form.removeAttribute("data-cleg-audio-fallback-pending");
                if (fields.data) fields.data.value = "";
                if (fields.name) fields.name.value = "";
                if (fields.type) fields.type.value = "";
            }
            function setRequestAudioFallback(context, file, blob, status){
                var fields = requestAudioFallbackFields(context);
                if (!fields.form || !fields.data || !window.FileReader) return;
                fields.form.setAttribute("data-cleg-audio-fallback-pending", "1");
                fields.data.value = "";
                if (fields.name) fields.name.value = file && file.name ? file.name : "solicitud-audio.webm";
                if (fields.type) fields.type.value = (file && file.type) || (blob && blob.type) || "audio/webm";
                if (status) status.textContent = "Procesando audio...";
                var reader = new FileReader();
                reader.onloadend = function(){
                    fields.data.value = String(reader.result || "");
                    fields.form.removeAttribute("data-cleg-audio-fallback-pending");
                    if (status) status.textContent = "Audio listo";
                };
                reader.onerror = function(){
                    fields.form.removeAttribute("data-cleg-audio-fallback-pending");
                    if (status) status.textContent = "Audio listo, verifica antes de enviar";
                };
                reader.readAsDataURL(blob);
            }
            function renderRequestAudioPreview(input){
                var preview = requestAudioPreview(input);
                if (!preview) return;
                var file = input && input.files && input.files.length ? input.files[0] : null;
                if (!file) {
                    preview.hidden = true;
                    preview.innerHTML = "";
                    return;
                }
                var url = URL.createObjectURL(file);
                preview.hidden = false;
                preview.innerHTML = "<strong>" + escapeHtml(file.name || "Nota de voz") + "</strong><audio controls preload=\"metadata\" src=\"" + escapeHtml(url) + "\"></audio><button class=\"cleg-proc-audio-remove\" type=\"button\" data-cleg-remove-request-audio aria-label=\"Borrar audio\">x</button>";
            }
            function showMicHelp(){
                var modal = document.querySelector(".cleg-proc-mic-help");
                if (!modal) {
                    modal = document.createElement("div");
                    modal.className = "cleg-proc-mic-help";
                    modal.innerHTML = "<div class=\"cleg-proc-mic-help-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"cleg-proc-mic-help-title\"><h3 id=\"cleg-proc-mic-help-title\">Activar microfono</h3><p>El navegador no pudo iniciar la grabacion. Revisa permisos y vuelve a intentar.</p><ul><li>iPhone / Safari: abre Ajustes, Safari, Microfono y permite acceso. Tambien revisa el icono Aa o permisos del sitio.</li><li>Android / Chrome: toca el candado de la barra, Permisos, Microfono y selecciona Permitir.</li><li>Si el telefono ya habia bloqueado el permiso, recarga esta pagina despues de cambiarlo.</li></ul><button class=\"cleg-proc-btn is-secondary\" type=\"button\" data-cleg-close-mic-help>Cerrar</button></div>";
                    document.body.appendChild(modal);
                }
                modal.classList.add("is-open");
            }
            function stopActiveRequestRecording(){
                if (!activeRequestRecording) return;
                if (activeRequestRecording.recorder && activeRequestRecording.recorder.state !== "inactive") {
                    activeRequestRecording.recorder.stop();
                }
            }
            function renderPrintDocument(sheet){
                return "<!doctype html><html><head><meta charset=\"utf-8\"><title>Ficha de requisicion</title><style>body{font-family:Arial,sans-serif;margin:24px;color:#06182d}.cleg-proc-print-sheet{display:block!important;max-width:820px;margin:0 auto}h2{font-size:24px;margin:0 0 6px}h3{font-size:14px;margin:18px 0 6px;text-transform:uppercase;color:#65707c}p{font-size:13px;line-height:1.45;margin:0 0 8px}dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0}dl div{border:1px solid #d8e0e7;border-radius:7px;padding:8px}dt{font-size:10px;font-weight:800;text-transform:uppercase;color:#65707c}dd{margin:2px 0 0;font-size:13px;font-weight:700}@media print{body{margin:12mm}button{display:none!important}}</style></head><body>" + sheet.outerHTML + "</body></html>";
            }
            function handlePrintSheet(button, action){
                var container = button ? button.closest("article,.cleg-proc-request-row") : null;
                var sheet = container ? container.querySelector("[data-cleg-print-sheet]") : null;
                if (!sheet) return;
                var html = renderPrintDocument(sheet);
                var titleNode = sheet.querySelector("h2");
                var title = (titleNode ? titleNode.textContent : "ficha-requisicion").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"") || "ficha-requisicion";
                var mode = action === true ? "download" : (action || "print");
                if (mode === "download") {
                    var blob = new Blob([html], {type:"text/html;charset=utf-8"});
                    var link = document.createElement("a");
                    link.href = URL.createObjectURL(blob);
                    link.download = title + ".html";
                    document.body.appendChild(link);
                    link.click();
                    setTimeout(function(){ URL.revokeObjectURL(link.href); link.remove(); }, 500);
                    return;
                }
                var win = window.open("", "_blank");
                if (!win) return;
                win.document.open();
                win.document.write(html);
                win.document.close();
                win.focus();
                if (mode === "print") {
                    setTimeout(function(){ win.print(); }, 350);
                }
            }
            function printAttachment(button){
                var url = button ? button.getAttribute("data-url") || "" : "";
                if (!url) return;
                var name = button.getAttribute("data-name") || "Adjunto";
                var kind = attachmentKind(url, button.getAttribute("data-kind") || "document");
                var content = "";
                if (kind === "image") {
                    content = "<img src=\"" + escapeHtml(url) + "\" alt=\"" + escapeHtml(name) + "\">";
                } else if (kind === "video") {
                    content = "<video controls src=\"" + escapeHtml(url) + "\"></video>";
                } else {
                    content = "<iframe title=\"" + escapeHtml(name) + "\" src=\"" + escapeHtml(url) + "\"></iframe>";
                }
                var html = "<!doctype html><html><head><meta charset=\"utf-8\"><title>" + escapeHtml(name) + "</title><style>body{margin:16px;font-family:Arial,sans-serif;color:#06182d}h1{font-size:16px;margin:0 0 12px}img,video{max-width:100%;max-height:88vh;display:block;margin:0 auto}iframe{width:100%;height:88vh;border:1px solid #d8e0e7}@media print{body{margin:10mm}iframe{height:92vh}}</style></head><body><h1>" + escapeHtml(name) + "</h1>" + content + "</body></html>";
                var win = window.open("", "_blank");
                if (!win) return;
                win.document.open();
                win.document.write(html);
                win.document.close();
                win.focus();
                setTimeout(function(){ win.print(); }, 550);
            }
            document.addEventListener("submit",function(event){
                var form = event.target.closest(".cleg-procurement form");
                if (!form) return;
                if (form.classList.contains("cleg-proc-attachment-manager")) return;
                if (form.getAttribute("data-cleg-audio-fallback-pending") === "1") {
                    event.preventDefault();
                    event.stopPropagation();
                    var pendingStatus = form.querySelector("[data-cleg-request-recording-status]");
                    if (pendingStatus) pendingStatus.textContent = "Preparando audio, intenta enviar de nuevo.";
                    return;
                }
                if (!markSubmitting(form)) {
                    event.preventDefault();
                    event.stopPropagation();
                }
            }, true);
            document.addEventListener("change",function(event){
                var attachmentSelect = event.target.closest("[data-cleg-attachment-select]");
                if (attachmentSelect) {
                    var manager = attachmentSelect.closest(".cleg-proc-attachment-manager");
                    if (manager) {
                        var selected = manager.querySelectorAll("[data-cleg-attachment-select]:checked").length;
                        manager.classList.toggle("has-selection", selected > 0);
                    }
                    return;
                }
                var statusSelect = event.target.closest("[data-cleg-proc-auto-status]");
                if (statusSelect) {
                    var form = statusSelect.closest("form");
                    if (!form || form.getAttribute("data-cleg-submitting") === "1") return;
                    var note = form.querySelector("[data-cleg-proc-auto-status-note]");
                    form.setAttribute("data-cleg-submitting", "1");
                    statusSelect.classList.add("is-saving");
                    if (note) note.textContent = "Guardando...";
                    if (typeof form.requestSubmit === "function") {
                        form.requestSubmit();
                    } else {
                        form.submit();
                    }
                    return;
                }
                var input = event.target.closest(".cleg-proc-attach-action input[type=file]");
                if (!input) return;
                render(input);
            });
            document.addEventListener("click",function(event){
                var downloadSelected = event.target.closest("[data-cleg-download-selected]");
                if (downloadSelected) {
                    event.preventDefault();
                    var managerForDownload = downloadSelected.closest(".cleg-proc-attachment-manager");
                    var selectedFiles = managerForDownload ? Array.prototype.slice.call(managerForDownload.querySelectorAll("[data-cleg-attachment-select]:checked")) : [];
                    if (!selectedFiles.length) {
                        alert("Selecciona al menos un adjunto para descargar.");
                        return;
                    }
                    selectedFiles.forEach(function(input, index){
                        var url = input.getAttribute("data-url") || "";
                        if (!url) return;
                        setTimeout(function(){
                            var link = document.createElement("a");
                            link.href = url;
                            link.target = "_blank";
                            link.rel = "noopener";
                            link.download = input.getAttribute("data-name") || "";
                            document.body.appendChild(link);
                            link.click();
                            link.remove();
                        }, index * 180);
                    });
                    return;
                }
                var viewRequest = event.target.closest("[data-cleg-view-request]");
                if (viewRequest) {
                    event.preventDefault();
                    handlePrintSheet(viewRequest, "view");
                    return;
                }
                var printRequest = event.target.closest("[data-cleg-print-request]");
                if (printRequest) {
                    event.preventDefault();
                    handlePrintSheet(printRequest, "print");
                    return;
                }
                var downloadRequest = event.target.closest("[data-cleg-download-request]");
                if (downloadRequest) {
                    event.preventDefault();
                    handlePrintSheet(downloadRequest, "download");
                    return;
                }
                var closeMicHelp = event.target.closest("[data-cleg-close-mic-help],.cleg-proc-mic-help");
                if (closeMicHelp && (event.target.classList.contains("cleg-proc-mic-help") || event.target.closest("[data-cleg-close-mic-help]"))) {
                    event.preventDefault();
                    closeMicHelp.closest(".cleg-proc-mic-help").classList.remove("is-open");
                    return;
                }
                var removeRequestAudio = event.target.closest("[data-cleg-remove-request-audio]");
                if (removeRequestAudio) {
                    event.preventDefault();
                    var formForRemove = removeRequestAudio.closest("form");
                    var inputForRemove = formForRemove ? formForRemove.querySelector("[data-cleg-request-audio-input]") : null;
                    var statusForRemove = formForRemove ? formForRemove.querySelector("[data-cleg-request-recording-status]") : null;
                    if (inputForRemove) {
                        syncInputFiles(inputForRemove, []);
                        renderRequestAudioPreview(inputForRemove);
                    }
                    clearRequestAudioFallback(removeRequestAudio);
                    if (statusForRemove) statusForRemove.textContent = "Nota de voz";
                    return;
                }
                var recordRequestAudio = event.target.closest("[data-cleg-record-request-audio]");
                if (recordRequestAudio) {
                    event.preventDefault();
                    if (!window.MediaRecorder || !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                        var unavailableStatus = requestRecordingStatus(recordRequestAudio);
                        if (unavailableStatus) unavailableStatus.textContent = "Microfono no disponible.";
                        showMicHelp();
                        return;
                    }
                    if (activeRequestRecording) {
                        stopActiveRequestRecording();
                        return;
                    }
                    var inputForAudio = requestAudioInput(recordRequestAudio);
                    var statusForAudio = requestRecordingStatus(recordRequestAudio);
                    navigator.mediaDevices.getUserMedia({audio:true}).then(function(stream){
                        var preferredTypes = ["audio/mp4", "audio/webm;codecs=opus", "audio/webm"];
                        var recorderOptions = {};
                        preferredTypes.some(function(type){
                            if (MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported(type)) {
                                recorderOptions.mimeType = type;
                                return true;
                            }
                            return false;
                        });
                        var recorder = new MediaRecorder(stream, recorderOptions);
                        var chunks = [];
                        activeRequestRecording = {recorder: recorder, stream: stream, chunks: chunks, input: inputForAudio, button: recordRequestAudio, status: statusForAudio};
                        recorder.addEventListener("dataavailable", function(event){
                            if (event.data && event.data.size) chunks.push(event.data);
                        });
                        recorder.addEventListener("stop", function(){
                            var type = recorder.mimeType || "audio/webm";
                            var blob = new Blob(chunks, {type:type});
                            var extension = type.indexOf("mp4") > -1 ? "m4a" : "webm";
                            var file = new File([blob], "solicitud-audio-" + Date.now() + "." + extension, {type:type});
                            setRequestAudioFallback(recordRequestAudio, file, blob, statusForAudio);
                            if (inputForAudio) {
                                syncInputFiles(inputForAudio, [file]);
                                renderRequestAudioPreview(inputForAudio);
                            }
                            stream.getTracks().forEach(function(track){ track.stop(); });
                            if (recordRequestAudio) {
                                recordRequestAudio.classList.remove("is-recording");
                                recordRequestAudio.setAttribute("aria-pressed", "false");
                            }
                            activeRequestRecording = null;
                        });
                        recorder.start();
                        recordRequestAudio.classList.add("is-recording");
                        recordRequestAudio.setAttribute("aria-pressed", "true");
                        if (statusForAudio) statusForAudio.textContent = "Grabando...";
                    }).catch(function(){
                        if (statusForAudio) statusForAudio.textContent = "No se pudo activar el microfono.";
                        showMicHelp();
                    });
                    return;
                }
                var printAttachmentButton = event.target.closest("[data-cleg-print-attachment]");
                if (printAttachmentButton) {
                    event.preventDefault();
                    printAttachment(printAttachmentButton);
                    return;
                }
                var previewButton = event.target.closest("[data-cleg-attachment-preview]");
                if (previewButton) {
                    event.preventDefault();
                    var modal = document.querySelector(".cleg-proc-attachment-modal");
                    if (!modal) {
                        modal = document.createElement("div");
                        modal.className = "cleg-proc-attachment-modal";
                        modal.innerHTML = "<div class=\"cleg-proc-attachment-modal-card\" role=\"dialog\" aria-modal=\"true\"><button type=\"button\" class=\"cleg-proc-attachment-modal-close\" aria-label=\"Cerrar\">Cerrar</button><strong class=\"cleg-proc-attachment-modal-title\"></strong><div class=\"cleg-proc-attachment-modal-body\"></div></div>";
                        document.body.appendChild(modal);
                    }
                    var url = previewButton.getAttribute("data-url") || "";
                    var name = previewButton.getAttribute("data-name") || "Adjunto";
                    var kind = attachmentKind(url, previewButton.getAttribute("data-kind") || "document");
                    var title = modal.querySelector(".cleg-proc-attachment-modal-title");
                    var body = modal.querySelector(".cleg-proc-attachment-modal-body");
                    if (title) title.textContent = name;
                    if (body) {
                        if (kind === "image") {
                            body.innerHTML = "<img src=\"" + escapeHtml(url) + "\" alt=\"" + escapeHtml(name) + "\"><a class=\"cleg-proc-btn is-secondary\" href=\"" + escapeHtml(url) + "\" target=\"_blank\" rel=\"noopener\">Abrir imagen completa</a>";
                        } else if (kind === "video") {
                            body.innerHTML = "<video controls playsinline src=\"" + escapeHtml(url) + "\"></video>";
                        } else if (kind === "audio") {
                            body.innerHTML = "<audio controls preload=\"metadata\" src=\"" + escapeHtml(url) + "\"></audio><a class=\"cleg-proc-btn is-secondary\" href=\"" + escapeHtml(url) + "\" target=\"_blank\" rel=\"noopener\">Abrir audio completo</a>";
                        } else {
                            body.innerHTML = "<iframe title=\"" + escapeHtml(name) + "\" src=\"" + escapeHtml(url) + "\"></iframe><a class=\"cleg-proc-btn is-secondary\" href=\"" + escapeHtml(url) + "\" target=\"_blank\" rel=\"noopener\">Abrir archivo completo</a>";
                        }
                    }
                    modal.classList.add("is-open");
                    return;
                }
                var closeModal = event.target.closest(".cleg-proc-attachment-modal-close,.cleg-proc-attachment-modal");
                if (closeModal && (event.target.classList.contains("cleg-proc-attachment-modal") || event.target.closest(".cleg-proc-attachment-modal-close"))) {
                    event.preventDefault();
                    closeModal.closest(".cleg-proc-attachment-modal").classList.remove("is-open");
                    return;
                }
                var remove = event.target.closest(".cleg-proc-attach-chip button");
                if (!remove) return;
                event.preventDefault();
                event.stopPropagation();
                var chip = remove.closest(".cleg-proc-attach-chip");
                var slot = remove.closest(".cleg-proc-attach-slot");
                var input = slot ? slot.querySelector("input[type=file]") : null;
                if (!chip || !input) return;
                var index = parseInt(chip.getAttribute("data-file-index"),10);
                var files = Array.prototype.slice.call(input.files || []).filter(function(file,fileIndex){return fileIndex !== index;});
                syncInputFiles(input, files);
                render(input);
            });
            document.addEventListener("submit",function(event){
                var manager = event.target.closest(".cleg-proc-attachment-manager");
                if (!manager) return;
                var single = event.submitter && event.submitter.name === "attachment_key_single";
                var checked = manager.querySelectorAll("input[name='attachment_keys[]']:checked").length;
                if (!single && checked < 1) {
                    event.preventDefault();
                    alert("Selecciona al menos un adjunto para eliminar.");
                    return;
                }
                if (!confirm(single ? "Eliminar este adjunto?" : "Eliminar los adjuntos seleccionados?")) {
                    event.preventDefault();
                }
            }, true);
        })();
        </script>
HTML;
    }
}
