if (!function_exists('cleg_starter_custom_roles')) {
    function cleg_starter_custom_roles() {
        $saved_roles = get_option('cleg_starter_custom_roles', array());
        if (!is_array($saved_roles)) {
            return array();
        }

        $roles = array();
        foreach ($saved_roles as $role_key => $role_data) {
            $role_key = sanitize_key($role_key);
            $role_label = isset($role_data['label']) ? sanitize_text_field($role_data['label']) : '';
            $role_caps = isset($role_data['caps']) && is_array($role_data['caps']) ? $role_data['caps'] : array();

            if ($role_key === '' || $role_label === '') {
                continue;
            }

            $caps = array('read' => true);
            foreach (cleg_starter_capabilities() as $capability) {
                $caps[$capability] = !empty($role_caps[$capability]);
            }

            $roles[$role_key] = array(
                'label' => $role_label,
                'description' => isset($role_data['description']) ? sanitize_text_field($role_data['description']) : '',
                'caps' => $caps,
            );
        }

        return $roles;
    }
}

