if (!function_exists('cleg_starter_capability_labels')) {
    function cleg_starter_capability_labels() {
        $labels = array();

        foreach (cleg_starter_capability_matrix() as $module) {
            foreach ($module['permissions'] as $capability => $permission) {
                $labels[$capability] = $permission['label'];
            }
        }

        return $labels;
    }
}

