if (!function_exists('cleg_starter_caps_from_template')) {
    function cleg_starter_caps_from_template($template_key) {
        $templates = cleg_starter_role_templates();
        $template_key = sanitize_key($template_key);
        return isset($templates[$template_key]['caps']) ? array_values($templates[$template_key]['caps']) : array('cleg_access_portal');
    }
}

if (!function_exists('cleg_starter_role_caps')) {
    function cleg_starter_role_caps($role_key) {
        $role = get_role($role_key);
        $caps = array();

        foreach (cleg_starter_capabilities() as $capability) {
            if ($role && $role->has_cap($capability)) {
                $caps[] = $capability;
            }
        }

        return $caps;
    }
}

if (!function_exists('cleg_starter_caps_summary')) {
    function cleg_starter_caps_summary($caps, $limit = 7) {
        $labels = cleg_starter_capability_labels();
        $human = array();

        foreach ((array) $caps as $capability) {
            if (isset($labels[$capability])) {
                $human[] = strtolower($labels[$capability]);
            }
        }

        if (!$human) {
            return 'Este rol no tiene permisos operativos seleccionados todavia.';
        }

        $shown = array_slice($human, 0, $limit);
        $extra = count($human) - count($shown);
        $summary = 'Este rol podra: ' . implode(', ', $shown);

        if ($extra > 0) {
            $summary .= ' y ' . $extra . ' permisos adicionales';
        }

        return $summary . '.';
    }
}

if (!function_exists('cleg_starter_role_user_count')) {
    function cleg_starter_role_user_count($role_key) {
        $users = get_users(array(
            'role' => $role_key,
            'fields' => 'ID',
            'number' => 1,
        ));

        if (empty($users)) {
            return 0;
        }

        $count = count_users();
        return isset($count['avail_roles'][$role_key]) ? (int) $count['avail_roles'][$role_key] : count($users);
    }
}


if (!function_exists('cleg_starter_ensure_roles')) {
    function cleg_starter_ensure_roles() {
        foreach (cleg_starter_roles() as $role_key => $role_data) {
            $role = get_role($role_key);

            if (!$role) {
                add_role($role_key, $role_data['label'], $role_data['caps']);
                continue;
            }

            foreach ($role_data['caps'] as $capability => $enabled) {
                if ($enabled && !$role->has_cap($capability)) {
                    $role->add_cap($capability);
                }
            }
        }

        $administrator = get_role('administrator');
        if ($administrator) {
            foreach (cleg_starter_capabilities() as $capability) {
                if (!$administrator->has_cap($capability)) {
                    $administrator->add_cap($capability);
                }
            }
        }
    }
}

add_action('init', 'cleg_starter_ensure_roles', 3);

