if (!function_exists('cleg_starter_current_path')) {
    function cleg_starter_current_path() {
        $path = isset($_SERVER['REQUEST_URI']) ? wp_parse_url(esc_url_raw(wp_unslash($_SERVER['REQUEST_URI'])), PHP_URL_PATH) : '/';
        $path = trim((string) $path, '/');
        return $path;
    }
}

if (!function_exists('cleg_starter_handle_redirects')) {
    function cleg_starter_handle_redirects() {
        if (is_admin() || wp_doing_ajax()) {
            return;
        }

        $path = cleg_starter_current_path();
        $redirects = cleg_starter_redirects();

        if (!isset($redirects[$path])) {
            return;
        }

        wp_safe_redirect(home_url('/' . trim($redirects[$path], '/') . '/'), 301);
        exit;
    }
}

add_action('template_redirect', 'cleg_starter_handle_redirects', 0);

if (!function_exists('cleg_starter_is_access_page')) {
    function cleg_starter_is_access_page() {
        return !is_admin() && !wp_doing_ajax() && (is_page('acceso') || is_page(259));
    }
}

if (!function_exists('cleg_starter_body_classes')) {
    function cleg_starter_body_classes($classes) {
        if (cleg_starter_is_access_page()) {
            $classes[] = 'cleg-page-access';
            $classes[] = 'cleg-module-access-login';
        }

        if (!is_admin() && !wp_doing_ajax() && is_page(array(
            'panel',
            'admin-horas',
            'admin-tiempo-real',
            'admin-dispositivos',
            'payroll-rrhh',
            'payroll-reportes',
            'admin-rrhh',
            'empleados',
            'mis-nominas',
        ))) {
            $classes[] = 'cleg-page-internal';
        }

        if (get_stylesheet() === 'astra') {
            $classes[] = 'cleg-theme-compat-astra';
        }

        return array_values(array_unique($classes));
    }
}

add_filter('body_class', 'cleg_starter_body_classes', 20);

