if (!function_exists('cleg_starter_strip_access_login_custom_css')) {
    function cleg_starter_strip_access_login_custom_css($css, $stylesheet = '') {
        if (!is_string($css) || $css === '') {
            return $css;
        }

        $start = strpos($css, '/* Acceso trabajadores */');
        if ($start === false) {
            return $css;
        }

        $end = strpos($css, '/* Portal interno RRHH: shell minimo temprano */', $start);
        if ($end === false) {
            return $css;
        }

        return rtrim(substr($css, 0, $start)) . "\n\n" . ltrim(substr($css, $end));
    }
}

