if (!function_exists('cleg_starter_readiness')) {
    function cleg_starter_readiness() {
        $pages = array();

        foreach (cleg_starter_required_pages() as $key => $page) {
            if ($page['slug'] === '') {
                $pages[$key] = array(
                    'label' => $page['label'],
                    'slug' => '/',
                    'exists' => (bool) get_option('page_on_front'),
                );
                continue;
            }

            $found = get_page_by_path($page['slug']);
            $pages[$key] = array(
                'label' => $page['label'],
                'slug' => '/' . $page['slug'] . '/',
                'exists' => (bool) $found,
                'status' => $found ? get_post_status($found) : 'missing',
            );
        }

        $roles = array();
        foreach (cleg_starter_roles() as $role_key => $role_data) {
            $roles[$role_key] = (bool) get_role($role_key);
        }

        return array(
            'roles' => $roles,
            'pages' => $pages,
            'theme' => wp_get_theme()->get('Name'),
            'stylesheet' => get_stylesheet(),
            'permalink_structure' => get_option('permalink_structure'),
            'timezone' => get_option('timezone_string'),
        );
    }
}

if (!function_exists('cleg_starter_can_manage_roles')) {
    function cleg_starter_can_manage_roles() {
        if (!is_user_logged_in()) {
            return false;
        }

        if (current_user_can('manage_options') || current_user_can('cleg_manage_roles') || current_user_can('cleg_manage_tenant')) {
            return true;
        }

        $user = wp_get_current_user();
        $roles = is_object($user) && isset($user->roles) ? (array) $user->roles : array();
        return (bool) array_intersect($roles, array('administrator', 'cleg_technical_admin'));
    }
}

if (!function_exists('cleg_starter_roles_admin_url')) {
    function cleg_starter_roles_admin_url(array $args = array()) {
        $base = function_exists('cleg_tenant_admin_tab_url')
            ? cleg_tenant_admin_tab_url('roles')
            : add_query_arg('cleg_tenant_tab', 'roles', home_url('/administracion/'));

        return empty($args) ? $base : add_query_arg($args, $base);
    }
}

if (!function_exists('cleg_starter_assignable_roles')) {
    function cleg_starter_assignable_roles() {
        $roles = cleg_starter_roles();
        $choices = array();

        foreach ($roles as $role_key => $role_data) {
            $choices[$role_key] = $role_data['label'];
        }

        return $choices;
    }
}

if (!function_exists('cleg_starter_role_key_by_label')) {
    function cleg_starter_role_key_by_label($role_label) {
        $role_label = sanitize_text_field($role_label);

        foreach (cleg_starter_assignable_roles() as $role_key => $label) {
            if (strcasecmp($role_label, sanitize_text_field($label)) === 0) {
                return $role_key;
            }
        }

        return '';
    }
}

if (!function_exists('cleg_starter_user_can_command_center')) {
    function cleg_starter_user_can_command_center() {
        return current_user_can('manage_options')
            || current_user_can('cleg_manage_rrhh')
            || current_user_can('cleg_manage_procurement');
    }
}

if (!function_exists('cleg_starter_user_can_rrhh')) {
    function cleg_starter_user_can_rrhh() {
        return current_user_can('manage_options')
            || current_user_can('edit_pages')
            || current_user_can('cleg_access_rrhh')
            || current_user_can('cleg_manage_rrhh');
    }
}

if (!function_exists('cleg_starter_user_can_procurement')) {
    function cleg_starter_user_can_procurement() {
        return current_user_can('manage_options')
            || current_user_can('cleg_access_procurement')
            || current_user_can('cleg_manage_procurement');
    }
}

if (!function_exists('cleg_starter_handle_role_update')) {
    function cleg_starter_handle_role_update() {
        if (!cleg_starter_can_manage_roles()) {
            wp_die(esc_html__('No autorizado.', 'cleg'));
        }

        check_admin_referer('cleg_starter_update_user_role');

        $user_id = isset($_POST['user_id']) ? absint($_POST['user_id']) : 0;
        $new_role = isset($_POST['cleg_role']) ? sanitize_key(wp_unslash($_POST['cleg_role'])) : '';
        $assignable = cleg_starter_assignable_roles();

        if (!$user_id || !isset($assignable[$new_role])) {
            wp_die(esc_html__('Rol invalido.', 'cleg'));
        }

        if ((int) get_current_user_id() === (int) $user_id) {
            wp_die(esc_html__('No puedes cambiar tu propio rol desde este panel.', 'cleg'));
        }

        $user = get_userdata($user_id);
        if (!$user) {
            wp_die(esc_html__('Usuario no encontrado.', 'cleg'));
        }

        $old_roles = (array) $user->roles;
        $updated = wp_update_user(array(
            'ID' => $user_id,
            'role' => $new_role,
        ));

        if (is_wp_error($updated)) {
            wp_die(esc_html($updated->get_error_message()));
        }

        update_user_meta($user_id, '_cleg_role_last_changed', array(
            'changed_at' => current_time('mysql'),
            'changed_by' => get_current_user_id(),
            'old_roles' => array_values($old_roles),
            'new_role' => $new_role,
        ));

        wp_safe_redirect(cleg_starter_roles_admin_url(array(
            'cleg_role_updated' => '1',
        )));
        exit;
    }
}

add_action('admin_post_cleg_starter_update_user_role', 'cleg_starter_handle_role_update');

if (!function_exists('cleg_starter_role_key_from_label')) {
    function cleg_starter_role_key_from_label($label) {
        $base = sanitize_title($label);
        $base = str_replace('-', '_', $base);
        $base = sanitize_key($base);

        if ($base === '') {
            $base = 'role';
        }

        if (strpos($base, 'cleg_') !== 0) {
            $base = 'cleg_' . $base;
        }

        return $base;
    }
}

if (!function_exists('cleg_starter_reserved_role_keys')) {
    function cleg_starter_reserved_role_keys() {
        return array(
            'administrator',
            'editor',
            'author',
            'contributor',
            'subscriber',
        );
    }
}

if (!function_exists('cleg_starter_role_can_be_edited')) {
    function cleg_starter_role_can_be_edited($role_key) {
        $role_key = sanitize_key($role_key);
        return $role_key !== 'administrator' && !in_array($role_key, cleg_starter_reserved_role_keys(), true);
    }
}

if (!function_exists('cleg_starter_audit_role_change')) {
    function cleg_starter_audit_role_change($event, $role_key, $before, $after) {
        $audit = get_option('cleg_starter_role_audit_log', array());
        if (!is_array($audit)) {
            $audit = array();
        }

        array_unshift($audit, array(
            'event' => sanitize_key($event),
            'role_key' => sanitize_key($role_key),
            'changed_at' => current_time('mysql'),
            'changed_by' => get_current_user_id(),
            'before' => $before,
            'after' => $after,
        ));

        $audit = array_slice($audit, 0, 80);
        update_option('cleg_starter_role_audit_log', $audit, false);
    }
}

if (!function_exists('cleg_starter_handle_role_create')) {
    function cleg_starter_handle_role_create() {
        if (!cleg_starter_can_manage_roles()) {
            wp_die(esc_html__('No autorizado.', 'cleg'));
        }

        check_admin_referer('cleg_starter_create_role');

        $role_label = isset($_POST['role_label']) ? sanitize_text_field(wp_unslash($_POST['role_label'])) : '';
        $role_key = isset($_POST['role_key']) ? sanitize_key(wp_unslash($_POST['role_key'])) : '';
        $role_description = isset($_POST['role_description']) ? sanitize_text_field(wp_unslash($_POST['role_description'])) : '';
        $template_key = isset($_POST['role_template']) ? sanitize_key(wp_unslash($_POST['role_template'])) : 'custom';

        if ($role_label === '') {
            wp_die(esc_html__('El nombre del rol es obligatorio.', 'cleg'));
        }

        if ($role_key === '') {
            $role_key = cleg_starter_role_key_from_label($role_label);
        } else {
            $role_key = cleg_starter_role_key_from_label($role_key);
        }

        if (in_array($role_key, cleg_starter_reserved_role_keys(), true) || get_role($role_key)) {
            wp_die(esc_html__('Ya existe un rol con ese identificador.', 'cleg'));
        }

        $selected = isset($_POST['cleg_caps']) && is_array($_POST['cleg_caps'])
            ? array_map('sanitize_key', wp_unslash($_POST['cleg_caps']))
            : cleg_starter_caps_from_template($template_key);

        $caps = array('read' => true);
        foreach (cleg_starter_capabilities() as $capability) {
            $caps[$capability] = in_array($capability, $selected, true);
        }

        $custom_roles = get_option('cleg_starter_custom_roles', array());
        if (!is_array($custom_roles)) {
            $custom_roles = array();
        }

        $custom_roles[$role_key] = array(
            'label' => $role_label,
            'description' => $role_description,
            'template' => $template_key,
            'caps' => $caps,
            'created_at' => current_time('mysql'),
            'created_by' => get_current_user_id(),
        );

        update_option('cleg_starter_custom_roles', $custom_roles, false);
        add_role($role_key, $role_label, $caps);
        cleg_starter_audit_role_change('created', $role_key, array(), $custom_roles[$role_key]);

        wp_safe_redirect(cleg_starter_roles_admin_url(array(
            'cleg_role_created' => $role_key,
        )));
        exit;
    }
}

add_action('admin_post_cleg_starter_create_role', 'cleg_starter_handle_role_create');

if (!function_exists('cleg_starter_handle_role_permissions_update')) {
    function cleg_starter_handle_role_permissions_update() {
        if (!cleg_starter_can_manage_roles()) {
            wp_die(esc_html__('No autorizado.', 'cleg'));
        }

        check_admin_referer('cleg_starter_update_role_permissions');

        $role_key = isset($_POST['role_key']) ? sanitize_key(wp_unslash($_POST['role_key'])) : '';
        $assignable = cleg_starter_assignable_roles();

        if (!$role_key || !isset($assignable[$role_key]) || !cleg_starter_role_can_be_edited($role_key)) {
            wp_die(esc_html__('Rol invalido.', 'cleg'));
        }

        $role = get_role($role_key);
        if (!$role) {
            wp_die(esc_html__('Rol no encontrado.', 'cleg'));
        }

        $selected = isset($_POST['cleg_caps']) && is_array($_POST['cleg_caps'])
            ? array_map('sanitize_key', wp_unslash($_POST['cleg_caps']))
            : array();

        $allowed = cleg_starter_capabilities();
        $old_caps = cleg_starter_role_caps($role_key);
        $description = isset($_POST['role_description']) ? sanitize_text_field(wp_unslash($_POST['role_description'])) : cleg_starter_role_description($role_key);

        $current_user = wp_get_current_user();
        $current_roles = $current_user ? (array) $current_user->roles : array();
        if (!current_user_can('manage_options') && in_array($role_key, $current_roles, true) && !in_array('cleg_manage_roles', $selected, true)) {
            wp_die(esc_html__('No puedes quitarte a ti mismo el permiso de administrar roles.', 'cleg'));
        }

        $role->add_cap('read');
        foreach ($allowed as $capability) {
            if (in_array($capability, $selected, true)) {
                $role->add_cap($capability);
            } else {
                $role->remove_cap($capability);
            }
        }

        $custom_roles = get_option('cleg_starter_custom_roles', array());
        if (is_array($custom_roles) && isset($custom_roles[$role_key])) {
            $custom_caps = array('read' => true);
            foreach ($allowed as $capability) {
                $custom_caps[$capability] = in_array($capability, $selected, true);
            }
            $custom_roles[$role_key]['description'] = $description;
            $custom_roles[$role_key]['caps'] = $custom_caps;
            $custom_roles[$role_key]['updated_at'] = current_time('mysql');
            $custom_roles[$role_key]['updated_by'] = get_current_user_id();
            update_option('cleg_starter_custom_roles', $custom_roles, false);
        }

        cleg_starter_audit_role_change('permissions_updated', $role_key, $old_caps, array_values($selected));

        update_option('cleg_starter_role_permissions_last_changed', array(
            'changed_at' => current_time('mysql'),
            'changed_by' => get_current_user_id(),
            'role_key' => $role_key,
            'caps' => array_values($selected),
        ), false);

        wp_safe_redirect(cleg_starter_roles_admin_url(array(
            'cleg_permissions_updated' => $role_key,
        )));
        exit;
    }
}

add_action('admin_post_cleg_starter_update_role_permissions', 'cleg_starter_handle_role_permissions_update');

if (!function_exists('cleg_starter_is_custom_role')) {
    function cleg_starter_is_custom_role($role_key) {
        $custom_roles = get_option('cleg_starter_custom_roles', array());
        return is_array($custom_roles) && isset($custom_roles[sanitize_key($role_key)]);
    }
}

if (!function_exists('cleg_starter_handle_role_duplicate')) {
    function cleg_starter_handle_role_duplicate() {
        if (!cleg_starter_can_manage_roles()) {
            wp_die(esc_html__('No autorizado.', 'cleg'));
        }

        check_admin_referer('cleg_starter_duplicate_role');

        $source_key = isset($_POST['role_key']) ? sanitize_key(wp_unslash($_POST['role_key'])) : '';
        $source_role = get_role($source_key);
        $assignable = cleg_starter_assignable_roles();

        if (!$source_key || !$source_role || !isset($assignable[$source_key])) {
            wp_die(esc_html__('Rol fuente invalido.', 'cleg'));
        }

        $base_label = cleg_starter_role_label($source_key) . ' copia';
        $new_key = cleg_starter_role_key_from_label($base_label);
        $index = 2;
        while (get_role($new_key)) {
            $new_key = cleg_starter_role_key_from_label($base_label . ' ' . $index);
            $index++;
        }

        $caps = array('read' => true);
        foreach (cleg_starter_capabilities() as $capability) {
            $caps[$capability] = $source_role->has_cap($capability);
        }

        $custom_roles = get_option('cleg_starter_custom_roles', array());
        if (!is_array($custom_roles)) {
            $custom_roles = array();
        }

        $custom_roles[$new_key] = array(
            'label' => $base_label,
            'description' => 'Duplicado de ' . cleg_starter_role_label($source_key) . '. Revisar permisos antes de asignar usuarios.',
            'template' => 'duplicated',
            'caps' => $caps,
            'created_at' => current_time('mysql'),
            'created_by' => get_current_user_id(),
            'source_role' => $source_key,
        );

        update_option('cleg_starter_custom_roles', $custom_roles, false);
        add_role($new_key, $base_label, $caps);
        cleg_starter_audit_role_change('duplicated', $new_key, array('source_role' => $source_key), $custom_roles[$new_key]);

        wp_safe_redirect(cleg_starter_roles_admin_url(array(
            'cleg_role_created' => $new_key,
        )));
        exit;
    }
}

add_action('admin_post_cleg_starter_duplicate_role', 'cleg_starter_handle_role_duplicate');

if (!function_exists('cleg_starter_handle_role_delete')) {
    function cleg_starter_handle_role_delete() {
        if (!cleg_starter_can_manage_roles()) {
            wp_die(esc_html__('No autorizado.', 'cleg'));
        }

        check_admin_referer('cleg_starter_delete_role');

        $role_key = isset($_POST['role_key']) ? sanitize_key(wp_unslash($_POST['role_key'])) : '';

        if (!$role_key || !cleg_starter_role_can_be_edited($role_key) || !cleg_starter_is_custom_role($role_key)) {
            wp_die(esc_html__('Solo se pueden eliminar roles CLEG personalizados.', 'cleg'));
        }

        if (cleg_starter_role_user_count($role_key) > 0) {
            wp_die(esc_html__('No se puede eliminar un rol asignado a usuarios reales.', 'cleg'));
        }

        $custom_roles = get_option('cleg_starter_custom_roles', array());
        $before = is_array($custom_roles) && isset($custom_roles[$role_key]) ? $custom_roles[$role_key] : array();

        if (is_array($custom_roles) && isset($custom_roles[$role_key])) {
            unset($custom_roles[$role_key]);
            update_option('cleg_starter_custom_roles', $custom_roles, false);
        }

        remove_role($role_key);
        cleg_starter_audit_role_change('deleted', $role_key, $before, array());

        wp_safe_redirect(cleg_starter_roles_admin_url(array(
            'cleg_role_deleted' => '1',
        )));
        exit;
    }
}

add_action('admin_post_cleg_starter_delete_role', 'cleg_starter_handle_role_delete');

