                        <?php endforeach; ?>
                    </div>
                </article>
            </div>
        </section>
        <script>
        (function(){
            var root = document.querySelector('.cleg-starter-roles');
            if (!root) { return; }
            var templates = {};
            var labels = {};
            try { templates = JSON.parse(root.getAttribute('data-cleg-role-templates') || '{}'); } catch(e) {}
            try { labels = JSON.parse(root.getAttribute('data-cleg-cap-labels') || '{}'); } catch(e) {}
            function slugify(value) {
                value = (value || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
                value = value.replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
                return value.indexOf('cleg_') === 0 ? value : 'cleg_' + (value || 'role');
            }
            function updateSummary(form) {
                var selected = Array.prototype.slice.call(form.querySelectorAll('input[name="cleg_caps[]"]:checked')).map(function(input){ return input.value; });
                var human = selected.map(function(cap){ return (labels[cap] || cap).toLowerCase(); }).slice(0, 7);
                var summary = form.querySelector('[data-cleg-summary]');
                if (!summary) { return; }
                if (!human.length) {
                    summary.textContent = 'Este rol no tiene permisos operativos seleccionados todavia.';
                    return;
                }
                var extra = selected.length - human.length;
                summary.textContent = 'Este rol podra: ' + human.join(', ') + (extra > 0 ? ' y ' + extra + ' permisos adicionales' : '') + '.';
            }
            root.querySelectorAll('[data-cleg-role-form]').forEach(function(form){
                var label = form.querySelector('[data-cleg-role-label]');
                var key = form.querySelector('[data-cleg-role-key]');
                var template = form.querySelector('[data-cleg-role-template]');
                if (label && key) {
                    label.addEventListener('input', function(){
                        if (!key.dataset.manual) { key.value = slugify(label.value); }
                    });
                    key.addEventListener('input', function(){ key.dataset.manual = '1'; });
                }
                if (template) {
                    template.addEventListener('change', function(){
                        var caps = templates[template.value] || ['cleg_access_portal'];
                        form.querySelectorAll('input[name="cleg_caps[]"]').forEach(function(input){
                            input.checked = caps.indexOf(input.value) !== -1;
                        });
                        updateSummary(form);
                    });
                    template.dispatchEvent(new Event('change'));
                } else {
                    updateSummary(form);
                }
                form.querySelectorAll('input[name="cleg_caps[]"]').forEach(function(input){
                    input.addEventListener('change', function(){ updateSummary(form); });
                });
            });
        })();
        </script>
        <?php
        return ob_get_clean();
    }
}

