if (!function_exists('cleg_starter_admin_notice')) {
    function cleg_starter_admin_notice() {
        if (!current_user_can('manage_options')) {
            return;
        }

        $screen = function_exists('get_current_screen') ? get_current_screen() : null;
        if (!$screen || $screen->base !== 'dashboard') {
            return;
        }

        $readiness = cleg_starter_readiness();
        $missing_pages = array();

        foreach ($readiness['pages'] as $page) {
            if (empty($page['exists'])) {
                $missing_pages[] = $page['slug'];
            }
        }

        if (!$missing_pages) {
            return;
        }

        echo '<div class="notice notice-warning"><p><strong>CLEG Starter Core:</strong> paginas faltantes detectadas: '
            . esc_html(implode(', ', $missing_pages))
            . '. No se crearan automaticamente hasta aprobar el instalador.</p></div>';
    }
}

