 */
/**
 * CLEG 22 - Worker Android REST API v0.1
 *
 * Endpoints for the native Android worker app.
 * Scope: login, status, and clock actions. Does not modify the web/PWA worker panel.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!defined('CLEG_WORKER_ANDROID_TOKEN_TTL')) {
    define('CLEG_WORKER_ANDROID_TOKEN_TTL', 30 * DAY_IN_SECONDS);
}

if (!function_exists('cleg_worker_android_token_key')) {
    function cleg_worker_android_token_key($token) {
        return 'cleg_worker_android_token_' . hash('sha256', (string) $token);
    }
}

if (!function_exists('cleg_worker_android_error')) {
    function cleg_worker_android_error($code, $message, $status = 400, $extra = array()) {
        return new WP_Error(
            sanitize_key($code),
            sanitize_text_field($message),
            array_merge(array('status' => (int) $status), is_array($extra) ? $extra : array())
        );
    }
}

if (!function_exists('cleg_worker_android_authorize')) {
    function cleg_worker_android_authorize(WP_REST_Request $request) {
        $header = (string) $request->get_header('authorization');

        if (!preg_match('/Bearer\s+(.+)/i', $header, $matches)) {
            return cleg_worker_android_error('missing_token', 'Sesion expirada. Vuelve a entrar.', 401);
        }

        $token = trim($matches[1]);
        $user_id = (int) get_transient(cleg_worker_android_token_key($token));

        if ($user_id <= 0) {
            return cleg_worker_android_error('invalid_token', 'Sesion expirada. Vuelve a entrar.', 401);
        }

        $user = get_user_by('id', $user_id);

        if (!$user || empty($user->ID)) {
            return cleg_worker_android_error('invalid_user', 'Usuario no encontrado.', 401);
        }

        $employee = function_exists('cleg_app_get_employee') ? cleg_app_get_employee($user) : false;

        if (function_exists('cleg_app_user_can_worker') && !cleg_app_user_can_worker($user, $employee)) {
            return cleg_worker_android_error('forbidden', 'Tu usuario no tiene acceso trabajador.', 403);
        }

        set_transient(cleg_worker_android_token_key($token), (int) $user->ID, CLEG_WORKER_ANDROID_TOKEN_TTL);

        return $user;
    }
}

if (!function_exists('cleg_worker_android_job_sites_payload')) {
    function cleg_worker_android_job_sites_payload() {
        $jobs = function_exists('cleg_app_get_job_sites') ? cleg_app_get_job_sites() : array();

        if (is_wp_error($jobs)) {
            return array();
        }

        $payload = array();

        foreach ((array) $jobs as $job) {
            $payload[] = array(
                'name' => isset($job['name']) ? sanitize_text_field($job['name']) : '',
                'latitude' => isset($job['latitude']) ? $job['latitude'] : null,
                'longitude' => isset($job['longitude']) ? $job['longitude'] : null,
                'radiusMeters' => isset($job['radius']) ? (float) $job['radius'] : null,
            );
        }

        return array_values(array_filter($payload, function ($job) {
            return !empty($job['name']);
        }));
    }
}

if (!function_exists('cleg_worker_android_entries_payload')) {
    function cleg_worker_android_entries_payload($user) {
        $entries = function_exists('cleg_app_get_week_entries') ? cleg_app_get_week_entries($user) : array();
        $payload = array();

        foreach ((array) $entries as $entry) {
            $payload[] = array(
                'date' => isset($entry['date']) ? sanitize_text_field($entry['date']) : '',
                'jobSite' => isset($entry['job_site']) ? sanitize_text_field($entry['job_site']) : 'Proyecto',
                'clockIn' => !empty($entry['in']) && function_exists('cleg_app_format_time_label') ? cleg_app_format_time_label($entry['in']) : '',
                'clockOut' => !empty($entry['out']) && function_exists('cleg_app_format_time_label') ? cleg_app_format_time_label($entry['out']) : '',
                'hoursLabel' => isset($entry['hours']) && function_exists('cleg_app_hours_label') ? cleg_app_hours_label($entry['hours']) : '',
                'status' => isset($entry['status']) ? sanitize_text_field($entry['status']) : '',
            );
        }

        return $payload;
    }
}

if (!function_exists('cleg_worker_android_status_payload')) {
    function cleg_worker_android_status_payload($user) {
        $open_entry = function_exists('cleg_app_get_open_entry') ? cleg_app_get_open_entry($user) : false;
        $week_entries = function_exists('cleg_app_get_week_entries') ? cleg_app_get_week_entries($user) : array();
        $summary = function_exists('cleg_app_entries_summary') ? cleg_app_entries_summary($week_entries) : array('hours' => '');

        return array(
            'displayName' => sanitize_text_field($user->display_name ?: $user->user_login),
            'isWorking' => !empty($open_entry),
            'activeJobSite' => !empty($open_entry['job_site']) ? sanitize_text_field($open_entry['job_site']) : null,
            'clockInTime' => !empty($open_entry['clock_in_time']) ? sanitize_text_field($open_entry['clock_in_time']) : null,
            'weekHoursLabel' => isset($summary['hours']) ? sanitize_text_field($summary['hours']) : '',
            'jobs' => cleg_worker_android_job_sites_payload(),
            'recentEntries' => cleg_worker_android_entries_payload($user),
        );
    }
}

if (!function_exists('cleg_worker_android_login')) {
    function cleg_worker_android_login(WP_REST_Request $request) {
        $username = sanitize_user((string) $request->get_param('username'));
        $password = (string) $request->get_param('password');

        if ($username === '' || $password === '') {
            return cleg_worker_android_error('missing_login', 'Escribe usuario y contrasena.', 422);
        }

        $user = wp_authenticate($username, $password);

        if (is_wp_error($user) || !$user || empty($user->ID)) {
            return cleg_worker_android_error('bad_login', 'Usuario o contrasena incorrectos.', 401);
        }

        $employee = function_exists('cleg_app_get_employee') ? cleg_app_get_employee($user) : false;

        if (function_exists('cleg_app_user_can_worker') && !cleg_app_user_can_worker($user, $employee)) {
            return cleg_worker_android_error('forbidden', 'Tu usuario no tiene acceso trabajador.', 403);
        }

        $token = wp_generate_password(64, false, false);
        set_transient(cleg_worker_android_token_key($token), (int) $user->ID, CLEG_WORKER_ANDROID_TOKEN_TTL);

        return rest_ensure_response(array(
            'token' => $token,
            'displayName' => sanitize_text_field($user->display_name ?: $user->user_login),
        ));
    }
}

if (!function_exists('cleg_worker_android_status')) {
    function cleg_worker_android_status(WP_REST_Request $request) {
        $user = cleg_worker_android_authorize($request);

        if (is_wp_error($user)) {
            return $user;
        }

        return rest_ensure_response(cleg_worker_android_status_payload($user));
    }
}

if (!function_exists('cleg_worker_android_clock')) {
    function cleg_worker_android_clock(WP_REST_Request $request) {
        $user = cleg_worker_android_authorize($request);

        if (is_wp_error($user)) {
            return $user;
        }

        if (!function_exists('cleg_app_airtable_is_configured') || !cleg_app_airtable_is_configured()) {
            return cleg_worker_android_error('airtable_missing', 'No se pudo conectar con la oficina. Intenta de nuevo.', 500);
        }

        $open_entry = function_exists('cleg_app_get_open_entry') ? cleg_app_get_open_entry($user) : false;
        $is_clock_out = !empty($open_entry);
        $mode = sanitize_text_field((string) $request->get_param('mode'));
        $is_project_switch = $is_clock_out && $mode === 'switch_project';
        $job_site = sanitize_text_field((string) $request->get_param('jobSite'));
        $note = sanitize_textarea_field((string) $request->get_param('note'));
        $device_id = sanitize_text_field((string) $request->get_param('deviceId'));
        $captured_at = sanitize_text_field((string) $request->get_param('capturedAt'));
        $latitude = sanitize_text_field((string) $request->get_param('latitude'));
        $longitude = sanitize_text_field((string) $request->get_param('longitude'));
        $accuracy = sanitize_text_field((string) $request->get_param('accuracy'));
        $event_time = function_exists('cleg_app_iso_time') ? cleg_app_iso_time($captured_at) : gmdate('c');
        $map_link = function_exists('cleg_app_map_link') ? cleg_app_map_link($latitude, $longitude) : '';
        $employee_name = sanitize_text_field($user->display_name ?: $user->user_login);
        $employee_email = !empty($user->user_email) ? sanitize_email($user->user_email) : '';
        $portal_username = sanitize_user($user->user_login);
        $ip_address = function_exists('cleg_app_get_client_ip') ? cleg_app_get_client_ip() : '';
        $user_agent = function_exists('cleg_app_get_user_agent') ? cleg_app_get_user_agent() : '';
        $previous_device_user = function_exists('cleg_app_find_previous_device_user') ? cleg_app_find_previous_device_user($device_id, $user) : '';
        $audit_flags = array();
        $review_job_site = $is_clock_out && !$is_project_switch && $open_entry ? $open_entry['job_site'] : $job_site;
        $gps_review = function_exists('cleg_app_location_review') ? cleg_app_location_review($review_job_site, $latitude, $longitude, $accuracy, '0', '') : array(
            'required' => false,
            'reasons' => array(),
            'audit_flags' => array(),
            'distance' => '',
            'note' => '',
        );
        $temporary_job_site = stripos($review_job_site, 'Proyecto Temporal') !== false;

        if ($latitude === '' || $longitude === '') {
            return cleg_worker_android_error('gps_missing', 'No se recibio ubicacion valida desde Android.', 422);
        }

        if (in_array('Outside Geofence', $gps_review['reasons'], true)) {
            return cleg_worker_android_error('outside_geofence', 'Parece que estas lejos de este proyecto. Revisa si escogiste el proyecto correcto.', 409, array(
                'distance' => $gps_review['distance'],
            ));
        }

        if ($previous_device_user !== '') {
            $audit_flags[] = 'Shared Device Detected';
        }

        if ($temporary_job_site) {
            $audit_flags[] = 'Manual Review';
        }

        $audit_flags = array_merge($audit_flags, isset($gps_review['audit_flags']) ? $gps_review['audit_flags'] : array());

        if ($is_project_switch) {
            if ($job_site === '') {
                return cleg_worker_android_error('missing_job_site', 'Escoge el nuevo proyecto.', 422);
            }

            $old_job_site = $open_entry['job_site'];

            if ($old_job_site !== '' && strcasecmp($old_job_site, $job_site) === 0) {
                return cleg_worker_android_error('same_job_site', 'Escoge un proyecto diferente al actual.', 422);
            }

            $exit_gps_review = function_exists('cleg_app_location_review') ? cleg_app_location_review($old_job_site, $latitude, $longitude, $accuracy, '0', '') : $gps_review;
            $old_temporary_job_site = stripos($old_job_site, 'Proyecto Temporal') !== false;
            $close_audit_flags = isset($exit_gps_review['audit_flags']) ? $exit_gps_review['audit_flags'] : array();

            if ($previous_device_user !== '') {
                $close_audit_flags[] = 'Shared Device Detected';
            }

            if ($old_temporary_job_site) {
                $close_audit_flags[] = 'Manual Review';
            }

            $close_fields = array(
                'Clock Out Time' => $event_time,
                'Clock Out Latitude' => $latitude,
                'Clock Out Longitude' => $longitude,
                'Clock Out Accuracy' => $accuracy,
                'Clock Out Map Link' => $map_link,
                'Approval Status' => 'Pending Review',
                'Portal Username' => $portal_username,
                'Device ID' => $device_id,
                'Previous Device User' => $previous_device_user,
                'IP Address' => $ip_address,
                'User Agent' => $user_agent,
                'Geofence Distance Meters' => $exit_gps_review['distance'],
                'Clock Out Geofence Distance Meters' => $exit_gps_review['distance'],
                'GPS Review Required' => $exit_gps_review['required'],
                'Temporary Job Site Used' => $old_temporary_job_site,
                'Admin Notes' => trim('Project changed by Android app.' . "\nPrevious job site: " . $old_job_site . "\nNew job site: " . $job_site . ($note !== '' ? "\nWorker note: " . $note : '')),
            );

            if (in_array('Outside Geofence', $exit_gps_review['reasons'], true)) {
                $close_fields['Clock Out Outside Geofence'] = true;
            }

            if (!empty($close_audit_flags)) {
                $close_fields['Audit Flags'] = array_values(array_unique($close_audit_flags));
            }

            if (!empty($exit_gps_review['reasons'])) {
                $close_fields['GPS Review Reason'] = array_values(array_unique($exit_gps_review['reasons']));
            }

            if (!empty($exit_gps_review['note'])) {
                $close_fields['Admin Notes'] = trim($exit_gps_review['note'] . "\n" . $close_fields['Admin Notes']);
            }

            $close_response = cleg_app_airtable_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
                'body' => array(
                    'typecast' => true,
                    'records' => array(array('id' => $open_entry['id'], 'fields' => cleg_app_remove_empty_values($close_fields))),
                ),
            ));

            if (is_wp_error($close_response)) {
                return cleg_worker_android_error('airtable_close_failed', 'No se pudo cerrar el proyecto actual. Intenta de nuevo.', 500);
            }

            $open_fields = array(
                'Entry Code' => 'ANDROID-SWITCH-' . gmdate('Ymd-His') . '-' . (int) $user->ID,
                'Employee Name' => $employee_name,
                'WordPress User ID' => (int) $user->ID,
                'Portal Username' => $portal_username,
                'Job Site Name' => $job_site,
                'Job Site Selection Type' => 'Android App',
                'Clock In Time' => $event_time,
                'Clock In Latitude' => $latitude,
                'Clock In Longitude' => $longitude,
                'Clock In Accuracy' => $accuracy,
                'Clock In Map Link' => $map_link,
                'Approval Status' => 'Open',
                'Device ID' => $device_id,
                'Previous Device User' => $previous_device_user,
                'IP Address' => $ip_address,
                'User Agent' => $user_agent,
                'Geofence Distance Meters' => $gps_review['distance'],
                'Clock In Geofence Distance Meters' => $gps_review['distance'],
                'GPS Review Required' => $gps_review['required'],
                'Temporary Job Site Used' => $temporary_job_site,
                'Admin Notes' => trim('New segment opened by Android app project change.' . "\nPrevious job site: " . $old_job_site . ($note !== '' ? "\nWorker note: " . $note : '')),
            );

            if (!empty($audit_flags)) {
                $open_fields['Audit Flags'] = array_values(array_unique($audit_flags));
            }

            if (!empty($gps_review['reasons'])) {
                $open_fields['GPS Review Reason'] = array_values(array_unique($gps_review['reasons']));
            }

            if ($employee_email !== '') {
                $open_fields['Employee Email'] = $employee_email;
            }

            if (!empty($gps_review['note'])) {
                $open_fields['Admin Notes'] = trim($gps_review['note'] . "\n" . $open_fields['Admin Notes']);
            }

            $open_response = cleg_app_airtable_request('POST', CLEG_AIRTABLE_TIME_TABLE, array(
                'body' => array(
                    'typecast' => true,
                    'records' => array(array('fields' => cleg_app_remove_empty_values($open_fields))),
                ),
            ));

            if (is_wp_error($open_response)) {
                return cleg_worker_android_error('airtable_open_failed', 'El proyecto anterior se cerro, pero no se pudo abrir el nuevo. Avisa a la oficina.', 500);
            }

            return rest_ensure_response(array(
                'isWorking' => true,
                'activeJobSite' => $job_site,
                'statusLabel' => 'Trabajando',
                'statusDetail' => 'Desde ahora',
                'message' => 'Proyecto cambiado.',
            ));
        }

        if ($is_clock_out) {
            $fields = array(
                'Clock Out Time' => $event_time,
                'Clock Out Latitude' => $latitude,
                'Clock Out Longitude' => $longitude,
                'Clock Out Accuracy' => $accuracy,
                'Clock Out Map Link' => $map_link,
                'Approval Status' => 'Pending Review',
                'Portal Username' => $portal_username,
                'Device ID' => $device_id,
                'Previous Device User' => $previous_device_user,
                'IP Address' => $ip_address,
                'User Agent' => $user_agent,
                'Geofence Distance Meters' => $gps_review['distance'],
                'Clock Out Geofence Distance Meters' => $gps_review['distance'],
                'GPS Review Required' => $gps_review['required'],
                'Temporary Job Site Used' => $temporary_job_site,
            );

            if (!empty($audit_flags)) {
                $fields['Audit Flags'] = array_values(array_unique($audit_flags));
            }

            if (!empty($gps_review['reasons'])) {
                $fields['GPS Review Reason'] = array_values(array_unique($gps_review['reasons']));
            }

            if (!empty($gps_review['note'])) {
                $fields['Admin Notes'] = trim(($fields['Admin Notes'] ?? '') . "\n" . $gps_review['note']);
            }

            if ($note !== '') {
                $fields['Admin Notes'] = trim(($fields['Admin Notes'] ?? '') . "\nWorker note: " . $note);
            }

            $response = cleg_app_airtable_request('PATCH', CLEG_AIRTABLE_TIME_TABLE, array(
                'body' => array(
                    'typecast' => true,
                    'records' => array(array('id' => $open_entry['id'], 'fields' => cleg_app_remove_empty_values($fields))),
                ),
            ));

            if (is_wp_error($response)) {
                return cleg_worker_android_error('airtable_clock_out_failed', 'No se pudo marcar salida. Intenta de nuevo.', 500);
            }

            return rest_ensure_response(array(
                'isWorking' => false,
                'activeJobSite' => null,
                'statusLabel' => 'No has empezado',
                'statusDetail' => 'Listo para entrar',
                'message' => 'Salida marcada.',
            ));
        }

        if ($job_site === '') {
            return cleg_worker_android_error('missing_job_site', 'Escoge el proyecto antes de marcar.', 422);
        }

        $fields = array(
            'Entry Code' => 'ANDROID-' . gmdate('Ymd-His') . '-' . (int) $user->ID,
            'Employee Name' => $employee_name,
            'WordPress User ID' => (int) $user->ID,
            'Portal Username' => $portal_username,
            'Job Site Name' => $job_site,
            'Job Site Selection Type' => 'Android App',
            'Clock In Time' => $event_time,
            'Clock In Latitude' => $latitude,
            'Clock In Longitude' => $longitude,
            'Clock In Accuracy' => $accuracy,
            'Clock In Map Link' => $map_link,
            'Approval Status' => 'Open',
            'Device ID' => $device_id,
            'Previous Device User' => $previous_device_user,
            'IP Address' => $ip_address,
            'User Agent' => $user_agent,
            'Geofence Distance Meters' => $gps_review['distance'],
            'Clock In Geofence Distance Meters' => $gps_review['distance'],
            'GPS Review Required' => $gps_review['required'],
            'Temporary Job Site Used' => $temporary_job_site,
        );

        if (!empty($audit_flags)) {
            $fields['Audit Flags'] = array_values(array_unique($audit_flags));
        }

        if (!empty($gps_review['reasons'])) {
            $fields['GPS Review Reason'] = array_values(array_unique($gps_review['reasons']));
        }

        if ($employee_email !== '') {
            $fields['Employee Email'] = $employee_email;
        }

        if (!empty($gps_review['note'])) {
            $fields['Admin Notes'] = trim(($fields['Admin Notes'] ?? '') . "\n" . $gps_review['note']);
        }

        if ($note !== '') {
            $fields['Admin Notes'] = trim(($fields['Admin Notes'] ?? '') . "\nWorker note: " . $note);
        }

        $response = cleg_app_airtable_request('POST', CLEG_AIRTABLE_TIME_TABLE, array(
            'body' => array(
                'typecast' => true,
                'records' => array(array('fields' => cleg_app_remove_empty_values($fields))),
            ),
        ));

        if (is_wp_error($response)) {
            return cleg_worker_android_error('airtable_clock_in_failed', 'No se pudo marcar entrada. Intenta de nuevo.', 500);
        }

        return rest_ensure_response(array(
            'isWorking' => true,
            'activeJobSite' => $job_site,
            'statusLabel' => 'Trabajando',
            'statusDetail' => 'Desde ahora',
            'message' => 'Entrada marcada.',
        ));
    }
}

