/**
 * BEGIN modulos/12-procurement-quotes/23-cleg-21-admin-recibos-v1.php
 * Module: procurement_quotes
 * Target: 01-Snippets-Activos/23-cleg-21-admin-recibos-v1.php
 * Source path: modulos/12-procurement-quotes/23-cleg-21-admin-recibos-v1.php
 */
/**
 * CLEG 21 - Admin Recibos de Compra v1.0
 *
 * Pantalla /admin-recibos/, shortcode [cleg_admin_recibos].
 * Lee recibos enviados desde Compra del trabajador en Airtable.
 */
if (!defined('ABSPATH')) {
    exit;
}

if (!defined('CLEG_AIRTABLE_RECEIPTS_TABLE')) {
    define('CLEG_AIRTABLE_RECEIPTS_TABLE', 'Purchase Receipts');
}

if (!function_exists('cleg_admin_receipts_module_enabled')) {
    function cleg_admin_receipts_module_enabled() {
        if (function_exists('cleg_saas_module_enabled')) {
            return (bool) cleg_saas_module_enabled('procurement_quotes');
        }

        return true;
    }
}

if (!function_exists('cleg_admin_receipts_filter_formula')) {
    function cleg_admin_receipts_filter_formula($date = '', $job_site = '', $employee = '', $status = '', $amount = '') {
        $parts = array();

        if ($date !== '' && preg_match('/^\d{4}-\d{2}-\d{2}$/', $date)) {
            $parts[] = "IS_SAME({Purchase Date}, '{$date}', 'day')";
        }

        if ($job_site !== '') {
            $parts[] = "{Job Site Name}='" . cleg_admin_formula_text($job_site) . "'";
        }

        if ($employee !== '') {
            $needle = cleg_admin_formula_text(strtolower($employee));
            $parts[] = "OR(FIND('{$needle}', LOWER({Employee Name}))>0, FIND('{$needle}', LOWER({Portal Username}))>0, FIND('{$needle}', LOWER({Employee Email}))>0)";
        }

        if ($status !== '') {
            $parts[] = "{Status}='" . cleg_admin_formula_text($status) . "'";
        }

        if ($amount !== '') {
            $amount = str_replace(',', '.', (string) $amount);
            $amount = preg_replace('/[^0-9\.\-]/', '', (string) $amount);
            if ($amount !== '' && is_numeric($amount)) {
                $parts[] = 'ABS({Total}-' . (float) $amount . ')<0.01';
            }
        }

        if (empty($parts)) {
            return '';
        }

        return count($parts) === 1 ? $parts[0] : 'AND(' . implode(',', $parts) . ')';
    }
}

if (!function_exists('cleg_admin_receipt_status_pill')) {
    function cleg_admin_receipt_status_pill($status) {
        $status = $status !== '' ? $status : 'Archivado';
        $class = 'is-archived';
        if ($status === 'Revisar') {
            $class = 'is-review';
        } elseif ($status === 'Resuelto') {
            $class = 'is-resolved';
        }

        return '<span class="cleg-pill cleg-receipt-pill ' . esc_attr($class) . '">' . esc_html($status) . '</span>';
    }
}

if (!function_exists('cleg_admin_receipt_records')) {
    function cleg_admin_receipt_records($filter = '') {
        if (!cleg_admin_receipts_module_enabled()) {
            return new WP_Error('cleg_receipts_module_disabled', 'Compras no esta activo para este tenant.');
        }

        $query = array(
            'pageSize' => 100,
            'sort[0][field]' => 'Purchase Date',
            'sort[0][direction]' => 'desc',
            'sort[1][field]' => 'Submitted At',
            'sort[1][direction]' => 'desc',
        );

        if ($filter !== '') {
            $query['filterByFormula'] = $filter;
        }

        return cleg_admin_records(CLEG_AIRTABLE_RECEIPTS_TABLE, $query);
    }
}

if (!function_exists('cleg_admin_receipt_record_by_id')) {
    function cleg_admin_receipt_record_by_id($record_id) {
        $records = cleg_admin_receipt_records("RECORD_ID()='" . cleg_admin_formula_text($record_id) . "'");
        if (is_wp_error($records)) {
            return $records;
        }
        return $records[0] ?? array();
    }
}

if (!function_exists('cleg_admin_handle_receipt_action')) {
    function cleg_admin_handle_receipt_action() {
        if (empty($_POST['cleg_receipt_action'])) {
            return;
        }

        if (!cleg_admin_receipts_module_enabled()) {
            return;
        }

        if (!cleg_admin_user_allowed()) {
            return;
        }

        if (!isset($_POST['cleg_receipt_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cleg_receipt_nonce'])), 'cleg_admin_receipt_action')) {
            return;
        }

        $action = sanitize_text_field(wp_unslash($_POST['cleg_receipt_action']));
        $record_id = isset($_POST['cleg_receipt_record_id']) ? sanitize_text_field(wp_unslash($_POST['cleg_receipt_record_id'])) : '';
        $allowed = array(
            'archive' => 'Archivado',
            'review' => 'Revisar',
            'resolved' => 'Resuelto',
        );

        if ($record_id === '' || !isset($allowed[$action])) {
            return;
        }

        $record = cleg_admin_receipt_record_by_id($record_id);
        if (is_wp_error($record) || empty($record)) {
            wp_safe_redirect(add_query_arg('receipt_error', rawurlencode('No se encontro el recibo seleccionado.'), remove_query_arg(array('_wp_http_referer'))));
            exit;
        }

        $user = wp_get_current_user();
        $actor_name = sanitize_text_field($user->display_name ?: $user->user_login);
        $new_status = $allowed[$action];
        $note = isset($_POST['cleg_receipt_note']) ? sanitize_textarea_field(wp_unslash($_POST['cleg_receipt_note'])) : '';
        $current_note = cleg_admin_field($record, 'Review Note');
        $audit = cleg_admin_audit_line($actor_name, 'Status', cleg_admin_field($record, 'Status'), $new_status, $note);

        $fields = array(
            'Status' => $new_status,
            'Reviewed By' => $actor_name,
            'Reviewed At' => gmdate('c'),
            'Review Note' => trim($current_note . "\n" . $audit),
        );

        $result = cleg_admin_request('PATCH', CLEG_AIRTABLE_RECEIPTS_TABLE, array(
            'body' => array(
                'typecast' => true,
                'records' => array(array('id' => $record_id, 'fields' => $fields)),
            ),
        ));

        if (is_wp_error($result)) {
            wp_safe_redirect(add_query_arg('receipt_error', rawurlencode($result->get_error_message()), remove_query_arg(array('_wp_http_referer'))));
            exit;
        }

        wp_safe_redirect(add_query_arg(array('receipt_saved' => '1', 'cleg_refresh' => time()), remove_query_arg(array('_wp_http_referer'))));
        exit;
    }
}

if (!function_exists('cleg_admin_receipt_attachment')) {
    function cleg_admin_receipt_attachment($record) {
        $fields = $record['fields'] ?? array();
        $url = '';
        $name = '';
        $type = '';

        if (!empty($fields['Receipt Photo']) && is_array($fields['Receipt Photo'])) {
            $first = reset($fields['Receipt Photo']);
            if (is_array($first)) {
                $url = isset($first['url']) ? esc_url_raw($first['url']) : '';
                $name = isset($first['filename']) ? sanitize_text_field($first['filename']) : '';
                $type = isset($first['type']) ? sanitize_text_field($first['type']) : '';
            }
        }

        if ($url === '') {
            $url = esc_url_raw(cleg_admin_field($record, 'Receipt File URL'));
        }

        if ($name === '') {
            $name = cleg_admin_field($record, 'Receipt Code', 'Recibo');
        }

        return array('url' => $url, 'name' => $name, 'type' => $type);
    }
}

if (!function_exists('cleg_admin_receipt_preview')) {
    function cleg_admin_receipt_preview($record) {
        $file = cleg_admin_receipt_attachment($record);

        if ($file['url'] === '') {
            return '<span class="cleg-receipt-empty">Sin imagen</span>';
        }

        $is_pdf = stripos($file['type'], 'pdf') !== false || preg_match('/\.pdf(\?|$)/i', $file['url']);
        if ($is_pdf) {
            return '<a class="cleg-receipt-pdf" href="' . esc_url($file['url']) . '" target="_blank" rel="noopener">Abrir PDF</a>';
        }

        return '<details class="cleg-receipt-preview"><summary><img src="' . esc_url($file['url']) . '" alt="' . esc_attr($file['name']) . '"><span>Ampliar</span></summary><div class="cleg-receipt-lightbox"><div class="cleg-receipt-toolbar"><button type="button" data-receipt-zoom-out>-</button><span data-receipt-zoom-label>100%</span><button type="button" data-receipt-zoom-in>+</button><button type="button" data-receipt-close>Cerrar</button></div><div class="cleg-receipt-stage"><img src="' . esc_url($file['url']) . '" alt="' . esc_attr($file['name']) . '" style="--receipt-zoom:1"></div></div></details>';
    }
}

if (!function_exists('cleg_admin_receipts_filters')) {
    function cleg_admin_receipts_filters($date, $job_site, $employee, $status, $amount, $job_sites = array()) {
        $statuses = array('', 'Archivado', 'Revisar', 'Resuelto');
        $html = '<form class="cleg-review-filters cleg-receipt-filters" method="get"><label><span>Dia</span><input type="date" name="receipt_date" value="' . esc_attr($date) . '"></label>';

        $html .= '<label><span>Proyecto</span><select name="receipt_job"><option value="">Todos</option>';
        foreach ((array) $job_sites as $site) {
            $name = cleg_admin_field($site, 'Job Site Name');
            if ($name === '') {
                continue;
            }
            $html .= '<option value="' . esc_attr($name) . '" ' . selected($job_site, $name, false) . '>' . esc_html($name) . '</option>';
        }
        $html .= '</select></label>';

        $html .= '<label><span>Persona</span><input type="search" name="receipt_employee" value="' . esc_attr($employee) . '" placeholder="Nombre, usuario o email"></label>';
        $html .= '<label><span>Monto exacto</span><input type="number" step="0.01" min="0" name="receipt_amount" value="' . esc_attr($amount) . '" placeholder="0.00"></label>';
        $html .= '<label><span>Estado</span><select name="receipt_status">';
        foreach ($statuses as $item) {
            $label = $item !== '' ? $item : 'Todos';
            $html .= '<option value="' . esc_attr($item) . '" ' . selected($status, $item, false) . '>' . esc_html($label) . '</option>';
        }
        $html .= '</select></label><button type="submit">Filtrar</button><a class="cleg-clear-filter" href="' . esc_url(home_url('/admin-recibos/')) . '">Limpiar filtro</a></form>';

        return $html;
    }
}

if (!function_exists('cleg_admin_receipt_action_form')) {
    function cleg_admin_receipt_action_form($record) {
        $record_id = $record['id'] ?? '';
        if ($record_id === '') {
            return '';
        }

        $status = cleg_admin_field($record, 'Status', 'Archivado');
        $buttons = array(
            'archive' => 'Archivar',
            'review' => 'Revisar',
            'resolved' => 'Resuelto',
        );

        $html = '<form class="cleg-receipt-actions" method="post">';
        $html .= wp_nonce_field('cleg_admin_receipt_action', 'cleg_receipt_nonce', true, false);
        $html .= '<input type="hidden" name="cleg_receipt_record_id" value="' . esc_attr($record_id) . '">';
        foreach ($buttons as $action => $label) {
            $target = $action === 'archive' ? 'Archivado' : ($action === 'review' ? 'Revisar' : 'Resuelto');
            $html .= '<button type="submit" name="cleg_receipt_action" value="' . esc_attr($action) . '" ' . disabled($status, $target, false) . '>' . esc_html($label) . '</button>';
        }
        $html .= '</form>';

        return $html;
    }
}

if (!function_exists('cleg_admin_receipts_table')) {
    function cleg_admin_receipts_table($records) {
        $total = 0;
        $review_count = 0;
        $resolved_count = 0;
        foreach ((array) $records as $record) {
            $value = cleg_admin_field($record, 'Total', 0);
            if (is_numeric($value)) {
                $total += (float) $value;
            }
            $record_status = cleg_admin_field($record, 'Status', 'Archivado');
            if ($record_status === 'Revisar') {
                $review_count++;
            } elseif ($record_status === 'Resuelto') {
                $resolved_count++;
            }
        }

        $html = '';
        if (!empty($_GET['receipt_saved'])) {
            $html .= '<div class="cleg-receipt-notice is-ok">Recibo actualizado.</div>';
        }
        if (!empty($_GET['receipt_error'])) {
            $html .= '<div class="cleg-receipt-notice is-bad">' . esc_html(sanitize_text_field(wp_unslash($_GET['receipt_error']))) . '</div>';
        }

        $active_status = isset($_GET['receipt_status']) ? sanitize_text_field(wp_unslash($_GET['receipt_status'])) : '';
        $html .= '<nav class="cleg-proc-metrics cleg-receipt-kpis" aria-label="Resumen de recibos">'
            . '<a class="' . esc_attr($active_status === '' ? 'is-active' : '') . '" href="' . esc_url(home_url('/admin-recibos/')) . '"><span>Recibos visibles</span><strong>' . esc_html(count($records)) . '</strong></a>'
            . '<a href="' . esc_url(home_url('/admin-recibos/')) . '"><span>Total visible</span><strong>$' . esc_html(number_format($total, 2)) . '</strong></a>'
            . '<a class="' . esc_attr($active_status === 'Revisar' ? 'is-active' : '') . '" href="' . esc_url(add_query_arg('receipt_status', 'Revisar', home_url('/admin-recibos/'))) . '"><span>Por revisar</span><strong>' . esc_html($review_count) . '</strong></a>'
            . '<a class="' . esc_attr($active_status === 'Resuelto' ? 'is-active' : '') . '" href="' . esc_url(add_query_arg('receipt_status', 'Resuelto', home_url('/admin-recibos/'))) . '"><span>Resueltos</span><strong>' . esc_html($resolved_count) . '</strong></a>'
            . '</nav>';
        $html .= '<div class="cleg-panel cleg-receipt-panel"><div class="cleg-panel-head"><div><h2>Recibos de compra</h2><p>Organizados por dia, proyecto, persona y monto desde Airtable.</p></div></div><div class="cleg-table-wrap cleg-desktop-table"><table><thead><tr><th>Recibo</th><th>Fecha</th><th>Persona</th><th>Proyecto</th><th>Compra</th><th>Total</th><th>Estado</th><th>Acciones</th><th>Archivo</th></tr></thead><tbody>';

        if (empty($records)) {
            $html .= '<tr><td colspan="9">No hay recibos con esos filtros.</td></tr>';
        }

        foreach ((array) $records as $record) {
            $code = cleg_admin_field($record, 'Receipt Code', $record['id'] ?? '');
            $employee = cleg_admin_field($record, 'Employee Name', cleg_admin_field($record, 'Portal Username', 'Sin persona'));
            $username = cleg_admin_field($record, 'Portal Username');
            $date = cleg_admin_field($record, 'Purchase Date');
            $project = cleg_admin_field($record, 'Job Site Name', 'Sin proyecto');
            $category = cleg_admin_field($record, 'Purchase Category', 'Compra');
            $description = cleg_admin_field($record, 'Description');
            $amount = cleg_admin_field($record, 'Total', '0');
            $status = cleg_admin_field($record, 'Status', 'Archivado');

            $html .= '<tr><td><strong>' . esc_html($code) . '</strong><small>' . esc_html(cleg_admin_date(cleg_admin_field($record, 'Submitted At'))) . '</small></td>'
                . '<td>' . esc_html($date !== '' ? cleg_admin_date($date) : 'Pendiente') . '</td>'
                . '<td><strong>' . esc_html($employee) . '</strong><small>' . esc_html($username) . '</small></td>'
                . '<td>' . esc_html($project) . '</td>'
                . '<td><strong>' . esc_html($category) . '</strong><small>' . esc_html($description) . '</small></td>'
                . '<td><strong>$' . esc_html(number_format((float) $amount, 2)) . '</strong><small>' . esc_html(cleg_admin_field($record, 'Company Card')) . '</small></td>'
                . '<td>' . cleg_admin_receipt_status_pill($status) . '</td>'
                . '<td>' . cleg_admin_receipt_action_form($record) . '</td>'
                . '<td>' . cleg_admin_receipt_preview($record) . '</td></tr>';
        }

        return $html . '</tbody></table></div></div>' . cleg_admin_receipts_styles();
    }
}

if (!function_exists('cleg_admin_receipts_review_count')) {
    function cleg_admin_receipts_review_count($records) {
        $count = 0;
        foreach ((array) $records as $record) {
            if (cleg_admin_field($record, 'Status', 'Archivado') === 'Revisar') {
                $count++;
            }
        }
        return $count;
    }
}

if (!function_exists('cleg_admin_receipts_procurement_shell_open')) {
    function cleg_admin_receipts_procurement_shell_open($review_count = 0) {
        if (function_exists('cleg_procurement_guard')) {
            cleg_procurement_guard();
        } elseif (!function_exists('cleg_admin_user_allowed') || !cleg_admin_user_allowed()) {
            return '<section class="cleg-procurement cleg-proc-receipts-screen"><div class="cleg-proc-empty"><h2>Acceso restringido</h2><p>Inicia sesion con un usuario autorizado.</p></div></section>';
        }

        $base_url = home_url('/admin-procurement/');
        $logout_url = wp_logout_url(home_url('/acceso/'));
