/**
 * BEGIN modulos/90-sync-qa/25-cleg-sync-status-wpwriter-mirror.php
 * Module: sync_qa
 * Target: 01-Snippets-Activos/25-cleg-sync-status-wpwriter-mirror.php
 * Source path: modulos/90-sync-qa/25-cleg-sync-status-wpwriter-mirror.php
 */
/**
 * CLEG Sync Status - WPWriter Mirror
 *
 * Keeps a readable QA snapshot inside the private panel page that WPWriter can
 * already read. This avoids depending only on the historical status page when
 * its REST permissions return 403.
 */

if (!defined('ABSPATH')) {
    exit;
}

if (!function_exists('cleg_sync_mirror_status_file')) {
    function cleg_sync_mirror_status_file() {
        $uploads = wp_upload_dir();
        if (empty($uploads['basedir'])) {
            return '';
        }

        return trailingslashit($uploads['basedir']) . 'cleg-snippet-sync/status/cleg-sync-status.json';
    }
}

if (!function_exists('cleg_sync_mirror_redact')) {
    function cleg_sync_mirror_redact($value) {
        if (is_array($value)) {
            $clean = array();
            foreach ($value as $key => $item) {
                $normalized_key = strtolower((string) $key);
                if (preg_match('/token|secret|password|bearer|authorization|api[_-]?key|pat/i', $normalized_key)) {
                    $clean[$key] = '[redacted]';
                    continue;
                }
                $clean[$key] = cleg_sync_mirror_redact($item);
            }
            return $clean;
        }

        if (is_string($value)) {
            $value = preg_replace('/Bearer\s+[A-Za-z0-9._\-]+/i', 'Bearer [redacted]', $value);
            $value = preg_replace('/(key|token|secret|password|pat)=([^&\s]+)/i', '$1=[redacted]', $value);
        }

        return $value;
    }
}

if (!function_exists('cleg_sync_mirror_find_value')) {
    function cleg_sync_mirror_find_value($data, array $keys, $default = '') {
        if (!is_array($data)) {
            return $default;
        }

        foreach ($keys as $key) {
            if (array_key_exists($key, $data) && is_scalar($data[$key])) {
                return is_bool($data[$key]) ? $data[$key] : (string) $data[$key];
            }
        }

        foreach ($data as $value) {
            if (is_array($value)) {
                $found = cleg_sync_mirror_find_value($value, $keys, null);
                if ($found !== null && $found !== '') {
                    return $found;
                }
            }
        }

        return $default;
    }
}

if (!function_exists('cleg_sync_mirror_bool_label')) {
    function cleg_sync_mirror_bool_label($value) {
        if (is_bool($value)) {
            return $value ? 'yes' : 'no';
        }

        $text = strtolower(trim((string) $value));
        if (in_array($text, array('1', 'yes', 'true', 'enabled', 'passed'), true)) {
            return 'yes';
        }
        if (in_array($text, array('0', 'no', 'false', 'disabled', 'failed'), true)) {
            return 'no';
        }

        return $text !== '' ? sanitize_text_field((string) $value) : 'unknown';
    }
}

if (!function_exists('cleg_sync_mirror_read_status')) {
    function cleg_sync_mirror_read_status() {
        $file = cleg_sync_mirror_status_file();
        $status = array(
            'mirror_version' => '1.0.0',
            'mirror_updated_at' => current_time('mysql'),
            'status_file' => $file,
            'status_file_exists' => $file && file_exists($file),
            'status_file_readable' => $file && is_readable($file),
            'status_file_mtime' => '',
            'raw' => array(),
        );

        if (!$status['status_file_exists'] || !$status['status_file_readable']) {
            $status['message'] = 'status_file_unavailable';
            $status['summary'] = 'No se pudo leer el JSON local del loader.';
            return $status;
        }

        $status['status_file_mtime'] = gmdate('c', (int) filemtime($file));
        $json = file_get_contents($file);
        $decoded = json_decode((string) $json, true);

        if (!is_array($decoded)) {
            $status['message'] = 'status_file_invalid_json';
            $status['summary'] = 'El JSON local del loader no es valido.';
            return $status;
        }

        $decoded = cleg_sync_mirror_redact($decoded);
        $status['raw'] = $decoded;
        $status['message'] = cleg_sync_mirror_find_value($decoded, array('message', 'status', 'last_message'), 'unknown');
        $status['summary'] = cleg_sync_mirror_find_value($decoded, array('summary', 'last_summary', 'result_summary'), '');
        $status['active_file_hash'] = cleg_sync_mirror_find_value($decoded, array('active_file_hash', 'active_hash', 'bundle_hash'), '');
        $status['last_good_hash'] = cleg_sync_mirror_find_value($decoded, array('last_good_hash', 'last_known_good_hash'), '');
        $status['candidate_hash'] = cleg_sync_mirror_find_value($decoded, array('candidate_hash'), '');
        $status['functional_qa_passed'] = cleg_sync_mirror_bool_label(cleg_sync_mirror_find_value($decoded, array('functional_qa_passed', 'qa_passed'), 'unknown'));
        $status['bundle_will_load'] = cleg_sync_mirror_bool_label(cleg_sync_mirror_find_value($decoded, array('bundle_will_load', 'will_load'), 'unknown'));
        $status['execution_enabled'] = cleg_sync_mirror_bool_label(cleg_sync_mirror_find_value($decoded, array('execution_enabled', 'bundle_execution_enabled'), 'unknown'));
        $status['code_snippets_active'] = cleg_sync_mirror_bool_label(cleg_sync_mirror_find_value($decoded, array('code_snippets_active'), 'unknown'));

        return $status;
    }
}

if (!function_exists('cleg_sync_mirror_render_block')) {
    function cleg_sync_mirror_render_block($status) {
        $message = sanitize_text_field((string) ($status['message'] ?? 'unknown'));
        $summary = sanitize_text_field((string) ($status['summary'] ?? ''));
        $raw_json = wp_json_encode(cleg_sync_mirror_redact($status['raw'] ?? array()), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);

        ob_start();
        ?>
<!-- CLEG_SYNC_QA_MIRROR_START -->
<section class="cleg-sync-qa-mirror" style="margin-top:22px;border:1px solid #d9e1e8;background:#fff;border-radius:8px;padding:18px;color:#17202a;">
  <h2 style="margin:0 0 10px;font-size:20px;">QA Sync Mirror</h2>
  <p style="margin:0 0 12px;color:#607080;">Snapshot privado para lectura de WPWriter. Fuente: JSON local del CLEG Snippet Sync Loader.</p>
  <ul style="margin:0 0 12px 18px;padding:0;line-height:1.55;">
    <li><strong>Mirror updated:</strong> <?php echo esc_html((string) ($status['mirror_updated_at'] ?? '')); ?></li>
    <li><strong>Message:</strong> <?php echo esc_html($message); ?></li>
    <li><strong>Summary:</strong> <?php echo esc_html($summary); ?></li>
    <li><strong>Functional QA passed:</strong> <?php echo esc_html((string) ($status['functional_qa_passed'] ?? 'unknown')); ?></li>
    <li><strong>Bundle will load:</strong> <?php echo esc_html((string) ($status['bundle_will_load'] ?? 'unknown')); ?></li>
    <li><strong>Execution enabled:</strong> <?php echo esc_html((string) ($status['execution_enabled'] ?? 'unknown')); ?></li>
    <li><strong>Code Snippets active:</strong> <?php echo esc_html((string) ($status['code_snippets_active'] ?? 'unknown')); ?></li>
    <li><strong>Active file hash:</strong> <code><?php echo esc_html((string) ($status['active_file_hash'] ?? '')); ?></code></li>
    <li><strong>Last good hash:</strong> <code><?php echo esc_html((string) ($status['last_good_hash'] ?? '')); ?></code></li>
    <li><strong>Status file readable:</strong> <?php echo !empty($status['status_file_readable']) ? 'yes' : 'no'; ?></li>
    <li><strong>Status file mtime:</strong> <?php echo esc_html((string) ($status['status_file_mtime'] ?? '')); ?></li>
  </ul>
  <details>
    <summary style="cursor:pointer;font-weight:700;">Raw loader status</summary>
    <pre style="white-space:pre-wrap;overflow:auto;background:#101820;color:#eef6ff;border-radius:8px;padding:12px;font-size:12px;line-height:1.45;"><?php echo esc_html((string) $raw_json); ?></pre>
  </details>
</section>
<!-- CLEG_SYNC_QA_MIRROR_END -->
        <?php
        return trim(ob_get_clean());
    }
}

if (!function_exists('cleg_sync_mirror_target_page')) {
    function cleg_sync_mirror_target_page() {
        $post = get_post(9612);
        if ($post && $post->post_type === 'page') {
            return $post;
        }

        $post = get_page_by_path('panel-sync', OBJECT, 'page');
        if ($post && !empty($post->ID)) {
            return $post;
        }

        return null;
    }
}

if (!function_exists('cleg_sync_mirror_update_panel_page')) {
    function cleg_sync_mirror_update_panel_page() {
        if (defined('WP_INSTALLING') && WP_INSTALLING) {
            return false;
        }

        $post = cleg_sync_mirror_target_page();
        if (!$post || empty($post->ID)) {
            return false;
        }

        $status = cleg_sync_mirror_read_status();
        $block = cleg_sync_mirror_render_block($status);
        $content = (string) $post->post_content;
        $pattern = '/<!-- CLEG_SYNC_QA_MIRROR_START -->.*?<!-- CLEG_SYNC_QA_MIRROR_END -->/s';

        if (preg_match($pattern, $content)) {
            $new_content = preg_replace($pattern, $block, $content);
        } else {
            $new_content = rtrim($content) . "\n\n" . $block . "\n";
        }

        if ($new_content === $content) {
            return false;
        }

        $result = wp_update_post(wp_slash(array(
            'ID' => (int) $post->ID,
            'post_content' => $new_content,
        )), true);

        if (is_wp_error($result)) {
            return false;
        }

        update_option('cleg_sync_qa_mirror_last_update', array(
            'updated_at' => current_time('mysql'),
            'target_post_id' => (int) $post->ID,
            'message' => sanitize_text_field((string) ($status['message'] ?? 'unknown')),
            'active_file_hash' => sanitize_text_field((string) ($status['active_file_hash'] ?? '')),
        ), false);

        return true;
    }
}

add_action('init', 'cleg_sync_mirror_update_panel_page', 45);
